import React, { useState, useEffect } from 'react';
import { User } from '../types';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { MagnifyingGlassIcon, ShoppingCartIcon, BellIcon, XMarkIcon, ArrowLeftIcon } from '@heroicons/react/24/outline';

interface HeaderProps {
  currentUser: User | null;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  unreadNotificationsCount: number;
  cartItemCount: number;
  onOpenCart: () => void;
}

const Header: React.FC<HeaderProps> = ({ currentUser, onNavigate, unreadNotificationsCount, cartItemCount, onOpenCart }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isMobileSearchOpen, setIsMobileSearchOpen] = useState(false);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      onNavigate('search-results', { query: searchQuery.trim() });
      setSearchQuery(''); 
      setIsMobileSearchOpen(false);
    }
  };

  useEffect(() => {
    if (isMobileSearchOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
  }, [isMobileSearchOpen]);

  return (
    <>
      <header className="bg-white/90 dark:bg-darkbg/90 backdrop-blur-md shadow-sm px-3 md:px-6 py-2 md:py-4 flex justify-between items-center fixed top-0 left-0 w-full z-50 border-b border-gray-100 dark:border-white/5 h-[64px] md:h-[72px]">
        <div className="flex items-center gap-1 md:gap-2">
          <h1 
            className="text-lg md:text-2xl font-black text-blue-600 cursor-pointer tracking-tighter flex-shrink-0 mr-1 md:mr-6" 
            onClick={() => onNavigate('feed')}
          >
            Edu<span className="text-gray-900 dark:text-white">Social</span>
          </h1>
        </div>

        {currentUser && (
          <>
            <form onSubmit={handleSearchSubmit} className="hidden md:flex flex-1 max-w-md mx-4 relative group">
              <div className="relative w-full text-gray-400 focus-within:text-blue-600 transition-colors">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <MagnifyingGlassIcon className="h-4 w-4" />
                </div>
                <input
                  type="text"
                  className="block w-full pl-9 pr-4 py-2 border border-gray-100 dark:border-white/10 rounded-xl bg-gray-50 dark:bg-white/5 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm transition-all shadow-inner dark:text-white"
                  placeholder="Buscar professores, aulas, materiais..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
            </form>

            <button 
              onClick={() => setIsMobileSearchOpen(true)}
              className="md:hidden p-2 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 rounded-xl transition-colors ml-auto mr-1"
            >
              <MagnifyingGlassIcon className="h-5 w-5" />
            </button>
          </>
        )}

        {currentUser ? (
          <div className="flex items-center gap-1 md:gap-4 flex-shrink-0">
            <button
              onClick={onOpenCart}
              className="p-1.5 md:p-2 rounded-xl text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 relative transition-colors"
            >
              <ShoppingCartIcon className="h-5 w-5 md:h-6 md:w-6" />
              {cartItemCount > 0 && (
                <span className="absolute top-0 right-0 bg-blue-600 text-white text-[7px] md:text-[8px] font-black rounded-full h-3 md:h-3.5 w-3 md:w-3.5 flex items-center justify-center">
                  {cartItemCount}
                </span>
              )}
            </button>

            <button
              onClick={() => onNavigate('notifications')}
              className="p-1.5 md:p-2 rounded-xl text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 relative transition-colors"
            >
              <BellIcon className="h-5 w-5 md:h-6 md:w-6" />
              {unreadNotificationsCount > 0 && (
                <span className="absolute top-0 right-0 bg-red-600 text-white text-[7px] md:text-[8px] font-black rounded-full h-3 md:h-3.5 w-3 md:w-3.5 flex items-center justify-center animate-pulse">
                  {unreadNotificationsCount > 9 ? '9+' : unreadNotificationsCount}
                </span>
              )}
            </button>

            <img
              src={currentUser.profilePicture || DEFAULT_PROFILE_PIC}
              alt="Profile"
              className="w-7 h-7 md:w-10 md:h-10 rounded-lg md:rounded-xl object-cover cursor-pointer border-2 border-transparent hover:border-blue-600 transition-all shadow-sm"
              onClick={() => onNavigate('profile')}
            />
          </div>
        ) : (
          <button
            onClick={() => onNavigate('auth')}
            className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 md:px-4 md:py-2 rounded-xl text-[10px] md:text-xs font-black uppercase tracking-widest transition-all"
          >
            Entrar
          </button>
        )}
      </header>

      {isMobileSearchOpen && (
        <div className="fixed inset-0 z-[100] bg-white dark:bg-darkbg animate-fade-in md:hidden">
          <div className="flex items-center p-4 border-b border-gray-100 dark:border-white/5">
            <button 
              onClick={() => setIsMobileSearchOpen(false)}
              className="p-2 text-gray-500 dark:text-gray-400 mr-2"
            >
              <ArrowLeftIcon className="h-6 w-6" />
            </button>
            <form onSubmit={handleSearchSubmit} className="flex-1">
              <input
                autoFocus
                type="text"
                placeholder="O que você quer aprender?"
                className="w-full bg-transparent text-lg font-bold outline-none dark:text-white"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </form>
          </div>

          <div className="p-6">
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-4">Matérias em destaque</p>
            <div className="flex flex-wrap gap-2">
              {['Matemática', 'História', 'Redação', 'Física', 'Biologia', 'Inglês'].map(tag => (
                <button 
                  key={tag}
                  onClick={() => {
                    setSearchQuery(tag);
                    onNavigate('search-results', { query: tag });
                    setIsMobileSearchOpen(false);
                  }}
                  className="px-4 py-2 bg-gray-50 dark:bg-white/5 rounded-xl text-[10px] font-bold text-gray-600 dark:text-gray-300 border border-gray-100 dark:border-white/5"
                >
                  {tag}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Header;

import React, { useState, useEffect, useRef } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { addPost, updatePost, getPosts } from '../services/storageService';
import { 
  SparklesIcon, 
  VideoCameraIcon, 
  PhotoIcon, 
  XMarkIcon,
  DocumentTextIcon,
  LockClosedIcon,
  FilmIcon,
  ArrowUpTrayIcon,
  TrashIcon,
  ChevronRightIcon,
  AcademicCapIcon
} from '@heroicons/react/24/solid';

interface CreatePostProps {
  currentUser: User;
  onPostCreated: () => void;
  refreshUser: () => void;
  postId?: string;
}

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [liveTitle, setLiveTitle] = useState('');
  const [liveDescription, setLiveDescription] = useState('');
  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('0');

  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isEditing = !!postId;
  const isProfessor = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    if (postId) {
      const posts = getPosts();
      const postToEdit = posts.find(p => p.id === postId);
      if (postToEdit) {
        setPostType(postToEdit.type);
        setContent(postToEdit.content || '');
        setImageUrl(postToEdit.imageUrl || '');
        if (postToEdit.type === PostType.LIVE && postToEdit.liveStream) {
          setLiveTitle(postToEdit.liveStream.title);
          setLiveDescription(postToEdit.liveStream.description);
          setIsLivePaid(postToEdit.liveStream.isPaid);
          setLivePrice(postToEdit.liveStream.price?.toString() || '0');
        }
      }
    }
  }, [postId]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImageUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const postData: Post = {
        id: isEditing ? postId! : `post-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: postType,
        timestamp: Date.now(),
        content: postType !== PostType.LIVE ? content : undefined,
        imageUrl: postType === PostType.IMAGE ? imageUrl : undefined,
        liveStream: postType === PostType.LIVE ? {
          title: liveTitle,
          description: liveDescription,
          isPaid: isLivePaid,
          price: isLivePaid ? parseFloat(livePrice) : 0
        } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };

      if (isEditing) updatePost(postData);
      else addPost(postData);

      onPostCreated();
      if (!isEditing) {
        setIsExpanded(false);
        setContent('');
        setImageUrl('');
        setLiveTitle('');
        setLiveDescription('');
      }
    } catch (err) {
      alert('Erro ao salvar publicação.');
    } finally {
      setLoading(false);
    }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2rem] shadow-sm p-4 border border-gray-100 dark:border-white/10 flex flex-col gap-3">
         <div className="flex items-start gap-3">
            <img src={currentUser.profilePicture} className="w-10 h-10 rounded-xl object-cover shrink-0" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-4 py-2.5 bg-slate-50 dark:bg-white/5 rounded-xl text-gray-400 font-bold text-xs md:text-sm">
              {isProfessor ? `Olá Professor, o que vamos ensinar hoje?` : `Dúvidas ou algo novo para compartilhar, ${currentUser.firstName}?`}
            </button>
         </div>
         <div className="flex items-center gap-6 px-1 border-t border-gray-50 dark:border-white/5 pt-2">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-2 text-gray-500 hover:text-blue-600 transition-all">
               <PhotoIcon className="h-5 w-5 text-blue-500" />
               <span className="text-[10px] font-black uppercase tracking-widest">Imagem/Material</span>
            </button>
            {isProfessor && (
              <button onClick={() => { setIsExpanded(true); setPostType(PostType.LIVE); }} className="flex items-center gap-2 text-gray-500 hover:text-red-600 transition-all">
                 <VideoCameraIcon className="h-5 w-5 text-red-500" />
                 <span className="text-[10px] font-black uppercase tracking-widest">Aula ao Vivo</span>
              </button>
            )}
         </div>
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-2xl p-6 md:p-8 border border-blue-50 dark:border-white/5 animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 left-0 w-2 h-full bg-blue-600"></div>

      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
           <div className={`p-3 text-white rounded-2xl shadow-lg ${postType === PostType.LIVE ? 'bg-red-600' : 'bg-blue-600'}`}>
             {postType === PostType.LIVE ? <VideoCameraIcon className="h-6 w-6" /> : <AcademicCapIcon className="h-6 w-6" />}
           </div>
           <div>
              <h3 className="font-black text-gray-900 dark:text-white uppercase text-[10px] tracking-[0.2em]">{isEditing ? 'Editar Publicação' : 'Novo Conteúdo Educacional'}</h3>
              <p className="text-[8px] text-blue-500 font-black uppercase mt-0.5 tracking-widest">Espalhando conhecimento</p>
           </div>
        </div>
        <button onClick={() => setIsExpanded(false)} className="p-2 text-gray-300 hover:text-red-500 transition-colors"><XMarkIcon className="h-6 w-6" /></button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex flex-wrap gap-2 p-1.5 bg-slate-50 dark:bg-white/5 rounded-2xl w-fit">
           {[
             { id: PostType.TEXT, icon: DocumentTextIcon, label: 'Texto', locked: false },
             { id: PostType.IMAGE, icon: PhotoIcon, label: 'Imagem/Material', locked: false },
             { id: PostType.LIVE, icon: VideoCameraIcon, label: 'Aula ao Vivo', locked: !isProfessor }
           ].map(t => (
             <button key={t.id} type="button" disabled={t.locked} onClick={() => setPostType(t.id)} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${postType === t.id ? 'bg-white dark:bg-white/10 text-blue-600 dark:text-white shadow-sm' : 'text-gray-400'} ${t.locked ? 'opacity-30' : ''}`}>
                {t.locked ? <LockClosedIcon className="h-3 w-3" /> : <t.icon className="h-4 w-4" />} {t.label}
             </button>
           ))}
        </div>

        {postType === PostType.LIVE ? (
          <div className="space-y-4 animate-fade-in">
            <input
              type="text"
              value={liveTitle}
              onChange={(e) => setLiveTitle(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-bold text-lg dark:text-white"
              placeholder="Título da Aula..."
              required
            />
            <textarea
              value={liveDescription}
              onChange={(e) => setLiveDescription(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-medium text-base dark:text-white h-32 resize-none"
              placeholder="Descrição do que será ensinado nesta aula..."
            />
            <div className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-white/5 rounded-2xl">
               <label className="flex items-center gap-2 cursor-pointer">
                  <input type="checkbox" checked={isLivePaid} onChange={e => setIsLivePaid(e.target.checked)} className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                  <span className="text-xs font-black uppercase text-gray-700 dark:text-gray-300">Aula Paga</span>
               </label>
               {isLivePaid && (
                  <input 
                    type="number" 
                    value={livePrice} 
                    onChange={e => setLivePrice(e.target.value)}
                    className="flex-1 p-2 bg-white dark:bg-darkcard border rounded-lg outline-none font-bold text-blue-600"
                    placeholder="Preço (USD)"
                  />
               )}
            </div>
          </div>
        ) : (
          <>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-medium text-lg dark:text-white h-40 resize-none"
              placeholder={postType === PostType.IMAGE ? "Descreva o material ou a foto..." : "Compartilhe uma dica, aviso ou conteúdo..."}
              required
            />

            {postType === PostType.IMAGE && (
              <div className="space-y-4 animate-fade-in">
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
                {!imageUrl ? (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full h-64 border-2 border-dashed border-gray-200 dark:border-white/10 rounded-3xl flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-blue-500 transition-all group">
                      <ArrowUpTrayIcon className="h-8 w-8 text-gray-400 group-hover:text-blue-600" />
                      <span className="text-[10px] font-black text-gray-400 uppercase">Escolher Arquivo/Imagem</span>
                  </div>
                ) : (
                  <div className="relative rounded-3xl overflow-hidden border-2 border-blue-500 group">
                      <img src={imageUrl} className="w-full h-auto max-h-[400px] object-cover" alt="Preview" />
                      <button onClick={() => setImageUrl('')} className="absolute top-4 right-4 p-2 bg-red-600 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity"><TrashIcon className="h-5 w-5"/></button>
                  </div>
                )}
              </div>
            )}
          </>
        )}

        <div className="flex justify-end gap-3 pt-6 border-t dark:border-white/5">
           <button 
              type="submit" 
              disabled={loading || (!content && !liveTitle)} 
              className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-xs uppercase shadow-xl hover:bg-blue-700 active:scale-95 transition-all flex items-center gap-2"
           >
              {loading ? 'Publicando...' : isEditing ? 'Salvar' : 'Publicar'} <ChevronRightIcon className="h-4 w-4" />
           </button>
        </div>
      </form>
    </div>
  );
};

export default CreatePost;

