           <QrCodeIcon className="h-44 w-44 text-gray-900" />
           <div className="absolute inset-0 bg-white/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity rounded-[2.5rem]">
              <span className="bg-black text-white text-[9px] font-black px-3 py-1 rounded-full">QR CODE DINÂMICO</span>
           </div>
        </div>

        <div className="space-y-4">
           <div className="bg-gray-50 dark:bg-white/5 p-5 rounded-2xl text-left border border-gray-100 dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Endereço de Pagamento ({selectedCoin.id})</p>
              <div className="flex items-center justify-between gap-3">
                 <code className="text-[11px] font-bold text-blue-600 break-all leading-tight">TNV7vXhY1vXhY1vXhY1vXhY1vXhY1vXhY...</code>
                 <button onClick={() => alert('Endereço copiado!')} className="p-2.5 bg-blue-100 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white transition-all shrink-0">
                    <ClipboardIcon className="h-4 w-4"/>
                 </button>
              </div>
           </div>

           <div className="flex justify-between items-center px-4 bg-blue-50 dark:bg-blue-900/10 py-3 rounded-xl border border-blue-100 dark:border-blue-900/20">
              <span className="text-[10px] font-black text-blue-800 dark:text-blue-300 uppercase">Rede: {selectedNetwork}</span>
              <span className="text-[10px] font-black text-blue-800 dark:text-blue-300 uppercase">Total: ${amount.toFixed(2)}</span>
           </div>
        </div>

        <div className="flex flex-col gap-3">
          <button 
            onClick={() => onConfirm({ amount, mode: 'deposit' })} 
            className="w-full bg-green-600 text-white py-5 rounded-2xl font-black text-xs uppercase shadow-xl hover:bg-green-700 transition-all active:scale-95"
          >
            Confirmar Envio Cripto
          </button>
          <button onClick={onCancel} className="text-[10px] font-black text-gray-400 uppercase tracking-widest hover:text-red-500">Cancelar Transação</button>
        </div>
      </div>
    );
  }

  return (
    <div className="animate-fade-in space-y-6 relative">
      <button 
        onClick={onCancel} 
        className="absolute -top-2 -right-2 p-2 text-gray-400 hover:text-red-500 transition-colors z-10 bg-gray-50 dark:bg-white/5 rounded-full"
        title="Fechar"
      >
        <XMarkIcon className="h-6 w-6" />
      </button>

      {/* Header Centralizado */}
      <div className="text-center space-y-1">
        <h3 className="text-2xl font-black text-gray-900 dark:text-white tracking-tighter uppercase">Gestão de Carteira</h3>
        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Movimentação Financeira Segura</p>
      </div>

      {/* Seletor de Modo (Entrada/Saída) */}
      <div className="flex bg-gray-100 dark:bg-white/5 p-1.5 rounded-2xl">
        <button 
          onClick={() => setMode('deposit')}
          className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${mode === 'deposit' ? 'bg-white dark:bg-darkcard text-blue-600 shadow-md' : 'text-gray-400'}`}
        >
          <ArrowDownCircleIcon className="h-4 w-4" /> Depósito
        </button>
        <button 
          onClick={() => setMode('withdraw')}
          className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${mode === 'withdraw' ? 'bg-white dark:bg-darkcard text-red-600 shadow-md' : 'text-gray-400'}`}
        >
          <ArrowUpCircleIcon className="h-4 w-4" /> Saque
        </button>
      </div>

      <form onSubmit={handleAction} className="space-y-6">
        {/* Valor da Transação */}
        <div>
          <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-2 block">
            {mode === 'deposit' ? 'Quanto deseja recarregar?' : 'Valor do Resgate'} (USD)
          </label>
          <div className="relative">
             <span className="absolute left-5 top-1/2 -translate-y-1/2 text-2xl font-black text-gray-300">$</span>
             <input 
               type="number" 
               required 
               value={amount} 
               onChange={e => setAmount(Number(e.target.value))}
               className="w-full pl-10 pr-6 py-5 bg-gray-50 dark:bg-white/5 dark:text-white border-2 border-transparent focus:border-blue-500 rounded-[1.8rem] outline-none font-black text-2xl transition-all shadow-inner" 
               placeholder="0.00"
             />
          </div>
        </div>

        {mode === 'deposit' ? (
          <>
            {/* Métodos de Depósito */}
            <div className="space-y-3">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 block">Escolha o Método</label>
              <div className="grid grid-cols-2 gap-3">
                <button 
                  type="button" 
                  onClick={() => setMethod('crypto')}
                  className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${method === 'crypto' ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/10 text-blue-600' : 'border-gray-50 dark:border-white/5 text-gray-400 hover:border-gray-200'}`}
                >
                  <BoltIcon className="h-6 w-6" />
                  <span className="text-[9px] font-black uppercase">Criptomoedas</span>
                </button>
                <button 
                  type="button" 
                  onClick={() => setMethod('card')}
                  className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${method === 'card' ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/10 text-blue-600' : 'border-gray-50 dark:border-white/5 text-gray-400 hover:border-gray-200'}`}
                >
                  <CreditCardIcon className="h-6 w-6" />
                  <span className="text-[9px] font-black uppercase">Cartão / Fiat</span>
                </button>
              </div>
            </div>

            {method === 'crypto' ? (
              <div className="space-y-4 animate-fade-in">
                <div className="grid grid-cols-2 gap-2">
                  {CRYPTO_OPTIONS.map(coin => (
                    <button
                      key={coin.id}
                      type="button"
                      onClick={() => { setSelectedCoin(coin); setSelectedNetwork(coin.networks[0]); }}
                      className={`flex items-center gap-3 p-3 rounded-xl border-2 transition-all ${selectedCoin.id === coin.id ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/10' : 'border-gray-50 dark:border-white/5 hover:border-gray-100'}`}
                    >
                      <div className={`w-8 h-8 rounded-full bg-white shadow-sm flex items-center justify-center font-black text-[10px] ${coin.color}`}>{coin.id[0]}</div>
                      <div className="text-left overflow-hidden">
                        <p className="font-black text-xs text-gray-900 dark:text-white">{coin.id}</p>
                        <p className="text-[8px] text-gray-400 font-bold uppercase truncate">{coin.name}</p>
                      </div>
                    </button>
                  ))}
                </div>
                <div>
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-2 block">Rede de Transferência</label>
                   <div className="flex flex-wrap gap-2">
                      {selectedCoin.networks.map(net => (
                        <button key={net} type="button" onClick={() => setSelectedNetwork(net)} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${selectedNetwork === net ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-400'}`}>{net}</button>
                      ))}
                   </div>
                </div>
              </div>
            ) : (
              <div className="space-y-4 animate-fade-in bg-gray-50 dark:bg-white/5 p-6 rounded-[2rem] border border-gray-100 dark:border-white/10">
                 <div className="space-y-4">
                    <input type="text" placeholder="0000 0000 0000 0000" className="w-full p-4 rounded-xl border border-gray-200 dark:border-white/10 dark:bg-darkcard text-sm font-bold outline-none focus:border-blue-500 transition-all" />
                    <div className="grid grid-cols-2 gap-4">
                       <input type="text" placeholder="MM/AA" className="p-4 rounded-xl border border-gray-200 dark:border-white/10 dark:bg-darkcard text-sm font-bold outline-none focus:border-blue-500 transition-all" />
                       <input type="password" placeholder="CVV" className="p-4 rounded-xl border border-gray-200 dark:border-white/10 dark:bg-darkcard text-sm font-bold outline-none focus:border-blue-500 transition-all" />
                    </div>
                    <input type="text" placeholder="NOME NO CARTÃO" className="w-full p-4 rounded-xl border border-gray-200 dark:border-white/10 dark:bg-darkcard text-sm font-bold outline-none focus:border-blue-500 transition-all uppercase" />
                 </div>
                 <div className="flex items-center gap-2 justify-center pt-2">
                    <ShieldCheckIcon className="h-4 w-4 text-green-500" />
                    <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Pagamento Criptografado de Ponta a Ponta</span>
                 </div>
              </div>
            )}
          </>
        ) : (
          <div className="space-y-5 animate-fade-in">
             <div className="p-4 bg-red-50 dark:bg-red-900/10 rounded-2xl border border-red-100 dark:border-red-900/20 flex gap-3">
                <ExclamationTriangleIcon className="h-5 w-5 text-red-600 shrink-0" />
                <p className="text-[9px] text-red-800 dark:text-red-300 font-bold leading-tight">
                  Atenção: Verifique o endereço e a rede. Transações enviadas para redes incompatíveis ou endereços errados são irreversíveis.
                </p>
             </div>
             <div>
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-2 block">Moeda de Recebimento</label>
                <div className="grid grid-cols-4 gap-2">
                   {CRYPTO_OPTIONS.map(coin => (
                     <button 
                       key={coin.id} 
                       type="button" 
                       onClick={() => { setSelectedCoin(coin); setSelectedNetwork(coin.networks[0]); }}
                       className={`p-3 rounded-xl border-2 transition-all flex flex-col items-center gap-1 ${selectedCoin.id === coin.id ? 'border-red-500 bg-red-50 dark:bg-red-900/10' : 'border-gray-50 dark:border-white/5'}`}
                     >
                        <span className={`font-black text-xs ${coin.color}`}>{coin.id}</span>
                     </button>
                   ))}
                </div>
             </div>
             <div>
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-2 block">Seu Endereço de Carteira ({selectedCoin.id})</label>
                <input 
                  type="text" 
                  required 
                  value={walletAddress} 
                  onChange={e => setWalletAddress(e.target.value)}
                  placeholder="0x... ou endereço nativo" 
                  className="w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl border-2 border-transparent focus:border-red-500 outline-none font-bold text-xs transition-all shadow-inner"
                />
             </div>
             <div>
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 mb-2 block">Rede (Network)</label>
                <div className="flex flex-wrap gap-2">
                   {selectedCoin.networks.map(net => (
                     <button key={net} type="button" onClick={() => setSelectedNetwork(net)} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${selectedNetwork === net ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-400'}`}>{net}</button>
                   ))}
                </div>
             </div>
          </div>
        )}

        <div className="flex flex-col gap-3 pt-4">
           <button 
             type="submit"
             disabled={loading}
             className={`w-full py-5 rounded-[2rem] font-black text-sm uppercase shadow-xl transition-all active:scale-95 flex items-center justify-center gap-2 disabled:opacity-50 ${mode === 'deposit' ? 'bg-blue-600 text-white' : 'bg-gray-900 text-white'}`}
           >
             {loading ? <div className="w-5 h-5 border-2 border-white border-t-transparent animate-spin rounded-full" /> : <><GlobeAltIcon className="h-5 w-5" /> {mode === 'deposit' ? (method === 'crypto' ? 'Gerar Endereço' : 'Finalizar com Cartão') : 'Solicitar Resgate'}</>}
           </button>
           <button type="button" onClick={onCancel} className="w-full py-2 text-[9px] font-black text-gray-400 uppercase tracking-widest text-center">Voltar</button>
        </div>
      </form>
    </div>
  );
};

export default CryptomusPaymentForm;

import React, { useState, useEffect, useRef } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { addPost, updatePost, getPosts } from '../services/storageService';
import RecordReelModal from './RecordReelModal';
import { 
  SparklesIcon, 
  VideoCameraIcon, 
  PhotoIcon, 
  XMarkIcon,
  DocumentTextIcon,
  LockClosedIcon,
  FilmIcon,
  ArrowUpTrayIcon,
  TrashIcon,
  ChevronRightIcon,
  BriefcaseIcon
} from '@heroicons/react/24/solid';

interface CreatePostProps {
  currentUser: User;
  onPostCreated: () => void;
  refreshUser: () => void;
  postId?: string;
}

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [liveTitle, setLiveTitle] = useState('');
  const [liveDescription, setLiveDescription] = useState('');
  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('0');
  const [showRecordReel, setShowRecordReel] = useState(false);

  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isEditing = !!postId;
  const isProfessional = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    if (postId) {
      const posts = getPosts();
      const postToEdit = posts.find(p => p.id === postId);
      if (postToEdit) {
        setPostType(postToEdit.type);
        setContent(postToEdit.content || '');
        setImageUrl(postToEdit.imageUrl || '');
        if (postToEdit.type === PostType.LIVE && postToEdit.liveStream) {
          setLiveTitle(postToEdit.liveStream.title);
          setLiveDescription(postToEdit.liveStream.description);
          setIsLivePaid(postToEdit.liveStream.isPaid);
          setLivePrice(postToEdit.liveStream.price?.toString() || '0');
        }
      }
    }
  }, [postId]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImageUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveReel = (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setLoading(true);
    // Simula upload de vídeo
    const reader = new FileReader();
    reader.onloadend = () => {
      const videoUrl = reader.result as string;
      const newReel: Post = {
        id: `reel-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: PostType.REEL,
        timestamp: Date.now(),
        reel: {
          videoUrl: videoUrl,
          description: "Novo Reel CyBerPhone! 🚀",
          audioTrackId: audioTrackId,
          aiEffectPrompt: aiPrompt,
          filter: filter
        },
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };
      addPost(newReel);
      setLoading(false);
      setShowRecordReel(false);
      onPostCreated();
    };
    reader.readAsBlob(videoBlob);
    reader.readAsDataURL(videoBlob);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const postData: Post = {
        id: isEditing ? postId! : `post-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: postType,
        timestamp: Date.now(),
        content: postType !== PostType.LIVE ? content : undefined,
        imageUrl: postType === PostType.IMAGE ? imageUrl : undefined,
        liveStream: postType === PostType.LIVE ? {
          title: liveTitle,
          description: liveDescription,
          isPaid: isLivePaid,
          price: isLivePaid ? parseFloat(livePrice) : 0
        } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };

      if (isEditing) updatePost(postData);
      else addPost(postData);

      onPostCreated();
      if (!isEditing) {
        setIsExpanded(false);
        setContent('');
        setImageUrl('');
        setLiveTitle('');
        setLiveDescription('');
      }
    } catch (err) {
      alert('Erro ao salvar publicação.');
    } finally {
      setLoading(false);
    }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2rem] shadow-sm p-4 border border-gray-100 dark:border-white/10 flex flex-col gap-3">
         <div className="flex items-start gap-3">
            <img src={currentUser.profilePicture} className="w-10 h-10 rounded-xl object-cover shrink-0" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-4 py-2.5 bg-slate-50 dark:bg-white/5 rounded-xl text-gray-400 font-bold text-xs md:text-sm">
              {isProfessional ? `Olá Profissional, o que temos para a rede hoje?` : `O que você está pensando, ${currentUser.firstName}?`}
            </button>
         </div>
         <div className="flex items-center gap-4 md:gap-6 px-1 border-t border-gray-50 dark:border-white/5 pt-2 overflow-x-auto no-scrollbar">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-2 text-gray-500 hover:text-blue-600 transition-all shrink-0">
               <PhotoIcon className="h-5 w-5 text-blue-500" />
               <span className="text-[10px] font-black uppercase tracking-widest">Mídia</span>
            </button>
            <button onClick={() => setShowRecordReel(true)} className="flex items-center gap-2 text-gray-500 hover:text-purple-600 transition-all shrink-0">
               <FilmIcon className="h-5 w-5 text-purple-500" />
               <span className="text-[10px] font-black uppercase tracking-widest">Gravar Reel</span>
            </button>
            {isProfessional && (
              <button onClick={() => { setIsExpanded(true); setPostType(PostType.LIVE); }} className="flex items-center gap-2 text-gray-500 hover:text-red-600 transition-all shrink-0">
                 <VideoCameraIcon className="h-5 w-5 text-red-500" />
                 <span className="text-[10px] font-black uppercase tracking-widest">Live</span>
              </button>
            )}
         </div>
         {showRecordReel && <RecordReelModal onClose={() => setShowRecordReel(false)} onSave={handleSaveReel} />}
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-2xl p-6 md:p-8 border border-blue-50 dark:border-white/5 animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 left-0 w-2 h-full bg-blue-600"></div>

      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
           <div className={`p-3 text-white rounded-2xl shadow-lg ${postType === PostType.LIVE ? 'bg-red-600' : 'bg-blue-600'}`}>
             {postType === PostType.LIVE ? <VideoCameraIcon className="h-6 w-6" /> : <BriefcaseIcon className="h-6 w-6" />}
           </div>
           <div>
              <h3 className="font-black text-gray-900 dark:text-white uppercase text-[10px] tracking-[0.2em]">{isEditing ? 'Editar Post' : 'Novo Insight CyBer'}</h3>
              <p className="text-[8px] text-blue-500 font-black uppercase mt-0.5 tracking-widest">Conectando Autoridade</p>
           </div>
        </div>
        <button onClick={() => setIsExpanded(false)} className="p-2 text-gray-300 hover:text-red-500 transition-colors"><XMarkIcon className="h-6 w-6" /></button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex flex-wrap gap-2 p-1.5 bg-slate-50 dark:bg-white/5 rounded-2xl w-fit">
           {[
             { id: PostType.TEXT, icon: DocumentTextIcon, label: 'Texto', locked: false },
             { id: PostType.IMAGE, icon: PhotoIcon, label: 'Mídia', locked: false },
             { id: PostType.LIVE, icon: VideoCameraIcon, label: 'Transmissão', locked: !isProfessional }
           ].map(t => (
             <button key={t.id} type="button" disabled={t.locked} onClick={() => setPostType(t.id)} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${postType === t.id ? 'bg-white dark:bg-white/10 text-blue-600 dark:text-white shadow-sm' : 'text-gray-400'} ${t.locked ? 'opacity-30' : ''}`}>
                {t.locked ? <LockClosedIcon className="h-3 w-3" /> : <t.icon className="h-4 w-4" />} {t.label}
             </button>
           ))}
        </div>

        {postType === PostType.LIVE ? (
          <div className="space-y-4 animate-fade-in">
            <input
              type="text"
              value={liveTitle}
              onChange={(e) => setLiveTitle(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-bold text-lg dark:text-white"
              placeholder="Título da Transmissão..."
              required
            />
            <textarea
              value={liveDescription}
              onChange={(e) => setLiveDescription(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-medium text-base dark:text-white h-32 resize-none"
              placeholder="Descreva o conteúdo desta live para seus seguidores..."
            />
            <div className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-white/5 rounded-2xl">
               <label className="flex items-center gap-2 cursor-pointer">
                  <input type="checkbox" checked={isLivePaid} onChange={e => setIsLivePaid(e.target.checked)} className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                  <span className="text-xs font-black uppercase text-gray-700 dark:text-gray-300">Live Paga</span>
               </label>
               {isLivePaid && (
                  <input 
                    type="number" 
                    value={livePrice} 
                    onChange={e => setLivePrice(e.target.value)}
                    className="flex-1 p-2 bg-white dark:bg-darkcard border rounded-lg outline-none font-bold text-blue-600"
                    placeholder="Valor de Acesso (USD)"
                  />
               )}
            </div>
          </div>
        ) : (
          <>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-medium text-lg dark:text-white h-40 resize-none"
              placeholder={postType === PostType.IMAGE ? "Dê uma legenda para sua foto ou trabalho..." : "O que você gostaria de compartilhar com a rede?"}
              required
            />

            {postType === PostType.IMAGE && (
              <div className="space-y-4 animate-fade-in">
                <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
                {!imageUrl ? (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full h-64 border-2 border-dashed border-gray-200 dark:border-white/10 rounded-3xl flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-blue-500 transition-all group">
                      <ArrowUpTrayIcon className="h-8 w-8 text-gray-400 group-hover:text-blue-600" />
                      <span className="text-[10px] font-black text-gray-400 uppercase">Fazer Upload de Mídia</span>
                  </div>
                ) : (
                  <div className="relative rounded-3xl overflow-hidden border-2 border-blue-500 group">
                      <img src={imageUrl} className="w-full h-auto max-h-[400px] object-cover" alt="Preview" />
                      <button onClick={() => setImageUrl('')} className="absolute top-4 right-4 p-2 bg-red-600 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity"><TrashIcon className="h-5 w-5"/></button>
                  </div>
                )}
              </div>
            )}
          </>
        )}

        <div className="flex justify-end gap-3 pt-6 border-t dark:border-white/5">
           <button 
              type="submit" 
              disabled={loading || (!content && !liveTitle)} 
              className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black text-xs uppercase shadow-xl hover:bg-blue-700 active:scale-95 transition-all flex items-center gap-2"
           >
              {loading ? 'Processando...' : isEditing ? 'Salvar' : 'Postar'} <ChevronRightIcon className="h-4 w-4" />
           </button>
        </div>
      </form>
    </div>
  );
};

export default CreatePost;

import React, { useState, useRef, useEffect } from 'react';
import { XMarkIcon, VideoCameraIcon, StopIcon, ArrowPathIcon, MusicalNoteIcon, SparklesIcon, CheckIcon, MagicWandIcon, ChevronDownIcon } from '@heroicons/react/24/solid';
import { AudioTrack } from '../types';
import AudioSelectionModal from './AudioSelectionModal';

interface RecordReelModalProps {
  onClose: () => void;
  onSave: (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => void;
}

const VIDEO_FILTERS = [
  { id: 'none', label: 'Normal', css: '' },
  { id: 'grayscale(1) contrast(1.2)', label: 'Noir', css: 'grayscale(1) contrast(1.2)' },
  { id: 'sepia(0.6) saturate(1.5)', label: 'Vintage', css: 'sepia(0.6) saturate(1.5)' },
  { id: 'hue-rotate(90deg) brightness(1.2)', label: 'Neon', css: 'hue-rotate(90deg) brightness(1.2)' },
  { id: 'saturate(2.5) contrast(1.1)', label: 'Vibrante', css: 'saturate(2.5) contrast(1.1)' },
  { id: 'invert(0.9) hue-rotate(180deg)', label: 'Raio-X', css: 'invert(0.9) hue-rotate(180deg)' },
  { id: 'blur(1.5px) saturate(1.8)', label: 'Sonho', css: 'blur(1.5px) saturate(1.8)' },
  { id: 'contrast(1.5) brightness(0.8)', label: 'Drama', css: 'contrast(1.5) brightness(0.8)' },
  { id: 'sepia(0.2) brightness(1.3) contrast(0.9)', label: 'Brilho', css: 'sepia(0.2) brightness(1.3) contrast(0.9)' },
];

const RecordReelModal: React.FC<RecordReelModalProps> = ({ onClose, onSave }) => {
  const [isRecording, setIsRecording] = useState(false);
  const [recordedVideo, setRecordedVideo] = useState<Blob | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [timer, setTimer] = useState(0);
  const [showAudioModal, setShowAudioModal] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedAudioId, setSelectedAudioId] = useState<string | undefined>(undefined);
  const [selectedFilter, setSelectedFilter] = useState(VIDEO_FILTERS[0]);
  const [aiPrompt, setAiPrompt] = useState('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const timerIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    startCamera();
    return () => {
      stopCamera();
      if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
    };
  }, []);

  const startCamera = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', aspectRatio: 9/16 }, 
        audio: true 
      });
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
    } catch (err) {
      alert("Permissão de câmera negada ou erro no hardware.");
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
    }
  };

  const startRecording = () => {
    if (!stream) return;
    chunksRef.current = [];
    const recorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
    recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunksRef.current.push(e.data);
    };
    recorder.onstop = () => {
      const blob = new Blob(chunksRef.current, { type: 'video/webm' });
      setRecordedVideo(blob);
    };

    recorder.start(1000); // Coleta dados a cada 1s
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
    setTimer(0);

    timerIntervalRef.current = window.setInterval(() => {
      setTimer(prev => {
        if (prev >= 60) {
          stopRecording();
          return 60;
        }
        return prev + 1;
      });
    }, 1000);
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
    }
  };

  const handleSave = () => {
    if (recordedVideo) {
      onSave(recordedVideo, selectedAudioId, aiPrompt, selectedFilter.id);
    }
  };

  return (
    <div className="fixed inset-0 bg-black z-[200] flex flex-col animate-fade-in overflow-hidden">
      {/* Header Bar */}
      <div className="absolute top-0 left-0 w-full p-6 flex justify-between items-center z-50 bg-gradient-to-b from-black/80 to-transparent">
        <button onClick={onClose} className="p-3 bg-white/10 rounded-full text-white backdrop-blur-md hover:bg-white/20 transition-all">
          <XMarkIcon className="h-6 w-6" />
        </button>

        <div className="flex flex-col items-center">
           <div className={`px-4 py-1.5 rounded-full text-[10px] font-black text-white uppercase tracking-[0.2em] transition-colors ${isRecording ? 'bg-red-600 animate-pulse' : 'bg-white/20 backdrop-blur-md'}`}>
             {isRecording ? `Gravando • ${timer}s` : 'Capture seu Conhecimento'}
           </div>
        </div>

        <div className="w-12"></div>
      </div>

      {/* Viewport Principal */}
      <div className="flex-1 relative bg-[#050505] flex items-center justify-center">
        {!recordedVideo ? (
          <video 
            ref={videoRef} 
            autoPlay 
            muted 
            playsInline 
            className="w-full h-full object-cover scale-x-[-1]" 
            style={{ filter: selectedFilter.id === 'none' ? 'none' : selectedFilter.id }}
          />
        ) : (
          <video 
            src={URL.createObjectURL(recordedVideo)} 
            autoPlay 
            loop 
            playsInline 
            className="w-full h-full object-cover" 
            style={{ filter: selectedFilter.id === 'none' ? 'none' : selectedFilter.id }}
          />
        )}

        {/* Barra Lateral de Ferramentas */}
        {!isRecording && !recordedVideo && !showFilters && (
          <div className="absolute right-5 top-1/2 -translate-y-1/2 flex flex-col gap-6 z-40">
             <button onClick={() => setShowAudioModal(true)} className="flex flex-col items-center gap-1.5 group">
                <div className={`p-4 rounded-2xl backdrop-blur-xl border border-white/20 transition-all shadow-2xl ${selectedAudioId ? 'bg-blue-600' : 'bg-black/40 group-hover:bg-black/60'}`}>
                  <MusicalNoteIcon className="h-6 w-6 text-white" />
                </div>
                <span className="text-[8px] font-black text-white uppercase tracking-widest shadow-lg">Áudio</span>
             </button>

             <button onClick={() => setShowFilters(true)} className="flex flex-col items-center gap-1.5 group">
                <div className="p-4 bg-black/40 rounded-2xl backdrop-blur-xl border border-white/20 transition-all shadow-2xl group-hover:bg-black/60">
                  <SparklesIcon className="h-6 w-6 text-white" />
                </div>
                <span className="text-[8px] font-black text-white uppercase tracking-widest shadow-lg">Filtros</span>
             </button>
          </div>
        )}

        {/* PRATELEIRA DE FILTROS COM ROLAGEM */}
        {showFilters && !isRecording && (
          <div className="absolute inset-0 z-50 flex flex-col justify-end bg-black/20 animate-fade-in" onClick={() => setShowFilters(false)}>
             <div 
               className="w-full bg-gradient-to-t from-black via-black/90 to-transparent pt-20 pb-10 px-0 animate-slide-up"
               onClick={e => e.stopPropagation()}
             >
                <div className="flex items-center justify-between px-8 mb-6">
                   <h4 className="text-[10px] font-black text-white uppercase tracking-[0.3em]">Estilos Criativos</h4>
                   <button onClick={() => setShowFilters(false)} className="bg-white/10 p-2 rounded-full text-white hover:bg-white/20 transition-all">
                      <CheckIcon className="h-4 w-4" />
                   </button>
                </div>

                <div className="flex gap-4 px-8 overflow-x-auto no-scrollbar scroll-smooth py-2 filter-shelf">
                   {VIDEO_FILTERS.map(filter => (
                     <button
                       key={filter.id}
                       onClick={() => setSelectedFilter(filter)}
                       className="flex flex-col items-center gap-3 shrink-0 group transition-transform active:scale-95"
                     >
                        <div className={`w-16 h-16 rounded-2xl border-2 transition-all duration-300 overflow-hidden relative ${selectedFilter.id === filter.id ? 'border-blue-500 scale-110 shadow-[0_0_20px_rgba(59,130,246,0.5)]' : 'border-white/20 opacity-60'}`}>
                           <div className="w-full h-full bg-gradient-to-tr from-gray-800 to-gray-700" style={{ filter: filter.id === 'none' ? 'none' : filter.id }}></div>
                           {selectedFilter.id === filter.id && (
                             <div className="absolute inset-0 flex items-center justify-center bg-blue-600/20">
                                <CheckIcon className="h-5 w-5 text-white" />
                             </div>
                           )}
                        </div>
                        <span className={`text-[9px] font-black uppercase tracking-widest ${selectedFilter.id === filter.id ? 'text-blue-400' : 'text-white/40'}`}>{filter.label}</span>
                     </button>
                   ))}
                </div>
             </div>
          </div>
        )}
      </div>

      {/* Footer Controls */}
      <div className="p-10 bg-gradient-to-t from-black via-black/60 to-transparent z-50 flex flex-col items-center gap-8">
        {!recordedVideo ? (
          <div className="flex items-center gap-10">
             <div className="w-12"></div>
             <button 
                onClick={isRecording ? stopRecording : startRecording}
                className={`relative group transition-all duration-500 ${isRecording ? 'scale-110' : 'hover:scale-105'}`}
             >
                <div className={`absolute inset-0 rounded-full blur-xl opacity-50 group-hover:opacity-100 transition-opacity ${isRecording ? 'bg-red-600' : 'bg-white'}`}></div>
                <div className={`w-20 h-20 rounded-full border-4 flex items-center justify-center relative z-10 ${isRecording ? 'border-red-600 bg-red-600/20' : 'border-white bg-white/10'}`}>
                  {isRecording ? <StopIcon className="h-10 w-10 text-red-600" /> : <div className="w-14 h-14 bg-red-600 rounded-full shadow-2xl" />}
                </div>
             </button>
             <button className="p-3 bg-white/10 rounded-full text-white/40 hover:text-white transition-all">
                <ArrowPathIcon className="h-6 w-6" />
             </button>
          </div>
        ) : (
          <div className="w-full max-w-lg animate-fade-in space-y-8">
            <div className="bg-white/10 backdrop-blur-2xl rounded-[2.5rem] p-8 border border-white/10 shadow-2xl">
               <div className="flex items-center gap-3 mb-5">
                  <div className="bg-purple-600 p-2 rounded-xl"><SparklesIcon className="h-5 w-5 text-white" /></div>
                  <span className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Refinar Estilo com IA</span>
               </div>
               <div className="relative group">
                  <input 
                    type="text" 
                    value={aiPrompt}
                    onChange={e => setAiPrompt(e.target.value)}
                    placeholder="Ex: Estilo Ghibli, Realismo Fantástico, VHS 90s..."
                    className="w-full bg-black/40 border-2 border-white/5 rounded-2xl p-5 text-sm text-white placeholder-white/20 focus:ring-0 focus:border-purple-500 transition-all font-bold"
                  />
                  <div className="absolute right-4 top-1/2 -translate-y-1/2 opacity-20 group-hover:opacity-100 transition-opacity">
                    <SparklesIcon className="h-5 w-5 text-purple-400" />
                  </div>
               </div>
            </div>

            <div className="flex gap-4">
              <button 
                onClick={() => { setRecordedVideo(null); setAiPrompt(''); }} 
                className="flex-1 py-5 bg-white/10 rounded-3xl text-white font-black text-xs uppercase tracking-[0.2em] hover:bg-white/20 transition-all flex items-center justify-center gap-3 border border-white/5"
              >
                <ArrowPathIcon className="h-4 w-4" /> Refazer
              </button>
              <button 
                onClick={handleSave} 
                className="flex-[2] py-5 bg-blue-600 rounded-3xl text-white font-black text-xs uppercase tracking-[0.2em] shadow-[0_20px_40px_rgba(37,99,235,0.4)] active:scale-95 transition-all flex items-center justify-center gap-3"
              >
                <CheckIcon className="h-5 w-5" /> Salvar Reel
              </button>
            </div>
          </div>
        )}
      </div>

      {showAudioModal && (
        <AudioSelectionModal 
          onClose={() => setShowAudioModal(false)} 
          onSelectTrack={(id) => { setSelectedAudioId(id); setShowAudioModal(false); }} 
        />
      )}
    </div>
  );
};

export default RecordReelModal;

import React, { useState, useEffect, useRef } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { addPost, updatePost, getPosts } from '../services/storageService';
import RecordReelModal from './RecordReelModal';
import { 
  SparklesIcon, 
  VideoCameraIcon, 
  PhotoIcon, 
  XMarkIcon,
  DocumentTextIcon,
  LockClosedIcon,
  FilmIcon,
  ArrowUpTrayIcon,
  TrashIcon,
  ChevronRightIcon,
  BriefcaseIcon
} from '@heroicons/react/24/solid';

interface CreatePostProps {
  currentUser: User;
  onPostCreated: () => void;
  refreshUser: () => void;
  postId?: string;
}

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [liveTitle, setLiveTitle] = useState('');
  const [liveDescription, setLiveDescription] = useState('');
  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('0');
  const [showRecordReel, setShowRecordReel] = useState(false);

  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isEditing = !!postId;
  const isProfessional = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    if (postId) {
      const posts = getPosts();
      const postToEdit = posts.find(p => p.id === postId);
      if (postToEdit) {
        setPostType(postToEdit.type);
        setContent(postToEdit.content || '');
        setImageUrl(postToEdit.imageUrl || '');
        if (postToEdit.type === PostType.LIVE && postToEdit.liveStream) {
          setLiveTitle(postToEdit.liveStream.title);
          setLiveDescription(postToEdit.liveStream.description);
          setIsLivePaid(postToEdit.liveStream.isPaid);
          setLivePrice(postToEdit.liveStream.price?.toString() || '0');
        }
      }
    }
  }, [postId]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImageUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveReel = (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setLoading(true);
    // Simula upload de vídeo
    const reader = new FileReader();
    reader.onloadend = () => {
      const videoUrl = reader.result as string;
      const newReel: Post = {
        id: `reel-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: PostType.REEL,
        timestamp: Date.now(),
        reel: {
          videoUrl: videoUrl,
          description: "Novo Reel CyBerPhone! 🚀",
          audioTrackId: audioTrackId,
          aiEffectPrompt: aiPrompt,
          filter: filter
        },
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };
      addPost(newReel);
      setLoading(false);
      setShowRecordReel(false);
      onPostCreated();
    };
    // Fix: Removed non-existent readAsBlob method. 'readAsDataURL' is sufficient to generate the base64 URL.
    reader.readAsDataURL(videoBlob);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const postData: Post = {
        id: isEditing ? postId! : `post-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: postType,
        timestamp: Date.now(),
        content: postType !== PostType.LIVE ? content : undefined,
        imageUrl: postType === PostType.IMAGE ? imageUrl : undefined,
        liveStream: postType === PostType.LIVE ? {
          title: liveTitle,
          description: liveDescription,
          isPaid: isLivePaid,
          price: isLivePaid ? parseFloat(livePrice) : 0
        } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };

      if (isEditing) updatePost(postData);
      else addPost(postData);

      onPostCreated();
      if (!isEditing) {
        setIsExpanded(false);
        setContent('');
        setImageUrl('');
        setLiveTitle('');
        setLiveDescription('');
      }
    } catch (err) {
      alert('Erro ao salvar publicação.');
    } finally {
      setLoading(false);
    }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2rem] shadow-sm p-4 border border-gray-100 dark:border-white/10 flex flex-col gap-3">
         <div className="flex items-start gap-3">
            <img src={currentUser.profilePicture} className="w-10 h-10 rounded-xl object-cover shrink-0" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-4 py-2.5 bg-slate-50 dark:bg-white/5 rounded-xl text-gray-400 font-bold text-xs md:text-sm">
              {isProfessional ? `Olá Profissional, o que temos para a rede hoje?` : `O que você está pensando, ${currentUser.firstName}?`}
            </button>
         </div>
         <div className="flex items-center gap-4 md:gap-6 px-1 border-t border-gray-50 dark:border-white/5 pt-2 overflow-x-auto no-scrollbar">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-2 text-gray-500 hover:text-blue-600 transition-all shrink-0">
               <PhotoIcon className="h-5 w-5 text-blue-500" />
               <span className="text-[10px] font-black uppercase tracking-widest">Mídia</span>
            </button>
            <button onClick={() => setShowRecordReel(true)} className="flex items-center gap-2 text-gray-500 hover:text-purple-600 transition-all shrink-0">
               <FilmIcon className="h-5 w-5 text-purple-500" />
               <span className="text-[10px] font-black uppercase tracking-widest">Gravar Reel</span>
            </button>
            {isProfessional && (
              <button onClick={() => { setIsExpanded(true); setPostType(PostType.LIVE); }} className="flex items-center gap-2 text-gray-500 hover:text-red-600 transition-all shrink-0">
                 <VideoCameraIcon className="h-5 w-5 text-red-500" />
                 <span className="text-[10px] font-black uppercase tracking-widest">Live</span>
              </button>
            )}
         </div>
         {showRecordReel && <RecordReelModal onClose={() => setShowRecordReel(false)} onSave={handleSaveReel} />}
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-2xl p-6 md:p-8 border border-blue-50 dark:border-white/5 animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 left-0 w-2 h-full bg-blue-600"></div>

      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
           <div className={`p-3 text-white rounded-2xl shadow-lg ${postType === PostType.LIVE ? 'bg-red-600' : 'bg-blue-600'}`}>
             {postType === PostType.LIVE ? <VideoCameraIcon className="h-6 w-6" /> : <BriefcaseIcon className="h-6 w-6" />}
           </div>
           <div>
              <h3 className="font-black text-gray-900 dark:text-white uppercase text-[10px] tracking-[0.2em]">{isEditing ? 'Editar Post' : 'Novo Insight CyBer'}</h3>
              <p className="text-[8px] text-blue-500 font-black uppercase mt-0.5 tracking-widest">Conectando Autoridade</p>
           </div>
        </div>
        <button onClick={() => setIsExpanded(false)} className="p-2 text-gray-300 hover:text-red-500 transition-colors"><XMarkIcon className="h-6 w-6" /></button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex flex-wrap gap-2 p-1.5 bg-slate-50 dark:bg-white/5 rounded-2xl w-fit">
           {[
             { id: PostType.TEXT, icon: DocumentTextIcon, label: 'Texto', locked: false },
             { id: PostType.IMAGE, icon: PhotoIcon, label: 'Mídia', locked: false },
             { id: PostType.LIVE, icon: VideoCameraIcon, label: 'Transmissão', locked: !isProfessional }
           ].map(t => (
             <button key={t.id} type="button" disabled={t.locked} onClick={() => setPostType(t.id)} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${postType === t.id ? 'bg-white dark:bg-white/10 text-blue-600 dark:text-white shadow-sm' : 'text-gray-400'} ${t.locked ? 'opacity-30' : ''}`}>
                {t.locked ? <LockClosedIcon className="h-3 w-3" /> : <t.icon className="h-4 w-4" />} {t.label}
             </button>
           ))}
        </div>

        {postType === PostType.LIVE ? (
          <div className="space-y-4 animate-fade-in">
            <input
              type="text"
              value={liveTitle}
              onChange={(e) => setLiveTitle(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-bold text-lg dark:text-white"
              placeholder="Título da Transmissão..."
              required
            />
            <textarea
              value={liveDescription}
              onChange={(e) => setLiveDescription(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-medium text-base dark:text-white h-32 resize-none"
              placeholder="Descreva o conteúdo desta live para seus seguidores..."
            />
            <div className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-white/5 rounded-2xl">
               <label className="flex items-center gap-2 cursor-pointer">
                  <input type="checkbox" checked={isLivePaid} onChange={e => setIsLivePaid(e.target.checked)} className="w-5 h-5 rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                  <span className="text-xs font-black uppercase text-gray-700 dark:text-gray-300">Live Paga</span>
               </label>
               {isLivePaid && (
                  <input 
                    type="number" 
                    value={livePrice} 
                    onChange={e => setLivePrice(e.target.value)}
                    className="flex-1 p-2 bg-white dark:bg-darkcard border rounded-lg outline-none font-bold text-blue-600"
                    placeholder="Valor de Acesso (USD)"
                  />
               )}
            </div>
          </div>
        ) : (
          <>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-medium text-lg dark:text-white h-40 resize-none"
              placeholder={postType === PostType.IMAGE ? "Dê uma legenda para sua foto ou trabalho..." : "O que você gostaria de compartilhar com a rede?"}
