          <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
            <PlayIcon className="h-20 w-20 text-white/50 animate-pulse" />
          </div>
        )}

        {/* DOUBLE TAP HEARTS */}
        {likeHearts.map(heart => (
          <div key={heart.id} className="absolute z-50 pointer-events-none animate-like-heart" style={{ left: heart.x - 40, top: heart.y - 40 }}>
            <HeartIconSolid className="w-24 h-24 text-red-500 drop-shadow-[0_0_15px_rgba(239,68,68,0.8)]" />
          </div>
        ))}

        {/* SIDEBAR DE AÇÕES (DIREITA) */}
        <div className="absolute bottom-24 right-3 flex flex-col items-center gap-5 z-40">
           {/* Perfil */}
           <div className="relative mb-2">
              <div 
                className="w-12 h-12 rounded-full border-2 border-white overflow-hidden cursor-pointer"
                onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}
              >
                 <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-full h-full object-cover" />
              </div>
              {!isFollowing && currentUser.id !== post.userId && (
                <button 
                  onClick={(e) => { e.stopPropagation(); onFollowToggle(post.userId); }}
                  className="absolute -bottom-2 left-1/2 -translate-x-1/2 bg-[#fe2c55] text-white rounded-full p-0.5 border-2 border-white shadow-lg"
                >
                   <PlusIcon className="h-3 w-3" />
                </button>
              )}
           </div>

           {/* Like */}
           <button onClick={(e) => { e.stopPropagation(); handleLike(); }} className="flex flex-col items-center">
              <HeartIconSolid className={`h-9 w-9 drop-shadow-lg transition-colors ${hasLiked ? 'text-[#fe2c55]' : 'text-white'}`} />
              <span className="text-[11px] font-bold text-white mt-1 drop-shadow-md">{post.likes?.length || 0}</span>
           </button>

           {/* Comentar */}
           <button onClick={(e) => { e.stopPropagation(); setIsCommentsModalOpen(true); }} className="flex flex-col items-center">
              <ChatIconOutline className="h-9 w-9 text-white drop-shadow-lg" />
