           </button>

           {/* Salvar */}
           <button onClick={(e) => { e.stopPropagation(); updatePostSaves(post.id, currentUser.id); onPostUpdate(); }} className="flex flex-col items-center">
              <BookmarkIconSolid className={`h-9 w-9 drop-shadow-lg transition-colors ${hasSaved ? 'text-[#facd3b]' : 'text-white'}`} />
              <span className="text-[11px] font-bold text-white mt-1 drop-shadow-md">{post.saves?.length || 0}</span>
           </button>

           {/* Indicar */}
           <button onClick={(e) => { e.stopPropagation(); setIsIndicateModalOpen(true); }} className="flex flex-col items-center">
