           {/* TICKER DE ÁUDIO */}
           <div className="flex items-center gap-2 mt-2 pointer-events-auto">
              <MusicalNoteIcon className="h-4 w-4 text-white animate-pulse" />
              <div className="overflow-hidden w-full h-5 relative">
                 <div className="whitespace-nowrap text-xs font-bold text-white animate-marquee-text flex items-center gap-8">
                    <span>{audioTrack ? `${audioTrack.title} - ${audioTrack.artist}` : `Áudio original - ${post.authorName}`}</span>
                    <span>{audioTrack ? `${audioTrack.title} - ${audioTrack.artist}` : `Áudio original - ${post.authorName}`}</span>
                 </div>
              </div>
           </div>
        </div>
      </div>

      {isCommentsModalOpen && (
        <CommentsModal postId={post.id} currentUser={currentUser} onClose={() => setIsCommentsModalOpen(false)} onCommentsUpdated={onPostUpdate} />
      )}

      {isIndicateModalOpen && (
        <IndicateModal post={post} currentUser={currentUser} onClose={() => setIsIndicateModalOpen(false)} onPostUpdated={onPostUpdate} />
      )}

      <style>{`
        @keyframes spin-disk { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        .animate-spin-disk { animation: spin-disk 4s linear infinite; }

        @keyframes marquee-text {
          0% { transform: translateX(0%); }
          100% { transform: translateX(-50%); }
        }
        .animate-marquee-text { animation: marquee-text 10s linear infinite; }

        @keyframes like-heart {
          0% { transform: scale(0.2) rotate(-15deg); opacity: 0; }
          20% { transform: scale(1.2) rotate(10deg); opacity: 1; }
          40% { transform: scale(1) rotate(-5deg); opacity: 1; }
          100% { transform: scale(2) rotate(0deg); opacity: 0; }
        }
        .animate-like-heart { animation: like-heart 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </>
  );
};

const ReelsPage: React.FC<ReelsPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [reels, setReels] = useState<Post[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);
  const [visibleIdx, setVisibleIdx] = useState(0);

  useEffect(() => {
    setReels(getPosts().filter(p => p.type === PostType.REEL));
  }, []);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) setVisibleIdx(Number((e.target as HTMLElement).dataset.idx));
      });
    }, { threshold: 0.7 });

    const items = containerRef.current?.children;
    /* Fix: Explicitly cast item to Element to resolve 'unknown' type error in IntersectionObserver */
    if (items) Array.from(items).forEach(item => observer.observe(item as Element));
    return () => observer.disconnect();
  }, [reels]);

  const handleFollow = (id: string) => {
    toggleFollowUser(currentUser.id, id);
    refreshUser();
  };

  return (
    <div 
      ref={containerRef} 
      className="fixed inset-0 top-[64px] md:top-[72px] bg-black overflow-y-scroll snap-y snap-mandatory no-scrollbar h-[calc(100vh-64px)] md:h-[calc(100vh-72px)]"
      style={{ scrollbarWidth: 'none' }}
    >
      {reels.map((r, i) => (
        <div key={r.id} data-idx={i} className="h-full w-full snap-start relative">
          <ReelVideo 
            post={r} 
            currentUser={currentUser} 
            onNavigate={onNavigate} 
            onFollowToggle={handleFollow} 
            refreshUser={refreshUser} 
            isIntersecting={i === visibleIdx}
            onPostUpdate={() => setReels(getPosts().filter(p => p.type === PostType.REEL))}
          />
        </div>
      ))}
    </div>
  );
};

