import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { Post, User, UserType } from '../types';
import { findUserById, addPostComment, updatePostLikes, updatePostSaves, updatePostShares, toggleFollowUser } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  XMarkIcon, 
  ChatBubbleOvalLeftIcon,
  HeartIcon as HeartIconOutline,
  BookmarkIcon as BookmarkIconOutline,
  ShareIcon,
  EllipsisHorizontalIcon,
  ArrowLeftIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid,
  BookmarkIcon as BookmarkIconSolid,
  CheckBadgeIcon
} from '@heroicons/react/24/solid';

interface PostDetailModalProps {
  post: Post;
  currentUser: User;
  onClose: () => void;
  onUpdate: () => void;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const PostDetailModal: React.FC<PostDetailModalProps> = ({ post, currentUser, onClose, onUpdate, onNavigate, refreshUser }) => {
  const [commentText, setCommentText] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  const author = findUserById(post.userId);
  const isOwner = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId);
  const hasLiked = post.likes?.includes(currentUser.id);
  const hasSaved = post.saves?.includes(currentUser.id);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'auto'; };
  }, []);

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onUpdate();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onUpdate();
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado para a área de transferência!');
      }
      updatePostShares(post.id, currentUser.id);
      onUpdate();
    } catch (err) {
      console.log('Share cancelled', err);
    }
  };

  const handleFollow = (e: React.MouseEvent) => {
    e.stopPropagation();
    toggleFollowUser(currentUser.id, post.userId);
    refreshUser();
    onUpdate();
  };

  const handleSendComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentText.trim()) return;

    addPostComment(post.id, {
      id: `comment-${Date.now()}`,
      userId: currentUser.id,
      userName: `${currentUser.firstName} ${currentUser.lastName}`,
      profilePic: currentUser.profilePicture,
      text: commentText,
      timestamp: Date.now()
    });

    setCommentText('');
    onUpdate();
  };

  if (!author) return null;

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return createPortal(
    <div className="fixed inset-0 z-[10000] bg-black/80 flex items-center justify-center animate-fade-in overflow-hidden backdrop-blur-sm">

      <div className="w-full h-full md:h-[95vh] md:max-w-6xl md:rounded-[2.5rem] bg-white dark:bg-black flex flex-col tablet:flex-row overflow-hidden relative shadow-2xl">

        <div className="absolute top-0 left-0 w-full h-16 flex items-center px-4 md:hidden z-[101] bg-white/95 dark:bg-black/95 backdrop-blur-md">
           <button onClick={onClose} className="p-2 -ml-2 text-gray-900 dark:text-white">
             <ArrowLeftIcon className="h-7 w-7" />
           </button>
           <span className="ml-4 font-black text-sm uppercase dark:text-white tracking-widest">Publicação</span>
        </div>

        <button 
          onClick={onClose} 
          className="hidden md:flex absolute top-6 left-6 z-[101] p-3 bg-black/50 hover:bg-black/70 text-white rounded-full transition-all backdrop-blur-sm shadow-xl"
        >
          <XMarkIcon className="h-6 w-6" />
        </button>

        <div className={`w-full tablet:flex-1 bg-black flex items-center justify-center relative overflow-hidden ${!post.imageUrl ? 'hidden tablet:flex' : 'h-[40vh] tablet:h-full mt-16 tablet:mt-0'}`}>
          {post.imageUrl && (
            <img 
              src={post.imageUrl} 
              className="max-w-full max-h-full object-contain" 
              alt="Mídia"
            />
          )}
        </div>

        <div className="flex-1 tablet:w-[480px] flex flex-col h-full bg-white dark:bg-black border-l border-gray-100 dark:border-white/10 relative">

          <div className="p-6 border-b border-gray-50 dark:border-white/10 flex items-center justify-between shrink-0 hidden tablet:flex">
             <div className="flex items-center gap-4 cursor-pointer group" onClick={() => { onClose(); onNavigate('profile', { userId: post.userId }); }}>
                <img src={author.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-[1rem] object-cover border shadow-sm" />
                <div>
                   <div className="flex items-center gap-1.5">
                      <span className="font-black text-sm dark:text-white group-hover:underline">{author.firstName} {author.lastName}</span>
                      {author.userType === UserType.CREATOR && <CheckBadgeIcon className="h-4 w-4 text-blue-500" />}
                   </div>
                   <span className="text-gray-400 text-[10px] font-bold uppercase tracking-widest">@{author.firstName.toLowerCase()}</span>
                </div>
             </div>
             {!isOwner && (
               <button 
                 onClick={handleFollow}
                 className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${isFollowing ? 'border border-gray-300 dark:text-white' : 'bg-blue-600 text-white shadow-lg shadow-blue-100'}`}
               >
                 {isFollowing ? 'Seguindo' : 'Seguir'}
               </button>
             )}
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-6">
             <div className="tablet:hidden flex items-center justify-between mb-4">
                <div className="flex items-center gap-4">
                   <img src={author.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover" />
                   <div className="flex flex-col">
                      <div className="flex items-center gap-1.5">
                         <span className="font-black text-sm dark:text-white">{author.firstName} {author.lastName}</span>
                         {author.userType === UserType.CREATOR && <CheckBadgeIcon className="h-4 w-4 text-blue-500" />}
                      </div>
                      <span className="text-gray-400 text-[10px] font-bold uppercase tracking-widest">@{author.firstName.toLowerCase()}</span>
                   </div>
                </div>
             </div>

             <div 
               className={`p-10 rounded-[2.5rem] space-y-6 shadow-sm flex flex-col items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
               style={{ 
                 backgroundColor: hasBg ? post.backgroundColor : 'transparent',
                 color: post.textColor || 'inherit',
                 fontSize: post.fontSize ? `calc(${post.fontSize} * 1.3)` : '1.2rem',
                 minHeight: hasBg ? '350px' : 'auto',
                 border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)'
               }}
             >
                <p className={`font-bold leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-sm' : 'text-left w-full'}`}>{post.content}</p>
                <div className={`text-[10px] font-black uppercase tracking-widest pt-6 border-t w-full ${hasBg ? 'border-white/10' : 'border-gray-50'}`} style={{ opacity: 0.6 }}>
                   Postado em {new Date(post.timestamp).toLocaleDateString()} às {new Date(post.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
                </div>
             </div>

             <div className="flex items-center justify-between py-4 border-b border-gray-50 dark:border-white/10 text-gray-400">
                <button onClick={handleLike} className={`flex items-center gap-2 group transition-colors ${hasLiked ? 'text-blue-600 font-black' : 'hover:text-blue-600'}`}>
                   <div className={`p-2.5 rounded-xl ${hasLiked ? 'bg-blue-50' : 'group-hover:bg-blue-50'}`}>
                    {hasLiked ? <HeartIconSolid className="h-6 w-6" /> : <HeartIconOutline className="h-6 w-6" />}
                   </div>
                   <span className="text-xs font-black">{post.likes?.length || 0}</span>
                </button>
                <div className="flex items-center gap-2 group hover:text-blue-500 transition-colors">
                   <div className="p-2.5 rounded-xl hover:bg-blue-50">
                    <ChatBubbleOvalLeftIcon className="h-6 w-6" />
                   </div>
                   <span className="text-xs font-black">{post.comments?.length || 0}</span>
                </div>
                <button onClick={handleSave} className={`flex items-center gap-2 group transition-colors ${hasSaved ? 'text-blue-600' : 'hover:text-blue-600'}`}>
                   <div className={`p-2.5 rounded-xl ${hasSaved ? 'bg-blue-50' : 'group-hover:bg-blue-50'}`}>
                    {hasSaved ? <BookmarkIconSolid className="h-6 w-6" /> : <BookmarkIconOutline className="h-6 w-6" />}
                   </div>
                </button>
                <button onClick={handleShare} className="flex items-center gap-2 group hover:text-blue-600 transition-colors">
                   <div className="p-2.5 rounded-xl hover:bg-blue-50">
                    <ShareIcon className="h-6 w-6" />
                   </div>
                   <span className="text-xs font-black">{post.shares?.length || 0}</span>
                </button>
             </div>

             <div className="space-y-6 pt-6 pb-24">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Respostas à Aula</p>
                {post.comments?.map((c) => (
                  <div key={c.id} className="flex gap-4 animate-fade-in group">
                     <img src={c.profilePic || DEFAULT_PROFILE_PIC} className="w-9 h-9 rounded-xl object-cover shrink-0 border" />
                     <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                           <span className="font-black text-[11px] dark:text-white uppercase tracking-tighter">{c.userName}</span>
                           <span className="text-gray-400 text-[9px] font-bold">· {new Date(c.timestamp).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                        </div>
                        <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-2xl rounded-tl-none border border-gray-100 dark:border-white/5">
                           <p className="text-sm dark:text-gray-200 font-medium leading-relaxed">{c.text}</p>
                        </div>
                     </div>
                  </div>
                ))}
             </div>
          </div>

          <div className="absolute bottom-0 left-0 w-full p-4 bg-white dark:bg-black border-t border-gray-100 dark:border-white/10 z-[105]">
             <form onSubmit={handleSendComment} className="flex items-end gap-3 bg-gray-50 dark:bg-white/5 p-3 rounded-[2rem] border border-gray-100 dark:border-white/10 shadow-inner">
                <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover hidden sm:block border" />
                <div className="flex-1 flex items-center gap-3">
                   <textarea 
                    value={commentText}
                    onChange={e => setCommentText(e.target.value)}
                    placeholder="Sua resposta..."
                    className="w-full bg-transparent dark:text-white outline-none resize-none text-sm placeholder-gray-400 py-2 custom-scrollbar max-h-24"
                    rows={1}
                    onInput={(e) => {
                      const target = e.target as HTMLTextAreaElement;
                      target.style.height = 'auto';
                      target.style.height = `${target.scrollHeight}px`;
                    }}
                   />
                   <button 
                     type="submit" 
                     disabled={!commentText.trim()}
                     className="bg-blue-600 disabled:opacity-30 text-white p-3 rounded-2xl shadow-lg active:scale-90 transition-all shrink-0"
                   >
                     <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                   </button>
                </div>
             </form>
             <div className="h-2 md:hidden"></div>
          </div>
        </div>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 0px; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fadeIn 0.2s ease-out forwards; }
      `}</style>
    </div>,
    document.body
  );
};

