  { id: 'font-dancing', label: 'Script' },
  { id: 'font-caveat', label: 'Hand' },
  { id: 'font-pacifico', label: 'Retro' },
  { id: 'font-marker', label: 'Marker' },
  { id: 'font-kalam', label: 'Organic' }
];

const TEXT_COLORS = [
  { id: '#ffffff', label: 'Branco', bg: 'bg-white border' },
  { id: '#000000', label: 'Preto', bg: 'bg-black' },
  { id: '#2563eb', label: 'Azul', bg: 'bg-blue-600' },
  { id: '#7c3aed', label: 'Roxo', bg: 'bg-purple-600' },
  { id: '#dc2626', label: 'Vermelho', bg: 'bg-red-600' },
  { id: '#f59e0b', label: 'Laranja', bg: 'bg-amber-500' },
  { id: '#10b981', label: 'Verde', bg: 'bg-emerald-500' }
];

const BG_COLORS = [
  { id: 'transparent', label: 'Nenhum', bg: 'bg-transparent border-2 border-dashed' },
  { id: '#000000', label: 'Dark', bg: 'bg-black' },
  { id: '#2563eb', label: 'Blue', bg: 'bg-blue-600' },
  { id: '#7c3aed', label: 'Purple', bg: 'bg-purple-600' },
  { id: '#ec4899', label: 'Pink', bg: 'bg-pink-500' },
  { id: '#10b981', label: 'Green', bg: 'bg-emerald-500' },
  { id: '#f59e0b', label: 'Solar', bg: 'bg-amber-500' },
  { id: '#ef4444', label: 'Red', bg: 'bg-red-500' },
  { id: '#f8fafc', label: 'Sky', bg: 'bg-slate-50' }
];

const SIZES = [
  { id: '14px', label: 'S' },
  { id: '18px', label: 'M' },
  { id: '24px', label: 'L' },
  { id: '36px', label: 'XL' },
  { id: '48px', label: 'XXL' }
];

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [liveTitle, setLiveTitle] = useState('');
  const [liveDescription, setLiveDescription] = useState('');
  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('0');
  const [showRecordReel, setShowRecordReel] = useState(false);

  // Estilização
  const [fontFamily, setFontFamily] = useState('font-sans');
  const [textColor, setTextColor] = useState('#000000');
  const [fontSize, setFontSize] = useState('18px');
  const [backgroundColor, setBackgroundColor] = useState('transparent');

  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isEditing = !!postId;
  const isProfessional = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    if (postId) {
      const posts = getPosts();
      const postToEdit = posts.find(p => p.id === postId);
      if (postToEdit) {
        setPostType(postToEdit.type);
        setContent(postToEdit.content || '');
        setImageUrl(postToEdit.imageUrl || '');
        setFontFamily(postToEdit.fontFamily || 'font-sans');
        setTextColor(postToEdit.textColor || '#000000');
        setFontSize(postToEdit.fontSize || '18px');
        setBackgroundColor(postToEdit.backgroundColor || 'transparent');

        if (postToEdit.type === PostType.LIVE && postToEdit.liveStream) {
          setLiveTitle(postToEdit.liveStream.title);
          setLiveDescription(postToEdit.liveStream.description);
          setIsLivePaid(postToEdit.liveStream.isPaid);
          setLivePrice(postToEdit.liveStream.price?.toString() || '0');
        }
      }
    }
  }, [postId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const postData: Post = {
        id: isEditing ? postId! : `post-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: postType,
        timestamp: Date.now(),
        content: postType !== PostType.LIVE ? content : undefined,
        imageUrl: postType === PostType.IMAGE ? imageUrl : undefined,
        fontFamily: postType === PostType.TEXT ? fontFamily : undefined,
        textColor: postType === PostType.TEXT ? textColor : undefined,
        fontSize: postType === PostType.TEXT ? fontSize : undefined,
        backgroundColor: postType === PostType.TEXT ? backgroundColor : undefined,
        liveStream: postType === PostType.LIVE ? {
          title: liveTitle,
          description: liveDescription,
          isPaid: isLivePaid,
          price: isLivePaid ? parseFloat(livePrice) : 0
        } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };

      if (isEditing) updatePost(postData);
      else addPost(postData);

      onPostCreated();
      if (!isEditing) {
        setIsExpanded(false);
        setContent('');
        setImageUrl('');
        setLiveTitle('');
        setLiveDescription('');
        setBackgroundColor('transparent');
        setTextColor('#000000');
        setFontFamily('font-sans');
      }
    } catch (err) {
      alert('Erro ao salvar publicação.');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveReel = (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = () => {
      const videoUrl = reader.result as string;
      const newReel: Post = {
        id: `reel-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: PostType.REEL,
        timestamp: Date.now(),
        reel: {
          videoUrl: videoUrl,
          description: "Novo Reel CyBerPhone! 🚀",
          audioTrackId: audioTrackId,
          aiEffectPrompt: aiPrompt,
          filter: filter
        },
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };
      addPost(newReel);
      setLoading(false);
      setShowRecordReel(false);
      onPostCreated();
    };
    reader.readAsDataURL(videoBlob);
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2rem] shadow-sm p-4 border border-gray-100 dark:border-white/10 flex flex-col gap-3">
         <div className="flex items-start gap-3">
            <img src={currentUser.profilePicture} className="w-10 h-10 rounded-xl object-cover shrink-0" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-4 py-2.5 bg-slate-50 dark:bg-white/5 rounded-xl text-gray-400 font-bold text-xs md:text-sm">
              {isProfessional ? `Olá Profissional, o que temos para a rede hoje?` : `O que você está pensando, ${currentUser.firstName}?`}
            </button>
         </div>
         <div className="flex items-center gap-4 md:gap-6 px-1 border-t border-gray-50 dark:border-white/5 pt-2 overflow-x-auto no-scrollbar">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-2 text-gray-500 hover:text-blue-600 transition-all shrink-0">
               <PhotoIcon className="h-5 w-5 text-blue-500" />
               <span className="text-[10px] font-black uppercase tracking-widest">Mídia</span>
            </button>
            <button onClick={() => setShowRecordReel(true)} className="flex items-center gap-2 text-gray-500 hover:text-purple-600 transition-all shrink-0">
               <FilmIcon className="h-5 w-5 text-purple-500" />
               <span className="text-[10px] font-black uppercase tracking-widest">Gravar Reel</span>
            </button>
            {isProfessional && (
              <button onClick={() => { setIsExpanded(true); setPostType(PostType.LIVE); }} className="flex items-center gap-2 text-gray-500 hover:text-red-600 transition-all shrink-0">
                 <VideoCameraIcon className="h-5 w-5 text-red-500" />
                 <span className="text-[10px] font-black uppercase tracking-widest">Live</span>
              </button>
            )}
         </div>
         {showRecordReel && <RecordReelModal onClose={() => setShowRecordReel(false)} onSave={handleSaveReel} />}
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-2xl p-6 md:p-8 border border-blue-50 dark:border-white/5 animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 left-0 w-2 h-full bg-blue-600"></div>

      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
           <div className={`p-3 text-white rounded-2xl shadow-lg ${postType === PostType.LIVE ? 'bg-red-600' : 'bg-blue-600'}`}>
             {postType === PostType.LIVE ? <VideoCameraIcon className="h-6 w-6" /> : <BriefcaseIcon className="h-6 w-6" />}
           </div>
           <div>
              <h3 className="font-black text-gray-900 dark:text-white uppercase text-[10px] tracking-[0.2em]">{isEditing ? 'Editar Post' : 'Criar Conteúdo'}</h3>
              <p className="text-[8px] text-blue-500 font-black uppercase mt-0.5 tracking-widest">Editor CyBer Pro</p>
           </div>
        </div>
        <button onClick={() => setIsExpanded(false)} className="p-2 text-gray-300 hover:text-red-500 transition-colors"><XMarkIcon className="h-6 w-6" /></button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex flex-wrap gap-2 p-1.5 bg-slate-50 dark:bg-white/5 rounded-2xl w-fit">
           {[
             { id: PostType.TEXT, icon: DocumentTextIcon, label: 'Texto', locked: false },
             { id: PostType.IMAGE, icon: PhotoIcon, label: 'Mídia', locked: false },
             { id: PostType.LIVE, icon: VideoCameraIcon, label: 'Transmissão', locked: !isProfessional }
           ].map(t => (
             <button key={t.id} type="button" disabled={t.locked} onClick={() => setPostType(t.id)} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${postType === t.id ? 'bg-white dark:bg-white/10 text-blue-600 dark:text-white shadow-sm' : 'text-gray-400'} ${t.locked ? 'opacity-30' : ''}`}>
                {t.locked ? <LockClosedIcon className="h-3 w-3" /> : <t.icon className="h-4 w-4" />} {t.label}
             </button>
           ))}
        </div>

        {postType === PostType.TEXT && (
          <div className="space-y-6 animate-fade-in p-5 bg-gray-50 dark:bg-white/5 rounded-[2rem] border border-gray-100 dark:border-white/10">
             <div className="space-y-4">
                {/* Fonte */}
                <div className="space-y-2">
                   <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Tipografia (Script & Manuscritos)</p>
                   <div className="flex flex-wrap gap-1.5 bg-white dark:bg-darkcard p-1.5 rounded-2xl shadow-sm">
                      {FONTS.map(f => (
                        <button 
                          key={f.id} 
                          type="button" 
                          onClick={() => setFontFamily(f.id)} 
                          className={`px-3 py-1.5 rounded-xl text-[10px] font-bold transition-all border ${fontFamily === f.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'text-gray-400 border-transparent hover:bg-gray-50 dark:hover:bg-white/5'}`}
                          style={{ fontFamily: f.id.replace('font-', '') }}
                        >
                          {f.label}
                        </button>
                      ))}
                   </div>
                </div>

                <div className="flex flex-wrap gap-8 items-start">
                  {/* Tamanho */}
                  <div className="space-y-2">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Tamanho</p>
                    <div className="flex gap-1.5 bg-white dark:bg-darkcard p-1.5 rounded-2xl shadow-sm">
                        {SIZES.map(s => (
                          <button key={s.id} type="button" onClick={() => setFontSize(s.id)} className={`w-9 h-9 rounded-xl text-[10px] font-black flex items-center justify-center transition-all ${fontSize === s.id ? 'bg-black text-white' : 'text-gray-400 hover:bg-gray-50'}`}>{s.label}</button>
                        ))}
                    </div>
                  </div>

                  {/* Cores Texto */}
                  <div className="space-y-2">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Cor Texto</p>
                    <div className="flex gap-2 flex-wrap">
                        {TEXT_COLORS.map(c => (
                          <button key={c.id} type="button" onClick={() => setTextColor(c.id)} className={`w-8 h-8 rounded-full transition-all ${c.bg} ${textColor === c.id ? 'ring-2 ring-blue-500 scale-110 shadow-lg' : 'opacity-60 hover:opacity-100'}`} title={c.label}></button>
                        ))}
                    </div>
                  </div>

                  {/* Cor Fundo */}
                  <div className="space-y-2">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Fundo do Card</p>
                    <div className="flex gap-2 flex-wrap">
                        {BG_COLORS.map(c => (
                          <button key={c.id} type="button" onClick={() => setBackgroundColor(c.id)} className={`w-8 h-8 rounded-full transition-all ${c.bg} ${backgroundColor === c.id ? 'ring-2 ring-blue-600 scale-110 shadow-lg' : 'opacity-60 hover:opacity-100'}`} title={c.label}></button>
                        ))}
                    </div>
                  </div>
                </div>
             </div>
          </div>
        )}

        {postType === PostType.LIVE ? (
          <div className="space-y-4 animate-fade-in">
            <input
              type="text"
              value={liveTitle}
              onChange={(e) => setLiveTitle(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-bold text-lg dark:text-white"
              placeholder="Título da Transmissão..."
              required
            />
            <textarea
              value={liveDescription}
              onChange={(e) => setLiveDescription(e.target.value)}
              className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-medium text-base dark:text-white h-32 resize-none"
              placeholder="Descreva o conteúdo desta live..."
            />
          </div>
        ) : (
          <div className="relative group min-h-[350px]">
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className={`w-full p-10 border-4 border-transparent focus:border-blue-500/20 rounded-[2.5rem] outline-none transition-all duration-500 shadow-inner resize-none flex items-center justify-center text-center ${fontFamily}`}
              style={{ 
                color: textColor, 
                fontSize: fontSize,
                backgroundColor: backgroundColor === 'transparent' ? 'transparent' : backgroundColor,
                minHeight: '350px',
                display: backgroundColor !== 'transparent' ? 'flex' : 'block',
                fontFamily: fontFamily.replace('font-', '')
              }}
              placeholder={postType === PostType.IMAGE ? "Legenda da mídia..." : "O que você quer compartilhar hoje?"}
              required
            />

            {postType === PostType.IMAGE && (
              <div className="mt-6 space-y-4 animate-fade-in">
                <input type="file" ref={fileInputRef} onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => setImageUrl(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }} accept="image/*" className="hidden" />
                {!imageUrl ? (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full h-64 border-2 border-dashed border-gray-200 dark:border-white/10 rounded-3xl flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-blue-500 transition-all">
                      <ArrowUpTrayIcon className="h-8 w-8 text-gray-400" />
                      <span className="text-[10px] font-black text-gray-400 uppercase">Fazer Upload</span>
                  </div>
                ) : (
                  <div className="relative rounded-3xl overflow-hidden border-2 border-blue-500">
                      <img src={imageUrl} className="w-full h-auto max-h-[400px] object-cover" />
                      <button onClick={() => setImageUrl('')} className="absolute top-4 right-4 p-2 bg-red-600 text-white rounded-full shadow-lg"><TrashIcon className="h-5 w-5"/></button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        <div className="flex justify-end pt-6 border-t dark:border-white/5">
           <button 
              type="submit" 
              disabled={loading || (!content && !liveTitle)} 
              className="bg-blue-600 text-white px-12 py-5 rounded-[1.8rem] font-black text-sm uppercase shadow-[0_20px_40px_rgba(37,99,235,0.4)] hover:bg-blue-700 active:scale-95 transition-all flex items-center gap-3"
           >
              {loading ? 'Postando...' : isEditing ? 'Atualizar' : 'Publicar Agora'} <ChevronRightIcon className="h-5 w-5" />
           </button>
        </div>
      </form>
    </div>
  );
};

export default CreatePost;

import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType, Comment } from '../types';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  updatePostSaves, 
  deletePost, 
  pinPost,
  unpinPost
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  TrashIcon, 
  CheckBadgeIcon,
  FlagIcon,
  PaperAirplaneIcon,
  MapPinIcon as PinIconOutline,
  VideoCameraIcon,
  SignalIcon,
  ArrowsPointingOutIcon,
  ShareIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  PlayIcon
} from '@heroicons/react/24/solid';
import IndicateModal from './IndicateModal';
import PostDetailModal from './PostDetailModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
  onPinToggle
}) => {
  if (!post || !currentUser || !post.id) return null;

  const postAuthor = findUserById(post.userId);
  const [showOptions, setShowOptions] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);

  const optionsRef = useRef<HTMLDivElement>(null);
  const hasLiked = post.likes?.includes(currentUser.id) || false;
  const hasSaved = post.saves?.includes(currentUser.id) || false;
  const isAuthor = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId) || false;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (optionsRef.current && !optionsRef.current.contains(event.target as Node)) setShowOptions(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado para a área de transferência!');
      }
      updatePostShares(post.id, currentUser.id);
      onPostUpdatedOrDeleted();
    } catch (err) {
      console.log('Share cancelled or failed', err);
    }
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('Excluir esta publicação?')) {
      deletePost(post.id);
      onPostUpdatedOrDeleted();
    }
  };

  const handlePin = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (post.isPinned) unpinPost(post.id, currentUser.id);
    else pinPost(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
    setShowOptions(false);
  };

  const handleCardClick = () => {
    if (post.type === PostType.LIVE) {
        onNavigate('live', { postId: post.id });
    } else {
        setShowDetailModal(true);
    }
  };

  if (!postAuthor) return null;

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={handleCardClick}
        className={`bg-white dark:bg-darkcard rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-4 transition-all hover:shadow-md animate-fade-in cursor-pointer group`}
      >

        {/* HEADER */}
        <div className="p-4 md:p-6 flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-4">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-xl object-cover shadow-sm" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1 -right-1 bg-blue-600 rounded-lg p-0.5 border-2 border-white dark:border-darkcard">
                  <CheckBadgeIcon className="h-3 w-3 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-1">
                <h4 className="font-black text-gray-900 dark:text-white text-sm md:text-base truncate leading-tight hover:underline cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
                    {postAuthor.firstName}
                </h4>
                {post.isPinned && <PinIconSolid className="h-3.5 w-3.5 text-blue-500 shrink-0" />}
              </div>
              <p className="text-[8px] md:text-[10px] font-bold text-gray-400 uppercase tracking-widest">{new Date(post.timestamp).toLocaleDateString()}</p>
            </div>
          </div>

          <div className="relative" ref={optionsRef}>
            <button onClick={(e) => { e.stopPropagation(); setShowOptions(!showOptions); }} className="p-2 text-gray-300 hover:text-blue-600 transition-colors">
              <EllipsisHorizontalIcon className="h-6 w-6" />
            </button>
            {showOptions && (
              <div className="absolute right-0 mt-1 w-48 bg-white dark:bg-darkcard rounded-2xl shadow-2xl py-2 z-20 border dark:border-white/10 animate-fade-in" onClick={e => e.stopPropagation()}>
                {isAuthor ? (
                  <>
                    <button onClick={handlePin} className="flex items-center w-full px-4 py-3 text-[10px] font-black text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-white/5">
                      {post.isPinned ? <><PinIconSolid className="h-4 w-4 mr-3 text-blue-500" /> Desafixar</> : <><PinIconOutline className="h-4 w-4 mr-3 text-blue-500" /> Fixar</>}
                    </button>
                    <button onClick={handleDelete} className="flex items-center w-full px-4 py-3 text-[10px] font-black text-red-600 hover:bg-red-50 dark:hover:bg-red-900/10">
                      <TrashIcon className="h-4 w-4 mr-3" /> Excluir
                    </button>
                  </>
                ) : (
                  <>
                    {!isFollowing && (
                      <button onClick={(e) => { e.stopPropagation(); onFollowToggle(post.userId); setShowOptions(false); }} className="flex items-center w-full px-4 py-3 text-[10px] font-black text-blue-600 hover:bg-blue-50 dark:hover:bg-red-900/10">
                        Seguir Professor
                      </button>
                    )}
                    <button onClick={(e) => { e.stopPropagation(); onNavigate('report-user', { userId: post.userId }); }} className="flex items-center w-full px-4 py-3 text-[10px] font-black text-orange-600 hover:bg-orange-50">
                      <FlagIcon className="h-4 w-4 mr-3" /> Denunciar
                    </button>
                  </>
                )}
              </div>
            )}
          </div>
        </div>

        {/* CONTENT */}
        <div className="px-4 md:px-6 pb-4 md:pb-6">
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden bg-gray-900 text-white p-6 md:p-12 relative shadow-2xl border-4 border-blue-600/30">
                <div className="absolute top-4 left-4 z-10">
                   <div className="bg-red-600 px-3 py-1 rounded text-[8px] md:text-[10px] font-black flex items-center gap-2 shadow-lg animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3 w-3" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-10 md:py-16 flex flex-col items-center text-center">
                   <div className="w-16 h-16 md:w-24 md:h-24 bg-blue-600/20 rounded-[2rem] flex items-center justify-center mb-6 border border-blue-500/30">
                      <VideoCameraIcon className="h-8 w-8 md:h-12 md:w-12 text-blue-400" />
                   </div>
                   <h3 className="text-xl md:text-3xl font-black mb-4 tracking-tighter leading-tight uppercase line-clamp-2">{post.liveStream.title}</h3>
                   <button 
                      onClick={(e) => { e.stopPropagation(); onNavigate('live', { postId: post.id }); }}
                      className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 md:px-12 md:py-5 rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-[0.1em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
                   >
                      <PlayIcon className="h-4 w-4 md:h-6 md:w-6" /> Entrar na Aula
                   </button>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`p-8 md:p-14 rounded-[2rem] md:rounded-[3.5rem] mb-4 transition-all duration-500 group-hover:scale-[1.005] flex items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    backgroundColor: hasBg ? post.backgroundColor : 'transparent',
                    color: post.textColor || 'inherit',
                    fontSize: post.fontSize || 'inherit',
                    minHeight: hasBg ? '280px' : 'auto',
                    border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
                    fontFamily: post.fontFamily?.replace('font-', '')
                  }}
                >
                  <p className={`font-bold leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-md' : 'text-left w-full'}`}>{post.content}</p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-sm">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[600px]" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        {/* ACTIONS */}
        <div className="px-4 md:px-8 py-3 md:py-4 flex items-center justify-between border-t dark:border-white/5">
          <div className="flex items-center gap-1 md:gap-3">
            <button onClick={handleLike} className={`flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl transition-all active:scale-90 ${hasLiked ? 'text-blue-600 bg-blue-50 dark:bg-blue-500/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {hasLiked ? <HeartIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <HeartIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
              <span className="text-xs md:text-sm font-black">{post.likes?.length || 0}</span>
            </button>

            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ChatIconOutline className="h-5 w-5 md:h-6 md:w-6" />
              <span className="font-black text-xs md:text-sm">{post.comments?.length || 0}</span>
            </button>

            <button onClick={handleShare} className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ShareIcon className="h-5 w-5 md:h-6 md:w-6" />
            </button>
          </div>

          <button onClick={handleSave} className={`p-2.5 rounded-xl transition-all ${hasSaved ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/20' : 'text-gray-300 hover:bg-gray-50'}`}>
            {hasSaved ? <BookmarkIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <BookmarkIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
          </button>
        </div>
      </div>

      {showDetailModal && (
        <PostDetailModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowDetailModal(false)}
          onUpdate={onPostUpdatedOrDeleted}
          onNavigate={onNavigate}
          refreshUser={refreshUser}
        />
      )}

      {showIndicateModal && (
        <IndicateModal 
          post={post} 
          currentUser={currentUser} 
          onClose={() => setShowIndicateModal(false)} 
          onPostUpdated={onPostUpdatedOrDeleted}
        />
      )}
    </>
  );
};

