export const findStoreById = (id: string) => getStores().find(s => s.id === id);
export const findProductById = (id: string) => getProducts().find(p => p.id === id);

export const updateStore = (updatedStore: Store) => {
  set(KEYS.STORES, getStores().map(s => s.id === updatedStore.id ? updatedStore : s));
};

export const getCart = (): CartItem[] => get(KEYS.CART, []);
export const addToCart = (pId: string, q = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(item => item.productId === pId && item.selectedColor === selectedColor);
  if (existing) {
    existing.quantity += q;
  } else {
    cart.push({ productId: pId, quantity: q, selectedColor });
  }
  set(KEYS.CART, cart);
};
export const removeFromCart = (productId: string) => {
  set(KEYS.CART, getCart().filter(item => item.productId !== productId));
};
export const updateCartItemQuantity = (productId: string, quantity: number) => {
  const cart = getCart();
  const item = cart.find(i => i.productId === productId);
  if (item) {
    item.quantity = quantity;
    if (item.quantity <= 0) {
      set(KEYS.CART, cart.filter(i => i.productId !== productId));
    } else {
      set(KEYS.CART, cart);
    }
  }
};
export const clearCart = () => set(KEYS.CART, []);

export const getNotificationsForUser = (uId: string) => get<any[]>(KEYS.NOTIFICATIONS, []).filter(n => n.recipientId === uId);
export const markNotificationsAsRead = (uId: string) => set(KEYS.NOTIFICATIONS, get<any[]>(KEYS.NOTIFICATIONS, []).map(n => n.recipientId === uId ? { ...n, isRead: true } : n));

export const buyPremiumSubscription = (userId: string) => {
  const cost = 29.90;
  const user = findUserById(userId);
  if (user && (user.balance || 0) >= cost) {
    updateUserBalance(userId, -cost);
    addPlatformRevenue(cost);
    user.isPremium = true;
    user.isVerified = true;
    updateUser(user);
    return true;
  }
  return false;
};

export const getAds = (): AdCampaign[] => get(KEYS.ADS, []);
export const saveAds = (ads: AdCampaign[]) => set(KEYS.ADS, ads);
export const getAudioTracks = (): AudioTrack[] => get(KEYS.AUDIO, DEFAULT_AUDIO_TRACKS);
export const findAudioTrackById = (id: string) => getAudioTracks().find(t => t.id === id);
