export const addStory = (uId: string, item: Partial<StoryItem>) => {
  const stories = getStories();
  let userStory = stories.find(s => s.userId === uId);
  const newItem: StoryItem = {
    id: `si-${Date.now()}`,
    timestamp: Date.now(),
    ...item
  };
  if (userStory) {
    userStory.items.push(newItem);
  } else {
    const user = findUserById(uId);
    stories.push({
      userId: uId,
      userName: user ? `${user.firstName} ${user.lastName}` : 'Usuário',
      userProfilePic: user?.profilePicture,
      items: [newItem]
    });
  }
  set(KEYS.STORIES, stories);
};
export const getChats = (): ChatConversation[] => get(KEYS.CHATS, []);
export const saveChats = (chats: ChatConversation[]) => set(KEYS.CHATS, chats);

export const toggleFollowUser = (cId: string, fId: string) => {
  const users = getUsers();
  const u1 = users.find(u => u.id === cId);
  const u2 = users.find(u => u.id === fId);
  if (u1 && u2) {
    if (u1.followedUsers.includes(fId)) u1.followedUsers = u1.followedUsers.filter(x => x !== fId);
    else u1.followedUsers.push(fId);
    set(KEYS.USERS, users);
  }
};

export const processProductPurchase = (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null = null, shippingAddress?: ShippingAddress) => {
  const products = getProducts();
  const settings = getGlobalSettings();
  const sales = get<AffiliateSale[]>(KEYS.SALES, []);
  for (const item of cartItems) {
    const product = products.find(p => p.id === item.productId);
    if (product) {
      const store = findStoreById(product.storeId);
      if (store) {
        const total = product.price * item.quantity;
        const tax = total * settings.platformTax;
        updateUserBalance(store.professorId, total - tax);
        addPlatformRevenue(tax);
        sales.push({
           id: `sale-${Date.now()}-${item.productId}`,
           productId: item.productId,
           buyerId,
           affiliateUserId: affiliateUserId || '',
           storeId: product.storeId,
           commissionEarned: 0,
           saleAmount: total,
           timestamp: Date.now(),
           status: OrderStatus.DELIVERED,
           shippingAddress
        });
      }
    }
  }
  set(KEYS.SALES, sales);
  clearCart();
  return true;
};

export const getPurchasesByBuyerId = (uId: string) => get<any[]>(KEYS.SALES, []).filter(s => s.buyerId === uId);
export const getSalesByAffiliateId = (uId: string) => get<any[]>(KEYS.SALES, []).filter(s => s.affiliateUserId === uId);
export const getSalesByStoreId = (sId: string) => get<any[]>(KEYS.SALES, []).filter(s => s.storeId === sId);

export const addPostComment = (pId: string, c: Comment) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === pId);
  if (post) {
    post.comments.push(c);
    set(KEYS.POSTS, posts);
  }
  return [];
};

export const saveAffiliateLink = (uId: string, pId: string, link: string) => {
  console.log(`Link de afiliado salvo para ${uId}: ${link}`);
};
export const addProductRating = (saleId: string, rating: number, comment: string) => {
  const sales = get<AffiliateSale[]>(KEYS.SALES, []);
  const sale = sales.find(s => s.id === saleId);
  if (sale) {
    sale.isRated = true;
    set(KEYS.SALES, sales);
    const products = getProducts();
    const product = products.find(p => p.id === sale.productId);
    if (product) {
      const newRating: ProductRating = { id: `rating-${Date.now()}`, saleId, userId: sale.buyerId, rating, comment, timestamp: Date.now() };
      product.ratings.push(newRating);
      product.ratingCount = product.ratings.length;
      product.averageRating = product.ratings.reduce((a, b) => a + b.rating, 0) / product.ratingCount;
      set(KEYS.PRODUCTS, products);
    }
  }
};
export const getEvents = (): CyberEvent[] => get(KEYS.EVENTS, []);
export const createEvent = (evt: CyberEvent) => set(KEYS.EVENTS, [evt, ...getEvents()]);
export const toggleJoinEvent = (eId: string, uId: string) => {
  const events = getEvents();
  const evt = events.find(e => e.id === eId);
  if (evt) {
    if (evt.attendees.includes(uId)) evt.attendees = evt.attendees.filter(id => id !== uId);
    else evt.attendees.push(uId);
    set(KEYS.EVENTS, events);
  }
};
