export const indicatePostToUser = (pId: string, aId: string, tId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === pId);
  if (post) {
    if (!post.indicatedUserIds) post.indicatedUserIds = [];
    if (!post.indicatedUserIds.includes(tId)) {
      post.indicatedUserIds.push(tId);
      set(KEYS.POSTS, posts);
      return true;
    }
  }
  return false;
};

