             </div>
           )}

           <button 
             onClick={handleBoost}
             disabled={loading || !hasBalance}
             className={`w-full py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3 ${loading || !hasBalance ? 'bg-gray-200 text-gray-400' : 'bg-blue-600 text-white hover:bg-blue-700'}`}
           >
              {loading ? <div className="w-5 h-5 border-2 border-white border-t-transparent animate-spin rounded-full"></div> : <><BoltIcon className="h-5 w-5" /> Ativar Impulsionamento Agora</>}
           </button>
        </div>
      </div>
    </div>
  );
};

export default BoostPostModal;

import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType, Comment } from '../types';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  updatePostSaves, 
  deletePost, 
  pinPost,
  unpinPost
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  TrashIcon, 
  CheckBadgeIcon,
  FlagIcon,
  PaperAirplaneIcon,
  MapPinIcon as PinIconOutline,
  VideoCameraIcon,
  SignalIcon,
  ArrowsPointingOutIcon,
  ShareIcon,
  RocketLaunchIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  PlayIcon,
  BoltIcon
} from '@heroicons/react/24/solid';
import IndicateModal from './IndicateModal';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
  onPinToggle
}) => {
  if (!post || !currentUser || !post.id) return null;

  const postAuthor = findUserById(post.userId);
  const [showOptions, setShowOptions] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);

  const optionsRef = useRef<HTMLDivElement>(null);
  const hasLiked = post.likes?.includes(currentUser.id) || false;
  const hasSaved = post.saves?.includes(currentUser.id) || false;
  const isAuthor = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId) || false;

  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (optionsRef.current && !optionsRef.current.contains(event.target as Node)) setShowOptions(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado para a área de transferência!');
      }
      updatePostShares(post.id, currentUser.id);
      onPostUpdatedOrDeleted();
    } catch (err) {
      console.log('Share cancelled or failed', err);
    }
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('Excluir esta publicação?')) {
      deletePost(post.id);
      onPostUpdatedOrDeleted();
    }
  };

  const handlePin = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (post.isPinned) unpinPost(post.id, currentUser.id);
    else pinPost(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
    setShowOptions(false);
  };

  const handleCardClick = () => {
    if (post.type === PostType.LIVE) {
        onNavigate('live', { postId: post.id });
    } else {
        setShowDetailModal(true);
    }
  };

  if (!postAuthor) return null;

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={handleCardClick}
        className={`bg-white dark:bg-darkcard rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-4 transition-all hover:shadow-md animate-fade-in cursor-pointer group`}
      >

        {/* HEADER */}
        <div className="p-4 md:p-6 flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-4">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-xl object-cover shadow-sm" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1 -right-1 bg-blue-600 rounded-lg p-0.5 border-2 border-white dark:border-darkcard">
                  <CheckBadgeIcon className="h-3 w-3 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-1">
                <h4 className="font-black text-gray-900 dark:text-white text-sm md:text-base truncate leading-tight hover:underline cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
                    {postAuthor.firstName}
                </h4>
                {post.isPinned && <PinIconSolid className="h-3.5 w-3.5 text-blue-500 shrink-0" />}
                {isPostBoosted && <BoltIcon className="h-3.5 w-3.5 text-orange-500 animate-pulse shrink-0" title="Impulsionado" />}
              </div>
              <p className="text-[8px] md:text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-2 text-blue-600 font-black">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {isAuthor && !isPostBoosted && (
               <button 
                 onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); }}
                 className="hidden md:flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
               >
                 <RocketLaunchIcon className="h-4 w-4" /> Impulsionar
               </button>
            )}

            <div className="relative" ref={optionsRef}>
              <button onClick={(e) => { e.stopPropagation(); setShowOptions(!showOptions); }} className="p-2 text-gray-300 hover:text-blue-600 transition-colors">
                <EllipsisHorizontalIcon className="h-6 w-6" />
              </button>
              {showOptions && (
                <div className="absolute right-0 mt-1 w-48 bg-white dark:bg-darkcard rounded-2xl shadow-2xl py-2 z-20 border dark:border-white/10 animate-fade-in" onClick={e => e.stopPropagation()}>
                  {isAuthor ? (
                    <>
                      <button onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); setShowOptions(false); }} className="md:hidden flex items-center w-full px-4 py-3 text-[10px] font-black text-blue-600 hover:bg-blue-50">
                        <RocketLaunchIcon className="h-4 w-4 mr-3" /> Impulsionar Post
                      </button>
                      <button onClick={handlePin} className="flex items-center w-full px-4 py-3 text-[10px] font-black text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-white/5">
                        {post.isPinned ? <><PinIconSolid className="h-4 w-4 mr-3 text-blue-500" /> Desafixar</> : <><PinIconOutline className="h-4 w-4 mr-3 text-blue-500" /> Fixar</>}
                      </button>
                      <button onClick={handleDelete} className="flex items-center w-full px-4 py-3 text-[10px] font-black text-red-600 hover:bg-red-50 dark:hover:bg-red-900/10">
                        <TrashIcon className="h-4 w-4 mr-3" /> Excluir
                      </button>
                    </>
                  ) : (
                    <>
                      {!isFollowing && (
                        <button onClick={(e) => { e.stopPropagation(); onFollowToggle(post.userId); setShowOptions(false); }} className="flex items-center w-full px-4 py-3 text-[10px] font-black text-blue-600 hover:bg-blue-50 dark:hover:bg-red-900/10">
                          Seguir Professor
                        </button>
                      )}
                      <button onClick={(e) => { e.stopPropagation(); onNavigate('report-user', { userId: post.userId }); }} className="flex items-center w-full px-4 py-3 text-[10px] font-black text-orange-600 hover:bg-orange-50">
                        <FlagIcon className="h-4 w-4 mr-3" /> Denunciar
                      </button>
                    </>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* CONTENT */}
        <div className="px-4 md:px-6 pb-4 md:pb-6">
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden bg-gray-900 text-white p-6 md:p-12 relative shadow-2xl border-4 border-blue-600/30">
                <div className="absolute top-4 left-4 z-10">
                   <div className="bg-red-600 px-3 py-1 rounded text-[8px] md:text-[10px] font-black flex items-center gap-2 shadow-lg animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3 w-3" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-10 md:py-16 flex flex-col items-center text-center">
                   <div className="w-16 h-16 md:w-24 md:h-24 bg-blue-600/20 rounded-[2rem] flex items-center justify-center mb-6 border border-blue-500/30">
                      <VideoCameraIcon className="h-8 w-8 md:h-12 md:w-12 text-blue-400" />
                   </div>
                   <h3 className="text-xl md:text-3xl font-black mb-4 tracking-tighter leading-tight uppercase line-clamp-2">{post.liveStream.title}</h3>
                   <button 
                      onClick={(e) => { e.stopPropagation(); onNavigate('live', { postId: post.id }); }}
                      className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 md:px-12 md:py-5 rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-[0.1em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
                   >
                      <PlayIcon className="h-4 w-4 md:h-6 md:w-6" /> Entrar na Aula
                   </button>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`p-8 md:p-14 rounded-[2rem] md:rounded-[3.5rem] mb-4 transition-all duration-500 group-hover:scale-[1.005] flex items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    backgroundColor: hasBg ? post.backgroundColor : 'transparent',
                    color: post.textColor || 'inherit',
                    fontSize: post.fontSize || 'inherit',
                    minHeight: hasBg ? '280px' : 'auto',
                    border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
                    fontFamily: post.fontFamily?.replace('font-', '')
                  }}
                >
                  <p className={`font-bold leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-md' : 'text-left w-full'}`}>{post.content}</p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-sm">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[600px]" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        {/* ACTIONS */}
        <div className="px-4 md:px-8 py-3 md:py-4 flex items-center justify-between border-t dark:border-white/5">
          <div className="flex items-center gap-1 md:gap-3">
            <button onClick={handleLike} className={`flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl transition-all active:scale-90 ${hasLiked ? 'text-blue-600 bg-blue-50 dark:bg-blue-500/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {hasLiked ? <HeartIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <HeartIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
              <span className="text-xs md:text-sm font-black">{post.likes?.length || 0}</span>
            </button>

            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ChatIconOutline className="h-5 w-5 md:h-6 md:w-6" />
              <span className="font-black text-xs md:text-sm">{post.comments?.length || 0}</span>
            </button>

            <button onClick={handleShare} className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ShareIcon className="h-5 w-5 md:h-6 md:w-6" />
            </button>
          </div>

          <button onClick={handleSave} className={`p-2.5 rounded-xl transition-all ${hasSaved ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/20' : 'text-gray-300 hover:bg-gray-50'}`}>
            {hasSaved ? <BookmarkIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <BookmarkIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
          </button>
        </div>
      </div>

      {showDetailModal && (
        <PostDetailModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowDetailModal(false)}
          onUpdate={onPostUpdatedOrDeleted}
          onNavigate={onNavigate}
          refreshUser={refreshUser}
        />
      )}

      {showBoostModal && (
        <BoostPostModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowBoostModal(false)}
          onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }}
        />
      )}

      {showIndicateModal && (
        <IndicateModal 
          post={post} 
          currentUser={currentUser} 
          onClose={() => setShowIndicateModal(false)} 
          onPostUpdated={onPostUpdatedOrDeleted}
        />
      )}
    </>
  );
};

export default PostCard;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Post, AdCampaign, PostType, Story, UserType, CyberEvent } from '../types';
import { getPosts, getAds, getStories, getUsers, toggleFollowUser, getEvents } from '../services/storageService';
import { DEFAULT_PROFILE_PIC, CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../constants';
import PostCard from './PostCard';
import CreatePost from './CreatePost';
import AdCard from './AdCard';
import StoryViewerModal from './StoryViewerModal';
import CreateStoryModal from './CreateStoryModal';
import { 
  PlusIcon, ArrowPathIcon, UserPlusIcon, CheckBadgeIcon, SparklesIcon, CalendarIcon, VideoCameraIcon, BookmarkSquareIcon, FireIcon, RocketLaunchIcon, UserGroupIcon, WalletIcon, MegaphoneIcon, ArrowTrendingUpIcon
} from '@heroicons/react/24/outline';
import { TrophyIcon } from '@heroicons/react/24/solid';

interface FeedPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const ITEMS_PER_PAGE = 5;

const FeedPage: React.FC<FeedPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [allItems, setAllItems] = useState<(Post | AdCampaign | { type: 'SUGGESTIONS' })[]>([]);
  const [visibleItems, setVisibleItems] = useState<(Post | AdCampaign | { type: 'SUGGESTIONS' })[]>([]);
  const [displayLimit, setDisplayLimit] = useState(ITEMS_PER_PAGE);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [suggestedUsers, setSuggestedUsers] = useState<User[]>([]);
  const [stories, setStories] = useState<Story[]>([]);
  const [upcomingEvents, setUpcomingEvents] = useState<CyberEvent[]>([]);
  const [sidebarAds, setSidebarAds] = useState<AdCampaign[]>([]);

  const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
  const [isCreatingStory, setIsCreatingStory] = useState(false);

  const observerTarget = useRef<HTMLDivElement>(null);

  const loadData = useCallback(() => {
    setLoading(true);
    const allPosts = getPosts()
      .filter(p => p && typeof p === 'object' && p.userId)
      .sort((a, b) => {
        // PRIORIDADES: 1. Pinned | 2. Boosted (Ativo) | 3. Timestamp
        const aBoosted = a.isBoosted && a.boostExpires && a.boostExpires > Date.now();
        const bBoosted = b.isBoosted && b.boostExpires && b.boostExpires > Date.now();

        if (a.isPinned && !b.isPinned) return -1;
        if (!a.isPinned && b.isPinned) return 1;

        if (aBoosted && !bBoosted) return -1;
        if (!aBoosted && bBoosted) return 1;

        return b.timestamp - a.timestamp;
    });
    const allAds = getAds().filter(a => a.isActive);
    const allUsers = getUsers();
    const allStories = getStories();
    const allEvents = getEvents().filter(e => e.dateTime > Date.now()).slice(0, 3);

    setStories(allStories);
    setUpcomingEvents(allEvents);
    setSidebarAds(allAds.slice(0, 2));

    const suggestions = allUsers
      .filter(u => u && u.id !== currentUser.id && !currentUser.followedUsers?.includes(u.id))
      .sort(() => 0.5 - Math.random())
      .slice(0, 8);

    setSuggestedUsers(suggestions);

    let combined: (Post | AdCampaign | { type: 'SUGGESTIONS' })[] = [];
    allPosts.forEach((post, idx) => {
        combined.push(post);
        if (idx === 1 && suggestions.length > 0) combined.push({ type: 'SUGGESTIONS' });
        if ((idx + 1) % 4 === 0 && allAds.length > 0) {
            const adIndex = Math.floor((idx / 4) % allAds.length);
            const ad = allAds[adIndex];
            if (ad) combined.push(ad);
        }
    });

    setAllItems(combined);
    setVisibleItems(combined.slice(0, ITEMS_PER_PAGE));
    setLoading(false);
  }, [currentUser]);

  useEffect(() => { loadData(); }, [loadData]);

  const loadMoreItems = useCallback(() => {
    if (loadingMore || visibleItems.length >= allItems.length) return;
    setLoadingMore(true);
    setTimeout(() => {
      const nextLimit = displayLimit + ITEMS_PER_PAGE;
      setDisplayLimit(nextLimit);
      setVisibleItems(allItems.slice(0, nextLimit));
      setLoadingMore(false);
    }, 1200);
  }, [displayLimit, allItems, loadingMore, visibleItems.length]);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && !loading && !loadingMore) loadMoreItems();
    }, { threshold: 0.1 });
    if (observerTarget.current) observer.observe(observerTarget.current);
    return () => observer.disconnect();
  }, [loading, loadingMore, loadMoreItems]);

  const followerCount = currentUser.followers?.length || 0;
  const progressPercent = Math.min((followerCount / CREATOR_UPGRADE_FOLLOWERS_GOAL) * 100, 100);

  return (
    <div className="w-full max-w-[1400px] mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-8">

      {/* Botão de Impulsionar Flutuante para Mobile */}
      <button 
        onClick={() => onNavigate('ads')}
        className="md:hidden fixed bottom-20 right-6 z-50 bg-blue-600 text-white p-4 rounded-2xl shadow-[0_15px_30px_rgba(37,99,235,0.4)] animate-bounce active:scale-95 transition-all"
      >
        <RocketLaunchIcon className="h-7 w-7" />
      </button>

      {/* Stories Section */}
      <section className="mb-8 bg-white dark:bg-[#1a1c23] rounded-[2.5rem] p-4 shadow-sm border border-gray-100 dark:border-white/5 relative overflow-hidden">
        <div className="flex gap-5 overflow-x-auto pb-2 no-scrollbar scroll-smooth">
          <div onClick={() => setIsCreatingStory(true)} className="flex-shrink-0 flex flex-col items-center gap-2 cursor-pointer group">
            <div className="relative p-1 rounded-[1.8rem] border-2 border-dashed border-blue-500 group-hover:bg-blue-50 transition-all">
              <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-14 h-14 md:w-16 md:h-16 rounded-[1.4rem] object-cover" />
              <div className="absolute -bottom-1 -right-1 bg-blue-600 text-white rounded-lg p-1 border-2 border-white dark:border-[#1a1c23] shadow-lg">
                <PlusIcon className="w-3 h-3 stroke-[4]" />
              </div>
            </div>
            <span className="text-[9px] font-black dark:text-gray-400 uppercase tracking-widest">History</span>
          </div>
          {stories.map((s, i) => (
            <div key={i} onClick={() => setSelectedStoryIndex(i)} className="flex-shrink-0 flex flex-col items-center gap-2 cursor-pointer">
              <div className="p-1 rounded-[1.8rem] bg-gradient-to-tr from-blue-500 via-purple-500 to-red-500">
                <div className="p-0.5 bg-white dark:bg-[#1a1c23] rounded-[1.4rem]">
                  <img src={s.userProfilePic || DEFAULT_PROFILE_PIC} className="w-14 h-14 md:w-16 md:h-16 rounded-[1.2rem] object-cover" />
                </div>
              </div>
              <span className="text-[9px] font-black dark:text-gray-400 truncate w-14 text-center">{s.userName.split(' ')[0]}</span>
            </div>
          ))}
        </div>
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Main Content Area */}
        <main className="lg:col-span-8 space-y-8">
          <CreatePost currentUser={currentUser} onPostCreated={loadData} refreshUser={refreshUser} />

          <div className="space-y-8">
            {loading ? (
              <div className="py-20 text-center"><div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto"></div></div>
            ) : (
              <>
                {visibleItems.map((item, idx) => {
                  if ('authorName' in item) {
                    return <PostCard key={(item as Post).id} post={item as Post} currentUser={currentUser} onNavigate={onNavigate} onFollowToggle={() => {}} refreshUser={refreshUser} onPostUpdatedOrDeleted={loadData} onPinToggle={() => {}} />;
                  }
                  if ('professorId' in item) {
                    return <AdCard key={(item as AdCampaign).id} ad={item as AdCampaign} />;
                  }
                  if ('type' in item && item.type === 'SUGGESTIONS') {
                    return (
                      <div key="sugg" className="bg-gradient-to-br from-indigo-600 to-blue-800 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden">
                         <SparklesIcon className="absolute -right-10 -bottom-10 w-72 h-72 opacity-10" />
                         <div className="flex items-center justify-between mb-8">
                            <div>
                               <h4 className="font-black text-2xl tracking-tighter flex items-center gap-3"><FireIcon className="h-8 w-8 text-yellow-400" /> Networking</h4>
                               <p className="text-blue-100 text-xs font-bold uppercase tracking-widest">Sugestões de Conexão CyBer</p>
                            </div>
                            <button className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all"><ArrowPathIcon className="h-6 w-6"/></button>
                         </div>
                         <div className="flex gap-5 overflow-x-auto pb-4 no-scrollbar">
                            {suggestedUsers.map(u => (
                              <div key={u.id} className="bg-white/10 backdrop-blur-xl p-6 rounded-[2.5rem] min-w-[180px] flex flex-col items-center text-center border border-white/10 group">
                                 <img src={u.profilePicture} className="w-20 h-20 rounded-2xl object-cover mb-3 border-2 border-white/20 shadow-xl group-hover:scale-110 transition-transform" />
                                 <p className="font-black text-sm truncate w-full">{u.firstName} {u.lastName}</p>
                                 <p className="text-[8px] font-black text-blue-200 uppercase mb-4 tracking-tighter">{u.credentials || 'Especialista'}</p>
                                 <button onClick={() => { toggleFollowUser(currentUser.id, u.id); refreshUser(); }} className="w-full bg-white text-blue-800 py-2.5 rounded-xl font-black text-[9px] uppercase shadow-lg active:scale-95 transition-all">Seguir</button>
                              </div>
