export default PostActionsModal;

import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType, Comment } from '../types';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  updatePostSaves, 
  deletePost, 
  pinPost,
  unpinPost
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  TrashIcon, 
  CheckBadgeIcon,
  FlagIcon,
  PaperAirplaneIcon,
  MapPinIcon as PinIconOutline,
  VideoCameraIcon,
  SignalIcon,
  ArrowsPointingOutIcon,
  ShareIcon,
  RocketLaunchIcon,
  PencilSquareIcon,
  UserPlusIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  PlayIcon,
  BoltIcon
} from '@heroicons/react/24/solid';
import IndicateModal from './IndicateModal';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
  onPinToggle
}) => {
  if (!post || !currentUser || !post.id) return null;

  const postAuthor = findUserById(post.userId);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const hasLiked = post.likes?.includes(currentUser.id) || false;
  const hasSaved = post.saves?.includes(currentUser.id) || false;
  const isAuthor = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId) || false;

  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado para a área de transferência!');
      }
      updatePostShares(post.id, currentUser.id);
      onPostUpdatedOrDeleted();
    } catch (err) {
      console.log('Share cancelled', err);
    }
  };

  const confirmDelete = () => {
    setIsDeleting(true);
    setTimeout(() => {
      deletePost(post.id);
      setIsDeleting(false);
      setShowDeleteModal(false);
      onPostUpdatedOrDeleted();
    }, 1000);
  };

  const handlePin = () => {
    if (post.isPinned) unpinPost(post.id, currentUser.id);
    else pinPost(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
    setShowActionsModal(false);
  };

  const handleCardClick = () => {
    if (post.type === PostType.LIVE) {
        onNavigate('live', { postId: post.id });
    } else {
        setShowDetailModal(true);
    }
  };

  if (!postAuthor) return null;

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={handleCardClick}
        className={`bg-white dark:bg-darkcard rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-4 transition-all hover:shadow-md animate-fade-in cursor-pointer group`}
      >

        {/* HEADER */}
        <div className="p-4 md:p-6 flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-4">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-xl object-cover shadow-sm" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1 -right-1 bg-blue-600 rounded-lg p-0.5 border-2 border-white dark:border-darkcard">
                  <CheckBadgeIcon className="h-3 w-3 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-1">
                <h4 className="font-black text-gray-900 dark:text-white text-sm md:text-base truncate leading-tight hover:underline cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
                    {postAuthor.firstName}
                </h4>
                {post.isPinned && <PinIconSolid className="h-3.5 w-3.5 text-blue-500 shrink-0" />}
                {isPostBoosted && <BoltIcon className="h-3.5 w-3.5 text-orange-500 animate-pulse shrink-0" title="Impulsionado" />}
              </div>
              <p className="text-[8px] md:text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-2 text-blue-600 font-black">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {isAuthor && !isPostBoosted && (
               <button 
                 onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); }}
                 className="hidden md:flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-[0_10px_20px_rgba(37,99,235,0.3)] hover:shadow-[0_15px_30px_rgba(37,99,235,0.4)] hover:-translate-y-0.5 transition-all active:scale-95"
               >
                 <RocketLaunchIcon className="h-4 w-4" /> Impulsionar
               </button>
            )}

            <button 
              onClick={(e) => { e.stopPropagation(); setShowActionsModal(true); }} 
              className={`p-2 rounded-xl transition-all ${showActionsModal ? 'bg-gray-100 dark:bg-white/10 text-blue-600' : 'text-gray-300 hover:text-blue-600'}`}
            >
              <EllipsisHorizontalIcon className="h-6 w-6" />
            </button>
          </div>
        </div>

        {/* CONTENT */}
        <div className="px-4 md:px-6 pb-4 md:pb-6">
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden bg-gray-900 text-white p-6 md:p-12 relative shadow-2xl border-4 border-blue-600/30">
                <div className="absolute top-4 left-4 z-10">
                   <div className="bg-red-600 px-3 py-1 rounded text-[8px] md:text-[10px] font-black flex items-center gap-2 shadow-lg animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3 w-3" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-10 md:py-16 flex flex-col items-center text-center">
                   <div className="w-16 h-16 md:w-24 md:h-24 bg-blue-600/20 rounded-[2rem] flex items-center justify-center mb-6 border border-blue-500/30">
                      <VideoCameraIcon className="h-8 w-8 md:h-12 md:w-12 text-blue-400" />
                   </div>
                   <h3 className="text-xl md:text-3xl font-black mb-4 tracking-tighter leading-tight uppercase line-clamp-2">{post.liveStream.title}</h3>
                   <button 
                      onClick={(e) => { e.stopPropagation(); onNavigate('live', { postId: post.id }); }}
                      className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 md:px-12 md:py-5 rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-[0.1em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
                   >
                      <PlayIcon className="h-4 w-4 md:h-6 md:w-6" /> Entrar na Aula
                   </button>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`p-8 md:p-14 rounded-[2rem] md:rounded-[3.5rem] mb-4 transition-all duration-500 group-hover:scale-[1.005] flex items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    backgroundColor: hasBg ? post.backgroundColor : 'transparent',
                    color: post.textColor || 'inherit',
                    fontSize: post.fontSize || 'inherit',
                    minHeight: hasBg ? '280px' : 'auto',
                    border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
                    fontFamily: post.fontFamily?.replace('font-', '')
                  }}
                >
                  <p className={`font-bold leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-md' : 'text-left w-full'}`}>{post.content}</p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-sm">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[600px]" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        {/* ACTIONS */}
        <div className="px-4 md:px-8 py-3 md:py-4 flex items-center justify-between border-t dark:border-white/5">
          <div className="flex items-center gap-1 md:gap-3">
            <button onClick={handleLike} className={`flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl transition-all active:scale-90 ${hasLiked ? 'text-blue-600 bg-blue-50 dark:bg-blue-500/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {hasLiked ? <HeartIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <HeartIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
              <span className="text-xs md:text-sm font-black">{post.likes?.length || 0}</span>
            </button>

            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ChatIconOutline className="h-5 w-5 md:h-6 md:w-6" />
              <span className="font-black text-xs md:text-sm">{post.comments?.length || 0}</span>
            </button>

            <button onClick={handleShare} className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ShareIcon className="h-5 w-5 md:h-6 md:w-6" />
            </button>
          </div>

          <button onClick={handleSave} className={`p-2.5 rounded-xl transition-all ${hasSaved ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/20' : 'text-gray-300 hover:bg-gray-50'}`}>
            {hasSaved ? <BookmarkIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <BookmarkIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
          </button>
        </div>
      </div>

      {showActionsModal && (
        <PostActionsModal 
          isAuthor={isAuthor}
          isPinned={!!post.isPinned}
          isFollowing={isFollowing}
          onClose={() => setShowActionsModal(false)}
          onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }}
          onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }}
          onPin={handlePin}
          onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }}
          onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }}
          onReport={() => { onNavigate('report-user', { userId: post.userId }); setShowActionsModal(false); }}
        />
      )}

      {showDetailModal && (
        <PostDetailModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowDetailModal(false)}
          onUpdate={onPostUpdatedOrDeleted}
          onNavigate={onNavigate}
          refreshUser={refreshUser}
        />
      )}

      {showBoostModal && (
        <BoostPostModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowBoostModal(false)}
          onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }}
        />
      )}

      {showDeleteModal && (
        <DeleteConfirmModal 
          onClose={() => setShowDeleteModal(false)}
          onConfirm={confirmDelete}
          loading={isDeleting}
        />
      )}

      {showEditModal && (
        <EditPostModal 
          postId={post.id}
          currentUser={currentUser}
          onClose={() => setShowEditModal(false)}
          onSuccess={onPostUpdatedOrDeleted}
        />
      )}

      {showIndicateModal && (
        <IndicateModal 
          post={post} 
          currentUser={currentUser} 
          onClose={() => setShowIndicateModal(false)} 
          onPostUpdated={onPostUpdatedOrDeleted}
        />
      )}
    </>
  );
};

export default PostCard;

import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType, Comment } from '../types';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  updatePostSaves, 
  deletePost, 
  pinPost,
  unpinPost
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  TrashIcon, 
  CheckBadgeIcon,
  FlagIcon,
  PaperAirplaneIcon,
  MapPinIcon as PinIconOutline,
  VideoCameraIcon,
  SignalIcon,
  ArrowsPointingOutIcon,
  ShareIcon,
  RocketLaunchIcon,
  PencilSquareIcon,
  UserPlusIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  PlayIcon,
  BoltIcon
} from '@heroicons/react/24/solid';
import IndicateModal from './IndicateModal';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
  onPinToggle
}) => {
  if (!post || !currentUser || !post.id) return null;

  const postAuthor = findUserById(post.userId);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const hasLiked = post.likes?.includes(currentUser.id) || false;
  const hasSaved = post.saves?.includes(currentUser.id) || false;
  const isAuthor = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId) || false;

  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleOptionsClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.innerWidth < 500) {
      setShowActionsModal(true);
    } else {
      setShowDropdown(!showDropdown);
    }
  };

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado!');
      }
      updatePostShares(post.id, currentUser.id);
      onPostUpdatedOrDeleted();
    } catch (err) {
      console.log('Share cancelled', err);
    }
  };

  const confirmDelete = () => {
    setIsDeleting(true);
    setTimeout(() => {
      deletePost(post.id);
      setIsDeleting(false);
      setShowDeleteModal(false);
      onPostUpdatedOrDeleted();
    }, 1000);
  };

  const handlePinAction = () => {
    if (post.isPinned) unpinPost(post.id, currentUser.id);
    else pinPost(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
    setShowActionsModal(false);
    setShowDropdown(false);
  };

  const handleCardClick = () => {
    if (post.type === PostType.LIVE) {
        onNavigate('live', { postId: post.id });
    } else {
        setShowDetailModal(true);
    }
  };

  if (!postAuthor) return null;
  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={handleCardClick}
        className={`bg-white dark:bg-darkcard rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-4 transition-all hover:shadow-md animate-fade-in cursor-pointer group`}
      >

        {/* HEADER */}
        <div className="p-4 md:p-6 flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-4">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-xl object-cover shadow-sm" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1 -right-1 bg-blue-600 rounded-lg p-0.5 border-2 border-white dark:border-darkcard">
                  <CheckBadgeIcon className="h-3 w-3 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-1">
                <h4 className="font-black text-gray-900 dark:text-white text-sm md:text-base truncate leading-tight hover:underline cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
                    {postAuthor.firstName}
                </h4>
                {post.isPinned && <PinIconSolid className="h-3.5 w-3.5 text-blue-500 shrink-0" />}
                {isPostBoosted && <BoltIcon className="h-3.5 w-3.5 text-orange-500 animate-pulse shrink-0" title="Impulsionado" />}
              </div>
              <p className="text-[8px] md:text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-2 text-blue-600 font-black">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 relative" ref={dropdownRef}>
            {isAuthor && !isPostBoosted && (
               <button 
                 onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); }}
                 className="hidden md:flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-lg hover:shadow-blue-200 dark:hover:shadow-none transition-all active:scale-95"
               >
                 <RocketLaunchIcon className="h-4 w-4" /> Impulsionar
               </button>
            )}

            <button 
              onClick={handleOptionsClick} 
              className={`p-2 rounded-xl transition-all ${showDropdown || showActionsModal ? 'bg-gray-100 dark:bg-white/10 text-blue-600' : 'text-gray-300 hover:text-blue-600'}`}
            >
              <EllipsisHorizontalIcon className="h-6 w-6" />
            </button>

            {/* Dropdown Desktop - Apenas para telas maiores que 500px */}
            {showDropdown && (
              <div className="hidden sm:block absolute right-0 top-full mt-2 w-48 bg-white dark:bg-darkcard rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 overflow-hidden z-50 animate-scale-in">
                {isAuthor ? (
                  <div className="p-1">
                    <button onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 flex items-center gap-3 rounded-xl transition-all"><RocketLaunchIcon className="h-4 w-4"/> Impulsionar</button>
                    <button onClick={(e) => { e.stopPropagation(); setShowEditModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-3 rounded-xl transition-all"><PencilSquareIcon className="h-4 w-4"/> Editar</button>
                    <button onClick={(e) => { e.stopPropagation(); handlePinAction(); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-3 rounded-xl transition-all">{post.isPinned ? <><PinIconSolid className="h-4 w-4 text-blue-500"/> Desafixar</> : <><PinIconOutline className="h-4 w-4"/> Fixar</>}</button>
                    <div className="h-px bg-gray-100 dark:bg-white/5 my-1"></div>
                    <button onClick={(e) => { e.stopPropagation(); setShowDeleteModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center gap-3 rounded-xl transition-all"><TrashIcon className="h-4 w-4"/> Eliminar</button>
                  </div>
                ) : (
                  <div className="p-1">
                    {!isFollowing && <button onClick={(e) => { e.stopPropagation(); onFollowToggle(post.userId); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 flex items-center gap-3 rounded-xl transition-all"><UserPlusIcon className="h-4 w-4"/> Seguir</button>}
                    <button onClick={(e) => { e.stopPropagation(); onNavigate('report-user', { userId: post.userId }); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-orange-600 hover:bg-orange-50 dark:hover:bg-orange-900/20 flex items-center gap-3 rounded-xl transition-all"><FlagIcon className="h-4 w-4"/> Denunciar</button>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* CONTENT */}
        <div className="px-4 md:px-6 pb-4 md:pb-6">
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden bg-gray-900 text-white p-6 md:p-12 relative shadow-2xl border-4 border-blue-600/30">
                <div className="absolute top-4 left-4 z-10">
                   <div className="bg-red-600 px-3 py-1 rounded text-[8px] md:text-[10px] font-black flex items-center gap-2 shadow-lg animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3 w-3" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-10 md:py-16 flex flex-col items-center text-center">
                   <div className="w-16 h-16 md:w-24 md:h-24 bg-blue-600/20 rounded-[2rem] flex items-center justify-center mb-6 border border-blue-500/30">
                      <VideoCameraIcon className="h-8 w-8 md:h-12 md:w-12 text-blue-400" />
                   </div>
                   <h3 className="text-xl md:text-3xl font-black mb-4 tracking-tighter leading-tight uppercase line-clamp-2">{post.liveStream.title}</h3>
                   <button 
                      onClick={(e) => { e.stopPropagation(); onNavigate('live', { postId: post.id }); }}
                      className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 md:px-12 md:py-5 rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-[0.1em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
                   >
                      <PlayIcon className="h-4 w-4 md:h-6 md:w-6" /> Entrar na Aula
                   </button>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`p-8 md:p-14 rounded-[2rem] md:rounded-[3.5rem] mb-4 transition-all duration-500 group-hover:scale-[1.005] flex items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    backgroundColor: hasBg ? post.backgroundColor : 'transparent',
                    color: post.textColor || 'inherit',
                    fontSize: post.fontSize || 'inherit',
                    minHeight: hasBg ? '280px' : 'auto',
                    border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
                    fontFamily: post.fontFamily?.replace('font-', '')
                  }}
                >
                  <p className={`font-bold leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-md' : 'text-left w-full'}`}>{post.content}</p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-sm">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[600px]" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        {/* ACTIONS */}
        <div className="px-4 md:px-8 py-3 md:py-4 flex items-center justify-between border-t dark:border-white/5">
          <div className="flex items-center gap-1 md:gap-3">
            <button onClick={handleLike} className={`flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl transition-all active:scale-90 ${hasLiked ? 'text-blue-600 bg-blue-50 dark:bg-blue-500/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {hasLiked ? <HeartIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <HeartIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
              <span className="text-xs md:text-sm font-black">{post.likes?.length || 0}</span>
            </button>

            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ChatIconOutline className="h-5 w-5 md:h-6 md:w-6" />
              <span className="font-black text-xs md:text-sm">{post.comments?.length || 0}</span>
            </button>

            <button onClick={handleShare} className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ShareIcon className="h-5 w-5 md:h-6 md:w-6" />
            </button>
          </div>

          <button onClick={handleSave} className={`p-2.5 rounded-xl transition-all ${hasSaved ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/20' : 'text-gray-300 hover:bg-gray-50'}`}>
            {hasSaved ? <BookmarkIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <BookmarkIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
          </button>
        </div>
      </div>

      {/* Modal de Ações Centralizado - Apenas para Telas < 500px */}
      {showActionsModal && (
        <PostActionsModal 
          isAuthor={isAuthor}
          isPinned={!!post.isPinned}
          isFollowing={isFollowing}
          onClose={() => setShowActionsModal(false)}
          onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }}
          onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }}
          onPin={handlePinAction}
          onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }}
          onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }}
          onReport={() => { onNavigate('report-user', { userId: post.userId }); setShowActionsModal(false); }}
        />
      )}

      {showDetailModal && (
        <PostDetailModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowDetailModal(false)}
          onUpdate={onPostUpdatedOrDeleted}
          onNavigate={onNavigate}
          refreshUser={refreshUser}
        />
      )}

      {showBoostModal && (
        <BoostPostModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowBoostModal(false)}
          onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }}
        />
      )}

      {showDeleteModal && (
        <DeleteConfirmModal 
          onClose={() => setShowDeleteModal(false)}
          onConfirm={confirmDelete}
          loading={isDeleting}
        />
      )}

      {showEditModal && (
        <EditPostModal 
          postId={post.id}
          currentUser={currentUser}
          onClose={() => setShowEditModal(false)}
          onSuccess={onPostUpdatedOrDeleted}
        />
      )}
    </>
  );
};

export default PostCard;

import React from 'react';
import { 
  PencilSquareIcon, 
  TrashIcon, 
  RocketLaunchIcon, 
  MapPinIcon, 
  XMarkIcon,
  FlagIcon,
  UserPlusIcon
} from '@heroicons/react/24/outline';

interface PostActionsModalProps {
  isAuthor: boolean;
  isPinned: boolean;
  isFollowing?: boolean;
  onClose: () => void;
  onEdit: () => void;
  onDelete: () => void;
  onPin: () => void;
  onBoost: () => void;
  onFollow?: () => void;
  onReport?: () => void;
}

const PostActionsModal: React.FC<PostActionsModalProps> = ({ 
  isAuthor, 
  isPinned, 
  isFollowing,
  onClose, 
  onEdit, 
  onDelete, 
  onPin, 
  onBoost,
  onFollow,
  onReport
}) => {
  return (
    <div className="fixed inset-0 z-[3000] flex items-center justify-center p-6 animate-fade-in">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-md" onClick={onClose}></div>

      {/* Modal Content - Ajustado para ser 'bem pequeno' */}
      <div className="bg-white dark:bg-[#1a1c23] w-full max-w-[260px] rounded-[3rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] border border-white/10 overflow-hidden animate-scale-in relative z-10">
        <div className="p-2 flex flex-col">
          {isAuthor ? (
            <>
              <button 
                onClick={(e) => { e.stopPropagation(); onBoost(); }}
                className="flex items-center gap-3 w-full px-5 py-4 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-2xl transition-all group"
              >
                <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-xl group-hover:scale-110 transition-transform shadow-sm">
                  <RocketLaunchIcon className="h-5 w-5" />
                </div>
                <span className="font-black text-[10px] uppercase tracking-widest">Impulsionar</span>
              </button>

              <button 
                onClick={(e) => { e.stopPropagation(); onEdit(); }}
                className="flex items-center gap-3 w-full px-5 py-4 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 rounded-2xl transition-all group"
              >
                <div className="p-2 bg-gray-100 dark:bg-white/10 rounded-xl group-hover:scale-110 transition-transform shadow-sm">
                  <PencilSquareIcon className="h-5 w-5" />
                </div>
                <span className="font-black text-[10px] uppercase tracking-widest">Editar Aula</span>
              </button>

              <button 
                onClick={(e) => { e.stopPropagation(); onPin(); }}
                className="flex items-center gap-3 w-full px-5 py-4 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 rounded-2xl transition-all group"
              >
                <div className="p-2 bg-gray-100 dark:bg-white/10 rounded-xl group-hover:scale-110 transition-transform shadow-sm">
                  <MapPinIcon className={`h-5 w-5 ${isPinned ? 'text-blue-500' : ''}`} />
                </div>
                <span className="font-black text-[10px] uppercase tracking-widest">
                  {isPinned ? 'Desafixar' : 'Fixar Post'}
                </span>
              </button>

              <div className="h-px bg-gray-100 dark:bg-white/5 my-1 mx-4"></div>

              <button 
                onClick={(e) => { e.stopPropagation(); onDelete(); }}
                className="flex items-center gap-3 w-full px-5 py-4 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-2xl transition-all group"
              >
                <div className="p-2 bg-red-100 dark:bg-red-900/30 rounded-xl group-hover:scale-110 transition-transform shadow-sm">
                  <TrashIcon className="h-5 w-5" />
                </div>
                <span className="font-black text-[10px] uppercase tracking-widest">Eliminar</span>
              </button>
            </>
          ) : (
            <>
              {!isFollowing && (
                <button 
                  onClick={(e) => { e.stopPropagation(); onFollow?.(); }}
                  className="flex items-center gap-3 w-full px-5 py-4 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-2xl transition-all group"
                >
                  <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-xl group-hover:scale-110 transition-transform shadow-sm">
                    <UserPlusIcon className="h-5 w-5" />
                  </div>
                  <span className="font-black text-[10px] uppercase tracking-widest">Seguir</span>
                </button>
              )}

              <button 
                onClick={(e) => { e.stopPropagation(); onReport?.(); }}
                className="flex items-center gap-3 w-full px-5 py-4 text-orange-600 hover:bg-orange-50 dark:hover:bg-orange-900/20 rounded-2xl transition-all group"
              >
                <div className="p-2 bg-orange-100 dark:bg-orange-900/30 rounded-xl group-hover:scale-110 transition-transform shadow-sm">
                  <FlagIcon className="h-5 w-5" />
                </div>
                <span className="font-black text-[10px] uppercase tracking-widest">Denunciar</span>
              </button>
            </>
          )}

          <button 
            onClick={onClose}
            className="mt-2 flex items-center justify-center w-full py-4 text-gray-400 hover:text-gray-900 dark:hover:text-white font-black text-[9px] uppercase tracking-[0.2em] transition-all"
          >
            Fechar Menu
          </button>
        </div>
      </div>
    </div>
  );
};

export default PostActionsModal;

import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  updatePostSaves, 
  deletePost, 
  pinPost,
  unpinPost
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  TrashIcon, 
  CheckBadgeIcon,
  FlagIcon,
  MapPinIcon as PinIconOutline,
  VideoCameraIcon,
  SignalIcon,
  ShareIcon,
  RocketLaunchIcon,
  PencilSquareIcon,
  UserPlusIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  PlayIcon,
  BoltIcon,
  ShareIcon as ShareIconSolid
} from '@heroicons/react/24/solid';
import IndicateModal from './IndicateModal';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  if (!post || !currentUser || !post.id) return null;

  const postAuthor = findUserById(post.userId);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const hasLiked = post.likes?.includes(currentUser.id) || false;
  const hasSaved = post.saves?.includes(currentUser.id) || false;
  const isAuthor = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId) || false;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleOptionsClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    // Lógica Mobile vs Desktop
    if (window.innerWidth < 500) {
      setShowActionsModal(true);
    } else {
      setShowDropdown(!showDropdown);
    }
  };

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado!');
      }
      updatePostShares(post.id, currentUser.id);
      onPostUpdatedOrDeleted();
    } catch (err) {
      console.log('Share error', err);
    }
  };

  const confirmDelete = () => {
    setIsDeleting(true);
    setTimeout(() => {
      deletePost(post.id);
      setIsDeleting(false);
      setShowDeleteModal(false);
      onPostUpdatedOrDeleted();
    }, 1000);
  };

  const handlePinAction = () => {
    if (post.isPinned) unpinPost(post.id, currentUser.id);
    else pinPost(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
    setShowActionsModal(false);
    setShowDropdown(false);
  };

  const handleCardClick = () => {
    if (post.type === PostType.LIVE) {
        onNavigate('live', { postId: post.id });
    } else {
        setShowDetailModal(true);
    }
  };

  if (!postAuthor) return null;
  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={handleCardClick}
        className={`bg-white dark:bg-darkcard rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-4 transition-all hover:shadow-md animate-fade-in cursor-pointer group`}
      >

        {/* HEADER */}
        <div className="p-4 md:p-6 flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-4">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-xl object-cover shadow-sm" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1 -right-1 bg-blue-600 rounded-lg p-0.5 border-2 border-white dark:border-darkcard">
                  <CheckBadgeIcon className="h-3 w-3 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-1">
                <h4 className="font-black text-gray-900 dark:text-white text-sm md:text-base truncate leading-tight hover:underline cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
                    {postAuthor.firstName}
                </h4>
                {post.isPinned && <PinIconSolid className="h-3.5 w-3.5 text-blue-500 shrink-0" />}
                {isPostBoosted && <BoltIcon className="h-3.5 w-3.5 text-orange-500 animate-pulse shrink-0" title="Impulsionado" />}
              </div>
              <p className="text-[8px] md:text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-2 text-blue-600 font-black">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 relative" ref={dropdownRef}>
            {isAuthor && !isPostBoosted && (
               <button 
                 onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); }}
                 className="hidden md:flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-lg hover:shadow-blue-200 dark:hover:shadow-none transition-all active:scale-95"
               >
                 <RocketLaunchIcon className="h-4 w-4" /> Impulsionar
               </button>
            )}

            <button 
              onClick={handleOptionsClick} 
              className={`p-2 rounded-xl transition-all ${showDropdown || showActionsModal ? 'bg-gray-100 dark:bg-white/10 text-blue-600' : 'text-gray-300 hover:text-blue-600'}`}
            >
              <EllipsisHorizontalIcon className="h-6 w-6" />
            </button>

            {/* Dropdown Desktop - Apenas para telas > 500px */}
            {showDropdown && (
              <div className="hidden sm:block absolute right-0 top-full mt-2 w-48 bg-white dark:bg-darkcard rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 overflow-hidden z-50 animate-scale-in">
                {isAuthor ? (
                  <div className="p-1">
                    <button onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 flex items-center gap-3 rounded-xl transition-all"><RocketLaunchIcon className="h-4 w-4"/> Impulsionar</button>
                    <button onClick={(e) => { e.stopPropagation(); setShowEditModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-3 rounded-xl transition-all"><PencilSquareIcon className="h-4 w-4"/> Editar</button>
                    <button onClick={(e) => { e.stopPropagation(); handlePinAction(); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-3 rounded-xl transition-all">{post.isPinned ? <><PinIconSolid className="h-4 w-4 text-blue-500"/> Desafixar</> : <><PinIconOutline className="h-4 w-4"/> Fixar</>}</button>
                    <div className="h-px bg-gray-100 dark:bg-white/5 my-1"></div>
                    <button onClick={(e) => { e.stopPropagation(); setShowDeleteModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center gap-3 rounded-xl transition-all"><TrashIcon className="h-4 w-4"/> Eliminar</button>
                  </div>
                ) : (
                  <div className="p-1">
                    {!isFollowing && <button onClick={(e) => { e.stopPropagation(); onFollowToggle(post.userId); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 flex items-center gap-3 rounded-xl transition-all"><UserPlusIcon className="h-4 w-4"/> Seguir</button>}
                    <button onClick={(e) => { e.stopPropagation(); setShowIndicateModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-3 rounded-xl transition-all"><ShareIconSolid className="h-4 w-4 text-blue-500"/> Indicar Aula</button>
                    <button onClick={(e) => { e.stopPropagation(); onNavigate('report-user', { userId: post.userId }); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-orange-600 hover:bg-orange-50 dark:hover:bg-orange-900/20 flex items-center gap-3 rounded-xl transition-all"><FlagIcon className="h-4 w-4"/> Denunciar</button>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* CONTENT */}
        <div className="px-4 md:px-6 pb-4 md:pb-6">
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden bg-gray-900 text-white p-6 md:p-12 relative shadow-2xl border-4 border-blue-600/30">
                <div className="absolute top-4 left-4 z-10">
                   <div className="bg-red-600 px-3 py-1 rounded text-[8px] md:text-[10px] font-black flex items-center gap-2 shadow-lg animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3 w-3" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-10 md:py-16 flex flex-col items-center text-center">
                   <div className="w-16 h-16 md:w-24 md:h-24 bg-blue-600/20 rounded-[2rem] flex items-center justify-center mb-6 border border-blue-500/30">
                      <VideoCameraIcon className="h-8 w-8 md:h-12 md:w-12 text-blue-400" />
                   </div>
                   <h3 className="text-xl md:text-3xl font-black mb-4 tracking-tighter leading-tight uppercase line-clamp-2">{post.liveStream.title}</h3>
                   <button 
                      onClick={(e) => { e.stopPropagation(); onNavigate('live', { postId: post.id }); }}
                      className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 md:px-12 md:py-5 rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-[0.1em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
                   >
                      <PlayIcon className="h-4 w-4 md:h-6 md:w-6" /> Entrar na Aula
                   </button>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`p-8 md:p-14 rounded-[2rem] md:rounded-[3.5rem] mb-4 transition-all duration-500 group-hover:scale-[1.005] flex items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    backgroundColor: hasBg ? post.backgroundColor : 'transparent',
                    color: post.textColor || 'inherit',
                    fontSize: post.fontSize || 'inherit',
                    minHeight: hasBg ? '280px' : 'auto',
                    border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
                    fontFamily: post.fontFamily?.replace('font-', '')
                  }}
                >
                  <p className={`font-bold leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-md' : 'text-left w-full'}`}>{post.content}</p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-sm">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[600px]" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        {/* ACTIONS */}
        <div className="px-4 md:px-8 py-3 md:py-4 flex items-center justify-between border-t dark:border-white/5">
          <div className="flex items-center gap-1 md:gap-3">
            <button onClick={handleLike} className={`flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl transition-all active:scale-90 ${hasLiked ? 'text-blue-600 bg-blue-50 dark:bg-blue-500/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {hasLiked ? <HeartIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <HeartIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
              <span className="text-xs md:text-sm font-black">{post.likes?.length || 0}</span>
            </button>

            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ChatIconOutline className="h-5 w-5 md:h-6 md:w-6" />
              <span className="font-black text-xs md:text-sm">{post.comments?.length || 0}</span>
            </button>

            <button onClick={handleShare} className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ShareIcon className="h-5 w-5 md:h-6 md:w-6" />
            </button>
          </div>

          <button onClick={handleSave} className={`p-2.5 rounded-xl transition-all ${hasSaved ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/20' : 'text-gray-300 hover:bg-gray-50'}`}>
            {hasSaved ? <BookmarkIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <BookmarkIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
          </button>
        </div>
      </div>

      {/* Modal de Ações Centralizado - Mobile < 500px */}
      {showActionsModal && (
        <PostActionsModal 
          isAuthor={isAuthor}
          isPinned={!!post.isPinned}
          isFollowing={isFollowing}
          onClose={() => setShowActionsModal(false)}
          onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }}
          onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }}
          onPin={handlePinAction}
          onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }}
          onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }}
          onIndicate={() => { setShowActionsModal(false); setShowIndicateModal(true); }}
          onReport={() => { onNavigate('report-user', { userId: post.userId }); setShowActionsModal(false); }}
        />
      )}

      {showDetailModal && (
        <PostDetailModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowDetailModal(false)}
          onUpdate={onPostUpdatedOrDeleted}
          onNavigate={onNavigate}
          refreshUser={refreshUser}
        />
      )}

      {showBoostModal && (
        <BoostPostModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowBoostModal(false)}
          onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }}
        />
      )}

      {showDeleteModal && (
        <DeleteConfirmModal 
          onClose={() => setShowDeleteModal(false)}
          onConfirm={confirmDelete}
          loading={isDeleting}
        />
      )}

      {showEditModal && (
        <EditPostModal 
          postId={post.id}
          currentUser={currentUser}
          onClose={() => setShowEditModal(false)}
          onSuccess={onPostUpdatedOrDeleted}
        />
      )}

      {showIndicateModal && (
        <IndicateModal 
          post={post} 
          currentUser={currentUser} 
          onClose={() => setShowIndicateModal(false)} 
          onPostUpdated={onPostUpdatedOrDeleted}
        />
      )}
    </>
  );
};

export default PostCard;

import React from 'react';
import { 
  PencilSquareIcon, 
  TrashIcon, 
  RocketLaunchIcon, 
  MapPinIcon, 
  XMarkIcon,
  FlagIcon,
  UserPlusIcon,
  ShareIcon
} from '@heroicons/react/24/outline';

interface PostActionsModalProps {
  isAuthor: boolean;
  isPinned: boolean;
  isFollowing?: boolean;
  onClose: () => void;
  onEdit: () => void;
  onDelete: () => void;
  onPin: () => void;
  onBoost: () => void;
  onFollow?: () => void;
  onIndicate?: () => void;
  onReport?: () => void;
}

const PostActionsModal: React.FC<PostActionsModalProps> = ({ 
  isAuthor, 
  isPinned, 
  isFollowing,
  onClose, 
  onEdit, 
  onDelete, 
  onPin, 
  onBoost,
  onFollow,
  onIndicate,
  onReport
}) => {
  return (
    <div className="fixed inset-0 z-[3000] flex items-center justify-center p-6 animate-fade-in">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-md" onClick={onClose}></div>

      {/* Modal Content - Compacto e Centralizado */}
      <div className="bg-white dark:bg-[#1a1c23] w-full max-w-[260px] rounded-[3rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] border border-white/10 overflow-hidden animate-scale-in relative z-10">
        <div className="p-2 flex flex-col">
          {isAuthor ? (
            <>
              <button 
                onClick={(e) => { e.stopPropagation(); onBoost(); }}
                className="flex items-center gap-3 w-full px-5 py-4 text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-2xl transition-all group"
              >
                <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-xl group-hover:scale-110 transition-transform shadow-sm">
                  <RocketLaunchIcon className="h-5 w-5" />
                </div>
                <span className="font-black text-[10px] uppercase tracking-widest">Impulsionar</span>
              </button>

              <button 
                onClick={(e) => { e.stopPropagation(); onEdit(); }}
                className="flex items-center gap-3 w-full px-5 py-4 text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 rounded-2xl transition-all group"
              >
                <div className="p-2 bg-gray-100 dark:bg-white/10 rounded-xl group-hover:scale-110 transition-transform shadow-sm">
                  <PencilSquareIcon className="h-5 w-5" />
                </div>
