interface ChatPageProps {
  currentUser: User;
}

const ChatPage: React.FC<ChatPageProps> = ({ currentUser }) => {
  const [chatContacts, setChatContacts] = useState<User[]>([]);
  const [followedUsersForNewChat, setFollowedUsersForNewChat] = useState<User[]>([]);
  const [selectedContact, setSelectedContact] = useState<User | null>(null);
  const [currentConversation, setCurrentConversation] = useState<ChatConversation | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [newImageToSend, setNewImageToSend] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [followedSearchTerm, setFollowedSearchTerm] = useState('');

  const scrollToBottom = useCallback((behavior: ScrollBehavior = 'auto') => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior, block: 'end' });
    }
  }, []);

  const fetchContactsAndConversations = useCallback(() => {
    const allChats = getChats();
    const existingChatPartnerIds = new Set<string>();

    allChats.forEach(chat => {
      if (chat.participants.includes(currentUser.id)) {
        chat.participants.forEach(p => {
          if (p !== currentUser.id) existingChatPartnerIds.add(p);
        });
      }
    });

    const chatContactsList = Array.from(existingChatPartnerIds)
      .map(id => findUserById(id))
      .filter((u): u is User => !!u) as User[];

    const followedUsersForNewChatList = currentUser.followedUsers
      .filter(followedId => !existingChatPartnerIds.has(followedId) && followedId !== currentUser.id)
      .map(id => findUserById(id))
      .filter((u): u is User => !!u) as User[];

    setChatContacts(chatContactsList.sort((a, b) => a.firstName.localeCompare(b.firstName)));
    setFollowedUsersForNewChat(followedUsersForNewChatList.sort((a, b) => a.firstName.localeCompare(b.firstName)));
  }, [currentUser.id, currentUser.followedUsers]);

  useEffect(() => {
    fetchContactsAndConversations();
  }, [fetchContactsAndConversations]);

  const selectContact = useCallback((contact: User) => {
    setSelectedContact(contact);
    const chats = getChats();
    let conversation = chats.find(
      (chat) =>
        (chat.participants[0] === currentUser.id && chat.participants[1] === contact.id) ||
        (chat.participants[0] === contact.id && chat.participants[1] === currentUser.id)
    );

    if (!conversation) {
      conversation = {
        id: `chat-${currentUser.id}-${contact.id}-${Date.now()}`,
        participants: [currentUser.id, contact.id],
        messages: [],
      };
      saveChats([...chats, conversation]);
    }
    setCurrentConversation(conversation);
    setTimeout(() => scrollToBottom('auto'), 50);
  }, [currentUser.id, scrollToBottom]);

  useEffect(() => {
    if (currentConversation) {
        scrollToBottom('smooth');
    }
  }, [currentConversation?.messages.length, scrollToBottom]);

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if ((!newMessage.trim() && !newImageToSend) || !selectedContact || !currentConversation) return;

    const message: Message = {
      id: `msg-${Date.now()}`,
      senderId: currentUser.id,
      receiverId: selectedContact.id,
      timestamp: Date.now(),
      text: newMessage.trim() || undefined,
      imageUrl: newImageToSend || undefined,
    };

    const allChats = getChats();
    const updatedConversation = {
      ...currentConversation,
      messages: [...(currentConversation.messages || []), message],
    };

    // Atualiza na lista global
    const chatExists = allChats.some(c => c.id === updatedConversation.id);
    const newChatsList = chatExists 
      ? allChats.map((chat) => chat.id === updatedConversation.id ? updatedConversation : chat)
      : [...allChats, updatedConversation];

    saveChats(newChatsList);
    setCurrentConversation(updatedConversation);
    setNewMessage('');
    setNewImageToSend(null);
  };

  const handleImageAttachment = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setNewImageToSend(reader.result as string);
        if (fileInputRef.current) fileInputRef.current.value = "";
      };
      reader.readAsDataURL(file);
    }
  };

  const filteredFollowedUsers = followedUsersForNewChat.filter(user =>
    user.firstName.toLowerCase().includes(followedSearchTerm.toLowerCase()) ||
    user.lastName.toLowerCase().includes(followedSearchTerm.toLowerCase())
  );

  return (
    <div className="fixed inset-0 top-[64px] md:top-[72px] bottom-[64px] md:bottom-0 flex flex-col md:flex-row bg-white dark:bg-darkbg overflow-hidden">

      {/* Sidebar - Contacts */}
      <div className={`w-full md:w-80 lg:w-96 flex flex-col bg-white dark:bg-darkcard border-r border-gray-100 dark:border-white/10 shrink-0 transition-transform duration-300 ${selectedContact ? 'hidden md:flex' : 'flex'}`}>
        <div className="p-5 border-b border-gray-50 dark:border-white/5">
          <h2 className="text-2xl font-black text-gray-900 dark:text-white tracking-tighter">Conversas</h2>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
          <div className="space-y-1">
            {chatContacts.map((contact) => (
              <button
                key={contact.id}
                onClick={() => selectContact(contact)}
                className={`w-full flex items-center p-4 rounded-2xl transition-all ${
                  selectedContact?.id === contact.id ? 'bg-blue-600 text-white shadow-lg' : 'hover:bg-gray-50 dark:hover:bg-white/5'
                }`}
              >
                <div className="relative shrink-0">
                  <img src={contact.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-2xl object-cover border-2 border-white/20" />
                  <div className="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-green-500 border-2 border-white dark:border-darkcard rounded-full"></div>
                </div>
                <div className="ml-4 text-left overflow-hidden">
                  <p className="font-black text-sm truncate">{contact.firstName} {contact.lastName}</p>
                  <p className={`text-[10px] ${selectedContact?.id === contact.id ? 'text-blue-100' : 'text-gray-400'}`}>Online</p>
                </div>
              </button>
            ))}
          </div>

          <div className="mt-8 px-4 pb-10">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Sugeridos</h3>
            <input
              type="text"
              placeholder="Buscar..."
              value={followedSearchTerm}
              onChange={(e) => setFollowedSearchTerm(e.target.value)}
              className="w-full p-3 bg-gray-50 dark:bg-white/5 border-none rounded-xl text-xs font-bold dark:text-white mb-4 shadow-inner"
            />
            {filteredFollowedUsers.map((contact) => (
              <button key={contact.id} onClick={() => selectContact(contact)} className="w-full flex items-center p-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-2xl transition-all">
                <img src={contact.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover grayscale opacity-50" />
                <span className="ml-3 font-bold text-gray-700 dark:text-gray-300 text-xs">{contact.firstName}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Main Chat Area */}
      <div className={`flex-1 flex flex-col h-full bg-[#f8fafc] dark:bg-black/20 relative ${!selectedContact ? 'hidden md:flex' : 'flex'}`}>
        {selectedContact ? (
          <>
            {/* Edge-to-Edge Header */}
            <div className="h-16 md:h-20 flex items-center justify-between px-4 bg-white/95 dark:bg-darkcard/95 backdrop-blur-md border-b border-gray-100 dark:border-white/5 z-30 shrink-0">
              <div className="flex items-center gap-3 min-w-0">
                <button onClick={() => setSelectedContact(null)} className="md:hidden p-2 -ml-2 text-gray-400 hover:text-blue-600">
                  <ArrowLeftIcon className="h-6 w-6" />
                </button>
                <img src={selectedContact.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-xl object-cover border-2 border-blue-500 shrink-0" />
                <div className="min-w-0">
                  <h3 className="text-sm md:text-base font-black text-gray-900 dark:text-white leading-tight truncate">{selectedContact.firstName} {selectedContact.lastName}</h3>
                  <span className="text-[9px] text-green-500 font-black uppercase tracking-widest">Ativo Agora</span>
                </div>
              </div>
              <div className="flex gap-1">
                <button className="p-2.5 text-gray-400 hover:text-blue-600 transition-colors"><PhoneIcon className="h-5 w-5 md:h-6 md:w-6" /></button>
                <button className="p-2.5 text-gray-400 hover:text-blue-600 transition-colors"><VideoCameraIcon className="h-5 w-5 md:h-6 md:w-6" /></button>
              </div>
            </div>

            {/* Centralized Message Feed */}
            <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6 custom-scrollbar scroll-smooth">
              <div className="max-w-4xl mx-auto w-full flex flex-col space-y-4">
                {currentConversation?.messages.map((message) => {
                  const isMine = message.senderId === currentUser.id;
                  return (
                    <div key={message.id} className={`flex w-full ${isMine ? 'justify-end' : 'justify-start'}`}>
                      <div className={`relative max-w-[85%] md:max-w-[70%] p-4 rounded-[2rem] shadow-sm animate-fade-in transition-all ${
                        isMine 
                          ? 'bg-blue-600 text-white rounded-br-none ml-12' 
                          : 'bg-white dark:bg-darkcard text-gray-800 dark:text-gray-100 rounded-bl-none border border-gray-100 dark:border-white/5 mr-12'
                      }`}>
                        {message.imageUrl && (
                          <div className="mb-3 rounded-2xl overflow-hidden shadow-md">
                             <img src={message.imageUrl} className="w-full h-auto object-cover max-h-96" alt="Anexo" />
                          </div>
                        )}
                        {message.text && (
                          <p className="text-sm md:text-base font-medium leading-relaxed break-words whitespace-pre-wrap">
                            {message.text}
                          </p>
                        )}
                        <div className={`flex items-center gap-1.5 mt-2 ${isMine ? 'justify-end' : 'justify-start'}`}>
                           <span className={`text-[8px] font-black uppercase tracking-tighter ${isMine ? 'text-blue-200' : 'text-gray-400'}`}>
                             {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                           </span>
                           {isMine && <CheckBadgeIcon className="h-2.5 w-2.5 text-blue-200" />}
                        </div>
                      </div>
                    </div>
                  );
                })}
                <div ref={messagesEndRef} className="h-4" />
              </div>
            </div>

            {/* Input Bar */}
            <div className="p-4 md:p-6 bg-white dark:bg-darkcard border-t border-gray-100 dark:border-white/5 shrink-0 z-30">
              <form onSubmit={handleSendMessage} className="max-w-4xl mx-auto flex flex-col gap-3">
                {newImageToSend && (
                  <div className="relative w-24 h-24 animate-fade-in ml-4 mb-2">
                     <img src={newImageToSend} className="w-full h-full object-cover rounded-2xl border-4 border-blue-500 shadow-2xl" alt="Preview" />
                     <button type="button" onClick={() => setNewImageToSend(null)} className="absolute -top-2 -right-2 bg-red-600 text-white rounded-full p-1.5 shadow-xl border-2 border-white"><XMarkIcon className="h-4 w-4" /></button>
                  </div>
                )}
                <div className="flex items-center gap-2 bg-gray-50 dark:bg-white/5 p-2 rounded-[2.5rem] border border-gray-100 dark:border-white/10 focus-within:ring-2 focus-within:ring-blue-500/20 transition-all shadow-inner">
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageAttachment} />
                  <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3 md:p-4 text-gray-400 hover:text-blue-600 transition-all shrink-0">
                    <PhotoIcon className="h-6 w-6" />
                  </button>

                  <input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    placeholder="Sua mensagem..."
                    className="flex-grow bg-transparent p-2 text-sm md:text-base focus:outline-none font-bold dark:text-white placeholder-gray-400"
                  />

                  <button type="submit" disabled={!newMessage.trim() && !newImageToSend} className="bg-blue-600 hover:bg-blue-700 text-white p-3 md:p-4 rounded-full shadow-xl active:scale-90 disabled:opacity-30 shrink-0 transition-all">
                    <PaperAirplaneIcon className="h-6 w-6" />
                  </button>
                </div>
              </form>
            </div>
          </>
        ) : (
          <div className="flex-grow flex flex-col items-center justify-center text-center p-10 animate-fade-in bg-slate-50/20 dark:bg-black/5 h-full">
             <div className="bg-blue-50 dark:bg-blue-900/10 w-24 h-24 md:w-32 md:h-32 rounded-[2.5rem] md:rounded-[3.5rem] flex items-center justify-center mb-8 shadow-inner">
                <ChatBubbleLeftRightIcon className="h-10 w-10 md:h-16 md:w-16 text-blue-200" />
             </div>
             <h3 className="text-xl md:text-2xl font-black text-gray-900 dark:text-white tracking-tighter">Central de Mensagens</h3>
             <p className="text-gray-400 max-w-xs mt-3 text-xs md:text-sm font-medium leading-relaxed">Conecte-se com professores e alunos em um ambiente privado e seguro.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatPage;

import { 
  User, Post, UserType, Product, AffiliateSale, Notification, CartItem, 
  TransactionType, ChatConversation, AdCampaign, AudioTrack, Store, 
  Comment, NotificationType, ProductType, ShippingAddress, OrderStatus, 
  PaymentCard, CyberEvent, Story, StoryItem, ProductRating, Message
} from '../types';
import { 
  DEFAULT_USERS, DEFAULT_POSTS, DEFAULT_STORES, DEFAULT_PRODUCTS, 
  DEFAULT_AFFILIATE_SALES, DEFAULT_AUDIO_TRACKS, DEFAULT_ADS, DEFAULT_STORIES 
} from '../constants';

const KEYS = {
  USERS: 'cyber_users',
  POSTS: 'cyber_posts',
  STORES: 'cyber_stores',
  PRODUCTS: 'cyber_products',
  SALES: 'cyber_sales',
  CHATS: 'cyber_chats',
  NOTIFICATIONS: 'cyber_notifications',
  CURRENT_USER: 'cyber_current_user_id',
  PLATFORM_STATS: 'cyber_platform_revenue',
  ADS: 'cyber_ads',
  AUDIO: 'cyber_audio',
  EVENTS: 'cyber_events',
  STORIES: 'cyber_stories',
  CART: 'cyber_cart',
  GLOBAL_SETTINGS: 'cyber_global_settings'
};

const get = <T>(key: string, fallback: T): T => {
  const data = localStorage.getItem(key);
  return data ? JSON.parse(data) : fallback;
};

const set = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

// Inicialização
if (!localStorage.getItem(KEYS.USERS)) set(KEYS.USERS, DEFAULT_USERS);
if (!localStorage.getItem(KEYS.POSTS)) set(KEYS.POSTS, DEFAULT_POSTS);
if (!localStorage.getItem(KEYS.CHATS)) set(KEYS.CHATS, []);

export const getUsers = (): User[] => get(KEYS.USERS, []);
export const findUserById = (id: string) => getUsers().find(u => u.id === id);
export const getCurrentUserId = () => localStorage.getItem(KEYS.CURRENT_USER);
export const saveCurrentUser = (id: string | null) => id ? localStorage.setItem(KEYS.CURRENT_USER, id) : localStorage.removeItem(KEYS.CURRENT_USER);

export const getChats = (): ChatConversation[] => get(KEYS.CHATS, []);
export const saveChats = (chats: ChatConversation[]) => set(KEYS.CHATS, chats);

export const getOrCreateConversation = (user1Id: string, user2Id: string): ChatConversation => {
  const chats = getChats();
  let conversation = chats.find(c => 
    (c.participants.includes(user1Id) && c.participants.includes(user2Id))
  );

  if (!conversation) {
    conversation = {
      id: `chat-${[user1Id, user2Id].sort().join('-')}`,
      participants: [user1Id, user2Id],
      messages: []
    };
    saveChats([...chats, conversation]);
  }
  return conversation;
};

export const sendMessage = (conversationId: string, message: Message) => {
  const chats = getChats();
  const updatedChats = chats.map(chat => {
    if (chat.id === conversationId) {
      return { ...chat, messages: [...chat.messages, message] };
    }
    return chat;
  });
  saveChats(updatedChats);
};

// ... (Manter todas as outras funções de posts, produtos e financeiro do arquivo original)
export const getPosts = (): Post[] => get(KEYS.POSTS, []);
export const updatePostLikes = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else post.likes.push(userId);
    set(KEYS.POSTS, posts);
  }
};
export const deletePost = (id: string) => set(KEYS.POSTS, getPosts().filter(p => p.id !== id));
export const updateUserBalance = (uId: string, amt: number) => {
  const users = getUsers();
  const u = users.find(x => x.id === uId);
  if(u) { u.balance = (u.balance || 0) + amt; set(KEYS.USERS, users); return true; }
  return false;
};
export const getAds = (): AdCampaign[] => get(KEYS.ADS, []);
export const saveAds = (ads: AdCampaign[]) => set(KEYS.ADS, ads);
export const getStories = (): Story[] => get(KEYS.STORIES, []);
export const getEvents = (): CyberEvent[] => get(KEYS.EVENTS, []);
export const toggleFollowUser = (cId: string, fId: string) => {
  const users = getUsers();
  const u1 = users.find(u => u.id === cId);
  if (u1) {
    if (u1.followedUsers.includes(fId)) u1.followedUsers = u1.followedUsers.filter(x => x !== fId);
    else u1.followedUsers.push(fId);
    set(KEYS.USERS, users);
  }
};
export const pinPost = (pId: string, uId: string) => {
    const posts = getPosts().map(p => p.userId === uId ? { ...p, isPinned: p.id === pId } : p);
    set(KEYS.POSTS, posts);
};
export const unpinPost = (pId: string, uId: string) => {
    const posts = getPosts().map(p => p.id === pId ? { ...p, isPinned: false } : p);
    set(KEYS.POSTS, posts);
};
export const updatePostSaves = (pId: string, uId: string) => {
    const posts = getPosts();
    const p = posts.find(x => x.id === pId);
    if(p) {
        if(p.saves.includes(uId)) p.saves = p.saves.filter(x => x !== uId);
        else p.saves.push(uId);
        set(KEYS.POSTS, posts);
    }
};
export const updatePostShares = (pId: string, uId: string) => {
    const posts = getPosts();
    const p = posts.find(x => x.id === pId);
    if(p) { p.shares.push(uId); set(KEYS.POSTS, posts); }
};
export const findStoreById = (id: string) => get<Store[]>(KEYS.STORES, []).find(s => s.id === id);
export const getProducts = (): Product[] => get(KEYS.PRODUCTS, []);
export const getStores = (): Store[] => get(KEYS.STORES, []);
export const updateStore = (s: Store) => set(KEYS.STORES, getStores().map(x => x.id === s.id ? s : x));
export const saveProducts = (p: Product[]) => set(KEYS.PRODUCTS, p);
export const saveStores = (s: Store[]) => set(KEYS.STORES, s);
export const getCart = (): CartItem[] => get(KEYS.CART, []);
export const clearCart = () => set(KEYS.CART, []);
export const getNotificationsForUser = (id: string) => get<any[]>(KEYS.NOTIFICATIONS, []).filter(x => x.recipientId === id);
export const markNotificationsAsRead = (id: string) => set(KEYS.NOTIFICATIONS, get<any[]>(KEYS.NOTIFICATIONS, []).map(x => x.recipientId === id ? {...x, isRead: true} : x));
export const deleteUser = (id: string) => set(KEYS.USERS, getUsers().filter(x => x.id !== id));
export const getGlobalSettings = (): any => get(KEYS.GLOBAL_SETTINGS, {});
export const updateGlobalSettings = (s: any) => set(KEYS.GLOBAL_SETTINGS, s);
export const addPost = (p: Post) => set(KEYS.POSTS, [p, ...getPosts()]);
export const updatePost = (p: Post) => set(KEYS.POSTS, getPosts().map(x => x.id === p.id ? p : x));
export const boostPost = (pId: string, uId: string, b: number, d: number) => {
    const posts = getPosts();
    const p = posts.find(x => x.id === pId);
    if(p && updateUserBalance(uId, -b)) {
        p.isBoosted = true;
        p.boostExpires = Date.now() + (d * 24 * 60 * 60 * 1000);
        set(KEYS.POSTS, posts);
        return true;
    }
    return false;
};
export const getPlatformRevenue = () => 0;
export const addStory = (uId: string, item: any) => {
    const stories = getStories();
    const userStory = stories.find(s => s.userId === uId);
    const newItem = { id: `s-${Date.now()}`, timestamp: Date.now(), ...item };
    if(userStory) userStory.items.push(newItem);
    else {
        const u = findUserById(uId);
        stories.push({ userId: uId, userName: u?.firstName || 'User', userProfilePic: u?.profilePicture, items: [newItem] });
    }
    set(KEYS.STORIES, stories);
};
export const createEvent = (e: CyberEvent) => set(KEYS.EVENTS, [e, ...getEvents()]);
export const toggleJoinEvent = (eId: string, uId: string) => {
    const evts = getEvents();
    const e = evts.find(x => x.id === eId);
    if(e) {
        if(e.attendees.includes(uId)) e.attendees = e.attendees.filter(x => x !== uId);
        else e.attendees.push(uId);
        set(KEYS.EVENTS, evts);
    }
};
export const requestDebitCard = (uId: string, card: any) => {
    const users = getUsers();
    const u = users.find(x => x.id === uId);
    if(u) { u.card = card; set(KEYS.USERS, users); }
};
export const addPostComment = (pId: string, c: Comment) => {
    const posts = getPosts();
    const p = posts.find(x => x.id === pId);
    if(p) { p.comments.push(c); set(KEYS.POSTS, posts); }
};
export const indicatePostToUser = (pId: string, uId: string, tId: string) => {
    const posts = getPosts();
    const p = posts.find(x => x.id === pId);
    if(p) {
        if(!p.indicatedUserIds) p.indicatedUserIds = [];
        p.indicatedUserIds.push(tId);
        set(KEYS.POSTS, posts);
        return true;
    }
    return false;
};
export const getPurchasesByBuyerId = (id: string) => get<any[]>(KEYS.SALES, []).filter(x => x.buyerId === id);
export const getSalesByAffiliateId = (id: string) => get<any[]>(KEYS.SALES, []).filter(x => x.affiliateUserId === id);
export const getSalesByStoreId = (id: string) => get<any[]>(KEYS.SALES, []).filter(x => x.storeId === id);
export const findProductById = (id: string) => getProducts().find(x => x.id === id);
export const addProductRating = (sId: string, r: number, c: string) => {
    const sales = get<any[]>(KEYS.SALES, []);
    const s = sales.find(x => x.id === sId);
    if(s) { s.isRated = true; set(KEYS.SALES, sales); }
};
export const processProductPurchase = (items: any[], bId: string, affId: string | null, addr: any) => {
    const sales = get<any[]>(KEYS.SALES, []);
    items.forEach(i => {
        sales.push({ id: `sale-${Date.now()}-${i.productId}`, buyerId: bId, productId: i.productId, timestamp: Date.now(), status: OrderStatus.DELIVERED });
    });
    set(KEYS.SALES, sales);
    return true;
};
export const adminUpdateUserType = (uId: string, type: UserType) => {
    const users = getUsers();
    const u = users.find(x => x.id === uId);
    if(u) { u.userType = type; set(KEYS.USERS, users); return true; }
    return false;
