export const toggleFollowUser = (cId: string, fId: string) => {
  const users = getUsers();
  const u1 = users.find(u => u.id === cId);
  const u2 = users.find(u => u.id === fId);
  if (u1 && u2) {
    if (u1.followedUsers.includes(fId)) {
      u1.followedUsers = u1.followedUsers.filter(x => x !== fId);
      u2.followers = u2.followers.filter(x => x !== cId);
    } else {
      u1.followedUsers.push(fId);
      u2.followers.push(cId);
    }
    set(KEYS.USERS, users);
  }
};

