import AffiliatesPage from './components/AffiliatesPage';
import { showNotification } from './services/notificationService';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'manage-store' | 'edit-post' | 'create-post' | 'reels-page' | 'search-results' | 'notifications' | 'report-user' | 'settings' | 'admin' | 'events' | 'purchases' | 'affiliates';

const NOTIFICATION_POLL_INTERVAL = 5000;
const LAST_NOTIFICATION_CHECK_KEY = 'cyber_last_notification_check';

const App: React.FC = () => {
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [darkMode, setDarkMode] = useState(() => localStorage.getItem('cyberphone_theme') === 'dark');
    const [currentPage, setCurrentPage] = useState<Page>(() => {
        return getCurrentUserId() ? 'feed' : 'auth';
    });
    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    const [cartItems, setCartItems] = useState<CartItem[]>(getCart());
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });

    const toggleTheme = useCallback(() => {
        setDarkMode(prev => {
            const newVal = !prev;
            localStorage.setItem('cyberphone_theme', newVal ? 'dark' : 'light');
            return newVal;
        });
    }, []);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    const refreshCurrentUser = useCallback(() => {
        const userId = getCurrentUserId();
        if (userId) {
            const user = findUserById(userId);
            setCurrentUser(user || null);
            if (user) {
                const notifications = getNotificationsForUser(user.id);
                setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
            }
        } else {
            setCurrentUser(null);
            setUnreadNotificationsCount(0);
        }
    }, []);

    const refreshCart = useCallback(() => {
        setCartItems(getCart());
    }, []);

    useEffect(() => {
        refreshCurrentUser();
        refreshCart();
    }, [refreshCurrentUser, refreshCart]);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        refreshCurrentUser();
        refreshCart();
        setCurrentPage('feed');
    }, [refreshCurrentUser, refreshCart]);

    const handleLogout = useCallback(() => {
        setCurrentUser(null);
        saveCurrentUser(null);
        setCurrentPage('auth');
        clearCart();
        refreshCart();
    }, [refreshCart]);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
        }
        setCurrentPage(page);
        setPageParams(params);
        window.scrollTo(0, 0);
    }, [currentUser, refreshCurrentUser]);

    const handleAddToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
        addToCart(productId, quantity, selectedColor);
        refreshCart();
    };

    // Notification Polling Logic
    useEffect(() => {
        let notificationInterval: number | null = null;

        if (currentUser) {
            notificationInterval = window.setInterval(() => {
                const userKey = `${LAST_NOTIFICATION_CHECK_KEY}_${currentUser.id}`;
                const lastCheckTime = parseInt(localStorage.getItem(userKey) || '0', 10);
                const currentTime = Date.now();
                let newMsgs = 0;

                const userChats = getChats().filter(chat => chat.participants.includes(currentUser.id));

                userChats.forEach(chat => {
                    chat.messages.forEach(message => {
                        if (message.senderId !== currentUser.id && message.timestamp > lastCheckTime) {
                            const sender = findUserById(message.senderId);
                            if (sender) {
                                showNotification(
                                    `Nova mensagem de ${sender.firstName}`,
                                    {
                                        body: message.text || (message.imageUrl ? 'Imagem enviada.' : 'Você recebeu uma nova mensagem.'),
                                        icon: sender.profilePicture,
                                        url: `/chat`,
                                        tag: `new-chat-message-${message.id}`
                                    }
                                );
                                newMsgs++;
                            }
                        }
                    });
                });

                if (newMsgs > 0) {
                    setUnreadNotificationsCount(prev => prev + newMsgs);
                }

                localStorage.setItem(userKey, currentTime.toString());
            }, NOTIFICATION_POLL_INTERVAL);
        }

        return () => {
            if (notificationInterval) clearInterval(notificationInterval);
        };
    }, [currentUser]);

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={toggleTheme} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={() => { deleteUser(currentUser.id); handleLogout(); }} />;
            case 'ads': return <AdCampaignPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'admin': return <AdminDashboard currentUser={currentUser} />;
            case 'events': return <EventsPage currentUser={currentUser} />;
            case 'purchases': return <PurchasesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'live':
                if (pageParams.postId) return <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
                return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={handleAddToCart} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'manage-store': return <StoreManagerPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'create-post': return <CreatePost currentUser={currentUser} onPostCreated={() => handleNavigate('feed')} refreshUser={refreshCurrentUser} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query || ''} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'report-user': return <ReportUserPage currentUser={currentUser} targetUserId={pageParams.userId} onNavigate={handleNavigate} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300 w-full overflow-x-hidden">
            <Header
                currentUser={currentUser}
                onNavigate={handleNavigate}
                unreadNotificationsCount={unreadNotificationsCount}
                cartItemCount={cartItems.reduce((sum, item) => sum + item.quantity, 0)}
                onOpenCart={() => setIsCartModalOpen(true)}
            />
            <div className="flex flex-1 w-full overflow-x-hidden">
                {currentUser && (
                    <Footer currentUser={currentUser} onNavigate={handleNavigate} activePage={currentPage} onLogout={handleLogout} />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[72px] md:pb-8 transition-all duration-300 w-full ${currentUser ? 'md:ml-64 px-0 md:px-8' : 'px-0'}`}>
                    <div className="max-w-7xl mx-auto w-full">
                        {renderPage()}
                    </div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal 
                    isOpen={isCartModalOpen}
                    onClose={() => setIsCartModalOpen(false)}
                    currentUser={currentUser}
                    onCartUpdate={refreshCart}
                    refreshUser={refreshCurrentUser}
                />
                <WalletModal
                    isOpen={walletConfig.isOpen}
                    mode={walletConfig.mode}
                    onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })}
                    currentUser={currentUser}
                    refreshUser={refreshCurrentUser}
                />
              </>
            )}
        </div>
    );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Message, ChatConversation } from '../types';
import {
  getChats,
  findUserById,
  getOrCreateConversation,
  sendMessage
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  PhoneIcon, 
  VideoCameraIcon, 
  XMarkIcon,
  ChatBubbleLeftRightIcon,
  PhotoIcon,
  ArrowLeftIcon,
  PaperAirplaneIcon,
  CheckBadgeIcon,
  MagnifyingGlassIcon,
  UserPlusIcon
} from '@heroicons/react/24/solid';

interface ChatPageProps {
  currentUser: User;
}

const ChatPage: React.FC<ChatPageProps> = ({ currentUser }) => {
  const [conversations, setConversations] = useState<ChatConversation[]>([]);
  const [selectedChat, setSelectedChat] = useState<ChatConversation | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadData = useCallback((forceSelectId?: string) => {
    const allChats = getChats().filter(c => c.participants.includes(currentUser.id));
    setConversations(allChats);

    const idToUpdate = forceSelectId || selectedChat?.id;
    if (idToUpdate) {
      const updatedSelected = allChats.find(c => c.id === idToUpdate);
      if (updatedSelected) setSelectedChat(updatedSelected);
    }
  }, [currentUser.id, selectedChat?.id]);

  useEffect(() => {
    loadData();
    const interval = setInterval(() => loadData(), 3000);
    return () => clearInterval(interval);
  }, [loadData]);

  useEffect(() => {
    if (messagesEndRef.current) {
        messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [selectedChat?.messages?.length]);

  const handleStartChat = (contactId: string) => {
    const chat = getOrCreateConversation(currentUser.id, contactId);
    setSelectedChat(chat);
    setIsSearching(false);
    setSearchTerm('');
    loadData(chat.id);
  };

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    if ((!newMessage.trim() && !attachedImage) || !selectedChat) return;

    const partnerId = selectedChat.participants.find(id => id !== currentUser.id);
    if (!partnerId) return;

    const msg: Message = {
      id: `msg-${Date.now()}`,
      senderId: currentUser.id,
      receiverId: partnerId,
      timestamp: Date.now(),
      text: newMessage.trim() || undefined,
      imageUrl: attachedImage || undefined
    };

    // Feedback visual imediato
    setSelectedChat(prev => prev ? { ...prev, messages: [...(prev.messages || []), msg] } : null);

    // Persistência
    sendMessage(selectedChat.id, msg);

    setNewMessage('');
    setAttachedImage(null);

    // Resetar altura do textarea
    const textarea = e.currentTarget.querySelector('textarea');
    if (textarea) textarea.style.height = 'auto';
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setAttachedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const filteredUsers = isSearching && searchTerm.length > 0 
    ? currentUser.followedUsers
        .map(id => findUserById(id))
        .filter(u => u && `${u.firstName} ${u.lastName}`.toLowerCase().includes(searchTerm.toLowerCase()))
    : [];

  return (
    <div className="fixed inset-0 top-[64px] md:top-[72px] bottom-[64px] md:bottom-0 flex flex-col md:flex-row bg-white dark:bg-darkbg overflow-hidden animate-fade-in">

      {/* Sidebar - Contatos */}
      <div className={`w-full md:w-80 lg:w-96 flex flex-col bg-white dark:bg-darkcard border-r border-gray-100 dark:border-white/10 shrink-0 z-40 transition-all ${selectedChat ? 'hidden md:flex' : 'flex'}`}>
        <div className="p-6 border-b border-gray-50 dark:border-white/5 space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-2xl font-black text-gray-900 dark:text-white tracking-tighter">Mensagens</h2>
            <button 
              onClick={() => setIsSearching(!isSearching)}
              className={`p-2 rounded-xl transition-all ${isSearching ? 'bg-blue-600 text-white shadow-lg' : 'bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-blue-600'}`}
            >
              {isSearching ? <XMarkIcon className="h-5 w-5" /> : <UserPlusIcon className="h-5 w-5" />}
            </button>
          </div>

          {isSearching && (
            <div className="relative animate-fade-in">
              <MagnifyingGlassIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
              <input 
                type="text" 
                autoFocus
                placeholder="Buscar em seguidos..." 
                className="w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-white/5 dark:text-white rounded-xl outline-none font-bold text-xs border border-transparent focus:border-blue-500"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />
            </div>
          )}
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1">
          {isSearching ? (
             <div className="space-y-1">
                {filteredUsers.map(u => u && (
                  <button key={u.id} onClick={() => handleStartChat(u.id)} className="w-full flex items-center p-3 hover:bg-blue-50 dark:hover:bg-blue-900/10 rounded-2xl transition-all group">
                     <img src={u.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-xl object-cover border shadow-sm group-hover:scale-105 transition-transform" />
                     <div className="ml-3 text-left">
                        <p className="font-black text-sm dark:text-white">{u.firstName} {u.lastName}</p>
                        <p className="text-[10px] text-blue-600 font-black uppercase">Clique para conversar</p>
                     </div>
                  </button>
                ))}
                {searchTerm && filteredUsers.length === 0 && <p className="text-center py-10 text-[10px] font-black text-gray-400 uppercase">Nenhum aluno encontrado</p>}
             </div>
          ) : (
            conversations.map(chat => {
              const partnerId = chat.participants.find(id => id !== currentUser.id);
              if (!partnerId) return null;
              const partner = findUserById(partnerId);
              const lastMsg = chat.messages && chat.messages.length > 0 ? chat.messages[chat.messages.length - 1] : null;
              const isActive = selectedChat?.id === chat.id;

              return (
                <button
                  key={chat.id}
                  onClick={() => setSelectedChat(chat)}
                  className={`w-full flex items-center p-4 rounded-2xl transition-all ${isActive ? 'bg-blue-600 text-white shadow-xl scale-[1.02]' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
                >
                  <div className="relative shrink-0">
                    <img src={partner?.profilePicture || DEFAULT_PROFILE_PIC} className={`w-14 h-14 rounded-2xl object-cover border-2 ${isActive ? 'border-white/30' : 'border-blue-500'}`} />
                    <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white dark:border-darkcard rounded-full shadow-lg"></div>
                  </div>
                  <div className="ml-4 text-left overflow-hidden flex-1">
                    <p className={`font-black text-sm truncate ${isActive ? 'text-white' : 'text-gray-900 dark:text-white'}`}>{partner?.firstName} {partner?.lastName}</p>
                    <p className={`text-[11px] truncate mt-0.5 ${isActive ? 'text-blue-100 font-medium' : 'text-gray-400 font-bold'}`}>
                       {lastMsg ? (lastMsg.senderId === currentUser.id ? 'Você: ' : '') + (lastMsg.text || '📷 Imagem') : 'Inicie uma conversa'}
                    </p>
                  </div>
                </button>
              );
            })
          )}

          {!isSearching && conversations.length === 0 && (
            <div className="flex flex-col items-center justify-center py-20 px-6 text-center opacity-30">
               <ChatBubbleLeftRightIcon className="h-12 w-12 mb-4" />
               <p className="text-[10px] font-black uppercase tracking-widest leading-relaxed">Conecte-se com alunos e professores clicando no ícone "+"</p>
            </div>
          )}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className={`flex-1 flex flex-col h-full bg-[#f8fafc] dark:bg-black/20 relative ${!selectedChat ? 'hidden md:flex' : 'flex'}`}>
        {selectedChat ? (
          <>
            <div className="h-16 md:h-20 flex items-center justify-between px-4 bg-white/90 dark:bg-darkcard/90 backdrop-blur-md border-b border-gray-100 dark:border-white/5 z-30 shrink-0">
              <div className="flex items-center gap-3 min-w-0">
                <button onClick={() => setSelectedChat(null)} className="md:hidden p-2 -ml-2 text-gray-400 hover:text-blue-600 transition-colors">
                  <ArrowLeftIcon className="h-6 w-6" />
                </button>
                {(() => {
                  const pId = selectedChat.participants.find(id => id !== currentUser.id);
                  const p = pId ? findUserById(pId) : null;
                  return (
                    <>
                      <img src={p?.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-xl object-cover border-2 border-blue-500 shrink-0 shadow-sm" />
                      <div className="min-w-0">
                        <h3 className="text-sm md:text-base font-black text-gray-900 dark:text-white leading-tight truncate">
                          {p?.firstName} {p?.lastName}
                        </h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                          <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                          <span className="text-[9px] text-green-500 font-black uppercase tracking-widest">Disponível</span>
                        </div>
                      </div>
                    </>
                  );
                })()}
              </div>
              <div className="flex gap-1">
                <button className="p-2.5 text-gray-400 hover:text-blue-600 transition-colors hover:bg-blue-50 dark:hover:bg-white/5 rounded-xl"><PhoneIcon className="h-5 w-5" /></button>
                <button className="p-2.5 text-gray-400 hover:text-blue-600 transition-colors hover:bg-blue-50 dark:hover:bg-white/5 rounded-xl"><VideoCameraIcon className="h-5 w-5" /></button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6 custom-scrollbar scroll-smooth bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] dark:bg-none">
              <div className="max-w-4xl mx-auto w-full flex flex-col gap-4">
                {(selectedChat.messages || []).map((message) => {
                  const isMine = message.senderId === currentUser.id;
                  return (
                    <div key={message.id} className={`flex w-full ${isMine ? 'justify-end' : 'justify-start'}`}>
                      <div className={`relative max-w-[85%] md:max-w-[70%] p-4 md:p-5 rounded-[2.2rem] shadow-sm animate-fade-in transition-all ${
                        isMine 
                          ? 'bg-blue-600 text-white rounded-br-none ml-10 shadow-blue-100 dark:shadow-none' 
                          : 'bg-white dark:bg-darkcard text-gray-800 dark:text-gray-100 rounded-bl-none border border-gray-100 dark:border-white/5 mr-10'
                      }`}>
                        {message.imageUrl && (
                          <div className="mb-3 rounded-2xl overflow-hidden shadow-lg border-2 border-white/10">
                             <img src={message.imageUrl} className="w-full h-auto object-cover max-h-96" alt="Anexo" />
                          </div>
                        )}
                        {message.text && (
                          <p className="text-sm md:text-base font-bold leading-relaxed break-words whitespace-pre-wrap">
                            {message.text}
                          </p>
                        )}
                        <div className={`flex items-center gap-1.5 mt-2 ${isMine ? 'justify-end' : 'justify-start'} opacity-60`}>
                           <span className="text-[8px] font-black uppercase tracking-widest">
                             {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                           </span>
                           {isMine && <CheckBadgeIcon className="h-3 w-3" />}
                        </div>
                      </div>
                    </div>
                  );
                })}
                <div ref={messagesEndRef} className="h-2 md:h-4" />
              </div>
            </div>

            <div className="p-4 md:p-6 bg-white dark:bg-darkcard border-t border-gray-100 dark:border-white/5 shrink-0 z-30 shadow-[0_-10px_40px_rgba(0,0,0,0.02)]">
              <form onSubmit={handleSend} className="max-w-4xl mx-auto space-y-4">
                {attachedImage && (
                  <div className="relative w-24 h-24 md:w-32 md:h-32 animate-fade-in ml-4">
                     <img src={attachedImage} className="w-full h-full object-cover rounded-2xl border-4 border-blue-500 shadow-2xl" alt="Preview" />
                     <button type="button" onClick={() => setAttachedImage(null)} className="absolute -top-2 -right-2 bg-red-600 text-white rounded-full p-1.5 shadow-xl border-2 border-white active:scale-90 transition-all"><XMarkIcon className="h-4 w-4" /></button>
                  </div>
                )}
                <div className="flex items-center gap-2 bg-gray-50 dark:bg-white/5 p-2 rounded-[2.5rem] border border-gray-100 dark:border-white/10 focus-within:ring-4 focus-within:ring-blue-500/10 transition-all shadow-inner">
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                  <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3 md:p-4 text-gray-400 hover:text-blue-600 transition-all shrink-0 hover:bg-blue-50 dark:hover:bg-white/10 rounded-full">
                    <PhotoIcon className="h-6 w-6 md:h-7 md:w-7" />
                  </button>

                  <textarea
                    value={newMessage}
                    onChange={(e) => {
                       setNewMessage(e.target.value);
                       e.target.style.height = 'auto';
                       e.target.style.height = `${Math.min(e.target.scrollHeight, 120)}px`;
                    }}
                    placeholder="Escreva algo..."
                    className="flex-grow bg-transparent p-3 text-sm md:text-base focus:outline-none font-bold dark:text-white placeholder-gray-400 resize-none max-h-32 custom-scrollbar"
                    rows={1}
                  />

                  <button 
                    type="submit" 
                    disabled={!newMessage.trim() && !attachedImage} 
                    className="bg-blue-600 hover:bg-blue-700 text-white p-3 md:p-5 rounded-full shadow-xl active:scale-90 disabled:opacity-30 disabled:grayscale shrink-0 transition-all"
                  >
                    <PaperAirplaneIcon className="h-6 w-6 md:h-7 md:w-7 -rotate-45" />
                  </button>
                </div>
              </form>
            </div>
          </>
        ) : (
          <div className="flex-grow flex flex-col items-center justify-center text-center p-12 animate-fade-in h-full bg-slate-50/30 dark:bg-black/10">
             <div className="bg-blue-50 dark:bg-blue-900/10 w-32 h-32 md:w-48 md:h-48 rounded-[4rem] flex items-center justify-center mb-10 shadow-inner relative group">
                <div className="absolute inset-0 bg-blue-600/5 rounded-[4rem] animate-ping group-hover:animate-none"></div>
                <ChatBubbleLeftRightIcon className="h-16 w-16 md:h-24 md:w-24 text-blue-300 relative z-10" />
             </div>
             <h3 className="text-2xl md:text-4xl font-black text-gray-900 dark:text-white tracking-tighter uppercase">Conversas CyBer</h3>
             <p className="text-gray-400 max-w-sm mt-4 text-sm md:text-base font-bold leading-relaxed">Conecte-se em tempo real clicando em um contato ou buscando novos.</p>
             <button onClick={() => setIsSearching(true)} className="mt-10 px-8 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase shadow-2xl hover:bg-blue-700 transition-all active:scale-95">Buscar Novo Contato</button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatPage;

import { 
