import React, { useState, useEffect, useMemo } from 'react';
import { User, AffiliateSale, Product, OrderStatus, ProductType } from '../types';
import { getPurchasesByBuyerId, findProductById, addProductRating, updateSaleStatus } from '../services/storageService';
import { ShoppingBagIcon, TruckIcon, CheckCircleIcon, ClockIcon, StarIcon, ArchiveBoxIcon, CheckIcon } from '@heroicons/react/24/outline';
import { StarIcon as StarIconSolid } from '@heroicons/react/24/solid';

interface PurchasesPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
}

const PurchasesPage: React.FC<PurchasesPageProps> = ({ currentUser, onNavigate }) => {
  const [purchases, setPurchases] = useState<AffiliateSale[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<OrderStatus | 'ALL'>('ALL');
  const [ratingModal, setRatingModal] = useState<{saleId: string, productId: string} | null>(null);
  const [tempRating, setTempRating] = useState(5);
  const [tempComment, setTempComment] = useState('');

  const loadPurchases = () => {
    setLoading(true);
    const data = getPurchasesByBuyerId(currentUser.id);
    setPurchases(data);
    setLoading(false);
  };

  useEffect(() => {
    loadPurchases();
  }, [currentUser.id]);

  const filteredPurchases = useMemo(() => {
    if (activeTab === 'ALL') return purchases;
    return purchases.filter(p => p.status === activeTab);
  }, [purchases, activeTab]);

  const handleRateProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!ratingModal) return;
    addProductRating(ratingModal.saleId, tempRating, tempComment);
    setRatingModal(null);
    setTempComment('');
    loadPurchases();
    alert('Avaliação enviada!');
  };

  const handleConfirmDelivery = (saleId: string) => {
    if (window.confirm("Você confirma que o produto foi entregue em mãos e está tudo certo?")) {
       updateSaleStatus(saleId, OrderStatus.DELIVERED);
       loadPurchases();
    }
  };

  const getStatusConfig = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.WAITLIST:
        return { label: 'Em Preparação', color: 'text-orange-600', bg: 'bg-orange-50', icon: ClockIcon, progress: 'w-1/4' };
      case OrderStatus.SHIPPING:
        return { label: 'A Caminho', color: 'text-blue-600', bg: 'bg-blue-50', icon: TruckIcon, progress: 'w-3/4' };
      case OrderStatus.DELIVERED:
        return { label: 'Entregue', color: 'text-green-600', bg: 'bg-green-50', icon: CheckCircleIcon, progress: 'w-full' };
    }
  };

  if (loading) return <div className="p-10 text-center font-black text-gray-400 uppercase tracking-widest text-xs">Aguarde...</div>;

  return (
    <div className="container mx-auto px-1 py-4 md:p-8 animate-fade-in">
      <header className="mb-6 px-4">
        <h2 className="text-2xl md:text-4xl font-black text-gray-900 dark:text-white mb-1">Meus Pedidos</h2>
        <p className="text-gray-500 text-[10px] font-bold uppercase tracking-widest">Rastreio e Acesso aos seus investimentos</p>
      </header>

      {/* Tabs */}
      <div className="flex gap-2 mb-6 overflow-x-auto no-scrollbar px-4 pb-2">
         {[
           { id: 'ALL', label: 'Tudo', icon: ArchiveBoxIcon },
           { id: OrderStatus.WAITLIST, label: 'Preparo', icon: ClockIcon },
           { id: OrderStatus.SHIPPING, label: 'Trânsito', icon: TruckIcon },
           { id: OrderStatus.DELIVERED, label: 'Finalizado', icon: CheckCircleIcon }
         ].map(tab => (
           <button
             key={tab.id}
             onClick={() => setActiveTab(tab.id as any)}
             className={`flex items-center gap-2 px-5 py-2.5 rounded-xl font-black text-[10px] uppercase transition-all whitespace-nowrap ${
               activeTab === tab.id ? 'bg-blue-600 text-white shadow-lg' : 'bg-white dark:bg-white/5 text-gray-500 border border-gray-100 dark:border-white/10'
             }`}
           >
             <tab.icon className="h-4 w-4" />
             {tab.label}
           </button>
         ))}
      </div>

      {filteredPurchases.length === 0 ? (
        <div className="bg-white dark:bg-darkcard rounded-[2.5rem] p-16 text-center border-2 border-dashed border-gray-100 dark:border-white/10 mx-4">
           <ShoppingBagIcon className="h-12 w-12 text-gray-200 mx-auto mb-4" />
           <p className="text-gray-400 font-black uppercase text-[10px]">Nenhum pedido nesta categoria</p>
        </div>
      ) : (
        <div className="space-y-4 px-4 pb-20">
          {filteredPurchases.map(sale => {
            const product = findProductById(sale.productId);
            if (!product) return null;
            const config = getStatusConfig(sale.status);

            return (
              <div key={sale.id} className="bg-white dark:bg-darkcard rounded-3xl shadow-sm border border-gray-50 dark:border-white/10 p-5 group transition-all hover:shadow-md">
                 <div className="flex gap-4 mb-4">
                    <img src={product.imageUrls[0]} className="w-16 h-16 rounded-2xl object-cover shrink-0" />
                    <div className="flex-1 overflow-hidden">
                       <h4 className="font-black text-gray-900 dark:text-white text-sm leading-tight truncate">{product.name}</h4>
                       <p className="text-[9px] font-black text-blue-600 uppercase tracking-tighter mt-1">Pedido: #{sale.id.split('-')[1]}</p>
                    </div>
                    <div className="text-right">
                       <p className="text-lg font-black text-gray-900 dark:text-white">${sale.saleAmount.toFixed(2)}</p>
                       <span className="text-[8px] font-black text-gray-400 uppercase">{product.type === ProductType.PHYSICAL ? 'Físico' : 'Digital'}</span>
                    </div>
                 </div>

                 <div className="space-y-3">
                    <div className="flex items-center justify-between">
                       <span className={`text-[9px] font-black uppercase px-2 py-1 rounded-lg ${config.bg} ${config.color} dark:bg-white/5`}>{config.label}</span>
                       <span className="text-[9px] font-bold text-gray-400">{new Date(sale.timestamp).toLocaleDateString()}</span>
                    </div>

                    <div className="w-full h-1.5 bg-gray-100 dark:bg-white/5 rounded-full overflow-hidden">
                       <div className={`h-full ${config.color.replace('text', 'bg')} ${config.progress} transition-all duration-700`}></div>
                    </div>

                    <div className="flex gap-2 pt-2">
                       {product.type !== ProductType.PHYSICAL && sale.status === OrderStatus.DELIVERED && (
                          <button className="flex-1 bg-blue-600 text-white py-3 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">Acessar Conteúdo</button>
                       )}

                       {product.type === ProductType.PHYSICAL && sale.status === OrderStatus.SHIPPING && (
                          <button 
                            onClick={() => handleConfirmDelivery(sale.id)}
                            className="flex-1 bg-green-600 text-white py-3 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center justify-center gap-2"
                          >
                             <CheckIcon className="h-4 w-4" /> Confirmar Recebimento
                          </button>
                       )}

                       {sale.status === OrderStatus.DELIVERED && !sale.isRated && (
                          <button onClick={() => setRatingModal({saleId: sale.id, productId: product.id})} className="flex-1 bg-gray-50 dark:bg-white/5 text-gray-500 py-3 rounded-xl text-[10px] font-black uppercase border dark:border-white/5">Avaliar Compra</button>
                       )}
                    </div>
                 </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal Rating */}
      {ratingModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setRatingModal(null)}>
           <div className="bg-white dark:bg-darkcard w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-black text-gray-900 dark:text-white mb-6 text-center">Como foi sua experiência?</h3>
              <form onSubmit={handleRateProduct} className="space-y-6">
                 <div className="flex justify-center gap-1">
                    {[1,2,3,4,5].map(star => (
                      <button key={star} type="button" onClick={() => setTempRating(star)} className="p-1">
                         {star <= tempRating ? <StarIconSolid className="h-8 w-8 text-yellow-400" /> : <StarIcon className="h-8 w-8 text-gray-200" />}
                      </button>
                    ))}
                 </div>
                 <textarea value={tempComment} onChange={e => setTempComment(e.target.value)} placeholder="Deixe um comentário para o professor..." className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none text-sm dark:text-white h-24 resize-none border dark:border-white/5" required />
                 <button type="submit" className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-xs uppercase shadow-xl">Enviar Avaliação</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default PurchasesPage;

import React, { useState, useEffect, useMemo } from 'react';
import { User, UserType, Store, Product, ProductType, OrderStatus, AffiliateSale } from '../types';
import { 
  getStores, 
  getProducts, 
  saveProducts,
  updateStore,
  getAllSales,
  updateSaleStatus,
  findUserById
} from '../services/storageService';
import { sourceDropshippingProducts } from '../services/geminiService';
import { 
  PlusIcon, 
  ArchiveBoxIcon,
  TrashIcon,
  CheckBadgeIcon,
  BoltIcon,
  XMarkIcon,
  MagnifyingGlassIcon,
  ArrowDownTrayIcon,
  PaintBrushIcon,
  ShoppingBagIcon,
  PhotoIcon,
  InformationCircleIcon,
  BookOpenIcon,
  VideoCameraIcon,
  AcademicCapIcon,
  TruckIcon,
  ClipboardDocumentListIcon,
  MapPinIcon,
  ClockIcon
} from '@heroicons/react/24/solid';

interface StoreManagerPageProps {
  currentUser: User;
  refreshUser: () => void;
  onNavigate: (page: any, params?: any) => void;
}

type ManagerTab = 'inventory' | 'orders' | 'sourcing' | 'branding';

const BRAND_COLORS = [
  { name: 'Azul CyBer', hex: '#2563eb' },
  { name: 'Roxo Royal', hex: '#7c3aed' },
  { name: 'Verde Mint', hex: '#10b981' },
  { name: 'Preto Carbono', hex: '#0f172a' },
  { name: 'Laranja Solar', hex: '#f59e0b' },
  { name: 'Rosa Shock', hex: '#db2777' }
];

const StoreManagerPage: React.FC<StoreManagerPageProps> = ({ currentUser, refreshUser, onNavigate }) => {
  const [userStore, setUserStore] = useState<Store | null>(null);
  const [storeProducts, setStoreProducts] = useState<Product[]>([]);
  const [storeSales, setStoreSales] = useState<AffiliateSale[]>([]);
  const [activeTab, setActiveTab] = useState<ManagerTab>('inventory');
  const [isAddingProduct, setIsAddingProduct] = useState(false);

  const [brandName, setBrandName] = useState('');
  const [brandDesc, setBrandDesc] = useState('');
  const [brandColor, setBrandColor] = useState(BRAND_COLORS[0].hex);

  const [pName, setPName] = useState('');
  const [pDesc, setPDesc] = useState('');
  const [pPrice, setPPrice] = useState('');
  const [pType, setPType] = useState<ProductType>(ProductType.DIGITAL_COURSE);
  const [pImg, setPImg] = useState('');
  const [pDigitalUrl, setPDigitalUrl] = useState('');

  const [searchQuery, setSearchQuery] = useState('');
  const [sourcingResults, setSourcingResults] = useState<any[]>([]);
  const [isSourcing, setIsSourcing] = useState(false);
  const [markup, setMarkup] = useState(1.5);

  const loadData = () => {
    const stores = getStores();
    const myStore = stores.find(s => s.professorId === currentUser.id);
    if (myStore) {
      setUserStore(myStore);
      setBrandName(myStore.name);
      setBrandDesc(myStore.description);
      setBrandColor(myStore.brandColor || BRAND_COLORS[0].hex);
      setStoreProducts(getProducts().filter(p => p.storeId === myStore.id));
      setStoreSales(getAllSales().filter(s => s.storeId === myStore.id).sort((a, b) => b.timestamp - a.timestamp));
    }
  };

  useEffect(() => {
    loadData();
  }, [currentUser.id]);

  const handleSaveBranding = () => {
    if (!userStore) return;
    const updated = { ...userStore, name: brandName, description: brandDesc, brandColor };
    updateStore(updated);
    setUserStore(updated);
    alert('Identidade visual da loja atualizada!');
  };

  const handleCreateProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userStore) return;

    const newProduct: Product = {
      id: `prod-man-${Date.now()}`,
      storeId: userStore.id,
      name: pName,
      description: pDesc,
      price: parseFloat(pPrice),
      imageUrls: [pImg || 'https://picsum.photos/400/400?random=prod'],
      affiliateCommissionRate: 0.15,
      type: pType,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      digitalContentUrl: pType !== ProductType.PHYSICAL ? pDigitalUrl : undefined
    };

    saveProducts([...getProducts(), newProduct]);
    setIsAddingProduct(false);
    loadData();
    alert('Produto criado com sucesso!');
  };

  const handleUpdateStatus = (saleId: string, status: OrderStatus) => {
    updateSaleStatus(saleId, status);
    loadData();
  };

  const handleSource = async () => {
    if (!searchQuery) return;
    setIsSourcing(true);
    const results = await sourceDropshippingProducts(searchQuery);
    setSourcingResults(results);
    setIsSourcing(false);
  };

  const handleImport = (sourceProd: any) => {
    if (!userStore) return;
    const newProduct: Product = {
      id: `prod-drop-${Date.now()}`,
      storeId: userStore.id,
      name: sourceProd.name,
      description: sourceProd.description,
      price: sourceProd.originalPrice * markup,
      imageUrls: [sourceProd.imageUrl],
      affiliateCommissionRate: 0.1,
      type: ProductType.PHYSICAL,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      isDropshipping: true,
      externalProviderId: sourceProd.externalProviderId,
      originalPrice: sourceProd.originalPrice
    };
    saveProducts([...getProducts(), newProduct]);
    loadData();
    alert('Importado para estoque!');
  };

  if (currentUser.userType === UserType.STANDARD) {
    return (
      <div className="container mx-auto px-4 pt-32 text-center max-w-2xl animate-fade-in">
         <div className="bg-blue-600 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl">
            <AcademicCapIcon className="h-12 w-12 text-white" />
         </div>
         <h2 className="text-4xl font-black mb-6 tracking-tighter dark:text-white">Seja um Mestre <span className="text-blue-600">Pro.</span></h2>
         <p className="text-gray-500 text-lg mb-10 leading-relaxed">Ganhe seguidores e suba de nível para desbloquear sua própria loja e faturar vendendo conhecimento.</p>
         <button onClick={() => onNavigate('ads')} className="bg-blue-600 text-white px-12 py-5 rounded-2xl font-black uppercase text-sm shadow-xl active:scale-95 transition-all">Impulsionar Carreira</button>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 pt-24 pb-32 max-w-6xl animate-fade-in">

       <div className="flex flex-col md:flex-row items-center justify-between mb-12 gap-8">
          <div className="flex items-center gap-5">
            <div className="w-16 h-16 rounded-[1.5rem] shadow-xl flex items-center justify-center text-white" style={{ backgroundColor: brandColor }}>
              <CheckBadgeIcon className="h-10 w-10" />
            </div>
            <div>
              <h2 className="text-3xl font-black dark:text-white tracking-tighter uppercase">{brandName || 'Minha Loja'}</h2>
              <p className="text-gray-500 text-[10px] font-black uppercase tracking-widest flex items-center gap-2">Painel do Especialista <span className="w-2 h-2 bg-green-500 rounded-full"></span></p>
            </div>
          </div>

          <div className="flex bg-gray-100 dark:bg-white/5 p-1.5 rounded-[1.8rem] shadow-inner overflow-x-auto no-scrollbar max-w-full">
             {[
               { id: 'inventory', label: 'Estoque', icon: ArchiveBoxIcon },
               { id: 'orders', label: 'Pedidos', icon: ClipboardDocumentListIcon },
               { id: 'sourcing', label: 'Sourcing', icon: BoltIcon },
               { id: 'branding', label: 'Marca', icon: PaintBrushIcon }
             ].map(t => (
               <button 
                key={t.id} 
                onClick={() => setActiveTab(t.id as any)} 
                className={`px-5 py-3 rounded-2xl font-black text-[10px] uppercase transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === t.id ? 'bg-white dark:bg-darkcard text-blue-600 shadow-lg' : 'text-gray-500'}`}
               >
                 <t.icon className="h-4 w-4" /> {t.label}
               </button>
             ))}
          </div>
       </div>

       {activeTab === 'inventory' && (
         <div className="space-y-8 animate-fade-in">
            <div className="flex justify-between items-center px-4">
               <h3 className="font-black text-xl dark:text-white uppercase tracking-tighter">Produtos Ativos</h3>
               <button onClick={() => setIsAddingProduct(true)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 active:scale-95 transition-all"><PlusIcon className="h-4 w-4 stroke-[4]" /> Novo Produto</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
               {storeProducts.map(p => (
                 <div key={p.id} className="bg-white dark:bg-darkcard rounded-[2.5rem] overflow-hidden border border-gray-100 dark:border-white/5 shadow-sm group hover:shadow-2xl transition-all">
                    <img src={p.imageUrls[0]} className="h-48 w-full object-cover group-hover:scale-105 transition-transform" />
                    <div className="p-6">
                       <h4 className="font-black text-sm dark:text-white uppercase truncate mb-1">{p.name}</h4>
                       <p className="text-2xl font-black text-blue-600 mb-6">${p.price.toFixed(2)}</p>
                       <div className="flex gap-2">
                          <button className="flex-1 bg-gray-50 dark:bg-white/5 text-gray-500 py-3 rounded-xl text-[10px] font-black uppercase">Editar</button>
                          <button className="p-3 bg-red-50 text-red-500 dark:bg-red-900/10 rounded-xl"><TrashIcon className="h-4 w-4"/></button>
                       </div>
                    </div>
                 </div>
               ))}
            </div>
         </div>
       )}

       {activeTab === 'orders' && (
         <div className="space-y-6 animate-fade-in">
            <div className="bg-white dark:bg-darkcard rounded-[2.5rem] overflow-hidden border border-gray-100 dark:border-white/5 shadow-xl">
               <div className="p-6 border-b dark:border-white/5 bg-gray-50 dark:bg-white/5 flex items-center justify-between">
                  <h3 className="font-black text-sm uppercase tracking-widest text-gray-900 dark:text-white">Fluxo de Vendas</h3>
                  <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 dark:bg-blue-900/20 px-3 py-1 rounded-full">{storeSales.length} Total</span>
               </div>
               <div className="divide-y divide-gray-50 dark:divide-white/5">
                  {storeSales.length === 0 ? (
                    <div className="p-20 text-center text-gray-400 font-black uppercase text-xs">Sem pedidos ainda.</div>
                  ) : (
                    storeSales.map(sale => {
                       const buyer = findUserById(sale.buyerId);
                       const product = getProducts().find(p => p.id === sale.productId);
                       const isPhysical = product?.type === ProductType.PHYSICAL;

                       return (
                         <div key={sale.id} className="p-6 flex flex-col md:flex-row gap-6 items-start md:items-center hover:bg-gray-50/50 dark:hover:bg-white/5 transition-colors">
                            <div className="flex items-center gap-4 min-w-[250px]">
                               <img src={product?.imageUrls[0]} className="w-14 h-14 rounded-xl object-cover" />
                               <div>
                                  <p className="font-black text-sm dark:text-white uppercase truncate max-w-[180px]">{product?.name}</p>
                                  <p className="text-[9px] font-bold text-gray-400 uppercase">#ID: {sale.id.split('-')[1]}</p>
                               </div>
                            </div>

                            <div className="flex-1 space-y-2">
                               <div className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase">
                                  <ShoppingBagIcon className="h-3.5 w-3.5" />
