                            </div>

                            <div className="flex items-center gap-4 w-full md:w-auto">
                               <div className="text-right min-w-[80px]">
                                  <p className="text-lg font-black text-gray-900 dark:text-white">${sale.saleAmount.toFixed(2)}</p>
                                  <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded ${sale.status === OrderStatus.DELIVERED ? 'bg-green-100 text-green-600' : 'bg-orange-100 text-orange-600'}`}>
                                     {sale.status}
                                  </span>
                               </div>

                               <div className="flex gap-2 shrink-0">
                                  {sale.status === OrderStatus.WAITLIST && isPhysical && (
                                     <button 
                                      onClick={() => handleUpdateStatus(sale.id, OrderStatus.SHIPPING)}
