                                     >
                                        <TruckIcon className="h-4 w-4" /> Marcar como Enviado
                                     </button>
                                  )}
                                  {sale.status === OrderStatus.WAITLIST && !isPhysical && (
                                     <button 
                                      onClick={() => handleUpdateStatus(sale.id, OrderStatus.DELIVERED)}
                                      className="bg-green-600 text-white px-5 py-2.5 rounded-xl font-black text-[10px] uppercase shadow-lg flex items-center gap-2 hover:bg-green-700 transition-all"
                                     >
                                        Liberar Acesso
                                     </button>
                                  )}
                                  {sale.status === OrderStatus.SHIPPING && (
                                     <div className="text-[9px] font-black text-blue-400 uppercase animate-pulse">Em trânsito...</div>
                                  )}
                               </div>
                            </div>
                         </div>
                       );
                    })
                  )}
               </div>
            </div>
         </div>
       )}

       {activeTab === 'branding' && (
         <div className="max-w-4xl mx-auto space-y-10 animate-fade-in">
            <div className="bg-white dark:bg-darkcard p-10 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-white/5">
               <h3 className="text-2xl font-black dark:text-white uppercase tracking-tight mb-10">Marca e Vitrine</h3>
               <div className="space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nome Comercial</label>
                        <input type="text" value={brandName} onChange={e => setBrandName(e.target.value)} className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white font-black outline-none" />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Cor Principal</label>
                        <div className="flex gap-2">
                           {BRAND_COLORS.map(c => (
                             <button key={c.hex} onClick={() => setBrandColor(c.hex)} className={`w-10 h-10 rounded-full border-4 transition-all ${brandColor === c.hex ? 'border-white shadow-xl scale-110' : 'opacity-60'}`} style={{ backgroundColor: c.hex }}></button>
                           ))}
                        </div>
                     </div>
                  </div>
                  <textarea value={brandDesc} onChange={e => setBrandDesc(e.target.value)} className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white h-32 resize-none outline-none" placeholder="Descrição da sua loja..." />
                  <button onClick={handleSaveBranding} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-sm uppercase shadow-xl hover:bg-blue-700 transition-all">Salvar Marca</button>
               </div>
            </div>
         </div>
       )}

       {activeTab === 'sourcing' && (
         <div className="space-y-8 animate-fade-in">
            <div className="bg-white dark:bg-darkcard p-10 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-white/5">
               <h3 className="text-2xl font-black dark:text-white uppercase tracking-tight mb-8">Dropshipping Inteligente</h3>
               <div className="flex gap-4">
                  <div className="flex-1 relative">
                    <MagnifyingGlassIcon className="h-6 w-6 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input type="text" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} placeholder="Pesquisar produtos para importar..." className="w-full pl-12 pr-6 py-5 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-black dark:text-white" />
                  </div>
                  <button onClick={handleSource} disabled={isSourcing} className="bg-orange-500 text-white px-10 rounded-2xl font-black uppercase text-xs shadow-xl disabled:opacity-50">{isSourcing ? 'Prospectando...' : 'Buscar'}</button>
               </div>
            </div>

            {sourcingResults.length > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {sourcingResults.map((res, i) => (
                  <div key={i} className="bg-white dark:bg-darkcard rounded-[3rem] p-8 flex gap-8 border border-gray-100 dark:border-white/5 shadow-md">
                     <img src={res.imageUrl} className="w-44 h-44 rounded-[2rem] object-cover shadow-lg" />
                     <div className="flex-1 flex flex-col justify-center">
                        <h4 className="font-black text-lg dark:text-white mb-2 uppercase line-clamp-1">{res.name}</h4>
                        <p className="text-xs text-gray-400 font-medium line-clamp-2 mb-6 italic">"{res.description}"</p>
                        <div className="flex items-center justify-between border-t border-gray-50 dark:border-white/5 pt-6">
                           <div>
                              <p className="text-[9px] font-black text-gray-400 uppercase mb-1">Preço Sugerido</p>
                              <p className="font-black text-xl text-orange-600">${(res.originalPrice * markup).toFixed(2)}</p>
                           </div>
                           <button onClick={() => handleImport(res)} className="bg-black dark:bg-white dark:text-black text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase">Importar</button>
                        </div>
                     </div>
                  </div>
                ))}
              </div>
            )}
         </div>
       )}

       {/* MODAL ADICIONAR PRODUTO */}
       {isAddingProduct && (
         <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setIsAddingProduct(false)}>
            <div className="bg-white dark:bg-darkcard w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl relative" onClick={e => e.stopPropagation()}>
               <h3 className="text-2xl font-black dark:text-white uppercase mb-10">Novo Item</h3>
               <form onSubmit={handleCreateProduct} className="space-y-6">
                  <div className="grid grid-cols-2 gap-6">
                     <input type="text" required value={pName} onChange={e => setPName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold" placeholder="Nome do Produto" />
                     <input type="number" required value={pPrice} onChange={e => setPPrice(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold" placeholder="Preço ($)" />
                  </div>
                  <div className="grid grid-cols-4 gap-2">
                     {[ProductType.DIGITAL_COURSE, ProductType.DIGITAL_EBOOK, ProductType.PHYSICAL, ProductType.DIGITAL_OTHER].map(t => (
                       <button key={t} type="button" onClick={() => setPType(t)} className={`p-3 rounded-xl border-2 text-[9px] font-black uppercase ${pType === t ? 'border-blue-600 bg-blue-50 text-blue-600' : 'border-gray-50 dark:border-white/5'}`}>{t.replace('DIGITAL_', '')}</button>
                     ))}
                  </div>
                  <input type="text" value={pImg} onChange={e => setPImg(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold" placeholder="URL da Imagem" />
                  {pType !== ProductType.PHYSICAL && (
                    <input type="url" value={pDigitalUrl} onChange={e => setPDigitalUrl(e.target.value)} className="w-full p-4 bg-blue-50 dark:bg-blue-900/10 rounded-2xl outline-none font-bold text-blue-600" placeholder="Link de Acesso Digital" />
                  )}
                  <textarea value={pDesc} onChange={e => setPDesc(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none h-24 resize-none" placeholder="Descrição comercial..." />
                  <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-sm uppercase shadow-xl hover:bg-blue-700">Criar Produto</button>
               </form>
            </div>
         </div>
       )}
    </div>
  );
};

