               <div className="flex items-center gap-4 mb-6">
                  <div className="flex-1 h-3 bg-white/10 rounded-full overflow-hidden border border-white/5">
                     <div className="h-full bg-white shadow-[0_0_15px_white] transition-all duration-1000" style={{ width: `${progressPercent}%` }} />
                  </div>
                  <span className="font-black text-xs">{followerCount} / {CREATOR_UPGRADE_FOLLOWERS_GOAL}</span>
