import { 
  User, Post, UserType, Product, AffiliateSale, Notification, CartItem, 
  TransactionType, ChatConversation, AdCampaign, AudioTrack, Store, 
  Comment, NotificationType, ProductType, ShippingAddress, OrderStatus, 
  PaymentCard, CyberEvent, Story, StoryItem, ProductRating, Message
} from '../types';
import { 
  DEFAULT_USERS, DEFAULT_POSTS, DEFAULT_STORES, DEFAULT_PRODUCTS, 
  DEFAULT_AFFILIATE_SALES, DEFAULT_AUDIO_TRACKS, DEFAULT_ADS, DEFAULT_STORIES,
  CREATOR_UPGRADE_COST_USD 
} from '../constants';

const KEYS = {
  USERS: 'cyber_users',
  POSTS: 'cyber_posts',
  STORES: 'cyber_stores',
  PRODUCTS: 'cyber_products',
  SALES: 'cyber_sales',
  CHATS: 'cyber_chats',
  NOTIFICATIONS: 'cyber_notifications',
  CURRENT_USER: 'cyber_current_user_id',
  PLATFORM_STATS: 'cyber_platform_revenue',
  ADS: 'cyber_ads',
  AUDIO: 'cyber_audio',
  EVENTS: 'cyber_events',
  STORIES: 'cyber_stories',
  CART: 'cyber_cart',
  GLOBAL_SETTINGS: 'cyber_global_settings'
};

const get = <T>(key: string, fallback: T): T => {
  const data = localStorage.getItem(key);
  if (!data) return fallback;
  try {
    return JSON.parse(data);
  } catch (e) {
    console.error(`Erro ao ler chave ${key}:`, e);
    return fallback;
  }
};

const set = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

// Inicialização segura
if (!localStorage.getItem(KEYS.USERS)) set(KEYS.USERS, DEFAULT_USERS);
if (!localStorage.getItem(KEYS.POSTS)) set(KEYS.POSTS, DEFAULT_POSTS);
if (!localStorage.getItem(KEYS.CHATS)) set(KEYS.CHATS, []);
if (!localStorage.getItem(KEYS.STORES)) set(KEYS.STORES, DEFAULT_STORES);
if (!localStorage.getItem(KEYS.PRODUCTS)) set(KEYS.PRODUCTS, DEFAULT_PRODUCTS);
if (!localStorage.getItem(KEYS.SALES)) set(KEYS.SALES, DEFAULT_AFFILIATE_SALES);

export const getUsers = (): User[] => get(KEYS.USERS, []);
export const findUserById = (id: string) => getUsers().find(u => u.id === id);
export const getCurrentUserId = () => localStorage.getItem(KEYS.CURRENT_USER);
export const saveCurrentUser = (id: string | null) => id ? localStorage.setItem(KEYS.CURRENT_USER, id) : localStorage.removeItem(KEYS.CURRENT_USER);

export const loginUser = async (email: string, password: string): Promise<User> => {
  const users = getUsers();
  const user = users.find(u => u.email === email);
  if (user) return user;
  throw new Error('Credenciais inválidas.');
};

export const registerUser = async (userData: any): Promise<User> => {
  const users = getUsers();
  if (users.some(u => u.email === userData.email)) throw new Error('Email já cadastrado.');
  const newUser: User = {
    ...userData,
    id: `user-${Date.now()}`,
    followedUsers: [],
    followers: [],
    balance: 0,
  };
  set(KEYS.USERS, [...users, newUser]);
  return newUser;
};

export const updateUser = (u: User) => {
  const users = getUsers().map(x => x.id === u.id ? u : x);
  set(KEYS.USERS, users);
};

export const getChats = (): ChatConversation[] => get(KEYS.CHATS, []);
export const saveChats = (chats: ChatConversation[]) => set(KEYS.CHATS, chats);

export const getOrCreateConversation = (user1Id: string, user2Id: string): ChatConversation => {
  const chats = getChats();
  let conversation = chats.find(c => 
    (c.participants.includes(user1Id) && c.participants.includes(user2Id))
  );

  if (!conversation) {
    conversation = {
      id: `chat-${[user1Id, user2Id].sort().join('-')}`,
      participants: [user1Id, user2Id],
      messages: []
    };
    saveChats([...chats, conversation]);
  }

  if (!conversation.messages) conversation.messages = [];
  return conversation;
};

export const sendMessage = (conversationId: string, message: Message) => {
  const chats = getChats();
  const updatedChats = chats.map(chat => {
    if (chat.id === conversationId) {
      return { ...chat, messages: [...(chat.messages || []), message] };
    }
    return chat;
  });
  saveChats(updatedChats);
};

export const getPosts = (): Post[] => get(KEYS.POSTS, []);
export const savePosts = (posts: Post[]) => set(KEYS.POSTS, posts);

export const updatePostLikes = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else post.likes.push(userId);
    savePosts(posts);
  }
};

export const deletePost = (id: string) => set(KEYS.POSTS, getPosts().filter(p => p.id !== id));

export const updateUserBalance = (uId: string, amt: number) => {
  const users = getUsers();
  const u = users.find(x => x.id === uId);
  if(u) { u.balance = (u.balance || 0) + amt; set(KEYS.USERS, users); return true; }
  return false;
};

export const getAds = (): AdCampaign[] => get(KEYS.ADS, []);
export const saveAds = (ads: AdCampaign[]) => set(KEYS.ADS, ads);
export const getStories = (): Story[] => get(KEYS.STORIES, []);
export const getEvents = (): CyberEvent[] => get(KEYS.EVENTS, []);

export const toggleFollowUser = (cId: string, fId: string) => {
  const users = getUsers();
  const u1 = users.find(u => u.id === cId);
  const u2 = users.find(u => u.id === fId);
  if (u1 && u2) {
    if (u1.followedUsers.includes(fId)) {
      u1.followedUsers = u1.followedUsers.filter(x => x !== fId);
      u2.followers = u2.followers.filter(x => x !== cId);
    } else {
      u1.followedUsers.push(fId);
      u2.followers.push(cId);
    }
    set(KEYS.USERS, users);
  }
};

export const pinPost = (pId: string, uId: string) => {
    const posts = getPosts().map(p => p.userId === uId ? { ...p, isPinned: p.id === pId } : p);
    set(KEYS.POSTS, posts);
};

export const unpinPost = (pId: string, uId: string) => {
    const posts = getPosts().map(p => p.id === pId ? { ...p, isPinned: false } : p);
    set(KEYS.POSTS, posts);
};

export const updatePostSaves = (pId: string, uId: string) => {
    const posts = getPosts();
    const p = posts.find(x => x.id === pId);
    if(p) {
        if(p.saves.includes(uId)) p.saves = p.saves.filter(x => x !== uId);
        else p.saves.push(uId);
        set(KEYS.POSTS, posts);
    }
};

export const updatePostShares = (pId: string, uId: string) => {
    const posts = getPosts();
    const p = posts.find(x => x.id === pId);
    if(p) { p.shares.push(uId); set(KEYS.POSTS, posts); }
};

export const findStoreById = (id: string) => get<Store[]>(KEYS.STORES, []).find(s => s.id === id);
export const getProducts = (): Product[] => get(KEYS.PRODUCTS, []);
export const getStores = (): Store[] => get(KEYS.STORES, []);
export const updateStore = (s: Store) => set(KEYS.STORES, getStores().map(x => x.id === s.id ? s : x));
export const saveProducts = (p: Product[]) => set(KEYS.PRODUCTS, p);
export const saveStores = (s: Store[]) => set(KEYS.STORES, s);

export const getCart = (): CartItem[] => get(KEYS.CART, []);
export const saveCart = (cart: CartItem[]) => set(KEYS.CART, cart);

export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(x => x.productId === productId && x.selectedColor === selectedColor);
  if (existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};

export const removeFromCart = (productId: string) => {
  saveCart(getCart().filter(x => x.productId !== productId));
};

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) return removeFromCart(productId);
  const item = cart.find(x => x.productId === productId);
  if (item) {
    item.quantity = quantity;
    saveCart(cart);
  }
};

