export const buyPremiumSubscription = (uId: string) => {
  const users = getUsers();
  const u = users.find(x => x.id === uId);
  if (u && (u.balance || 0) >= CREATOR_UPGRADE_COST_USD) {
    u.balance -= CREATOR_UPGRADE_COST_USD;
