               placeholder="0.00"
             />
          </div>
        </div>

        {mode === 'deposit' ? (
          <>
            <div className="space-y-2.5 xs:space-y-3">
              <label className="text-[8px] xs:text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 block">Método</label>
              <div className="grid grid-cols-2 gap-2 xs:gap-3">
