  );
};

export default CryptomusPaymentForm;

import React, { useState, useMemo, useEffect } from 'react';
import { CartItem, Product, User, ShippingAddress, ProductType } from '../types';
import { getCart, updateCartItemQuantity, removeFromCart, processProductPurchase, updateUserBalance } from '../services/storageService';
import { XMarkIcon, PlusIcon, MinusIcon, TrashIcon, QrCodeIcon, BanknotesIcon, ShoppingBagIcon, ArrowRightIcon } from '@heroicons/react/24/outline';
import { CheckIcon, ShieldCheckIcon, BoltIcon, ExclamationTriangleIcon } from '@heroicons/react/24/solid';
import CryptomusPaymentForm from './CryptomusPaymentForm';

interface CartModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentUser: User;
  onCartUpdate: () => void;
  refreshUser: () => void;
}

const CartModal: React.FC<CartModalProps> = ({ isOpen, onClose, currentUser, onCartUpdate, refreshUser }) => {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [view, setView] = useState<'cart' | 'shipping' | 'payment' | 'cryptomus' | 'processing' | 'success'>('cart');
  const [shippingDetails, setShippingDetails] = useState<ShippingAddress>({ address: '', city: '', state: '', zipCode: '' });
  const [selectedPayment, setSelectedPayment] = useState<'balance' | 'pix' | 'card' | 'cryptomus' | null>(null);
  const [formError, setFormError] = useState('');

  useEffect(() => {
    if (isOpen) {
      const cart = getCart();
      const allProducts = JSON.parse(localStorage.getItem('cyber_products') || '[]') as Product[];
      setCartItems(cart);
      setProducts(allProducts);
      setView('cart');
      setFormError('');
      setSelectedPayment(null);
    }
  }, [isOpen]);

  const syncCart = () => {
    setCartItems(getCart());
    onCartUpdate();
  };

  const detailedCartItems = useMemo(() => {
    return cartItems.map(item => {
      const product = products.find(p => p.id === item.productId);
      return product ? { ...item, product } : null;
    }).filter((item): item is (CartItem & { product: Product }) => item !== null);
  }, [cartItems, products]);

  const subtotal = useMemo(() => detailedCartItems.reduce((sum, item) => sum + item.product.price * item.quantity, 0), [detailedCartItems]);

  const hasInsufficientBalance = (currentUser.balance || 0) < subtotal;

  const handleConfirmPurchase = () => {
    if (selectedPayment === 'balance' && hasInsufficientBalance) {
      setFormError('Saldo insuficiente na sua carteira CyBer.');
      return;
    }

    if (selectedPayment === 'cryptomus') {
        setView('cryptomus');
        return;
    }

    executeFinalPurchase();
  };

  const executeFinalPurchase = () => {
    setView('processing');
    setTimeout(() => {
      // Se for saldo, desconta primeiro
      if (selectedPayment === 'balance') {
         updateUserBalance(currentUser.id, -subtotal);
      }

      const success = processProductPurchase(cartItems, currentUser.id, null, shippingDetails);
      if (success) {
        refreshUser();
        onCartUpdate();
        setView('success');
      } else {
        setFormError('Erro ao processar compra.');
        setView('payment');
      }
    }, 2500);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex justify-end overflow-hidden" onClick={onClose}>
      <div 
        className="bg-white dark:bg-darkcard w-full max-w-md h-full shadow-2xl flex flex-col animate-slide-left relative" 
        onClick={e => e.stopPropagation()}
      >
        <div className="p-4 xs:p-6 border-b border-gray-100 dark:border-white/10 flex justify-between items-center bg-white dark:bg-darkcard sticky top-0 z-10">
          <div className="flex items-center gap-2 xs:gap-3">
             <div className="bg-blue-600 p-2 xs:p-2.5 rounded-xl xs:rounded-2xl shadow-lg shadow-blue-100 dark:shadow-none">
                <ShoppingBagIcon className="h-5 w-5 xs:h-6 xs:w-6 text-white" />
             </div>
             <div>
                <h2 className="text-lg xs:text-xl font-black text-gray-900 dark:text-white tracking-tighter">Minha Sacola</h2>
                <p className="text-[8px] xs:text-[10px] text-gray-400 font-bold uppercase tracking-widest">{detailedCartItems.length} Itens</p>
             </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-full transition-colors group">
            <XMarkIcon className="h-6 w-6 text-gray-400 group-hover:text-gray-900 dark:group-hover:text-white" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 xs:p-6 space-y-4 custom-scrollbar">
          {view === 'cart' && (
            <div className="space-y-3 xs:space-y-4">
              {detailedCartItems.length === 0 ? (
                <div className="text-center py-20 xs:py-24">
                  <ShoppingBagIcon className="h-10 w-10 xs:h-12 xs:w-12 text-gray-200 mx-auto mb-4" />
                  <p className="text-gray-400 font-black uppercase text-[10px] xs:text-xs">Vazio</p>
                </div>
              ) : (
                detailedCartItems.map(item => (
                  <div key={item.productId} className="flex gap-3 xs:gap-4 p-3 xs:p-4 bg-gray-50 dark:bg-white/5 rounded-[1.5rem] xs:rounded-[2rem] border border-transparent">
                    <img src={item.product.imageUrls[0]} className="w-14 h-14 xs:w-16 xs:h-16 rounded-xl object-cover" />
                    <div className="flex-1 min-w-0">
                       <p className="font-black text-xs xs:text-sm text-gray-900 dark:text-white truncate">{item.product.name}</p>
                       <p className="text-blue-600 font-black text-sm xs:text-base">${item.product.price.toFixed(2)}</p>
                       <div className="flex items-center justify-between mt-1 xs:mt-2">
                          <div className="flex items-center bg-white dark:bg-white/10 rounded-lg p-0.5 xs:p-1">
                             <button onClick={() => { updateCartItemQuantity(item.productId, item.quantity - 1); syncCart(); }} className="p-1"><MinusIcon className="h-2.5 w-2.5 xs:h-3 xs:w-3"/></button>
                             <span className="w-5 xs:w-6 text-center font-bold text-[10px] xs:text-xs">{item.quantity}</span>
                             <button onClick={() => { updateCartItemQuantity(item.productId, item.quantity + 1); syncCart(); }} className="p-1"><PlusIcon className="h-2.5 w-2.5 xs:h-3 xs:w-3"/></button>
                          </div>
                          <button onClick={() => { removeFromCart(item.productId); syncCart(); }}><TrashIcon className="h-3.5 w-3.5 xs:h-4 xs:w-4 text-gray-300 hover:text-red-500"/></button>
                       </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}

          {view === 'shipping' && (
            <div className="space-y-4 xs:space-y-6 animate-fade-in">
              <h3 className="font-black text-lg xs:text-xl text-gray-900 dark:text-white">Entrega</h3>
              <input type="text" placeholder="Endereço Completo" value={shippingDetails.address} onChange={e => setShippingDetails({...shippingDetails, address: e.target.value})} className="w-full p-3.5 xs:p-4 bg-gray-50 dark:bg-white/5 rounded-xl xs:rounded-2xl outline-none font-bold text-xs xs:text-sm" />
              <div className="grid grid-cols-1 xs:grid-cols-2 gap-3 xs:gap-4">
                 <input type="text" placeholder="Cidade" value={shippingDetails.city} onChange={e => setShippingDetails({...shippingDetails, city: e.target.value})} className="p-3.5 xs:p-4 bg-gray-50 dark:bg-white/5 rounded-xl xs:rounded-2xl outline-none font-bold text-xs xs:text-sm" />
                 <input type="text" placeholder="CEP" value={shippingDetails.zipCode} onChange={e => setShippingDetails({...shippingDetails, zipCode: e.target.value})} className="p-3.5 xs:p-4 bg-gray-50 dark:bg-white/5 rounded-xl xs:rounded-2xl outline-none font-bold text-xs xs:text-sm" />
              </div>
            </div>
          )}

          {view === 'payment' && (
            <div className="space-y-4 xs:space-y-6 animate-fade-in">
              <h3 className="font-black text-lg xs:text-xl text-gray-900 dark:text-white">Pagamento</h3>
              <div className="space-y-2 xs:space-y-3">
                <button 
                  onClick={() => setSelectedPayment('balance')} 
                  className={`w-full flex items-center justify-between p-4 xs:p-5 border-2 rounded-2xl xs:rounded-3xl transition-all relative overflow-hidden ${selectedPayment === 'balance' ? 'border-blue-600 bg-blue-50 dark:bg-blue-600/10' : 'border-gray-50 dark:border-white/5'}`}
                >
                  <div className="flex items-center gap-3 xs:gap-4">
                     <div className="p-2 xs:p-3 bg-blue-600 text-white rounded-lg xs:rounded-xl"><BanknotesIcon className="h-5 w-5 xs:h-6 xs:w-6" /></div>
                     <div className="text-left">
                        <p className="font-black text-gray-900 dark:text-white text-xs xs:text-sm">Saldo CyBer</p>
                        <p className={`text-[8px] xs:text-[10px] font-black ${hasInsufficientBalance ? 'text-red-500' : 'text-gray-400'}`}>
                          ${(currentUser.balance || 0).toFixed(2)}
                        </p>
                     </div>
                  </div>
                  {selectedPayment === 'balance' && <CheckIcon className="h-4 w-4 xs:h-5 xs:w-5 text-blue-600" />}
                </button>

                <button onClick={() => setSelectedPayment('cryptomus')} className={`w-full flex items-center justify-between p-4 xs:p-5 border-2 rounded-2xl xs:rounded-3xl transition-all ${selectedPayment === 'cryptomus' ? 'border-purple-600 bg-purple-50 dark:bg-purple-600/10' : 'border-gray-50 dark:border-white/5'}`}>
                  <div className="flex items-center gap-3 xs:gap-4">
                     <div className="p-2 xs:p-3 bg-purple-600 text-white rounded-lg xs:rounded-xl"><BoltIcon className="h-5 w-5 xs:h-6 xs:w-6" /></div>
                     <div className="text-left"><p className="font-black text-gray-900 dark:text-white text-xs xs:text-sm">Criptomoedas</p><p className="text-[8px] xs:text-[10px] text-gray-400 font-black">Cryptomus Gate</p></div>
                  </div>
                  {selectedPayment === 'cryptomus' && <CheckIcon className="h-4 w-4 xs:h-5 xs:w-5 text-purple-600" />}
                </button>
              </div>

              {hasInsufficientBalance && selectedPayment === 'balance' && (
                <div className="p-3 xs:p-4 bg-red-50 dark:bg-red-900/10 border border-red-100 rounded-xl xs:rounded-2xl flex flex-col items-center text-center gap-2 xs:gap-3">
                   <p className="text-[10px] xs:text-xs text-red-600 font-bold uppercase tracking-widest">Saldo insuficiente.</p>
                   <button onClick={() => setView('cryptomus')} className="text-[8px] xs:text-[10px] font-black text-white bg-blue-600 px-3 xs:px-4 py-1.5 xs:py-2 rounded-lg uppercase">Recarregar</button>
                </div>
              )}
              {formError && <p className="text-red-500 text-center text-[10px] xs:text-xs font-bold">{formError}</p>}
            </div>
          )}

          {view === 'cryptomus' && (
            <CryptomusPaymentForm amount={subtotal} onConfirm={executeFinalPurchase} onCancel={() => setView('payment')} />
          )}

          {view === 'processing' && (
            <div className="flex flex-col items-center justify-center h-full gap-4">
              <div className="w-10 h-10 xs:w-12 xs:h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
              <h3 className="text-lg xs:text-xl font-black">Processando...</h3>
            </div>
          )}

          {view === 'success' && (
            <div className="flex flex-col items-center justify-center h-full text-center gap-4 xs:gap-6">
              <CheckIcon className="h-12 w-12 xs:h-16 xs:w-16 text-green-500" />
              <h3 className="text-xl xs:text-2xl font-black">Compra Efetuada!</h3>
              <button onClick={onClose} className="w-full bg-blue-600 text-white py-3.5 xs:py-4 rounded-xl xs:rounded-2xl font-black">Concluir</button>
            </div>
          )}
        </div>

        {view !== 'success' && view !== 'processing' && view !== 'cryptomus' && detailedCartItems.length > 0 && (
          <div className="p-5 xs:p-8 border-t border-gray-100 dark:border-white/10">
            <div className="flex justify-between items-end mb-4 xs:mb-6">
               <span className="text-[8px] xs:text-[10px] font-black text-gray-400 uppercase tracking-widest">Total</span>
               <span className="text-2xl xs:text-3xl font-black text-gray-900 dark:text-white tracking-tighter">${subtotal.toFixed(2)}</span>
            </div>

            {view === 'cart' && (
              <button onClick={() => setView(detailedCartItems.some(i => i.product.type === ProductType.PHYSICAL) ? 'shipping' : 'payment')} className="w-full bg-blue-600 text-white py-4 xs:py-5 rounded-[1.5rem] xs:rounded-[2rem] font-black text-xs xs:text-sm flex items-center justify-center gap-2 xs:gap-3">Prosseguir <ArrowRightIcon className="h-4 w-4 xs:h-5 xs:w-5"/></button>
            )}

            {view === 'shipping' && (
              <button onClick={() => setView('payment')} className="w-full bg-blue-600 text-white py-4 xs:py-5 rounded-[1.5rem] xs:rounded-[2rem] font-black text-xs xs:text-sm flex items-center justify-center gap-2 xs:gap-3">Confirmar Entrega</button>
            )}

            {view === 'payment' && (
              <button 
                onClick={handleConfirmPurchase} 
                disabled={!selectedPayment || (selectedPayment === 'balance' && hasInsufficientBalance)} 
                className={`w-full py-4 xs:py-5 rounded-[1.5rem] xs:rounded-[2rem] font-black text-xs xs:text-sm text-white shadow-xl transition-all ${selectedPayment === 'balance' && hasInsufficientBalance ? 'bg-gray-400' : 'bg-black dark:bg-white dark:text-black'}`}
              >
                {selectedPayment === 'balance' && hasInsufficientBalance ? 'Saldo Insuficiente' : 'Pagar Agora'}
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default CartModal;

import React, { useState, useEffect, useRef } from 'react';
import { Post, User, Message } from '../types';
import { getPosts, findUserById, updateUserBalance, deletePost, getGlobalSettings } from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  XMarkIcon,
  HandRaisedIcon,
  SignalIcon,
  UsersIcon,
  ComputerDesktopIcon,
  PhotoIcon,
  PaperAirplaneIcon,
  ShieldCheckIcon,
  ShieldExclamationIcon,
  PowerIcon,
  BanknotesIcon,
  HeartIcon,
  CheckCircleIcon,
  ExclamationCircleIcon,
  ExclamationTriangleIcon,
  SparklesIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  PhotoIcon as PhotoIconOutline,
  WalletIcon,
  HandRaisedIcon as HandRaisedIconOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(false);
  const [isCamOn, setIsCamOn] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [showScreenShareSafety, setShowScreenShareSafety] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  const [activeSidebar, setActiveSidebar] = useState<'chat' | null>(null);
  const [handRaised, setHandRaised] = useState(false);
  const [handRaiseNotification, setHandRaiseNotification] = useState<{id: string, name: string} | null>(null);

  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const localVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax; // Ex: 0.1 para 10%

  useEffect(() => {
    const foundPost = getPosts().find(p => p.id === postId);
    if (foundPost && foundPost.liveStream) {
      setPost(foundPost);
      const author = findUserById(foundPost.userId);
      setCreator(author || null);
    } else {
      onNavigate('feed');
    }
    return () => stopStreams();
  }, [postId, onNavigate, currentUser.id]);

  useEffect(() => {
    let timer: number;
    if (handRaiseNotification) {
      timer = window.setTimeout(() => setHandRaiseNotification(null), 6000);
    }
    return () => clearTimeout(timer);
  }, [handRaiseNotification]);

  const stopStreams = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await (navigator.mediaDevices as any).getDisplayMedia({ video: true });
      const screenTrack = screenStream.getVideoTracks()[0];
      screenTrack.onended = () => {
        setIsScreenSharing(false);
        setIsCamOn(false);
      };
      if (streamRef.current) {
        const oldTrack = streamRef.current.getVideoTracks()[0];
        if (oldTrack) streamRef.current.removeTrack(oldTrack);
        streamRef.current.addTrack(screenTrack);
      } else {
        streamRef.current = new MediaStream([screenTrack]);
      }
      if (localVideoRef.current) localVideoRef.current.srcObject = streamRef.current;
      setIsScreenSharing(true);
      setIsCamOn(true);
      setShowScreenShareSafety(false);
    } catch (err) {
      setShowScreenShareSafety(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSelectedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim() && !selectedImage) return;

    const msg: Message = {
      id: `live-msg-${Date.now()}`,
      senderId: currentUser.id,
      receiverId: 'room',
      timestamp: Date.now(),
      text: newMessage,
      imageUrl: selectedImage || undefined
    };

    setChatMessages(prev => [...prev, msg]);
    setNewMessage('');
    setSelectedImage(null);
  };

  const prepareDonation = (amount: number) => {
    setPendingAmount(amount);
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) {
      alert("Saldo insuficiente para enviar este presente.");
      setPendingAmount(null);
      return;
    }

    setIsProcessingDonation(true);

    setTimeout(() => {
      const grossAmount = pendingAmount;
      const taxAmount = grossAmount * platformTax;
      const netAmount = grossAmount - taxAmount;

      // Aluno paga o valor cheio
      updateUserBalance(currentUser.id, -grossAmount);

      // Professor recebe o valor líquido (com o desconto da plataforma)
      updateUserBalance(creator.id, netAmount);

      refreshUser();

      // Notificação visual do apoio
      setDonationAlert({ name: currentUser.firstName, amount: grossAmount });
      setTimeout(() => setDonationAlert(null), 5000);

      const msg: Message = {
        id: `donation-msg-${Date.now()}`,
        senderId: currentUser.id,
        receiverId: 'room',
        timestamp: Date.now(),
        text: `🎁 Enviou um apoio de $${grossAmount.toFixed(2)} para o profissional!`,
      };

      setChatMessages(prev => [...prev, msg]);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
      alert(`Presente enviado! O profissional recebeu $${netAmount.toFixed(2)} líquidos.`);
    }, 1200);
  };

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) streamRef.current.getVideoTracks().forEach(track => track.stop());
      setIsCamOn(false);
      setIsScreenSharing(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ video: true });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (streamRef.current) {
          const oldTrack = streamRef.current.getVideoTracks()[0];
          if (oldTrack) streamRef.current.removeTrack(oldTrack);
          streamRef.current.addTrack(videoTrack);
        } else {
          streamRef.current = new MediaStream([videoTrack]);
        }
        if (localVideoRef.current) localVideoRef.current.srcObject = streamRef.current;
        setIsCamOn(true);
      } catch (err) {
        alert("Câmera indisponível.");
      }
    }
  };

  const toggleMic = async () => {
    if (isMicOn) {
      if (streamRef.current) streamRef.current.getAudioTracks().forEach(t => t.enabled = false);
      setIsMicOn(false);
    } else {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const audioTrack = audioStream.getAudioTracks()[0];
        if (streamRef.current) {
          streamRef.current.addTrack(audioTrack);
        } else {
          streamRef.current = new MediaStream([audioTrack]);
        }
        setIsMicOn(true);
      } catch (err) {
        alert("Microfone indisponível.");
      }
    }
  };

  const handleHandRaise = () => {
    const newState = !handRaised;
    setHandRaised(newState);
    if (newState) {
      setHandRaiseNotification({
        id: `hand-${Date.now()}`,
        name: `${currentUser.firstName} ${currentUser.lastName}`
      });
    } else {
      setHandRaiseNotification(null);
    }
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  return (
    <div className="fixed inset-0 bg-[#020408] z-[60] flex flex-col overflow-hidden text-white font-sans">

      <nav className="w-full flex items-center justify-between px-4 pt-4 pb-2 z-50 flex-shrink-0">
        <button onClick={() => onNavigate('feed')} className="p-2 bg-white/10 rounded-xl">
          <XMarkIcon className="h-5 w-5" />
        </button>
        <div className="flex flex-col items-center">
           <div className="bg-red-600 px-3 py-1 rounded-lg text-[9px] font-black flex items-center gap-2 shadow-lg">
             <SignalIcon className="h-3 w-3 animate-pulse" /> EM TRANSMISSÃO
           </div>
           <p className="text-[9px] font-black uppercase mt-1 tracking-widest text-gray-400">{post.liveStream.title}</p>
        </div>
        <div className="flex items-center gap-4">
           {isProfessional && (
             <button onClick={() => { if(window.confirm("Encerrar transmissão?")) { deletePost(post.id); onNavigate('feed'); refreshUser(); } }} className="bg-white/10 p-2 rounded-xl flex items-center gap-2 hover:bg-red-600/20 transition-colors">
                <PowerIcon className="h-4 w-4 text-red-500" />
             </button>
           )}
           <div className="flex items-center gap-2 bg-white/5 px-3 py-1.5 rounded-lg">
              <UsersIcon className="h-3 w-3 text-gray-400" />
              <span className="text-[10px] font-bold">128</span>
           </div>
        </div>
      </nav>

      <main className="flex-1 flex relative items-center justify-center overflow-hidden p-2 md:p-4">
        <div className="w-full h-full max-w-5xl rounded-[2rem] overflow-hidden bg-black border-4 border-white/5 relative shadow-2xl group">
          {isCamOn ? (
            <video ref={localVideoRef} autoPlay playsInline muted className="w-full h-full object-contain" />
          ) : (
            <div className="flex flex-col items-center justify-center h-full opacity-40 bg-gradient-to-br from-gray-900 to-black">
               <div className="w-32 h-32 rounded-[3rem] bg-gray-800 flex items-center justify-center text-5xl font-black border-4 border-white/5">
                {creator.firstName[0]}
               </div>
               <p className="mt-4 font-black uppercase tracking-widest text-[10px]">Aguardando Profissional...</p>
            </div>
          )}

          {donationAlert && (
            <div className="absolute top-10 left-1/2 -translate-x-1/2 z-[100] animate-shoutout">
               <div className="bg-gradient-to-r from-yellow-400 to-yellow-600 p-[2px] rounded-full shadow-[0_0_30px_rgba(234,179,8,0.4)]">
                  <div className="bg-black/90 backdrop-blur-xl px-8 py-3 rounded-full flex items-center gap-4">
                     <div className="bg-yellow-500 p-2 rounded-full shadow-lg">
                        <SparklesIcon className="h-5 w-5 text-black" />
                     </div>
                     <div className="text-left">
                        <p className="text-[10px] font-black text-yellow-500 uppercase tracking-[0.2em] leading-none mb-1">Novo Apoio!</p>
                        <p className="text-sm font-black text-white whitespace-nowrap">
                           <span className="text-yellow-400">{donationAlert.name}</span> enviou <span className="text-green-400">${donationAlert.amount.toFixed(2)}</span>
                        </p>
                     </div>
                  </div>
               </div>
            </div>
          )}

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/60 backdrop-blur-xl p-3 rounded-3xl border border-white/10 group-hover:translate-y-0 translate-y-20 transition-all duration-500 z-40">
             <div className="flex gap-2">
                <button onClick={toggleMic} className={`p-3 rounded-xl transition-all ${isMicOn ? 'bg-blue-600 shadow-lg shadow-blue-600/30' : 'bg-white/10 hover:bg-white/20'}`}>
                   {isMicOn ? <MicrophoneIcon className="h-5 w-5" /> : <MicrophoneIconOutline className="h-5 w-5" />}
                </button>
                <button onClick={toggleCamera} className={`p-3 rounded-xl transition-all ${isCamOn ? 'bg-blue-600 shadow-lg shadow-blue-600/30' : 'bg-white/10 hover:bg-white/20'}`}>
                   <VideoCameraIcon className="h-5 w-5" />
                </button>
                <button onClick={() => setShowScreenShareSafety(true)} className={`p-3 rounded-xl transition-all ${isScreenSharing ? 'bg-blue-600 shadow-lg shadow-blue-600/30' : 'bg-white/10 hover:bg-white/20'}`}>
                   <ComputerDesktopIcon className="h-5 w-5" />
                </button>
                <button onClick={() => setShowDonationModal(true)} className="p-3 bg-yellow-500 rounded-xl hover:bg-yellow-400 transition-all shadow-lg shadow-yellow-500/30">
                   <BanknotesIcon className="h-5 w-5 text-black" />
                </button>
             </div>
          </div>

          <div className="absolute top-6 right-6 flex flex-col gap-3">
             <button onClick={() => setActiveSidebar(activeSidebar === 'chat' ? null : 'chat')} className={`p-4 rounded-2xl backdrop-blur-xl border border-white/10 transition-all shadow-2xl ${activeSidebar === 'chat' ? 'bg-blue-600' : 'bg-black/40 hover:bg-black/60'}`}>
                <ChatBubbleLeftRightIcon className="h-6 w-6" />
             </button>
             <button onClick={handleHandRaise} className={`p-4 rounded-2xl backdrop-blur-xl border border-white/10 transition-all shadow-2xl ${handRaised ? 'bg-purple-600 animate-bounce' : 'bg-black/40 hover:bg-black/60'}`}>
                {handRaised ? <HandRaisedIcon className="h-6 w-6" /> : <HandRaisedIconOutline className="h-6 w-6" />}
             </button>
          </div>
        </div>
      </main>

      {/* MODAL DE APOIO/DOAÇÃO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-darkcard w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/10" onClick={e => e.stopPropagation()}>
              <button onClick={() => setShowDonationModal(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600"><XMarkIcon className="h-6 w-6" /></button>

              <div className="text-center mb-8">
                 <div className="bg-yellow-50 dark:bg-yellow-900/20 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4">
                    <SparklesIcon className="h-8 w-8 text-yellow-500" />
                 </div>
                 <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter">Apoiar Transmissão</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">Fortaleça o trabalho do profissional</p>
              </div>

              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button 
                    key={val} 
                    onClick={() => prepareDonation(val)}
                    className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white shadow-xl scale-105' : 'bg-gray-100 dark:bg-white/5 text-gray-500 hover:bg-gray-200'}`}
                   >
                     ${val}
                   </button>
                 ))}
              </div>

              {pendingAmount && (
                <div className="mb-8 p-4 bg-blue-50 dark:bg-blue-900/10 rounded-2xl border border-blue-100 dark:border-blue-900/30 text-center animate-fade-in">
                   <p className="text-[10px] text-blue-800 dark:text-blue-300 font-bold uppercase mb-1">Resumo do Apoio</p>
                   <div className="flex justify-between items-center text-xs font-black dark:text-white">
                      <span>Valor Bruto:</span>
                      <span>${pendingAmount.toFixed(2)}</span>
                   </div>
                   <div className="flex justify-between items-center text-[10px] text-gray-400 mt-1">
                      <span>Taxa CyBer ({(platformTax * 100).toFixed(0)}%):</span>
                      <span className="text-red-400">-${(pendingAmount * platformTax).toFixed(2)}</span>
                   </div>
                </div>
              )}

              <button 
                onClick={executeDonation}
                disabled={!pendingAmount || isProcessingDonation}
                className="w-full bg-green-600 hover:bg-green-700 text-white py-5 rounded-[1.8rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all disabled:opacity-50"
              >
                {isProcessingDonation ? 'Processando...' : 'Confirmar Apoio'}
              </button>

              <p className="text-[8px] text-gray-400 font-bold uppercase text-center mt-6 tracking-widest leading-relaxed">
                As doações ajudam a manter a plataforma CyBer ativa. <br/> Taxa de {(platformTax * 100).toFixed(0)}% inclusa.
              </p>
           </div>
        </div>
      )}

      {/* CHAT SIDEBAR */}
      {activeSidebar === 'chat' && (
        <div className="w-full md:w-96 bg-[#0a0c10] border-l border-white/5 flex flex-col animate-slide-left fixed md:relative inset-y-0 right-0 z-[70]">
           <div className="p-6 border-b border-white/5 flex items-center justify-between">
              <h3 className="text-sm font-black uppercase tracking-widest">Chat da Live</h3>
              <button onClick={() => setActiveSidebar(null)} className="p-2 hover:bg-white/5 rounded-lg"><XMarkIcon className="h-5 w-5" /></button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
              {chatMessages.map(msg => {
                const sender = findUserById(msg.senderId);
                return (
                  <div key={msg.id} className="flex gap-3 animate-fade-in">
                     <img src={sender?.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 rounded-lg shrink-0 object-cover" />
                     <div className="flex-1">
                        <p className="text-[10px] font-black text-gray-400 uppercase mb-1">{sender?.firstName || 'Membro'}</p>
                        <div className="bg-white/5 p-3 rounded-2xl text-xs font-medium leading-relaxed border border-white/5">
                           {msg.imageUrl && <img src={msg.imageUrl} className="w-full rounded-lg mb-2" />}
                           {msg.text}
                        </div>
                     </div>
                  </div>
                );
              })}
           </div>

           <div className="p-4 bg-black/40 border-t border-white/5">
              <form onSubmit={handleSendMessage} className="space-y-3">
                 {selectedImage && (
                    <div className="relative w-16 h-16 rounded-xl overflow-hidden border-2 border-blue-500">
                       <img src={selectedImage} className="w-full h-full object-cover" />
                       <button onClick={() => setSelectedImage(null)} className="absolute top-0 right-0 bg-red-600 p-0.5"><XMarkIcon className="h-3 w-3" /></button>
                    </div>
                 )}
                 <div className="flex items-center gap-2 bg-white/5 p-2 rounded-2xl border border-white/10">
                    <button type="button" onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-400 hover:text-white"><PhotoIconOutline className="h-5 w-5" /></button>
                    <input ref={fileInputRef} type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                    <input 
                      type="text" 
                      value={newMessage} 
                      onChange={e => setNewMessage(e.target.value)} 
                      placeholder="Enviar mensagem..." 
                      className="bg-transparent flex-1 text-sm outline-none px-2" 
                    />
                    <button type="submit" className="p-2 bg-blue-600 rounded-xl"><PaperAirplaneIcon className="h-4 w-4" /></button>
                 </div>
              </form>
           </div>
        </div>
      )}

      <style>{`
        .animate-slide-left { animation: slideLeft 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes slideLeft { from { transform: translateX(100%); } to { transform: translateX(0); } }

        @keyframes shoutout {
          0% { transform: translate(-50%, -100%); opacity: 0; }
          15% { transform: translate(-50%, 0); opacity: 1; }
          85% { transform: translate(-50%, 0); opacity: 1; }
          100% { transform: translate(-50%, -100%); opacity: 0; }
        }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

