  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('5.00');
  const [showRecordReel, setShowRecordReel] = useState(false);

  // Estilização
  const [fontFamily, setFontFamily] = useState('font-sans');
  const [textColor, setTextColor] = useState('#000000');
  const [fontSize, setFontSize] = useState('18px');
  const [backgroundColor, setBackgroundColor] = useState('transparent');

  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isEditing = !!postId;
  const isProfessional = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    if (postId) {
      const posts = getPosts();
      const postToEdit = posts.find(p => p.id === postId);
      if (postToEdit) {
        setPostType(postToEdit.type);
        setContent(postToEdit.content || '');
        setImageUrl(postToEdit.imageUrl || '');
        setFontFamily(postToEdit.fontFamily || 'font-sans');
        setTextColor(postToEdit.textColor || '#000000');
        setFontSize(postToEdit.fontSize || '18px');
        setBackgroundColor(postToEdit.backgroundColor || 'transparent');

        if (postToEdit.type === PostType.LIVE && postToEdit.liveStream) {
          setLiveTitle(postToEdit.liveStream.title);
          setLiveDescription(postToEdit.liveStream.description);
          setIsLivePaid(postToEdit.liveStream.isPaid);
          setLivePrice(postToEdit.liveStream.price?.toString() || '0');
        }
      }
    }
  }, [postId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const postData: Post = {
        id: isEditing ? postId! : `post-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: postType,
        timestamp: Date.now(),
        content: postType !== PostType.LIVE ? content : undefined,
        imageUrl: postType === PostType.IMAGE ? imageUrl : undefined,
        fontFamily: postType === PostType.TEXT ? fontFamily : undefined,
        textColor: postType === PostType.TEXT ? textColor : undefined,
        fontSize: postType === PostType.TEXT ? fontSize : undefined,
        backgroundColor: postType === PostType.TEXT ? backgroundColor : undefined,
        liveStream: postType === PostType.LIVE ? {
          title: liveTitle,
          description: liveDescription,
          isPaid: isLivePaid,
          price: isLivePaid ? parseFloat(livePrice) : 0
        } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };

      if (isEditing) updatePost(postData);
      else addPost(postData);

      onPostCreated();
      if (!isEditing) {
        setIsExpanded(false);
        setContent('');
        setImageUrl('');
        setLiveTitle('');
        setLiveDescription('');
        setBackgroundColor('transparent');
        setTextColor('#000000');
        setFontFamily('font-sans');
      }
    } catch (err) {
      alert('Erro ao salvar publicação.');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveReel = (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = () => {
      const videoUrl = reader.result as string;
      const newReel: Post = {
        id: `reel-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: PostType.REEL,
        timestamp: Date.now(),
        reel: {
          videoUrl: videoUrl,
          description: "Novo Reel CyBerPhone! 🚀",
          audioTrackId: audioTrackId,
          aiEffectPrompt: aiPrompt,
          filter: filter
        },
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };
      addPost(newReel);
      setLoading(false);
      setShowRecordReel(false);
      onPostCreated();
    };
    reader.readAsDataURL(videoBlob);
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2rem] shadow-sm p-4 border border-gray-100 dark:border-white/10 flex flex-col gap-3">
         <div className="flex items-start gap-3">
            <img src={currentUser.profilePicture} className="w-10 h-10 rounded-xl object-cover shrink-0" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-4 py-2.5 bg-slate-50 dark:bg-white/5 rounded-xl text-gray-400 font-bold text-xs md:text-sm">
              {isProfessional ? `Olá Profissional, o que temos para a rede hoje?` : `O que você está pensando, ${currentUser.firstName}?`}
            </button>
         </div>
         <div className="flex items-center gap-4 md:gap-6 px-1 border-t border-gray-50 dark:border-white/5 pt-2 overflow-x-auto no-scrollbar">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-2 text-gray-500 hover:text-blue-600 transition-all shrink-0">
               <PhotoIcon className="h-5 w-5 text-blue-500" />
               <span className="text-[10px] font-black uppercase tracking-widest">Mídia</span>
            </button>
            <button onClick={() => setShowRecordReel(true)} className="flex items-center gap-2 text-gray-500 hover:text-purple-600 transition-all shrink-0">
               <FilmIcon className="h-5 w-5 text-purple-500" />
               <span className="text-[10px] font-black uppercase tracking-widest">Gravar Reel</span>
            </button>
            {isProfessional && (
              <button onClick={() => { setIsExpanded(true); setPostType(PostType.LIVE); }} className="flex items-center gap-2 text-gray-500 hover:text-red-600 transition-all shrink-0">
                 <VideoCameraIcon className="h-5 w-5 text-red-500" />
                 <span className="text-[10px] font-black uppercase tracking-widest">Live</span>
              </button>
            )}
         </div>
         {showRecordReel && <RecordReelModal onClose={() => setShowRecordReel(false)} onSave={handleSaveReel} />}
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-2xl p-6 md:p-8 border border-blue-50 dark:border-white/5 animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 left-0 w-2 h-full bg-blue-600"></div>

      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
           <div className={`p-3 text-white rounded-2xl shadow-lg ${postType === PostType.LIVE ? 'bg-red-600' : 'bg-blue-600'}`}>
             {postType === PostType.LIVE ? <VideoCameraIcon className="h-6 w-6" /> : <BriefcaseIcon className="h-6 w-6" />}
           </div>
           <div>
              <h3 className="font-black text-gray-900 dark:text-white uppercase text-[10px] tracking-[0.2em]">{isEditing ? 'Editar Post' : 'Criar Conteúdo'}</h3>
              <p className="text-[8px] text-blue-500 font-black uppercase mt-0.5 tracking-widest">Editor CyBer Pro</p>
           </div>
        </div>
        <button onClick={() => setIsExpanded(false)} className="p-2 text-gray-300 hover:text-red-500 transition-colors"><XMarkIcon className="h-6 w-6" /></button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex flex-wrap gap-2 p-1.5 bg-slate-50 dark:bg-white/5 rounded-2xl w-fit">
           {[
             { id: PostType.TEXT, icon: DocumentTextIcon, label: 'Texto', locked: false },
             { id: PostType.IMAGE, icon: PhotoIcon, label: 'Mídia', locked: false },
             { id: PostType.LIVE, icon: VideoCameraIcon, label: 'Transmissão', locked: !isProfessional }
           ].map(t => (
             <button key={t.id} type="button" disabled={t.locked} onClick={() => setPostType(t.id)} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${postType === t.id ? 'bg-white dark:bg-white/10 text-blue-600 dark:text-white shadow-sm' : 'text-gray-400'} ${t.locked ? 'opacity-30' : ''}`}>
                {t.locked ? <LockClosedIcon className="h-3 w-3" /> : <t.icon className="h-4 w-4" />} {t.label}
             </button>
           ))}
        </div>

        {postType === PostType.TEXT && (
          <div className="space-y-6 animate-fade-in p-5 bg-gray-50 dark:bg-white/5 rounded-[2rem] border border-gray-100 dark:border-white/10">
             <div className="space-y-4">
                <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Tipografia (Script & Manuscritos)</p>
                <div className="flex flex-wrap gap-1.5 bg-white dark:bg-darkcard p-1.5 rounded-2xl shadow-sm">
                   {FONTS.map(f => (
                     <button 
                       key={f.id} 
                       type="button" 
                       onClick={() => setFontFamily(f.id)} 
                       className={`px-3 py-1.5 rounded-xl text-[10px] font-bold transition-all border ${fontFamily === f.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'text-gray-400 border-transparent hover:bg-gray-50 dark:hover:bg-white/5'}`}
                       style={{ fontFamily: f.id.replace('font-', '') }}
                     >
                       {f.label}
                     </button>
                   ))}
                </div>
                <div className="flex flex-wrap gap-8 items-start">
                  <div className="space-y-2">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Tamanho</p>
                    <div className="flex gap-1.5 bg-white dark:bg-darkcard p-1.5 rounded-2xl shadow-sm">
                        {SIZES.map(s => (
                          <button key={s.id} type="button" onClick={() => setFontSize(s.id)} className={`w-9 h-9 rounded-xl text-[10px] font-black flex items-center justify-center transition-all ${fontSize === s.id ? 'bg-black text-white' : 'text-gray-400 hover:bg-gray-50'}`}>{s.label}</button>
                        ))}
                    </div>
                  </div>
                  <div className="space-y-2">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Cor Texto</p>
                    <div className="flex gap-2 flex-wrap">
                        {TEXT_COLORS.map(c => (
                          <button key={c.id} type="button" onClick={() => setTextColor(c.id)} className={`w-8 h-8 rounded-full transition-all ${c.bg} ${textColor === c.id ? 'ring-2 ring-blue-500 scale-110 shadow-lg' : 'opacity-60 hover:opacity-100'}`} title={c.label}></button>
                        ))}
                    </div>
                  </div>
                  <div className="space-y-2">
                    <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Fundo do Card</p>
                    <div className="flex gap-2 flex-wrap">
                        {BG_COLORS.map(c => (
                          <button key={c.id} type="button" onClick={() => setBackgroundColor(c.id)} className={`w-8 h-8 rounded-full transition-all ${c.bg} ${backgroundColor === c.id ? 'ring-2 ring-blue-600 scale-110 shadow-lg' : 'opacity-60 hover:opacity-100'}`} title={c.label}></button>
                        ))}
                    </div>
                  </div>
                </div>
             </div>
          </div>
        )}

        {postType === PostType.LIVE ? (
          <div className="space-y-6 animate-fade-in">
            <div className="space-y-4">
              <input
                type="text"
                value={liveTitle}
                onChange={(e) => setLiveTitle(e.target.value)}
                className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-bold text-lg dark:text-white"
                placeholder="Título da Transmissão..."
                required
              />
              <textarea
                value={liveDescription}
                onChange={(e) => setLiveDescription(e.target.value)}
                className="w-full p-6 bg-slate-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-2xl outline-none font-medium text-base dark:text-white h-32 resize-none"
                placeholder="Descreva o conteúdo desta live..."
              />
            </div>

            <div className="p-6 bg-gray-50 dark:bg-white/5 rounded-[2rem] border border-gray-100 dark:border-white/10 space-y-5">
               <div className="flex items-center justify-between">
                  <div>
                    <h4 className="text-sm font-black dark:text-white uppercase tracking-tighter">Tipo de Acesso</h4>
                    <p className="text-[10px] text-gray-400 font-bold uppercase mt-0.5">Determine se haverá cobrança de ingresso</p>
                  </div>
                  <div className="flex bg-white dark:bg-darkcard p-1 rounded-xl shadow-sm border border-gray-100 dark:border-white/5">
                     <button 
                       type="button" 
                       onClick={() => setIsLivePaid(false)}
                       className={`px-6 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${!isLivePaid ? 'bg-green-500 text-white shadow-md' : 'text-gray-400'}`}
                     >
                       Grátis
                     </button>
                     <button 
                       type="button" 
                       onClick={() => setIsLivePaid(true)}
                       className={`px-6 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${isLivePaid ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400'}`}
                     >
                       Paga
                     </button>
                  </div>
               </div>

               {isLivePaid && (
                 <div className="animate-fade-in flex items-center gap-4 pt-2">
                    <div className="flex-1 space-y-2">
                       <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-1">Valor do Ingresso (USD)</label>
                       <div className="relative">
                          <BanknotesIcon className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-blue-500" />
                          <input 
                            type="number" 
                            step="0.01"
                            value={livePrice}
                            onChange={e => setLivePrice(e.target.value)}
                            className="w-full pl-12 pr-4 py-4 bg-white dark:bg-darkcard rounded-xl outline-none font-black text-lg dark:text-white border-2 border-blue-500/20 focus:border-blue-500" 
                          />
                       </div>
                    </div>
                    <div className="bg-blue-50 dark:bg-blue-900/10 p-4 rounded-xl border border-blue-100 dark:border-blue-900/20 max-w-[200px]">
                       <p className="text-[9px] text-blue-800 dark:text-blue-300 font-medium leading-tight">Alunos precisarão ter saldo para entrar na sala.</p>
                    </div>
                 </div>
               )}

               <div className="flex items-center gap-3 pt-2 text-gray-400">
                  <GiftIcon className="h-5 w-5 text-yellow-500" />
                  <p className="text-[9px] font-bold uppercase leading-tight">Botão de Doações ficará ativo em ambos os modos.</p>
               </div>
            </div>
          </div>
        ) : (
          <div className="relative group min-h-[350px]">
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className={`w-full p-10 border-4 border-transparent focus:border-blue-500/20 rounded-[2.5rem] outline-none transition-all duration-500 shadow-inner resize-none flex items-center justify-center text-center ${fontFamily}`}
              style={{ 
                color: textColor, 
                fontSize: fontSize,
                backgroundColor: backgroundColor === 'transparent' ? 'transparent' : backgroundColor,
                minHeight: '350px',
                display: backgroundColor !== 'transparent' ? 'flex' : 'block',
                fontFamily: fontFamily.replace('font-', '')
              }}
              placeholder={postType === PostType.IMAGE ? "Legenda da mídia..." : "O que você quer compartilhar hoje?"}
              required
            />

            {postType === PostType.IMAGE && (
              <div className="mt-6 space-y-4 animate-fade-in">
                <input type="file" ref={fileInputRef} onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => setImageUrl(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }} accept="image/*" className="hidden" />
                {!imageUrl ? (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full h-64 border-2 border-dashed border-gray-200 dark:border-white/10 rounded-3xl flex flex-col items-center justify-center gap-4 cursor-pointer hover:border-blue-500 transition-all">
                      <ArrowUpTrayIcon className="h-8 w-8 text-gray-400" />
                      <span className="text-[10px] font-black text-gray-400 uppercase">Fazer Upload</span>
                  </div>
                ) : (
                  <div className="relative rounded-3xl overflow-hidden border-2 border-blue-500">
                      <img src={imageUrl} className="w-full h-auto max-h-[400px] object-cover" />
                      <button onClick={() => setImageUrl('')} className="absolute top-4 right-4 p-2 bg-red-600 text-white rounded-full shadow-lg"><TrashIcon className="h-5 w-5"/></button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        <div className="flex justify-end pt-6 border-t dark:border-white/5">
           <button 
              type="submit" 
              disabled={loading || (!content && !liveTitle)} 
              className="bg-blue-600 text-white px-12 py-5 rounded-[1.8rem] font-black text-sm uppercase shadow-[0_20px_40px_rgba(37,99,235,0.4)] hover:bg-blue-700 active:scale-95 transition-all flex items-center gap-3"
           >
              {loading ? 'Postando...' : isEditing ? 'Atualizar' : 'Publicar Agora'} <ChevronRightIcon className="h-5 w-5" />
           </button>
        </div>
      </form>
    </div>
  );
};

export default CreatePost;

import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  updatePostSaves, 
  deletePost, 
  pinPost,
  unpinPost,
  updateUserBalance
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  TrashIcon, 
  CheckBadgeIcon,
  FlagIcon,
  MapPinIcon as PinIconOutline,
  VideoCameraIcon,
  SignalIcon,
  ShareIcon,
  RocketLaunchIcon,
  PencilSquareIcon,
  UserPlusIcon,
  LockClosedIcon,
  LockOpenIcon,
  CurrencyDollarIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  PlayIcon,
  BoltIcon,
  ShareIcon as ShareIconSolid,
  BanknotesIcon
} from '@heroicons/react/24/solid';
import IndicateModal from './IndicateModal';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  if (!post || !currentUser || !post.id) return null;

  const postAuthor = findUserById(post.userId);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const hasLiked = post.likes?.includes(currentUser.id) || false;
  const hasSaved = post.saves?.includes(currentUser.id) || false;
  const isAuthor = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId) || false;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleOptionsClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.innerWidth < 500) {
      setShowActionsModal(true);
    } else {
      setShowDropdown(!showDropdown);
    }
  };

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado!');
      }
      updatePostShares(post.id, currentUser.id);
      onPostUpdatedOrDeleted();
    } catch (err) {
      console.log('Share error', err);
    }
  };

  const confirmDelete = () => {
    setIsDeleting(true);
    setTimeout(() => {
      deletePost(post.id);
      setIsDeleting(false);
      setShowDeleteModal(false);
      onPostUpdatedOrDeleted();
    }, 1000);
  };

  const handlePinAction = () => {
    if (post.isPinned) unpinPost(post.id, currentUser.id);
    else pinPost(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
    setShowActionsModal(false);
    setShowDropdown(false);
  };

  const handleCardClick = () => {
    if (post.type === PostType.LIVE) {
        handleEnterLive();
    } else {
        setShowDetailModal(true);
    }
  };

  const handleEnterLive = () => {
    if (!post.liveStream) return;

    // Se for o autor ou grátis, entra direto
    if (isAuthor || !post.liveStream.isPaid) {
      onNavigate('live', { postId: post.id });
      return;
    }

    // Se for paga, processa cobrança
    const price = post.liveStream.price || 0;
    if ((currentUser.balance || 0) < price) {
       alert(`Saldo insuficiente. Esta aula custa $${price.toFixed(2)}. Recarregue sua carteira.`);
       return;
    }

    if (window.confirm(`Esta aula é restrita. Deseja pagar $${price.toFixed(2)} do seu saldo CyBer para ingressar?`)) {
       updateUserBalance(currentUser.id, -price);
       // Repassa para o professor (lógica simplificada sem taxa aqui, taxa é na doação e no saque)
       updateUserBalance(post.userId, price);
       refreshUser();
       onNavigate('live', { postId: post.id });
    }
  };

  if (!postAuthor) return null;
  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={handleCardClick}
        className={`bg-white dark:bg-darkcard rounded-[1.5rem] md:rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-4 transition-all hover:shadow-md animate-fade-in cursor-pointer group`}
      >

        <div className="p-4 md:p-6 flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-4">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-xl object-cover shadow-sm" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1 -right-1 bg-blue-600 rounded-lg p-0.5 border-2 border-white dark:border-darkcard">
                  <CheckBadgeIcon className="h-3 w-3 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-1">
                <h4 className="font-black text-gray-900 dark:text-white text-sm md:text-base truncate leading-tight hover:underline cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
                    {postAuthor.firstName}
                </h4>
                {post.isPinned && <PinIconSolid className="h-3.5 w-3.5 text-blue-500 shrink-0" />}
                {isPostBoosted && <BoltIcon className="h-3.5 w-3.5 text-orange-500 animate-pulse shrink-0" title="Impulsionado" />}
              </div>
              <p className="text-[8px] md:text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-2 text-blue-600 font-black">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 relative" ref={dropdownRef}>
            {isAuthor && !isPostBoosted && (
               <button 
                 onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); }}
                 className="hidden md:flex items-center gap-2 px-5 py-2.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-lg hover:shadow-blue-200 dark:hover:shadow-none transition-all active:scale-95"
               >
                 <RocketLaunchIcon className="h-4 w-4" /> Impulsionar
               </button>
            )}

            <button 
              onClick={handleOptionsClick} 
              className={`p-2 rounded-xl transition-all ${showDropdown || showActionsModal ? 'bg-gray-100 dark:bg-white/10 text-blue-600' : 'text-gray-300 hover:text-blue-600'}`}
            >
              <EllipsisHorizontalIcon className="h-6 w-6" />
            </button>

            {showDropdown && (
              <div className="hidden sm:block absolute right-0 top-full mt-2 w-48 bg-white dark:bg-darkcard rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 overflow-hidden z-50 animate-scale-in">
                {isAuthor ? (
                  <div className="p-1">
                    <button onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 flex items-center gap-3 rounded-xl transition-all"><RocketLaunchIcon className="h-4 w-4"/> Impulsionar</button>
                    <button onClick={(e) => { e.stopPropagation(); setShowEditModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-3 rounded-xl transition-all"><PencilSquareIcon className="h-4 w-4"/> Editar</button>
                    <button onClick={(e) => { e.stopPropagation(); handlePinAction(); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-3 rounded-xl transition-all">{post.isPinned ? <><PinIconSolid className="h-4 w-4 text-blue-500"/> Desafixar</> : <><PinIconOutline className="h-4 w-4"/> Fixar</>}</button>
                    <div className="h-px bg-gray-100 dark:bg-white/5 my-1"></div>
                    <button onClick={(e) => { e.stopPropagation(); setShowDeleteModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center gap-3 rounded-xl transition-all"><TrashIcon className="h-4 w-4"/> Eliminar</button>
                  </div>
                ) : (
                  <div className="p-1">
                    {!isFollowing && <button onClick={(e) => { e.stopPropagation(); onFollowToggle(post.userId); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 flex items-center gap-3 rounded-xl transition-all"><UserPlusIcon className="h-4 w-4"/> Seguir</button>}
                    <button onClick={(e) => { e.stopPropagation(); setShowIndicateModal(true); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-3 rounded-xl transition-all"><ShareIconSolid className="h-4 w-4 text-blue-500"/> Indicar Aula</button>
                    <button onClick={(e) => { e.stopPropagation(); onNavigate('report-user', { userId: post.userId }); setShowDropdown(false); }} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-orange-600 hover:bg-orange-50 dark:hover:bg-orange-900/20 flex items-center gap-3 rounded-xl transition-all"><FlagIcon className="h-4 w-4"/> Denunciar</button>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        <div className="px-4 md:px-6 pb-4 md:pb-6">
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden bg-gray-900 text-white p-6 md:p-12 relative shadow-2xl border-4 border-blue-600/30">
                <div className="absolute top-4 left-4 z-10 flex gap-2">
                   <div className="bg-red-600 px-3 py-1 rounded text-[8px] md:text-[10px] font-black flex items-center gap-2 shadow-lg animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3 w-3" /> Ao Vivo
                   </div>
                   {post.liveStream.isPaid ? (
                      <div className="bg-blue-600 px-3 py-1 rounded text-[8px] md:text-[10px] font-black flex items-center gap-2 shadow-lg uppercase tracking-widest">
                         <LockClosedIcon className="h-3 w-3" /> Restrito: ${post.liveStream.price?.toFixed(2)}
                      </div>
                   ) : (
                      <div className="bg-green-600 px-3 py-1 rounded text-[8px] md:text-[10px] font-black flex items-center gap-2 shadow-lg uppercase tracking-widest">
                         <LockOpenIcon className="h-3 w-3" /> Acesso Livre
                      </div>
                   )}
                </div>

                <div className="relative z-10 py-10 md:py-16 flex flex-col items-center text-center">
                   <div className="w-16 h-16 md:w-24 md:h-24 bg-blue-600/20 rounded-[2rem] flex items-center justify-center mb-6 border border-blue-500/30">
                      <VideoCameraIcon className="h-8 w-8 md:h-12 md:w-12 text-blue-400" />
                   </div>
                   <h3 className="text-xl md:text-3xl font-black mb-4 tracking-tighter leading-tight uppercase line-clamp-2">{post.liveStream.title}</h3>

                   <button 
                      onClick={(e) => { e.stopPropagation(); handleEnterLive(); }}
                      className={`${post.liveStream.isPaid && !isAuthor ? 'bg-yellow-500 text-black hover:bg-yellow-400' : 'bg-blue-600 text-white hover:bg-blue-700'} px-8 py-3 md:px-12 md:py-5 rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-[0.1em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3`}
                   >
                      {post.liveStream.isPaid && !isAuthor ? <><BanknotesIcon className="h-4 w-4 md:h-6 md:w-6" /> Pagar e Entrar</> : <><PlayIcon className="h-4 w-4 md:h-6 md:w-6" /> Ingressar na Aula</>}
                   </button>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`p-8 md:p-14 rounded-[2rem] md:rounded-[3.5rem] mb-4 transition-all duration-500 group-hover:scale-[1.005] flex items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    backgroundColor: hasBg ? post.backgroundColor : 'transparent',
                    color: post.textColor || 'inherit',
                    fontSize: post.fontSize || 'inherit',
                    minHeight: hasBg ? '280px' : 'auto',
                    border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
                    fontFamily: post.fontFamily?.replace('font-', '')
                  }}
                >
                  <p className={`font-bold leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-md' : 'text-left w-full'}`}>{post.content}</p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[1.5rem] md:rounded-[2.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-sm">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[600px]" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        <div className="px-4 md:px-8 py-3 md:py-4 flex items-center justify-between border-t dark:border-white/5">
          <div className="flex items-center gap-1 md:gap-3">
            <button onClick={handleLike} className={`flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl transition-all active:scale-90 ${hasLiked ? 'text-blue-600 bg-blue-50 dark:bg-blue-500/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {hasLiked ? <HeartIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <HeartIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
              <span className="text-xs md:text-sm font-black">{post.likes?.length || 0}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ChatIconOutline className="h-5 w-5 md:h-6 md:w-6" />
              <span className="font-black text-xs md:text-sm">{post.comments?.length || 0}</span>
            </button>
            <button onClick={handleShare} className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-50 transition-all">
              <ShareIcon className="h-5 w-5 md:h-6 md:w-6" />
            </button>
          </div>
          <button onClick={handleSave} className={`p-2.5 rounded-xl transition-all ${hasSaved ? 'text-blue-600 bg-blue-50 dark:bg-blue-900/20' : 'text-gray-300 hover:bg-gray-50'}`}>
            {hasSaved ? <BookmarkIconSolid className="h-5 w-5 md:h-6 md:w-6" /> : <BookmarkIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
          </button>
        </div>
      </div>

      {showActionsModal && (
        <PostActionsModal 
          isAuthor={isAuthor}
          isPinned={!!post.isPinned}
          isFollowing={isFollowing}
          onClose={() => setShowActionsModal(false)}
          onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }}
          onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }}
          onPin={handlePinAction}
          onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }}
          onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }}
          onIndicate={() => { setShowActionsModal(false); setShowIndicateModal(true); }}
          onReport={() => { onNavigate('report-user', { userId: post.userId }); setShowActionsModal(false); }}
        />
      )}

      {showDetailModal && (
        <PostDetailModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowDetailModal(false)}
          onUpdate={onPostUpdatedOrDeleted}
          onNavigate={onNavigate}
          refreshUser={refreshUser}
        />
      )}

      {showBoostModal && (
        <BoostPostModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowBoostModal(false)}
          onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }}
        />
      )}

      {showDeleteModal && (
        <DeleteConfirmModal 
          onClose={() => setShowDeleteModal(false)}
          onConfirm={confirmDelete}
          loading={isDeleting}
        />
      )}

      {showEditModal && (
        <EditPostModal 
          postId={post.id}
          currentUser={currentUser}
          onClose={() => setShowEditModal(false)}
          onSuccess={onPostUpdatedOrDeleted}
        />
      )}

      {showIndicateModal && (
        <IndicateModal 
          post={post} 
          currentUser={currentUser} 
          onClose={() => setShowIndicateModal(false)} 
          onPostUpdated={onPostUpdatedOrDeleted}
        />
      )}
    </>
  );
};

export default PostCard;

import React, { useState, useEffect, useRef } from 'react';
import { Post, User, Message } from '../types';
import { getPosts, findUserById, updateUserBalance, deletePost, getGlobalSettings } from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  XMarkIcon,
  HandRaisedIcon,
  SignalIcon,
  UsersIcon,
  ComputerDesktopIcon,
  PhotoIcon,
  PaperAirplaneIcon,
  ShieldCheckIcon,
  ShieldExclamationIcon,
  PowerIcon,
  BanknotesIcon,
  HeartIcon,
  CheckCircleIcon,
  ExclamationCircleIcon,
  ExclamationTriangleIcon,
  SparklesIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  PhotoIcon as PhotoIconOutline,
  WalletIcon,
  HandRaisedIcon as HandRaisedIconOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(false);
  const [isCamOn, setIsCamOn] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [showScreenShareSafety, setShowScreenShareSafety] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  const [activeSidebar, setActiveSidebar] = useState<'chat' | null>(null);
  const [handRaised, setHandRaised] = useState(false);
  const [handRaiseNotification, setHandRaiseNotification] = useState<{id: string, name: string} | null>(null);

  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const localVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax;

  useEffect(() => {
    const foundPost = getPosts().find(p => p.id === postId);
    if (foundPost && foundPost.liveStream) {
      setPost(foundPost);
      const author = findUserById(foundPost.userId);
      setCreator(author || null);
    } else {
      onNavigate('feed');
    }
    return () => stopStreams();
  }, [postId, onNavigate]);

  // Sincronização crítica: Garante que o srcObject seja atribuído quando o elemento vídeo for renderizado
  useEffect(() => {
    if (isCamOn && localVideoRef.current && streamRef.current) {
      localVideoRef.current.srcObject = streamRef.current;
    }
  }, [isCamOn]);

  useEffect(() => {
    let timer: number;
    if (handRaiseNotification) {
      timer = window.setTimeout(() => setHandRaiseNotification(null), 6000);
    }
    return () => clearTimeout(timer);
  }, [handRaiseNotification]);

  const stopStreams = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await (navigator.mediaDevices as any).getDisplayMedia({ video: true });
      const screenTrack = screenStream.getVideoTracks()[0];

      screenTrack.onended = () => {
        setIsScreenSharing(false);
        setIsCamOn(false);
      };

      if (!streamRef.current) {
        streamRef.current = new MediaStream();
      }

      const oldVideoTrack = streamRef.current.getVideoTracks()[0];
      if (oldVideoTrack) streamRef.current.removeTrack(oldVideoTrack);

      streamRef.current.addTrack(screenTrack);

      setIsScreenSharing(true);
      setIsCamOn(true);
      setShowScreenShareSafety(false);
    } catch (err) {
      console.error("Erro ao partilhar ecrã:", err);
      setShowScreenShareSafety(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setSelectedImage(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim() && !selectedImage) return;

    const msg: Message = {
      id: `live-msg-${Date.now()}`,
      senderId: currentUser.id,
      receiverId: 'room',
      timestamp: Date.now(),
      text: newMessage,
      imageUrl: selectedImage || undefined
    };

    setChatMessages(prev => [...prev, msg]);
    setNewMessage('');
    setSelectedImage(null);
  };

  const prepareDonation = (amount: number) => {
    setPendingAmount(amount);
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) {
      alert("Saldo insuficiente.");
      setPendingAmount(null);
      return;
    }

    setIsProcessingDonation(true);

    setTimeout(() => {
      const grossAmount = pendingAmount;
      const taxAmount = grossAmount * platformTax;
      const netAmount = grossAmount - taxAmount;

      updateUserBalance(currentUser.id, -grossAmount);
      updateUserBalance(creator.id, netAmount);
      refreshUser();

      setDonationAlert({ name: currentUser.firstName, amount: grossAmount });
      setTimeout(() => setDonationAlert(null), 5000);

      const msg: Message = {
        id: `donation-msg-${Date.now()}`,
        senderId: currentUser.id,
        receiverId: 'room',
        timestamp: Date.now(),
        text: `🎁 Enviou um apoio de $${grossAmount.toFixed(2)}!`,
      };

      setChatMessages(prev => [...prev, msg]);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
    }, 1200);
  };

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
      setIsScreenSharing(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
        const videoTrack = videoStream.getVideoTracks()[0];

        if (!streamRef.current) {
          streamRef.current = new MediaStream();
        }

        const oldTrack = streamRef.current.getVideoTracks()[0];
        if (oldTrack) streamRef.current.removeTrack(oldTrack);

        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
      } catch (err) {
        console.error("Câmera indisponível:", err);
        alert("Câmera indisponível. Verifique as permissões do navegador.");
      }
    }
  };

  const toggleMic = async () => {
    if (isMicOn) {
      if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => {
          track.enabled = false;
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsMicOn(false);
    } else {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const audioTrack = audioStream.getAudioTracks()[0];

        if (!streamRef.current) {
          streamRef.current = new MediaStream();
        }

        streamRef.current.addTrack(audioTrack);
        setIsMicOn(true);
      } catch (err) {
        console.error("Microfone indisponível:", err);
        alert("Microfone indisponível.");
      }
    }
  };

  const handleHandRaise = () => {
    const newState = !handRaised;
    setHandRaised(newState);
    if (newState) {
      setHandRaiseNotification({
        id: `hand-${Date.now()}`,
        name: `${currentUser.firstName} ${currentUser.lastName}`
      });
    } else {
      setHandRaiseNotification(null);
    }
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  return (
    <div className="fixed inset-0 bg-[#020408] z-[60] flex flex-col overflow-hidden text-white font-sans">

      <nav className="w-full flex items-center justify-between px-4 pt-4 pb-2 z-50 flex-shrink-0">
        <button onClick={() => onNavigate('feed')} className="p-2 bg-white/10 rounded-xl">
          <XMarkIcon className="h-5 w-5" />
        </button>
        <div className="flex flex-col items-center">
           <div className="bg-red-600 px-3 py-1 rounded-lg text-[9px] font-black flex items-center gap-2 shadow-lg">
             <SignalIcon className="h-3 w-3 animate-pulse" /> EM TRANSMISSÃO
           </div>
           <p className="text-[9px] font-black uppercase mt-1 tracking-widest text-gray-400">{post.liveStream.title}</p>
        </div>
        <div className="flex items-center gap-4">
           {isProfessional && (
             <button onClick={() => { if(window.confirm("Encerrar transmissão?")) { deletePost(post.id); onNavigate('feed'); refreshUser(); } }} className="bg-white/10 p-2 rounded-xl flex items-center gap-2 hover:bg-red-600/20 transition-colors">
                <PowerIcon className="h-4 w-4 text-red-500" />
             </button>
           )}
           <div className="flex items-center gap-2 bg-white/5 px-3 py-1.5 rounded-lg">
              <UsersIcon className="h-3 w-3 text-gray-400" />
              <span className="text-[10px] font-bold">128</span>
           </div>
        </div>
      </nav>

      <main className="flex-1 flex relative items-center justify-center overflow-hidden p-2 md:p-4">
        <div className="w-full h-full max-w-5xl rounded-[2rem] overflow-hidden bg-black border-4 border-white/5 relative shadow-2xl group">
          {isCamOn ? (
            <video 
              ref={localVideoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-contain bg-black" 
            />
          ) : (
            <div className="flex flex-col items-center justify-center h-full opacity-40 bg-gradient-to-br from-gray-900 to-black">
               <div className="w-32 h-32 rounded-[3rem] bg-gray-800 flex items-center justify-center text-5xl font-black border-4 border-white/5">
                {creator.firstName[0]}
               </div>
               <p className="mt-4 font-black uppercase tracking-widest text-[10px]">Câmara Desligada</p>
            </div>
          )}

          {donationAlert && (
            <div className="absolute top-10 left-1/2 -translate-x-1/2 z-[100] animate-shoutout">
               <div className="bg-gradient-to-r from-yellow-400 to-yellow-600 p-[2px] rounded-full shadow-[0_0_30px_rgba(234,179,8,0.4)]">
                  <div className="bg-black/90 backdrop-blur-xl px-8 py-3 rounded-full flex items-center gap-4">
                     <div className="bg-yellow-50 p-2 rounded-full shadow-lg">
                        <SparklesIcon className="h-5 w-5 text-black" />
                     </div>
                     <div className="text-left">
                        <p className="text-[10px] font-black text-yellow-500 uppercase tracking-[0.2em] leading-none mb-1">Novo Apoio!</p>
                        <p className="text-sm font-black text-white whitespace-nowrap">
                           <span className="text-yellow-400">{donationAlert.name}</span> enviou <span className="text-green-400">${donationAlert.amount.toFixed(2)}</span>
                        </p>
                     </div>
                  </div>
               </div>
            </div>
          )}

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/60 backdrop-blur-xl p-3 rounded-3xl border border-white/10 group-hover:translate-y-0 translate-y-20 transition-all duration-500 z-40">
             <div className="flex gap-2">
                <button onClick={toggleMic} className={`p-3 rounded-xl transition-all ${isMicOn ? 'bg-blue-600 shadow-lg shadow-blue-600/30' : 'bg-white/10 hover:bg-white/20'}`}>
