                <ChatBubbleLeftRightIcon className="h-6 w-6" />
             </button>
             <button onClick={handleHandRaise} className={`p-4 rounded-2xl backdrop-blur-xl border border-white/10 transition-all shadow-2xl ${handRaised ? 'bg-purple-600 animate-bounce' : 'bg-black/40 hover:bg-black/60'}`}>
                {handRaised ? <HandRaisedIcon className="h-6 w-6" /> : <HandRaisedIconOutline className="h-6 w-6" />}
             </button>
          </div>
        </div>
      </main>

      {/* MODAL DE APOIO/DOAÇÃO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-darkcard w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/10" onClick={e => e.stopPropagation()}>
              <button onClick={() => setShowDonationModal(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-600"><XMarkIcon className="h-6 w-6" /></button>

              <div className="text-center mb-8">
                 <div className="bg-yellow-50 dark:bg-yellow-900/20 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4">
                    <SparklesIcon className="h-8 w-8 text-yellow-500" />
                 </div>
                 <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter">Apoiar Transmissão</h3>
              </div>

              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button 
                    key={val} 
                    onClick={() => prepareDonation(val)}
                    className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white shadow-xl scale-105' : 'bg-gray-100 dark:bg-white/5 text-gray-500 hover:bg-gray-200'}`}
                   >
                     ${val}
                   </button>
                 ))}
              </div>

              {pendingAmount && (
                <div className="mb-8 p-4 bg-blue-50 dark:bg-blue-900/10 rounded-2xl border border-blue-100 dark:border-blue-900/30 text-center animate-fade-in">
                   <div className="flex justify-between items-center text-xs font-black dark:text-white">
                      <span>Valor:</span>
                      <span>${pendingAmount.toFixed(2)}</span>
                   </div>
                </div>
              )}

              <button 
                onClick={executeDonation}
                disabled={!pendingAmount || isProcessingDonation}
                className="w-full bg-green-600 hover:bg-green-700 text-white py-5 rounded-[1.8rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all disabled:opacity-50"
              >
                {isProcessingDonation ? 'Processando...' : 'Confirmar Apoio'}
              </button>
           </div>
        </div>
      )}

      {/* CHAT SIDEBAR */}
      {activeSidebar === 'chat' && (
        <div className="w-full md:w-96 bg-[#0a0c10] border-l border-white/5 flex flex-col animate-slide-left fixed md:relative inset-y-0 right-0 z-[70]">
           <div className="p-6 border-b border-white/5 flex items-center justify-between">
              <h3 className="text-sm font-black uppercase tracking-widest">Chat da Live</h3>
              <button onClick={() => setActiveSidebar(null)} className="p-2 hover:bg-white/5 rounded-lg"><XMarkIcon className="h-5 w-5" /></button>
           </div>

           <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
              {chatMessages.map(msg => {
                const sender = findUserById(msg.senderId);
                return (
                  <div key={msg.id} className="flex gap-3 animate-fade-in">
                     <img src={sender?.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 rounded-lg shrink-0 object-cover" />
                     <div className="flex-1">
                        <p className="text-[10px] font-black text-gray-400 uppercase mb-1">{sender?.firstName || 'Membro'}</p>
                        <div className="bg-white/5 p-3 rounded-2xl text-xs font-medium leading-relaxed border border-white/5">
                           {msg.imageUrl && <img src={msg.imageUrl} className="w-full rounded-lg mb-2" />}
                           {msg.text}
                        </div>
                     </div>
                  </div>
                );
              })}
           </div>

           <div className="p-4 bg-black/40 border-t border-white/5">
              <form onSubmit={handleSendMessage} className="space-y-3">
                 <div className="flex items-center gap-2 bg-white/5 p-2 rounded-2xl border border-white/10">
                    <input 
                      type="text" 
                      value={newMessage} 
                      onChange={e => setNewMessage(e.target.value)} 
                      placeholder="Enviar mensagem..." 
                      className="bg-transparent flex-1 text-sm outline-none px-2" 
                    />
                    <button type="submit" className="p-2 bg-blue-600 rounded-xl"><PaperAirplaneIcon className="h-4 w-4" /></button>
                 </div>
              </form>
           </div>
        </div>
      )}

      <style>{`
        .animate-slide-left { animation: slideLeft 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes slideLeft { from { transform: translateX(100%); } to { transform: translateX(0); } }

        @keyframes shoutout {
          0% { transform: translate(-50%, -100%); opacity: 0; }
          15% { transform: translate(-50%, 0); opacity: 1; }
          85% { transform: translate(-50%, 0); opacity: 1; }
          100% { transform: translate(-50%, -100%); opacity: 0; }
        }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Message } from '../types';
import { getPosts, findUserById, updateUserBalance, deletePost, getGlobalSettings } from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  XMarkIcon,
  HandRaisedIcon,
  SignalIcon,
  UsersIcon,
  ComputerDesktopIcon,
  PhotoIcon,
  PaperAirplaneIcon,
  ShieldCheckIcon,
  ShieldExclamationIcon,
  PowerIcon,
  BanknotesIcon,
  HeartIcon,
  CheckCircleIcon,
  ExclamationCircleIcon,
  ExclamationTriangleIcon,
  SparklesIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  PhotoIcon as PhotoIconOutline,
  WalletIcon,
  HandRaisedIcon as HandRaisedIconOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(false);
  const [isCamOn, setIsCamOn] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  const [activeSidebar, setActiveSidebar] = useState<'chat' | null>(null);
  const [handRaised, setHandRaised] = useState(false);

  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');

  const streamRef = useRef<MediaStream | null>(null);
  const localVideoRef = useRef<HTMLVideoElement | null>(null);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax;

  // Carregar dados iniciais
  useEffect(() => {
    const foundPost = getPosts().find(p => p.id === postId);
    if (foundPost && foundPost.liveStream) {
      setPost(foundPost);
      const author = findUserById(foundPost.userId);
      setCreator(author || null);
    } else {
      onNavigate('feed');
    }
    return () => stopStreams();
  }, [postId, onNavigate]);

  // Função crítica: Garante que o vídeo seja conectado sempre que o elemento aparecer
  const videoRefCallback = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      localVideoRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    }
  }, [isCamOn]);

  // Efeito secundário para garantir a sincronização após mudanças de UI (Chat/Modal)
  useEffect(() => {
    if (isCamOn && localVideoRef.current && streamRef.current) {
      if (localVideoRef.current.srcObject !== streamRef.current) {
        localVideoRef.current.srcObject = streamRef.current;
      }
    }
  }, [activeSidebar, showDonationModal, isCamOn]);

  const stopStreams = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await (navigator.mediaDevices as any).getDisplayMedia({ video: true });
      const screenTrack = screenStream.getVideoTracks()[0];

      screenTrack.onended = () => {
        setIsScreenSharing(false);
        setIsCamOn(false);
      };

      if (!streamRef.current) {
        streamRef.current = new MediaStream();
      }

      const oldVideoTracks = streamRef.current.getVideoTracks();
      oldVideoTracks.forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });

      streamRef.current.addTrack(screenTrack);
      setIsScreenSharing(true);
      setIsCamOn(true);
    } catch (err) {
      console.error("Falha ao partilhar ecrã:", err);
    }
  };

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
      setIsScreenSharing(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];

        if (!streamRef.current) {
          streamRef.current = new MediaStream();
        }

        const oldTracks = streamRef.current.getVideoTracks();
        oldTracks.forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });

        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
      } catch (err) {
        alert("Câmera indisponível.");
      }
    }
  };

  const toggleMic = async () => {
    if (isMicOn) {
      if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => {
          track.enabled = false;
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsMicOn(false);
    } else {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const audioTrack = audioStream.getAudioTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.addTrack(audioTrack);
        setIsMicOn(true);
      } catch (err) {
        alert("Microfone indisponível.");
      }
    }
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) {
      alert("Saldo insuficiente.");
      setPendingAmount(null);
      return;
    }

    setIsProcessingDonation(true);

    setTimeout(() => {
      updateUserBalance(currentUser.id, -pendingAmount);
      updateUserBalance(creator.id, pendingAmount * (1 - platformTax));
      refreshUser();

      setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });
      setTimeout(() => setDonationAlert(null), 5000);

      const msg: Message = {
        id: `don-${Date.now()}`,
        senderId: currentUser.id,
        receiverId: 'room',
        timestamp: Date.now(),
        text: `🎁 Enviou um apoio de $${pendingAmount.toFixed(2)}!`,
      };

      setChatMessages(prev => [...prev, msg]);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
    }, 1000);
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;
    const msg: Message = {
      id: `msg-${Date.now()}`,
      senderId: currentUser.id,
      receiverId: 'room',
      timestamp: Date.now(),
      text: newMessage
    };
    setChatMessages(prev => [...prev, msg]);
    setNewMessage('');
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  return (
    <div className="fixed inset-0 bg-[#020408] z-[60] flex flex-col overflow-hidden text-white font-sans">

      <nav className="w-full flex items-center justify-between px-4 py-3 z-50 flex-shrink-0 bg-gradient-to-b from-black/60 to-transparent">
        <button onClick={() => onNavigate('feed')} className="p-2.5 bg-white/10 rounded-2xl hover:bg-white/20 transition-all">
          <XMarkIcon className="h-5 w-5" />
        </button>
        <div className="flex flex-col items-center">
           <div className="bg-red-600 px-3 py-1 rounded-lg text-[9px] font-black flex items-center gap-2 shadow-lg animate-pulse">
             <SignalIcon className="h-3 w-3" /> EM TRANSMISSÃO
           </div>
           <p className="text-[10px] font-black uppercase mt-1 tracking-widest text-white/70">{post.liveStream.title}</p>
        </div>
        <div className="flex items-center gap-3">
           {isProfessional && (
             <button onClick={() => { if(window.confirm("Encerrar transmissão?")) { deletePost(post.id); onNavigate('feed'); refreshUser(); } }} className="bg-red-600/20 p-2.5 rounded-2xl border border-red-500/30 hover:bg-red-600 transition-all">
                <PowerIcon className="h-5 w-5 text-red-500" />
             </button>
           )}
           <div className="flex items-center gap-2 bg-white/5 px-3 py-2 rounded-xl border border-white/10">
              <UsersIcon className="h-3.5 w-3.5 text-blue-400" />
              <span className="text-[11px] font-black">1.4k</span>
           </div>
        </div>
      </nav>

      <main className="flex-1 flex relative items-center justify-center overflow-hidden p-2 md:p-6">
        <div className="w-full h-full max-w-6xl rounded-[2.5rem] md:rounded-[4rem] overflow-hidden bg-black border-4 border-white/5 relative shadow-2xl group">
          {isCamOn ? (
            <video 
              ref={videoRefCallback} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-cover bg-black" 
            />
          ) : (
            <div className="flex flex-col items-center justify-center h-full bg-gradient-to-br from-gray-900 via-black to-gray-900">
               <div className="w-32 h-32 md:w-48 md:h-48 rounded-[3.5rem] md:rounded-[5rem] bg-white/5 flex items-center justify-center text-5xl md:text-7xl font-black border-4 border-white/10 shadow-inner">
                {creator.firstName[0]}
               </div>
               <p className="mt-8 font-black uppercase tracking-[0.3em] text-[10px] md:text-xs text-white/30 animate-pulse">Aguardando Câmara...</p>
            </div>
          )}

          {donationAlert && (
            <div className="absolute top-10 left-1/2 -translate-x-1/2 z-[100] animate-shoutout">
               <div className="bg-gradient-to-r from-yellow-400 to-yellow-600 p-[2px] rounded-full shadow-[0_0_40px_rgba(234,179,8,0.5)]">
                  <div className="bg-black/95 backdrop-blur-2xl px-10 py-4 rounded-full flex items-center gap-5">
                     <div className="bg-yellow-500 p-2.5 rounded-full shadow-lg"><SparklesIcon className="h-6 w-6 text-black" /></div>
                     <div className="text-left">
                        <p className="text-[10px] font-black text-yellow-500 uppercase tracking-widest leading-none mb-1">Novo Presente!</p>
                        <p className="text-base font-black text-white whitespace-nowrap">
                           <span className="text-yellow-400">{donationAlert.name}</span> apoiou com <span className="text-green-400">${donationAlert.amount.toFixed(2)}</span>
                        </p>
                     </div>
                  </div>
               </div>
            </div>
          )}

          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/60 backdrop-blur-2xl px-6 py-4 rounded-[2.5rem] border border-white/10 group-hover:translate-y-0 translate-y-32 transition-all duration-700 z-40 shadow-2xl">
             <div className="flex gap-3">
                <button onClick={toggleMic} className={`p-4 rounded-[1.5rem] transition-all ${isMicOn ? 'bg-blue-600 shadow-lg shadow-blue-500/40' : 'bg-white/10 hover:bg-white/20'}`}>
                   {isMicOn ? <MicrophoneIcon className="h-6 w-6" /> : <MicrophoneIconOutline className="h-6 w-6" />}
                </button>
                <button onClick={toggleCamera} className={`p-4 rounded-[1.5rem] transition-all ${isCamOn ? 'bg-blue-600 shadow-lg shadow-blue-500/40' : 'bg-white/10 hover:bg-white/20'}`}>
                   <VideoCameraIcon className="h-6 w-6" />
                </button>
                <button onClick={startScreenShare} className={`p-4 rounded-[1.5rem] transition-all ${isScreenSharing ? 'bg-blue-600 shadow-lg shadow-blue-500/40' : 'bg-white/10 hover:bg-white/20'}`}>
                   <ComputerDesktopIcon className="h-6 w-6" />
                </button>
                <button onClick={() => setShowDonationModal(true)} className="p-4 bg-yellow-500 rounded-[1.5rem] hover:bg-yellow-400 transition-all shadow-xl shadow-yellow-500/30">
                   <BanknotesIcon className="h-6 w-6 text-black" />
                </button>
             </div>
          </div>

          <div className="absolute top-8 right-8 flex flex-col gap-4">
             <button onClick={() => setActiveSidebar(activeSidebar === 'chat' ? null : 'chat')} className={`p-5 rounded-[1.8rem] backdrop-blur-2xl border border-white/10 transition-all shadow-2xl ${activeSidebar === 'chat' ? 'bg-blue-600 scale-110' : 'bg-black/40 hover:bg-black/60'}`}>
                <ChatBubbleLeftRightIcon className="h-7 w-7" />
             </button>
             <button onClick={() => setHandRaised(!handRaised)} className={`p-5 rounded-[1.8rem] backdrop-blur-2xl border border-white/10 transition-all shadow-2xl ${handRaised ? 'bg-purple-600 animate-bounce' : 'bg-black/40 hover:bg-black/60'}`}>
                {handRaised ? <HandRaisedIcon className="h-7 w-7" /> : <HandRaisedIconOutline className="h-7 w-7" />}
             </button>
          </div>
        </div>
      </main>

      {/* MODAL DE APOIO/DOAÇÃO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-darkcard w-full max-w-sm rounded-[3.5rem] p-10 shadow-2xl relative border border-white/10" onClick={e => e.stopPropagation()}>
              <button onClick={() => setShowDonationModal(false)} className="absolute top-8 right-8 text-gray-400 hover:text-gray-900 dark:hover:text-white"><XMarkIcon className="h-6 w-6" /></button>

              <div className="text-center mb-10">
                 <div className="bg-yellow-50 dark:bg-yellow-500/10 w-20 h-20 rounded-[2rem] flex items-center justify-center mx-auto mb-5 shadow-inner">
                    <SparklesIcon className="h-10 w-10 text-yellow-500" />
                 </div>
                 <h3 className="text-2xl font-black dark:text-white uppercase tracking-tighter">Apoiar Profissional</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">Sua contribuição fortalece o ensino</p>
              </div>

              <div className="grid grid-cols-3 gap-3 mb-10">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button 
                    key={val} 
                    onClick={() => setPendingAmount(val)}
                    className={`py-5 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white shadow-xl scale-105' : 'bg-gray-100 dark:bg-white/5 text-gray-500 hover:bg-gray-200'}`}
                   >
                     ${val}
                   </button>
                 ))}
              </div>

              <button 
                onClick={executeDonation}
                disabled={!pendingAmount || isProcessingDonation}
                className="w-full bg-green-600 hover:bg-green-700 text-white py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all disabled:opacity-50"
              >
                {isProcessingDonation ? 'Processando...' : 'Confirmar Apoio'}
              </button>
           </div>
        </div>
      )}

      {/* CHAT SIDEBAR (OVERLAY) */}
      {activeSidebar === 'chat' && (
        <div className="w-full md:w-[420px] bg-[#0a0c10]/95 backdrop-blur-3xl border-l border-white/5 flex flex-col animate-slide-left fixed inset-y-0 right-0 z-[70] shadow-[-20px_0_50px_rgba(0,0,0,0.5)]">
           <div className="p-8 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-lg font-black uppercase tracking-widest text-white">Chat em Tempo Real</h3>
                <p className="text-[10px] text-blue-500 font-bold uppercase">Interaja com a comunidade</p>
              </div>
              <button onClick={() => setActiveSidebar(null)} className="p-3 hover:bg-white/5 rounded-2xl transition-all"><XMarkIcon className="h-6 w-6" /></button>
           </div>

           <div className="flex-1 overflow-y-auto p-6 space-y-5 custom-scrollbar">
              {chatMessages.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center opacity-20">
                    <ChatBubbleLeftRightIcon className="h-16 w-16 mb-4" />
                    <p className="font-black text-xs uppercase tracking-[0.2em]">Silêncio na sala...</p>
                 </div>
              ) : (
                chatMessages.map(msg => {
                  const sender = findUserById(msg.senderId);
                  const isMe = msg.senderId === currentUser.id;
                  return (
                    <div key={msg.id} className={`flex gap-3 animate-fade-in ${isMe ? 'flex-row-reverse' : ''}`}>
                       <img src={sender?.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl shrink-0 object-cover shadow-lg border border-white/10" />
                       <div className={`flex-1 max-w-[80%] ${isMe ? 'text-right' : ''}`}>
                          <p className="text-[10px] font-black text-gray-500 uppercase mb-1">{sender?.firstName || 'Membro'}</p>
                          <div className={`p-4 rounded-[1.5rem] text-sm font-medium leading-relaxed border ${isMe ? 'bg-blue-600 text-white border-blue-500 rounded-tr-none' : 'bg-white/5 text-white border-white/10 rounded-tl-none'}`}>
                             {msg.text}
                          </div>
                       </div>
                    </div>
                  );
                })
              )}
           </div>

           <div className="p-6 bg-black/40 border-t border-white/5">
              <form onSubmit={handleSendMessage} className="flex items-center gap-3 bg-white/5 p-2 rounded-[1.8rem] border border-white/10 focus-within:border-blue-500 transition-all">
                 <input 
                    type="text" 
                    value={newMessage} 
                    onChange={e => setNewMessage(e.target.value)} 
                    placeholder="Diga algo ao mestre..." 
                    className="bg-transparent flex-1 text-sm outline-none px-4 font-medium" 
                 />
                 <button type="submit" className="p-4 bg-blue-600 rounded-[1.4rem] shadow-xl hover:bg-blue-700 active:scale-90 transition-all">
                    <PaperAirplaneIcon className="h-5 w-5 text-white -rotate-45" />
                 </button>
              </form>
           </div>
        </div>
      )}

      <style>{`
        .animate-slide-left { animation: slideLeft 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes slideLeft { from { transform: translateX(100%); } to { transform: translateX(0); } }

        @keyframes shoutout {
          0% { transform: translate(-50%, -100%); opacity: 0; }
          15% { transform: translate(-50%, 0); opacity: 1; }
          85% { transform: translate(-50%, 0); opacity: 1; }
          100% { transform: translate(-50%, -100%); opacity: 0; }
        }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.16, 1, 0.3, 1) forwards; }

        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
      `}</style>
    </div>
  );
};

