              >
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      {/* CHAT SIDEBAR - REESTILIZADO */}
      {activeSidebar === 'chat' && (
        <div className="w-full md:w-[450px] bg-[#0a0c10]/98 backdrop-blur-3xl border-l border-white/5 flex flex-col animate-slide-left fixed inset-y-0 right-0 z-[70] shadow-[-20px_0_100px_rgba(0,0,0,0.8)]">
