              ) : (
                chatMessages.map(msg => {
                  const sender = findUserById(msg.senderId);
                  const isMe = msg.senderId === currentUser.id;
                  return (
                    <div key={msg.id} className={`flex gap-4 animate-fade-in ${isMe ? 'flex-row-reverse' : ''}`}>
                       <img src={sender?.profilePicture || DEFAULT_PROFILE_PIC} className="w-11 h-11 rounded-2xl shrink-0 object-cover shadow-xl border-2 border-white/5" />
                       <div className={`flex-1 max-w-[80%] ${isMe ? 'text-right' : ''}`}>
