                 <button type="submit" className="p-4 bg-blue-600 hover:bg-blue-700 text-white rounded-[1.8rem] shadow-xl shadow-blue-600/20 active:scale-90 transition-all flex items-center justify-center">
                    <PaperAirplaneIcon className="h-6 w-6 -rotate-45" />
                 </button>
              </form>
           </div>
        </div>
      )}

      <style>{`
        .animate-slide-left { animation: slideLeft 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes slideLeft { from { transform: translateX(100%); } to { transform: translateX(0); } }

        @keyframes shoutout {
          0% { transform: translate(-50%, -100%); opacity: 0; }
          10% { transform: translate(-50%, 0); opacity: 1; }
          90% { transform: translate(-50%, 0); opacity: 1; }
          100% { transform: translate(-50%, -100%); opacity: 0; }
