const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  if (!post || !currentUser || !post.id) return null;

  const postAuthor = findUserById(post.userId);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const hasLiked = post.likes?.includes(currentUser.id) || false;
  const hasSaved = post.saves?.includes(currentUser.id) || false;
  const isAuthor = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId) || false;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleOptionsClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.innerWidth < 500) {
      setShowActionsModal(true);
    } else {
      setShowDropdown(!showDropdown);
    }
  };

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado!');
      }
      updatePostShares(post.id, currentUser.id);
      onPostUpdatedOrDeleted();
    } catch (err) {
      console.log('Share error', err);
    }
  };

  const confirmDelete = () => {
    setIsDeleting(true);
    setTimeout(() => {
      deletePost(post.id);
      setIsDeleting(false);
      setShowDeleteModal(false);
      onPostUpdatedOrDeleted();
    }, 1000);
  };

  const handlePinAction = () => {
    if (post.isPinned) unpinPost(post.id, currentUser.id);
    else pinPost(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
    setShowActionsModal(false);
    setShowDropdown(false);
  };

  const handleCardClick = () => {
    if (post.type === PostType.LIVE) {
        handleEnterLive();
    } else {
        setShowDetailModal(true);
    }
  };

  const handleEnterLive = () => {
    if (!post.liveStream) return;

    if (isAuthor || !post.liveStream.isPaid) {
      onNavigate('live', { postId: post.id });
      return;
    }

    const price = post.liveStream.price || 0;
    if ((currentUser.balance || 0) < price) {
       alert(`Saldo insuficiente. Esta aula custa $${price.toFixed(2)}.`);
       return;
    }

    if (window.confirm(`Deseja pagar $${price.toFixed(2)} do seu saldo CyBer para ingressar nesta aula mestre?`)) {
       updateUserBalance(currentUser.id, -price);
       updateUserBalance(post.userId, price);
       refreshUser();
       onNavigate('live', { postId: post.id });
    }
  };

  if (!postAuthor) return null;
  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={handleCardClick}
        className={`bg-white dark:bg-darkcard rounded-[2rem] md:rounded-[3rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-6 transition-all hover:shadow-2xl hover:-translate-y-1 animate-fade-in cursor-pointer group`}
      >

        <div className="p-5 md:p-8 flex items-center justify-between">
          <div className="flex items-center gap-4 md:gap-5">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 md:w-16 md:h-16 rounded-[1.2rem] md:rounded-[1.8rem] object-cover shadow-lg border-2 border-white dark:border-white/10" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1.5 -right-1.5 bg-blue-600 rounded-xl p-1 border-2 border-white dark:border-darkcard shadow-md">
                  <CheckBadgeIcon className="h-4 w-4 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-2">
                <h4 className="font-black text-gray-900 dark:text-white text-base md:text-xl truncate tracking-tighter hover:text-blue-600 transition-colors" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
                    {postAuthor.firstName}
                </h4>
                {post.isPinned && <PinIconSolid className="h-4 w-4 text-blue-500 shrink-0" />}
                {isPostBoosted && <BoltIcon className="h-4 w-4 text-orange-500 animate-pulse shrink-0" />}
              </div>
              <p className="text-[9px] md:text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mt-0.5">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-3 text-blue-600">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3 relative" ref={dropdownRef}>
            {isAuthor && !isPostBoosted && (
               <button 
                 onClick={(e) => { e.stopPropagation(); setShowBoostModal(true); }}
                 className="hidden lg:flex items-center gap-3 px-6 py-3.5 bg-gradient-to-r from-blue-600 via-indigo-600 to-indigo-700 text-white rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest shadow-xl shadow-blue-500/20 hover:brightness-110 transition-all active:scale-95"
               >
                 <RocketLaunchIcon className="h-4.5 w-4.5" /> Impulsionar
               </button>
            )}

            <button 
              onClick={handleOptionsClick} 
              className={`p-3 rounded-2xl transition-all ${showDropdown || showActionsModal ? 'bg-blue-600 text-white shadow-xl' : 'bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-blue-600'}`}
            >
              <EllipsisHorizontalIcon className="h-7 w-7" />
            </button>
          </div>
        </div>

        <div className="px-5 md:px-8 pb-5 md:pb-8">
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[2.5rem] md:rounded-[3.5rem] overflow-hidden bg-gray-900 text-white p-8 md:p-16 relative shadow-2xl border-4 border-white/5">
                <div className="absolute inset-0 bg-gradient-to-br from-indigo-900/40 via-transparent to-black opacity-60"></div>
                <div className="absolute top-6 left-6 z-10 flex gap-3">
                   <div className="bg-red-600 px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-2 shadow-2xl animate-pulse border border-red-400/30 uppercase tracking-widest">
                      <SignalIcon className="h-3.5 w-3.5" /> Ao Vivo
                   </div>
                   {post.liveStream.isPaid ? (
                      <div className="bg-blue-600/90 backdrop-blur-md px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-2 shadow-2xl border border-blue-400/30 uppercase tracking-widest">
                         <LockClosedIcon className="h-3.5 w-3.5" /> Mestre: ${post.liveStream.price?.toFixed(2)}
                      </div>
                   ) : (
                      <div className="bg-green-600/90 backdrop-blur-md px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-2 shadow-2xl border border-green-400/30 uppercase tracking-widest">
                         <LockOpenIcon className="h-3.5 w-3.5" /> Livre
                      </div>
                   )}
                </div>

                <div className="relative z-10 py-8 flex flex-col items-center text-center">
                   <div className="w-20 h-20 md:w-28 md:h-28 bg-white/5 backdrop-blur-xl rounded-[2.5rem] md:rounded-[3rem] flex items-center justify-center mb-8 border border-white/10 shadow-inner group-hover:scale-110 transition-transform duration-500">
                      <VideoCameraIcon className="h-10 w-10 md:h-14 md:w-14 text-blue-400" />
                   </div>
                   <h3 className="text-2xl md:text-4xl font-black mb-8 tracking-tighter leading-tight uppercase line-clamp-2 max-w-2xl">{post.liveStream.title}</h3>

                   <button 
                      onClick={(e) => { e.stopPropagation(); handleEnterLive(); }}
                      className={`relative overflow-hidden group/btn px-10 py-5 md:px-16 md:py-6 rounded-[2.2rem] font-black text-[11px] md:text-sm uppercase tracking-[0.2em] shadow-[0_25px_50px_-12px_rgba(37,99,235,0.5)] transition-all active:scale-90 flex items-center justify-center gap-4 ${post.liveStream.isPaid && !isAuthor ? 'bg-gradient-to-r from-yellow-400 via-amber-500 to-yellow-600 text-black' : 'bg-gradient-to-r from-blue-600 via-blue-500 to-indigo-600 text-white'}`}
                   >
                      <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover/btn:translate-x-[100%] transition-transform duration-1000 skew-x-[-20deg]"></div>
                      {post.liveStream.isPaid && !isAuthor ? <><BanknotesIcon className="h-6 w-6" /> Pagar e Entrar</> : <><PlayIcon className="h-6 w-6" /> Entrar na Sala</>}
                   </button>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`p-10 md:p-20 rounded-[2.5rem] md:rounded-[4rem] mb-6 transition-all duration-700 group-hover:scale-[1.01] flex items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    backgroundColor: hasBg ? post.backgroundColor : 'transparent',
                    color: post.textColor || 'inherit',
                    fontSize: post.fontSize ? `calc(${post.fontSize} * 1.1)` : '1.2rem',
                    minHeight: hasBg ? '320px' : 'auto',
                    border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
                    fontFamily: post.fontFamily?.replace('font-', '')
                  }}
                >
                  <p className={`font-black leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-xl' : 'text-left w-full'}`}>{post.content}</p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-xl">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[700px] transition-transform duration-1000 group-hover:scale-105" alt="Post" />
                   <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>
                </div>
              )}
            </>
          )}
        </div>

        <div className="px-6 md:px-12 py-5 md:py-8 flex items-center justify-between border-t border-gray-50 dark:border-white/5">
          <div className="flex items-center gap-2 md:gap-5">
            <button onClick={handleLike} className={`flex items-center gap-3 px-5 md:px-7 py-3 md:py-4 rounded-[1.5rem] transition-all active:scale-75 ${hasLiked ? 'text-blue-600 bg-blue-50 dark:bg-blue-600/10 font-black shadow-inner shadow-blue-200/20' : 'text-gray-400 hover:bg-gray-50 dark:hover:bg-white/5'}`}>
              {hasLiked ? <HeartIconSolid className="h-6 w-6 md:h-8 md:w-8" /> : <HeartIconOutline className="h-6 w-6 md:h-8 md:w-8" />}
              <span className="text-xs md:text-base font-black">{post.likes?.length || 0}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-3 px-5 md:px-7 py-3 md:py-4 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 dark:hover:bg-white/5 transition-all active:scale-90">
              <ChatIconOutline className="h-6 w-6 md:h-8 md:w-8" />
              <span className="font-black text-xs md:text-base">{post.comments?.length || 0}</span>
            </button>
            <button onClick={handleShare} className="p-4 md:p-5 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 dark:hover:bg-white/5 transition-all active:scale-90">
              <ShareIcon className="h-6 w-6 md:h-8 md:w-8" />
            </button>
          </div>
          <button onClick={handleSave} className={`p-4 md:p-5 rounded-[1.5rem] transition-all active:scale-90 ${hasSaved ? 'text-blue-600 bg-blue-50 dark:bg-blue-600/10 shadow-inner shadow-blue-200/20' : 'text-gray-300 hover:bg-gray-50'}`}>
            {hasSaved ? <BookmarkIconSolid className="h-6 w-6 md:h-8 md:w-8" /> : <BookmarkIconOutline className="h-6 w-6 md:h-8 md:w-8" />}
          </button>
        </div>
      </div>

      {showActionsModal && (
        <PostActionsModal 
          isAuthor={isAuthor}
          isPinned={!!post.isPinned}
          isFollowing={isFollowing}
          onClose={() => setShowActionsModal(false)}
          onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }}
          onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }}
          onPin={handlePinAction}
          onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }}
          onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }}
          onIndicate={() => { setShowActionsModal(false); setShowIndicateModal(true); }}
          onReport={() => { onNavigate('report-user', { userId: post.userId }); setShowActionsModal(false); }}
        />
      )}

      {showDetailModal && (
        <PostDetailModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowDetailModal(false)}
          onUpdate={onPostUpdatedOrDeleted}
          onNavigate={onNavigate}
          refreshUser={refreshUser}
        />
      )}

      {showBoostModal && (
        <BoostPostModal
          post={post}
          currentUser={currentUser}
          onClose={() => setShowBoostModal(false)}
          onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }}
        />
      )}

      {showDeleteModal && (
        <DeleteConfirmModal 
          onClose={() => setShowDeleteModal(false)}
          onConfirm={confirmDelete}
          loading={isDeleting}
        />
      )}

      {showEditModal && (
        <EditPostModal 
          postId={post.id}
          currentUser={currentUser}
          onClose={() => setShowEditModal(false)}
          onSuccess={onPostUpdatedOrDeleted}
        />
      )}

      {showIndicateModal && (
        <IndicateModal 
          post={post} 
          currentUser={currentUser} 
          onClose={() => setShowIndicateModal(false)} 
          onPostUpdated={onPostUpdatedOrDeleted}
        />
      )}
    </>
  );
};

export default PostCard;

import React, { useState, useEffect, useRef } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { addPost, updatePost, getPosts } from '../services/storageService';
import RecordReelModal from './RecordReelModal';
import { 
  VideoCameraIcon, 
  PhotoIcon, 
  XMarkIcon,
  DocumentTextIcon,
  LockClosedIcon,
  FilmIcon,
  ArrowUpTrayIcon,
  TrashIcon,
  ChevronRightIcon,
  BriefcaseIcon,
  PaintBrushIcon,
  SwatchIcon,
  BanknotesIcon,
  GiftIcon,
  LockOpenIcon
} from '@heroicons/react/24/solid';

