                          <input 
                            type="number" 
                            step="0.01"
                            value={livePrice}
                            onChange={e => setLivePrice(e.target.value)}
                            className="w-full pl-16 pr-6 py-6 bg-white dark:bg-darkcard rounded-[1.8rem] outline-none font-black text-2xl dark:text-white border-2 border-blue-500/20 focus:border-blue-500 transition-all shadow-xl" 
                          />
                       </div>
                    </div>
                    <div className="bg-blue-600 p-6 rounded-[2rem] shadow-xl text-white max-w-xs">
                       <p className="text-[11px] font-black uppercase tracking-widest leading-relaxed">O saldo será creditado automaticamente na sua carteira após cada entrada.</p>
                    </div>
                 </div>
               )}
            </div>
          </div>
        ) : (
          <div className="relative group min-h-[400px]">
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className={`w-full p-12 border-4 border-transparent focus:border-blue-500/10 rounded-[3.5rem] outline-none transition-all duration-500 shadow-inner resize-none flex items-center justify-center text-center ${fontFamily}`}
              style={{ 
                color: textColor, 
                fontSize: fontSize,
                backgroundColor: backgroundColor === 'transparent' ? 'transparent' : backgroundColor,
                minHeight: '400px',
                display: backgroundColor !== 'transparent' ? 'flex' : 'block',
                fontFamily: fontFamily.replace('font-', '')
              }}
              placeholder={postType === PostType.IMAGE ? "Descreva esta mídia..." : "Partilhe algo importante com a rede..."}
              required
            />

            {postType === PostType.IMAGE && (
              <div className="mt-8 space-y-5 animate-fade-in">
                <input type="file" ref={fileInputRef} onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => setImageUrl(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }} accept="image/*" className="hidden" />
                {!imageUrl ? (
                  <div onClick={() => fileInputRef.current?.click()} className="w-full h-80 border-4 border-dashed border-gray-100 dark:border-white/5 rounded-[3rem] flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-all group">
                      <div className="p-6 bg-gray-50 dark:bg-white/5 rounded-full group-hover:scale-110 transition-transform"><ArrowUpTrayIcon className="h-12 w-12 text-gray-300 group-hover:text-blue-600" /></div>
                      <span className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em]">Carregar do Dispositivo</span>
                  </div>
                ) : (
                  <div className="relative rounded-[3rem] overflow-hidden border-4 border-blue-500 shadow-2xl">
                      <img src={imageUrl} className="w-full h-auto max-h-[500px] object-cover" />
                      <button onClick={() => setImageUrl('')} className="absolute top-6 right-6 p-3 bg-red-600 text-white rounded-full shadow-2xl active:scale-75 transition-all hover:bg-red-700"><TrashIcon className="h-6 w-6"/></button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        <div className="flex justify-end pt-10 border-t border-gray-50 dark:border-white/5">
           <button 
              type="submit" 
              disabled={loading || (!content && !liveTitle && !imageUrl)} 
              className="relative overflow-hidden group/btn bg-gradient-to-r from-blue-600 via-indigo-600 to-indigo-700 text-white px-16 py-6 rounded-[2.5rem] font-black text-sm uppercase shadow-[0_25px_50px_-12px_rgba(37,99,235,0.4)] hover:brightness-110 active:scale-95 transition-all flex items-center gap-4 disabled:opacity-30 disabled:grayscale"
           >
              <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover/btn:translate-x-[100%] transition-transform duration-1000 skew-x-[-20deg]"></div>
              {loading ? 'Processando...' : isEditing ? 'Atualizar Conhecimento' : 'Publicar na Rede'} 
              <ChevronRightIcon className="h-6 w-6" />
           </button>
        </div>
      </form>
    </div>
  );
};

export default CreatePost;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Message } from '../types';
import { getPosts, findUserById, updateUserBalance, deletePost, getGlobalSettings } from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  XMarkIcon,
  HandRaisedIcon,
  SignalIcon,
  UsersIcon,
  ComputerDesktopIcon,
  PowerIcon,
  BanknotesIcon,
  PaperAirplaneIcon,
  SparklesIcon,
  PlayIcon,
  PauseIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedIconOutline,
  ChatBubbleLeftRightIcon as ChatIconOutline,
  ComputerDesktopIcon as ScreenIconOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(false);
  const [isCamOn, setIsCamOn] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  const [activeSidebar, setActiveSidebar] = useState<'chat' | null>(null);
  const [handRaised, setHandRaised] = useState(false);

  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax;

  // Carrega os dados da live e do criador
  useEffect(() => {
    const foundPost = getPosts().find(p => p.id === postId);
    if (foundPost && foundPost.liveStream) {
      setPost(foundPost);
      const author = findUserById(foundPost.userId);
      setCreator(author || null);
    } else {
      onNavigate('feed');
    }
    return () => stopStreams();
  }, [postId, onNavigate]);

  // Callback Ref: Crucial para garantir que o srcObject seja atribuído sempre que o vídeo renderiza/remonta
  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  // Efeito de re-sincronização automática quando o estado de visibilidade muda (ex: chat abre)
  useEffect(() => {
    if (isCamOn && videoElementRef.current && streamRef.current) {
      if (videoElementRef.current.srcObject !== streamRef.current) {
        videoElementRef.current.srcObject = streamRef.current;
      }
    }
  }, [activeSidebar, showDonationModal, isCamOn]);

  const stopStreams = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
  };

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
      setIsScreenSharing(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];

        if (!streamRef.current) {
          streamRef.current = new MediaStream();
        }

        const oldTracks = streamRef.current.getVideoTracks();
        oldTracks.forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });

        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
      } catch (err) {
        alert("Câmera indisponível.");
      }
    }
  };

  const toggleMic = async () => {
    if (isMicOn) {
      if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => {
          track.enabled = false;
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsMicOn(false);
    } else {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const audioTrack = audioStream.getAudioTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.addTrack(audioTrack);
        setIsMicOn(true);
      } catch (err) {
        alert("Microfone indisponível.");
      }
    }
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await (navigator.mediaDevices as any).getDisplayMedia({ video: true });
      const screenTrack = screenStream.getVideoTracks()[0];

      screenTrack.onended = () => {
        setIsScreenSharing(false);
        setIsCamOn(false);
      };

      if (!streamRef.current) streamRef.current = new MediaStream();
      const oldVideoTracks = streamRef.current.getVideoTracks();
      oldVideoTracks.forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });

      streamRef.current.addTrack(screenTrack);
      setIsScreenSharing(true);
      setIsCamOn(true);
    } catch (err) {
      console.error("Erro ao partilhar ecrã:", err);
    }
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;
    const msg: Message = { id: `msg-${Date.now()}`, senderId: currentUser.id, receiverId: 'room', timestamp: Date.now(), text: newMessage };
    setChatMessages(prev => [...prev, msg]);
    setNewMessage('');
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) {
      alert("Saldo insuficiente.");
      return;
    }

    setIsProcessingDonation(true);
    setTimeout(() => {
      updateUserBalance(currentUser.id, -pendingAmount);
      updateUserBalance(creator.id, pendingAmount * (1 - platformTax));
      refreshUser();
      setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });
      setTimeout(() => setDonationAlert(null), 5000);
      const msg: Message = { id: `don-${Date.now()}`, senderId: currentUser.id, receiverId: 'room', timestamp: Date.now(), text: `🎁 Enviou um apoio de $${pendingAmount.toFixed(2)}!` };
      setChatMessages(prev => [...prev, msg]);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
    }, 1000);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  const controlBtnClass = "p-5 rounded-3xl backdrop-blur-xl border border-white/10 transition-all active:scale-90 shadow-xl flex flex-col items-center gap-1 group";
  const activeControlClass = "bg-blue-600 text-white shadow-blue-500/40 border-blue-400/30";
  const inactiveControlClass = "bg-black/40 text-white/70 hover:bg-black/60 hover:text-white";

  return (
    <div className="fixed inset-0 bg-[#020408] z-[60] flex flex-col overflow-hidden text-white font-sans">

      {/* BARRA DE TÍTULO SUPERIOR */}
      <nav className="w-full flex items-center justify-between px-6 py-4 z-50 flex-shrink-0 bg-gradient-to-b from-black/80 to-transparent">
        <button 
          onClick={() => onNavigate('feed')} 
          className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/10 transition-all active:scale-90"
        >
          <XMarkIcon className="h-6 w-6" />
        </button>

        <div className="flex flex-col items-center">
           <div className="bg-red-600 px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-2 shadow-[0_0_20px_rgba(220,38,38,0.4)] animate-pulse border border-red-500/50 uppercase tracking-widest">
             <SignalIcon className="h-3.5 w-3.5" /> AO VIVO
           </div>
           <p className="text-[11px] font-black uppercase mt-2 tracking-[0.2em] text-white/60">{post.liveStream.title}</p>
        </div>

        <div className="flex items-center gap-4">
           {isProfessional && (
             <button 
               onClick={() => { if(window.confirm("Encerrar transmissão?")) { deletePost(post.id); onNavigate('feed'); refreshUser(); } }} 
               className="bg-red-600 hover:bg-red-700 text-white p-3 rounded-2xl shadow-xl shadow-red-600/20 border border-red-500 transition-all active:scale-90"
             >
                <PowerIcon className="h-6 w-6" />
             </button>
           )}
           <div className="flex items-center gap-3 bg-white/5 px-4 py-2.5 rounded-2xl border border-white/10 backdrop-blur-md">
              <UsersIcon className="h-4 w-4 text-blue-400" />
              <span className="text-xs font-black">1.4k</span>
           </div>
        </div>
      </nav>

      {/* ÁREA PRINCIPAL DO VÍDEO */}
      <main className="flex-1 flex relative items-center justify-center overflow-hidden p-2 md:p-8">
        <div className="w-full h-full max-w-6xl rounded-[3rem] md:rounded-[4.5rem] overflow-hidden bg-black border-4 border-white/5 relative shadow-2xl group">

          {isCamOn ? (
            <video 
              ref={setVideoRef} 
              autoPlay 
              playsInline 
              muted 
              className="w-full h-full object-cover bg-black" 
            />
          ) : (
            <div className="flex flex-col items-center justify-center h-full bg-gradient-to-br from-[#0a0c10] via-black to-[#0a0c10]">
               <div className="w-32 h-32 md:w-56 md:h-56 rounded-[4rem] md:rounded-[6rem] bg-white/5 flex items-center justify-center text-6xl md:text-8xl font-black border-4 border-white/10 shadow-inner relative overflow-hidden">
                  <span className="opacity-20 z-0">{creator.firstName[0]}</span>
                  <div className="absolute inset-0 border-4 border-blue-500/10 animate-ping rounded-full"></div>
               </div>
               <p className="mt-10 font-black uppercase tracking-[0.4em] text-[10px] md:text-xs text-white/20 animate-pulse">Câmara Desligada</p>
            </div>
          )}

          {/* ALERTA DE DOAÇÃO (SHOUTOUT) */}
          {donationAlert && (
            <div className="absolute top-10 left-1/2 -translate-x-1/2 z-[100] animate-shoutout">
               <div className="bg-gradient-to-r from-yellow-400 via-amber-500 to-yellow-600 p-[2px] rounded-full shadow-[0_0_50px_rgba(234,179,8,0.6)]">
                  <div className="bg-black/95 backdrop-blur-3xl px-12 py-5 rounded-full flex items-center gap-6">
                     <div className="bg-gradient-to-tr from-yellow-500 to-amber-300 p-3 rounded-full shadow-lg"><SparklesIcon className="h-7 w-7 text-black" /></div>
                     <div className="text-left">
                        <p className="text-[11px] font-black text-yellow-500 uppercase tracking-[0.2em] mb-1.5">Apoio Recebido!</p>
                        <p className="text-lg font-black text-white whitespace-nowrap">
                           <span className="text-yellow-400">{donationAlert.name}</span> enviou <span className="text-green-400">${donationAlert.amount.toFixed(2)}</span>
                        </p>
                     </div>
                  </div>
               </div>
            </div>
          )}

          {/* BARRA DE CONTROLES INFERIOR */}
          <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-5 bg-black/40 backdrop-blur-3xl px-8 py-5 rounded-[3rem] border border-white/10 group-hover:translate-y-0 translate-y-32 transition-all duration-700 z-40 shadow-2xl">
             <div className="flex gap-4">
                <button 
                  onClick={toggleMic} 
                  className={`${controlBtnClass} ${isMicOn ? activeControlClass : inactiveControlClass}`}
                >
                   {isMicOn ? <MicrophoneIcon className="h-7 w-7" /> : <MicrophoneIconOutline className="h-7 w-7" />}
                   <span className="text-[8px] font-black uppercase tracking-widest">{isMicOn ? 'On' : 'Off'}</span>
                </button>
                <button 
                  onClick={toggleCamera} 
                  className={`${controlBtnClass} ${isCamOn ? activeControlClass : inactiveControlClass}`}
                >
                   {isCamOn ? <VideoCameraIcon className="h-7 w-7" /> : <VideoCameraIconOutline className="h-7 w-7" />}
                   <span className="text-[8px] font-black uppercase tracking-widest">{isCamOn ? 'On' : 'Off'}</span>
                </button>
                <button 
                  onClick={startScreenShare} 
                  className={`${controlBtnClass} ${isScreenSharing ? activeControlClass : inactiveControlClass}`}
                >
                   {isScreenSharing ? <ComputerDesktopIcon className="h-7 w-7" /> : <ScreenIconOutline className="h-7 w-7" />}
                   <span className="text-[8px] font-black uppercase tracking-widest">Ecrã</span>
                </button>
                <div className="w-px h-12 bg-white/10 self-center mx-2"></div>
                <button 
                  onClick={() => setShowDonationModal(true)} 
                  className="p-5 bg-gradient-to-tr from-yellow-500 to-amber-600 text-black rounded-3xl hover:brightness-110 transition-all shadow-xl shadow-yellow-500/20 active:scale-90 flex flex-col items-center gap-1"
                >
                   <BanknotesIcon className="h-7 w-7" />
                   <span className="text-[8px] font-black uppercase tracking-widest">Apoiar</span>
                </button>
             </div>
          </div>

          {/* BOTÕES LATERAIS (CHAT / MÃO) */}
          <div className="absolute top-10 right-10 flex flex-col gap-5">
             <button 
               onClick={() => setActiveSidebar(activeSidebar === 'chat' ? null : 'chat')} 
               className={`p-6 rounded-[2rem] backdrop-blur-3xl border border-white/10 transition-all shadow-2xl active:scale-90 ${activeSidebar === 'chat' ? 'bg-blue-600 text-white shadow-blue-600/40' : 'bg-black/40 text-white/70 hover:bg-black/60'}`}
             >
                {activeSidebar === 'chat' ? <ChatBubbleLeftRightIcon className="h-8 w-8" /> : <ChatIconOutline className="h-8 w-8" />}
             </button>
             <button 
               onClick={() => setHandRaised(!handRaised)} 
               className={`p-6 rounded-[2rem] backdrop-blur-3xl border border-white/10 transition-all shadow-2xl active:scale-90 ${handRaised ? 'bg-purple-600 text-white animate-bounce shadow-purple-600/40' : 'bg-black/40 text-white/70 hover:bg-black/60'}`}
             >
                {handRaised ? <HandRaisedIcon className="h-8 w-8" /> : <HandRaisedIconOutline className="h-8 w-8" />}
             </button>
          </div>
        </div>
      </main>

      {/* MODAL DE APOIO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-[#12141c] w-full max-w-md rounded-[4rem] p-12 shadow-2xl relative border border-white/5" onClick={e => e.stopPropagation()}>
              <button onClick={() => setShowDonationModal(false)} className="absolute top-10 right-10 text-gray-500 hover:text-white transition-all"><XMarkIcon className="h-8 w-8" /></button>

              <div className="text-center mb-12">
                 <div className="bg-gradient-to-tr from-yellow-500 to-amber-300 w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-yellow-500/20">
                    <SparklesIcon className="h-12 w-12 text-black" />
                 </div>
                 <h3 className="text-3xl font-black dark:text-white uppercase tracking-tighter">Apoiar Mestre</h3>
                 <p className="text-[11px] text-gray-500 font-bold uppercase tracking-widest mt-2">Sua doação incentiva o conhecimento</p>
              </div>

              <div className="grid grid-cols-3 gap-4 mb-12">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button 
                    key={val} 
                    onClick={() => setPendingAmount(val)}
                    className={`py-6 rounded-3xl font-black text-base transition-all active:scale-95 border-2 ${pendingAmount === val ? 'bg-blue-600 text-white border-blue-500 shadow-xl shadow-blue-600/30' : 'bg-gray-100 dark:bg-white/5 text-gray-500 border-transparent hover:border-white/10'}`}
                   >
                     ${val}
                   </button>
                 ))}
              </div>

              <button 
                onClick={executeDonation}
                disabled={!pendingAmount || isProcessingDonation}
                className="w-full bg-gradient-to-r from-green-500 to-emerald-600 hover:brightness-110 text-white py-6 rounded-[2.5rem] font-black text-sm uppercase tracking-[0.2em] shadow-xl active:scale-95 transition-all disabled:opacity-30 disabled:grayscale"
              >
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      {/* CHAT SIDEBAR */}
      {activeSidebar === 'chat' && (
        <div className="w-full md:w-[450px] bg-[#0a0c10]/98 backdrop-blur-3xl border-l border-white/5 flex flex-col animate-slide-left fixed inset-y-0 right-0 z-[70] shadow-[-20px_0_100px_rgba(0,0,0,0.8)]">
           <div className="p-10 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-black uppercase tracking-widest text-white">Chat Realtime</h3>
                <p className="text-[10px] text-blue-500 font-black uppercase mt-1">Sala CyBer Ativa</p>
              </div>
              <button onClick={() => setActiveSidebar(null)} className="p-4 hover:bg-white/5 rounded-[1.5rem] transition-all active:scale-90"><XMarkIcon className="h-7 w-7" /></button>
           </div>

           <div className="flex-1 overflow-y-auto p-8 space-y-6 custom-scrollbar">
              {chatMessages.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center opacity-10">
                    <ChatIconOutline className="h-24 w-24 mb-6" />
                    <p className="font-black text-sm uppercase tracking-[0.3em]">Ninguém falou ainda...</p>
                 </div>
              ) : (
                chatMessages.map(msg => {
                  const sender = findUserById(msg.senderId);
                  const isMe = msg.senderId === currentUser.id;
                  return (
                    <div key={msg.id} className={`flex gap-4 animate-fade-in ${isMe ? 'flex-row-reverse' : ''}`}>
                       <img src={sender?.profilePicture || DEFAULT_PROFILE_PIC} className="w-11 h-11 rounded-2xl shrink-0 object-cover shadow-xl border-2 border-white/5" />
                       <div className={`flex-1 max-w-[80%] ${isMe ? 'text-right' : ''}`}>
                          <p className="text-[11px] font-black text-white/40 uppercase mb-1.5 tracking-tighter">{sender?.firstName || 'Membro'}</p>
                          <div className={`p-5 rounded-[2rem] text-sm font-medium leading-relaxed border ${isMe ? 'bg-gradient-to-tr from-blue-600 to-blue-700 text-white border-blue-500 shadow-xl rounded-tr-none' : 'bg-white/5 text-white/90 border-white/10 rounded-tl-none'}`}>
                             {msg.text}
                          </div>
                       </div>
                    </div>
                  );
                })
              )}
           </div>

           <div className="p-8 bg-black/40 border-t border-white/5">
              <form onSubmit={handleSendMessage} className="flex items-center gap-4 bg-white/5 p-2 rounded-[2.2rem] border border-white/10 focus-within:border-blue-500 focus-within:ring-4 focus-within:ring-blue-500/10 transition-all">
                 <input 
                    type="text" 
                    value={newMessage} 
                    onChange={e => setNewMessage(e.target.value)} 
                    placeholder="Diga algo aos alunos..." 
                    className="bg-transparent flex-1 text-sm outline-none px-6 font-medium h-14" 
                 />
                 <button type="submit" className="p-4 bg-blue-600 hover:bg-blue-700 text-white rounded-[1.8rem] shadow-xl active:scale-90 transition-all">
                    <PaperAirplaneIcon className="h-6 w-6 -rotate-45" />
                 </button>
              </form>
           </div>
        </div>
      )}

      <style>{`
        .animate-slide-left { animation: slideLeft 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes slideLeft { from { transform: translateX(100%); } to { transform: translateX(0); } }

        @keyframes shoutout {
          0% { transform: translate(-50%, -100%); opacity: 0; }
          10% { transform: translate(-50%, 0); opacity: 1; }
          90% { transform: translate(-50%, 0); opacity: 1; }
          100% { transform: translate(-50%, -100%); opacity: 0; }
        }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }

        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Message } from '../types';
import { getPosts, findUserById, updateUserBalance, deletePost, getGlobalSettings } from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  XMarkIcon,
  HandRaisedIcon,
  SignalIcon,
  UsersIcon,
  ComputerDesktopIcon,
  PowerIcon,
  BanknotesIcon,
  PaperAirplaneIcon,
  SparklesIcon,
  PlayIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedIconOutline,
  ChatBubbleLeftRightIcon as ChatIconOutline,
  ComputerDesktopIcon as ScreenIconOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(false);
  const [isCamOn, setIsCamOn] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  const [activeSidebar, setActiveSidebar] = useState<'chat' | null>(null);
  const [handRaised, setHandRaised] = useState(false);

  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax;

  useEffect(() => {
    const foundPost = getPosts().find(p => p.id === postId);
    if (foundPost && foundPost.liveStream) {
      setPost(foundPost);
      const author = findUserById(foundPost.userId);
      setCreator(author || null);
    } else {
      onNavigate('feed');
    }
    return () => stopStreams();
  }, [postId, onNavigate]);

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  useEffect(() => {
    if (isCamOn && videoElementRef.current && streamRef.current) {
      if (videoElementRef.current.srcObject !== streamRef.current) {
        videoElementRef.current.srcObject = streamRef.current;
      }
    }
  }, [activeSidebar, showDonationModal, isCamOn]);

  const stopStreams = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
  };

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
      setIsScreenSharing(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        const oldTracks = streamRef.current.getVideoTracks();
        oldTracks.forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  const toggleMic = async () => {
    if (isMicOn) {
      if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => {
          track.enabled = false;
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsMicOn(false);
    } else {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const audioTrack = audioStream.getAudioTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.addTrack(audioTrack);
        setIsMicOn(true);
      } catch (err) { alert("Microfone indisponível."); }
    }
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await (navigator.mediaDevices as any).getDisplayMedia({ video: true });
      const screenTrack = screenStream.getVideoTracks()[0];
      screenTrack.onended = () => { setIsScreenSharing(false); setIsCamOn(false); };
      if (!streamRef.current) streamRef.current = new MediaStream();
      const oldVideoTracks = streamRef.current.getVideoTracks();
      oldVideoTracks.forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
      streamRef.current.addTrack(screenTrack);
      setIsScreenSharing(true);
      setIsCamOn(true);
    } catch (err) { console.error(err); }
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;
    const msg: Message = { id: `msg-${Date.now()}`, senderId: currentUser.id, receiverId: 'room', timestamp: Date.now(), text: newMessage };
    setChatMessages(prev => [...prev, msg]);
    setNewMessage('');
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) { alert("Saldo insuficiente."); return; }
    setIsProcessingDonation(true);
    setTimeout(() => {
      updateUserBalance(currentUser.id, -pendingAmount);
      updateUserBalance(creator.id, pendingAmount * (1 - platformTax));
      refreshUser();
      setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });
      setTimeout(() => setDonationAlert(null), 5000);
      const msg: Message = { id: `don-${Date.now()}`, senderId: currentUser.id, receiverId: 'room', timestamp: Date.now(), text: `🎁 Enviou um apoio de $${pendingAmount.toFixed(2)}!` };
      setChatMessages(prev => [...prev, msg]);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
    }, 1000);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  // Variáveis de estilo compactas
  const controlBtnClass = "p-2.5 md:p-3.5 rounded-2xl md:rounded-3xl backdrop-blur-xl border border-white/10 transition-all active:scale-90 shadow-lg flex flex-col items-center gap-0.5 group min-w-[50px] md:min-w-[64px]";
  const activeControlClass = "bg-blue-600 text-white shadow-blue-500/30 border-blue-400/30";
  const inactiveControlClass = "bg-black/40 text-white/70 hover:bg-black/60";

  return (
    <div className="fixed inset-0 bg-[#020408] z-[60] flex flex-col overflow-hidden text-white font-sans">

      {/* HEADER BAR COMPACTA */}
      <nav className="w-full flex items-center justify-between px-4 py-2 md:px-6 md:py-4 z-50 flex-shrink-0 bg-gradient-to-b from-black/80 to-transparent">
        <button 
          onClick={() => onNavigate('feed')} 
          className="p-2 md:p-3 bg-white/5 hover:bg-white/10 rounded-xl md:rounded-2xl border border-white/10 transition-all active:scale-90"
        >
          <XMarkIcon className="h-5 w-5 md:h-6 md:w-6" />
        </button>

        <div className="flex flex-col items-center">
           <div className="bg-red-600 px-3 py-1 rounded-full text-[8px] md:text-[10px] font-black flex items-center gap-1.5 shadow-[0_0_15px_rgba(220,38,38,0.4)] animate-pulse border border-red-500/50 uppercase tracking-widest">
             <SignalIcon className="h-3 w-3" /> AO VIVO
           </div>
           <p className="text-[9px] md:text-[11px] font-black uppercase mt-1 tracking-widest text-white/50 truncate max-w-[150px] md:max-w-xs">{post.liveStream.title}</p>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
           {isProfessional && (
             <button 
               onClick={() => { if(window.confirm("Encerrar transmissão?")) { deletePost(post.id); onNavigate('feed'); refreshUser(); } }} 
               className="bg-red-600 hover:bg-red-700 text-white p-2 md:p-3 rounded-xl md:rounded-2xl shadow-lg border border-red-500 transition-all active:scale-90"
             >
                <PowerIcon className="h-5 w-5 md:h-6 md:w-6" />
             </button>
           )}
           <div className="flex items-center gap-1.5 md:gap-3 bg-white/5 px-3 py-1.5 md:px-4 md:py-2.5 rounded-xl md:rounded-2xl border border-white/10 backdrop-blur-md">
              <UsersIcon className="h-3 w-3 md:h-4 md:w-4 text-blue-400" />
              <span className="text-[10px] md:text-xs font-black">1.4k</span>
           </div>
        </div>
      </nav>

      {/* ÁREA PRINCIPAL DO VÍDEO */}
      <main className="flex-1 flex relative items-center justify-center overflow-hidden p-1 md:p-6 lg:p-8">
        <div className="w-full h-full max-w-6xl rounded-[2rem] md:rounded-[4rem] overflow-hidden bg-black border-2 md:border-4 border-white/5 relative shadow-2xl group">

          {isCamOn ? (
            <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover bg-black" />
          ) : (
            <div className="flex flex-col items-center justify-center h-full bg-gradient-to-br from-[#0a0c10] via-black to-[#0a0c10]">
               <div className="w-24 h-24 md:w-48 md:h-48 rounded-[2.5rem] md:rounded-[5rem] bg-white/5 flex items-center justify-center text-4xl md:text-8xl font-black border-2 md:border-4 border-white/10 relative overflow-hidden">
                  <span className="opacity-20">{creator.firstName[0]}</span>
                  <div className="absolute inset-0 border-2 md:border-4 border-blue-500/10 animate-ping rounded-full"></div>
               </div>
               <p className="mt-6 md:mt-10 font-black uppercase tracking-[0.3em] text-[8px] md:text-xs text-white/20 animate-pulse">Câmara Offline</p>
            </div>
          )}

          {donationAlert && (
            <div className="absolute top-6 left-1/2 -translate-x-1/2 z-[100] animate-shoutout">
               <div className="bg-gradient-to-r from-yellow-400 to-amber-600 p-[1.5px] rounded-full shadow-2xl">
                  <div className="bg-black/90 backdrop-blur-3xl px-6 py-3 md:px-10 md:py-4 rounded-full flex items-center gap-3 md:gap-5">
                     <div className="bg-yellow-500 p-1.5 md:p-2 rounded-full shadow-lg"><SparklesIcon className="h-4 w-4 md:h-6 md:w-6 text-black" /></div>
                     <div className="text-left">
                        <p className="text-[8px] md:text-[10px] font-black text-yellow-500 uppercase tracking-widest leading-none mb-1">Apoio!</p>
                        <p className="text-xs md:text-base font-black text-white whitespace-nowrap">
                           {donationAlert.name} <span className="text-green-400">${donationAlert.amount}</span>
                        </p>
                     </div>
                  </div>
               </div>
            </div>
          )}

          {/* BARRA DE CONTROLES COMPACTA */}
          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-2 md:gap-4 bg-black/40 backdrop-blur-3xl px-4 py-3 md:px-6 md:py-4 rounded-[2rem] md:rounded-[3rem] border border-white/10 group-hover:translate-y-0 translate-y-32 transition-all duration-700 z-40 shadow-2xl">
             <div className="flex gap-2 md:gap-3">
                <button onClick={toggleMic} className={`${controlBtnClass} ${isMicOn ? activeControlClass : inactiveControlClass}`}>
                   {isMicOn ? <MicrophoneIcon className="h-5 w-5 md:h-6 md:w-6" /> : <MicrophoneIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
                   <span className="text-[7px] font-black uppercase tracking-tighter opacity-60">{isMicOn ? 'On' : 'Off'}</span>
                </button>
                <button onClick={toggleCamera} className={`${controlBtnClass} ${isCamOn ? activeControlClass : inactiveControlClass}`}>
                   {isCamOn ? <VideoCameraIcon className="h-5 w-5 md:h-6 md:w-6" /> : <VideoCameraIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
                   <span className="text-[7px] font-black uppercase tracking-tighter opacity-60">{isCamOn ? 'On' : 'Off'}</span>
                </button>
                <button onClick={startScreenShare} className={`${controlBtnClass} ${isScreenSharing ? activeControlClass : inactiveControlClass}`}>
                   {isScreenSharing ? <ComputerDesktopIcon className="h-5 w-5 md:h-6 md:w-6" /> : <ScreenIconOutline className="h-5 w-5 md:h-6 md:w-6" />}
                   <span className="text-[7px] font-black uppercase tracking-tighter opacity-60">Ecrã</span>
                </button>
                <div className="w-px h-8 md:h-10 bg-white/10 self-center mx-1 md:mx-2"></div>
                <button 
                  onClick={() => setShowDonationModal(true)} 
                  className="p-2.5 md:p-3.5 bg-gradient-to-tr from-yellow-500 to-amber-600 text-black rounded-2xl md:rounded-3xl hover:brightness-110 transition-all shadow-xl active:scale-90 flex flex-col items-center gap-0.5"
                >
                   <BanknotesIcon className="h-5 w-5 md:h-6 md:w-6" />
                   <span className="text-[7px] font-black uppercase tracking-tighter">Apoiar</span>
                </button>
             </div>
          </div>

          {/* FERRAMENTAS LATERAIS COMPACTAS */}
          <div className="absolute top-6 right-6 md:top-10 md:right-10 flex flex-col gap-3 md:gap-5">
             <button 
               onClick={() => setActiveSidebar(activeSidebar === 'chat' ? null : 'chat')} 
               className={`p-3 md:p-5 rounded-2xl md:rounded-3xl backdrop-blur-3xl border border-white/10 transition-all shadow-2xl active:scale-90 ${activeSidebar === 'chat' ? 'bg-blue-600 text-white shadow-blue-500/30' : 'bg-black/40 text-white/70'}`}
             >
                {activeSidebar === 'chat' ? <ChatBubbleLeftRightIcon className="h-5 w-5 md:h-7 md:w-7" /> : <ChatIconOutline className="h-5 w-5 md:h-7 md:w-7" />}
             </button>
             <button 
               onClick={() => setHandRaised(!handRaised)} 
               className={`p-3 md:p-5 rounded-2xl md:rounded-3xl backdrop-blur-3xl border border-white/10 transition-all shadow-2xl active:scale-90 ${handRaised ? 'bg-purple-600 text-white animate-bounce shadow-purple-600/30' : 'bg-black/40 text-white/70'}`}
