              <button onClick={() => setShowDonationModal(false)} className="absolute top-8 right-8 text-gray-500 hover:text-white transition-all"><XMarkIcon className="h-6 w-6" /></button>

              <div className="text-center mb-8">
                 <div className="bg-gradient-to-tr from-yellow-500 to-amber-300 w-16 h-16 rounded-[1.5rem] flex items-center justify-center mx-auto mb-4">
                    <SparklesIcon className="h-8 w-8 text-black" />
                 </div>
                 <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter leading-none">Apoiar Mestre</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-2">Envie um presente ao criador</p>
              </div>

              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button 
                    key={val} 
                    onClick={() => setPendingAmount(val)}
                    className={`py-4 rounded-2xl font-black text-sm transition-all border-2 ${pendingAmount === val ? 'bg-blue-600 text-white border-blue-500 shadow-xl' : 'bg-gray-100 dark:bg-white/5 text-gray-500 border-transparent'}`}
                   >
                     ${val}
                   </button>
                 ))}
              </div>

              <button 
                onClick={executeDonation}
                disabled={!pendingAmount || isProcessingDonation}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white py-5 rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] shadow-xl disabled:opacity-30 transition-all active:scale-95"
              >
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      {/* CHAT SIDEBAR */}
      {activeSidebar === 'chat' && (
        <div className="w-full md:w-[400px] lg:w-[450px] bg-[#0a0c10]/98 backdrop-blur-3xl border-l border-white/5 flex flex-col animate-slide-left fixed inset-y-0 right-0 z-[70] shadow-[-20px_0_100px_rgba(0,0,0,0.8)]">
           <div className="p-6 md:p-10 border-b border-white/5 flex items-center justify-between">
              <div>
                <h3 className="text-lg md:text-xl font-black uppercase tracking-widest text-white leading-none">Chat</h3>
                <p className="text-[9px] text-blue-500 font-black uppercase mt-1">Conectado ao mestre</p>
              </div>
              <button onClick={() => setActiveSidebar(null)} className="p-3 hover:bg-white/5 rounded-xl transition-all"><XMarkIcon className="h-6 w-6" /></button>
           </div>

           <div className="flex-1 overflow-y-auto p-6 md:p-8 space-y-5 custom-scrollbar">
              {chatMessages.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center opacity-10">
                    <ChatIconOutline className="h-20 w-20 mb-4" />
                    <p className="font-black text-[10px] uppercase tracking-[0.3em]">Silêncio na sala...</p>
                 </div>
              ) : (
                chatMessages.map(msg => {
                  const sender = findUserById(msg.senderId);
                  const isMe = msg.senderId === currentUser.id;
                  return (
                    <div key={msg.id} className={`flex gap-3 animate-fade-in ${isMe ? 'flex-row-reverse' : ''}`}>
                       <img src={sender?.profilePicture || DEFAULT_PROFILE_PIC} className="w-9 h-9 rounded-xl shrink-0 object-cover border border-white/5" />
                       <div className={`flex-1 max-w-[80%] ${isMe ? 'text-right' : ''}`}>
                          <p className="text-[9px] font-black text-white/40 uppercase mb-1">{sender?.firstName || 'Membro'}</p>
                          <div className={`p-4 rounded-2xl text-xs font-medium border ${isMe ? 'bg-blue-600 text-white border-blue-500 rounded-tr-none' : 'bg-white/5 text-white/90 border-white/10 rounded-tl-none'}`}>
                             {msg.text}
                          </div>
                       </div>
                    </div>
                  );
                })
              )}
           </div>

           <div className="p-6 md:p-8 bg-black/40 border-t border-white/5">
              <form onSubmit={handleSendMessage} className="flex items-center gap-3 bg-white/5 p-1.5 rounded-full border border-white/10 focus-within:border-blue-500 transition-all">
                 <input 
                    type="text" 
                    value={newMessage} 
                    onChange={e => setNewMessage(e.target.value)} 
                    placeholder="Diga algo..." 
                    className="bg-transparent flex-1 text-xs outline-none px-4 font-medium h-10" 
                 />
                 <button type="submit" className="p-3 bg-blue-600 text-white rounded-full shadow-lg active:scale-90 transition-all">
                    <PaperAirplaneIcon className="h-4 w-4 -rotate-45" />
                 </button>
              </form>
           </div>
        </div>
      )}

      <style>{`
        .animate-slide-left { animation: slideLeft 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes slideLeft { from { transform: translateX(100%); } to { transform: translateX(0); } }

        @keyframes shoutout {
          0% { transform: translate(-50%, -100%); opacity: 0; }
          15% { transform: translate(-50%, 0); opacity: 1; }
          85% { transform: translate(-50%, 0); opacity: 1; }
          100% { transform: translate(-50%, -100%); opacity: 0; }
        }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }

        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

