import React, { useState, useEffect, useMemo } from 'react';
import { User, UserType, Post, AdCampaign } from '../types';
import { 
  findUserById, 
  updateUser,
  getPosts,
  getAds 
} from '../services/storageService';
import { CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../constants';
import { 
  CheckBadgeIcon, 
  TrophyIcon,
  WalletIcon,
  ArrowDownCircleIcon,
  ArrowUpCircleIcon,
  UserIcon,
  Squares2X2Icon,
  ShoppingBagIcon,
  MegaphoneIcon,
  SparklesIcon,
  RocketLaunchIcon,
  ClockIcon,
  ShieldCheckIcon
} from '@heroicons/react/24/solid';
import PostCard from './PostCard';
import AdCard from './AdCard';

interface ProfilePageProps {
  currentUser: User;
  onNavigate: (page: string, params?: any) => void;
  refreshUser: () => void;
  userId?: string;
  onOpenWallet: (mode: 'deposit' | 'withdraw') => void;
}

const ProfilePage: React.FC<ProfilePageProps> = ({ currentUser, onNavigate, refreshUser, userId, onOpenWallet }) => {
  const profileId = userId || currentUser.id;
  const [profile, setProfile] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'posts' | 'about' | 'store' | 'ads'>('posts');

  const userPosts = useMemo(() => {
    return getPosts().filter(p => p.userId === profileId).sort((a, b) => b.timestamp - a.timestamp);
  }, [profileId, currentUser]);

  const userAds = useMemo(() => {
    return getAds().filter(a => a.professorId === profileId);
  }, [profileId, currentUser]);

  useEffect(() => {
    const u = findUserById(profileId);
    if (u) {
      setProfile(u);
    }
