       <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8">
             {activeTab === 'posts' && (
                <div className="space-y-6 animate-fade-in">
                   {userPosts.length > 0 ? userPosts.map(post => (
                     <PostCard key={post.id} post={post} currentUser={currentUser} onNavigate={onNavigate} onFollowToggle={() => {}} refreshUser={refreshUser} onPostUpdatedOrDeleted={refreshUser} onPinToggle={() => {}} />
                   )) : (
                     <div className="bg-white dark:bg-darkcard p-16 rounded-[3rem] text-center border-2 border-dashed border-gray-100 dark:border-white/5">
                        <Squares2X2Icon className="h-12 w-12 text-gray-200 mx-auto mb-4" />
                        <p className="text-gray-400 font-black uppercase text-xs">Sem posts ainda</p>
                     </div>
                   )}
                </div>
             )}

             {activeTab === 'ads' && (
                <div className="space-y-6 animate-fade-in">
                   {userAds.length > 0 ? userAds.map(ad => (
                     <AdCard key={ad.id} ad={ad} />
