                     </div>
                   )}
                </div>
             )}

             {activeTab === 'about' && (
                <div className="bg-white dark:bg-darkcard p-10 rounded-[3rem] shadow-xl border border-gray-100 dark:border-white/5 animate-fade-in">
                   <h3 className="text-2xl font-black dark:text-white mb-6 tracking-tighter">Biografia</h3>
                   <p className="text-gray-600 dark:text-gray-400 leading-relaxed text-lg font-medium italic">"{profile.bio || 'Sem biografia disponível.'}"</p>
                </div>
             )}
          </div>

          <div className="lg:col-span-4 space-y-6">
             {isOwnProfile && (
                <>
                <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border border-gray-100 dark:border-white/5 space-y-8">
                   <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                         <div className="p-3 bg-blue-600 text-white rounded-2xl shadow-lg"><WalletIcon className="h-6 w-6" /></div>
                         <div>
                            <h4 className="font-black dark:text-white text-xs uppercase tracking-widest">Carteira</h4>
                            <p className="text-[9px] text-gray-400 font-black uppercase">Saldo CyBer</p>
                         </div>
                      </div>
                      <p className="text-3xl font-black text-blue-600">${(currentUser.balance || 0).toFixed(2)}</p>
                   </div>

                   <div className="grid grid-cols-2 gap-3">
                      <button onClick={() => onOpenWallet('deposit')} className="p-4 bg-gray-50 dark:bg-white/5 rounded-2xl flex flex-col items-center gap-2 hover:bg-green-50 transition-all group">
                         <ArrowDownCircleIcon className="h-6 w-6 text-green-500 group-hover:scale-110 transition-transform" />
