                      </button>
                      <button onClick={() => onOpenWallet('withdraw')} className="p-4 bg-gray-50 dark:bg-white/5 rounded-2xl flex flex-col items-center gap-2 hover:bg-red-50 transition-all group">
                         <ArrowUpCircleIcon className="h-6 w-6 text-red-500 group-hover:scale-110 transition-transform" />
