  );
};

export default ProfilePage;

import React, { useState, useEffect, useMemo } from 'react';
import { User, UserType, Store, Product, ProductType, OrderStatus, AffiliateSale } from '../types';
import { 
  getStores, 
  getProducts, 
  saveProducts,
  updateStore,
  getAllSales,
  updateSaleStatus,
  findUserById
} from '../services/storageService';
import { sourceDropshippingProducts } from '../services/geminiService';
import { 
  PlusIcon, 
  ArchiveBoxIcon,
  TrashIcon,
  CheckBadgeIcon,
  BoltIcon,
  XMarkIcon,
  MagnifyingGlassIcon,
  ArrowDownTrayIcon,
  PaintBrushIcon,
  ShoppingBagIcon,
  PhotoIcon,
  InformationCircleIcon,
  BookOpenIcon,
  VideoCameraIcon,
  AcademicCapIcon,
  TruckIcon,
  ClipboardDocumentListIcon,
  MapPinIcon,
  ClockIcon
} from '@heroicons/react/24/solid';

interface StoreManagerPageProps {
  currentUser: User;
  refreshUser: () => void;
  onNavigate: (page: any, params?: any) => void;
}

type ManagerTab = 'inventory' | 'orders' | 'sourcing' | 'branding';

const BRAND_COLORS = [
  { name: 'Azul CyBer', hex: '#2563eb' },
  { name: 'Roxo Royal', hex: '#7c3aed' },
  { name: 'Verde Mint', hex: '#10b981' },
  { name: 'Preto Carbono', hex: '#0f172a' },
  { name: 'Laranja Solar', hex: '#f59e0b' },
  { name: 'Rosa Shock', hex: '#db2777' }
];

const StoreManagerPage: React.FC<StoreManagerPageProps> = ({ currentUser, refreshUser, onNavigate }) => {
  const [userStore, setUserStore] = useState<Store | null>(null);
  const [storeProducts, setStoreProducts] = useState<Product[]>([]);
  const [storeSales, setStoreSales] = useState<AffiliateSale[]>([]);
  const [activeTab, setActiveTab] = useState<ManagerTab>('inventory');
  const [isAddingProduct, setIsAddingProduct] = useState(false);

  const [brandName, setBrandName] = useState('');
  const [brandDesc, setBrandDesc] = useState('');
  const [brandColor, setBrandColor] = useState(BRAND_COLORS[0].hex);

  const [pName, setPName] = useState('');
  const [pDesc, setPDesc] = useState('');
  const [pPrice, setPPrice] = useState('');
  const [pType, setPType] = useState<ProductType>(ProductType.DIGITAL_COURSE);
  const [pImg, setPImg] = useState('');
  const [pDigitalUrl, setPDigitalUrl] = useState('');

  const [searchQuery, setSearchQuery] = useState('');
  const [sourcingResults, setSourcingResults] = useState<any[]>([]);
  const [isSourcing, setIsSourcing] = useState(false);
  const [markup, setMarkup] = useState(1.5);

  const loadData = () => {
    const stores = getStores();
    const myStore = stores.find(s => s.professorId === currentUser.id);
    if (myStore) {
      setUserStore(myStore);
      setBrandName(myStore.name);
      setBrandDesc(myStore.description);
      setBrandColor(myStore.brandColor || BRAND_COLORS[0].hex);
      setStoreProducts(getProducts().filter(p => p.storeId === myStore.id));
      setStoreSales(getAllSales().filter(s => s.storeId === myStore.id).sort((a, b) => b.timestamp - a.timestamp));
    }
  };

  useEffect(() => {
    loadData();
  }, [currentUser.id]);

  const handleSaveBranding = () => {
    if (!userStore) return;
    const updated = { ...userStore, name: brandName, description: brandDesc, brandColor };
    updateStore(updated);
    setUserStore(updated);
    alert('Identidade visual da loja atualizada!');
  };

  const handleCreateProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userStore) return;

    const newProduct: Product = {
      id: `prod-man-${Date.now()}`,
      storeId: userStore.id,
      name: pName,
      description: pDesc,
      price: parseFloat(pPrice),
      imageUrls: [pImg || 'https://picsum.photos/400/400?random=prod'],
      affiliateCommissionRate: 0.15,
      type: pType,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      digitalContentUrl: pType !== ProductType.PHYSICAL ? pDigitalUrl : undefined
    };

    saveProducts([...getProducts(), newProduct]);
    setIsAddingProduct(false);
    loadData();
    alert('Produto criado com sucesso!');
  };

  const handleUpdateStatus = (saleId: string, status: OrderStatus) => {
    updateSaleStatus(saleId, status);
    loadData();
    alert(`Status atualizado para: ${status}`);
  };

  const handleSource = async () => {
    if (!searchQuery) return;
    setIsSourcing(true);
    const results = await sourceDropshippingProducts(searchQuery);
    setSourcingResults(results);
    setIsSourcing(false);
  };

  const handleImport = (sourceProd: any) => {
    if (!userStore) return;
    const newProduct: Product = {
      id: `prod-drop-${Date.now()}`,
      storeId: userStore.id,
      name: sourceProd.name,
      description: sourceProd.description,
      price: sourceProd.originalPrice * markup,
      imageUrls: [sourceProd.imageUrl],
      affiliateCommissionRate: 0.1,
      type: ProductType.PHYSICAL,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      isDropshipping: true,
      externalProviderId: sourceProd.externalProviderId,
      originalPrice: sourceProd.originalPrice
    };
    saveProducts([...getProducts(), newProduct]);
    loadData();
    alert('Item importado para sua loja!');
  };

  if (currentUser.userType === UserType.STANDARD) {
    return (
      <div className="container mx-auto px-4 pt-32 text-center max-w-2xl animate-fade-in">
         <div className="bg-blue-600 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl">
            <CheckBadgeIcon className="h-12 w-12 text-white" />
         </div>
         <h2 className="text-4xl font-black mb-6 tracking-tighter dark:text-white uppercase leading-none">Torne-se um Profissional <span className="text-blue-600">CyBer.</span></h2>
         <p className="text-gray-500 text-lg mb-10 leading-relaxed font-medium">Ganhe influência e suba de nível para desbloquear sua loja exclusiva e faturar com seu conhecimento ou revenda.</p>
         <button onClick={() => onNavigate('ads')} className="bg-blue-600 text-white px-12 py-5 rounded-2xl font-black uppercase text-sm shadow-xl active:scale-95 transition-all tracking-[0.2em]">Crescer meu Perfil</button>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 pt-24 pb-32 max-w-6xl animate-fade-in">

       <div className="flex flex-col md:flex-row items-center justify-between mb-12 gap-8">
          <div className="flex items-center gap-5">
            <div className="w-16 h-16 rounded-[1.5rem] shadow-xl flex items-center justify-center text-white" style={{ backgroundColor: brandColor }}>
              <CheckBadgeIcon className="h-10 w-10" />
            </div>
            <div>
              <h2 className="text-3xl font-black dark:text-white tracking-tighter uppercase">{brandName || 'Minha Vitrine'}</h2>
              <p className="text-gray-500 text-[10px] font-black uppercase tracking-widest flex items-center gap-2">Painel Profissional <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span></p>
            </div>
          </div>

          <div className="flex bg-gray-100 dark:bg-white/5 p-1.5 rounded-[1.8rem] shadow-inner overflow-x-auto no-scrollbar max-w-full">
             {[
               { id: 'inventory', label: 'Produtos', icon: ArchiveBoxIcon },
               { id: 'orders', label: 'Vendas', icon: ClipboardDocumentListIcon },
               { id: 'sourcing', label: 'Revenda', icon: BoltIcon },
               { id: 'branding', label: 'Marca', icon: PaintBrushIcon }
             ].map(t => (
               <button 
                key={t.id} 
                onClick={() => setActiveTab(t.id as any)} 
                className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === t.id ? 'bg-white dark:bg-darkcard text-blue-600 shadow-lg' : 'text-gray-500'}`}
               >
                 <t.icon className="h-4 w-4" /> {t.label}
               </button>
             ))}
          </div>
       </div>

       {activeTab === 'inventory' && (
         <div className="space-y-8 animate-fade-in">
            <div className="flex justify-between items-center px-4">
               <h3 className="font-black text-xl dark:text-white uppercase tracking-tighter">Estoque Ativo</h3>
               <button onClick={() => setIsAddingProduct(true)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 active:scale-95 transition-all"><PlusIcon className="h-4 w-4 stroke-[4]" /> Adicionar Item</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
               {storeProducts.map(p => (
                 <div key={p.id} className="bg-white dark:bg-darkcard rounded-[2.5rem] overflow-hidden border border-gray-100 dark:border-white/5 shadow-sm group hover:shadow-2xl transition-all">
                    <img src={p.imageUrls[0]} className="h-48 w-full object-cover group-hover:scale-105 transition-transform duration-700" />
                    <div className="p-6">
                       <div className="flex items-center gap-2 mb-2">
                          <span className="text-[8px] font-black uppercase text-blue-600 bg-blue-50 dark:bg-blue-900/20 px-2 py-0.5 rounded">{p.type.replace('DIGITAL_', '')}</span>
                       </div>
                       <h4 className="font-black text-sm dark:text-white uppercase truncate mb-1">{p.name}</h4>
                       <p className="text-2xl font-black text-blue-600 mb-6">${p.price.toFixed(2)}</p>
                       <div className="flex gap-2">
                          <button className="flex-1 bg-gray-50 dark:bg-white/5 text-gray-500 py-3 rounded-xl text-[10px] font-black uppercase">Editar</button>
                          <button className="p-3 bg-red-50 text-red-500 dark:bg-red-900/10 rounded-xl"><TrashIcon className="h-4 w-4"/></button>
                       </div>
                    </div>
                 </div>
               ))}
            </div>
         </div>
       )}

       {activeTab === 'orders' && (
         <div className="space-y-6 animate-fade-in">
            <div className="bg-white dark:bg-darkcard rounded-[2.5rem] overflow-hidden border border-gray-100 dark:border-white/5 shadow-xl">
               <div className="p-6 border-b dark:border-white/5 bg-gray-50 dark:bg-white/5 flex items-center justify-between">
                  <h3 className="font-black text-sm uppercase tracking-widest text-gray-900 dark:text-white">Fluxo de Pedidos</h3>
                  <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 dark:bg-blue-900/20 px-3 py-1 rounded-full">{storeSales.length} Total</span>
               </div>
               <div className="divide-y divide-gray-50 dark:divide-white/5">
                  {storeSales.length === 0 ? (
                    <div className="p-24 text-center text-gray-400 font-black uppercase text-xs tracking-widest">Aguardando sua primeira venda...</div>
                  ) : (
                    storeSales.map(sale => {
                       const buyer = findUserById(sale.buyerId);
                       const product = getProducts().find(p => p.id === sale.productId);
                       const isPhysical = product?.type === ProductType.PHYSICAL;

                       return (
                         <div key={sale.id} className="p-6 md:p-8 flex flex-col md:flex-row gap-8 items-start md:items-center hover:bg-gray-50/50 dark:hover:bg-white/5 transition-colors">
                            <div className="flex items-center gap-5 min-w-[280px]">
                               <img src={product?.imageUrls[0]} className="w-16 h-16 rounded-2xl object-cover shadow-lg" />
                               <div>
                                  <p className="font-black text-sm dark:text-white uppercase truncate max-w-[200px]">{product?.name}</p>
                                  <p className="text-[9px] font-bold text-gray-400 uppercase">#ID: {sale.id.split('-')[1]}</p>
                               </div>
                            </div>

                            <div className="flex-1 space-y-3">
                               <div className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase">
                                  <ShoppingBagIcon className="h-4 w-4" />
                                  Cliente: {buyer?.firstName} {buyer?.lastName}
                               </div>
                               {isPhysical && sale.shippingAddress && (
                                  <div className="flex items-start gap-2 bg-white dark:bg-darkcard p-3 rounded-xl border border-gray-100 dark:border-white/10 shadow-sm">
                                     <MapPinIcon className="h-4 w-4 text-red-500 shrink-0" />
                                     <span className="text-[10px] font-bold text-gray-500 uppercase leading-snug">
                                        {sale.shippingAddress.address}, {sale.shippingAddress.city} - {sale.shippingAddress.zipCode}
                                     </span>
                                  </div>
                               )}
                               <div className="flex items-center gap-2 text-[10px] font-bold text-gray-400 uppercase">
                                  <ClockIcon className="h-3.5 w-3.5" />
                                  {new Date(sale.timestamp).toLocaleString()}
                               </div>
                            </div>

                            <div className="flex items-center gap-6 w-full md:w-auto">
                               <div className="text-right min-w-[100px]">
                                  <p className="text-2xl font-black text-gray-900 dark:text-white">${sale.saleAmount.toFixed(2)}</p>
                                  <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${sale.status === OrderStatus.DELIVERED ? 'bg-green-100 text-green-600' : 'bg-orange-100 text-orange-600'}`}>
                                     {sale.status}
                                  </span>
                               </div>

                               <div className="flex gap-2 shrink-0">
                                  {sale.status === OrderStatus.WAITLIST && isPhysical && (
                                     <button 
                                      onClick={() => handleUpdateStatus(sale.id, OrderStatus.SHIPPING)}
                                      className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 hover:bg-blue-700 active:scale-95 transition-all"
                                     >
                                        <TruckIcon className="h-5 w-5" /> Enviar Produto
                                     </button>
                                  )}
                                  {sale.status === OrderStatus.WAITLIST && !isPhysical && (
                                     <button 
                                      onClick={() => handleUpdateStatus(sale.id, OrderStatus.DELIVERED)}
                                      className="bg-green-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 hover:bg-green-700 active:scale-95 transition-all"
                                     >
                                        Liberar Acesso
                                     </button>
                                  )}
                                  {sale.status === OrderStatus.SHIPPING && (
                                     <div className="text-[10px] font-black text-blue-400 uppercase tracking-widest animate-pulse px-4 py-2 bg-blue-50 dark:bg-blue-900/10 rounded-xl border border-blue-100">A Caminho...</div>
                                  )}
                               </div>
                            </div>
                         </div>
                       );
                    })
                  )}
               </div>
            </div>
         </div>
       )}

       {activeTab === 'branding' && (
         <div className="max-w-4xl mx-auto space-y-10 animate-fade-in">
            <div className="bg-white dark:bg-darkcard p-10 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-white/5">
               <h3 className="text-2xl font-black dark:text-white uppercase tracking-tight mb-10">Personalização de Marca</h3>
               <div className="space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nome Comercial</label>
                        <input type="text" value={brandName} onChange={e => setBrandName(e.target.value)} className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white font-black outline-none border-2 border-transparent focus:border-blue-600" />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Cor da Identidade</label>
                        <div className="flex gap-2">
                           {BRAND_COLORS.map(c => (
                             <button key={c.hex} onClick={() => setBrandColor(c.hex)} className={`w-11 h-11 rounded-full border-4 transition-all ${brandColor === c.hex ? 'border-white shadow-xl scale-110' : 'opacity-40 border-transparent'}`} style={{ backgroundColor: c.hex }}></button>
                           ))}
                        </div>
                     </div>
                  </div>
                  <textarea value={brandDesc} onChange={e => setBrandDesc(e.target.value)} className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white h-32 resize-none outline-none border-2 border-transparent focus:border-blue-600 font-medium" placeholder="Descreva o propósito da sua vitrine profissional..." />
                  <button onClick={handleSaveBranding} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-sm uppercase shadow-xl hover:bg-blue-700 transition-all tracking-[0.2em]">Salvar Identidade</button>
               </div>
            </div>
         </div>
       )}

       {activeTab === 'sourcing' && (
         <div className="space-y-8 animate-fade-in">
            <div className="bg-white dark:bg-darkcard p-6 md:p-10 rounded-[2.5rem] md:rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-white/5">
               <h3 className="text-xl md:text-2xl font-black dark:text-white uppercase tracking-tight mb-6 md:mb-8">Revenda de Produtos (Sourcing)</h3>
               <p className="text-xs md:text-sm text-gray-500 mb-6 font-medium leading-relaxed">Use nossa rede de fornecedores para preencher sua vitrine com produtos físicos sem estoque.</p>
               <div className="flex flex-col sm:flex-row gap-4">
                  <div className="flex-1 relative">
                    <MagnifyingGlassIcon className="h-5 w-5 md:h-6 md:w-6 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input type="text" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} placeholder="Pesquisar itens..." className="w-full pl-11 md:pl-12 pr-6 py-4 md:py-5 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-black dark:text-white border-2 border-transparent focus:border-orange-500 text-sm" />
                  </div>
                  <button onClick={handleSource} disabled={isSourcing} className="bg-orange-500 text-white px-8 md:px-10 py-4 md:py-5 rounded-2xl font-black uppercase text-[10px] md:text-xs shadow-xl disabled:opacity-50 transition-all active:scale-95">{isSourcing ? 'Prospectando...' : 'Prospectar'}</button>
               </div>
            </div>

            {sourcingResults.length > 0 && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8">
                {sourcingResults.map((res, i) => (
                  <div key={i} className="bg-white dark:bg-darkcard rounded-[2.5rem] md:rounded-[3rem] p-5 md:p-8 flex flex-col md:flex-row gap-6 md:gap-8 border border-gray-100 dark:border-white/5 shadow-md group transition-all hover:shadow-xl">
                     <div className="w-full md:w-44 h-48 md:h-44 shrink-0 rounded-[1.8rem] md:rounded-[2rem] overflow-hidden shadow-lg">
                        <img src={res.imageUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                     </div>
                     <div className="flex-1 flex flex-col justify-center">
                        <h4 className="font-black text-base md:text-lg dark:text-white mb-2 uppercase line-clamp-1">{res.name}</h4>
                        <p className="text-[11px] md:text-xs text-gray-400 font-medium line-clamp-2 mb-6 italic leading-relaxed">"{res.description}"</p>
                        <div className="flex items-center justify-between border-t border-gray-50 dark:border-white/5 pt-5 mt-auto flex-wrap gap-4">
                           <div>
                              <p className="text-[8px] md:text-[9px] font-black text-gray-400 uppercase mb-0.5">Custo Sugerido</p>
                              <p className="font-black text-xl md:text-2xl text-orange-600">${(res.originalPrice * markup).toFixed(2)}</p>
                           </div>
                           <button onClick={() => handleImport(res)} className="flex-1 md:flex-none bg-black dark:bg-white dark:text-black text-white px-6 md:px-8 py-3 md:py-4 rounded-xl md:rounded-2xl font-black text-[10px] uppercase shadow-lg active:scale-95 transition-all">Importar</button>
                        </div>
                     </div>
                  </div>
                ))}
              </div>
            )}
         </div>
       )}

       {/* MODAL ADICIONAR PRODUTO */}
       {isAddingProduct && (
         <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setIsAddingProduct(false)}>
            <div className="bg-white dark:bg-darkcard w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl relative border border-white/10" onClick={e => e.stopPropagation()}>
               <h3 className="text-2xl font-black dark:text-white uppercase mb-10 tracking-tight">Novo Item de Venda</h3>
               <form onSubmit={handleCreateProduct} className="space-y-6">
                  <div className="grid grid-cols-2 gap-6">
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nome do Produto</label>
                        <input type="text" required value={pName} onChange={e => setPName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl outline-none font-bold" placeholder="Ex: Curso Master..." />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Preço (USD)</label>
                        <input type="number" required value={pPrice} onChange={e => setPPrice(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl outline-none font-bold" placeholder="0.00" />
                     </div>
                  </div>
                  <div className="space-y-2">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Tipo de Item</label>
                     <div className="grid grid-cols-4 gap-2">
                        {[ProductType.DIGITAL_COURSE, ProductType.DIGITAL_EBOOK, ProductType.PHYSICAL, ProductType.DIGITAL_OTHER].map(t => (
                          <button key={t} type="button" onClick={() => setPType(t)} className={`p-3 rounded-xl border-2 text-[9px] font-black uppercase transition-all ${pType === t ? 'border-blue-600 bg-blue-50 text-blue-600 shadow-md' : 'border-gray-50 dark:border-white/5'}`}>{t.replace('DIGITAL_', '')}</button>
                        ))}
                     </div>
                  </div>
                  <input type="text" value={pImg} onChange={e => setPImg(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl outline-none font-bold text-sm" placeholder="URL da Foto do Produto" />
                  {pType !== ProductType.PHYSICAL && (
                    <input type="url" value={pDigitalUrl} onChange={e => setPDigitalUrl(e.target.value)} className="w-full p-4 bg-blue-50 dark:bg-blue-900/10 rounded-2xl outline-none font-bold text-blue-600 text-sm" placeholder="Link Seguro para Download/Acesso" />
                  )}
                  <textarea value={pDesc} onChange={e => setPDesc(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl outline-none h-32 resize-none font-medium text-sm" placeholder="Escreva uma descrição persuasiva para vender este item..." />
                  <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-sm uppercase shadow-2xl hover:bg-blue-700 tracking-[0.2em] transition-all active:scale-95">Publicar Agora</button>
               </form>
            </div>
         </div>
       )}
    </div>
  );
};

export default StoreManagerPage;

import React, { useState, useEffect, useMemo } from 'react';
import { User, UserType, Store, Product, ProductType, OrderStatus, AffiliateSale } from '../types';
import { 
  getStores, 
  getProducts, 
  saveProducts,
  updateStore,
  getAllSales,
  updateSaleStatus,
  findUserById
} from '../services/storageService';
import { sourceDropshippingProducts } from '../services/geminiService';
import { 
  PlusIcon, 
  ArchiveBoxIcon,
  TrashIcon,
  CheckBadgeIcon,
  BoltIcon,
  XMarkIcon,
  MagnifyingGlassIcon,
  ArrowDownTrayIcon,
  PaintBrushIcon,
  ShoppingBagIcon,
  PhotoIcon,
  InformationCircleIcon,
  BookOpenIcon,
  VideoCameraIcon,
  AcademicCapIcon,
  TruckIcon,
  ClipboardDocumentListIcon,
  MapPinIcon,
  ClockIcon,
  CheckCircleIcon
} from '@heroicons/react/24/solid';

interface StoreManagerPageProps {
  currentUser: User;
  refreshUser: () => void;
  onNavigate: (page: any, params?: any) => void;
}

type ManagerTab = 'inventory' | 'orders' | 'sourcing' | 'branding';

const BRAND_COLORS = [
  { name: 'Azul CyBer', hex: '#2563eb' },
  { name: 'Roxo Royal', hex: '#7c3aed' },
  { name: 'Verde Mint', hex: '#10b981' },
  { name: 'Preto Carbono', hex: '#0f172a' },
  { name: 'Laranja Solar', hex: '#f59e0b' },
  { name: 'Rosa Shock', hex: '#db2777' }
];

const StoreManagerPage: React.FC<StoreManagerPageProps> = ({ currentUser, refreshUser, onNavigate }) => {
  const [userStore, setUserStore] = useState<Store | null>(null);
  const [storeProducts, setStoreProducts] = useState<Product[]>([]);
  const [storeSales, setStoreSales] = useState<AffiliateSale[]>([]);
  const [activeTab, setActiveTab] = useState<ManagerTab>('inventory');
  const [isAddingProduct, setIsAddingProduct] = useState(false);

  const [brandName, setBrandName] = useState('');
  const [brandDesc, setBrandDesc] = useState('');
  const [brandColor, setBrandColor] = useState(BRAND_COLORS[0].hex);

  const [pName, setPName] = useState('');
  const [pDesc, setPDesc] = useState('');
  const [pPrice, setPPrice] = useState('');
  const [pType, setPType] = useState<ProductType>(ProductType.DIGITAL_COURSE);
  const [pImg, setPImg] = useState('');
  const [pDigitalUrl, setPDigitalUrl] = useState('');

  const [searchQuery, setSearchQuery] = useState('');
  const [sourcingResults, setSourcingResults] = useState<any[]>([]);
  const [isSourcing, setIsSourcing] = useState(false);
  const [markup, setMarkup] = useState(1.5);

  const loadData = () => {
    const stores = getStores();
    const myStore = stores.find(s => s.professorId === currentUser.id);
    if (myStore) {
      setUserStore(myStore);
      setBrandName(myStore.name);
      setBrandDesc(myStore.description);
      setBrandColor(myStore.brandColor || BRAND_COLORS[0].hex);
      setStoreProducts(getProducts().filter(p => p.storeId === myStore.id));
      setStoreSales(getAllSales().filter(s => s.storeId === myStore.id).sort((a, b) => b.timestamp - a.timestamp));
    }
  };

  useEffect(() => {
    loadData();
  }, [currentUser.id]);

  const handleSaveBranding = () => {
    if (!userStore) return;
    const updated = { ...userStore, name: brandName, description: brandDesc, brandColor };
    updateStore(updated);
    setUserStore(updated);
    alert('Identidade visual da loja atualizada!');
  };

  const handleCreateProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userStore) return;

    const newProduct: Product = {
      id: `prod-man-${Date.now()}`,
      storeId: userStore.id,
      name: pName,
      description: pDesc,
      price: parseFloat(pPrice),
      imageUrls: [pImg || 'https://picsum.photos/400/400?random=prod'],
      affiliateCommissionRate: 0.15,
      type: pType,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      digitalContentUrl: pType !== ProductType.PHYSICAL ? pDigitalUrl : undefined
    };

    saveProducts([...getProducts(), newProduct]);
    setIsAddingProduct(false);
    loadData();
    alert('Produto criado com sucesso!');
  };

  const handleUpdateStatus = (saleId: string, status: OrderStatus) => {
    updateSaleStatus(saleId, status);
    loadData(); // Recarrega para atualizar a UI do vendedor
  };

  const handleSource = async () => {
    if (!searchQuery) return;
    setIsSourcing(true);
    const results = await sourceDropshippingProducts(searchQuery);
    setSourcingResults(results);
    setIsSourcing(false);
  };

  const handleImport = (sourceProd: any) => {
    if (!userStore) return;
    const newProduct: Product = {
      id: `prod-drop-${Date.now()}`,
      storeId: userStore.id,
      name: sourceProd.name,
      description: sourceProd.description,
      price: sourceProd.originalPrice * markup,
      imageUrls: [sourceProd.imageUrl],
      affiliateCommissionRate: 0.1,
      type: ProductType.PHYSICAL,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      isDropshipping: true,
      externalProviderId: sourceProd.externalProviderId,
      originalPrice: sourceProd.originalPrice
    };
    saveProducts([...getProducts(), newProduct]);
    loadData();
    alert('Item importado para sua loja!');
  };

  if (currentUser.userType === UserType.STANDARD) {
    return (
      <div className="container mx-auto px-4 pt-32 text-center max-w-2xl animate-fade-in">
         <div className="bg-blue-600 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl">
            <CheckBadgeIcon className="h-12 w-12 text-white" />
         </div>
         <h2 className="text-4xl font-black mb-6 tracking-tighter dark:text-white uppercase leading-none">Torne-se um Profissional <span className="text-blue-600">CyBer.</span></h2>
         <p className="text-gray-500 text-lg mb-10 leading-relaxed font-medium">Ganhe influência e suba de nível para desbloquear sua loja exclusiva e faturar com seu conhecimento ou revenda.</p>
         <button onClick={() => onNavigate('ads')} className="bg-blue-600 text-white px-12 py-5 rounded-2xl font-black uppercase text-sm shadow-xl active:scale-95 transition-all tracking-[0.2em]">Crescer meu Perfil</button>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 pt-24 pb-32 max-w-6xl animate-fade-in">

       <div className="flex flex-col md:flex-row items-center justify-between mb-12 gap-8">
          <div className="flex items-center gap-5">
            <div className="w-16 h-16 rounded-[1.5rem] shadow-xl flex items-center justify-center text-white" style={{ backgroundColor: brandColor }}>
              <CheckBadgeIcon className="h-10 w-10" />
            </div>
            <div>
              <h2 className="text-3xl font-black dark:text-white tracking-tighter uppercase">{brandName || 'Minha Vitrine'}</h2>
              <p className="text-gray-500 text-[10px] font-black uppercase tracking-widest flex items-center gap-2">Painel Profissional <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span></p>
            </div>
          </div>

          <div className="flex bg-gray-100 dark:bg-white/5 p-1.5 rounded-[1.8rem] shadow-inner overflow-x-auto no-scrollbar max-w-full">
             {[
               { id: 'inventory', label: 'Produtos', icon: ArchiveBoxIcon },
               { id: 'orders', label: 'Vendas', icon: ClipboardDocumentListIcon },
               { id: 'sourcing', label: 'Revenda', icon: BoltIcon },
               { id: 'branding', label: 'Marca', icon: PaintBrushIcon }
             ].map(t => (
               <button 
                key={t.id} 
                onClick={() => setActiveTab(t.id as any)} 
                className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === t.id ? 'bg-white dark:bg-darkcard text-blue-600 shadow-lg' : 'text-gray-500'}`}
               >
                 <t.icon className="h-4 w-4" /> {t.label}
               </button>
             ))}
          </div>
       </div>

       {activeTab === 'inventory' && (
         <div className="space-y-8 animate-fade-in">
            <div className="flex justify-between items-center px-4">
               <h3 className="font-black text-xl dark:text-white uppercase tracking-tighter">Estoque Ativo</h3>
               <button onClick={() => setIsAddingProduct(true)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 active:scale-95 transition-all"><PlusIcon className="h-4 w-4 stroke-[4]" /> Adicionar Item</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
               {storeProducts.map(p => (
                 <div key={p.id} className="bg-white dark:bg-darkcard rounded-[2.5rem] overflow-hidden border border-gray-100 dark:border-white/5 shadow-sm group hover:shadow-2xl transition-all">
                    <img src={p.imageUrls[0]} className="h-48 w-full object-cover group-hover:scale-105 transition-transform duration-700" />
                    <div className="p-6">
                       <div className="flex items-center gap-2 mb-2">
                          <span className="text-[8px] font-black uppercase text-blue-600 bg-blue-50 dark:bg-blue-900/20 px-2 py-0.5 rounded">{p.type.replace('DIGITAL_', '')}</span>
                       </div>
                       <h4 className="font-black text-sm dark:text-white uppercase truncate mb-1">{p.name}</h4>
                       <p className="text-2xl font-black text-blue-600 mb-6">${p.price.toFixed(2)}</p>
                       <div className="flex gap-2">
                          <button className="flex-1 bg-gray-50 dark:bg-white/5 text-gray-500 py-3 rounded-xl text-[10px] font-black uppercase">Editar</button>
                          <button className="p-3 bg-red-50 text-red-500 dark:bg-red-900/10 rounded-xl"><TrashIcon className="h-4 w-4"/></button>
                       </div>
                    </div>
                 </div>
               ))}
            </div>
         </div>
       )}

       {activeTab === 'orders' && (
         <div className="space-y-6 animate-fade-in">
            <div className="bg-white dark:bg-darkcard rounded-[2.5rem] overflow-hidden border border-gray-100 dark:border-white/5 shadow-xl">
               <div className="p-6 border-b dark:border-white/5 bg-gray-50 dark:bg-white/5 flex items-center justify-between">
                  <h3 className="font-black text-sm uppercase tracking-widest text-gray-900 dark:text-white">Gerenciamento de Entregas</h3>
                  <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 dark:bg-blue-900/20 px-3 py-1 rounded-full">{storeSales.length} Pedidos</span>
               </div>
               <div className="divide-y divide-gray-50 dark:divide-white/5">
                  {storeSales.length === 0 ? (
                    <div className="p-24 text-center text-gray-400 font-black uppercase text-xs tracking-widest">Aguardando sua primeira venda...</div>
                  ) : (
                    storeSales.map(sale => {
                       const buyer = findUserById(sale.buyerId);
                       const product = getProducts().find(p => p.id === sale.productId);
                       const isPhysical = product?.type === ProductType.PHYSICAL;

                       return (
                         <div key={sale.id} className="p-6 md:p-8 flex flex-col lg:flex-row gap-8 items-start lg:items-center hover:bg-gray-50/50 dark:hover:bg-white/5 transition-colors">
                            <div className="flex items-center gap-5 min-w-[240px]">
                               <img src={product?.imageUrls[0]} className="w-16 h-16 rounded-2xl object-cover shadow-lg" />
                               <div>
                                  <p className="font-black text-sm dark:text-white uppercase truncate max-w-[180px]">{product?.name}</p>
                                  <p className="text-[9px] font-bold text-gray-400 uppercase">#{sale.id.split('-')[1]}</p>
                               </div>
                            </div>

                            <div className="flex-1 space-y-3 w-full">
                               <div className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase">
                                  <ShoppingBagIcon className="h-4 w-4" />
                                  Cliente: {buyer?.firstName} {buyer?.lastName}
                               </div>
                               {isPhysical && sale.shippingAddress && (
                                  <div className="flex items-start gap-2 bg-white dark:bg-darkcard p-3 rounded-xl border border-gray-100 dark:border-white/10 shadow-sm">
                                     <MapPinIcon className="h-4 w-4 text-red-500 shrink-0" />
                                     <span className="text-[10px] font-bold text-gray-500 uppercase leading-snug">
                                        {sale.shippingAddress.address}, {sale.shippingAddress.city} - {sale.shippingAddress.zipCode}
                                     </span>
                                  </div>
                               )}
                               <div className="flex items-center gap-2 text-[10px] font-bold text-gray-400 uppercase">
                                  <ClockIcon className="h-3.5 w-3.5" />
                                  {new Date(sale.timestamp).toLocaleString()}
                               </div>
                            </div>

                            <div className="flex flex-col md:flex-row items-center gap-6 w-full lg:w-auto border-t lg:border-t-0 pt-6 lg:pt-0">
                               <div className="text-center lg:text-right min-w-[100px]">
                                  <p className="text-2xl font-black text-gray-900 dark:text-white">${sale.saleAmount.toFixed(2)}</p>
                                  <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${sale.status === OrderStatus.DELIVERED ? 'bg-green-100 text-green-600' : sale.status === OrderStatus.SHIPPING ? 'bg-blue-100 text-blue-600' : 'bg-orange-100 text-orange-600'}`}>
                                     {sale.status === OrderStatus.WAITLIST ? 'Em Preparo' : sale.status === OrderStatus.SHIPPING ? 'Em Trânsito' : 'Finalizado'}
                                  </span>
                               </div>

                               {/* CONTROLES DE STATUS PARA O VENDEDOR */}
                               <div className="flex flex-wrap gap-2 shrink-0 justify-center">
                                  {sale.status === OrderStatus.WAITLIST && (
                                     <button 
                                      onClick={() => handleUpdateStatus(sale.id, OrderStatus.SHIPPING)}
                                      className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 hover:bg-blue-700 active:scale-95 transition-all"
                                     >
                                        <TruckIcon className="h-5 w-5" /> {isPhysical ? 'Despachar Produto' : 'Marcar como Enviado'}
                                     </button>
                                  )}

                                  {sale.status === OrderStatus.SHIPPING && (
                                     <button 
                                      onClick={() => handleUpdateStatus(sale.id, OrderStatus.DELIVERED)}
                                      className="bg-green-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 hover:bg-green-700 active:scale-95 transition-all"
                                     >
                                        <CheckCircleIcon className="h-5 w-5" /> Confirmar Entrega
                                     </button>
                                  )}

                                  {sale.status === OrderStatus.DELIVERED && (
                                     <div className="flex items-center gap-2 px-6 py-3 bg-gray-100 dark:bg-white/5 text-gray-400 rounded-2xl text-[10px] font-black uppercase border border-gray-200 dark:border-white/10">
                                        <CheckBadgeIcon className="h-5 w-5 text-green-500" /> Venda Concluída
                                     </div>
                                  )}
                               </div>
                            </div>
                         </div>
                       );
                    })
                  )}
               </div>
            </div>
         </div>
       )}

       {activeTab === 'branding' && (
