export const processProductPurchase = (items: any[], bId: string, affId: string | null, addr: any) => {
    const sales = get<any[]>(KEYS.SALES, []);
    const products = getProducts();

    items.forEach(i => {
        const prod = products.find(p => p.id === i.productId);
        sales.push({ 
            id: `sale-${Date.now()}-${i.productId}`, 
            buyerId: bId, 
            productId: i.productId, 
            storeId: prod?.storeId || 'unknown',
            timestamp: Date.now(), 
            status: OrderStatus.WAITLIST,
            shippingAddress: addr,
            saleAmount: (prod?.price || 0) * i.quantity,
            affiliateUserId: affId || ''
        });
    });
    set(KEYS.SALES, sales);
    return true;
};

