  { id: '#2563eb', label: 'Azul', bg: 'bg-blue-600' },
  { id: '#7c3aed', label: 'Roxo', bg: 'bg-purple-600' },
  { id: '#dc2626', label: 'Vermelho', bg: 'bg-red-600' },
  { id: '#f59e0b', label: 'Laranja', bg: 'bg-amber-500' },
  { id: '#10b981', label: 'Verde', bg: 'bg-emerald-500' }
];

const BG_COLORS = [
  { id: 'transparent', label: 'Nenhum', bg: 'bg-transparent border-2 border-dashed' },
  { id: '#000000', label: 'Dark', bg: 'bg-black' },
  { id: '#2563eb', label: 'Blue', bg: 'bg-blue-600' },
  { id: '#7c3aed', label: 'Purple', bg: 'bg-purple-600' },
  { id: '#ec4899', label: 'Pink', bg: 'bg-pink-500' },
  { id: '#10b981', label: 'Green', bg: 'bg-emerald-500' },
  { id: '#f59e0b', label: 'Solar', bg: 'bg-amber-500' },
  { id: '#ef4444', label: 'Red', bg: 'bg-red-500' },
  { id: '#f8fafc', label: 'Sky', bg: 'bg-slate-50' }
];

const SIZES = [
  { id: '14px', label: 'S' },
  { id: '18px', label: 'M' },
  { id: '24px', label: 'L' },
  { id: '36px', label: 'XL' },
  { id: '48px', label: 'XXL' }
];

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId, onCancel }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [reelUrl, setReelUrl] = useState('');
  const [liveTitle, setLiveTitle] = useState('');
  const [liveDescription, setLiveDescription] = useState('');
  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('5.00');
  const [showRecordReel, setShowRecordReel] = useState(false);

  // Estilização
  const [fontFamily, setFontFamily] = useState('font-sans');
  const [textColor, setTextColor] = useState('#000000');
  const [fontSize, setFontSize] = useState('18px');
  const [backgroundColor, setBackgroundColor] = useState('transparent');

  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const reelInputRef = useRef<HTMLInputElement>(null);
  const isEditing = !!postId;
  const isProfessional = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    if (postId) {
      const posts = getPosts();
      const postToEdit = posts.find(p => p.id === postId);
      if (postToEdit) {
        setPostType(postToEdit.type);
        setContent(postToEdit.content || '');
        setImageUrl(postToEdit.imageUrl || '');
        setFontFamily(postToEdit.fontFamily || 'font-sans');
        setTextColor(postToEdit.textColor || '#000000');
        setFontSize(postToEdit.fontSize || '18px');
        setBackgroundColor(postToEdit.backgroundColor || 'transparent');

        if (postToEdit.type === PostType.REEL && postToEdit.reel) {
          setReelUrl(postToEdit.reel.videoUrl);
          setContent(postToEdit.reel.description);
        }

        if (postToEdit.type === PostType.LIVE && postToEdit.liveStream) {
          setLiveTitle(postToEdit.liveStream.title);
          setLiveDescription(postToEdit.liveStream.description);
          setIsLivePaid(postToEdit.liveStream.isPaid);
          setLivePrice(postToEdit.liveStream.price?.toString() || '0');
        }
        setIsExpanded(true);
      }
    }
  }, [postId]);

  const resetState = () => {
    setContent('');
    setImageUrl('');
    setReelUrl('');
    setLiveTitle('');
    setLiveDescription('');
    setIsLivePaid(false);
    setLivePrice('5.00');
    setBackgroundColor('transparent');
    setTextColor('#000000');
    setFontFamily('font-sans');
    setFontSize('18px');
  };

  const handleClose = () => {
    if (onCancel) {
      onCancel();
    } else if (isEditing) {
      onPostCreated(); 
    } else {
      setIsExpanded(false);
      resetState();
    }
  };

  const handleReelFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = function() {
        window.URL.revokeObjectURL(video.src);
        if (video.duration > 60) {
          alert('O Reel deve ter no máximo 1 minuto (60 segundos). Seu vídeo tem ' + Math.round(video.duration) + 's.');
          if (reelInputRef.current) reelInputRef.current.value = '';
          return;
        }

        const reader = new FileReader();
        reader.onloadend = () => {
          setReelUrl(reader.result as string);
        };
        reader.readAsDataURL(file);
      };
      video.src = URL.createObjectURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const postData: Post = {
        id: isEditing ? postId! : `post-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: postType,
        timestamp: isEditing ? (getPosts().find(p => p.id === postId)?.timestamp || Date.now()) : Date.now(),
        content: (postType === PostType.TEXT || postType === PostType.IMAGE) ? content : undefined,
        imageUrl: postType === PostType.IMAGE ? imageUrl : undefined,
        fontFamily: postType === PostType.TEXT ? fontFamily : undefined,
        textColor: postType === PostType.TEXT ? textColor : undefined,
        fontSize: postType === PostType.TEXT ? fontSize : undefined,
        backgroundColor: postType === PostType.TEXT ? backgroundColor : undefined,
        reel: postType === PostType.REEL ? {
          videoUrl: reelUrl,
          description: content || 'Confira meu novo Reel! 🚀'
        } : undefined,
        liveStream: postType === PostType.LIVE ? {
          title: liveTitle,
          description: liveDescription,
          isPaid: isLivePaid,
          price: isLivePaid ? parseFloat(livePrice) : 0
        } : undefined,
        likes: isEditing ? (getPosts().find(p => p.id === postId)?.likes || []) : [],
        comments: isEditing ? (getPosts().find(p => p.id === postId)?.comments || []) : [],
        shares: isEditing ? (getPosts().find(p => p.id === postId)?.shares || []) : [],
        saves: isEditing ? (getPosts().find(p => p.id === postId)?.saves || []) : [],
        indicatedUserIds: isEditing ? (getPosts().find(p => p.id === postId)?.indicatedUserIds || []) : [],
      };

      if (isEditing) updatePost(postData);
      else addPost(postData);

      resetState();
      onPostCreated();
      if (!isEditing && !onCancel) setIsExpanded(false);
    } catch (err) {
      alert('Erro ao salvar publicação.');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveReel = (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onloadend = () => {
      const videoUrl = reader.result as string;
      const newReel: Post = {
        id: `reel-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: PostType.REEL,
        timestamp: Date.now(),
        reel: {
          videoUrl: videoUrl,
          description: "Novo Reel CyBerPhone! 🚀",
          audioTrackId: audioTrackId,
          aiEffectPrompt: aiPrompt,
          filter: filter
        },
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: [],
      };
      addPost(newReel);
      setLoading(false);
      setShowRecordReel(false);
      onPostCreated();
    };
    reader.readAsDataURL(videoBlob);
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-sm p-5 md:p-6 border border-gray-100 dark:border-white/10 flex flex-col gap-5">
         <div className="flex items-start gap-4">
            <img src={currentUser.profilePicture} className="w-12 h-12 rounded-2xl object-cover shrink-0 shadow-lg" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-6 py-3.5 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 font-bold text-xs md:text-sm transition-all hover:bg-gray-100 dark:hover:bg-white/10">
              {isProfessional ? `Olá Mestre, qual conhecimento partilhamos hoje?` : `O que queres aprender ou dizer, ${currentUser.firstName}?`}
            </button>
         </div>
         <div className="flex items-center gap-6 md:gap-10 px-2 border-t border-gray-50 dark:border-white/5 pt-4 overflow-x-auto no-scrollbar">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-3 text-gray-500 hover:text-blue-600 transition-all shrink-0 active:scale-95 group">
               <div className="p-2 bg-blue-50 dark:bg-blue-600/10 rounded-xl group-hover:bg-blue-600 group-hover:text-white transition-all"><PhotoIcon className="h-5 w-5" /></div>
               <span className="text-[10px] font-black uppercase tracking-[0.2em]">Mídia</span>
            </button>
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.REEL); }} className="flex items-center gap-3 text-gray-500 hover:text-purple-600 transition-all shrink-0 active:scale-95 group">
               <div className="p-2 bg-purple-50 dark:bg-purple-600/10 rounded-xl group-hover:bg-purple-600 group-hover:text-white transition-all"><FilmIcon className="h-5 w-5" /></div>
               <span className="text-[10px] font-black uppercase tracking-[0.2em]">Reel</span>
            </button>
            {isProfessional && (
              <button onClick={() => { setIsExpanded(true); setPostType(PostType.LIVE); }} className="flex items-center gap-3 text-gray-500 hover:text-red-600 transition-all shrink-0 active:scale-95 group">
                 <div className="p-2 bg-red-50 dark:bg-red-600/10 rounded-xl group-hover:bg-red-600 group-hover:text-white transition-all"><VideoCameraIcon className="h-5 w-5" /></div>
                 <span className="text-[10px] font-black uppercase tracking-[0.2em]">Mestre Live</span>
              </button>
            )}
         </div>
         {showRecordReel && <RecordReelModal onClose={() => setShowRecordReel(false)} onSave={handleSaveReel} />}
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl p-8 md:p-12 border border-blue-50 dark:border-white/5 animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 left-0 w-2 h-full bg-blue-600"></div>

      <div className="flex items-center justify-between mb-10">
        <div className="flex items-center gap-5">
           <div className={`p-4 text-white rounded-[1.5rem] shadow-2xl ${postType === PostType.LIVE ? 'bg-red-600' : postType === PostType.REEL ? 'bg-purple-600' : 'bg-blue-600'}`}>
             {postType === PostType.LIVE ? <VideoCameraIcon className="h-7 w-7" /> : postType === PostType.REEL ? <FilmIcon className="h-7 w-7" /> : <BriefcaseIcon className="h-7 w-7" />}
           </div>
           <div>
              <h3 className="font-black text-gray-900 dark:text-white uppercase text-[11px] tracking-[0.3em]">{isEditing ? 'Editar Post' : 'Novo Conteúdo'}</h3>
              <p className="text-[9px] text-blue-500 font-black uppercase mt-1 tracking-widest flex items-center gap-2">CyBer Studio Pro <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></span></p>
           </div>
        </div>
        <button onClick={handleClose} className="p-3 bg-gray-50 dark:bg-white/5 text-gray-300 hover:text-red-500 hover:bg-red-50 transition-all rounded-2xl active:scale-90" title="Fechar formulário">
          <XMarkIcon className="h-7 w-7" />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        <div className="flex flex-wrap gap-3 p-2 bg-gray-50 dark:bg-white/5 rounded-[2rem] w-fit">
           {[
             { id: PostType.TEXT, icon: DocumentTextIcon, label: 'Mensagem', locked: false },
             { id: PostType.IMAGE, icon: PhotoIcon, label: 'Mídia', locked: false },
             { id: PostType.REEL, icon: FilmIcon, label: 'Reel', locked: false },
             { id: PostType.LIVE, icon: VideoCameraIcon, label: 'Live Mestre', locked: !isProfessional }
           ].map(t => (
             <button 
              key={t.id} 
              type="button" 
              disabled={t.locked} 
              onClick={() => setPostType(t.id)} 
              className={`flex items-center gap-3 px-6 py-3 rounded-[1.5rem] text-[10px] font-black uppercase tracking-[0.15em] transition-all active:scale-95 ${postType === t.id ? 'bg-white dark:bg-white/10 text-blue-600 dark:text-white shadow-xl' : 'text-gray-400'} ${t.locked ? 'opacity-20 grayscale' : ''}`}
             >
                {t.locked ? <LockClosedIcon className="h-4 w-4" /> : <t.icon className="h-4 w-4" />} {t.label}
             </button>
           ))}
        </div>

        {postType === PostType.TEXT && (
          <div className="space-y-8 animate-fade-in p-8 bg-gray-50 dark:bg-white/5 rounded-[3rem] border border-gray-100 dark:border-white/10">
             <div className="space-y-5">
                <div className="flex items-center justify-between">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Tipografia & Estilo</p>
                  <button type="button" onClick={() => { setFontFamily('font-sans'); setBackgroundColor('transparent'); setTextColor('#000000'); setFontSize('18px'); }} className="text-[8px] font-black text-blue-600 uppercase hover:underline">Resetar Estilo</button>
                </div>
                <div className="flex flex-wrap gap-2 bg-white dark:bg-darkcard p-2 rounded-[2rem] shadow-inner">
                   {FONTS.map(f => (
                     <button 
                       key={f.id} 
                       type="button" 
                       onClick={() => setFontFamily(f.id)} 
                       className={`px-4 py-2 rounded-xl text-[10px] font-bold transition-all border ${fontFamily === f.id ? 'bg-blue-600 text-white border-blue-600 shadow-xl' : 'text-gray-400 border-transparent hover:bg-gray-50 dark:hover:bg-white/5'}`}
                       style={{ fontFamily: f.id.replace('font-', '') }}
                     >
                       {f.label}
                     </button>
                   ))}
                </div>
                <div className="flex flex-wrap gap-12 items-start px-2">
                  <div className="space-y-3">
                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Tamanho</p>
                    <div className="flex gap-2">
                        {SIZES.map(s => (
                          <button key={s.id} type="button" onClick={() => setFontSize(s.id)} className={`w-10 h-10 rounded-xl text-[10px] font-black flex items-center justify-center transition-all active:scale-90 ${fontSize === s.id ? 'bg-black text-white shadow-lg' : 'bg-white dark:bg-white/5 text-gray-400'}`}>{s.label}</button>
                        ))}
                    </div>
                  </div>
                  <div className="space-y-3">
                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Cor Texto</p>
                    <div className="flex gap-3 flex-wrap">
                        {TEXT_COLORS.map(c => (
                          <button key={c.id} type="button" onClick={() => setTextColor(c.id)} className={`w-9 h-9 rounded-full transition-all border-2 ${c.bg} ${textColor === c.id ? 'border-blue-500 scale-125 shadow-xl' : 'border-transparent opacity-60'}`}></button>
                        ))}
                    </div>
                  </div>
                  <div className="space-y-3">
                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Fundo</p>
                    <div className="flex gap-3 flex-wrap">
                        {BG_COLORS.map(c => (
                          <button key={c.id} type="button" onClick={() => setBackgroundColor(c.id)} className={`w-9 h-9 rounded-full transition-all border-2 ${c.bg} ${backgroundColor === c.id ? 'border-blue-600 scale-125 shadow-xl' : 'border-transparent opacity-60'}`}></button>
                        ))}
                    </div>
                  </div>
                </div>
             </div>
          </div>
        )}

        {postType === PostType.REEL && (
           <div className="space-y-8 animate-fade-in">
              <div className="relative group min-h-[400px]">
                 <input type="file" ref={reelInputRef} onChange={handleReelFileChange} accept="video/mp4,video/x-m4v,video/*" className="hidden" />
                 {!reelUrl ? (
                   <div className="flex flex-col md:flex-row gap-4">
                      <div onClick={() => reelInputRef.current?.click()} className="flex-1 h-80 border-4 border-dashed border-gray-100 dark:border-white/5 rounded-[3rem] flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-purple-500 hover:bg-purple-50 dark:hover:bg-purple-900/10 transition-all group">
                          <div className="p-6 bg-gray-50 dark:bg-white/5 rounded-full group-hover:scale-110 transition-transform text-gray-300 group-hover:text-purple-600"><ArrowUpTrayIcon className="h-12 w-12" /></div>
                          <div className="text-center px-4">
                             <span className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em] block">Upload de Vídeo</span>
                             <span className="text-[9px] font-bold text-purple-400 uppercase mt-2 block">Máximo 60 segundos</span>
                          </div>
                      </div>
                      <div onClick={() => setShowRecordReel(true)} className="flex-1 h-80 border-4 border-dashed border-gray-100 dark:border-white/5 rounded-[3rem] flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-red-500 hover:bg-red-50 dark:hover:bg-red-900/10 transition-all group">
                          <div className="p-6 bg-gray-50 dark:bg-white/5 rounded-full group-hover:scale-110 transition-transform text-gray-300 group-hover:text-red-600"><VideoCameraIcon className="h-12 w-12" /></div>
                          <span className="text-[11px] font-black text-gray-400 uppercase tracking-[0.3em]">Gravar ao Vivo</span>
                      </div>
                   </div>
                 ) : (
                   <div className="relative rounded-[3rem] overflow-hidden border-4 border-purple-500 shadow-2xl max-w-sm mx-auto">
                      <video src={reelUrl} controls className="w-full h-auto max-h-[500px]" />
                      <button type="button" onClick={() => setReelUrl('')} className="absolute top-6 right-6 p-3 bg-red-600 text-white rounded-full shadow-2xl active:scale-75 transition-all hover:bg-red-700">
                        <TrashIcon className="h-6 w-6"/>
                      </button>
                   </div>
                 )}
              </div>
              <textarea 
                value={content}
                onChange={e => setContent(e.target.value)}
                placeholder="Legenda para seu Reel..."
                className="w-full p-6 bg-gray-50 dark:bg-white/5 border-2 border-transparent focus:border-purple-500 rounded-[2rem] outline-none font-medium text-sm dark:text-white h-24 resize-none transition-all shadow-inner"
              />
           </div>
        )}

        {postType === PostType.LIVE ? (
          <div className="space-y-8 animate-fade-in">
            <div className="space-y-5">
              <input
                type="text"
                value={liveTitle}
                onChange={(e) => setLiveTitle(e.target.value)}
                className="w-full p-8 bg-gray-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-[2rem] outline-none font-black text-2xl dark:text-white transition-all shadow-inner"
                placeholder="Título Impactante da Aula..."
                required
              />
              <textarea
                value={liveDescription}
                onChange={(e) => setLiveDescription(e.target.value)}
                className="w-full p-8 bg-gray-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-[2rem] outline-none font-medium text-lg dark:text-white h-40 resize-none transition-all shadow-inner"
                placeholder="O que os alunos vão aprender nesta live mestre?"
              />
            </div>

            <div className="p-8 bg-gray-50 dark:bg-white/5 rounded-[3rem] border border-gray-100 dark:border-white/10 space-y-6">
               <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                  <div>
                    <h4 className="text-lg font-black dark:text-white uppercase tracking-tighter">Políticas de Acesso</h4>
                    <p className="text-[10px] text-gray-400 font-bold uppercase mt-1">Monetize seu tempo de ensino</p>
                  </div>
                  <div className="flex bg-white dark:bg-darkcard p-1.5 rounded-2xl shadow-inner">
                     <button 
                       type="button" 
                       onClick={() => setIsLivePaid(false)}
                       className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all active:scale-95 ${!isLivePaid ? 'bg-green-500 text-white shadow-xl' : 'text-gray-400'}`}
                     >
                       Grátis
                     </button>
                     <button 
                       type="button" 
                       onClick={() => setIsLivePaid(true)}
                       className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all active:scale-95 ${isLivePaid ? 'bg-blue-600 text-white shadow-xl' : 'text-gray-400'}`}
                     >
                       Mestre (Paga)
                     </button>
                  </div>
               </div>

               {isLivePaid && (
                 <div className="animate-fade-in flex flex-col md:flex-row items-center gap-6 pt-4">
                    <div className="flex-1 w-full space-y-3">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Valor da Inscrição (USD)</label>
                       <div className="relative group">
                          <BanknotesIcon className="absolute left-6 top-1/2 -translate-y-1/2 h-6 w-6 text-blue-500 group-focus-within:scale-110 transition-transform" />
                          <input 
                            type="number" 
                            step="0.01"
                            min="0.50"
                            value={livePrice}
                            onChange={e => setLivePrice(e.target.value)}
                            className="w-full pl-16 pr-6 py-6 bg-white dark:bg-darkcard rounded-[1.8rem] outline-none font-black text-2xl dark:text-white border-2 border-blue-500/20 focus:border-blue-500 transition-all shadow-xl" 
                          />
                       </div>
                    </div>
                    <div className="bg-blue-600 p-6 rounded-[2rem] shadow-xl text-white max-w-xs">
                       <p className="text-[11px] font-black uppercase tracking-widest leading-relaxed">O saldo será creditado automaticamente na sua carteira após cada entrada de aluno.</p>
                    </div>
                 </div>
               )}
            </div>
          </div>
        ) : (
          postType !== PostType.REEL && (
            <div className="relative group min-h-[400px]">
              <textarea
                value={content}
                onChange={(e) => setContent(e.target.value)}
                className={`w-full p-12 border-4 border-transparent focus:border-blue-500/10 rounded-[3.5rem] outline-none transition-all duration-500 shadow-inner resize-none flex items-center justify-center text-center ${fontFamily}`}
                style={{ 
                  color: textColor, 
                  fontSize: fontSize,
                  backgroundColor: backgroundColor === 'transparent' ? 'transparent' : backgroundColor,
                  minHeight: '400px',
                  display: backgroundColor !== 'transparent' ? 'flex' : 'block',
                  fontFamily: fontFamily.replace('font-', '')
                }}
                placeholder={postType === PostType.IMAGE ? "Descreva esta mídia..." : "Partilhe algo importante com a rede..."}
                required={postType === PostType.TEXT}
              />

              {postType === PostType.IMAGE && (
                <div className="mt-8 space-y-5 animate-fade-in">
                  <input type="file" ref={fileInputRef} onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) {
                      const reader = new FileReader();
                      reader.onloadend = () => setImageUrl(reader.result as string);
                      reader.readAsDataURL(file);
                    }
                  }} accept="image/*" className="hidden" />
                  {!imageUrl ? (
                    <div onClick={() => fileInputRef.current?.click()} className="w-full h-80 border-4 border-dashed border-gray-100 dark:border-white/5 rounded-[3rem] flex flex-col items-center justify-center gap-6 cursor-pointer hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-all group">
                        <div className="p-6 bg-gray-50 dark:bg-white/5 rounded-full group-hover:scale-110 transition-transform"><ArrowUpTrayIcon className="h-12 w-12 text-gray-300 group-hover:text-blue-600" /></div>
