                          <TrashIcon className="h-6 w-6"/>
                        </button>
                    </div>
                  )}
                </div>
              )}
            </div>
          )
        )}

        <div className="flex justify-end pt-10 border-t border-gray-50 dark:border-white/5">
           <button 
              type="submit" 
              disabled={loading || (postType === PostType.TEXT && !content) || (postType === PostType.IMAGE && !imageUrl) || (postType === PostType.REEL && !reelUrl) || (postType === PostType.LIVE && !liveTitle)} 
              className="relative overflow-hidden group/btn bg-gradient-to-r from-blue-600 via-indigo-600 to-indigo-700 text-white px-16 py-6 rounded-[2.5rem] font-black text-sm uppercase shadow-[0_25px_50px_-12px_rgba(37,99,235,0.4)] hover:brightness-110 active:scale-95 transition-all flex items-center gap-4 disabled:opacity-30 disabled:grayscale"
           >
              <div className="absolute inset-0 bg-white/20 translate-x-[-100%] group-hover/btn:translate-x-[100%] transition-transform duration-1000 skew-x-[-20deg]"></div>
              {loading ? 'Processando...' : isEditing ? 'Atualizar' : 'Publicar na Rede'} 
              <ChevronRightIcon className="h-6 w-6" />
           </button>
        </div>
      </form>
      {showRecordReel && <RecordReelModal onClose={() => setShowRecordReel(false)} onSave={handleSaveReel} />}
    </div>
  );
};

