import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, PostType, AudioTrack } from '../types';
import { 
  getPosts, 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  toggleFollowUser, 
  findAudioTrackById, 
  updatePostSaves 
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
import {
  ChatBubbleOvalLeftIcon as ChatIconOutline,
  ShareIcon as ShareIconOutline,
  SpeakerWaveIcon,
  SpeakerXMarkIcon,
  PlayIcon,
  BookmarkIcon as BookmarkIconOutline,
  MusicalNoteIcon
} from '@heroicons/react/24/outline';
import {
  HeartIcon as HeartIconSolid,
  BookmarkIcon as BookmarkIconSolid,
  PlusIcon
} from '@heroicons/react/24/solid';
import CommentsModal from './CommentsModal';
import IndicateModal from './IndicateModal';

interface ReelsPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

interface ReelVideoProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  isIntersecting: boolean;
  onPostUpdate: () => void;
}

const ReelVideo: React.FC<ReelVideoProps> = ({ post, currentUser, onNavigate, onFollowToggle, refreshUser, isIntersecting, onPostUpdate }) => {
  if (!post || !currentUser) return null;

  const videoRef = useRef<HTMLVideoElement>(null);
  const [isMuted, setIsMuted] = useState(true);
  const [showPlayIcon, setShowPlayIcon] = useState(false);
  const [isCommentsModalOpen, setIsCommentsModalOpen] = useState(false);
  const [isIndicateModalOpen, setIsIndicateModalOpen] = useState(false);
  const [likeHearts, setLikeHearts] = useState<{ id: number; x: number; y: number }[]>([]);
  const [videoProgress, setVideoProgress] = useState(0);

  const clickTimeout = useRef<number | null>(null);

  const postAuthor = findUserById(post.userId);
  const isFollowing = currentUser.followedUsers?.includes(post.userId);
  const hasLiked = post.likes?.includes(currentUser.id);
  const hasSaved = post.saves?.includes(currentUser.id);
  const [audioTrack, setAudioTrack] = useState<AudioTrack | null>(null);

  useEffect(() => {
    if (post.reel?.audioTrackId) {
      setAudioTrack(findAudioTrackById(post.reel.audioTrackId) || null);
    }
  }, [post.reel?.audioTrackId]);

  const syncPlay = useCallback(async () => {
    const video = videoRef.current;
    if (!video) return;
    try {
      video.muted = isMuted;
      if (video.paused) await video.play();
    } catch (e) {}
  }, [isMuted]);

  const syncPause = useCallback(() => {
    const video = videoRef.current;
    if (video && !video.paused) video.pause();
  }, []);

  useEffect(() => {
    if (isIntersecting) syncPlay();
    else syncPause();
  }, [isIntersecting, syncPlay, syncPause]);

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      const progress = (videoRef.current.currentTime / videoRef.current.duration) * 100;
      setVideoProgress(progress);
    }
  };

  const togglePlayPause = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) {
      syncPlay();
      setShowPlayIcon(false);
    } else {
      syncPause();
      setShowPlayIcon(true);
    }
  };

  const handleLike = () => {
    updatePostLikes(post.id, currentUser.id);
    onPostUpdate();
    refreshUser();
  };

  const handleDoubleClick = (e: React.MouseEvent | React.TouchEvent) => {
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    const x = ('clientX' in e ? e.clientX : (e as React.TouchEvent).touches[0].clientX) - rect.left;
    const y = ('clientY' in e ? e.clientY : (e as React.TouchEvent).touches[0].clientY) - rect.top;

    const newHeart = { id: Date.now(), x, y };
    setLikeHearts(prev => [...prev, newHeart]);
    if (!hasLiked) handleLike();
    setTimeout(() => setLikeHearts(prev => prev.filter(h => h.id !== newHeart.id)), 800);
  };

  const handleContainerClick = (e: React.MouseEvent) => {
    if (clickTimeout.current) {
      window.clearTimeout(clickTimeout.current);
      clickTimeout.current = null;
      handleDoubleClick(e);
    } else {
      clickTimeout.current = window.setTimeout(() => {
        togglePlayPause();
        clickTimeout.current = null;
      }, 250);
    }
  };

  if (!postAuthor || !post.reel) return null;

  return (
    <div 
      className="relative w-full h-full snap-start snap-always overflow-hidden bg-black flex items-center justify-center"
      onClick={handleContainerClick}
    >
      {/* VIDEO ELEMENT */}
      <video
        ref={videoRef}
        src={post.reel.videoUrl}
        loop
        playsInline
        webkit-playsinline="true"
        onTimeUpdate={handleTimeUpdate}
        className="w-full h-full object-cover md:max-w-lg md:mx-auto"
        style={{ filter: post.reel.filter || 'none' }}
      />

      {/* PROGRESS OVERLAY */}
      <div className="absolute bottom-0 left-0 w-full h-1 bg-white/10 z-50">
        <div 
          className="h-full bg-blue-600 transition-all duration-100 ease-linear shadow-[0_0_10px_#2563eb]" 
          style={{ width: `${videoProgress}%` }}
        />
      </div>

      {/* GRADIENT OVERLAYS */}
      <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/60 pointer-events-none"></div>

      {/* PLAY ICON OVERLAY */}
      {showPlayIcon && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <div className="bg-black/20 p-6 rounded-full backdrop-blur-md">
            <PlayIcon className="h-16 w-16 text-white/80" />
          </div>
        </div>
      )}

      {/* LIKE ANIMATIONS */}
      {likeHearts.map(heart => (
        <div key={heart.id} className="absolute z-50 pointer-events-none animate-like-heart" style={{ left: heart.x - 40, top: heart.y - 40 }}>
          <HeartIconSolid className="w-24 h-24 text-red-500 drop-shadow-[0_0_20px_rgba(239,68,68,0.8)]" />
        </div>
      ))}

      {/* MUTE TOGGLE */}
      <button 
        onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }}
        className="absolute top-6 right-6 p-3 bg-black/20 backdrop-blur-md rounded-2xl text-white hover:bg-black/40 transition-all active:scale-90 z-40 border border-white/10"
      >
        {isMuted ? <SpeakerXMarkIcon className="h-6 w-6" /> : <SpeakerWaveIcon className="h-6 w-6" />}
      </button>

      {/* ACTIONS SIDEBAR */}
      <div className="absolute bottom-24 right-4 flex flex-col items-center gap-6 z-40">
        <div className="relative mb-2">
          <div 
            className="w-14 h-14 rounded-full border-2 border-white overflow-hidden cursor-pointer shadow-2xl"
            onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}
          >
            <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-full h-full object-cover" />
          </div>
          {!isFollowing && currentUser.id !== post.userId && (
            <button 
              onClick={(e) => { e.stopPropagation(); onFollowToggle(post.userId); }}
              className="absolute -bottom-1 left-1/2 -translate-x-1/2 bg-blue-600 text-white rounded-full p-1 border-2 border-white shadow-xl active:scale-90"
            >
              <PlusIcon className="h-3 w-3" />
            </button>
          )}
        </div>

        <button onClick={(e) => { e.stopPropagation(); handleLike(); }} className="flex flex-col items-center group">
          <HeartIconSolid className={`h-10 w-10 drop-shadow-xl transition-all duration-300 group-active:scale-125 ${hasLiked ? 'text-red-500' : 'text-white'}`} />
          <span className="text-[12px] font-black text-white mt-1 drop-shadow-md">{post.likes?.length || 0}</span>
        </button>

        <button onClick={(e) => { e.stopPropagation(); setIsCommentsModalOpen(true); }} className="flex flex-col items-center group">
          <ChatIconOutline className="h-10 w-10 text-white drop-shadow-xl group-active:scale-125 transition-transform" />
          <span className="text-[12px] font-black text-white mt-1 drop-shadow-md">{post.comments?.length || 0}</span>
        </button>

        <button onClick={(e) => { e.stopPropagation(); updatePostSaves(post.id, currentUser.id); onPostUpdate(); }} className="flex flex-col items-center group">
          <BookmarkIconSolid className={`h-10 w-10 drop-shadow-xl transition-all duration-300 group-active:scale-125 ${hasSaved ? 'text-yellow-400' : 'text-white'}`} />
          <span className="text-[12px] font-black text-white mt-1 drop-shadow-md">{post.saves?.length || 0}</span>
        </button>

        <button onClick={(e) => { e.stopPropagation(); setIsIndicateModalOpen(true); }} className="flex flex-col items-center group">
          <ShareIconOutline className="h-10 w-10 text-white drop-shadow-xl group-active:scale-125 transition-transform" />
          <span className="text-[10px] font-black text-white uppercase mt-1 drop-shadow-md">Indicar</span>
        </button>

        <div className="pt-2">
          <div className="w-12 h-12 rounded-full bg-gradient-to-r from-gray-800 to-gray-900 border-4 border-gray-700/50 flex items-center justify-center overflow-hidden shadow-2xl animate-spin-slow">
            <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-full h-full object-cover opacity-60" />
          </div>
        </div>
      </div>

      {/* INFO AREA */}
      <div className="absolute bottom-10 left-6 right-24 z-30 pointer-events-none flex flex-col gap-3">
        <div 
          className="flex items-center gap-2 pointer-events-auto cursor-pointer w-fit"
          onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}
        >
          <span className="font-black text-lg text-white hover:underline drop-shadow-lg">@{post.authorName}</span>
          <span className="bg-white/10 backdrop-blur-md px-2 py-0.5 rounded-lg text-[9px] font-black text-white uppercase border border-white/10">Mestre</span>
        </div>

        <p className="text-sm text-white/90 font-medium leading-snug drop-shadow-md pointer-events-auto line-clamp-3">
          {post.reel.description}
        </p>

        <div className="flex items-center gap-2 mt-2 pointer-events-auto w-fit bg-black/20 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/5">
          <MusicalNoteIcon className="h-4 w-4 text-white animate-pulse" />
          <div className="overflow-hidden max-w-[150px]">
            <div className="whitespace-nowrap text-[11px] font-black text-white uppercase tracking-wider animate-marquee">
              {audioTrack ? `${audioTrack.title} - ${audioTrack.artist}` : `Áudio Original • ${post.authorName}`}
            </div>
          </div>
        </div>
      </div>

      {isCommentsModalOpen && (
        <CommentsModal postId={post.id} currentUser={currentUser} onClose={() => setIsCommentsModalOpen(false)} onCommentsUpdated={onPostUpdate} />
      )}

      {isIndicateModalOpen && (
        <IndicateModal post={post} currentUser={currentUser} onClose={() => setIsIndicateModalOpen(false)} onPostUpdated={onPostUpdate} />
      )}

      <style>{`
        .animate-spin-slow { animation: spin 6s linear infinite; }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

        @keyframes marquee {
          0% { transform: translateX(100%); }
          100% { transform: translateX(-100%); }
        }
        .animate-marquee {
          display: inline-block;
          animation: marquee 10s linear infinite;
        }

        @keyframes like-heart {
          0% { transform: scale(0); opacity: 0; }
          20% { transform: scale(1.2) rotate(15deg); opacity: 1; }
          80% { transform: scale(1) rotate(-10deg); opacity: 1; }
          100% { transform: scale(2); opacity: 0; }
        }
        .animate-like-heart { animation: like-heart 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </div>
  );
};

const ReelsPage: React.FC<ReelsPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [reels, setReels] = useState<Post[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);
  const [visibleIdx, setVisibleIdx] = useState(0);

  useEffect(() => {
    const fetchReels = () => {
      const posts = getPosts().filter(p => p.type === PostType.REEL);
      setReels(posts);
    };
    fetchReels();
  }, []);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          setVisibleIdx(Number((e.target as HTMLElement).dataset.idx));
        }
      });
    }, { threshold: 0.6 });

    const items = containerRef.current?.children;
    if (items) {
      Array.from(items).forEach(item => {
        if ((item as HTMLElement).dataset.idx !== undefined) {
          observer.observe(item);
        }
      });
    }
    return () => observer.disconnect();
  }, [reels]);

  const handleFollow = (id: string) => {
    toggleFollowUser(currentUser.id, id);
    refreshUser();
  };

  return (
    <div 
      className="fixed inset-0 top-[64px] md:top-[72px] md:ml-64 bottom-[64px] md:bottom-0 bg-black z-10"
    >
      <div 
        ref={containerRef} 
        className="w-full h-full overflow-y-scroll snap-y snap-mandatory no-scrollbar scroll-smooth"
        style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
      >
        {reels.length > 0 ? (
          reels.map((r, i) => (
            <div 
              key={r.id} 
              data-idx={i} 
              className="h-full w-full snap-start snap-always"
            >
              <ReelVideo 
                post={r} 
                currentUser={currentUser} 
                onNavigate={onNavigate} 
                onFollowToggle={handleFollow} 
                refreshUser={refreshUser} 
                isIntersecting={i === visibleIdx}
                onPostUpdate={() => setReels(getPosts().filter(p => p.type === PostType.REEL))}
              />
            </div>
          ))
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-white p-10 text-center">
            <MusicalNoteIcon className="h-20 w-20 text-gray-800 mb-6" />
            <h3 className="text-2xl font-black uppercase tracking-tighter">Nenhum Reel ainda</h3>
            <p className="text-gray-500 mt-2 font-medium">Seja o primeiro mestre a publicar conteúdo vertical!</p>
          </div>
        )}
      </div>
    </div>
  );
};

