    setNewCommentText('');
    onCommentsUpdated();
    setPost(prevPost => prevPost ? { ...prevPost, comments: [...prevPost.comments, newComment] } : null);

    if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
    }
  };

  const handleTextareaChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setNewCommentText(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = `${Math.min(e.target.scrollHeight, 100)}px`;
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
        onClose();
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [onClose]);

  if (!post) return null;

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-[2px] flex items-end justify-center z-[1000] animate-fade-in px-0 sm:px-4">
      <div 
        ref={modalRef} 
        className="bg-white dark:bg-[#0f1117] w-full max-w-lg h-[75vh] sm:h-[80vh] rounded-t-[1.8rem] sm:rounded-t-[2.5rem] shadow-2xl flex flex-col animate-slide-up overflow-hidden border-t border-white/10"
      >
        {/* Barra de arraste visual */}
        <div className="w-10 h-1 bg-gray-200 dark:bg-white/10 rounded-full mx-auto mt-3 mb-1 shrink-0"></div>

        <header className="flex items-center justify-between px-4 sm:px-6 py-2 sm:py-4 border-b border-gray-100 dark:border-white/5 sticky top-0 bg-white dark:bg-[#0f1117] z-10">
          <div>
            <h2 className="text-base sm:text-lg font-black text-gray-900 dark:text-white tracking-tighter">Comentários</h2>
            <p className="text-[8px] sm:text-[10px] text-gray-400 font-bold uppercase tracking-widest">{post.comments.length} mensagens</p>
          </div>
          <button onClick={onClose} className="p-1.5 sm:p-2 rounded-xl bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-gray-900 dark:hover:text-white transition-all active:scale-90">
            <XMarkIcon className="h-5 w-5 sm:h-6 sm:w-6" />
          </button>
        </header>

        <div className="flex-grow p-3 sm:p-6 overflow-y-auto space-y-4 sm:space-y-6 custom-scrollbar bg-gray-50/20 dark:bg-black/20">
          {post.comments.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-center opacity-30 py-10">
              <ChatBubbleOvalLeftIcon className="h-10 w-10 text-gray-400 mb-2" />
              <p className="font-black uppercase text-[9px] tracking-widest dark:text-white">Sem comentários</p>
            </div>
          ) : (
            [...post.comments].sort((a, b) => b.timestamp - a.timestamp).map(comment => (
              <div key={comment.id} className="flex gap-2 sm:gap-4 animate-fade-in">
                <img 
                  src={comment.profilePic || DEFAULT_PROFILE_PIC} 
                  className="w-8 h-8 sm:w-10 sm:h-10 rounded-lg object-cover border border-gray-100 dark:border-white/10 shrink-0" 
                  alt=""
                />
                <div className="flex-1 min-w-0">
                  <div className="bg-white dark:bg-white/5 p-2.5 sm:p-4 rounded-xl rounded-tl-none border border-gray-100 dark:border-white/5 shadow-sm">
                    <p className="font-black text-[9px] sm:text-[11px] text-blue-600 dark:text-blue-400 uppercase tracking-tighter mb-0.5 truncate">{comment.userName}</p>
                    <p className="text-[13px] sm:text-sm text-gray-800 dark:text-gray-200 leading-snug font-medium break-words">{comment.text}</p>
                  </div>
                  <span className="text-[7px] sm:text-[9px] font-bold text-gray-400 uppercase mt-1 ml-1">
                    {new Date(comment.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))
          )}
        </div>

        <footer className="p-3 sm:p-6 border-t border-gray-100 dark:border-white/10 bg-white dark:bg-[#0f1117] sticky bottom-0">
          <form onSubmit={handleAddComment} className="flex items-end gap-2">
            <div className="flex-1 relative flex items-center bg-gray-50 dark:bg-white/5 border border-transparent focus-within:border-blue-500 rounded-xl transition-all shadow-inner">
              <textarea
                ref={textareaRef}
                value={newCommentText}
                onChange={handleTextareaChange}
                placeholder="Diga algo..."
                rows={1}
                className="w-full bg-transparent p-2.5 sm:p-3 pr-10 outline-none font-medium text-[13px] sm:text-sm dark:text-white resize-none max-h-24"
                required
              />
              <button
                type="submit"
                disabled={!newCommentText.trim()}
                className="absolute right-1 bottom-1 p-2 bg-blue-600 text-white rounded-lg shadow-lg active:scale-90 transition-all disabled:opacity-30 disabled:grayscale"
              >
                <PaperAirplaneIcon className="h-3.5 w-3.5 -rotate-45" />
