import React, { useState } from 'react';
import { User, UserType, PaymentCard } from '../types';
import { updateUser, requestDebitCard } from '../services/storageService';
import { 
  ShieldCheckIcon, 
  BellIcon, 
  UserIcon, 
  PaintBrushIcon, 
  ArrowLeftIcon, 
  CreditCardIcon,
  CheckIcon,
  XMarkIcon,
  ArrowRightOnRectangleIcon,
  TrashIcon,
  CreditCardIcon as CreditCardIconSolid,
  ShieldExclamationIcon,
  SparklesIcon,
  CpuChipIcon,
  WifiIcon,
  LockClosedIcon
} from '@heroicons/react/24/outline';

interface SettingsPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  darkMode: boolean;
  toggleTheme: () => void;
  refreshUser: () => void;
  onLogout: () => void;
  onDeleteAccount: () => void;
}

const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'security'>('main');
  const [notifications, setNotifications] = useState(true);

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // States para solicitação de cartão
  const [isRequestingCard, setIsRequestingCard] = useState(false);

  const handleSaveProfile = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    const updatedUser: User = {
      ...currentUser,
      firstName,
      lastName,
      bio,
      credentials,
      profilePicture
    };

    setTimeout(() => {
      updateUser(updatedUser);
      refreshUser();
      setIsSaving(false);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    }, 1000);
  };

  const handleRequestVirtualCard = () => {
    setIsRequestingCard(true);

    // Simula a geração de um cartão pela rede CyBer
    setTimeout(() => {
      const newCard: PaymentCard = {
        cardNumber: `4500 ${Math.floor(1000 + Math.random() * 9000)} ${Math.floor(1000 + Math.random() * 9000)} ${Math.floor(1000 + Math.random() * 9000)}`,
        holderName: `${currentUser.firstName} ${currentUser.lastName}`.toUpperCase(),
        expiryDate: '12/30',
        cvv: Math.floor(100 + Math.random() * 899).toString(),
        type: 'CREDIT'
      };

      requestDebitCard(currentUser.id, newCard);
      refreshUser();
      setIsRequestingCard(false);
      alert('Seu CyBer Card Virtual foi emitido com sucesso!');
    }, 2000);
  };

  const handleDeletePress = () => {
    const confirmed = window.confirm("ATENÇÃO: Esta ação é irreversível. Todos os seus dados, aulas e saldo serão permanentemente excluídos. Deseja continuar?");
    if (confirmed) {
      onDeleteAccount();
    }
  };

  const sections = [
    ...(currentUser.isAdmin ? [{ 
        title: 'Gestão do Sistema', items: [
            { label: 'Painel Admin', icon: ShieldExclamationIcon, desc: 'Controle global da plataforma', onClick: () => onNavigate('admin') }
        ] 
    }] : []),
    { title: 'Conta', items: [
        { label: 'Informações Pessoais', icon: UserIcon, desc: 'Nome, bio e foto', onClick: () => setView('edit-profile') },
        { label: 'CyBer Card Virtual', icon: CreditCardIcon, desc: 'Solicite seu cartão da rede', onClick: () => setView('payments') },
        { label: 'Segurança e Senha', icon: ShieldCheckIcon, desc: 'Mude sua senha de acesso', onClick: () => setView('security') }
    ]},
    { title: 'Preferências', items: [
        { label: 'Notificações Push', icon: BellIcon, desc: 'Avisos de novos posts e vendas', toggle: notifications, onToggle: () => setNotifications(!notifications) },
        { label: 'Tema Escuro', icon: PaintBrushIcon, desc: 'Alternar entre claro e escuro', toggle: darkMode, onToggle: toggleTheme }
    ]},
    { title: 'Sessão', items: [
        { label: 'Sair da Conta', icon: ArrowRightOnRectangleIcon, desc: 'Desconectar deste dispositivo', onClick: onLogout }
    ]}
  ];

  if (view === 'edit-profile') {
    return (
      <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
        <div className="flex items-center gap-6 mb-10">
          <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-blue-600 transition-all">
            <ArrowLeftIcon className="h-6 w-6" />
