import React, { useState } from 'react';
import { User, UserType, PaymentCard } from '../types';
import { updateUser, requestDebitCard, updateUserBalance } from '../services/storageService';
import { 
  ShieldCheckIcon, 
  BellIcon, 
  UserIcon, 
  PaintBrushIcon, 
  ArrowLeftIcon, 
  CreditCardIcon,
  CheckIcon,
  XMarkIcon,
  ArrowRightOnRectangleIcon,
  TrashIcon,
  CreditCardIcon as CreditCardIconSolid,
  ShieldExclamationIcon,
  SparklesIcon,
  CpuChipIcon,
  WifiIcon,
  LockClosedIcon,
  GlobeAltIcon,
  CurrencyDollarIcon
} from '@heroicons/react/24/outline';

interface SettingsPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  darkMode: boolean;
  toggleTheme: () => void;
  refreshUser: () => void;
  onLogout: () => void;
  onDeleteAccount: () => void;
}

const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'security'>('main');
  const [notifications, setNotifications] = useState(true);

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // States para solicitação de cartão
  const [isRequestingCard, setIsRequestingCard] = useState(false);
  const CARD_ISSUE_COST = 2.00;

  const handleSaveProfile = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    const updatedUser: User = {
      ...currentUser,
      firstName,
      lastName,
      bio,
      credentials,
      profilePicture
    };

    setTimeout(() => {
      updateUser(updatedUser);
      refreshUser();
      setIsSaving(false);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    }, 1000);
  };

  const handleRequestVirtualCard = () => {
    if ((currentUser.balance || 0) < CARD_ISSUE_COST) {
      alert(`Saldo insuficiente. A emissão do CyBer Card custa $${CARD_ISSUE_COST.toFixed(2)}.`);
      return;
    }

    if (!window.confirm(`Deseja emitir seu CyBer Card Virtual? Um valor de $${CARD_ISSUE_COST.toFixed(2)} será debitado do seu saldo.`)) {
      return;
    }

    setIsRequestingCard(true);

    // Simula a geração de um cartão pela rede CyBer após cobrança
    setTimeout(() => {
      const newCard: PaymentCard = {
        cardNumber: `4500 ${Math.floor(1000 + Math.random() * 9000)} ${Math.floor(1000 + Math.random() * 9000)} ${Math.floor(1000 + Math.random() * 9000)}`,
        holderName: `${currentUser.firstName} ${currentUser.lastName}`.toUpperCase(),
        expiryDate: '12/30',
        cvv: Math.floor(100 + Math.random() * 899).toString(),
        type: 'CREDIT'
      };

      updateUserBalance(currentUser.id, -CARD_ISSUE_COST);
      requestDebitCard(currentUser.id, newCard);
      refreshUser();
      setIsRequestingCard(false);
      alert('Seu CyBer Card Virtual foi emitido com sucesso! O custo de $2.00 foi descontado do seu saldo.');
    }, 2000);
  };

  const handleDeletePress = () => {
    const confirmed = window.confirm("ATENÇÃO: Esta ação é irreversível. Todos os seus dados, aulas e saldo serão permanentemente excluídos. Deseja continuar?");
    if (confirmed) {
      onDeleteAccount();
    }
