          </button>
        </form>
      </div>
    );
  }

  if (view === 'payments') {
    return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
          <div className="flex items-center gap-6 mb-10">
            <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-blue-600 transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
            <h2 className="text-4xl font-black dark:text-white tracking-tighter">CyBer Card</h2>
          </div>

          <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10 space-y-10">
             {/* VISA VIRTUAL PREVIEW */}
             <div className="relative group perspective-1000">
                <div className="bg-gradient-to-br from-gray-900 via-blue-900 to-indigo-900 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden border border-white/20 aspect-[1.6/1] flex flex-col justify-between transform transition-transform duration-700 group-hover:rotate-y-12">
                   <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>

                   <div className="flex justify-between items-start relative z-10">
                      <div className="space-y-1">
                         <h4 className="text-xl font-black italic tracking-tighter">CyBer<span className="text-blue-400">Phone</span></h4>
