const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'security'>('main');
  const [notifications, setNotifications] = useState(true);
  const [showSensitiveData, setShowSensitiveData] = useState(false);

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // States para solicitação de Cartão CyBer
  const [isRequestingCard, setIsRequestingCard] = useState(false);
  const [activationStatus, setActivationStatus] = useState('');
  const CARD_ISSUE_COST = 2.00;

  const handleSaveProfile = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    const updatedUser: User = { ...currentUser, firstName, lastName, bio, credentials, profilePicture };
    setTimeout(() => {
      updateUser(updatedUser);
      refreshUser();
      setIsSaving(false);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    }, 1000);
  };

  const handleRequestCyberCard = async () => {
    if ((currentUser.balance || 0) < CARD_ISSUE_COST) {
      alert(`Saldo insuficiente. A taxa de ativação da Rede CyBer é de $${CARD_ISSUE_COST.toFixed(2)}.`);
      return;
    }

    if (!window.confirm(`Confirmar emissão do CyBer Card Pro? O valor de $${CARD_ISSUE_COST.toFixed(2)} será debitado da sua carteira.`)) {
      return;
    }

    setIsRequestingCard(true);

    const steps = [
      "Iniciando Protocolo CyBer Sec...",
      "Sincronizando com a Rede de Pagamentos...",
      "Verificando Integridade da Conta...",
      "Gerando Criptografia de Ponta...",
      "Ativando Chip Virtual CyBer Pro..."
    ];

    for (const step of steps) {
      setActivationStatus(step);
      await new Promise(r => setTimeout(r, 1000));
