           </div>
           <textarea value={bio} onChange={e => setBio(e.target.value)} placeholder="Biografia" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-medium h-32 resize-none" />
           <button type="submit" disabled={isSaving} className="w-full py-5 bg-blue-600 text-white rounded-[2rem] font-black uppercase shadow-xl transition-all active:scale-95">
