                >
                  <div className="flex items-center gap-5">
                    <div className={`p-3 rounded-2xl ${item.label === 'Sair da Conta' ? 'bg-red-50 dark:bg-red-500/10 text-red-500' : 'bg-blue-50 dark:bg-blue-500/10 text-blue-600'}`}>
                      <item.icon className="h-6 w-6" />
