import React from 'react';
import { AdCampaign } from '../types';
import { findUserById } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  MegaphoneIcon, 
  GlobeAltIcon, 
  ArrowTopRightOnSquareIcon, 
  SparklesIcon,
  CheckBadgeIcon,
  TrophyIcon
} from '@heroicons/react/24/solid';

interface AdCardProps {
  ad: AdCampaign;
  isSidebar?: boolean;
  rank?: number; // Posição no leilão (0 = lance mais alto)
}

const AdCard: React.FC<AdCardProps> = ({ ad, isSidebar = false, rank = 0 }) => {
  const professor = findUserById(ad.professorId);
  if (!professor) return null;

  const getRankBadge = () => {
    if (rank === 0) return { label: 'Top Bid', color: 'bg-yellow-400 text-yellow-900', icon: TrophyIcon };
    if (rank === 1) return { label: 'Bid Prata', color: 'bg-slate-300 text-slate-700', icon: SparklesIcon };
    if (rank === 2) return { label: 'Bid Bronze', color: 'bg-orange-300 text-orange-800', icon: MegaphoneIcon };
    return null;
  };

  const rankBadge = getRankBadge();

  if (isSidebar) {
    return (
      <div className="bg-white dark:bg-darkcard p-4 rounded-3xl border border-blue-100 dark:border-blue-900/30 shadow-sm hover:shadow-lg transition-all group cursor-pointer relative overflow-hidden">
         {rankBadge && (
           <div className={`absolute top-0 right-0 px-2 py-0.5 rounded-bl-lg text-[6px] font-black uppercase ${rankBadge.color} z-10 shadow-sm`}>
              {rankBadge.label}
           </div>
         )}
         <div className="relative h-32 rounded-2xl overflow-hidden mb-3">
            <img src={ad.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt="" />
            <div className="absolute top-2 left-2 bg-blue-600 text-white text-[7px] font-black uppercase px-2 py-0.5 rounded shadow-lg flex items-center gap-1">
               <MegaphoneIcon className="h-2 w-2" /> Patrocinado
