export default AdCard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { AdCampaign, User, UserType } from '../types';
import { saveAds, getAds, updateUserBalance } from '../services/storageService';
import { generateAdCopy } from '../services/geminiService';
import { MIN_DAILY_AD_BUDGET_USD, DEFAULT_PROFILE_PIC, CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../constants';
import { 
  RocketLaunchIcon, 
  MegaphoneIcon, 
  CursorArrowRaysIcon, 
  PhotoIcon, 
  ChevronRightIcon, 
  ChevronLeftIcon, 
  SparklesIcon, 
  CheckCircleIcon, 
  MapPinIcon, 
  GlobeAltIcon, 
  XMarkIcon, 
  PlusIcon, 
  InformationCircleIcon, 
  UserGroupIcon, 
  ExclamationTriangleIcon, 
  ShieldCheckIcon, 
  PresentationChartLineIcon, 
  ArrowTrendingUpIcon, 
  CheckBadgeIcon, 
  TrophyIcon,
  UserIcon,
  BanknotesIcon
} from '@heroicons/react/24/solid';

interface AdCampaignPageProps {
  currentUser: User;
  refreshUser: () => void;
  onNavigate?: (page: string) => void;
}

type Step = 'objective' | 'creative' | 'targeting' | 'budget';

const AdCampaignPage: React.FC<AdCampaignPageProps> = ({ currentUser, refreshUser, onNavigate }) => {
  const [currentStep, setCurrentStep] = useState<Step>('objective');
  const [loading, setLoading] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);

  // Form States
  const [objective, setObjective] = useState<'traffic' | 'awareness' | 'engagement'>('traffic');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [linkUrl, setLinkUrl] = useState('');
  const [ctaText, setCtaText] = useState('Saiba Mais');
  const [targetAudience, setTargetAudience] = useState('');
  const [minAge, setMinAge] = useState<number>(18);
  const [maxAge, setMaxAge] = useState<number>(65);
  const [durationDays, setDurationDays] = useState<number>(7);
  const [dailyReachGoal, setDailyReachGoal] = useState<number>(5000);
  const [locations, setLocations] = useState<string[]>(['Brasil']);
  const [newLoc, setNewLoc] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const COST_PER_1K_REACH = 0.50; 
  const calculatedTotalBudget = useMemo(() => {
    const costPerDay = (dailyReachGoal / 1000) * COST_PER_1K_REACH;
    return Math.max(costPerDay * durationDays, durationDays * MIN_DAILY_AD_BUDGET_USD);
  }, [dailyReachGoal, durationDays]);

  const hasBalance = (currentUser.balance || 0) >= calculatedTotalBudget;
  const followerCount = currentUser.followers?.length || 0;
  const progressPercent = Math.min((followerCount / CREATOR_UPGRADE_FOLLOWERS_GOAL) * 100, 100);

  const handleAiGenerate = async () => {
    if (!targetAudience) {
      alert("Descreva brevemente o público ou curso para a IA te ajudar.");
      return;
    }
    setAiLoading(true);
    try {
      const copy = await generateAdCopy(`Anúncio para público interessado em: ${targetAudience}`);
      const parts = copy.split('Texto:');
      if (parts.length > 1) {
        setTitle(parts[0].replace('Título:', '').trim());
        setDescription(parts[1].trim());
      } else {
        setDescription(copy);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setAiLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImageUrl(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handlePublish = () => {
    if (!hasBalance) return;
    setLoading(true);
    setTimeout(() => {
      const newAd: AdCampaign = {
        id: `ad-${Date.now()}`,
        professorId: currentUser.id,
        title,
        description,
        targetAudience,
        minAge,
        maxAge,
        budget: calculatedTotalBudget,
        isActive: true,
        imageUrl,
        linkUrl: linkUrl || '#',
        ctaText,
        timestamp: Date.now()
      };

      updateUserBalance(currentUser.id, -calculatedTotalBudget);
      saveAds([...getAds(), newAd]);
      alert("Sua campanha foi lançada no leilão! Quanto maior seu investimento, mais vezes e mais alto você aparecerá no feed.");
      if(onNavigate) onNavigate('feed');
      else window.location.reload(); 
    }, 2000);
  };

  const addLocation = () => {
    if (newLoc.trim()) {
      setLocations([...locations, newLoc.trim()]);
      setNewLoc('');
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-[#080a0f] pt-24 pb-32 px-4">
      <div className="max-w-7xl mx-auto">

        <div className="bg-white dark:bg-darkcard p-6 md:p-8 rounded-[2.5rem] shadow-xl border border-blue-500/10 mb-10 relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
              <TrophyIcon className="h-40 w-40 text-blue-600" />
           </div>
           <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 relative z-10">
              <div className="flex-1">
                 <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter flex items-center gap-2">
                    <SparklesIcon className="h-6 w-6 text-yellow-500" /> 
                    {currentUser.userType === UserType.CREATOR ? 'Leilão de Atenção CyBer' : 'Caminho para o Sucesso'}
                 </h3>
                 <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest mt-1">
                    {currentUser.userType === UserType.CREATOR 
                      ? 'O sistema de leilão garante que o maior lance tenha prioridade no feed.' 
                      : `Atinja ${CREATOR_UPGRADE_FOLLOWERS_GOAL} seguidores para desbloquear ferramentas profissionais gratuitas.`}
                 </p>
                 <div className="mt-4 flex items-center gap-4">
                    <div className="flex-1 h-3 bg-gray-100 dark:bg-white/5 rounded-full overflow-hidden border dark:border-white/5">
                       <div 
                        className="h-full bg-gradient-to-r from-blue-600 to-indigo-600 transition-all duration-1000 shadow-[0_0_10px_rgba(37,99,235,0.5)]" 
                        style={{ width: `${progressPercent}%` }}
                       />
                    </div>
                    <span className="text-xs font-black text-blue-600">{followerCount} / {CREATOR_UPGRADE_FOLLOWERS_GOAL}</span>
                 </div>
              </div>
              <div className="bg-blue-50 dark:bg-blue-900/10 p-4 rounded-2xl border border-blue-100 dark:border-blue-500/20 max-w-xs">
                 <p className="text-[9px] text-blue-800 dark:text-blue-300 font-medium leading-relaxed">
                    <strong>Poder de Leilão:</strong> Seu orçamento não apenas define o alcance, mas sua posição na "vaga de ouro" do feed social.
                 </p>
