import { 
  User, Post, UserType, Product, AffiliateSale, Transaction, 
  SystemLog, ContentReport, OrderStatus, AdCampaign, Store, GlobalSettings
} from '../types';
import { 
  DEFAULT_USERS, DEFAULT_POSTS, DEFAULT_STORES, DEFAULT_PRODUCTS 
} from '../constants';

const KEYS = {
  USERS: 'cyber_users',
  POSTS: 'cyber_posts',
  STORES: 'cyber_stores',
  PRODUCTS: 'cyber_products',
  SALES: 'cyber_sales',
  TRANSACTIONS: 'cyber_transactions',
  LOGS: 'cyber_system_logs',
  REPORTS: 'cyber_reports',
  CURRENT_USER: 'cyber_current_user_id',
  ADS: 'cyber_ads',
  GLOBAL_SETTINGS: 'cyber_global_settings'
};

const get = <T>(key: string, fallback: T): T => {
  const data = localStorage.getItem(key);
  if (!data) return fallback;
  try { return JSON.parse(data); } catch (e) { return fallback; }
};

const set = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));

// Admin Helpers
export const getUsers = (): User[] => get(KEYS.USERS, DEFAULT_USERS);
export const getPosts = (): Post[] => get(KEYS.POSTS, DEFAULT_POSTS);
export const getProducts = (): Product[] => get(KEYS.PRODUCTS, DEFAULT_PRODUCTS);
export const getAds = (): AdCampaign[] => get(KEYS.ADS, []);
export const getAllSales = (): AffiliateSale[] => get(KEYS.SALES, []);
export const getTransactions = (): Transaction[] => get(KEYS.TRANSACTIONS, []);
export const getSystemLogs = (): SystemLog[] => get(KEYS.LOGS, []);
export const getReports = (): ContentReport[] => get(KEYS.REPORTS, []);

export const addSystemLog = (log: Omit<SystemLog, 'id' | 'timestamp'>) => {
  const logs = getSystemLogs();
  const newLog = { ...log, id: `log-${Date.now()}`, timestamp: Date.now() };
  set(KEYS.LOGS, [newLog, ...logs]);
};

export const adminUpdateUser = (uId: string, updates: Partial<User>, adminId: string) => {
  const users = getUsers();
  const updated = users.map(u => u.id === uId ? { ...u, ...updates } : u);
  set(KEYS.USERS, updated);
  addSystemLog({ adminId, action: 'UPDATE_USER', targetId: uId, details: JSON.stringify(updates) });
};

export const adminDeletePost = (pId: string, adminId: string) => {
  const posts = getPosts().filter(p => p.id !== pId);
  set(KEYS.POSTS, posts);
  addSystemLog({ adminId, action: 'DELETE_POST', targetId: pId, details: 'Post removido por moderação.' });
};

export const adminProcessReport = (reportId: string, status: 'RESOLVED' | 'DISMISSED', adminId: string) => {
  const reports = getReports().map(r => r.id === reportId ? { ...r, status } : r);
  set(KEYS.REPORTS, reports);
  addSystemLog({ adminId, action: 'RESOLVE_REPORT', targetId: reportId, details: `Status: ${status}` });
};

export const updateUserBalance = (uId: string, amount: number, desc: string = 'Transação de Sistema'): boolean => {
  const users = getUsers();
  const idx = users.findIndex(u => u.id === uId);
  if (idx === -1) return false;

  users[idx].balance = (users[idx].balance || 0) + amount;
  set(KEYS.USERS, users);

  const transactions = getTransactions();
  transactions.push({
    id: `tx-${Date.now()}`,
    userId: uId,
    amount,
    type: amount > 0 ? 'DEPOSIT' : 'WITHDRAWAL' as any,
    description: desc,
    timestamp: Date.now(),
    status: 'COMPLETED'
  });
  set(KEYS.TRANSACTIONS, transactions);
  return true;
};

export const getPlatformRevenue = (): number => {
  const settings = getGlobalSettings();
  const sales = getAllSales();
  // Simulação: a plataforma fica com 10% (ou definido em settings) de cada venda
  return sales.reduce((acc, s) => acc + (s.saleAmount * (settings.platformTax || 0.1)), 0);
};

export const getGlobalSettings = (): GlobalSettings => get(KEYS.GLOBAL_SETTINGS, {
  platformTax: 0.1,
  upgradeCost: 29.90,
  minWithdrawal: 50,
  maintenanceMode: false
});

export const updateGlobalSettings = (s: GlobalSettings) => set(KEYS.GLOBAL_SETTINGS, s);
