                     <div className="w-full md:w-44 h-48 md:h-44 shrink-0 rounded-[1.8rem] md:rounded-[2rem] overflow-hidden shadow-lg">
                        <img src={res.imageUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                     </div>
                     <div className="flex-1 flex flex-col justify-center">
                        <h4 className="font-black text-base md:text-lg dark:text-white mb-2 uppercase line-clamp-1">{res.name}</h4>
                        <p className="text-[11px] md:text-xs text-gray-400 font-medium line-clamp-2 mb-6 italic leading-relaxed">"{res.description}"</p>
                        <div className="flex items-center justify-between border-t border-gray-50 dark:border-white/5 pt-5 mt-auto flex-wrap gap-4">
