  COMMENT = 'COMMENT',
  NEW_FOLLOWER = 'NEW_FOLLOWER',
  AFFILIATE_SALE = 'AFFILIATE_SALE',
  REACTION = 'REACTION',
}

export interface Notification {
  id: string;
  recipientId: string;
  actorId: string;
  type: NotificationType;
  timestamp: number;
  postId?: string;
  saleId?: string;
  isRead: boolean;
}

export interface AudioTrack {
  id: string;
  title: string;
  artist: string;
  url: string;
}

export interface Story {
  userId: string;
  userName: string;
  userProfilePic: string;
  items: StoryItem[];
}

export interface StoryItem {
  id: string;
  imageUrl?: string;
  text?: string;
  backgroundColor?: string;
  textColor?: string;
  fontFamily?: string;
  timestamp: number;
}

export interface PaymentCard {
  id: string;
  userId: string;
  cardNumber: string;
  expiryDate: string;
  cardHolderName: string;
}

import React from 'react';

interface LogoProps {
  className?: string;
  size?: 'sm' | 'md' | 'lg' | 'xl';
  showText?: boolean;
  variant?: 'default' | 'white' | 'dark';
}

const Logo: React.FC<LogoProps> = ({ 
  className = "", 
  size = 'md', 
  showText = true,
  variant = 'default'
}) => {
  const sizes = {
    sm: 'h-5',
    md: 'h-7',
    lg: 'h-10',
    xl: 'h-14 md:h-16'
  };

  const textSizes = {
    sm: 'text-base',
    md: 'text-xl',
    lg: 'text-2xl',
    xl: 'text-3xl md:text-4xl'
  };

  const getTextColor = () => {
    if (variant === 'white') return 'text-white';
    if (variant === 'dark') return 'text-gray-900';
    return 'text-gray-900 dark:text-white';
  };

  return (
    <div className={`flex items-center gap-3 ${className}`}>
      <div className={`${sizes[size]} aspect-square relative`}>
        <svg viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" className="w-full h-full drop-shadow-xl">
          <defs>
            <linearGradient id="cyber-grad" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#2563eb" />
              <stop offset="100%" stopColor="#7c3aed" />
            </linearGradient>
            <filter id="glow">
              <feGaussianBlur stdDeviation="2" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>

          {/* Símbolo "C" Estilizado (Circuito de Conexão) */}
          <path 
            d="M80 25C72.5 15.5 61.5 10 49.5 10C27.6853 10 10 27.6853 10 49.5C10 71.3147 27.6853 89 49.5 89C61.5 89 72.5 83.5 80 74" 
            stroke="url(#cyber-grad)" 
            strokeWidth="12" 
            strokeLinecap="round"
          />

          {/* Núcleo "B" e "P" (Abstrato) */}
          <rect x="40" y="35" width="12" height="30" rx="6" fill="url(#cyber-grad)" filter="url(#glow)" />
          <path d="M52 35C60 35 66 41 66 49C66 57 60 63 52 63H40V35H52Z" fill="url(#cyber-grad)" opacity="0.8" />
          <circle cx="55" cy="50" r="8" stroke="white" strokeWidth="3" opacity="0.5" />
        </svg>
      </div>

      {showText && (
        <h1 className={`${textSizes[size]} font-black tracking-tighter transition-colors`}>
          <span className="text-blue-600">CyBer</span>
          <span className={getTextColor()}>Phone</span>
        </h1>
      )}
    </div>
  );
};

export default Logo;

import React, { useState, useRef } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { DocumentArrowUpIcon, CheckCircleIcon, CalendarDaysIcon } from '@heroicons/react/24/outline';
import Logo from './Logo';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [documentId, setDocumentId] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');
  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');
  const [verificationFile, setVerificationFile] = useState<File | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const inputClasses = "w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl border-2 border-transparent focus:border-blue-500 focus:bg-white dark:focus:bg-darkcard outline-none font-bold text-sm transition-all shadow-inner placeholder-gray-400";

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        setError('O comprovante deve ser um arquivo PDF.');
        setVerificationFile(null);
        return;
      }
      setVerificationFile(file);
      setError('');
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !phone || !documentId || !birthDate || !password) {
      setError('Todos os campos fundamentais, incluindo nascimento, são obrigatórios.');
      return;
    }

    if (userType === UserType.CREATOR) {
      if (!credentials || !bio) {
        setError('Perfil Profissional exige cargo/área e biografia.');
        return;
      }
      if (!verificationFile) {
        setError('É obrigatório anexar um comprovante profissional (PDF).');
        return;
      }
    }

    setLoading(true);
    try {
      const newUser = await registerUser({
        userType,
        firstName,
        lastName,
        email,
        phone,
        documentId,
        birthDate: new Date(birthDate).getTime(),
        password,
        profilePicture: DEFAULT_PROFILE_PIC,
        credentials: userType === UserType.CREATOR ? credentials : undefined,
        bio: userType === UserType.CREATOR ? bio : undefined,
        verificationFileUrl: verificationFile ? verificationFile.name : undefined
      });
      saveCurrentUser(newUser.id);
      onLoginSuccess(newUser);
    } catch (err: any) {
      setError(err.message || 'Erro no registro.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!email || !password) {
      setError('Email e senha são obrigatórios.');
      return;
    }
    setLoading(true);
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError('Credenciais inválidas.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4 font-sans">
      <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10 relative overflow-hidden">
        <div className="mb-8 flex flex-col items-center">
          <Logo size="xl" className="mb-1" />
          <p className="text-center text-gray-400 font-bold uppercase text-[8px] tracking-[0.25em] opacity-80">
            {isRegister ? 'Conectando Talentos e Oportunidades' : 'Seja bem-vindo novamente'}
          </p>
        </div>

        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-500/30 text-red-600 dark:text-red-400 p-4 rounded-2xl text-[10px] font-black mb-6 text-center animate-pulse uppercase tracking-widest">
            {error}
          </div>
        )}

        <div className="mb-6">
          <h2 className="text-xl md:text-2xl font-black text-center text-gray-800 dark:text-white uppercase tracking-tighter">
            {isRegister ? 'Nova Inscrição' : 'Acesse seu Perfil'}
          </h2>
        </div>

        {isRegister && (
          <div className="flex bg-gray-50 dark:bg-white/5 p-1.5 rounded-2xl mb-8 border border-gray-100 dark:border-white/5">
            <button 
              type="button" 
              onClick={() => { setUserType(UserType.STANDARD); setVerificationFile(null); }} 
              className={`flex-1 py-3 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${userType === UserType.STANDARD ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400'}`}
            >
              NORMAL
            </button>
            <button 
              type="button" 
              onClick={() => setUserType(UserType.CREATOR)} 
              className={`flex-1 py-3 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${userType === UserType.CREATOR ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400'}`}
            >
              PROFISSIONAL
            </button>
          </div>
        )}

        <form onSubmit={isRegister ? handleRegister : handleLogin} className="space-y-4">
          {isRegister && (
            <>
              <div className="grid grid-cols-2 gap-3">
                <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClasses} />
                <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClasses} />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Data de Nascimento</label>
                <div className="relative">
                  <CalendarDaysIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
                  <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className={inputClasses + " pl-12"} />
                </div>
              </div>
            </>
          )}
          <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />
          {isRegister && (
            <div className="grid grid-cols-2 gap-3">
              <input type="tel" placeholder="Telefone" value={phone} onChange={e => setPhone(e.target.value)} className={inputClasses} />
              <input type="text" placeholder="ID / Documento" value={documentId} onChange={e => setDocumentId(e.target.value)} className={inputClasses} />
            </div>
          )}
          <input type="password" placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className={inputClasses} />

          {isRegister && userType === UserType.CREATOR && (
            <div className="space-y-4 animate-fade-in pt-2">
              <input type="text" placeholder="Cargo ou Área (Ex: Designer, Médico)" value={credentials} onChange={e => setCredentials(e.target.value)} className={inputClasses} />
              <textarea placeholder="Resumo profissional..." value={bio} onChange={e => setBio(e.target.value)} className={inputClasses + " h-24 resize-none font-medium"} />

              <div className="pt-2">
                 <label className="block text-[8px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Comprovante Profissional (PDF)</label>
                 <div 
                   onClick={() => fileInputRef.current?.click()}
                   className={`w-full p-6 border-2 border-dashed rounded-[1.8rem] flex flex-col items-center justify-center gap-2 cursor-pointer transition-all ${verificationFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10' : 'border-gray-200 dark:border-white/10 hover:border-blue-500'}`}
                 >
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      onChange={handleFileChange} 
                      accept=".pdf" 
                      className="hidden" 
                    />
                    {verificationFile ? (
                      <>
                        <CheckCircleIcon className="h-8 w-8 text-green-500" />
                        <span className="text-[10px] font-black text-green-600 uppercase truncate max-w-full px-4">{verificationFile.name}</span>
                      </>
                    ) : (
                      <>
                        <DocumentArrowUpIcon className="h-8 w-8 text-gray-300" />
                        <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">Clique para enviar comprovante</span>
                      </>
                    )}
                 </div>
              </div>
            </div>
          )}

          <button type="submit" disabled={loading} className="w-full py-5 rounded-[1.8rem] font-black text-sm uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50 mt-4 bg-green-600 text-white">
            {loading ? <div className="w-5 h-5 border-3 border-current border-t-transparent rounded-full animate-spin" /> : isRegister ? 'CRIAR MINHA CONTA' : 'ENTRAR'}
          </button>
        </form>

        <button onClick={() => { setIsRegister(!isRegister); setError(''); }} className="w-full mt-10 text-[9px] font-black uppercase tracking-[0.3em] text-gray-400 hover:text-blue-600 transition-colors">
          {isRegister ? 'Já tem conta? Login' : 'Novo por aqui? Criar conta'}
        </button>
      </div>
    </div>
  );
};

export default AuthPage;

import React, { useState, useRef } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { DocumentArrowUpIcon, CheckCircleIcon, CalendarDaysIcon, CameraIcon, UserIcon } from '@heroicons/react/24/outline';
import Logo from './Logo';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [documentId, setDocumentId] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');
  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');
  const [profilePicBase64, setProfilePicBase64] = useState<string>(DEFAULT_PROFILE_PIC);
  const [verificationFile, setVerificationFile] = useState<File | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const profilePicInputRef = useRef<HTMLInputElement>(null);

  const inputClasses = "w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl border-2 border-transparent focus:border-blue-500 focus:bg-white dark:focus:bg-darkcard outline-none font-bold text-sm transition-all shadow-inner placeholder-gray-400";

  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Por favor, selecione um arquivo de imagem válido.');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfilePicBase64(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        setError('O comprovante deve ser um arquivo PDF.');
        setVerificationFile(null);
        return;
      }
      setVerificationFile(file);
      setError('');
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !phone || !documentId || !birthDate || !password) {
      setError('Campos fundamentais e data de nascimento são obrigatórios.');
      return;
    }

    if (userType === UserType.CREATOR) {
      if (!credentials) {
        setError('Perfil Profissional exige cargo ou área de atuação.');
        return;
      }
      if (!verificationFile) {
        setError('É obrigatório anexar um comprovante profissional (PDF).');
        return;
      }
    }

    setLoading(true);
    try {
      const newUser = await registerUser({
        userType,
        firstName,
        lastName,
        email,
        phone,
        documentId,
        birthDate: new Date(birthDate).getTime(),
        password,
        profilePicture: profilePicBase64,
        credentials: userType === UserType.CREATOR ? credentials : undefined,
        bio: bio || undefined,
        verificationFileUrl: verificationFile ? verificationFile.name : undefined
      });
      saveCurrentUser(newUser.id);
      onLoginSuccess(newUser);
    } catch (err: any) {
      setError(err.message || 'Erro no registro.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!email || !password) {
      setError('Email e senha são obrigatórios.');
      return;
    }
    setLoading(true);
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError('Credenciais inválidas.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4 font-sans">
      <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10 relative overflow-hidden">
        <div className="mb-6 flex flex-col items-center">
          <Logo size="xl" className="mb-1" />
          <p className="text-center text-gray-400 font-bold uppercase text-[8px] tracking-[0.25em] opacity-80">
            {isRegister ? 'Conectando Talentos e Oportunidades' : 'Seja bem-vindo novamente'}
          </p>
        </div>

        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-500/30 text-red-600 dark:text-red-400 p-4 rounded-2xl text-[10px] font-black mb-6 text-center animate-pulse uppercase tracking-widest">
            {error}
          </div>
        )}

        <div className="mb-6">
          <h2 className="text-xl md:text-2xl font-black text-center text-gray-800 dark:text-white uppercase tracking-tighter">
            {isRegister ? 'Nova Inscrição' : 'Acesse seu Perfil'}
          </h2>
        </div>

        {isRegister && (
          <div className="flex bg-gray-50 dark:bg-white/5 p-1.5 rounded-2xl mb-6 border border-gray-100 dark:border-white/5">
            <button 
              type="button" 
              onClick={() => { setUserType(UserType.STANDARD); setVerificationFile(null); }} 
              className={`flex-1 py-3 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${userType === UserType.STANDARD ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400'}`}
            >
              NORMAL
            </button>
            <button 
              type="button" 
              onClick={() => setUserType(UserType.CREATOR)} 
              className={`flex-1 py-3 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${userType === UserType.CREATOR ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400'}`}
            >
              PROFISSIONAL
            </button>
          </div>
        )}

        <form onSubmit={isRegister ? handleRegister : handleLogin} className="space-y-4">
          {isRegister && (
            <div className="flex flex-col items-center mb-6">
              <div 
                onClick={() => profilePicInputRef.current?.click()}
                className="relative group cursor-pointer"
              >
                <div className="w-24 h-24 rounded-[2rem] overflow-hidden border-4 border-gray-50 dark:border-white/10 shadow-xl transition-all group-hover:scale-105 group-hover:border-blue-500">
                  <img src={profilePicBase64} className="w-full h-full object-cover" alt="Preview" />
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <CameraIcon className="h-8 w-8 text-white" />
                  </div>
                </div>
                <div className="absolute -bottom-2 -right-2 bg-blue-600 text-white p-2 rounded-xl shadow-lg border-2 border-white dark:border-darkcard">
                  <PlusIcon className="h-3 w-3 stroke-[4]" />
                </div>
                <input 
                  type="file" 
                  ref={profilePicInputRef} 
                  onChange={handleProfilePicChange} 
                  accept="image/*" 
                  className="hidden" 
                />
              </div>
              <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mt-4">Foto de Perfil</p>
            </div>
          )}

          {isRegister && (
            <>
              <div className="grid grid-cols-2 gap-3">
                <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClasses} />
                <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClasses} />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Data de Nascimento</label>
                <div className="relative">
                  <CalendarDaysIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
                  <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className={inputClasses + " pl-12"} />
                </div>
              </div>
            </>
          )}

          <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="grid grid-cols-2 gap-3">
              <input type="tel" placeholder="Telefone" value={phone} onChange={e => setPhone(e.target.value)} className={inputClasses} />
              <input type="text" placeholder="ID / Documento" value={documentId} onChange={e => setDocumentId(e.target.value)} className={inputClasses} />
            </div>
          )}

          <input type="password" placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="space-y-4 animate-fade-in pt-2">
              {userType === UserType.CREATOR && (
                <input type="text" placeholder="Cargo ou Área (Ex: Designer, Médico)" value={credentials} onChange={e => setCredentials(e.target.value)} className={inputClasses} />
              )}

              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Biografia / Descrição</label>
                <textarea 
                  placeholder={userType === UserType.CREATOR ? "Conte sobre sua carreira e o que você ensina..." : "Fale um pouco sobre você e seus interesses..."} 
                  value={bio} 
                  onChange={e => setBio(e.target.value)} 
                  className={inputClasses + " h-24 resize-none font-medium"} 
                />
              </div>

              {userType === UserType.CREATOR && (
                <div className="pt-2">
                   <label className="block text-[8px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Comprovante Profissional (PDF)</label>
                   <div 
                     onClick={() => fileInputRef.current?.click()}
                     className={`w-full p-6 border-2 border-dashed rounded-[1.8rem] flex flex-col items-center justify-center gap-2 cursor-pointer transition-all ${verificationFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10' : 'border-gray-200 dark:border-white/10 hover:border-blue-500'}`}
                   >
                      <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileChange} 
                        accept=".pdf" 
                        className="hidden" 
                      />
                      {verificationFile ? (
                        <>
                          <CheckCircleIcon className="h-8 w-8 text-green-500" />
                          <span className="text-[10px] font-black text-green-600 uppercase truncate max-w-full px-4">{verificationFile.name}</span>
                        </>
                      ) : (
                        <>
                          <DocumentArrowUpIcon className="h-8 w-8 text-gray-300" />
                          <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">Clique para enviar comprovante</span>
                        </>
                      )}
                   </div>
                </div>
              )}
            </div>
          )}

          <button type="submit" disabled={loading} className="w-full py-5 rounded-[1.8rem] font-black text-sm uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50 mt-4 bg-green-600 text-white">
            {loading ? <div className="w-5 h-5 border-3 border-current border-t-transparent rounded-full animate-spin" /> : isRegister ? 'CRIAR MINHA CONTA' : 'ENTRAR'}
          </button>
        </form>

        <button onClick={() => { setIsRegister(!isRegister); setError(''); }} className="w-full mt-10 text-[9px] font-black uppercase tracking-[0.3em] text-gray-400 hover:text-blue-600 transition-colors">
          {isRegister ? 'Já tem conta? Login' : 'Novo por aqui? Criar conta'}
        </button>
      </div>
    </div>
  );
};

export default AuthPage;

import React, { useState, useRef } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
// Fix: Added missing PlusIcon to the imports from @heroicons/react/24/outline
import { DocumentArrowUpIcon, CheckCircleIcon, CalendarDaysIcon, CameraIcon, UserIcon, PlusIcon } from '@heroicons/react/24/outline';
import Logo from './Logo';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [documentId, setDocumentId] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');
  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');
  const [profilePicBase64, setProfilePicBase64] = useState<string>(DEFAULT_PROFILE_PIC);
  const [verificationFile, setVerificationFile] = useState<File | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const profilePicInputRef = useRef<HTMLInputElement>(null);

  const inputClasses = "w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl border-2 border-transparent focus:border-blue-500 focus:bg-white dark:focus:bg-darkcard outline-none font-bold text-sm transition-all shadow-inner placeholder-gray-400";

  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Por favor, selecione um arquivo de imagem válido.');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfilePicBase64(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        setError('O comprovante deve ser um arquivo PDF.');
        setVerificationFile(null);
        return;
      }
      setVerificationFile(file);
      setError('');
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !phone || !documentId || !birthDate || !password) {
      setError('Campos fundamentais e data de nascimento são obrigatórios.');
      return;
    }

    if (userType === UserType.CREATOR) {
      if (!credentials) {
        setError('Perfil Profissional exige cargo ou área de atuação.');
        return;
      }
      if (!verificationFile) {
        setError('É obrigatório anexar um comprovante profissional (PDF).');
        return;
      }
    }

    setLoading(true);
    try {
      const newUser = await registerUser({
        userType,
        firstName,
        lastName,
        email,
        phone,
        documentId,
        birthDate: new Date(birthDate).getTime(),
        password,
        profilePicture: profilePicBase64,
        credentials: userType === UserType.CREATOR ? credentials : undefined,
        bio: bio || undefined,
        verificationFileUrl: verificationFile ? verificationFile.name : undefined
      });
      saveCurrentUser(newUser.id);
      onLoginSuccess(newUser);
    } catch (err: any) {
      setError(err.message || 'Erro no registro.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!email || !password) {
      setError('Email e senha são obrigatórios.');
      return;
    }
    setLoading(true);
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError('Credenciais inválidas.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4 font-sans">
      <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10 relative overflow-hidden">
        <div className="mb-6 flex flex-col items-center">
          <Logo size="xl" className="mb-1" />
          <p className="text-center text-gray-400 font-bold uppercase text-[8px] tracking-[0.25em] opacity-80">
            {isRegister ? 'Conectando Talentos e Oportunidades' : 'Seja bem-vindo novamente'}
          </p>
        </div>

        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-500/30 text-red-600 dark:text-red-400 p-4 rounded-2xl text-[10px] font-black mb-6 text-center animate-pulse uppercase tracking-widest">
            {error}
          </div>
        )}

        <div className="mb-6">
          <h2 className="text-xl md:text-2xl font-black text-center text-gray-800 dark:text-white uppercase tracking-tighter">
            {isRegister ? 'Nova Inscrição' : 'Acesse seu Perfil'}
          </h2>
        </div>

        {isRegister && (
          <div className="flex bg-gray-50 dark:bg-white/5 p-1.5 rounded-2xl mb-6 border border-gray-100 dark:border-white/5">
            <button 
              type="button" 
              onClick={() => { setUserType(UserType.STANDARD); setVerificationFile(null); }} 
              className={`flex-1 py-3 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${userType === UserType.STANDARD ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400'}`}
            >
              NORMAL
            </button>
            <button 
              type="button" 
              onClick={() => setUserType(UserType.CREATOR)} 
              className={`flex-1 py-3 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${userType === UserType.CREATOR ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400'}`}
            >
              PROFISSIONAL
            </button>
          </div>
        )}

        <form onSubmit={isRegister ? handleRegister : handleLogin} className="space-y-4">
          {isRegister && (
            <div className="flex flex-col items-center mb-6">
              <div 
                onClick={() => profilePicInputRef.current?.click()}
                className="relative group cursor-pointer"
              >
                <div className="w-24 h-24 rounded-[2rem] overflow-hidden border-4 border-gray-50 dark:border-white/10 shadow-xl transition-all group-hover:scale-105 group-hover:border-blue-500">
                  <img src={profilePicBase64} className="w-full h-full object-cover" alt="Preview" />
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <CameraIcon className="h-8 w-8 text-white" />
                  </div>
                </div>
                {/* Fix: Added PlusIcon to imports above to fix line 183 */}
                <div className="absolute -bottom-2 -right-2 bg-blue-600 text-white p-2 rounded-xl shadow-lg border-2 border-white dark:border-darkcard">
                  <PlusIcon className="h-3 w-3 stroke-[4]" />
                </div>
                <input 
                  type="file" 
                  ref={profilePicInputRef} 
                  onChange={handleProfilePicChange} 
                  accept="image/*" 
                  className="hidden" 
                />
              </div>
              <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mt-4">Foto de Perfil</p>
            </div>
          )}

          {isRegister && (
            <>
              <div className="grid grid-cols-2 gap-3">
                <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClasses} />
                <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClasses} />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Data de Nascimento</label>
                <div className="relative">
                  <CalendarDaysIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" />
                  <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className={inputClasses + " pl-12"} />
                </div>
              </div>
            </>
          )}

          <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="grid grid-cols-2 gap-3">
              <input type="tel" placeholder="Telefone" value={phone} onChange={e => setPhone(e.target.value)} className={inputClasses} />
              <input type="text" placeholder="ID / Documento" value={documentId} onChange={e => setDocumentId(e.target.value)} className={inputClasses} />
            </div>
          )}

          <input type="password" placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="space-y-4 animate-fade-in pt-2">
              {userType === UserType.CREATOR && (
                <input type="text" placeholder="Cargo ou Área (Ex: Designer, Médico)" value={credentials} onChange={e => setCredentials(e.target.value)} className={inputClasses} />
              )}

              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Biografia / Descrição</label>
                <textarea 
                  placeholder={userType === UserType.CREATOR ? "Conte sobre sua carreira e o que você ensina..." : "Fale um pouco sobre você e seus interesses..."} 
                  value={bio} 
                  onChange={e => setBio(e.target.value)} 
                  className={inputClasses + " h-24 resize-none font-medium"} 
                />
              </div>

              {userType === UserType.CREATOR && (
                <div className="pt-2">
                   <label className="block text-[8px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Comprovante Profissional (PDF)</label>
                   <div 
                     onClick={() => fileInputRef.current?.click()}
                     className={`w-full p-6 border-2 border-dashed rounded-[1.8rem] flex flex-col items-center justify-center gap-2 cursor-pointer transition-all ${verificationFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10' : 'border-gray-200 dark:border-white/10 hover:border-blue-500'}`}
                   >
                      <input 
                        type="file" 
                        ref={fileInputRef} 
                        onChange={handleFileChange} 
                        accept=".pdf" 
                        className="hidden" 
                      />
                      {verificationFile ? (
                        <>
                          <CheckCircleIcon className="h-8 w-8 text-green-500" />
                          <span className="text-[10px] font-black text-green-600 uppercase truncate max-w-full px-4">{verificationFile.name}</span>
                        </>
                      ) : (
                        <>
                          <DocumentArrowUpIcon className="h-8 w-8 text-gray-300" />
                          <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">Clique para enviar comprovante</span>
                        </>
                      )}
                   </div>
                </div>
              )}
            </div>
          )}

          <button type="submit" disabled={loading} className="w-full py-5 rounded-[1.8rem] font-black text-sm uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50 mt-4 bg-green-600 text-white">
            {loading ? <div className="w-5 h-5 border-3 border-current border-t-transparent rounded-full animate-spin" /> : isRegister ? 'CRIAR MINHA CONTA' : 'ENTRAR'}
          </button>
        </form>

        <button onClick={() => { setIsRegister(!isRegister); setError(''); }} className="w-full mt-10 text-[9px] font-black uppercase tracking-[0.3em] text-gray-400 hover:text-blue-600 transition-colors">
          {isRegister ? 'Já tem conta? Login' : 'Novo por aqui? Criar conta'}
        </button>
      </div>
    </div>
  );
};

export default AuthPage;

