// Função para comprimir imagens Base64 antes de salvar
const compressImage = (base64Str: string, maxWidth = 200, maxHeight = 200): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = base64Str;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      if (width > height) {
        if (width > maxWidth) {
          height *= maxWidth / width;
          width = maxWidth;
        }
      } else {
        if (height > maxHeight) {
          width *= maxHeight / height;
          height = maxHeight;
        }
      }
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(img, 0, 0, width, height);
      resolve(canvas.toDataURL('image/jpeg', 0.7)); // Salva como JPEG comprimido
    };
    img.onerror = () => resolve(base64Str);
  });
};

const get = <T>(key: string, fallback: T): T => {
  const data = localStorage.getItem(key);
  if (!data) return fallback;
  try { return JSON.parse(data); } catch (e) { return fallback; }
};

const set = (key: string, data: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(data));
  } catch (e) {
    if (e instanceof DOMException && e.name === 'QuotaExceededError') {
      console.error('LocalStorage lotado! Limpando dados antigos...');
      // Estratégia de limpeza: remove logs e stories antigos para tentar abrir espaço
      localStorage.removeItem(KEYS.LOGS);
      localStorage.removeItem(KEYS.STORIES);
      try {
        localStorage.setItem(key, JSON.stringify(data));
      } catch (retryError) {
        alert('O armazenamento do seu navegador está cheio. Por favor, limpe os dados do site nas configurações do navegador.');
      }
    }
  }
};

