  addSystemLog({ adminId, action: 'DELETE_POST', targetId: pId, details: 'Post removido por moderação.' });
};

export const adminProcessReport = (reportId: string, status: 'RESOLVED' | 'DISMISSED', adminId: string) => {
  const reports = getReports().map(r => r.id === reportId ? { ...r, status } : r);
  set(KEYS.REPORTS, reports);
  addSystemLog({ adminId, action: 'RESOLVE_REPORT', targetId: reportId, details: `Status: ${status}` });
};

export const updateUserBalance = (uId: string, amount: number, desc: string = 'Transação de Sistema'): boolean => {
  const users = getUsers();
  const idx = users.findIndex(u => u.id === uId);
  if (idx === -1) return false;

  users[idx].balance = (users[idx].balance || 0) + amount;
  saveUsers(users);

  const transactions = getTransactions();
  transactions.push({
    id: `tx-${Date.now()}`,
    userId: uId,
    amount,
    type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
    description: desc,
    timestamp: Date.now(),
    status: 'COMPLETED'
  });
  set(KEYS.TRANSACTIONS, transactions);
  return true;
};

export const getPosts = (): Post[] => get(KEYS.POSTS, DEFAULT_POSTS);
export const savePosts = (posts: Post[]) => set(KEYS.POSTS, posts);
export const addPost = (post: Post) => savePosts([post, ...getPosts()]);
export const updatePost = (updatedPost: Post) => {
  const posts = getPosts().map(p => p.id === updatedPost.id ? updatedPost : p);
  savePosts(posts);
};
export const deletePost = (pId: string) => savePosts(getPosts().filter(p => p.id !== pId));

export const pinPost = (postId: string, userId: string) => {
  const posts = getPosts();
  posts.forEach(p => { if(p.userId === userId) p.isPinned = (p.id === postId); });
  savePosts(posts);
  return true;
};
export const unpinPost = (postId: string, userId: string) => {
  const posts = getPosts();
  const p = posts.find(p => p.id === postId && p.userId === userId);
  if (p) p.isPinned = false;
  savePosts(posts);
  return true;
};

export const updatePostLikes = (pId: string, uId: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) {
    if (post.likes.includes(uId)) post.likes = post.likes.filter(id => id !== uId);
    else {
      post.likes.push(uId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: uId, postId: pId, timestamp: Date.now() });
    }
    updatePost(post);
  }
};

export const updatePostSaves = (pId: string, uId: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) {
    if (post.saves.includes(uId)) post.saves = post.saves.filter(id => id !== uId);
    else post.saves.push(uId);
    updatePost(post);
  }
};

export const updatePostShares = (pId: string, uId: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post && !post.shares.includes(uId)) {
    post.shares.push(uId);
    updatePost(post);
  }
};

export const addPostComment = (pId: string, comment: Comment) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) {
    post.comments.push(comment);
    createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: pId, timestamp: Date.now() });
    updatePost(post);
  }
};

export const boostPost = (postId: string, userId: string, budget: number, days: number) => {
  const post = getPosts().find(p => p.id === postId);
  if (post && updateUserBalance(userId, -budget, `Impulsionamento de Post`)) {
    post.isBoosted = true;
    post.boostExpires = Date.now() + (days * 24 * 60 * 60 * 1000);
    updatePost(post);
    return true;
  }
  return false;
};

export const indicatePostToUser = (postId: string, fromId: string, toId: string) => {
  const post = getPosts().find(p => p.id === postId);
  if (post) {
    if (!post.indicatedUserIds) post.indicatedUserIds = [];
    if (post.indicatedUserIds.includes(toId)) return false;
    post.indicatedUserIds.push(toId);
    updatePost(post);
    return true;
  }
  return false;
};

export const getStores = (): Store[] => get(KEYS.STORES, DEFAULT_STORES);
export const saveStores = (stores: Store[]) => set(KEYS.STORES, stores);
export const findStoreById = (id: string) => getStores().find(s => s.id === id);
export const updateStore = (updatedStore: Store) => {
  const stores = getStores().map(s => s.id === updatedStore.id ? updatedStore : s);
  saveStores(stores);
};

export const getProducts = (): Product[] => get(KEYS.PRODUCTS, DEFAULT_PRODUCTS);
export const saveProducts = (products: Product[]) => set(KEYS.PRODUCTS, products);
export const findProductById = (id: string) => getProducts().find(p => p.id === id);

export const getAllSales = (): AffiliateSale[] => get(KEYS.SALES, DEFAULT_AFFILIATE_SALES);
export const saveAffiliateSales = (sales: AffiliateSale[]) => set(KEYS.SALES, sales);
export const getPurchasesByBuyerId = (uId: string) => getAllSales().filter(s => s.buyerId === uId);
export const getSalesByAffiliateId = (uId: string) => getAllSales().filter(s => s.affiliateUserId === uId);
export const getSalesByStoreId = (sId: string) => getAllSales().filter(s => s.storeId === sId);

export const updateSaleStatus = (saleId: string, status: OrderStatus) => {
  const sales = getAllSales().map(s => s.id === saleId ? { ...s, status } : s);
  saveAffiliateSales(sales);
};

export const addProductRating = (saleId: string, rating: number, comment: string) => {
  const sales = getAllSales();
  const sale = sales.find(s => s.id === saleId);
  if (sale && !sale.isRated) {
    sale.isRated = true;
    saveAffiliateSales(sales);
    const product = findProductById(sale.productId);
    if (product) {
      product.ratings.push({ id: `rate-${Date.now()}`, saleId, userId: sale.buyerId, rating, comment, timestamp: Date.now() });
      product.ratingCount = product.ratings.length;
      product.averageRating = product.ratings.reduce((a, b) => a + b.rating, 0) / product.ratingCount;
      saveProducts(getProducts().map(p => p.id === product.id ? product : p));
    }
  }
};

export const processProductPurchase = (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: any) => {
  const sales = getAllSales();
  cartItems.forEach(item => {
    const prod = findProductById(item.productId);
    if (prod) {
      const sale: AffiliateSale = {
        id: `sale-${Date.now()}-${item.productId}`,
        productId: item.productId,
        buyerId,
        affiliateUserId: affiliateUserId || '',
        storeId: prod.storeId,
        commissionEarned: prod.price * item.quantity * prod.affiliateCommissionRate,
        saleAmount: prod.price * item.quantity,
        timestamp: Date.now(),
        status: OrderStatus.WAITLIST,
        shippingAddress,
        digitalContentUrl: prod.digitalContentUrl
      };
      sales.push(sale);
      if (affiliateUserId) {
        updateUserBalance(affiliateUserId, sale.commissionEarned, `Comissão de Venda #${sale.id}`);
        createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliateUserId, actorId: buyerId, timestamp: Date.now(), saleId: sale.id });
      }
      const store = findStoreById(prod.storeId);
      if (store) updateUserBalance(store.professorId, sale.saleAmount - sale.commissionEarned, `Venda de Produto #${sale.id}`);
    }
  });
  saveAffiliateSales(sales);
  clearCart();
  return true;
};

export const getCart = (): CartItem[] => get(KEYS.CART, []);
export const saveCart = (cart: CartItem[]) => set(KEYS.CART, cart);
export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
  if (existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};
export const removeFromCart = (pId: string) => saveCart(getCart().filter(i => i.productId !== pId));
export const updateCartItemQuantity = (pId: string, q: number) => {
  const cart = getCart().map(i => i.productId === pId ? { ...i, quantity: q } : i).filter(i => i.quantity > 0);
  saveCart(cart);
};
export const clearCart = () => saveCart([]);

export const getChats = (): ChatConversation[] => get(KEYS.CHATS, []);
export const saveChats = (chats: ChatConversation[]) => set(KEYS.CHATS, chats);
export const getOrCreateConversation = (u1: string, u2: string): ChatConversation => {
  const chats = getChats();
  let chat = chats.find(c => c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, participants: [u1, u2], messages: [] };
    saveChats([...chats, chat]);
  }
  return chat;
};
export const sendMessage = (chatId: string, msg: Message) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === chatId);
  if (chat) {
    chat.messages.push(msg);
    saveChats(chats);
  }
};

export const getNotifications = (): Notification[] => get(KEYS.NOTIFICATIONS, []);
export const saveNotifications = (nots: Notification[]) => set(KEYS.NOTIFICATIONS, nots);
export const createNotification = (n: any) => {
  if (n.actorId === n.recipientId) return;
  saveNotifications([{ ...n, id: `notif-${Date.now()}`, isRead: false }, ...getNotifications()]);
};
export const getNotificationsForUser = (uId: string) => getNotifications().filter(n => n.recipientId === uId);
export const markNotificationsAsRead = (uId: string) => {
  const nots = getNotifications().map(n => n.recipientId === uId ? { ...n, isRead: true } : n);
  saveNotifications(nots);
};

export const getTransactions = (): Transaction[] => get(KEYS.TRANSACTIONS, []);
export const getSystemLogs = (): SystemLog[] => get(KEYS.LOGS, []);
export const addSystemLog = (log: any) => set(KEYS.LOGS, [{ ...log, id: `log-${Date.now()}`, timestamp: Date.now() }, ...getSystemLogs()]);
export const getReports = (): ContentReport[] => get(KEYS.REPORTS, []);
export const getGlobalSettings = (): GlobalSettings => get(KEYS.GLOBAL_SETTINGS, { platformTax: 0.1, upgradeCost: 29.9, minWithdrawal: 50, maintenanceMode: false });
export const updateGlobalSettings = (s: GlobalSettings) => set(KEYS.GLOBAL_SETTINGS, s);
export const getPlatformRevenue = () => getAllSales().reduce((acc, s) => acc + (s.saleAmount * 0.1), 0);
export const getStories = (): Story[] => get(KEYS.STORIES, []);
export const addStory = (uId: string, item: any) => {
  const stories = getStories();
  const user = findUserById(uId);
  if (!user) return;
  let userStory = stories.find(s => s.userId === uId);
  if (!userStory) {
    userStory = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
    stories.push(userStory);
  }
  userStory.items.push({ ...item, id: `item-${Date.now()}`, timestamp: Date.now() });
  set(KEYS.STORIES, stories);
};

export const getEvents = (): CyberEvent[] => get('cyber_events', []);
export const createEvent = (evt: CyberEvent) => set('cyber_events', [evt, ...getEvents()]);
export const toggleJoinEvent = (eId: string, uId: string) => {
  const evts = getEvents();
  const evt = evts.find(e => e.id === eId);
  if (evt) {
    if (evt.attendees.includes(uId)) evt.attendees = evt.attendees.filter(id => id !== uId);
    else evt.attendees.push(uId);
    set('cyber_events', evts);
  }
};

export const getAudioTracks = (): AudioTrack[] => get(KEYS.AUDIO_TRACKS, DEFAULT_AUDIO_TRACKS);
export const findAudioTrackById = (id: string) => getAudioTracks().find(t => t.id === id);

export const getAds = (): AdCampaign[] => get(KEYS.ADS, []);
export const saveAds = (ads: AdCampaign[]) => set(KEYS.ADS, ads);

import React, { useState, useRef } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { DocumentArrowUpIcon, CheckCircleIcon, CalendarDaysIcon, CameraIcon, PlusIcon } from '@heroicons/react/24/outline';
import Logo from './Logo';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [documentId, setDocumentId] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');
  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');
  const [profilePicBase64, setProfilePicBase64] = useState<string>(DEFAULT_PROFILE_PIC);
  const [verificationFile, setVerificationFile] = useState<File | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const profilePicInputRef = useRef<HTMLInputElement>(null);

  const inputClasses = "w-full p-3.5 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl border-2 border-transparent focus:border-blue-500 focus:bg-white dark:focus:bg-darkcard outline-none font-bold text-sm transition-all shadow-inner placeholder-gray-400";

  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Por favor, selecione uma imagem válida.');
        return;
      }
      // Limita o tamanho do arquivo no cliente antes de processar
      if (file.size > 2 * 1024 * 1024) {
        setError('A imagem é muito grande. Escolha uma foto menor que 2MB.');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setProfilePicBase64(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        setError('O comprovante deve ser um arquivo PDF.');
        setVerificationFile(null);
        return;
      }
      setVerificationFile(file);
      setError('');
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !phone || !documentId || !birthDate || !password) {
      setError('Todos os campos obrigatórios devem ser preenchidos.');
      return;
    }

    if (userType === UserType.CREATOR && (!credentials || !verificationFile)) {
      setError('Profissionais precisam de cargo e comprovante.');
      return;
    }

    setLoading(true);
    try {
      const newUser = await registerUser({
        userType,
        firstName,
        lastName,
        email,
        phone,
        documentId,
        birthDate: new Date(birthDate).getTime(),
        password,
        profilePicture: profilePicBase64,
        credentials: userType === UserType.CREATOR ? credentials : undefined,
        bio: bio || undefined,
        verificationFileUrl: verificationFile ? verificationFile.name : undefined
      });
      saveCurrentUser(newUser.id);
      onLoginSuccess(newUser);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Erro ao realizar cadastro. Tente uma foto de perfil menor.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!email || !password) {
      setError('Email e senha são obrigatórios.');
      return;
    }
    setLoading(true);
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError('Credenciais inválidas.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4 font-sans">
      <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10 relative overflow-hidden">

        <div className="mb-6 flex flex-col items-center">
          <Logo size="lg" className="mb-1" />
          <p className="text-center text-gray-400 font-bold uppercase text-[8px] tracking-[0.25em] opacity-80">
            {isRegister ? 'Conectando Talentos' : 'Bem-vindo ao CyBerPhone'}
          </p>
        </div>

        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 text-red-600 p-4 rounded-2xl text-[10px] font-black mb-6 text-center animate-pulse uppercase tracking-widest leading-tight">
            {error}
          </div>
        )}

        {isRegister && (
          <div className="flex bg-gray-50 dark:bg-white/5 p-1 rounded-2xl mb-6">
            <button type="button" onClick={() => setUserType(UserType.STANDARD)} className={`flex-1 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${userType === UserType.STANDARD ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400'}`}>Normal</button>
            <button type="button" onClick={() => setUserType(UserType.CREATOR)} className={`flex-1 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${userType === UserType.CREATOR ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400'}`}>Profissional</button>
          </div>
        )}

        <form onSubmit={isRegister ? handleRegister : handleLogin} className="space-y-4">
          {isRegister && (
            <div className="flex flex-col items-center mb-4">
              <div onClick={() => profilePicInputRef.current?.click()} className="relative group cursor-pointer">
                <div className="w-20 h-20 rounded-[1.8rem] overflow-hidden border-4 border-gray-50 dark:border-white/10 shadow-xl transition-all group-hover:scale-105 group-hover:border-blue-500">
                  <img src={profilePicBase64} className="w-full h-full object-cover" alt="Preview" />
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <CameraIcon className="h-6 w-6 text-white" />
                  </div>
                </div>
                <div className="absolute -bottom-1 -right-1 bg-blue-600 text-white p-1.5 rounded-lg shadow-lg border-2 border-white dark:border-darkcard">
                  <PlusIcon className="h-2.5 w-2.5 stroke-[4]" />
                </div>
                <input type="file" ref={profilePicInputRef} onChange={handleProfilePicChange} accept="image/*" className="hidden" />
              </div>
              <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mt-2">Foto de Perfil</p>
            </div>
          )}

          {isRegister && (
            <>
              <div className="grid grid-cols-2 gap-2.5">
                <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClasses} />
                <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClasses} />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Nascimento</label>
                <div className="relative">
                  <CalendarDaysIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className={inputClasses + " pl-10"} />
                </div>
              </div>
            </>
          )}

          <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="grid grid-cols-2 gap-2.5">
              <input type="tel" placeholder="Telefone" value={phone} onChange={e => setPhone(e.target.value)} className={inputClasses} />
              <input type="text" placeholder="Documento ID" value={documentId} onChange={e => setDocumentId(e.target.value)} className={inputClasses} />
            </div>
          )}

          <input type="password" placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="space-y-4 animate-fade-in pt-1">
              {userType === UserType.CREATOR && (
                <input type="text" placeholder="Cargo ou Especialidade" value={credentials} onChange={e => setCredentials(e.target.value)} className={inputClasses} />
              )}

              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Sobre você (Bio)</label>
                <textarea 
                  placeholder="Fale um pouco sobre seus interesses ou carreira..." 
                  value={bio} 
                  onChange={e => setBio(e.target.value)} 
                  className={inputClasses + " h-20 resize-none font-medium text-xs"} 
                />
              </div>

              {userType === UserType.CREATOR && (
                <div className="pt-1">
                   <label className="block text-[8px] font-black text-gray-400 uppercase tracking-widest mb-1.5 ml-1">Diploma/Comprovante (PDF)</label>
                   <div 
                     onClick={() => fileInputRef.current?.click()}
                     className={`w-full p-4 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center gap-2 cursor-pointer transition-all ${verificationFile ? 'border-green-500 bg-green-50' : 'border-gray-200 dark:border-white/10'}`}
                   >
                      <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".pdf" className="hidden" />
                      {verificationFile ? <CheckCircleIcon className="h-6 w-6 text-green-500" /> : <DocumentArrowUpIcon className="h-6 w-6 text-gray-300" />}
                      <span className="text-[8px] font-black text-gray-400 uppercase truncate max-w-full px-2">{verificationFile ? verificationFile.name : 'Anexar PDF'}</span>
                   </div>
                </div>
              )}
            </div>
          )}

          <button type="submit" disabled={loading} className="w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 bg-green-600 text-white mt-4 disabled:opacity-50">
            {loading ? <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> : isRegister ? 'Cadastrar' : 'Entrar'}
          </button>
        </form>

        <button onClick={() => { setIsRegister(!isRegister); setError(''); }} className="w-full mt-8 text-[8px] font-black uppercase tracking-[0.3em] text-gray-400 hover:text-blue-600 transition-colors">
          {isRegister ? 'Já tem conta? Entrar' : 'Novo por aqui? Criar conta'}
        </button>
      </div>
    </div>
  );
};

export default AuthPage;

