export const loginUser = async (email: string, password: string): Promise<User> => {
  const users = getUsers();
  const user = users.find(u => u.email === email);
  if (user) return user;
  throw new Error('Credenciais inválidas.');
};

export const registerUser = async (userData: any): Promise<User> => {
  const users = getUsers();
  if (users.some(u => u.email === userData.email)) throw new Error('Email já cadastrado.');

  let finalPic = userData.profilePicture;
  if (finalPic && finalPic.length > 50000) {
    finalPic = await compressImage(finalPic);
  }

  const newUser: User = {
    ...userData,
    profilePicture: finalPic || DEFAULT_PROFILE_PIC,
    id: `user-${Date.now()}`,
    followedUsers: [],
    followers: [],
    balance: 0
  };

  if (newUser.userType === UserType.CREATOR) {
    const allStores = getStores();
    const newStore: Store = {
      id: `store-${Date.now()}`,
      professorId: newUser.id,
      name: `Loja de ${newUser.firstName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: []
    };
    newUser.storeId = newStore.id;
    saveStores([...allStores, newStore]);
  }

  saveUsers([...users, newUser]);
  return newUser;
};

export const deleteUser = (uId: string) => {
  const users = getUsers().filter(u => u.id !== uId);
  saveUsers(users);
};

export const getUsers = (): User[] => get(KEYS.USERS, DEFAULT_USERS);
export const findUserById = (id: string) => getUsers().find(u => u.id === id);
export const saveUsers = (users: User[]) => set(KEYS.USERS, users);

export const updateUser = async (updatedUser: User) => {
  const users = getUsers();

  if (updatedUser.profilePicture && updatedUser.profilePicture.startsWith('data:image') && updatedUser.profilePicture.length > 50000) {
    updatedUser.profilePicture = await compressImage(updatedUser.profilePicture);
  }

  const updatedUsers = users.map(u => u.id === updatedUser.id ? updatedUser : u);
  saveUsers(updatedUsers);
};

export const toggleFollowUser = (currentUserId: string, targetId: string) => {
  const users = getUsers();
  const current = users.find(u => u.id === currentUserId);
  const target = users.find(u => u.id === targetId);
  if (current && target) {
    if (current.followedUsers.includes(targetId)) {
      current.followedUsers = current.followedUsers.filter(id => id !== targetId);
      target.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      current.followedUsers.push(targetId);
      target.followers.push(currentUserId);
      createNotification({
        type: NotificationType.NEW_FOLLOWER,
        recipientId: targetId,
        actorId: currentUserId,
        timestamp: Date.now(),
      });
    }
    saveUsers(users);
  }
};

export const adminUpdateUser = (uId: string, updates: Partial<User>, adminId: string) => {
  const users = getUsers();
  const updated = users.map(u => u.id === uId ? { ...u, ...updates } : u);
  saveUsers(updated);
  addSystemLog({ adminId, action: 'UPDATE_USER', targetId: uId, details: JSON.stringify(updates) });
};

