export const loginUser = async (email: string, password: string): Promise<User> => {
  const users = getUsers();
  const user = users.find(u => u.email === email);
  if (user) return user;
  throw new Error('Credenciais inválidas.');
};

export const registerUser = async (userData: any): Promise<User> => {
  const users = getUsers();
  if (users.some(u => u.email === userData.email)) throw new Error('Email já cadastrado.');

  let finalPic = userData.profilePicture;
  if (finalPic && finalPic.length > 50000) {
    finalPic = await compressImage(finalPic);
  }

  const newUser: User = {
    ...userData,
    profilePicture: finalPic || DEFAULT_PROFILE_PIC,
    id: `user-${Date.now()}`,
    followedUsers: [],
    followers: [],
    balance: 0
  };

  if (newUser.userType === UserType.CREATOR) {
    const allStores = getStores();
    const newStore: Store = {
      id: `store-${Date.now()}`,
      professorId: newUser.id,
      name: `Loja de ${newUser.firstName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: []
    };
    newUser.storeId = newStore.id;
    saveStores([...allStores, newStore]);
  }

  saveUsers([...users, newUser]);
  return newUser;
};

export const deleteUser = (uId: string) => {
  const users = getUsers().filter(u => u.id !== uId);
  saveUsers(users);
};

export const getUsers = (): User[] => get(KEYS.USERS, DEFAULT_USERS);
export const findUserById = (id: string) => getUsers().find(u => u.id === id);
export const saveUsers = (users: User[]) => set(KEYS.USERS, users);

export const updateUser = async (updatedUser: User) => {
  const users = getUsers();

  if (updatedUser.profilePicture && updatedUser.profilePicture.startsWith('data:image') && updatedUser.profilePicture.length > 50000) {
    updatedUser.profilePicture = await compressImage(updatedUser.profilePicture);
  }

  const updatedUsers = users.map(u => u.id === updatedUser.id ? updatedUser : u);
  saveUsers(updatedUsers);
};

export const toggleFollowUser = (currentUserId: string, targetId: string) => {
  const users = getUsers();
  const current = users.find(u => u.id === currentUserId);
  const target = users.find(u => u.id === targetId);
  if (current && target) {
    if (current.followedUsers.includes(targetId)) {
      current.followedUsers = current.followedUsers.filter(id => id !== targetId);
      target.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      current.followedUsers.push(targetId);
      target.followers.push(currentUserId);
      createNotification({
        type: NotificationType.NEW_FOLLOWER,
        recipientId: targetId,
        actorId: currentUserId,
        timestamp: Date.now(),
      });
    }
    saveUsers(users);
  }
};

export const adminUpdateUser = (uId: string, updates: Partial<User>, adminId: string) => {
  const users = getUsers();
  const updated = users.map(u => u.id === uId ? { ...u, ...updates } : u);
  saveUsers(updated);
  addSystemLog({ adminId, action: 'UPDATE_USER', targetId: uId, details: JSON.stringify(updates) });
};

export const adminDeletePost = (pId: string, adminId: string) => {
  const posts = getPosts().filter(p => p.id !== pId);
  savePosts(posts);
  addSystemLog({ adminId, action: 'DELETE_POST', targetId: pId, details: 'Post removido por moderação.' });
};

export const adminProcessReport = (reportId: string, status: 'RESOLVED' | 'DISMISSED', adminId: string) => {
  const reports = getReports().map(r => r.id === reportId ? { ...r, status } : r);
  set(KEYS.REPORTS, reports);
  addSystemLog({ adminId, action: 'RESOLVE_REPORT', targetId: reportId, details: `Status: ${status}` });
};

export const updateUserBalance = (uId: string, amount: number, desc: string = 'Transação de Sistema'): boolean => {
  const users = getUsers();
  const idx = users.findIndex(u => u.id === uId);
  if (idx === -1) return false;

  users[idx].balance = (users[idx].balance || 0) + amount;
  saveUsers(users);

  const transactions = getTransactions();
  transactions.push({
    id: `tx-${Date.now()}`,
    userId: uId,
    amount,
    type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
    description: desc,
    timestamp: Date.now(),
    status: 'COMPLETED'
  });
  set(KEYS.TRANSACTIONS, transactions);
  return true;
};

export const getPosts = (): Post[] => get(KEYS.POSTS, DEFAULT_POSTS);
export const savePosts = (posts: Post[]) => set(KEYS.POSTS, posts);

export const addPost = (post: Post) => {
  const currentPosts = getPosts();
  savePosts([post, ...currentPosts]);

  // Notifica todos os seguidores do autor
  const author = findUserById(post.userId);
  if (author && author.followers) {
    author.followers.forEach(followerId => {
      createNotification({
        type: NotificationType.NEW_POST,
        recipientId: followerId,
        actorId: post.userId,
        postId: post.id,
        timestamp: Date.now(),
      });
    });
  }
};

export const updatePost = (updatedPost: Post) => {
  const posts = getPosts().map(p => p.id === updatedPost.id ? updatedPost : p);
  savePosts(posts);
};
export const deletePost = (pId: string) => savePosts(getPosts().filter(p => p.id !== pId));

export const pinPost = (postId: string, userId: string) => {
  const posts = getPosts();
  posts.forEach(p => { if(p.userId === userId) p.isPinned = (p.id === postId); });
  savePosts(posts);
  return true;
};
export const unpinPost = (postId: string, userId: string) => {
  const posts = getPosts();
  const p = posts.find(p => p.id === postId && p.userId === userId);
  if (p) p.isPinned = false;
  savePosts(posts);
  return true;
};

export const updatePostLikes = (pId: string, uId: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) {
    if (post.likes.includes(uId)) post.likes = post.likes.filter(id => id !== uId);
    else {
      post.likes.push(uId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: uId, postId: pId, timestamp: Date.now() });
    }
    updatePost(post);
  }
};

export const updatePostSaves = (pId: string, uId: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) {
    if (post.saves.includes(uId)) post.saves = post.saves.filter(id => id !== uId);
    else post.saves.push(uId);
    updatePost(post);
  }
};

export const updatePostShares = (pId: string, uId: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post && !post.shares.includes(uId)) {
    post.shares.push(uId);
    updatePost(post);
  }
};

export const addPostComment = (pId: string, comment: Comment) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) {
    post.comments.push(comment);
    createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: pId, timestamp: Date.now() });
    updatePost(post);
  }
};

export const boostPost = (postId: string, userId: string, budget: number, days: number) => {
  const post = getPosts().find(p => p.id === postId);
  if (post && updateUserBalance(userId, -budget, `Impulsionamento de Post`)) {
    post.isBoosted = true;
    post.boostExpires = Date.now() + (days * 24 * 60 * 60 * 1000);
    updatePost(post);
    return true;
  }
  return false;
};

export const indicatePostToUser = (postId: string, fromId: string, toId: string) => {
  const post = getPosts().find(p => p.id === postId);
  if (post) {
    if (!post.indicatedUserIds) post.indicatedUserIds = [];
    if (post.indicatedUserIds.includes(toId)) return false;
    post.indicatedUserIds.push(toId);
    updatePost(post);

    // Notifica o usuário alvo da indicação
    createNotification({
      type: NotificationType.INDICATION,
      recipientId: toId,
      actorId: fromId,
      postId: postId,
      timestamp: Date.now(),
    });
    return true;
  }
  return false;
};

