export const addProductRating = (saleId: string, rating: number, comment: string) => {
  const sales = getAllSales();
  const sale = sales.find(s => s.id === saleId);
  if (sale && !sale.isRated) {
    sale.isRated = true;
    saveAffiliateSales(sales);
    const product = findProductById(sale.productId);
    if (product) {
      product.ratings.push({ id: `rate-${Date.now()}`, saleId, userId: sale.buyerId, rating, comment, timestamp: Date.now() });
      product.ratingCount = product.ratings.length;
      product.averageRating = product.ratings.reduce((a, b) => a + b.rating, 0) / product.ratingCount;
      saveProducts(getProducts().map(p => p.id === product.id ? product : p));
    }
  }
};

export const processProductPurchase = (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: any) => {
  const sales = getAllSales();
  cartItems.forEach(item => {
    const prod = findProductById(item.productId);
    if (prod) {
      const sale: AffiliateSale = {
        id: `sale-${Date.now()}-${item.productId}`,
        productId: item.productId,
        buyerId,
        affiliateUserId: affiliateUserId || '',
        storeId: prod.storeId,
        commissionEarned: prod.price * item.quantity * prod.affiliateCommissionRate,
        saleAmount: prod.price * item.quantity,
        timestamp: Date.now(),
        status: OrderStatus.WAITLIST,
        shippingAddress,
        digitalContentUrl: prod.digitalContentUrl
      };
      sales.push(sale);
      if (affiliateUserId) {
        updateUserBalance(affiliateUserId, sale.commissionEarned, `Comissão de Venda #${sale.id}`);
        createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliateUserId, actorId: buyerId, timestamp: Date.now(), saleId: sale.id });
      }
      const store = findStoreById(prod.storeId);
      if (store) updateUserBalance(store.professorId, sale.saleAmount - sale.commissionEarned, `Venda de Produto #${sale.id}`);
    }
  });
  saveAffiliateSales(sales);
  clearCart();
  return true;
};

