const SearchResultsPage: React.FC<SearchResultsPageProps> = ({ currentUser, query, onNavigate, refreshUser }) => {
  const [foundUsers, setFoundUsers] = useState<User[]>([]);
  const [foundPosts, setFoundPosts] = useState<Post[]>([]);
  const [foundProducts, setFoundProducts] = useState<Product[]>([]);
  const [activeTab, setActiveTab] = useState<SearchTab>('all');
  const [loading, setLoading] = useState(true);
  const [isFilterMobileOpen, setIsFilterMobileOpen] = useState(false);

  // Filtros de refinamento
  const [maxPrice, setMaxPrice] = useState<number>(1000);
  const [onlyVerified, setOnlyVerified] = useState(false);
  const [sortBy, setSortBy] = useState<'relevant' | 'newest'>('relevant');

  const performSearch = useCallback(() => {
    if (!query) return;
    setLoading(true);
    const lowerQuery = query.toLowerCase();

    let users = getUsers().filter(u => `${u.firstName} ${u.lastName}`.toLowerCase().includes(lowerQuery));
    if (onlyVerified) users = users.filter(u => u.userType === UserType.CREATOR);

    let posts = getPosts().filter(p => p.content?.toLowerCase().includes(lowerQuery));
    if (sortBy === 'newest') posts = posts.sort((a, b) => b.timestamp - a.timestamp);

    let products = getProducts().filter(p => p.name.toLowerCase().includes(lowerQuery));
    products = products.filter(p => p.price <= maxPrice);

    setFoundUsers(users);
    setFoundPosts(posts);
    setFoundProducts(products);

    setTimeout(() => setLoading(false), 300);
  }, [query, onlyVerified, maxPrice, sortBy]);

  useEffect(() => { performSearch(); }, [performSearch]);

  const handleFollowToggle = (userId: string) => {
    toggleFollowUser(currentUser.id, userId);
    refreshUser();
    performSearch();
