import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Post, AdCampaign, PostType, Story, UserType, CyberEvent } from '../types';
import { getPosts, getAds, getStories, getUsers, toggleFollowUser, getEvents } from '../services/storageService';
import { DEFAULT_PROFILE_PIC, CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../constants';
import PostCard from './PostCard';
import CreatePost from './CreatePost';
import AdCard from './AdCard';
import StoryViewerModal from './StoryViewerModal';
import CreateStoryModal from './CreateStoryModal';
import { 
  PlusIcon, ArrowPathIcon, UserPlusIcon, CheckBadgeIcon, SparklesIcon, CalendarIcon, VideoCameraIcon, BookmarkSquareIcon, FireIcon, RocketLaunchIcon, UserGroupIcon, WalletIcon, MegaphoneIcon, ArrowTrendingUpIcon, ChevronUpIcon
} from '@heroicons/react/24/outline';
import { TrophyIcon, StarIcon, CheckCircleIcon } from '@heroicons/react/24/solid';

interface FeedPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const ITEMS_PER_PAGE = 6;

const FeedPage: React.FC<FeedPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [allItems, setAllItems] = useState<(Post | AdCampaign | { type: 'SUGGESTIONS' })[]>([]);
  const [visibleItems, setVisibleItems] = useState<(Post | AdCampaign | { type: 'SUGGESTIONS' })[]>([]);
  const [displayLimit, setDisplayLimit] = useState(ITEMS_PER_PAGE);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);

  const [suggestedUsers, setSuggestedUsers] = useState<User[]>([]);
  const [stories, setStories] = useState<Story[]>([]);
  const [upcomingEvents, setUpcomingEvents] = useState<CyberEvent[]>([]);
  const [sidebarAds, setSidebarAds] = useState<AdCampaign[]>([]);

  const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
  const [isCreatingStory, setIsCreatingStory] = useState(false);

  const observerTarget = useRef<HTMLDivElement>(null);

  const loadData = useCallback((isRefresh = false) => {
    if (!isRefresh) setLoading(true);

    // Ordenação de Posts: Fixados > Impulsionados > Recentes
    const allPosts = getPosts()
      .filter(p => p && typeof p === 'object' && p.userId)
      .sort((a, b) => {
        if (a.isPinned && !b.isPinned) return -1;
        if (!a.isPinned && b.isPinned) return 1;

        const aBoosted = a.isBoosted && a.boostExpires && a.boostExpires > Date.now();
        const bBoosted = b.isBoosted && b.boostExpires && b.boostExpires > Date.now();

        if (aBoosted && !bBoosted) return -1;
        if (!aBoosted && bBoosted) return 1;

        return b.timestamp - a.timestamp;
    });

    const allAds = getAds()
      .filter(a => a.isActive)
      .sort((a, b) => (b.budget || 0) - (a.budget || 0));

    const allUsers = getUsers();
    const allStories = getStories();
    const allEvents = getEvents().filter(e => e.dateTime > Date.now()).slice(0, 3);

    setStories(allStories);
    setUpcomingEvents(allEvents);
    setSidebarAds(allAds.slice(0, 2));

    const suggestions = allUsers
      .filter(u => u && u.id !== currentUser.id && !currentUser.followedUsers?.includes(u.id))
      .sort(() => 0.5 - Math.random())
      .slice(0, 8);

    setSuggestedUsers(suggestions);

    let combined: (Post | AdCampaign | { type: 'SUGGESTIONS' })[] = [];
    let adPointer = 0;

    allPosts.forEach((post, idx) => {
        combined.push(post);
        // Insere sugestões após o primeiro post
        if (idx === 0 && suggestions.length > 0) combined.push({ type: 'SUGGESTIONS' });
        // Insere um Ad a cada 4 posts
        if ((idx + 1) % 4 === 0 && adPointer < allAds.length) {
            combined.push(allAds[adPointer]);
            adPointer++;
        }
    });

    setAllItems(combined);
    setVisibleItems(combined.slice(0, ITEMS_PER_PAGE));
    setDisplayLimit(ITEMS_PER_PAGE);
    setLoading(false);
  }, [currentUser]);

  useEffect(() => { loadData(); }, [loadData]);

  // Infinite Scroll Handler
  const loadMoreItems = useCallback(() => {
    if (loadingMore || visibleItems.length >= allItems.length) return;

    setLoadingMore(true);
    // Simula um pequeno delay para suavidade visual
    setTimeout(() => {
      const nextLimit = displayLimit + ITEMS_PER_PAGE;
      setVisibleItems(allItems.slice(0, nextLimit));
      setDisplayLimit(nextLimit);
      setLoadingMore(false);
    }, 400);
  }, [displayLimit, allItems, loadingMore, visibleItems.length]);

  // Observer para o Infinite Scroll
  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && !loading && !loadingMore && visibleItems.length < allItems.length) {
        loadMoreItems();
      }
    }, { threshold: 0.1, rootMargin: '100px' });

    if (observerTarget.current) observer.observe(observerTarget.current);
    return () => observer.disconnect();
  }, [loading, loadingMore, loadMoreItems, visibleItems.length, allItems.length]);

  // Monitorar scroll para o botão "Voltar ao Topo"
  useEffect(() => {
    const handleScroll = () => {
      setShowScrollTop(window.scrollY > 1000);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const followerCount = currentUser.followers?.length || 0;
  const progressPercent = Math.min((followerCount / CREATOR_UPGRADE_FOLLOWERS_GOAL) * 100, 100);

  const isAtEnd = visibleItems.length >= allItems.length && allItems.length > 0;

  return (
    <div className="w-full max-w-[1400px] mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-8 relative">

      {/* Botões Flutuantes */}
      <div className="fixed bottom-24 right-6 z-[60] flex flex-col gap-3">
        {showScrollTop && (
          <button 
            onClick={scrollToTop}
            className="bg-white dark:bg-darkcard text-blue-600 p-4 rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 animate-fade-in active:scale-95 transition-all"
          >
            <ChevronUpIcon className="h-6 w-6 stroke-[3]" />
          </button>
        )}
        <button 
          onClick={() => onNavigate('ads')}
          className="bg-blue-600 text-white p-4 rounded-2xl shadow-[0_15px_30px_rgba(37,99,235,0.4)] hover:scale-105 active:scale-95 transition-all"
        >
          <RocketLaunchIcon className="h-7 w-7" />
        </button>
      </div>

      {/* Stories Section */}
      <section className="mb-8 bg-white dark:bg-[#1a1c23] rounded-[2.5rem] p-4 shadow-sm border border-gray-100 dark:border-white/5 relative overflow-hidden">
        <div className="flex gap-5 overflow-x-auto pb-2 no-scrollbar scroll-smooth">
          <div onClick={() => setIsCreatingStory(true)} className="flex-shrink-0 flex flex-col items-center gap-2 cursor-pointer group">
            <div className="relative p-1 rounded-[1.8rem] border-2 border-dashed border-blue-500 group-hover:bg-blue-50 transition-all">
              <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-14 h-14 md:w-16 md:h-16 rounded-[1.4rem] object-cover" />
              <div className="absolute -bottom-1 -right-1 bg-blue-600 text-white rounded-lg p-1 border-2 border-white dark:border-[#1a1c23] shadow-lg">
                <PlusIcon className="w-3 h-3 stroke-[4]" />
              </div>
            </div>
            <span className="text-[9px] font-black dark:text-gray-400 uppercase tracking-widest">Novo</span>
          </div>
          {stories.map((s, i) => (
            <div key={i} onClick={() => setSelectedStoryIndex(i)} className="flex-shrink-0 flex flex-col items-center gap-2 cursor-pointer">
              <div className="p-1 rounded-[1.8rem] bg-gradient-to-tr from-blue-500 via-purple-500 to-red-500">
                <div className="p-0.5 bg-white dark:bg-[#1a1c23] rounded-[1.4rem]">
                  <img src={s.userProfilePic || DEFAULT_PROFILE_PIC} className="w-14 h-14 md:w-16 md:h-16 rounded-[1.2rem] object-cover" />
                </div>
              </div>
              <span className="text-[9px] font-black dark:text-gray-400 truncate w-14 text-center">{s.userName.split(' ')[0]}</span>
            </div>
          ))}
        </div>
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <main className="lg:col-span-8 space-y-8">
          <CreatePost currentUser={currentUser} onPostCreated={() => loadData(true)} refreshUser={refreshUser} />

          <div className="space-y-8">
            {loading ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                <p className="mt-4 text-[10px] font-black uppercase text-gray-400 tracking-widest">Carregando Conhecimento...</p>
              </div>
            ) : (
              <>
                {visibleItems.map((item, idx) => {
                  if ('authorName' in item) {
                    return <PostCard key={(item as Post).id} post={item as Post} currentUser={currentUser} onNavigate={onNavigate} onFollowToggle={() => loadData(true)} refreshUser={refreshUser} onPostUpdatedOrDeleted={() => loadData(true)} onPinToggle={() => loadData(true)} />;
                  }
                  if ('professorId' in item) {
                    const adsArray = allItems.filter(i => 'professorId' in i) as AdCampaign[];
                    const adRank = adsArray.findIndex(a => a.id === item.id);
                    return <AdCard key={(item as AdCampaign).id} ad={item as AdCampaign} rank={adRank} />;
                  }
                  if ('type' in item && item.type === 'SUGGESTIONS') {
                    return (
                      <div key="sugg" className="bg-gradient-to-br from-indigo-600 to-blue-800 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden animate-fade-in">
                         <SparklesIcon className="absolute -right-10 -bottom-10 w-72 h-72 opacity-10" />
                         <div className="flex items-center justify-between mb-8">
                            <div>
                               <h4 className="font-black text-2xl tracking-tighter flex items-center gap-3"><FireIcon className="h-8 w-8 text-yellow-400" /> Networking</h4>
                               <p className="text-blue-100 text-xs font-bold uppercase tracking-widest">Sugestões de Conexão CyBer</p>
                            </div>
                            <button onClick={() => loadData(true)} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all"><ArrowPathIcon className="h-6 w-6"/></button>
                         </div>
                         <div className="flex gap-5 overflow-x-auto pb-4 no-scrollbar">
                            {suggestedUsers.map(u => (
                              <div key={u.id} className="bg-white/10 backdrop-blur-xl p-6 rounded-[2.5rem] min-w-[180px] flex flex-col items-center text-center border border-white/10 group">
                                 <img src={u.profilePicture} className="w-20 h-20 rounded-2xl object-cover mb-3 border-2 border-white/20 shadow-xl group-hover:scale-110 transition-transform" />
                                 <p className="font-black text-sm truncate w-full">{u.firstName} {u.lastName}</p>
                                 <p className="text-[8px] font-black text-blue-200 uppercase mb-4 tracking-tighter">{u.credentials || 'Especialista'}</p>
                                 <button onClick={() => { toggleFollowUser(currentUser.id, u.id); refreshUser(); loadData(true); }} className="w-full bg-white text-blue-800 py-2.5 rounded-xl font-black text-[9px] uppercase shadow-lg active:scale-95 transition-all">Seguir</button>
                              </div>
                            ))}
                         </div>
                      </div>
                    );
                  }
                  return null;
                })}

                {/* Sentinela do Infinite Scroll */}
                <div ref={observerTarget} className="h-24 flex flex-col items-center justify-center">
                  {loadingMore && (
                    <>
                      <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                      <p className="mt-3 text-[9px] font-black text-gray-400 uppercase tracking-widest">Buscando mais conteúdos...</p>
                    </>
                  )}
                  {isAtEnd && (
                    <div className="flex flex-col items-center gap-3 opacity-60 py-10">
                       <CheckCircleIcon className="h-10 w-10 text-green-500" />
                       <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.3em]">Você chegou ao fim do seu feed!</p>
                       <button onClick={scrollToTop} className="text-blue-600 text-[9px] font-black uppercase underline tracking-widest mt-2">Voltar para o topo</button>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </main>

        <aside className="hidden lg:block lg:col-span-4 space-y-6">
           <div className="sticky top-24 space-y-6">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-[2.5rem] p-8 text-white shadow-xl relative overflow-hidden group">
                 <RocketLaunchIcon className="absolute -right-4 -bottom-4 w-32 h-32 opacity-10 group-hover:scale-110 transition-transform duration-700" />
                 <h3 className="text-xl font-black uppercase tracking-tighter mb-4 flex items-center gap-2">
                    <TrophyIcon className="h-6 w-6 text-yellow-400" /> Meta Profissional
                 </h3>
                 <div className="mb-6">
                    <div className="flex justify-between text-[10px] font-black uppercase mb-2">
                       <span>Progresso</span>
                       <span>{followerCount} / 2.000</span>
                    </div>
                    <div className="w-full h-2.5 bg-white/20 rounded-full overflow-hidden border border-white/10">
                       <div className="h-full bg-white shadow-[0_0_10px_white] transition-all duration-1000" style={{ width: `${progressPercent}%` }} />
                    </div>
                 </div>
                 <button 
                   onClick={() => onNavigate('ads')}
                   className="w-full bg-white text-blue-700 py-4 rounded-2xl font-black text-[11px] uppercase shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3"
                 >
                    <MegaphoneIcon className="h-5 w-5" /> Impulsionar Perfil
                 </button>
              </div>

              <div className="bg-white dark:bg-[#1a1c23] rounded-[2.5rem] p-8 shadow-sm border border-gray-100 dark:border-white/5">
                 <div className="flex items-center justify-between mb-8">
                    <h3 className="font-black text-gray-900 dark:text-white uppercase text-[10px] tracking-[0.2em] flex items-center gap-3">
                       <StarIcon className="h-6 w-6 text-blue-600" /> Membros em Destaque
                    </h3>
                    <button onClick={() => onNavigate('store')} className="text-[8px] font-black text-blue-600 uppercase hover:underline">Ver Todos</button>
                 </div>
                 <div className="space-y-4">
                    {sidebarAds.length > 0 ? sidebarAds.map((ad, i) => (
                       <AdCard key={ad.id} ad={ad} isSidebar={true} rank={i} />
                    )) : (
                       <div className="text-center py-6 bg-gray-50 dark:bg-white/5 rounded-3xl border border-dashed border-gray-200">
                          <ArrowTrendingUpIcon className="h-8 w-8 text-gray-300 mx-auto mb-2" />
                          <p className="text-[9px] text-gray-400 font-black uppercase">Sua aula aqui?</p>
                       </div>
                    )}
                 </div>
              </div>

              <div className="bg-white dark:bg-[#1a1c23] rounded-[2.5rem] p-8 shadow-sm border border-gray-100 dark:border-white/5">
                 <h3 className="font-black text-gray-900 dark:text-white uppercase text-[10px] tracking-[0.2em] mb-8 flex items-center gap-3">
                    <CalendarIcon className="h-6 w-6 text-blue-600" /> Próximos Eventos
                 </h3>
                 <div className="space-y-6">
                    {upcomingEvents.length > 0 ? upcomingEvents.map(evt => (
                      <div key={evt.id} onClick={() => onNavigate('events')} className="flex items-center gap-5 group cursor-pointer">
                         <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-2xl text-blue-600 font-black text-center min-w-[60px] shadow-sm">
                            <p className="text-[9px] leading-none mb-1 uppercase">{new Date(evt.dateTime).toLocaleDateString('pt-BR', { month: 'short' })}</p>
                            <p className="text-xl leading-none">{new Date(evt.dateTime).getDate()}</p>
                         </div>
                         <div className="min-w-0">
                            <p className="font-black text-sm text-gray-900 dark:text-white truncate group-hover:text-blue-600 transition-colors leading-tight">{evt.title}</p>
                            <p className="text-[9px] text-gray-400 font-black uppercase tracking-widest mt-1">{evt.type === 'ONLINE' ? 'Virtual' : 'Presencial'}</p>
                         </div>
                      </div>
                    )) : (
                       <div className="text-center py-6">
                          <UserGroupIcon className="h-8 w-8 text-gray-200 mx-auto mb-2" />
                          <p className="text-[10px] font-black uppercase">Sem eventos próximos</p>
                       </div>
                    )}
                 </div>
              </div>
           </div>
        </aside>
      </div>

      {selectedStoryIndex !== null && <StoryViewerModal stories={stories} initialIndex={selectedStoryIndex} onClose={() => setSelectedStoryIndex(null)} />}
      {isCreatingStory && <CreateStoryModal currentUser={currentUser} onClose={() => setIsCreatingStory(false)} onStoryCreated={() => { setIsCreatingStory(false); loadData(true); }} />}
    </div>
  );
};

export default FeedPage;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Message } from '../types';
import { getPosts, findUserById, updateUserBalance, deletePost, getGlobalSettings } from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  XMarkIcon,
  HandRaisedIcon,
  SignalIcon,
  UsersIcon,
  ComputerDesktopIcon,
  PowerIcon,
  BanknotesIcon,
  PaperAirplaneIcon,
  SparklesIcon,
  PlayIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedIconOutline,
  ChatBubbleLeftRightIcon as ChatIconOutline,
  ComputerDesktopIcon as ScreenIconOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(false);
  const [isCamOn, setIsCamOn] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);

  // Estado para garantir que o desligamento manual seja respeitado
  const [cameraManuallyDisabled, setCameraManuallyDisabled] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  const [activeSidebar, setActiveSidebar] = useState<'chat' | null>(null);
  const [handRaised, setHandRaised] = useState(false);

  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax;

  useEffect(() => {
    const foundPost = getPosts().find(p => p.id === postId);
    if (foundPost && foundPost.liveStream) {
      setPost(foundPost);
      const author = findUserById(foundPost.userId);
      setCreator(author || null);
    } else {
      onNavigate('feed');
    }
    return () => stopStreams();
  }, [postId, onNavigate]);

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  useEffect(() => {
    if (isCamOn && videoElementRef.current && streamRef.current) {
      if (videoElementRef.current.srcObject !== streamRef.current) {
        videoElementRef.current.srcObject = streamRef.current;
      }
    }
  }, [activeSidebar, showDonationModal, isCamOn]);

  const stopStreams = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
  };

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
      setIsScreenSharing(false);
      setCameraManuallyDisabled(true); // Marca como desligado pelo usuário
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        const oldTracks = streamRef.current.getVideoTracks();
        oldTracks.forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
        setCameraManuallyDisabled(false); // Reseta o override manual
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  const toggleMic = async () => {
    if (isMicOn) {
      if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => {
          track.enabled = false;
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsMicOn(false);
    } else {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const audioTrack = audioStream.getAudioTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.addTrack(audioTrack);
        setIsMicOn(true);
      } catch (err) { alert("Microfone indisponível."); }
    }
  };

  const startScreenShare = async () => {
    try {
      const screenStream = await (navigator.mediaDevices as any).getDisplayMedia({ video: true });
      const screenTrack = screenStream.getVideoTracks()[0];
      screenTrack.onended = () => { setIsScreenSharing(false); setIsCamOn(false); };
      if (!streamRef.current) streamRef.current = new MediaStream();
      const oldVideoTracks = streamRef.current.getVideoTracks();
      oldVideoTracks.forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
      streamRef.current.addTrack(screenTrack);
      setIsScreenSharing(true);
      setIsCamOn(true);
      setCameraManuallyDisabled(false);
    } catch (err) { console.error(err); }
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;
    const msg: Message = { id: `msg-${Date.now()}`, senderId: currentUser.id, receiverId: 'room', timestamp: Date.now(), text: newMessage };
    setChatMessages(prev => [...prev, msg]);
    setNewMessage('');
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) { alert("Saldo insuficiente."); return; }
    setIsProcessingDonation(true);
    setTimeout(() => {
      updateUserBalance(currentUser.id, -pendingAmount);
      updateUserBalance(creator.id, pendingAmount * (1 - platformTax));
      refreshUser();
      setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });
      setTimeout(() => setDonationAlert(null), 5000);
      const msg: Message = { id: `don-${Date.now()}`, senderId: currentUser.id, receiverId: 'room', timestamp: Date.now(), text: `🎁 Enviou um apoio de $${pendingAmount.toFixed(2)}!` };
      setChatMessages(prev => [...prev, msg]);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
    }, 1000);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  const controlBtnClass = "p-2.5 md:p-3.5 rounded-2xl md:rounded-3xl backdrop-blur-xl border border-white/10 transition-all active:scale-90 shadow-lg flex flex-col items-center gap-0.5 group min-w-[50px] md:min-w-[64px]";
  const activeControlClass = "bg-blue-600 text-white shadow-blue-500/30 border-blue-400/30";
  const inactiveControlClass = "bg-black/40 text-white/70 hover:bg-black/60";

  return (
    <div className="fixed inset-0 bg-[#020408] z-[60] flex flex-col overflow-hidden text-white font-sans">

      {/* HEADER BAR COMPACTA */}
      <nav className="w-full flex items-center justify-between px-4 py-2 md:px-6 md:py-4 z-50 flex-shrink-0 bg-gradient-to-b from-black/80 to-transparent">
        <button 
          onClick={() => onNavigate('feed')} 
          className="p-2 md:p-3 bg-white/5 hover:bg-white/10 rounded-xl md:rounded-2xl border border-white/10 transition-all active:scale-90"
        >
          <XMarkIcon className="h-5 w-5 md:h-6 md:w-6" />
        </button>

        <div className="flex flex-col items-center">
           <div className="bg-red-600 px-3 py-1 rounded-full text-[8px] md:text-[10px] font-black flex items-center gap-1.5 shadow-[0_0_15px_rgba(220,38,38,0.4)] animate-pulse border border-red-500/50 uppercase tracking-widest">
             <SignalIcon className="h-3 w-3" /> AO VIVO
           </div>
           <p className="text-[9px] md:text-[11px] font-black uppercase mt-1 tracking-widest text-white/50 truncate max-w-[150px] md:max-w-xs">{post.liveStream.title}</p>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
           {isProfessional && (
             <button 
               onClick={() => { if(window.confirm("Encerrar transmissão?")) { deletePost(post.id); onNavigate('feed'); refreshUser(); } }} 
               className="bg-red-600 hover:bg-red-700 text-white p-2 md:p-3 rounded-xl md:rounded-2xl shadow-lg border border-red-500 transition-all active:scale-90"
             >
                <PowerIcon className="h-5 w-5 md:h-6 md:w-6" />
             </button>
           )}
           <div className="flex items-center gap-1.5 md:gap-3 bg-white/5 px-3 py-1.5 md:px-4 md:py-2.5 rounded-xl md:rounded-2xl border border-white/10 backdrop-blur-md">
              <UsersIcon className="h-3 w-3 md:h-4 md:w-4 text-blue-400" />
              <span className="text-[10px] md:xs font-black">1.4k</span>
           </div>
        </div>
      </nav>

      {/* ÁREA PRINCIPAL DO VÍDEO */}
      <main className="flex-1 flex relative items-center justify-center overflow-hidden p-1 md:p-6 lg:p-8">
        <div className="w-full h-full max-w-6xl rounded-[2rem] md:rounded-[4rem] overflow-hidden bg-black border-2 md:border-4 border-white/5 relative shadow-2xl group">

          {isCamOn ? (
            <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover bg-black" />
