export const saveUsers = (users: User[]) => set(KEYS.USERS, users);
export const deleteUser = (uId: string) => saveUsers(getUsers().filter(u => u.id !== uId));
export const updateUser = async (updatedUser: User) => saveUsers(getUsers().map(u => u.id === updatedUser.id ? updatedUser : u));

