  const chats = getChats();
  let chat = chats.find(c => c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, participants: [u1, u2], messages: [] };
    saveChats([...chats, chat]);
  }
  return chat;
};
export const sendMessage = (chatId: string, msg: Message) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === chatId);
  if (chat) { chat.messages.push(msg); saveChats(chats); }
};

export const toggleFollowUser = (currentId: string, targetId: string) => {
  const users = getUsers();
  const current = users.find(u => u.id === currentId);
  const target = users.find(u => u.id === targetId);
  if (current && target) {
    if (current.followedUsers.includes(targetId)) {
      current.followedUsers = current.followedUsers.filter(id => id !== targetId);
      target.followers = target.followers.filter(id => id !== currentId);
    } else {
      current.followedUsers.push(targetId);
      target.followers.push(currentId);
    }
    saveUsers(users);
  }
};

