export const getStories = (): Story[] => get(KEYS.STORIES, []);
export const addStory = (userId: string, item: any) => {
  const stories = getStories();
  const user = findUserById(userId);
  if (!user) return;
  let userStory = stories.find(s => s.userId === userId);
  if (!userStory) {
    userStory = { userId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
    stories.push(userStory);
  }
  userStory.items.push({ ...item, id: `story-${Date.now()}`, timestamp: Date.now() });
  set(KEYS.STORIES, stories);
};

