export const getOrCreateConversation = (u1: string, u2: string): ChatConversation => {
  const chats = getChats();
  let chat = chats.find(c => c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) { chat = { id: `chat-${Date.now()}`, participants: [u1, u2], messages: [] }; saveChats([...chats, chat]); }
  return chat;
};
export const sendMessage = (id: string, msg: Message) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === id);
  if (chat) { chat.messages.push(msg); saveChats(chats); }
};

// Social
export const toggleFollowUser = (cId: string, tId: string) => {
  const users = getUsers();
  const current = users.find(u => u.id === cId);
  const target = users.find(u => u.id === tId);
  if (current && target) {
    if (current.followedUsers.includes(tId)) {
      current.followedUsers = current.followedUsers.filter(id => id !== tId);
      target.followers = target.followers.filter(id => id !== cId);
    } else {
      current.followedUsers.push(tId);
      target.followers.push(cId);
    }
    saveUsers(users);
  }
};

export const getNotificationsForUser = (uId: string) => get(KEYS.NOTIFICATIONS, []).filter((n: any) => n.recipientId === uId);
export const markNotificationsAsRead = (uId: string) => {
    const nots = get(KEYS.NOTIFICATIONS, []).map((n: any) => n.recipientId === uId ? { ...n, isRead: true } : n);
    set(KEYS.NOTIFICATIONS, nots);
};

