export const processProductPurchase = (cart: CartItem[], buyerId: string, affiliateId: string | null, address?: any) => {
  const sales = getAllSales();
  cart.forEach(item => {
    const prod = findProductById(item.productId);
    if (prod) {
      const sale: AffiliateSale = {
        id: `sale-${Date.now()}-${item.productId}`,
        productId: item.productId, buyerId, affiliateUserId: affiliateId || '', storeId: prod.storeId,
        commissionEarned: prod.price * item.quantity * prod.affiliateCommissionRate,
        saleAmount: prod.price * item.quantity, timestamp: Date.now(), status: OrderStatus.WAITLIST, shippingAddress: address
      };
      sales.push(sale);
      if (affiliateId) updateUserBalance(affiliateId, sale.commissionEarned);
      const store = findStoreById(prod.storeId);
      if (store) updateUserBalance(store.professorId, sale.saleAmount - sale.commissionEarned);
    }
  });
  saveAffiliateSales(sales);
  saveCart([]);
  return true;
};

