  const cart = getCart();
  const item = cart.find(i => i.productId === pId);
  if (item) item.quantity += qty;
  else cart.push({ productId: pId, quantity: qty });
  saveCart(cart);
};
export const removeFromCart = (id: string) => saveCart(getCart().filter(i => i.productId !== id));
export const updateCartItemQuantity = (id: string, q: number) => saveCart(getCart().map(i => i.productId === id ? { ...i, quantity: q } : i).filter(i => i.quantity > 0));
