// Auth
export const getCurrentUserId = (): string | null => {
    const id = localStorage.getItem(KEYS.CURRENT_USER);
    if (!id || id === "null" || id === "undefined") return null;
    return id;
};

export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem(KEYS.CURRENT_USER, userId);
  else localStorage.removeItem(KEYS.CURRENT_USER);
};

export const loginUser = async (email: string, password: string): Promise<User> => {
  const users = getUsers();
  const user = users.find(u => u.email === email);
  if (user) return user;
  throw new Error('Credenciais inválidas.');
};

export const registerUser = async (userData: any): Promise<User> => {
  const users = getUsers();
  if (users.some(u => u.email === userData.email)) throw new Error('Email já cadastrado.');

  const newUser: User = {
    ...userData,
    id: `user-${Date.now()}`,
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC
  };

  if (newUser.userType === UserType.CREATOR) {
    const stores = getStores();
    const store: Store = { id: `store-${Date.now()}`, professorId: newUser.id, name: `Loja de ${newUser.firstName}`, description: 'Bem-vindo!', productIds: [] };
    newUser.storeId = store.id;
    saveStores([...stores, store]);
  }

  saveUsers([...users, newUser]);
  return newUser;
};

