  const cart = getCart();
  const item = cart.find(i => i.productId === pId);
  if (item) item.quantity += q; else cart.push({ productId: pId, quantity: q });
  set(KEYS.CART, cart);
};

// Added updateCartItemQuantity to allow flexible cart adjustments
export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) {
    cart = cart.filter(item => item.productId !== productId);
  } else {
    const item = cart.find(item => item.productId === productId);
    if (item) item.quantity = quantity;
  }
  set(KEYS.CART, cart);
};

