export const getPosts = (): Post[] => get(KEYS.POSTS, DEFAULT_POSTS);
export const savePosts = (p: Post[]) => set(KEYS.POSTS, p);
export const addPost = (p: Post) => savePosts([p, ...getPosts()]);
export const deletePost = (id: string) => savePosts(getPosts().filter(p => p.id !== id));
export const updatePost = (p: Post) => savePosts(getPosts().map(old => old.id === p.id ? p : old));

export const pinPost = (postId: string, userId: string) => {
  let posts = getPosts();
  posts.forEach(p => { if (p.userId === userId) p.isPinned = (p.id === postId); });
  savePosts(posts);
  return true;
};
export const unpinPost = (postId: string, userId: string) => {
  let posts = getPosts();
  const p = posts.find(p => p.id === postId && p.userId === userId);
  if (p) p.isPinned = false;
  savePosts(posts);
  return true;
};

export const updateUserBalance = (uId: string, amount: number): boolean => {
  const users = getUsers();
  const user = users.find(u => u.id === uId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    saveUsers(users);
    addTransaction({ userId: uId, amount, type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL, description: amount > 0 ? 'Depósito via Sistema' : 'Débito/Resgate' });
    return true;
  }
  return false;
};

