export const getAffiliateSales = (): AffiliateSale[] => get(KEYS.SALES, DEFAULT_AFFILIATE_SALES);
export const saveAffiliateSales = (s: AffiliateSale[]) => set(KEYS.SALES, s);
export const getPurchasesByBuyerId = (id: string) => getAffiliateSales().filter(s => s.buyerId === id);
export const getSalesByAffiliateId = (id: string) => getAffiliateSales().filter(s => s.affiliateUserId === id);
export const getSalesByStoreId = (id: string) => getAffiliateSales().filter(s => s.storeId === id);
export const updateSaleStatus = (id: string, status: OrderStatus) => set(KEYS.SALES, getAffiliateSales().map(s => s.id === id ? { ...s, status } : s));

export const addProductRating = (saleId: string, rating: number, comment: string) => {
  const sales = getAffiliateSales();
  const products = getProducts();
  const sale = sales.find(s => s.id === saleId);
  if (!sale || sale.isRated) return false;
  const product = products.find(p => p.id === sale.productId);
  if (!product) return false;
  sale.isRated = true;
  const newRating: ProductRating = { id: `rating-${Date.now()}`, saleId, userId: sale.buyerId, rating, comment, timestamp: Date.now() };
  product.ratings.push(newRating);
  product.ratingCount = product.ratings.length;
  product.averageRating = product.ratings.reduce((sum, r) => sum + r.rating, 0) / product.ratingCount;
  set(KEYS.SALES, sales);
  saveProducts(products);
  return true;
};

export const processProductPurchase = (cart: CartItem[], buyerId: string, affId: string | null, addr?: any) => {
  const sales = getAffiliateSales();
  const settings = getGlobalSettings();
  cart.forEach(item => {
    const prod = findProductById(item.productId);
    if (prod) {
      const sale: AffiliateSale = {
        id: `sale-${Date.now()}-${item.productId}`,
        productId: item.productId, buyerId, affiliateUserId: affId || '', storeId: prod.storeId,
        commissionEarned: prod.price * item.quantity * prod.affiliateCommissionRate,
        saleAmount: prod.price * item.quantity, timestamp: Date.now(), status: OrderStatus.WAITLIST, shippingAddress: addr
      };
      sales.push(sale);
      if (affId) updateUserBalance(affId, sale.commissionEarned);
      const store = findStoreById(prod.storeId);
      if (store) {
          const ownerRevenue = sale.saleAmount - sale.commissionEarned;
          const platformFee = ownerRevenue * settings.platformTax;
          updateUserBalance(store.professorId, ownerRevenue - platformFee);
      }
    }
  });
  set(KEYS.SALES, sales);
  set(KEYS.CART, []);
  return true;
};

export const getCart = (): CartItem[] => get(KEYS.CART, []);
export const addToCart = (pId: string, q: number = 1) => {
  const cart = getCart();
  const item = cart.find(i => i.productId === pId);
  if (item) item.quantity += q; else cart.push({ productId: pId, quantity: q });
  set(KEYS.CART, cart);
};
export const updateCartItemQuantity = (pId: string, q: number) => {
  let cart = getCart();
  if (q <= 0) cart = cart.filter(i => i.productId !== pId);
  else { const item = cart.find(i => i.productId === pId); if (item) item.quantity = q; }
  set(KEYS.CART, cart);
};
export const removeFromCart = (pId: string) => set(KEYS.CART, getCart().filter(i => i.productId !== pId));
export const clearCart = () => set(KEYS.CART, []);

export const getChats = (): ChatConversation[] => get(KEYS.CHATS, []);
export const saveChats = (c: ChatConversation[]) => set(KEYS.CHATS, c);
export const getOrCreateConversation = (u1: string, u2: string): ChatConversation => {
  const chats = getChats();
  let chat = chats.find(c => c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) { chat = { id: `chat-${Date.now()}`, participants: [u1, u2], messages: [] }; set(KEYS.CHATS, [...chats, chat]); }
  return chat;
};
export const sendMessage = (id: string, msg: Message) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === id);
  if (chat) { chat.messages.push(msg); saveChats(chats); }
};

export const getNotificationsForUser = (uId: string) => get(KEYS.NOTIFICATIONS, []).filter((n: any) => n.recipientId === uId);
export const markNotificationsAsRead = (uId: string) => set(KEYS.NOTIFICATIONS, get(KEYS.NOTIFICATIONS, []).map((n: any) => n.recipientId === uId ? { ...n, isRead: true } : n));
export const getAds = (): AdCampaign[] => get(KEYS.ADS, DEFAULT_ADS);
export const saveAds = (ads: AdCampaign[]) => set(KEYS.ADS, ads);
export const getStories = (): Story[] => get(KEYS.STORIES, []);
export const addStory = (uId: string, item: any) => {
  const stories = getStories();
  const user = findUserById(uId);
  if (!user) return;
  let s = stories.find(st => st.userId === uId);
  if (!s) { s = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] }; stories.push(s); }
  s.items.push({ ...item, id: `item-${Date.now()}`, timestamp: Date.now() });
  set(KEYS.STORIES, stories);
};
export const getEvents = (): CyberEvent[] => get(KEYS.EVENTS, []);
export const createEvent = (evt: CyberEvent) => set(KEYS.EVENTS, [evt, ...getEvents()]);
export const toggleJoinEvent = (eId: string, uId: string) => {
  const evts = getEvents();
  const evt = evts.find(e => e.id === eId);
  if (evt) {
    if (!evt.attendees) evt.attendees = [];
    if (evt.attendees.includes(uId)) evt.attendees = evt.attendees.filter(id => id !== uId);
    else evt.attendees.push(uId);
    set(KEYS.EVENTS, evts);
  }
};
export const getAudioTracks = (): AudioTrack[] => get(KEYS.AUDIO, DEFAULT_AUDIO_TRACKS);
export const findAudioTrackById = (id: string) => getAudioTracks().find(t => t.id === id);
export const updatePostLikes = (pId: string, uId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === pId);
  if (post) {
    if (post.likes.includes(uId)) post.likes = post.likes.filter(id => id !== uId);
    else post.likes.push(uId);
    updatePost(post);
  }
};
export const updatePostSaves = (pId: string, uId: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) { if (post.saves.includes(uId)) post.saves = post.saves.filter(id => id !== uId); else post.saves.push(uId); updatePost(post); }
};
export const updatePostShares = (pId: string, uId: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post && !post.shares.includes(uId)) { post.shares.push(uId); updatePost(post); }
};
export const addPostComment = (pId: string, comment: Comment) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) { post.comments.push(comment); updatePost(post); }
};
export const toggleFollowUser = (cId: string, tId: string) => {
  const users = getUsers();
  const c = users.find(u => u.id === cId);
  const t = users.find(u => u.id === tId);
  if (c && t) {
    if (c.followedUsers.includes(tId)) { c.followedUsers = c.followedUsers.filter(id => id !== tId); t.followers = t.followers.filter(id => id !== cId); }
    else { c.followedUsers.push(tId); t.followers.push(cId); }
    saveUsers(users);
  }
};
export const indicatePostToUser = (pId: string, f: string, t: string) => {
    const post = getPosts().find(p => p.id === pId);
    if (post) {
        if (!post.indicatedUserIds) post.indicatedUserIds = [];
        if (!post.indicatedUserIds.includes(t)) { post.indicatedUserIds.push(t); updatePost(post); return true; }
    }
    return false;
};
export const boostPost = (pId: string, uId: string, b: number, d: number) => {
  const post = getPosts().find(p => p.id === pId);
  if (post && updateUserBalance(uId, -b)) {
    post.isBoosted = true; post.boostExpires = Date.now() + (d * 86400000);
    updatePost(post); return true;
  }
  return false;
};
