  ExclamationTriangleIcon, KeyIcon,
  ChartBarIcon, ArrowPathIcon, EyeIcon, BoltIcon, FingerPrintIcon,
  ChevronRightIcon, ClockIcon, ArrowTrendingUpIcon,
  SparklesIcon, Bars3Icon, XMarkIcon,
  ArrowLeftOnRectangleIcon,
  CheckIcon,
  HandThumbUpIcon,
  EnvelopeIcon,
  DevicePhoneMobileIcon,
  ShieldExclamationIcon,
  UserPlusIcon,
  FunnelIcon,
  ArrowDownCircleIcon,
  ArrowUpCircleIcon,
  CommandLineIcon
} from '@heroicons/react/24/solid';
import Logo from './Logo';
import { DEFAULT_PROFILE_PIC } from '../constants';

type AdminTab = 'dashboard' | 'users' | 'moderation' | 'market' | 'ads' | 'finance' | 'config';

interface AdminDashboardProps {
  currentUser: User;
  onNavigate: (page: any) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser, onNavigate }) => {
  const [activeTab, setActiveTab] = useState<AdminTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // States para Configurações (Cópia local para edição)
  const [settings, setSettings] = useState<GlobalSettings>(getGlobalSettings());

  const refresh = () => {
    setRefreshKey(prev => prev + 1);
    setSettings(getGlobalSettings());
  };

  const data = useMemo(() => ({
    users: getUsers(),
    posts: getPosts(),
    products: getProducts(),
    ads: getAds().sort((a, b) => (b.budget || 0) - (a.budget || 0)),
    transactions: getTransactions().sort((a, b) => b.timestamp - a.timestamp),
    reports: getReports().sort((a, b) => b.timestamp - a.timestamp),
    logs: getSystemLogs().sort((a, b) => b.timestamp - a.timestamp),
    revenue: getPlatformRevenue()
  }), [refreshKey]);

  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return data.users.filter(u => 
      `${u.firstName} ${u.lastName}`.toLowerCase().includes(term) || 
      u.email.toLowerCase().includes(term) ||
      u.id.includes(term)
    );
  }, [data.users, searchTerm]);

  // --- HANDLERS FUNCIONAIS ---

  const handleToggleVerification = (user: User) => {
    const updated = { ...user, isVerified: !user.isVerified };
    adminUpdateUser(updated);
    refresh();
  };

  const handleToggleSuspension = (user: User) => {
    const updated = { ...user, isSuspended: !user.isSuspended };
    adminUpdateUser(updated);
    refresh();
  };

  const handleDeleteUser = (uId: string) => {
    if (window.confirm("ROOT: Tem certeza que deseja apagar este membro permanentemente?")) {
        deleteUser(uId);
        addSystemLog(`Usuário ${uId} removido permanentemente.`, 'USER_DELETE');
        refresh();
    }
  };

  const handleProcessReport = (rId: string, action: 'RESOLVED' | 'DISMISSED') => {
    adminProcessReport(rId, action, currentUser.id);
    refresh();
  };

  const handleDeletePost = (pId: string) => {
    if (window.confirm("Remover esta publicação globalmente?")) {
        adminDeletePost(pId);
        refresh();
    }
  };

  const handleDeleteProduct = (pId: string) => {
    if (window.confirm("Banir este produto do marketplace?")) {
        adminDeleteProduct(pId);
        refresh();
    }
  };

  const handleUpdateBalance = (uId: string) => {
    const amount = prompt("ROOT: Informe o valor para ajustar (ex: 50 ou -50):", "0");
    if (amount && !isNaN(parseFloat(amount))) {
        updateUserBalance(uId, parseFloat(amount));
        addSystemLog(`Ajuste manual de saldo para ${uId}: $${amount}`, 'BALANCE_ADJUST');
        refresh();
    }
  };

  const handleUpdateSettings = () => {
    updateGlobalSettings(settings);
    alert('SISTEMA: Configurações CyBer aplicadas.');
    refresh();
  };

  const toggleAdStatus = (adId: string) => {
    const updatedAds = data.ads.map(a => a.id === adId ? { ...a, isActive: !a.isActive } : a);
    saveAds(updatedAds);
    addSystemLog(`Status do anúncio ${adId} alterado.`, 'AD_MOD');
    refresh();
  };

  const SidebarItem = ({ id, icon: Icon, label }: { id: AdminTab, icon: any, label: string }) => (
    <button 
      onClick={() => { setActiveTab(id); setSearchTerm(''); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 ${activeTab === id ? 'bg-blue-600 text-white shadow-lg scale-105 rounded-2xl' : 'text-gray-400 hover:text-white'}`}
    >
      <Icon className="h-5 w-5" />
      <span className="font-black text-[10px] uppercase tracking-widest">{label}</span>
    </button>
  );

  return (
    <div className="fixed inset-0 bg-[#080a0f] text-white flex flex-col md:flex-row font-sans z-[9999] overflow-hidden">

      {/* SIDEBAR ADMINISTRATIVA */}
      <aside className={`fixed inset-y-0 left-0 z-[150] w-72 bg-[#0d1117] border-r border-white/5 flex flex-col p-6 transition-transform duration-300 md:sticky md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
         <div className="flex items-center justify-between mb-12">
            <Logo size="md" variant="white" className="cursor-pointer" onClick={() => onNavigate('feed')} />
            <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2"><XMarkIcon className="h-6 w-6" /></button>
         </div>

         <nav className="space-y-2 flex-1 overflow-y-auto no-scrollbar">
            <SidebarItem id="dashboard" icon={ChartPieIcon} label="Visão Geral" />
            <SidebarItem id="users" icon={UserGroupIcon} label="Gestão de Membros" />
            <SidebarItem id="moderation" icon={ShieldExclamationIcon} label="Moderação" />
            <SidebarItem id="market" icon={ShoppingBagIcon} label="Vitrines & Vendas" />
            <SidebarItem id="ads" icon={MegaphoneIcon} label="Central de Ads" />
            <SidebarItem id="finance" icon={BanknotesIcon} label="Financeiro" />
            <SidebarItem id="config" icon={Cog6ToothIcon} label="Sistema Root" />
         </nav>

         <div className="mt-10 pt-10 border-t border-white/5">
            <button onClick={() => onNavigate('feed')} className="w-full flex items-center gap-4 px-6 py-4 text-gray-400 hover:text-white transition-all bg-white/5 rounded-2xl">
               <ArrowLeftOnRectangleIcon className="h-5 w-5" />
               <span className="font-black text-[10px] uppercase tracking-widest">Voltar à Rede</span>
            </button>
         </div>
      </aside>

      <main className="flex-1 p-4 md:p-12 overflow-y-auto h-screen custom-scrollbar relative">
         <header className="flex flex-col lg:flex-row lg:items-center justify-between mb-12 gap-6">
            <div>
               <h2 className="text-4xl font-black uppercase tracking-tighter">{activeTab}</h2>
               <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mt-2 flex items-center gap-2">Painel Root Autorizado <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span></p>
            </div>

            <div className="flex items-center gap-4">
               <div className="relative">
                  <MagnifyingGlassIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" />
                  <input 
                    type="text" 
                    placeholder="Pesquisa administrativa..." 
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="bg-white/5 border border-white/10 rounded-2xl pl-12 pr-6 py-4 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-600 w-full lg:w-80 transition-all shadow-inner"
                  />
               </div>
               <button onClick={refresh} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all border border-white/5"><ArrowPathIcon className="h-6 w-6 text-gray-400" /></button>
            </div>
         </header>

         {/* ABA DASHBOARD */}
         {activeTab === 'dashboard' && (
           <div className="space-y-12 animate-fade-in">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                 {[
                   { label: 'Lucro Retido', val: `$${data.revenue.toFixed(2)}`, icon: CurrencyDollarIcon, color: 'text-green-500' },
                   { label: 'Usuários', val: data.users.length, icon: UserGroupIcon, color: 'text-blue-500' },
                   { label: 'Denúncias', val: data.reports.filter(r => r.status === 'OPEN').length, icon: ShieldExclamationIcon, color: 'text-red-500' },
                   { label: 'Ads Ativos', val: data.ads.filter(a => a.isActive).length, icon: MegaphoneIcon, color: 'text-orange-500' }
                 ].map(s => (
                   <div key={s.label} className="bg-[#12161f] p-8 rounded-[2.5rem] border border-white/5 shadow-2xl relative overflow-hidden group">
                      <div className={`absolute top-0 right-0 p-4 opacity-5 group-hover:scale-110 transition-transform ${s.color}`}><s.icon className="h-20 w-20" /></div>
                      <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">{s.label}</p>
                      <p className="text-4xl font-black tracking-tighter">{s.val}</p>
                   </div>
                 ))}
              </div>

              <div className="bg-[#12161f] p-10 rounded-[3rem] border border-white/5">
                 <h3 className="text-xs font-black uppercase tracking-[0.3em] mb-10 flex items-center gap-3 text-blue-500">
                    <CommandLineIcon className="h-5 w-5" /> Auditoria de Eventos Root
                 </h3>
                 <div className="space-y-4">
                    {data.logs.length === 0 ? (
                        <p className="text-center py-10 text-gray-600 font-black text-[10px] uppercase tracking-widest">Nenhum evento registrado</p>
                    ) : (
                        data.logs.slice(0, 15).map(log => (
                        <div key={log.id} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5 hover:bg-white/10 transition-colors">
                            <div className="flex items-center gap-4">
                                <div className="p-2 bg-blue-600/20 text-blue-400 rounded-xl font-black text-[8px] uppercase">{log.action}</div>
                                <p className="text-xs font-medium text-gray-300">{log.details}</p>
                            </div>
                            <span className="text-[9px] font-bold text-gray-500">{new Date(log.timestamp).toLocaleTimeString()}</span>
                        </div>
                        ))
                    )}
                 </div>
              </div>
           </div>
         )}

         {/* ABA USERS */}
         {activeTab === 'users' && (
            <div className="bg-[#12161f] rounded-[3rem] overflow-hidden border border-white/5 animate-fade-in shadow-2xl">
               <div className="overflow-x-auto">
                  <table className="w-full text-left">
                     <thead className="bg-black/40">
                        <tr className="text-[10px] font-black uppercase tracking-widest text-gray-500">
                           <th className="px-8 py-6">Membro</th>
                           <th className="px-8 py-6">Tipo / Status</th>
                           <th className="px-8 py-6">Saldo (USD)</th>
                           <th className="px-8 py-6 text-right">Controles Root</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-white/5">
                        {filteredUsers.map(user => (
                           <tr key={user.id} className={`hover:bg-white/[0.02] transition-colors ${user.isSuspended ? 'opacity-40 grayscale' : ''}`}>
                              <td className="px-8 py-6">
                                 <div className="flex items-center gap-4">
                                    <img src={user.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-2xl object-cover border border-white/10" />
                                    <div>
                                       <div className="flex items-center gap-2">
                                          <p className="font-black text-sm">{user.firstName} {user.lastName}</p>
                                          {user.isVerified && <CheckBadgeIcon className="h-4 w-4 text-blue-500" />}
                                       </div>
                                       <p className="text-[9px] font-bold text-gray-500 uppercase">{user.email}</p>
                                    </div>
                                 </div>
                              </td>
                              <td className="px-8 py-6">
                                 <div className="flex flex-col gap-1">
                                    <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded w-fit ${user.userType === UserType.CREATOR ? 'bg-purple-500/20 text-purple-400' : 'bg-blue-500/20 text-blue-400'}`}>
                                       {user.userType}
                                    </span>
                                    {user.isSuspended && <span className="text-[8px] font-black text-red-500 uppercase tracking-tighter">Conta Suspensa</span>}
                                 </div>
                              </td>
                              <td className="px-8 py-6">
                                 <button onClick={() => handleUpdateBalance(user.id)} className="group text-left">
                                    <p className="font-black text-lg text-green-500 group-hover:underline">${(user.balance || 0).toFixed(2)}</p>
                                    <p className="text-[7px] text-gray-600 uppercase font-black">Ajustar Saldo</p>
                                 </button>
                              </td>
                              <td className="px-8 py-6 text-right">
                                 <div className="flex items-center justify-end gap-2">
                                    <button 
                                      onClick={() => handleToggleVerification(user)} 
                                      className={`p-3 rounded-xl transition-all ${user.isVerified ? 'bg-blue-600 text-white' : 'bg-white/5 text-gray-400 hover:text-white'}`}
                                      title="Verificar/Desverificar"
                                    >
                                       <CheckBadgeIcon className="h-5 w-5" />
                                    </button>
                                    <button 
                                      onClick={() => handleToggleSuspension(user)}
                                      className={`p-3 rounded-xl transition-all ${user.isSuspended ? 'bg-red-600 text-white' : 'bg-white/5 text-gray-400 hover:text-red-500'}`}
                                      title="Suspender/Ativar"
                                    >
                                       <NoSymbolIcon className="h-5 w-5" />
                                    </button>
                                    <button 
                                      onClick={() => handleDeleteUser(user.id)}
                                      className="p-3 rounded-xl bg-white/5 text-gray-600 hover:bg-red-900/20 hover:text-red-400 transition-all"
                                      title="Remover Permanente"
                                    >
                                       <TrashIcon className="h-5 w-5" />
                                    </button>
                                 </div>
                              </td>
                           </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
         )}

         {/* ABA MODERATION */}
         {activeTab === 'moderation' && (
           <div className="grid grid-cols-1 gap-10 animate-fade-in">
              <div className="bg-[#12161f] rounded-[3rem] p-10 border border-white/5 shadow-2xl">
                 <h3 className="text-xs font-black uppercase tracking-[0.3em] mb-10 flex items-center gap-3">
                    <ShieldExclamationIcon className="h-5 w-5 text-red-500" /> Fila de Denúncias
                 </h3>
                 {data.reports.length === 0 ? (
                    <div className="py-20 text-center text-gray-600 font-black uppercase text-[10px]">Não há denúncias pendentes</div>
                 ) : (
                    <div className="space-y-6">
                       {data.reports.map(r => (
                          <div key={r.id} className="p-8 bg-white/5 rounded-[2rem] border border-white/5 flex flex-col lg:flex-row justify-between gap-6 items-start">
                             <div className="flex-1 space-y-4">
                                <div className="flex items-center gap-4">
                                   <span className="bg-red-600 px-3 py-1 rounded-lg text-[9px] font-black uppercase">{r.reason}</span>
                                   <span className={`text-[9px] font-black uppercase ${r.status === 'OPEN' ? 'text-orange-500' : 'text-green-500'}`}>{r.status}</span>
                                </div>
                                <p className="text-gray-300 text-sm italic font-medium leading-relaxed">"{r.details}"</p>
                                <div className="text-[9px] font-bold text-gray-500 uppercase flex gap-6">
                                   <span>De: {r.reporterId}</span>
                                   <span>Alvo: {r.targetType} ({r.targetId})</span>
                                </div>
                             </div>
                             <div className="flex gap-2">
                                <button onClick={() => handleProcessReport(r.id, 'RESOLVED')} className="bg-green-600 text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase shadow-lg active:scale-95 transition-all">Resolver</button>
                                <button onClick={() => handleProcessReport(r.id, 'DISMISSED')} className="bg-white/10 text-gray-400 px-6 py-3 rounded-xl font-black text-[10px] uppercase hover:text-white transition-all">Ignorar</button>
                             </div>
                          </div>
                       ))}
                    </div>
                 )}
              </div>

              <div className="bg-[#12161f] rounded-[3rem] p-10 border border-white/5 shadow-2xl">
                 <h3 className="text-xs font-black uppercase tracking-[0.3em] mb-10 flex items-center gap-3 text-purple-500">
                    <NewspaperIcon className="h-5 w-5" /> Moderação Global de Conteúdo
                 </h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {data.posts.slice(0, 15).map(post => (
                        <div key={post.id} className="p-4 bg-white/5 rounded-2xl flex items-center justify-between border border-white/5 group hover:bg-white/10 transition-colors">
                           <div className="flex items-center gap-4">
                              {post.imageUrl ? <img src={post.imageUrl} className="w-10 h-10 rounded-lg object-cover" /> : <div className="w-10 h-10 bg-white/10 rounded-lg flex items-center justify-center"><NewspaperIcon className="h-5 w-5 text-gray-400" /></div>}
                              <div className="min-w-0">
                                 <p className="text-xs font-black truncate max-w-[200px]">{post.content || 'Sem texto'}</p>
                                 <p className="text-[8px] font-bold text-gray-500 uppercase">Autor: {post.userId}</p>
                              </div>
                           </div>
                           <button onClick={() => handleDeletePost(post.id)} className="p-2.5 bg-red-900/20 text-red-500 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity"><TrashIcon className="h-4 w-4" /></button>
                        </div>
                    ))}
                 </div>
              </div>
           </div>
         )}

         {/* ABA FINANCE */}
         {activeTab === 'finance' && (
            <div className="space-y-8 animate-fade-in">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="bg-[#12161f] p-10 rounded-[3rem] border border-white/5 shadow-2xl relative overflow-hidden group">
                     <ArrowTrendingUpIcon className="absolute -right-10 -bottom-10 h-48 w-48 opacity-5 text-green-500 group-hover:scale-110 transition-transform" />
                     <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">Lucro Retido (Sistema de Taxas)</p>
                     <p className="text-6xl font-black text-green-500 tracking-tighter">${data.revenue.toFixed(2)}</p>
                  </div>
                  <div className="bg-[#12161f] p-10 rounded-[3rem] border border-white/5 shadow-2xl flex flex-col justify-center">
                     <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-6">Processamento de Saques</p>
                     <div className="flex items-center gap-4 text-orange-500">
                        <ClockIcon className="h-10 w-10 animate-spin-slow" />
                        <div>
                            <p className="text-4xl font-black">$0.00</p>
                            <p className="text-[8px] uppercase font-black text-gray-600">Nenhum saque em espera</p>
                        </div>
                     </div>
                  </div>
               </div>

               <div className="bg-[#12161f] rounded-[3rem] overflow-hidden border border-white/5 shadow-2xl">
                  <div className="p-8 border-b border-white/5 bg-black/20">
                     <h3 className="font-black text-xs uppercase tracking-widest flex items-center gap-3">
                        <CommandLineIcon className="h-5 w-5 text-green-500" /> Fluxo de Transações Globais
                     </h3>
                  </div>
                  <div className="divide-y divide-white/5">
                     {data.transactions.length === 0 ? (
                        <div className="p-24 text-center text-gray-600 font-black uppercase text-[10px]">Vazio no momento</div>
                     ) : (
                        data.transactions.map(t => (
                           <div key={t.id} className="p-6 md:p-8 flex items-center justify-between hover:bg-white/[0.02] transition-colors">
                              <div className="flex items-center gap-6">
                                 <div className={`p-4 rounded-2xl ${t.amount > 0 ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                                    {t.amount > 0 ? <ArrowDownCircleIcon className="h-6 w-6" /> : <ArrowUpCircleIcon className="h-6 w-6" />}
                                 </div>
                                 <div>
                                    <p className="font-black text-sm">{t.description}</p>
                                    <p className="text-[9px] font-bold text-gray-500 uppercase">Membro: {t.userId} • {new Date(t.timestamp).toLocaleString()}</p>
                                 </div>
                              </div>
                              <p className={`text-xl font-black ${t.amount > 0 ? 'text-green-500' : 'text-red-500'}`}>
                                 {t.amount > 0 ? '+' : ''}${Math.abs(t.amount).toFixed(2)}
                              </p>
                           </div>
                        ))
                     )}
                  </div>
               </div>
            </div>
         )}

         {/* ABA MARKET */}
         {activeTab === 'market' && (
           <div className="bg-[#12161f] rounded-[3rem] overflow-hidden border border-white/5 animate-fade-in shadow-2xl">
              <div className="overflow-x-auto">
                 <table className="w-full text-left">
                    <thead className="bg-black/40">
                       <tr className="text-[10px] font-black uppercase tracking-widest text-gray-500">
                          <th className="px-8 py-6">Produto</th>
                          <th className="px-8 py-6">Loja ID</th>
                          <th className="px-8 py-6">Preço</th>
                          <th className="px-8 py-6 text-right">Banimento</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                       {data.products.map(p => (
                          <tr key={p.id} className="hover:bg-white/[0.02] transition-colors">
                             <td className="px-8 py-6">
                                <div className="flex items-center gap-4">
                                   <img src={p.imageUrls[0]} className="w-12 h-12 rounded-xl object-cover shadow-md" />
                                   <div>
                                      <p className="font-black text-sm">{p.name}</p>
                                      <span className="text-[8px] font-black uppercase px-2 py-0.5 bg-gray-500/10 text-gray-400 rounded">{p.type}</span>
                                   </div>
                                </div>
                             </td>
                             <td className="px-8 py-6 text-xs text-blue-500 font-bold uppercase">{p.storeId}</td>
                             <td className="px-8 py-6 font-black text-green-500">${p.price.toFixed(2)}</td>
                             <td className="px-8 py-6 text-right">
                                <button onClick={() => handleDeleteProduct(p.id)} className="p-3 bg-red-900/20 text-red-500 rounded-xl hover:bg-red-600 hover:text-white transition-all"><TrashIcon className="h-5 w-5" /></button>
                             </td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
         )}

         {/* ABA CONFIG */}
         {activeTab === 'config' && (
           <div className="max-w-4xl space-y-10 animate-fade-in">
              <div className="bg-[#12161f] p-12 rounded-[3rem] border border-white/5 shadow-2xl">
                 <h3 className="text-2xl font-black uppercase tracking-tight mb-10 flex items-center gap-4 text-blue-500">
                    <Cog6ToothIcon className="h-8 w-8" /> Configurações Root do Sistema
                 </h3>

                 <div className="space-y-12">
                    <div className="space-y-5">
                       <div className="flex justify-between items-center">
                          <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Taxa de Intermediação CyBer (%)</label>
                          <span className="bg-blue-600 text-white px-4 py-1.5 rounded-full text-sm font-black">{(settings.platformTax * 100).toFixed(0)}%</span>
                       </div>
                       <input 
                         type="range" min="0" max="0.5" step="0.01" 
                         value={settings.platformTax} 
                         onChange={e => setSettings({...settings, platformTax: parseFloat(e.target.value)})}
                         className="w-full h-2 bg-white/5 rounded-full appearance-none cursor-pointer accent-blue-600" 
                       />
                    </div>

                    <div className="space-y-5">
