export const toggleFollowUser = (currentUserId: string, userIdToFollow: string) => {
  let allUsers = getUsers();
  const current = allUsers.find(u => u.id === currentUserId);
  const target = allUsers.find(u => u.id === userIdToFollow);
  if (current && target) {
    if (current.followedUsers.includes(userIdToFollow)) {
      current.followedUsers = current.followedUsers.filter(id => id !== userIdToFollow);
      target.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      current.followedUsers.push(userIdToFollow);
      target.followers.push(currentUserId);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: userIdToFollow, actorId: currentUserId, timestamp: Date.now() });
    }
    saveUsers(allUsers);
  }
};

