                    </div>
                    <div className="flex items-center gap-4 mb-6">
                       <img src={ad.imageUrl} className="w-16 h-16 rounded-2xl object-cover shadow-lg" />
                       <div>
                          <h4 className="font-black text-sm uppercase truncate max-w-[150px]">{ad.title}</h4>
                          <p className="text-[8px] font-black text-blue-500 uppercase tracking-widest">Orçamento: ${ad.budget}</p>
