                    </div>
                    <p className="text-[10px] text-gray-400 font-medium line-clamp-2 italic mb-6">"{ad.description}"</p>
                    <div className="pt-6 border-t border-white/5 flex justify-between items-center">
                       <p className="text-[9px] font-black text-gray-500 uppercase">Público: {ad.targetAudience}</p>
                       <button className="text-red-500 p-2 hover:bg-red-500/10 rounded-lg transition-colors"><TrashIcon className="h-4 w-4" /></button>
                    </div>
                 </div>
              ))}
           </div>
         )}

      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 3px; height: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #1e293b; border-radius: 10px; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fadeIn 0.4s ease-out forwards; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .animate-spin-slow { animation: spin 10s linear infinite; }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useMemo } from 'react';
import { 
  User, Post, Product, AdCampaign, Transaction, 
  ContentReport, OrderStatus, UserType, GlobalSettings 
} from '../types';
import { 
  getUsers, getPlatformRevenue, getPosts, getProducts, getAds,
  getTransactions, getSystemLogs, getReports, getGlobalSettings,
  adminUpdateUser, adminDeletePost, adminProcessReport, adminDeleteProduct,
  updateGlobalSettings, updateUserBalance, addSystemLog, saveAds, deleteUser
} from '../services/storageService';
import { 
  BanknotesIcon, UserGroupIcon, ShieldCheckIcon, TrashIcon, 
  CheckBadgeIcon, ChartPieIcon, MagnifyingGlassIcon, CurrencyDollarIcon, 
  NewspaperIcon, ShoppingBagIcon, MegaphoneIcon, NoSymbolIcon, 
  Cog6ToothIcon, BellAlertIcon, GlobeAltIcon, 
  ExclamationTriangleIcon, KeyIcon,
  ChartBarIcon, ArrowPathIcon, EyeIcon, BoltIcon, FingerPrintIcon,
  ChevronRightIcon, ClockIcon, ArrowTrendingUpIcon,
  SparklesIcon, Bars3Icon, XMarkIcon,
  ArrowLeftOnRectangleIcon,
  CheckIcon,
  HandThumbUpIcon,
  EnvelopeIcon,
  DevicePhoneMobileIcon,
  ShieldExclamationIcon,
  UserPlusIcon,
  FunnelIcon,
  ArrowDownCircleIcon,
  ArrowUpCircleIcon,
  CommandLineIcon,
  ArrowTopRightOnSquareIcon,
  NoSymbolIcon as BlockIcon
} from '@heroicons/react/24/solid';
import Logo from './Logo';
import { DEFAULT_PROFILE_PIC } from '../constants';

type AdminTab = 'dashboard' | 'users' | 'moderation' | 'market' | 'ads' | 'finance' | 'config';

interface AdminDashboardProps {
  currentUser: User;
  onNavigate: (page: any) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser, onNavigate }) => {
  const [activeTab, setActiveTab] = useState<AdminTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // States para Configurações (Cópia local para edição)
  const [settings, setSettings] = useState<GlobalSettings>(getGlobalSettings());

  const refresh = () => {
    setRefreshKey(prev => prev + 1);
    setSettings(getGlobalSettings());
  };

  const data = useMemo(() => ({
    users: getUsers(),
    posts: getPosts(),
    products: getProducts(),
    ads: getAds().sort((a, b) => (b.budget || 0) - (a.budget || 0)),
    transactions: getTransactions().sort((a, b) => b.timestamp - a.timestamp),
    reports: getReports().sort((a, b) => b.timestamp - a.timestamp),
    logs: getSystemLogs().sort((a, b) => b.timestamp - a.timestamp),
    revenue: getPlatformRevenue()
  }), [refreshKey]);

  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return data.users.filter(u => 
      `${u.firstName} ${u.lastName}`.toLowerCase().includes(term) || 
      u.email.toLowerCase().includes(term) ||
      u.id.includes(term)
    );
  }, [data.users, searchTerm]);

  // --- HANDLERS FUNCIONAIS ---

  const handleToggleVerification = (user: User) => {
    const updated = { ...user, isVerified: !user.isVerified };
    adminUpdateUser(updated);
    refresh();
  };

  const handleToggleSuspension = (user: User) => {
    const updated = { ...user, isSuspended: !user.isSuspended };
    adminUpdateUser(updated);
    refresh();
  };

  const handleDeleteUser = (uId: string) => {
    if (window.confirm("ROOT: Tem certeza que deseja apagar este membro permanentemente?")) {
        deleteUser(uId);
        addSystemLog(`Usuário ${uId} removido permanentemente.`, 'USER_DELETE');
        refresh();
    }
  };

  const handleProcessReport = (rId: string, action: 'RESOLVED' | 'DISMISSED') => {
    adminProcessReport(rId, action, currentUser.id);
    refresh();
  };

  const handleDeletePost = (pId: string) => {
    if (window.confirm("Remover esta publicação globalmente?")) {
        adminDeletePost(pId);
        refresh();
    }
  };

  const handleDeleteProduct = (pId: string) => {
    if (window.confirm("Banir este produto do marketplace?")) {
        adminDeleteProduct(pId);
        refresh();
    }
  };

  const handleUpdateBalance = (uId: string) => {
    const amount = prompt("ROOT: Informe o valor para ajustar (ex: 50 ou -50):", "0");
    if (amount && !isNaN(parseFloat(amount))) {
        updateUserBalance(uId, parseFloat(amount));
        addSystemLog(`Ajuste manual de saldo para ${uId}: $${amount}`, 'BALANCE_ADJUST');
        refresh();
    }
  };

  const handleUpdateSettings = () => {
    updateGlobalSettings(settings);
    alert('SISTEMA: Configurações CyBer aplicadas.');
    refresh();
  };

  const toggleAdStatus = (adId: string) => {
    const updatedAds = data.ads.map(a => a.id === adId ? { ...a, isActive: !a.isActive } : a);
    saveAds(updatedAds);
    addSystemLog(`Status do anúncio ${adId} alterado.`, 'AD_MOD');
    refresh();
  };

  const SidebarItem = ({ id, icon: Icon, label }: { id: AdminTab, icon: any, label: string }) => (
    <button 
      onClick={() => { setActiveTab(id); setSearchTerm(''); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 ${activeTab === id ? 'bg-blue-600 text-white shadow-lg scale-105 rounded-2xl' : 'text-gray-400 hover:text-white'}`}
    >
      <Icon className="h-5 w-5" />
      <span className="font-black text-[10px] uppercase tracking-widest">{label}</span>
    </button>
  );

  return (
    <div className="fixed inset-0 bg-[#080a0f] text-white flex flex-col md:flex-row font-sans z-[9999] overflow-hidden">

      {/* SIDEBAR ADMINISTRATIVA */}
