         <div className="flex items-center justify-between mb-12">
            <Logo size="md" variant="white" className="cursor-pointer" onClick={() => onNavigate('feed')} />
            <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400 hover:text-white"><XMarkIcon className="h-6 w-6" /></button>
         </div>

         <nav className="space-y-2 flex-1 overflow-y-auto no-scrollbar">
            <SidebarItem id="dashboard" icon={ChartPieIcon} label="Visão Geral" />
            <SidebarItem id="users" icon={UserGroupIcon} label="Gestão de Membros" />
            <SidebarItem id="moderation" icon={ShieldExclamationIcon} label="Moderação" />
            <SidebarItem id="market" icon={ShoppingBagIcon} label="Vitrines & Vendas" />
            <SidebarItem id="ads" icon={MegaphoneIcon} label="Central de Ads" />
            <SidebarItem id="finance" icon={BanknotesIcon} label="Financeiro" />
            <SidebarItem id="config" icon={Cog6ToothIcon} label="Sistema Root" />
         </nav>

         <div className="mt-10 pt-10 border-t border-white/5">
            <button onClick={() => onNavigate('feed')} className="w-full flex items-center gap-4 px-6 py-4 text-gray-400 hover:text-white transition-all bg-white/5 rounded-2xl">
               <ArrowLeftOnRectangleIcon className="h-5 w-5" />
               <span className="font-black text-[10px] uppercase tracking-widest">Voltar à Rede</span>
            </button>
         </div>
      </aside>

      {/* OVERLAY PARA MOBILE */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[500] md:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      <main className="flex-1 p-4 md:p-12 overflow-y-auto h-screen custom-scrollbar relative">
         <header className="flex flex-col lg:flex-row lg:items-center justify-between mb-12 gap-6">
            <div className="flex items-center justify-between">
               <div>
                  <h2 className="text-4xl font-black uppercase tracking-tighter">{activeTab}</h2>
                  <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mt-2 flex items-center gap-2">Painel Root Autorizado <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span></p>
               </div>

               {/* HAMBURGER BUTTON - MOBILE ONLY */}
               <button 
                 onClick={() => setIsSidebarOpen(true)}
                 className="md:hidden p-3 bg-white/5 rounded-2xl text-gray-400 hover:text-white transition-all border border-white/10"
               >
                  <Bars3Icon className="h-7 w-7" />
               </button>
            </div>

            <div className="flex items-center gap-4">
               <div className="relative flex-1 lg:flex-none">
                  <MagnifyingGlassIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" />
                  <input 
