                                      title="Remover Registro Permanente"
                                    >
                                       <TrashIcon className="h-5 w-5" />
                                    </button>
                                 </div>
                              </td>
                           </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
