                       <input 
                         type="range" min="10" max="500" step="1" 
                         value={settings.upgradeCost} 
                         onChange={e => setSettings({...settings, upgradeCost: parseFloat(e.target.value)})}
                         className="w-full h-2 bg-white/5 rounded-full appearance-none cursor-pointer accent-blue-600" 
                       />
                    </div>

                    <div className="flex items-center justify-between p-8 bg-red-900/10 border border-red-500/20 rounded-[2.5rem]">
                       <div className="flex items-center gap-5">
                          <NoSymbolIcon className="h-10 w-10 text-red-500" />
                          <div>
                             <p className="font-black text-sm text-red-500 uppercase tracking-widest">Modo de Manutenção Global</p>
                             <p className="text-[9px] text-red-200/40 uppercase font-black">Bloqueia acesso para todos exceto administradores</p>
                          </div>
                       </div>
                       <button 
                         onClick={() => setSettings({...settings, maintenanceMode: !settings.maintenanceMode})}
                         className={`w-16 h-9 rounded-full transition-all relative ${settings.maintenanceMode ? 'bg-red-600 shadow-[0_0_20px_rgba(220,38,38,0.5)]' : 'bg-gray-700'}`}
