                          <div className={`absolute top-1.5 w-6 h-6 bg-white rounded-full transition-all ${settings.maintenanceMode ? 'right-1.5' : 'left-1.5'}`} />
                       </button>
                    </div>

                    <button 
                      onClick={handleUpdateSettings}
                      className="w-full py-6 bg-blue-600 hover:bg-blue-700 text-white rounded-[2rem] font-black uppercase text-sm tracking-[0.25em] shadow-2xl active:scale-95 transition-all"
                    >
                       Persistir Parâmetros de Ecossistema
                    </button>
                 </div>
              </div>
           </div>
         )}

         {/* ABA ADS */}
         {activeTab === 'ads' && (
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 animate-fade-in">
              {data.ads.map(ad => (
                 <div key={ad.id} className="bg-[#12161f] rounded-[2.5rem] p-8 border border-white/5 shadow-2xl relative group">
                    <div className="absolute top-6 right-6">
                       <button 
                         onClick={() => toggleAdStatus(ad.id)}
                         className={`w-12 h-6 rounded-full transition-all relative ${ad.isActive ? 'bg-green-600' : 'bg-gray-700'}`}
                       >
                          <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${ad.isActive ? 'right-1' : 'left-1'}`} />
                       </button>
                    </div>
                    <div className="flex items-center gap-4 mb-6">
                       <img src={ad.imageUrl} className="w-16 h-16 rounded-2xl object-cover shadow-lg" />
                       <div>
                          <h4 className="font-black text-sm uppercase truncate max-w-[150px]">{ad.title}</h4>
                          <p className="text-[8px] font-black text-blue-500 uppercase tracking-widest">Orçamento: ${ad.budget}</p>
                       </div>
                    </div>
                    <p className="text-[10px] text-gray-400 font-medium line-clamp-2 italic mb-6">"{ad.description}"</p>
                    <div className="pt-6 border-t border-white/5 flex justify-between items-center">
                       <p className="text-[9px] font-black text-gray-500 uppercase">Público: {ad.targetAudience}</p>
                       <button className="text-red-500 p-2 hover:bg-red-500/10 rounded-lg transition-colors"><TrashIcon className="h-4 w-4" /></button>
                    </div>
                 </div>
              ))}
           </div>
         )}

      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 3px; height: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #1e293b; border-radius: 10px; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fadeIn 0.4s ease-out forwards; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .animate-spin-slow { animation: spin 10s linear infinite; }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
};

