export const getStores = (): Store[] => get(KEYS.STORES, DEFAULT_STORES);
export const findStoreById = (id: string) => getStores().find(s => s.id === id);
export const updateStore = (s: Store) => set(KEYS.STORES, getStores().map(old => old.id === s.id ? s : old));
export const getProducts = (): Product[] => get(KEYS.PRODUCTS, DEFAULT_PRODUCTS);
export const saveProducts = (p: Product[]) => set(KEYS.PRODUCTS, p);
export const findProductById = (id: string) => getProducts().find(p => p.id === id);

export const getAffiliateSales = (): AffiliateSale[] => get(KEYS.SALES, DEFAULT_AFFILIATE_SALES);
export const getPurchasesByBuyerId = (uId: string) => getAffiliateSales().filter(s => s.buyerId === uId);
export const getSalesByStoreId = (storeId: string) => getAffiliateSales().filter(sale => sale.storeId === storeId);

export const updateSaleStatus = (id: string, status: OrderStatus) => {
  const sales = getAffiliateSales().map(s => s.id === id ? { ...s, status } : s);
  set(KEYS.SALES, sales);
  addSystemLog(`Status da venda ${id} alterado para ${status}`, 'MARKET_ACTION');
};

export const processProductPurchase = (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  const allSales = getAffiliateSales();
  const settings = getGlobalSettings();

  for (const item of cartItems) {
    const product = findProductById(item.productId);
    if (!product) continue;
    const store = findStoreById(product.storeId);
    if (!store) continue;

    const netAmount = product.price * item.quantity;
    const platformFee = netAmount * settings.platformTax;
    const sellerRevenue = netAmount - platformFee;

    updateUserBalance(store.professorId, sellerRevenue);

    const newSale: AffiliateSale = {
      id: `sale-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
      productId: item.productId,
      buyerId,
      affiliateUserId: affiliateUserId || '',
      storeId: product.storeId,
      commissionEarned: 0,
      saleAmount: netAmount,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      shippingAddress,
      digitalContentUrl: product.digitalContentUrl
    };
    allSales.push(newSale);
    addSystemLog(`Venda realizada: ${product.name} para ${buyerId}`, 'MARKET_SALE');
  }
  set(KEYS.SALES, allSales);
  return true;
};

// --- UTILS ---
export const getCart = (): CartItem[] => get(KEYS.CART, []);
export const saveCart = (c: CartItem[]) => set(KEYS.CART, c);
export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
  if (existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};
export const removeFromCart = (pId: string) => saveCart(getCart().filter(i => i.productId !== pId));
export const clearCart = () => set(KEYS.CART, []);

export const getNotificationsForUser = (uId: string) => get(KEYS.NOTIFICATIONS, [] as Notification[]).filter(n => n.recipientId === uId);
export const markNotificationsAsRead = (uId: string) => {
    const all = get(KEYS.NOTIFICATIONS, [] as Notification[]);
    set(KEYS.NOTIFICATIONS, all.map(n => n.recipientId === uId ? { ...n, isRead: true } : n));
};
export const createNotification = (n: Omit<Notification, 'id' | 'isRead'>) => {
    if (n.recipientId === n.actorId) return;
    const all = get(KEYS.NOTIFICATIONS, [] as Notification[]);
    set(KEYS.NOTIFICATIONS, [{ ...n, id: `notif-${Date.now()}`, isRead: false }, ...all]);
};

export const getChats = (): ChatConversation[] => get(KEYS.CHATS, []);
export const saveChats = (c: ChatConversation[]) => set(KEYS.CHATS, c);
export const getOrCreateConversation = (u1: string, u2: string): ChatConversation => {
  const chats = getChats();
  let chat = chats.find(c => c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, participants: [u1, u2], messages: [] };
    saveChats([...chats, chat]);
  }
  return chat;
};
export const sendMessage = (id: string, m: Message) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === id);
  if (chat) { chat.messages.push(m); saveChats(chats); }
};

export const toggleFollowUser = (cur: string, tar: string) => {
  const users = getUsers();
  const c = users.find(u => u.id === cur);
  const t = users.find(u => u.id === tar);
  if (c && t) {
    if (c.followedUsers.includes(tar)) {
      c.followedUsers = c.followedUsers.filter(x => x !== tar);
      t.followers = t.followers.filter(x => x !== cur);
    } else {
      c.followedUsers.push(tar);
      t.followers.push(cur);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: tar, actorId: cur, timestamp: Date.now() });
    }
    saveUsers(users);
  }
};

export const getGlobalSettings = (): GlobalSettings => get(KEYS.SETTINGS, { platformTax: 0.1, upgradeCost: 29.9, minWithdrawal: 50, maintenanceMode: false });
export const updateGlobalSettings = (s: GlobalSettings) => {
    set(KEYS.SETTINGS, s);
    addSystemLog('Configurações globais atualizadas.', 'SYSTEM_CONFIG');
};

export const getAds = (): AdCampaign[] => get(KEYS.ADS, DEFAULT_ADS);
export const saveAds = (ads: AdCampaign[]) => set(KEYS.ADS, ads);

export const getStories = (): Story[] => get(KEYS.STORIES, []);
export const addStory = (uId: string, item: any) => {
  const stories = getStories();
  const user = findUserById(uId);
  if (!user) return;
  let s = stories.find(x => x.userId === uId);
  if (!s) {
    s = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
    stories.push(s);
  }
  s.items.push({ ...item, id: `item-${Date.now()}`, timestamp: Date.now() });
  set(KEYS.STORIES, stories);
};

export const boostPost = (pId: string, uId: string, budget: number, days: number) => {
  const post = getPosts().find(p => p.id === pId);
  if (post && updateUserBalance(uId, -budget)) {
    post.isBoosted = true;
    post.boostExpires = Date.now() + (days * 86400000);
    updatePost(post);
    addSystemLog(`Post ${pId} impulsionado por ${uId}`, 'POST_BOOST');
    return true;
  }
  return false;
};

export const compressImage = (b: string) => Promise.resolve(b);
export const getAudioTracks = (): AudioTrack[] => get(KEYS.AUDIO, DEFAULT_AUDIO_TRACKS);
export const findAudioTrackById = (id: string) => getAudioTracks().find(t => t.id === id);
export const saveAffiliateLink = (uId: string, pId: string, link: string) => {};
export const addProductRating = (sId: string, r: number, c: string) => {
    const sales = getAffiliateSales();
    const sale = sales.find(x => x.id === sId);
    if(sale) { sale.isRated = true; set(KEYS.SALES, sales); return true; }
    return false;
};
export const getEvents = (): CyberEvent[] => get(KEYS.EVENTS, []);
export const createEvent = (e: CyberEvent) => set(KEYS.EVENTS, [e, ...getEvents()]);
export const toggleJoinEvent = (eId: string, uId: string) => {
  const evts = getEvents();
  const e = evts.find(x => x.id === eId);
  if (e) {
    if (e.attendees.includes(uId)) e.attendees = e.attendees.filter(x => x !== uId);
    else e.attendees.push(uId);
    set(KEYS.EVENTS, evts);
  }
};
export const pinPost = (pId: string, uId: string) => {
  const posts = getPosts();
  posts.forEach(p => { if(p.userId === uId) p.isPinned = p.id === pId; });
  savePosts(posts);
  return true;
};
export const unpinPost = (pId: string, uId: string) => {
  const posts = getPosts();
  const p = posts.find(x => x.id === pId && x.userId === uId);
  if (p) p.isPinned = false;
  savePosts(posts);
  return true;
};
export const indicatePostToUser = (pId: string, from: string, to: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === pId);
  if (post) {
    if (!post.indicatedUserIds) post.indicatedUserIds = [];
    if (post.indicatedUserIds.includes(to)) return false;
    post.indicatedUserIds.push(to);
    updatePost(post);
    createNotification({ type: NotificationType.INDICATION, recipientId: to, actorId: from, postId: post.id, timestamp: Date.now() });
    return true;
  }
  return false;
};

