                   <button onClick={handleSave} className={`p-3 rounded-2xl transition-all active:scale-90 ${hasSaved ? 'text-yellow-500 bg-yellow-50 dark:bg-yellow-500/10' : 'hover:bg-gray-50 text-gray-300'}`}>
