const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser, onNavigate, onRefreshUser }) => {
  const [activeTab, setActiveTab] = useState<AdminTab>('users'); // Focar na aba de usuários
  const [searchTerm, setSearchTerm] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const refresh = () => {
    setRefreshKey(prev => prev + 1);
    onRefreshUser(); // Notifica o App.tsx que os dados mudaram
  };

  const data = useMemo(() => ({
    users: getUsers(),
    posts: getPosts(),
    products: getProducts(),
    ads: getAds().sort((a, b) => (b.budget || 0) - (a.budget || 0)),
    transactions: getTransactions().sort((a, b) => b.timestamp - a.timestamp),
    reports: getReports().sort((a, b) => b.timestamp - a.timestamp),
    logs: getSystemLogs().sort((a, b) => b.timestamp - a.timestamp),
    revenue: getPlatformRevenue()
  }), [refreshKey]);

  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return data.users.filter(u => 
      `${u.firstName} ${u.lastName}`.toLowerCase().includes(term) || 
      u.email.toLowerCase().includes(term) ||
      u.id.includes(term)
    );
  }, [data.users, searchTerm]);

  const handleToggleVerification = (user: User) => {
    const updated = { ...user, isVerified: !user.isVerified };
    adminUpdateUser(updated);
    refresh();
  };

  const handleToggleSuspension = (user: User) => {
    const updated = { ...user, isSuspended: !user.isSuspended };
    adminUpdateUser(updated);
    refresh();
  };

  const handleDeleteUser = (uId: string) => {
    if (window.confirm("ROOT: Tem certeza que deseja apagar este membro permanentemente?")) {
        deleteUser(uId);
        refresh();
    }
  };

  const handleUpdateBalance = (uId: string) => {
    const amount = prompt("ROOT: Informe o valor para ajustar (ex: 50 ou -50):", "0");
    if (amount !== null && !isNaN(parseFloat(amount))) {
        updateUserBalance(uId, parseFloat(amount));
        refresh();
    }
  };

  const SidebarItem = ({ id, icon: Icon, label }: { id: AdminTab, icon: any, label: string }) => (
    <button 
      onClick={() => { setActiveTab(id); setSearchTerm(''); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 ${activeTab === id ? 'bg-blue-600 text-white shadow-lg scale-105 rounded-2xl' : 'text-gray-400 hover:text-white'}`}
    >
      <Icon className="h-5 w-5" />
      <span className="font-black text-[10px] uppercase tracking-widest">{label}</span>
    </button>
  );

  return (
    <div className="fixed inset-0 bg-[#080a0f] text-white flex flex-col md:flex-row font-sans z-[9999] overflow-hidden">

      <aside className={`fixed inset-y-0 left-0 z-[510] w-72 bg-[#0d1117] border-r border-white/5 flex flex-col p-6 transition-transform duration-300 md:sticky md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
         <div className="flex items-center justify-between mb-12">
            <Logo size="md" variant="white" className="cursor-pointer" onClick={() => onNavigate('feed')} />
            <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400 hover:text-white"><XMarkIcon className="h-6 w-6" /></button>
         </div>

         <nav className="space-y-2 flex-1 overflow-y-auto no-scrollbar">
            <SidebarItem id="dashboard" icon={ChartPieIcon} label="Visão Geral" />
            <SidebarItem id="users" icon={UserGroupIcon} label="Users" />
            <SidebarItem id="moderation" icon={ShieldExclamationIcon} label="Moderação" />
            <SidebarItem id="market" icon={ShoppingBagIcon} label="Marketplace" />
            <SidebarItem id="ads" icon={MegaphoneIcon} label="Anúncios" />
            <SidebarItem id="finance" icon={BanknotesIcon} label="Financeiro" />
            <SidebarItem id="config" icon={Cog6ToothIcon} label="ROOT CFG" />
         </nav>

         <div className="mt-10 pt-10 border-t border-white/5">
            <button onClick={() => onNavigate('feed')} className="w-full flex items-center gap-4 px-6 py-4 text-gray-400 hover:text-white transition-all bg-white/5 rounded-2xl group">
               <ArrowLeftOnRectangleIcon className="h-5 w-5 group-hover:-translate-x-1 transition-transform" />
               <span className="font-black text-[10px] uppercase tracking-widest">Sair do Root</span>
            </button>
         </div>
      </aside>

      <main className="flex-1 p-4 md:p-12 overflow-y-auto h-screen custom-scrollbar relative">
         <header className="flex flex-col lg:flex-row lg:items-center justify-between mb-12 gap-6">
            <div className="flex items-center justify-between w-full lg:w-auto">
               <div>
                  <h2 className="text-4xl font-black uppercase tracking-tighter">{activeTab}</h2>
                  <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mt-2 flex items-center gap-2">Protocolo Root Ativo <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_10px_#22c55e]"></span></p>
               </div>
               <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-3 bg-white/5 rounded-2xl text-gray-400 border border-white/10">
                  <Bars3Icon className="h-7 w-7" />
               </button>
            </div>

            <div className="flex items-center gap-4 w-full lg:w-auto">
               <div className="relative flex-1 lg:w-80">
                  <MagnifyingGlassIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" />
                  <input 
                    type="text" 
                    placeholder="Pesquisar registro..." 
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="bg-white/5 border border-white/10 rounded-2xl pl-12 pr-6 py-4 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-600 w-full transition-all"
                  />
               </div>
               <button onClick={refresh} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all border border-white/5" title="Sincronizar Dados"><ArrowPathIcon className="h-6 w-6 text-gray-400" /></button>
            </div>
         </header>

         {activeTab === 'users' && (
            <div className="bg-[#0a0c12]/50 rounded-[3rem] overflow-hidden border border-white/5 animate-fade-in shadow-2xl">
               <div className="overflow-x-auto no-scrollbar">
                  <table className="w-full text-left border-collapse">
                     <thead className="bg-[#12161f]">
                        <tr className="text-[9px] font-black uppercase tracking-[0.25em] text-gray-500">
                           <th className="px-8 py-6">Membro</th>
                           <th className="px-8 py-6">Saldo USD</th>
                           <th className="px-8 py-6 text-right">Controles</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-white/[0.03]">
                        {filteredUsers.map(user => (
                           <tr key={user.id} className={`group hover:bg-white/[0.02] transition-all duration-300 ${user.isSuspended ? 'opacity-30' : ''}`}>
                              <td className="px-8 py-6">
                                 <div className="flex items-center gap-4 min-w-[200px]">
                                    <div className="relative shrink-0">
                                        <img src={user.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-[1.1rem] object-cover border-2 border-white/10 shadow-lg" />
                                        {user.isVerified && <div className="absolute -bottom-1 -right-1 bg-blue-600 p-1 rounded-lg border-2 border-[#0a0c12]"><CheckBadgeIcon className="h-3 w-3 text-white" /></div>}
                                    </div>
                                    <div className="overflow-hidden">
                                       <p className="font-black text-sm text-gray-100 uppercase tracking-tighter truncate">{user.firstName} {user.lastName}</p>
                                       <p className="text-[8px] font-black text-blue-500/60 uppercase tracking-widest truncate">{user.email}</p>
                                    </div>
                                 </div>
                              </td>
                              <td className="px-8 py-6">
                                 {/* BOTÃO DE SALDO CONFORME IMAGEM */}
                                 <button 
                                    onClick={() => handleUpdateBalance(user.id)} 
                                    className="bg-[#10b981]/5 hover:bg-[#10b981]/10 border border-[#10b981]/20 rounded-2xl px-5 py-3 transition-all flex flex-col items-center justify-center min-w-[130px] group/bal"
                                 >
                                    <p className="font-black text-lg text-[#10b981] leading-none tracking-tighter mb-1">${(user.balance || 0).toFixed(2)}</p>
                                    <p className="text-[7px] font-black text-[#10b981]/60 uppercase tracking-widest group-hover/bal:text-[#10b981]">Ajustar Saldo</p>
                                 </button>
                              </td>
                              <td className="px-8 py-6 text-right">
                                 <div className="flex items-center justify-end gap-2.5">
                                    {/* BOTÕES PÍLULAS VERTICAIS CONFORME IMAGEM */}
                                    <button 
                                      onClick={() => handleToggleVerification(user)} 
                                      className={`w-10 h-14 rounded-full flex items-center justify-center transition-all border shadow-xl active:scale-90 ${user.isVerified ? 'bg-blue-600 border-blue-400 text-white shadow-blue-500/30' : 'bg-white/5 border-white/10 text-gray-500 hover:text-blue-400'}`}
                                      title="Verificação"
                                    >
                                       <CheckBadgeIcon className="h-6 w-6" />
                                    </button>

                                    <button 
                                      onClick={() => handleToggleSuspension(user)} 
                                      className={`w-10 h-14 rounded-full flex items-center justify-center transition-all border shadow-xl active:scale-90 ${user.isSuspended ? 'bg-red-600 border-red-400 text-white shadow-red-500/30' : 'bg-white/5 border-white/10 text-gray-500 hover:text-red-500'}`}
                                      title="Suspensão"
                                    >
                                       <NoSymbolIcon className="h-6 w-6" />
                                    </button>

                                    <button 
                                      onClick={() => handleDeleteUser(user.id)} 
                                      className="w-10 h-14 rounded-full flex items-center justify-center bg-white/5 border border-white/10 text-gray-500 hover:bg-red-500/10 hover:text-red-500 transition-all shadow-lg active:scale-90"
                                      title="Remover Registro"
                                    >
                                       <TrashIcon className="h-6 w-6" />
                                    </button>
                                 </div>
                              </td>
                           </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
         )}

         {activeTab === 'dashboard' && (
           <div className="space-y-12 animate-fade-in">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                 {[
                   { label: 'Receita Root', val: `$${data.revenue.toFixed(2)}`, icon: CurrencyDollarIcon, color: 'text-green-500' },
                   { label: 'Total Membros', val: data.users.length, icon: UserGroupIcon, color: 'text-blue-500' },
                   { label: 'Moderação Fila', val: data.reports.filter(r => r.status === 'OPEN').length, icon: ShieldExclamationIcon, color: 'text-red-500' },
                   { label: 'Campanhas Ads', val: data.ads.filter(a => a.isActive).length, icon: MegaphoneIcon, color: 'text-orange-500' }
                 ].map(s => (
                   <div key={s.label} className="bg-[#12161f] p-8 rounded-[2.5rem] border border-white/5 shadow-2xl relative overflow-hidden group">
                      <div className={`absolute -right-4 -top-4 opacity-5 group-hover:scale-110 transition-transform ${s.color}`}><s.icon className="h-24 w-24" /></div>
                      <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">{s.label}</p>
                      <p className={`text-4xl font-black tracking-tighter ${s.color}`}>{s.val}</p>
                   </div>
                 ))}
              </div>

              <div className="bg-[#12161f] p-10 rounded-[3rem] border border-white/5 shadow-inner">
                 <h3 className="text-[10px] font-black uppercase tracking-[0.3em] mb-10 flex items-center gap-3 text-blue-500">
                    <CommandLineIcon className="h-5 w-5" /> Auditoria Root Ativa
                 </h3>
                 <div className="space-y-4">
                    {data.logs.slice(0, 10).map(log => (
                        <div key={log.id} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5 hover:bg-white/[0.08] transition-colors">
                            <div className="flex items-center gap-4">
                                <div className="p-2 bg-blue-600/20 text-blue-400 rounded-xl font-black text-[8px] uppercase">{log.action}</div>
                                <p className="text-xs font-medium text-gray-300">{log.details}</p>
                            </div>
                            <span className="text-[9px] font-bold text-gray-500">{new Date(log.timestamp).toLocaleTimeString()}</span>
                        </div>
                    ))}
                 </div>
              </div>
           </div>
         )}
      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; height: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #1e293b; border-radius: 10px; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fadeIn 0.4s ease-out forwards; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  User, Post, Product, AdCampaign, Transaction, 
  ContentReport, OrderStatus, UserType, GlobalSettings, TransactionType 
} from '../types';
import { 
  getUsers, getPlatformRevenue, getPosts, getProducts, getAds,
  getTransactions, getSystemLogs, getReports, getGlobalSettings,
  adminUpdateUser, adminDeletePost, adminProcessReport, adminDeleteProduct,
  updateGlobalSettings, updateUserBalance, addSystemLog, saveAds, deleteUser
} from '../services/storageService';
import { 
  BanknotesIcon, UserGroupIcon, ShieldCheckIcon, TrashIcon, 
  CheckBadgeIcon, ChartPieIcon, MagnifyingGlassIcon, CurrencyDollarIcon, 
  MegaphoneIcon, NoSymbolIcon, 
  Cog6ToothIcon, GlobeAltIcon, 
  CommandLineIcon, ArrowPathIcon, 
  ClockIcon, Bars3Icon, XMarkIcon,
  ArrowLeftOnRectangleIcon,
  ShieldExclamationIcon,
  ShoppingBagIcon,
  ArrowTrendingUpIcon,
  ExclamationTriangleIcon,
  DocumentMagnifyingGlassIcon,
  ReceiptPercentIcon,
  WrenchScrewdriverIcon
} from '@heroicons/react/24/solid';
import Logo from './Logo';
import { DEFAULT_PROFILE_PIC } from '../constants';

type AdminTab = 'dashboard' | 'users' | 'moderation' | 'market' | 'finance' | 'config';

interface AdminDashboardProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  onRefreshUser: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser, onNavigate, onRefreshUser }) => {
  const [activeTab, setActiveTab] = useState<AdminTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [settings, setSettings] = useState<GlobalSettings>(getGlobalSettings());

  const refresh = () => {
    setRefreshKey(prev => prev + 1);
    setSettings(getGlobalSettings());
    onRefreshUser();
  };

  const data = useMemo(() => ({
    users: getUsers(),
    posts: getPosts(),
    products: getProducts(),
    ads: getAds().sort((a, b) => (b.budget || 0) - (a.budget || 0)),
    transactions: getTransactions().sort((a, b) => b.timestamp - a.timestamp),
    reports: getReports().sort((a, b) => b.timestamp - a.timestamp),
    logs: getSystemLogs().sort((a, b) => b.timestamp - a.timestamp),
    revenue: getPlatformRevenue()
  }), [refreshKey]);

  const filteredItems = useMemo(() => {
    const term = searchTerm.toLowerCase();
    if (activeTab === 'users') {
      return data.users.filter(u => `${u.firstName} ${u.lastName}`.toLowerCase().includes(term) || u.email.toLowerCase().includes(term));
    }
    if (activeTab === 'moderation') {
      return data.reports.filter(r => r.reason.toLowerCase().includes(term) || r.targetId.includes(term));
    }
    if (activeTab === 'market') {
      return data.products.filter(p => p.name.toLowerCase().includes(term));
    }
    return [];
  }, [data, searchTerm, activeTab]);

  // Handlers
  const handleToggleVerification = (user: User) => {
    adminUpdateUser({ ...user, isVerified: !user.isVerified });
    refresh();
  };

  const handleToggleSuspension = (user: User) => {
    adminUpdateUser({ ...user, isSuspended: !user.isSuspended });
    refresh();
  };

  const handleDeleteUser = (uId: string) => {
    if (confirm("REMOÇÃO PERMANENTE: Esta ação não pode ser desfeita. Confirmar?")) {
      deleteUser(uId);
      refresh();
    }
  };

  const handleUpdateBalance = (uId: string) => {
    const val = prompt("Ajustar saldo (USD):", "0");
    if (val && !isNaN(parseFloat(val))) {
      updateUserBalance(uId, parseFloat(val));
      refresh();
    }
  };

  const handleProcessReport = (reportId: string, status: 'RESOLVED' | 'DISMISSED') => {
    adminProcessReport(reportId, status, currentUser.id);
    refresh();
  };

  const handleSaveSettings = (e: React.FormEvent) => {
    e.preventDefault();
    updateGlobalSettings(settings);
    refresh();
    alert("Parâmetros do sistema atualizados com sucesso.");
  };

  const SidebarItem = ({ id, icon: Icon, label }: { id: AdminTab, icon: any, label: string }) => (
    <button 
      onClick={() => { setActiveTab(id); setSearchTerm(''); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 ${activeTab === id ? 'bg-blue-600 text-white shadow-lg scale-105 rounded-2xl' : 'text-gray-400 hover:text-white'}`}
    >
      <Icon className="h-5 w-5" />
      <span className="font-black text-[10px] uppercase tracking-widest">{label}</span>
    </button>
  );

  return (
    <div className="fixed inset-0 bg-[#080a0f] text-white flex flex-col md:flex-row font-sans z-[9999] overflow-hidden">

      {/* SIDEBAR */}
      <aside className={`fixed inset-y-0 left-0 z-[510] w-72 bg-[#0d1117] border-r border-white/5 flex flex-col p-6 transition-transform duration-300 md:sticky md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
         <div className="flex items-center justify-between mb-12">
            <Logo size="md" variant="white" className="cursor-pointer" onClick={() => onNavigate('feed')} />
            <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400 hover:text-white"><XMarkIcon className="h-6 w-6" /></button>
         </div>

         <nav className="space-y-2 flex-1 overflow-y-auto no-scrollbar">
            <SidebarItem id="dashboard" icon={ChartPieIcon} label="Monitoramento" />
            <SidebarItem id="users" icon={UserGroupIcon} label="Membros" />
            <SidebarItem id="moderation" icon={ShieldExclamationIcon} label="Moderação" />
            <SidebarItem id="market" icon={ShoppingBagIcon} label="Marketplace" />
            <SidebarItem id="finance" icon={BanknotesIcon} label="Tesouraria" />
            <SidebarItem id="config" icon={WrenchScrewdriverIcon} label="Config Root" />
         </nav>

         <div className="mt-10 pt-10 border-t border-white/5">
            <button onClick={() => onNavigate('feed')} className="w-full flex items-center gap-4 px-6 py-4 text-gray-400 hover:text-white transition-all bg-white/5 rounded-2xl group">
               <ArrowLeftOnRectangleIcon className="h-5 w-5 group-hover:-translate-x-1 transition-transform" />
               <span className="font-black text-[10px] uppercase tracking-widest">Sair do Root</span>
            </button>
         </div>
      </aside>

      {/* MAIN */}
      <main className="flex-1 p-4 md:p-12 overflow-y-auto h-screen custom-scrollbar relative">
         <header className="flex flex-col lg:flex-row lg:items-center justify-between mb-12 gap-6">
            <div className="flex items-center justify-between w-full lg:w-auto">
               <div>
                  <h2 className="text-4xl font-black uppercase tracking-tighter">{activeTab}</h2>
                  <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mt-2 flex items-center gap-2">Protocolo Root Ativo <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_10px_#22c55e]"></span></p>
               </div>
               <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-3 bg-white/5 rounded-2xl text-gray-400 border border-white/10">
                  <Bars3Icon className="h-7 w-7" />
               </button>
            </div>

            <div className="flex items-center gap-4 w-full lg:w-auto">
               <div className="relative flex-1 lg:w-80">
                  <MagnifyingGlassIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" />
                  <input 
                    type="text" 
                    placeholder="Filtrar dados..." 
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="bg-white/5 border border-white/10 rounded-2xl pl-12 pr-6 py-4 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-600 w-full transition-all"
                  />
               </div>
               <button onClick={refresh} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all border border-white/5" title="Sincronizar Dados"><ArrowPathIcon className="h-6 w-6 text-gray-400" /></button>
            </div>
         </header>

         {/* MONITORAMENTO DASHBOARD */}
         {activeTab === 'dashboard' && (
           <div className="space-y-12 animate-fade-in">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                 {[
                   { label: 'Receita Total', val: `$${data.revenue.toFixed(2)}`, icon: CurrencyDollarIcon, color: 'text-green-500' },
                   { label: 'Usuários Ativos', val: data.users.length, icon: UserGroupIcon, color: 'text-blue-500' },
                   { label: 'Denúncias Abertas', val: data.reports.filter(r => r.status === 'OPEN').length, icon: ShieldExclamationIcon, color: 'text-red-500' },
                   { label: 'Anúncios No Ar', val: data.ads.filter(a => a.isActive).length, icon: MegaphoneIcon, color: 'text-orange-500' }
                 ].map(s => (
                   <div key={s.label} className="bg-[#12161f] p-8 rounded-[2.5rem] border border-white/5 shadow-2xl relative overflow-hidden group">
                      <div className={`absolute -right-4 -top-4 opacity-5 group-hover:scale-110 transition-transform ${s.color}`}><s.icon className="h-24 w-24" /></div>
                      <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">{s.label}</p>
                      <p className={`text-4xl font-black tracking-tighter ${s.color}`}>{s.val}</p>
                   </div>
                 ))}
              </div>

              {/* LOGS EM TEMPO REAL */}
              <div className="bg-[#12161f] p-10 rounded-[3rem] border border-white/5 shadow-inner">
                 <h3 className="text-[10px] font-black uppercase tracking-[0.3em] mb-10 flex items-center gap-3 text-blue-500">
                    <CommandLineIcon className="h-5 w-5" /> Auditoria Root (Últimos 10 Eventos)
                 </h3>
                 <div className="space-y-4">
                    {data.logs.slice(0, 10).map(log => (
                        <div key={log.id} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5 hover:bg-white/[0.08] transition-colors">
                            <div className="flex items-center gap-4">
                                <div className="p-2 bg-blue-600/20 text-blue-400 rounded-xl font-black text-[8px] uppercase">{log.action}</div>
                                <p className="text-xs font-medium text-gray-300">{log.details}</p>
                            </div>
                            <span className="text-[9px] font-bold text-gray-500">{new Date(log.timestamp).toLocaleTimeString()}</span>
                        </div>
                    ))}
                 </div>
              </div>
           </div>
         )}

         {/* GESTÃO DE MEMBROS */}
         {activeTab === 'users' && (
            <div className="bg-[#0a0c12]/50 rounded-[3rem] overflow-hidden border border-white/5 animate-fade-in shadow-2xl">
               <div className="overflow-x-auto no-scrollbar">
                  <table className="w-full text-left border-collapse">
