  REPORTS: 'cyber_content_reports_v5.1',
  TRANSACTIONS: 'cyber_transactions_v5.1'
};

const get = <T>(key: string, fallback: T): T => {
  try {
    const data = localStorage.getItem(key);
    if (!data || data === "undefined" || data === "null") return fallback;
    return JSON.parse(data);
  } catch (e) {
    return fallback;
  }
};

const set = (key: string, data: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(data));
  } catch (e) {}
};

export const initializeData = () => {
  if (!localStorage.getItem(KEYS.USERS)) set(KEYS.USERS, DEFAULT_USERS);
  if (!localStorage.getItem(KEYS.POSTS)) set(KEYS.POSTS, DEFAULT_POSTS);
  if (!localStorage.getItem(KEYS.STORES)) set(KEYS.STORES, DEFAULT_STORES);
  if (!localStorage.getItem(KEYS.PRODUCTS)) set(KEYS.PRODUCTS, DEFAULT_PRODUCTS);
  if (!localStorage.getItem(KEYS.SALES)) set(KEYS.SALES, DEFAULT_AFFILIATE_SALES);
  if (!localStorage.getItem(KEYS.ADS)) set(KEYS.ADS, DEFAULT_ADS);
  if (!localStorage.getItem(KEYS.AUDIO)) set(KEYS.AUDIO, DEFAULT_AUDIO_TRACKS);
  if (!localStorage.getItem(KEYS.SETTINGS)) set(KEYS.SETTINGS, { platformTax: 0.1, upgradeCost: 29.9, minWithdrawal: 50, maintenanceMode: false });
};

initializeData();

// --- ADMIN & AUDIT ---
export const getSystemLogs = (): SystemLog[] => get(KEYS.LOGS, []);
export const getReports = (): ContentReport[] => get(KEYS.REPORTS, []);
export const getTransactions = (): Transaction[] => get(KEYS.TRANSACTIONS, []);

export const addSystemLog = (details: string, action: string, adminId: string = 'root') => {
  const logs = getSystemLogs();
  const newLog: SystemLog = { id: `log-${Date.now()}`, adminId, action, details, timestamp: Date.now() };
  set(KEYS.LOGS, [newLog, ...logs].slice(0, 100));
};

export const createReport = (report: Omit<ContentReport, 'id' | 'status' | 'timestamp'>) => {
    const reports = getReports();
    const newReport: ContentReport = { ...report, id: `rep-${Date.now()}`, status: 'OPEN', timestamp: Date.now() };
    set(KEYS.REPORTS, [newReport, ...reports]);
    addSystemLog(`Nova denúncia criada contra ${report.targetType} (${report.targetId})`, 'REPORT_CREATE', report.reporterId);
};

export const adminUpdateUser = (user: User) => {
  const users = getUsers().map(u => u.id === user.id ? user : u);
  saveUsers(users);
  addSystemLog(`Membro ${user.firstName} (ID: ${user.id}) modificado via Root.`, 'USER_MOD');
};

export const adminDeletePost = (postId: string) => {
  const posts = getPosts().filter(p => p.id !== postId);
  savePosts(posts);
  addSystemLog(`Conteúdo ${postId} removido por moderação.`, 'CONTENT_MOD');
};

export const deletePost = (postId: string) => {
  savePosts(getPosts().filter(p => p.id !== postId));
  addSystemLog(`Post ${postId} removido pelo autor.`, 'POST_DELETE');
};

export const adminDeleteProduct = (productId: string) => {
  const products = getProducts().filter(p => p.id !== productId);
  saveProducts(products);
  addSystemLog(`Produto ${productId} banido do marketplace.`, 'MARKET_MOD');
};

export const adminProcessReport = (reportId: string, status: 'RESOLVED' | 'DISMISSED', adminId: string) => {
  const reports = getReports().map(r => r.id === reportId ? { ...r, status } : r);
  set(KEYS.REPORTS, reports);
  addSystemLog(`Denúncia ${reportId} marcada como ${status}.`, 'REPORT_ACTION', adminId);
};

export const getPlatformRevenue = () => {
  const sales = getAffiliateSales();
  const settings = getGlobalSettings();
  return sales.reduce((total, sale) => total + (sale.saleAmount * settings.platformTax), 0);
};

// --- AUTH ---
export const getCurrentUserId = (): string | null => localStorage.getItem(KEYS.CURRENT_USER);
export const saveCurrentUser = (id: string | null) => id ? localStorage.setItem(KEYS.CURRENT_USER, id) : localStorage.removeItem(KEYS.CURRENT_USER);
export const loginUser = async (e: string, p: string): Promise<User> => {
  const user = getUsers().find(u => u.email === e);
  if (user) return user;
  throw new Error('Credenciais inválidas.');
};

export const registerUser = async (userData: any): Promise<User> => {
  const users = getUsers();
  if (users.some(u => u.email === userData.email)) throw new Error('Email já cadastrado.');
  const newUser: User = {
    id: `user-${Date.now()}`,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.userType === UserType.CREATOR ? userData.credentials : undefined,
    bio: userData.bio
  };
  if (newUser.userType === UserType.CREATOR) {
    const storeId = `store-${Date.now()}`;
    newUser.storeId = storeId;
    const stores = getStores();
    set(KEYS.STORES, [...stores, { id: storeId, professorId: newUser.id, name: `Loja de ${newUser.firstName}`, description: 'Bem-vindo!', productIds: [] }]);
  }
  saveUsers([...users, newUser]);
  return newUser;
};

export const deleteUser = (userId: string) => {
    saveUsers(getUsers().filter(u => u.id !== userId));
    addSystemLog(`Membro ${userId} removido.`, 'USER_DELETE');
};

// --- POSTS ---
export const getPosts = (): Post[] => get(KEYS.POSTS, DEFAULT_POSTS);
export const savePosts = (p: Post[]) => set(KEYS.POSTS, p);
export const addPost = (p: Post) => {
  savePosts([p, ...getPosts()]);
  addSystemLog(`Novo post criado por ${p.userId}`, 'POST_CREATE');
};
export const updatePost = (p: Post) => savePosts(getPosts().map(old => old.id === p.id ? p : old));

export const updatePostLikes = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
      post.likes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId: post.id, timestamp: Date.now() });
    }
    updatePost(post);
  }
};

export const updatePostShares = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    updatePost(post);
  }
};

export const updatePostSaves = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
    else post.saves.push(userId);
    updatePost(post);
  }
};

export const addPostComment = (postId: string, comment: Comment) => {
  const post = getPosts().find(p => p.id === postId);
  if (post) {
    post.comments.push(comment);
    createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: post.id, timestamp: Date.now() });
    updatePost(post);
  }
};

// --- FINANCE ---
export const getUsers = (): User[] => get(KEYS.USERS, DEFAULT_USERS);
export const saveUsers = (users: User[]) => set(KEYS.USERS, users);
export const findUserById = (id: string) => getUsers().find(u => u.id === id);
export const updateUser = async (user: User) => {
    saveUsers(getUsers().map(u => u.id === user.id ? user : u));
    return user;
};

export const updateUserBalance = (uId: string, amount: number): boolean => {
  const users = getUsers();
  const user = users.find(u => u.id === uId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    saveUsers(users);
    const ts = getTransactions();
    const nt: Transaction = {
      id: `tr-${Date.now()}`,
      userId: uId,
      amount,
      type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
      description: amount > 0 ? 'Crédito CyBer' : 'Débito CyBer',
      timestamp: Date.now(),
      status: 'COMPLETED'
    };
    set(KEYS.TRANSACTIONS, [nt, ...ts]);
    return true;
  }
  return false;
};

// --- MARKETPLACE ---
export const getStores = (): Store[] => get(KEYS.STORES, DEFAULT_STORES);
export const findStoreById = (id: string) => getStores().find(s => s.id === id);
export const updateStore = (s: Store) => set(KEYS.STORES, getStores().map(old => old.id === s.id ? s : old));
export const getProducts = (): Product[] => get(KEYS.PRODUCTS, DEFAULT_PRODUCTS);
export const saveProducts = (p: Product[]) => set(KEYS.PRODUCTS, p);
export const findProductById = (id: string) => getProducts().find(p => p.id === id);

export const getAffiliateSales = (): AffiliateSale[] => get(KEYS.SALES, DEFAULT_AFFILIATE_SALES);
export const getPurchasesByBuyerId = (uId: string) => getAffiliateSales().filter(s => s.buyerId === uId);
export const getSalesByStoreId = (storeId: string) => getAffiliateSales().filter(sale => sale.storeId === storeId);

export const getSalesByAffiliateId = (affiliateUserId: string): AffiliateSale[] => {
  return getAffiliateSales().filter(sale => sale.affiliateUserId === affiliateUserId);
};

export const updateSaleStatus = (id: string, status: OrderStatus) => {
  const sales = getAffiliateSales().map(s => s.id === id ? { ...s, status } : s);
  set(KEYS.SALES, sales);
  addSystemLog(`Status da venda ${id} alterado para ${status}`, 'MARKET_ACTION');
};

export const processProductPurchase = (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  const allSales = getAffiliateSales();
  const settings = getGlobalSettings();

  for (const item of cartItems) {
    const product = findProductById(item.productId);
    if (!product) continue;
    const store = findStoreById(product.storeId);
    if (!store) continue;

    const netAmount = product.price * item.quantity;
    const platformFee = netAmount * settings.platformTax;
    const sellerRevenue = netAmount - platformFee;

    updateUserBalance(store.professorId, sellerRevenue);

    const newSale: AffiliateSale = {
      id: `sale-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
      productId: item.productId,
      buyerId,
      affiliateUserId: affiliateUserId || '',
      storeId: product.storeId,
      commissionEarned: 0,
      saleAmount: netAmount,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      shippingAddress,
      digitalContentUrl: product.digitalContentUrl
    };
    allSales.push(newSale);
    addSystemLog(`Venda realizada: ${product.name} para ${buyerId}`, 'MARKET_SALE');
  }
  set(KEYS.SALES, allSales);
  return true;
};

// --- UTILS ---
export const getCart = (): CartItem[] => get(KEYS.CART, []);
export const saveCart = (c: CartItem[]) => set(KEYS.CART, c);
export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
  if (existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) {
    cart = cart.filter(item => item.productId !== productId);
  } else {
    const item = cart.find(item => item.productId === productId);
    if (item) {
      item.quantity = quantity;
    }
  }
  saveCart(cart);
};

export const removeFromCart = (pId: string) => saveCart(getCart().filter(i => i.productId !== pId));
export const clearCart = () => set(KEYS.CART, []);

export const getNotificationsForUser = (uId: string) => get(KEYS.NOTIFICATIONS, [] as Notification[]).filter(n => n.recipientId === uId);
export const markNotificationsAsRead = (uId: string) => {
    const all = get(KEYS.NOTIFICATIONS, [] as Notification[]);
    set(KEYS.NOTIFICATIONS, all.map(n => n.recipientId === uId ? { ...n, isRead: true } : n));
};
export const createNotification = (n: Omit<Notification, 'id' | 'isRead'>) => {
    if (n.recipientId === n.actorId) return;
    const all = get(KEYS.NOTIFICATIONS, [] as Notification[]);
    set(KEYS.NOTIFICATIONS, [{ ...n, id: `notif-${Date.now()}`, isRead: false }, ...all]);
};

export const getChats = (): ChatConversation[] => get(KEYS.CHATS, []);
export const saveChats = (c: ChatConversation[]) => set(KEYS.CHATS, c);
export const getOrCreateConversation = (u1: string, u2: string): ChatConversation => {
  const chats = getChats();
  let chat = chats.find(c => c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, participants: [u1, u2], messages: [] };
    saveChats([...chats, chat]);
  }
  return chat;
};
export const sendMessage = (id: string, m: Message) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === id);
  if (chat) { chat.messages.push(m); saveChats(chats); }
};

export const toggleFollowUser = (cur: string, tar: string) => {
  const users = getUsers();
  const c = users.find(u => u.id === cur);
  const t = users.find(u => u.id === tar);
  if (c && t) {
    if (c.followedUsers.includes(tar)) {
      c.followedUsers = c.followedUsers.filter(x => x !== tar);
      t.followers = t.followers.filter(x => x !== cur);
    } else {
      c.followedUsers.push(tar);
      t.followers.push(cur);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: tar, actorId: cur, timestamp: Date.now() });
    }
    saveUsers(users);
  }
};

export const getGlobalSettings = (): GlobalSettings => get(KEYS.SETTINGS, { platformTax: 0.1, upgradeCost: 29.9, minWithdrawal: 50, maintenanceMode: false });
export const updateGlobalSettings = (s: GlobalSettings) => {
    set(KEYS.SETTINGS, s);
    addSystemLog('Configurações globais atualizadas.', 'SYSTEM_CONFIG');
};

export const getAds = (): AdCampaign[] => get(KEYS.ADS, DEFAULT_ADS);
export const saveAds = (ads: AdCampaign[]) => set(KEYS.ADS, ads);

export const getStories = (): Story[] => get(KEYS.STORIES, []);
export const addStory = (uId: string, item: any) => {
  const stories = getStories();
  const user = findUserById(uId);
  if (!user) return;
  let s = stories.find(x => x.userId === uId);
  if (!s) {
    s = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
    stories.push(s);
  }
  s.items.push({ ...item, id: `item-${Date.now()}`, timestamp: Date.now() });
  set(KEYS.STORIES, stories);
};

export const boostPost = (pId: string, uId: string, budget: number, days: number) => {
  const post = getPosts().find(p => p.id === pId);
  if (post && updateUserBalance(uId, -budget)) {
    post.isBoosted = true;
    post.boostExpires = Date.now() + (days * 86400000);
    updatePost(post);
    addSystemLog(`Post ${pId} impulsionado por ${uId}`, 'POST_BOOST');
    return true;
  }
  return false;
};

export const compressImage = (b: string) => Promise.resolve(b);
export const getAudioTracks = (): AudioTrack[] => get(KEYS.AUDIO, DEFAULT_AUDIO_TRACKS);
export const findAudioTrackById = (id: string) => getAudioTracks().find(t => t.id === id);
export const saveAffiliateLink = (uId: string, pId: string, link: string) => {};
export const addProductRating = (sId: string, r: number, c: string) => {
    const sales = getAffiliateSales();
    const sale = sales.find(x => x.id === sId);
    if(sale) { sale.isRated = true; set(KEYS.SALES, sales); return true; }
    return false;
};
export const getEvents = (): CyberEvent[] => get(KEYS.EVENTS, []);
export const createEvent = (e: CyberEvent) => set(KEYS.EVENTS, [e, ...getEvents()]);
export const toggleJoinEvent = (eId: string, uId: string) => {
  const evts = getEvents();
  const e = evts.find(x => x.id === eId);
  if (e) {
    if (e.attendees.includes(uId)) e.attendees = e.attendees.filter(x => x !== uId);
    else e.attendees.push(uId);
    set(KEYS.EVENTS, evts);
  }
};
export const pinPost = (pId: string, uId: string) => {
  const posts = getPosts();
  posts.forEach(p => { if(p.userId === uId) p.isPinned = p.id === pId; });
  savePosts(posts);
  return true;
};
export const unpinPost = (pId: string, uId: string) => {
  const posts = getPosts();
  const p = posts.find(x => x.id === pId && x.userId === uId);
  if (p) p.isPinned = false;
  savePosts(posts);
  return true;
};
export const indicatePostToUser = (pId: string, from: string, to: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === pId);
  if (post) {
    if (!post.indicatedUserIds) post.indicatedUserIds = [];
    if (post.indicatedUserIds.includes(to)) return false;
    post.indicatedUserIds.push(to);
    updatePost(post);
    createNotification({ type: NotificationType.INDICATION, recipientId: to, actorId: from, postId: post.id, timestamp: Date.now() });
    return true;
  }
  return false;
};

import React, { useState, useEffect, useCallback } from 'react';
import { User, CartItem, GlobalSettings } from './types';
import {
    getCurrentUserId,
    findUserById,
    saveCurrentUser,
    getNotificationsForUser,
    markNotificationsAsRead,
    getCart,
    addToCart,
    removeFromCart,
    updateCartItemQuantity,
    clearCart,
    deleteUser,
    getGlobalSettings
} from './services/storageService';
import Header from './components/Header';
import Footer from './components/Footer';
import AuthPage from './components/AuthPage';
import FeedPage from './components/FeedPage';
import ProfilePage from './components/ProfilePage';
import ChatPage from './components/ChatPage';
import AdCampaignPage from './components/AdCampaignPage';
import LiveStreamViewer from './components/LiveStreamViewer';
import { StorePage } from './components/StorePage';
import StoreManagerPage from './components/StoreManagerPage';
import CreatePost from './components/CreatePost';
import ReelsPage from './components/ReelsPage';
import SearchResultsPage from './components/SearchResultsPage';
import NotificationsPage from './components/NotificationsPage';
import CartModal from './components/CartModal';
import WalletModal from './components/WalletModal';
import ReportUserPage from './components/ReportUserPage';
import SettingsPage from './components/SettingsPage';
import AdminDashboard from './components/AdminDashboard';
import EventsPage from './components/EventsPage';
import PurchasesPage from './components/PurchasesPage';
import AffiliatesPage from './components/AffiliatesPage';
import Logo from './components/Logo';
import { WrenchScrewdriverIcon, BoltIcon, ShieldCheckIcon } from '@heroicons/react/24/solid';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'manage-store' | 'edit-post' | 'create-post' | 'reels-page' | 'search-results' | 'notifications' | 'report-user' | 'settings' | 'admin' | 'events' | 'purchases' | 'affiliates';

const App: React.FC = () => {
    const [darkMode, setDarkMode] = useState(() => localStorage.getItem('cyberphone_theme') === 'dark');

    const [currentUser, setCurrentUser] = useState<User | null>(() => {
        try {
            const userId = getCurrentUserId();
            if (!userId) return null;
            return findUserById(userId) || null;
        } catch (e) {
            return null;
        }
    });

    const [currentPage, setCurrentPage] = useState<Page>(() => {
        return currentUser ? 'feed' : 'auth';
    });

    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    const [cartItems, setCartItems] = useState<CartItem[]>(getCart());
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });

    // Tornando as configurações globais um estado reativo
    const [settings, setSettings] = useState<GlobalSettings>(() => getGlobalSettings());

    const toggleTheme = useCallback(() => {
        setDarkMode(prev => {
            const newVal = !prev;
            localStorage.setItem('cyberphone_theme', newVal ? 'dark' : 'light');
            return newVal;
        });
    }, []);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    const refreshCurrentUser = useCallback(() => {
        const userId = getCurrentUserId();
        // Também atualiza as configurações globais durante o refresh
        setSettings(getGlobalSettings());

        if (userId) {
            const user = findUserById(userId);
            if (user) {
                setCurrentUser(user);
                const notifications = getNotificationsForUser(user.id);
                setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
            } else {
                saveCurrentUser(null);
                setCurrentUser(null);
                setCurrentPage('auth');
            }
        } else {
            setCurrentUser(null);
            setUnreadNotificationsCount(0);
        }
    }, []);

    const refreshCart = useCallback(() => {
        setCartItems(getCart());
    }, []);

    useEffect(() => {
        refreshCurrentUser();
        refreshCart();
    }, [refreshCurrentUser, refreshCart]);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        setCurrentPage('feed');
    }, []);

    const handleLogout = useCallback(() => {
        setCurrentUser(null);
        saveCurrentUser(null);
        setCurrentPage('auth');
        clearCart();
        refreshCart();
    }, [refreshCart]);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
        }
        setCurrentPage(page);
        setPageParams(params);
        window.scrollTo(0, 0);
    }, [currentUser, refreshCurrentUser]);

    const handleAddToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
        addToCart(productId, quantity, selectedColor);
        refreshCart();
    };

    // BARREIRA DE MODO MANUTENÇÃO (Respeita o estado reativo)
    if (settings.maintenanceMode && !currentUser?.isAdmin) {
        return (
            <div className="min-h-screen bg-[#0a0c10] text-white flex flex-col items-center justify-center p-8 text-center animate-fade-in">
                <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-20 pointer-events-none"></div>
                <div className="relative z-10 space-y-8 max-w-lg">
                    <Logo size="xl" variant="white" className="mb-12 justify-center" />

                    <div className="relative inline-block">
                        <div className="absolute inset-0 bg-blue-600 rounded-full blur-[60px] opacity-20 animate-pulse"></div>
                        <div className="bg-white/5 border border-white/10 p-8 rounded-[3rem] shadow-2xl relative z-10 backdrop-blur-xl">
                            <WrenchScrewdriverIcon className="h-16 w-16 text-blue-500 mx-auto mb-6 animate-bounce" />
                            <h2 className="text-3xl font-black uppercase tracking-tighter mb-4">Sistema em Atualização</h2>
                            <p className="text-gray-400 font-medium text-sm leading-relaxed">
                                O protocolo Root está sendo otimizado para oferecer uma experiência superior. Nossos engenheiros estão trabalhando nos servidores.
                            </p>
                        </div>
                    </div>

                    <div className="flex items-center justify-center gap-6 pt-4">
                        <div className="flex items-center gap-2 px-4 py-2 bg-blue-600/10 border border-blue-500/20 rounded-xl">
                            <BoltIcon className="h-4 w-4 text-blue-500" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-blue-400">Status: Root Lock</span>
                        </div>
                        <div className="flex items-center gap-2 px-4 py-2 bg-green-600/10 border border-green-500/20 rounded-xl">
                            <ShieldCheckIcon className="h-4 w-4 text-green-500" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-green-400">Seguro</span>
                        </div>
                    </div>

                    <button 
                        onClick={() => window.location.reload()} 
                        className="text-gray-500 hover:text-white transition-colors text-[10px] font-black uppercase tracking-[0.3em]"
                    >
                        Tentar reconectar em breve
                    </button>
                </div>
            </div>
        );
    }

    if (currentPage === 'admin' && currentUser?.isAdmin) {
        return <AdminDashboard currentUser={currentUser} onNavigate={handleNavigate} onRefreshUser={refreshCurrentUser} />;
    }

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;

        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={toggleTheme} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={() => { deleteUser(currentUser.id); handleLogout(); }} />;
            case 'ads': return <AdCampaignPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'events': return <EventsPage currentUser={currentUser} />;
            case 'purchases': return <PurchasesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'live':
                return pageParams.postId 
                    ? <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />
                    : <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={handleAddToCart} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'manage-store': return <StoreManagerPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'create-post': return <CreatePost currentUser={currentUser} onPostCreated={() => handleNavigate('feed')} refreshUser={refreshCurrentUser} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query || ''} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'report-user': return <ReportUserPage currentUser={currentUser} targetUserId={pageParams.userId} onNavigate={handleNavigate} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300 w-full overflow-x-hidden">
            <Header currentUser={currentUser} onNavigate={handleNavigate} unreadNotificationsCount={unreadNotificationsCount} cartItemCount={cartItems.reduce((sum, item) => sum + item.quantity, 0)} onOpenCart={() => setIsCartModalOpen(true)} />
            <div className="flex flex-1 w-full overflow-x-hidden">
                {currentUser && <Footer currentUser={currentUser} onNavigate={handleNavigate} activePage={currentPage} onLogout={handleLogout} />}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[72px] md:pb-8 transition-all duration-300 w-full ${currentUser ? 'md:ml-64 px-0 md:px-8' : 'px-0'}`}>
                    <div className="max-w-7xl mx-auto w-full">{renderPage()}</div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={refreshCart} refreshUser={refreshCurrentUser} />
                <WalletModal isOpen={walletConfig.isOpen} mode={walletConfig.mode} onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })} currentUser={currentUser} refreshUser={refreshCurrentUser} />
              </>
            )}
        </div>
    );
};

export default App;

