import { DEFAULT_PROFILE_PIC } from '../constants';

type AdminTab = 'dashboard' | 'users' | 'moderation' | 'market' | 'finance' | 'config';

interface AdminDashboardProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  onRefreshUser: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser, onNavigate, onRefreshUser }) => {
  const [activeTab, setActiveTab] = useState<AdminTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [settings, setSettings] = useState<GlobalSettings>(() => getGlobalSettings());

  const refresh = () => {
    setRefreshKey(prev => prev + 1);
    setSettings(getGlobalSettings());
    onRefreshUser();
  };

  const data = useMemo(() => ({
    users: getUsers(),
    posts: getPosts(),
    products: getProducts(),
    ads: getAds().sort((a, b) => (b.budget || 0) - (a.budget || 0)),
    transactions: getTransactions().sort((a, b) => b.timestamp - a.timestamp),
    reports: getReports().sort((a, b) => b.timestamp - a.timestamp),
    logs: getSystemLogs().sort((a, b) => b.timestamp - a.timestamp),
    revenue: getPlatformRevenue()
  }), [refreshKey]);

  const filteredItems = useMemo(() => {
    const term = searchTerm.toLowerCase();
    if (activeTab === 'users') {
      return data.users.filter(u => `${u.firstName} ${u.lastName}`.toLowerCase().includes(term) || u.email.toLowerCase().includes(term));
    }
    if (activeTab === 'moderation') {
      return data.reports.filter(r => r.reason.toLowerCase().includes(term) || r.targetId.includes(term));
    }
    if (activeTab === 'market') {
      return data.products.filter(p => p.name.toLowerCase().includes(term));
    }
    return [];
  }, [data, searchTerm, activeTab]);

  // Handlers
  const handleToggleVerification = (user: User) => {
    adminUpdateUser({ ...user, isVerified: !user.isVerified });
    refresh();
  };

  const handleToggleSuspension = (user: User) => {
    adminUpdateUser({ ...user, isSuspended: !user.isSuspended });
    refresh();
  };

  const handleDeleteUser = (uId: string) => {
    if (confirm("REMOÇÃO PERMANENTE: Esta ação não pode ser desfeita. Confirmar?")) {
      deleteUser(uId);
      refresh();
    }
  };

  const handleUpdateBalance = (uId: string) => {
    const val = prompt("Ajustar saldo (USD):", "0");
    if (val && !isNaN(parseFloat(val))) {
      updateUserBalance(uId, parseFloat(val));
      refresh();
    }
  };

  const handleProcessReport = (reportId: string, status: 'RESOLVED' | 'DISMISSED') => {
    adminProcessReport(reportId, status, currentUser.id);
    refresh();
