                     </thead>
                     <tbody className="divide-y divide-white/[0.03]">
                        {filteredData.map((post: any) => (
                           <tr key={post.id} className="group hover:bg-white/[0.01]">
                              <td className="px-8 py-6">
                                 <div className="p-3 bg-white/5 rounded-xl inline-block" title={post.type}>
                                    {getPostIcon(post.type)}
                                 </div>
