                              <td className="px-8 py-6">
                                 <p className="text-xs font-black text-gray-100 uppercase mb-1">{post.authorName}</p>
                                 <p className="text-[10px] text-gray-500 truncate max-w-md italic">"{post.content || 'Mídia sem legenda'}"</p>
