                                 <button onClick={() => handleDeletePost(post.id)} className="p-4 bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white rounded-2xl transition-all shadow-xl"><TrashIcon className="h-5 w-5" /></button>
