                     </div>
                     <div className="flex justify-between items-end">
                        <div>
                           <p className="text-[24px] font-black text-white">{data.products.filter(p => p.storeId === store.id).length}</p>
                           <p className="text-[8px] font-black text-gray-500 uppercase tracking-widest">Produtos Ativos</p>
