               ))}
            </div>
         )}

         {/* PRODUTOS */}
         {activeTab === 'products' && (
            <div className="bg-[#12161f] rounded-[3rem] overflow-hidden border border-white/5 animate-fade-in shadow-2xl">
               <div className="overflow-x-auto">
                  <table className="w-full text-left border-collapse">
                     <thead className="bg-black/20">
                        <tr className="text-[9px] font-black uppercase tracking-[0.25em] text-gray-500">
                           <th className="px-8 py-6">Item</th>
                           <th className="px-8 py-6">Tipo</th>
                           <th className="px-8 py-6">Preço</th>
                           <th className="px-8 py-6 text-right">Status</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-white/[0.03]">
                        {filteredData.map((prod: any) => (
                           <tr key={prod.id} className="group hover:bg-white/[0.01]">
