  const sales = getAffiliateSales().map(s => s.id === id ? { ...s, status } : s);
  set(KEYS.SALES, sales);
};

export const processProductPurchase = (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  const allSales = getAffiliateSales();
  const settings = getGlobalSettings();

  for (const item of cartItems) {
    const product = findProductById(item.productId);
    if (!product) continue;
    const store = findStoreById(product.storeId);
    if (!store) continue;

    const netAmount = product.price * item.quantity;
    const platformFee = netAmount * settings.platformTax;
    const sellerRevenue = netAmount - platformFee;

    updateUserBalance(store.professorId, sellerRevenue);

    const newSale: AffiliateSale = {
      id: `sale-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
      productId: item.productId,
      buyerId,
      affiliateUserId: affiliateUserId || '',
      storeId: product.storeId,
      commissionEarned: 0,
      saleAmount: netAmount,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      shippingAddress,
      digitalContentUrl: product.digitalContentUrl
    };
    allSales.push(newSale);
  }
  set(KEYS.SALES, allSales);
  return true;
};

// --- UTILS ---
export const getCart = (): CartItem[] => get(KEYS.CART, []);
export const saveCart = (c: CartItem[]) => set(KEYS.CART, c);
export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
  if (existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) {
    cart = cart.filter(item => item.productId !== productId);
  } else {
    const item = cart.find(item => item.productId === productId);
    if (item) {
      item.quantity = quantity;
    }
  }
  saveCart(cart);
};

export const removeFromCart = (pId: string) => saveCart(getCart().filter(i => i.productId !== pId));
export const clearCart = () => set(KEYS.CART, []);

export const getNotificationsForUser = (uId: string) => get(KEYS.NOTIFICATIONS, [] as Notification[]).filter(n => n.recipientId === uId);
export const markNotificationsAsRead = (uId: string) => {
    const all = get(KEYS.NOTIFICATIONS, [] as Notification[]);
    set(KEYS.NOTIFICATIONS, all.map(n => n.recipientId === uId ? { ...n, isRead: true } : n));
};
export const createNotification = (n: Omit<Notification, 'id' | 'isRead'>) => {
    if (n.recipientId === n.actorId) return;
    const all = get(KEYS.NOTIFICATIONS, [] as Notification[]);
    set(KEYS.NOTIFICATIONS, [{ ...n, id: `notif-${Date.now()}`, isRead: false }, ...all]);
};

export const getChats = (): ChatConversation[] => get(KEYS.CHATS, []);
export const saveChats = (c: ChatConversation[]) => set(KEYS.CHATS, c);
export const getOrCreateConversation = (u1: string, u2: string): ChatConversation => {
  const chats = getChats();
  let chat = chats.find(c => c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, participants: [u1, u2], messages: [] };
    saveChats([...chats, chat]);
  }
  return chat;
};
export const sendMessage = (id: string, m: Message) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === id);
  if (chat) { chat.messages.push(m); saveChats(chats); }
};

export const toggleFollowUser = (cur: string, tar: string) => {
  const users = getUsers();
  const c = users.find(u => u.id === cur);
  const t = users.find(u => u.id === tar);
  if (c && t) {
    if (c.followedUsers.includes(tar)) {
      c.followedUsers = c.followedUsers.filter(x => x !== tar);
      t.followers = t.followers.filter(x => x !== cur);
    } else {
      c.followedUsers.push(tar);
      t.followers.push(cur);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: tar, actorId: cur, timestamp: Date.now() });
    }
    saveUsers(users);
  }
};

