export const getStories = (): Story[] => get(KEYS.STORIES, []);
export const addStory = (uId: string, item: any) => {
  const stories = getStories();
  const user = findUserById(uId);
  if (!user) return;
  let s = stories.find(x => x.userId === uId);
  if (!s) {
    s = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
    stories.push(s);
  }
  s.items.push({ ...item, id: `item-${Date.now()}`, timestamp: Date.now() });
  set(KEYS.STORIES, stories);
};

export const boostPost = (pId: string, uId: string, budget: number, days: number) => {
  const post = getPosts().find(p => p.id === pId);
  if (post && updateUserBalance(uId, -budget)) {
    post.isBoosted = true;
    post.boostExpires = Date.now() + (days * 86400000);
    updatePost(post);
    return true;
  }
  return false;
};

export const compressImage = (b: string) => Promise.resolve(b);
export const getAudioTracks = (): AudioTrack[] => get(KEYS.AUDIO, DEFAULT_AUDIO_TRACKS);
export const findAudioTrackById = (id: string) => getAudioTracks().find(t => t.id === id);
export const saveAffiliateLink = (uId: string, pId: string, link: string) => {};
export const addProductRating = (sId: string, r: number, c: string) => {
    const sales = getAffiliateSales();
    const sale = sales.find(x => x.id === sId);
    if(sale) { sale.isRated = true; set(KEYS.SALES, sales); return true; }
    return false;
};
export const getEvents = (): CyberEvent[] => get(KEYS.EVENTS, []);
export const createEvent = (e: CyberEvent) => set(KEYS.EVENTS, [e, ...getEvents()]);
export const toggleJoinEvent = (eId: string, uId: string) => {
  const evts = getEvents();
  const e = evts.find(x => x.id === eId);
  if (e) {
    if (e.attendees.includes(uId)) e.attendees = e.attendees.filter(x => x !== uId);
    else e.attendees.push(uId);
    set(KEYS.EVENTS, evts);
  }
};
export const pinPost = (pId: string, uId: string) => {
  const posts = getPosts();
  posts.forEach(p => { if(p.userId === uId) p.isPinned = p.id === pId; });
  savePosts(posts);
  return true;
};
export const unpinPost = (pId: string, uId: string) => {
  const posts = getPosts();
  const p = posts.find(x => x.id === pId && x.userId === uId);
  if (p) p.isPinned = false;
  savePosts(posts);
  return true;
};
export const indicatePostToUser = (pId: string, from: string, to: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === pId);
  if (post) {
    if (!post.indicatedUserIds) post.indicatedUserIds = [];
    if (post.indicatedUserIds.includes(to)) return false;
    post.indicatedUserIds.push(to);
    updatePost(post);
    createNotification({ type: NotificationType.INDICATION, recipientId: to, actorId: from, postId: post.id, timestamp: Date.now() });
    return true;
  }
  return false;
};

