                                 <p className="text-[10px] font-black text-gray-400">#{t.id.slice(-8)}</p>
                                 <p className="text-[9px] text-gray-600 font-bold">{new Date(t.timestamp).toLocaleTimeString()}</p>
                              </td>
                              <td className="px-8 py-6 text-[10px] font-black text-blue-500">{t.userId}</td>
