  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      onNavigate('search-results', { query: searchQuery.trim() });
      setSearchQuery(''); 
      setIsMobileSearchOpen(false);
    }
  };

  useEffect(() => {
    if (isMobileSearchOpen || isMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
  }, [isMobileSearchOpen, isMenuOpen]);

  const navSections = [
    { title: 'Explorar', items: [
      { name: 'Feed Social', page: 'feed', Icon: HomeIcon },
      { name: 'Reels IA', page: 'reels-page', Icon: FilmIcon },
      { name: 'Eventos', page: 'events', Icon: CalendarDaysIcon },
    ]},
    { title: 'Central de Vendas', items: [
      { name: 'Marketplace', page: 'store', Icon: BuildingStorefrontIcon },
      { name: 'Minhas Compras', page: 'purchases', Icon: ShoppingBagIcon },
      { name: 'Afiliados Pro', page: 'affiliates', Icon: PresentationChartLineIcon },
