                    <img src={currentUser?.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-xl object-cover border-2 border-white dark:border-white/10" />
                    <div className="min-w-0">
                        <p className="font-black text-sm dark:text-white uppercase truncate">{currentUser?.firstName} {currentUser?.lastName}</p>
                        <p className="text-[10px] font-bold text-blue-600 uppercase tracking-widest">{currentUser?.userType === UserType.CREATOR ? 'Professor' : 'Membro'}</p>
                    </div>
                </div>

                <nav className="flex-1 overflow-y-auto p-4 space-y-8 custom-scrollbar">
                    {navSections.map((section) => (
                        <div key={section.title}>
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4 ml-2">{section.title}</p>
                            <div className="space-y-1">
                                {section.items.map((item) => (
                                    <button 
                                        key={item.page}
                                        onClick={() => handleMenuNavigate(item.page)}
                                        className="w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl text-gray-600 dark:text-gray-400 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-white/5 transition-all group"
                                    >
                                        <item.Icon className="h-5 w-5 group-hover:scale-110 transition-transform" />
                                        <span className="font-black text-[10px] uppercase tracking-widest">{item.name}</span>
                                    </button>
                                ))}
                            </div>
                        </div>
                    ))}
                </nav>

                <div className="p-6 border-t border-gray-100 dark:border-white/5 mb-4">
                    <button 
                        onClick={() => { window.location.reload(); }} 
                        className="w-full flex items-center gap-4 px-4 py-4 rounded-2xl text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 transition-all font-black text-[10px] uppercase tracking-widest"
                    >
                        <ArrowRightOnRectangleIcon className="h-5 w-5" />
                        Desconectar
                    </button>
                </div>
            </div>
        </div>
      )}

      {isMobileSearchOpen && (
        <div className="fixed inset-0 z-[100] bg-white dark:bg-darkbg animate-fade-in lg:hidden">
          <div className="flex items-center p-4 border-b border-gray-100 dark:border-white/5">
            <button 
              onClick={() => setIsMobileSearchOpen(false)}
              className="p-2 text-gray-500 dark:text-gray-400 mr-2"
            >
              <ArrowLeftIcon className="h-7 w-7" />
            </button>
            <form onSubmit={handleSearchSubmit} className="flex-1">
              <input
                autoFocus
                type="text"
                placeholder="Buscar na CyBerPhone..."
                className="w-full bg-transparent text-lg font-bold outline-none dark:text-white"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </form>
          </div>

          <div className="p-6">
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-4">Populares agora</p>
            <div className="flex flex-wrap gap-2">
              {['Educação', 'E-books', 'Curso Master', 'Dropshipping', 'Mentoria'].map(tag => (
                <button 
                  key={tag}
                  onClick={() => {
                    setSearchQuery(tag);
                    onNavigate('search-results', { query: tag });
                    setIsMobileSearchOpen(false);
                  }}
                  className="px-4 py-2 bg-gray-50 dark:bg-white/5 rounded-xl text-[10px] font-bold text-gray-600 dark:text-gray-300 border border-gray-100 dark:border-white/5"
                >
                  {tag}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes slide-right {
            from { transform: translateX(-100%); }
            to { transform: translateX(0); }
        }
        .animate-slide-right { animation: slide-right 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fade-in 0.2s ease-out; }
      `}</style>
    </>
  );
};

