import React, { useState, useMemo } from 'react';
import { 
  User, Post, Product, AdCampaign, Transaction, 
  ContentReport, OrderStatus, UserType, GlobalSettings, TransactionType, Store, PostType
} from '../types';
import { 
  getUsers, getPlatformRevenue, getPosts, getProducts, getAds,
  getTransactions, getSystemLogs, getReports, getGlobalSettings,
  adminUpdateUser, adminDeletePost, adminProcessReport, adminDeleteProduct,
  updateGlobalSettings, updateUserBalance, getStores, deleteUser
} from '../services/storageService';
import { 
  BanknotesIcon, UserGroupIcon, ShieldCheckIcon, TrashIcon, 
  CheckBadgeIcon, ChartPieIcon, MagnifyingGlassIcon, CurrencyDollarIcon, 
  MegaphoneIcon, NoSymbolIcon, 
  Cog6ToothIcon, GlobeAltIcon, 
  CommandLineIcon, ArrowPathIcon, 
  ClockIcon, Bars3Icon, XMarkIcon,
  ArrowLeftOnRectangleIcon,
  ShieldExclamationIcon,
  ShoppingBagIcon,
  ArrowTrendingUpIcon,
  ExclamationTriangleIcon,
  DocumentMagnifyingGlassIcon,
  ReceiptPercentIcon,
  WrenchScrewdriverIcon,
  NewspaperIcon,
  BuildingStorefrontIcon,
  TagIcon,
  VideoCameraIcon,
  PhotoIcon,
  DocumentTextIcon
} from '@heroicons/react/24/solid';
import Logo from './Logo';
import { DEFAULT_PROFILE_PIC } from '../constants';

type AdminTab = 'dashboard' | 'users' | 'posts' | 'stores' | 'products' | 'moderation' | 'finance' | 'config';

interface AdminDashboardProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  onRefreshUser: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser, onNavigate, onRefreshUser }) => {
  const [activeTab, setActiveTab] = useState<AdminTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [settings, setSettings] = useState<GlobalSettings>(() => getGlobalSettings());

  const refresh = () => {
    setRefreshKey(prev => prev + 1);
    setSettings(getGlobalSettings());
    onRefreshUser();
  };

  const data = useMemo(() => ({
    users: getUsers(),
    posts: getPosts(),
    products: getProducts(),
    stores: getStores(),
    ads: getAds().sort((a, b) => (b.budget || 0) - (a.budget || 0)),
    transactions: getTransactions().sort((a, b) => b.timestamp - a.timestamp),
    reports: getReports().sort((a, b) => b.timestamp - a.timestamp),
    logs: getSystemLogs().sort((a, b) => b.timestamp - a.timestamp),
    revenue: getPlatformRevenue()
  }), [refreshKey]);

  const filteredData = useMemo(() => {
    const term = searchTerm.toLowerCase();
    switch (activeTab) {
      case 'users':
        return data.users.filter(u => `${u.firstName} ${u.lastName}`.toLowerCase().includes(term) || u.email.toLowerCase().includes(term));
      case 'posts':
        return data.posts.filter(p => p.authorName.toLowerCase().includes(term) || (p.content?.toLowerCase().includes(term)));
      case 'products':
        return data.products.filter(p => p.name.toLowerCase().includes(term));
      case 'stores':
        return data.stores.filter(s => s.name.toLowerCase().includes(term));
      case 'moderation':
        return data.reports.filter(r => r.reason.toLowerCase().includes(term) || r.targetId.includes(term));
      default:
        return [];
    }
  }, [data, searchTerm, activeTab]);

  const handleToggleVerification = (user: User) => {
    adminUpdateUser({ ...user, isVerified: !user.isVerified });
    refresh();
  };

  const handleToggleSuspension = (user: User) => {
    adminUpdateUser({ ...user, isSuspended: !user.isSuspended });
    refresh();
  };

  const handleDeleteUser = (uId: string) => {
    if (confirm("REMOÇÃO PERMANENTE: Confirmar?")) {
      deleteUser(uId);
      refresh();
    }
  };

  const handleUpdateBalance = (uId: string) => {
    const val = prompt("Ajustar saldo (USD):", "0");
    if (val && !isNaN(parseFloat(val))) {
      updateUserBalance(uId, parseFloat(val));
      refresh();
    }
  };

  const handleDeletePost = (pId: string) => {
    if (confirm("Remover esta publicação?")) {
      adminDeletePost(pId);
      refresh();
    }
  };

  const handleDeleteProduct = (pId: string) => {
    if (confirm("Banir este produto?")) {
      adminDeleteProduct(pId);
      refresh();
    }
  };

  const handleProcessReport = (reportId: string, status: 'RESOLVED' | 'DISMISSED') => {
    adminProcessReport(reportId, status, currentUser.id);
    refresh();
  };

  const handleSaveSettings = (e: React.FormEvent) => {
    e.preventDefault();
    updateGlobalSettings(settings);
    refresh();
    alert("Parâmetros Root salvos.");
  };

  const SidebarItem = ({ id, icon: Icon, label }: { id: AdminTab, icon: any, label: string }) => (
    <button 
      onClick={() => { setActiveTab(id); setSearchTerm(''); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 ${activeTab === id ? 'bg-blue-600 text-white shadow-lg scale-105 rounded-2xl' : 'text-gray-400 hover:text-white'}`}
    >
      <Icon className="h-5 w-5" />
      <span className="font-black text-[10px] uppercase tracking-widest">{label}</span>
    </button>
  );

  const getPostIcon = (type: PostType) => {
    switch(type) {
      case PostType.IMAGE: return <PhotoIcon className="h-4 w-4 text-purple-400" />;
      case PostType.LIVE: return <VideoCameraIcon className="h-4 w-4 text-red-500" />;
      default: return <DocumentTextIcon className="h-4 w-4 text-blue-400" />;
    }
  };

  return (
    <div className="fixed inset-0 bg-[#080a0f] text-white flex flex-col md:flex-row font-sans z-[9999] overflow-hidden">

      {/* Mobile Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[505] md:hidden"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* SIDEBAR */}
      <aside className={`fixed inset-y-0 left-0 z-[510] w-72 bg-[#0d1117] border-r border-white/5 flex flex-col p-6 transition-transform duration-300 md:sticky md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
         <div className="flex items-center justify-between mb-12">
            <Logo size="md" variant="white" className="cursor-pointer" onClick={() => onNavigate('feed')} />
            <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-3 bg-white/5 rounded-xl text-gray-400 hover:text-white hover:bg-white/10 transition-all"><XMarkIcon className="h-7 w-7" /></button>
         </div>
         <nav className="space-y-1 flex-1 overflow-y-auto no-scrollbar">
            <SidebarItem id="dashboard" icon={ChartPieIcon} label="Monitoramento" />
            <SidebarItem id="users" icon={UserGroupIcon} label="Membros" />
            <SidebarItem id="posts" icon={NewspaperIcon} label="Publicações" />
            <SidebarItem id="stores" icon={BuildingStorefrontIcon} label="Lojas" />
            <SidebarItem id="products" icon={ShoppingBagIcon} label="Produtos" />
            <SidebarItem id="moderation" icon={ShieldExclamationIcon} label="Denúncias" />
            <SidebarItem id="finance" icon={BanknotesIcon} label="Tesouraria" />
            <SidebarItem id="config" icon={WrenchScrewdriverIcon} label="Config Root" />
         </nav>
         <div className="mt-10 pt-10 border-t border-white/5">
            <button onClick={() => onNavigate('feed')} className="w-full flex items-center gap-4 px-6 py-4 text-gray-400 hover:text-white transition-all bg-white/5 rounded-2xl active:scale-95">
               <ArrowLeftOnRectangleIcon className="h-5 w-5" />
               <span className="font-black text-[10px] uppercase tracking-widest">Sair do Root</span>
            </button>
         </div>
      </aside>

      {/* MAIN CONTENT */}
      <main className="flex-1 p-4 md:p-12 overflow-y-auto h-screen custom-scrollbar relative bg-[#080a0f]">
         <header className="flex flex-col lg:flex-row lg:items-center justify-between mb-12 gap-6">
            <div className="flex items-center gap-5">
               {/* BOTÃO HAMBÚRGUER ADMIN */}
               <button 
                onClick={() => setIsSidebarOpen(true)}
                className="md:hidden p-4 bg-white/5 border border-white/10 rounded-[1.4rem] text-gray-400 active:scale-90 transition-all shadow-xl"
               >
                 <Bars3Icon className="h-8 w-8" />
               </button>
               <div>
                  <h2 className="text-3xl md:text-4xl font-black uppercase tracking-tighter">{activeTab}</h2>
                  <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mt-2 flex items-center gap-2">Protocolo Root Ativo <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_10px_#22c55e]"></span></p>
               </div>
            </div>

            <div className="flex items-center gap-4 w-full lg:w-auto">
               <div className="relative flex-1 lg:w-80">
                  <MagnifyingGlassIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" />
                  <input type="text" placeholder="Filtrar dados..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="bg-white/5 border border-white/10 rounded-2xl pl-12 pr-6 py-4 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-600 w-full transition-all"/>
               </div>
               <button onClick={refresh} className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl transition-all border border-white/5 shadow-xl"><ArrowPathIcon className="h-6 w-6 text-gray-400" /></button>
            </div>
         </header>

         {activeTab === 'dashboard' && (
           <div className="space-y-12 animate-fade-in">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                 {[
                   { label: 'Receita Total', val: `$${data.revenue.toFixed(2)}`, color: 'text-green-500' },
                   { label: 'Usuários Ativos', val: data.users.length, color: 'text-blue-500' },
                   { label: 'Publicações', val: data.posts.length, color: 'text-purple-500' },
                   { label: 'Vendas Brutas', val: data.transactions.length, color: 'text-orange-500' }
                 ].map(s => (
                   <div key={s.label} className="bg-[#12161f] p-8 rounded-[2.5rem] border border-white/5 shadow-2xl overflow-hidden group">
                      <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">{s.label}</p>
                      <p className={`text-4xl font-black tracking-tighter ${s.color}`}>{s.val}</p>
                   </div>
                 ))}
              </div>
              <div className="bg-[#12161f] p-10 rounded-[3rem] border border-white/5 shadow-inner">
                 <h3 className="text-[10px] font-black uppercase tracking-[0.3em] mb-10 flex items-center gap-3 text-blue-500">
                    <CommandLineIcon className="h-5 w-5" /> Auditoria Root (Últimos 10)
                 </h3>
                 <div className="space-y-4">
                    {data.logs.slice(0, 10).map(log => (
                        <div key={log.id} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
                            <div className="flex items-center gap-4">
                                <div className="p-2 bg-blue-600/20 text-blue-400 rounded-xl font-black text-[8px] uppercase">{log.action}</div>
                                <p className="text-xs font-medium text-gray-300">{log.details}</p>
                            </div>
                            <span className="text-[9px] font-bold text-gray-500">{new Date(log.timestamp).toLocaleTimeString()}</span>
                        </div>
                    ))}
                 </div>
              </div>
           </div>
         )}

         {activeTab === 'users' && (
            <div className="bg-[#12161f] rounded-[3rem] overflow-hidden border border-white/5 shadow-2xl animate-fade-in">
               <div className="overflow-x-auto">
                  <table className="w-full text-left border-collapse">
                     <thead className="bg-black/20">
                        <tr className="text-[9px] font-black uppercase tracking-[0.25em] text-gray-500">
                           <th className="px-8 py-6">Membro</th>
                           <th className="px-8 py-6">Saldo USD</th>
                           <th className="px-8 py-6 text-right">Controles</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-white/[0.03]">
                        {filteredData.map((user: any) => (
                           <tr key={user.id} className={`group hover:bg-white/[0.02] ${user.isSuspended ? 'opacity-30' : ''}`}>
                              <td className="px-8 py-6">
                                 <div className="flex items-center gap-4 min-w-[200px]">
                                    <img src={user.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-[1.1rem] object-cover border-2 border-white/10 shadow-lg" />
                                    <div>
                                       <p className="font-black text-sm text-gray-100 uppercase tracking-tighter truncate">{user.firstName}</p>
                                       <p className="text-[8px] font-black text-blue-500/60 uppercase tracking-widest">{user.email}</p>
                                    </div>
                                 </div>
                              </td>
                              <td className="px-8 py-6">
                                 <button onClick={() => handleUpdateBalance(user.id)} className="bg-[#10b981]/5 border border-[#10b981]/20 rounded-2xl px-5 py-3 transition-all flex flex-col items-center">
                                    <p className="font-black text-lg text-[#10b981]">${(user.balance || 0).toFixed(2)}</p>
                                    <p className="text-[7px] font-black uppercase text-[#10b981]/60">Ajustar Saldo</p>
                                 </button>
                              </td>
                              <td className="px-8 py-6 text-right">
