              className="w-8 h-8 md:w-10 md:h-10 rounded-xl object-cover cursor-pointer border-2 border-transparent hover:border-blue-600 transition-all shadow-sm"
              onClick={() => onNavigate('profile')}
            />
          </div>
        ) : (
          <button onClick={() => onNavigate('auth')} className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all">Entrar</button>
        )}
      </header>

      {isMobileSearchOpen && (
