interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [documentId, setDocumentId] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');
  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');
  const [profilePicBase64, setProfilePicBase64] = useState<string>(DEFAULT_PROFILE_PIC);
  const [verificationFile, setVerificationFile] = useState<File | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const profilePicInputRef = useRef<HTMLInputElement>(null);

  const inputClasses = "w-full p-3.5 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl border-2 border-transparent focus:border-blue-500 focus:bg-white dark:focus:bg-darkcard outline-none font-bold text-sm transition-all shadow-inner placeholder-gray-400";

  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let input = e.target.value;
    const isInternational = input.startsWith('+');

    // Remove tudo que não for dígito, exceto o + inicial se existir
    let digits = input.replace(/[^\d]/g, '');

    // Limita a 15 dígitos (padrão máximo internacional E.164)
    if (digits.length > 15) digits = digits.slice(0, 15);

    let formatted = '';
    if (isInternational) {
      formatted = '+' + digits;
      // Formatação genérica internacional: +XX XX XXXXXXXX
      if (digits.length > 2) {
        formatted = `+${digits.slice(0, 2)} ${digits.slice(2, 4)} ${digits.slice(4)}`;
      }
    } else {
      // Formatação padrão Brasil se não começar com +
      if (digits.length > 10) {
        formatted = `(${digits.slice(0, 2)}) ${digits.slice(2, 7)}-${digits.slice(7, 11)}`;
      } else if (digits.length > 6) {
        formatted = `(${digits.slice(0, 2)}) ${digits.slice(2, 6)}-${digits.slice(6)}`;
      } else if (digits.length > 2) {
        formatted = `(${digits.slice(0, 2)}) ${digits.slice(2)}`;
      } else if (digits.length > 0) {
        formatted = `(${digits}`;
      }
    }

    setPhone(formatted.trim());
  };

  const handleProfilePicChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        setError('Por favor, selecione uma imagem válida.');
        return;
      }
      if (file.size > 2 * 1024 * 1024) {
        setError('A imagem é muito grande. Escolha uma foto menor que 2MB.');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setProfilePicBase64(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        setError('O comprovante deve ser um arquivo PDF.');
        setVerificationFile(null);
        return;
      }
      setVerificationFile(file);
      setError('');
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !phone || !documentId || !birthDate || !password) {
      setError('Todos os campos obrigatórios devem ser preenchidos.');
      return;
    }

    if (userType === UserType.CREATOR && (!credentials || !verificationFile)) {
      setError('Profissionais precisam de cargo e comprovante.');
      return;
    }

    setLoading(true);
    try {
      const newUser = await registerUser({
        userType,
        firstName,
        lastName,
        email,
        phone,
        documentId,
        birthDate: new Date(birthDate).getTime(),
        password,
        profilePicture: profilePicBase64,
        credentials: userType === UserType.CREATOR ? credentials : undefined,
        bio: bio || undefined,
        verificationFileUrl: verificationFile ? verificationFile.name : undefined
      });
      saveCurrentUser(newUser.id);
      onLoginSuccess(newUser);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Erro ao realizar cadastro. Tente uma foto de perfil menor.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!email || !password) {
      setError('Email e senha são obrigatórios.');
      return;
    }
    setLoading(true);
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError('Credenciais inválidas.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4 font-sans">
      <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10 relative overflow-hidden">

        <div className="mb-6 flex flex-col items-center">
          <Logo size="lg" className="mb-1" />
          <p className="text-center text-gray-400 font-bold uppercase text-[8px] tracking-[0.25em] opacity-80">
            {isRegister ? 'Conectando Talentos' : 'Bem-vindo ao CyBerPhone'}
          </p>
        </div>

        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 text-red-600 p-4 rounded-2xl text-[10px] font-black mb-6 text-center animate-pulse uppercase tracking-widest leading-tight">
            {error}
          </div>
        )}

        {isRegister && (
          <div className="flex bg-gray-50 dark:bg-white/5 p-1 rounded-2xl mb-6">
            <button type="button" onClick={() => setUserType(UserType.STANDARD)} className={`flex-1 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${userType === UserType.STANDARD ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400'}`}>Normal</button>
            <button type="button" onClick={() => setUserType(UserType.CREATOR)} className={`flex-1 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${userType === UserType.CREATOR ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400'}`}>Profissional</button>
          </div>
        )}

        <form onSubmit={isRegister ? handleRegister : handleLogin} className="space-y-4">
          {isRegister && (
            <div className="flex flex-col items-center mb-4">
              <div onClick={() => profilePicInputRef.current?.click()} className="relative group cursor-pointer">
                <div className="w-20 h-20 rounded-[1.8rem] overflow-hidden border-4 border-gray-50 dark:border-white/10 shadow-xl transition-all group-hover:scale-105 group-hover:border-blue-500">
                  <img src={profilePicBase64} className="w-full h-full object-cover" alt="Preview" />
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <CameraIcon className="h-6 w-6 text-white" />
                  </div>
                </div>
                <div className="absolute -bottom-1 -right-1 bg-blue-600 text-white p-1.5 rounded-lg shadow-lg border-2 border-white dark:border-darkcard">
                  <PlusIcon className="h-2.5 w-2.5 stroke-[4]" />
                </div>
                <input type="file" ref={profilePicInputRef} onChange={handleProfilePicChange} accept="image/*" className="hidden" />
              </div>
              <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mt-2">Foto de Perfil</p>
            </div>
          )}

          {isRegister && (
            <>
              <div className="grid grid-cols-2 gap-2.5">
                <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClasses} />
                <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClasses} />
              </div>
              <div className="space-y-1">
