import React from 'react';
import { User, UserType } from '../types';
import { 
    HomeIcon, 
    ChatBubbleLeftRightIcon, 
    UserCircleIcon, 
    BuildingStorefrontIcon, 
    FilmIcon,
    ArrowRightOnRectangleIcon,
    Cog6ToothIcon,
    MegaphoneIcon,
    CalendarDaysIcon,
    ShoppingBagIcon,
    PresentationChartLineIcon,
    RocketLaunchIcon,
    ShieldCheckIcon,
    XMarkIcon
} from '@heroicons/react/24/outline';
import { 
    HomeIcon as HomeIconSolid, 
    ChatBubbleLeftRightIcon as ChatIconSolid, 
    UserCircleIcon as UserIconSolid, 
    BuildingStorefrontIcon as StoreIconSolid, 
    FilmIcon as FilmIconSolid,
    Cog6ToothIcon as CogIconSolid,
    MegaphoneIcon as MegaphoneIconSolid,
    CalendarDaysIcon as CalendarIconSolid,
    ShoppingBagIcon as ShoppingBagIconSolid,
    PresentationChartLineIcon as ChartIconSolid,
    RocketLaunchIcon as RocketIconSolid,
    ShieldCheckIcon as ShieldIconSolid
} from '@heroicons/react/24/solid';
import Logo from './Logo';

interface FooterProps {
  currentUser: User | null;
  onNavigate: (page: any) => void;
  activePage: string;
  onLogout: () => void;
  isMenuOpen: boolean;
  onCloseMenu: () => void;
}

const MOBILE_BOTTOM_PAGES = ['feed', 'reels-page', 'chat', 'store', 'profile'];

const Footer: React.FC<FooterProps> = ({ currentUser, onNavigate, activePage, onLogout, isMenuOpen, onCloseMenu }) => {
  if (!currentUser) return null;

  const isProfessional = currentUser.userType === UserType.CREATOR || currentUser.isAdmin;

  const navSections = [
    { section: 'EXPLORAR', items: [
      { name: 'Feed Social', page: 'feed', Icon: HomeIcon, SolidIcon: HomeIconSolid },
      { name: 'Reels IA', page: 'reels-page', Icon: FilmIcon, SolidIcon: FilmIconSolid },
      { name: 'Eventos', page: 'events', Icon: CalendarDaysIcon, SolidIcon: CalendarIconSolid },
    ]},
    { section: 'CONEXÕES', items: [
      { name: 'Marketplace', page: 'store', Icon: BuildingStorefrontIcon, SolidIcon: StoreIconSolid },
      { name: 'Minhas Compras', page: 'purchases', Icon: ShoppingBagIcon, SolidIcon: ShoppingBagIconSolid },
      { name: 'Afiliados Pro', page: 'affiliates', Icon: PresentationChartLineIcon, SolidIcon: ChartIconSolid },
    ]},
    { section: 'HUB PROFISSIONAL', items: [
      { name: 'Impulsionar (Ads)', page: 'ads', Icon: MegaphoneIcon, SolidIcon: MegaphoneIconSolid },
      ...(isProfessional ? [
        { name: 'Gestão de Negócio', page: 'manage-store', Icon: RocketLaunchIcon, SolidIcon: RocketIconSolid }
      ] : []),
    ]},
    { section: 'CONTA', items: [
      { name: 'Mensagens', page: 'chat', Icon: ChatBubbleLeftRightIcon, SolidIcon: ChatIconSolid },
      { name: 'Meu Perfil', page: 'profile', Icon: UserCircleIcon, SolidIcon: UserIconSolid },
      { name: 'Ajustes', page: 'settings', Icon: Cog6ToothIcon, SolidIcon: CogIconSolid },
    ]},
    ...(currentUser.isAdmin ? [{
      section: 'ADMINISTRAÇÃO',
      items: [{ name: 'Painel Root', page: 'admin', Icon: ShieldCheckIcon, SolidIcon: ShieldIconSolid }]
    }] : [])
  ];

  const mobileBottomItems = [
    { page: 'feed', Icon: HomeIcon, Solid: HomeIconSolid },
    { page: 'reels-page', Icon: FilmIcon, Solid: FilmIconSolid },
    { page: 'chat', Icon: ChatBubbleLeftRightIcon, Solid: ChatIconSolid },
    { page: 'store', Icon: BuildingStorefrontIcon, Solid: StoreIconSolid },
    { page: 'profile', Icon: UserCircleIcon, Solid: UserIconSolid }
  ];

  const renderNavContent = (isMobileDrawer: boolean = false) => (
    <div className="space-y-8 flex-grow py-2">
      {navSections.map((section) => {
        const filteredItems = isMobileDrawer 
          ? section.items.filter(item => !MOBILE_BOTTOM_PAGES.includes(item.page))
          : section.items;

        if (filteredItems.length === 0) return null;

        return (
          <div key={section.section}>
