  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const reelInputRef = useRef<HTMLInputElement>(null);
  const isEditing = !!postId;
  const isProfessional = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    if (postId) {
      const posts = getPosts();
      const postToEdit = posts.find(p => p.id === postId);
      if (postToEdit) {
        setPostType(postToEdit.type);
        setContent(postToEdit.content || '');
        setImageUrl(postToEdit.imageUrl || '');
        setFontFamily(postToEdit.fontFamily || 'font-sans');
        setTextColor(postToEdit.textColor || '#000000');
        setFontSize(postToEdit.fontSize || '18px');
        setBackgroundColor(postToEdit.backgroundColor || 'transparent');

        if (postToEdit.type === PostType.REEL && postToEdit.reel) {
          setReelUrl(postToEdit.reel.videoUrl);
          setContent(postToEdit.reel.description);
        }
        if (postToEdit.type === PostType.LIVE && postToEdit.liveStream) {
          setLiveTitle(postToEdit.liveStream.title);
          setLiveDescription(postToEdit.liveStream.description);
          setIsLivePaid(postToEdit.liveStream.isPaid);
          setLivePrice(postToEdit.liveStream.price?.toString() || '0');
        }
        setIsExpanded(true);
      }
    }
  }, [postId]);

  const resetState = () => {
    setContent(''); setImageUrl(''); setReelUrl(''); setLiveTitle(''); setLiveDescription('');
    setIsLivePaid(false); setLivePrice('5.00'); setBackgroundColor('transparent');
    setTextColor('#000000'); setFontFamily('font-sans'); setFontSize('18px');
  };

  const handleClose = () => {
    if (onCancel) onCancel();
    else if (isEditing) onPostCreated();
    else { setIsExpanded(false); resetState(); }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const postData: Post = {
        id: isEditing ? postId! : `post-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: postType,
        timestamp: isEditing ? (getPosts().find(p => p.id === postId)?.timestamp || Date.now()) : Date.now(),
        content: (postType === PostType.TEXT || postType === PostType.IMAGE) ? content : undefined,
        imageUrl: postType === PostType.IMAGE ? imageUrl : undefined,
        fontFamily: postType === PostType.TEXT ? fontFamily : undefined,
        textColor: postType === PostType.TEXT ? textColor : undefined,
        fontSize: postType === PostType.TEXT ? fontSize : undefined,
        backgroundColor: postType === PostType.TEXT ? backgroundColor : undefined,
        reel: postType === PostType.REEL ? { videoUrl: reelUrl, description: content || 'Confira! 🚀' } : undefined,
        liveStream: postType === PostType.LIVE ? { title: liveTitle, description: liveDescription, isPaid: isLivePaid, price: isLivePaid ? parseFloat(livePrice) : 0 } : undefined,
        likes: isEditing ? (getPosts().find(p => p.id === postId)?.likes || []) : [],
        comments: isEditing ? (getPosts().find(p => p.id === postId)?.comments || []) : [],
        shares: isEditing ? (getPosts().find(p => p.id === postId)?.shares || []) : [],
        saves: isEditing ? (getPosts().find(p => p.id === postId)?.saves || []) : [],
        indicatedUserIds: isEditing ? (getPosts().find(p => p.id === postId)?.indicatedUserIds || []) : [],
      };
      if (isEditing) updatePost(postData);
      else addPost(postData);
      resetState();
      onPostCreated();
      if (!isEditing && !onCancel) setIsExpanded(false);
    } catch (err) { alert('Erro ao salvar.'); }
    finally { setLoading(false); }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-sm p-5 md:p-6 border border-gray-100 dark:border-white/10 flex flex-col gap-5">
         <div className="flex items-start gap-4">
