                              <button onClick={() => handleProcessReport(rep.id, 'DISMISSED')} className="bg-white/5 text-gray-400 px-6 py-3 rounded-2xl text-[10px] font-black uppercase border border-white/10 active:scale-95 transition-all">Descartar</button>
