               <div className="overflow-x-auto">
                  <table className="w-full text-left border-collapse">
                     <thead>
                        <tr className="text-[9px] font-black uppercase text-gray-500 border-b border-white/5">
                           <th className="px-8 py-6">ID / Data</th>
                           <th className="px-8 py-6">Usuário</th>
                           <th className="px-8 py-6 text-right">Valor</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-white/[0.03]">
                        {data.transactions.slice(0, 50).map(t => (
                           <tr key={t.id} className="hover:bg-white/[0.01]">
                              <td className="px-8 py-6">
                                 <p className="text-[10px] font-black text-gray-400">#{t.id.slice(-8)}</p>
                                 <p className="text-[9px] text-gray-600 font-bold">{new Date(t.timestamp).toLocaleTimeString()}</p>
                              </td>
                              <td className="px-8 py-6 text-[10px] font-black text-blue-500">{t.userId}</td>
                              <td className={`px-8 py-6 text-right font-mono font-black ${t.amount > 0 ? 'text-green-500' : 'text-red-500'}`}>
                                 {t.amount > 0 ? '+' : ''}${t.amount.toFixed(2)}
                              </td>
