                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
         )}

         {activeTab === 'config' && (
            <div className="max-w-3xl animate-fade-in">
               <div className="bg-[#12161f] p-10 rounded-[3rem] border border-white/5 shadow-2xl">
                  <h3 className="text-2xl font-black mb-10 tracking-tight uppercase flex items-center gap-3">
                     <Cog6ToothIcon className="h-8 w-8 text-blue-600" /> Parâmetros Globais
                  </h3>
                  <form onSubmit={handleSaveSettings} className="space-y-8">
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-2">
                           <label className="text-[10px] font-black text-gray-500 uppercase ml-2">Taxa da Plataforma (%)</label>
                           <input type="number" step="1" value={settings.platformTax * 100} onChange={e => setSettings({...settings, platformTax: parseFloat(e.target.value) / 100})} className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl font-black outline-none focus:ring-2 focus:ring-blue-600 dark:text-white"/>
                        </div>
                        <div className="space-y-2">
                           <label className="text-[10px] font-black text-gray-500 uppercase ml-2">Custo de Upgrade (USD)</label>
                           <input type="number" step="0.01" value={settings.upgradeCost} onChange={e => setSettings({...settings, upgradeCost: parseFloat(e.target.value)})} className="w-full p-5 bg-white/5 border border-white/10 rounded-2xl font-black outline-none focus:ring-2 focus:ring-blue-600 dark:text-white"/>
