                                      title="Remover Conta"
                                      className="p-3.5 rounded-2xl bg-[#1a1e26] border-2 border-white/5 text-gray-500 hover:bg-red-600 hover:border-red-400 hover:text-white transition-all shadow-xl active:scale-90"
                                    >
                                       <TrashIcon className="h-6 w-6" />
                                    </button>
                                 </div>
                              </td>
                           </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
               {filteredData.length === 0 && (
                  <div className="p-32 text-center">
                     <UserGroupIcon className="h-16 w-16 text-white/5 mx-auto mb-6" />
                     <p className="text-gray-500 font-black uppercase text-xs tracking-widest">Nenhum registro encontrado</p>
                  </div>
               )}
            </div>
         )}

         {activeTab === 'dashboard' && (
           <div className="space-y-12 animate-fade-in">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                 {[
                   { label: 'Receita Root', val: `$${data.revenue.toFixed(2)}`, color: 'text-green-500', icon: BanknotesIcon },
                   { label: 'Total Membros', val: data.users.length, color: 'text-blue-500', icon: UserGroupIcon },
                   { label: 'Publicações', val: data.posts.length, color: 'text-purple-500', icon: NewspaperIcon },
                   { label: 'Vendas Totais', val: data.transactions.length, color: 'text-orange-500', icon: ArrowTrendingUpIcon }
                 ].map(s => (
                   <div key={s.label} className="bg-[#12161f] p-8 rounded-[2.5rem] border border-white/5 shadow-2xl group transition-all hover:-translate-y-1 hover:border-white/10">
                      <div className="flex items-center gap-3 mb-4">
                         <s.icon className={`h-5 w-5 ${s.color} opacity-60`} />
                         <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{s.label}</p>
                      </div>
                      <p className={`text-4xl font-black tracking-tighter ${s.color}`}>{s.val}</p>
                   </div>
                 ))}
              </div>

              <div className="bg-[#12161f] p-10 rounded-[3rem] border border-white/5 shadow-inner">
                 <h3 className="text-[10px] font-black uppercase tracking-[0.3em] mb-10 flex items-center gap-3 text-blue-500">
                    <CommandLineIcon className="h-5 w-5" /> Log de Segurança Root
                 </h3>
                 <div className="space-y-4">
                    {data.logs.slice(0, 8).map(log => (
                        <div key={log.id} className="flex items-center justify-between p-5 bg-white/5 rounded-[1.8rem] border border-white/5 transition-all hover:bg-white/[0.08]">
                            <div className="flex items-center gap-5">
                                <div className="p-2.5 bg-blue-600/20 text-blue-400 rounded-xl font-black text-[7px] uppercase border border-blue-500/20">{log.action}</div>
                                <p className="text-xs font-medium text-gray-300">{log.details}</p>
                            </div>
                            <div className="flex items-center gap-2 text-gray-500">
                               <ClockIcon className="h-3 w-3" />
                               <span className="text-[9px] font-bold">{new Date(log.timestamp).toLocaleTimeString()}</span>
                            </div>
                        </div>
                    ))}
                 </div>
              </div>
           </div>
         )}
      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; height: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #1e293b; border-radius: 10px; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fadeIn 0.4s ease-out forwards; }
        .no-scrollbar::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useMemo } from 'react';
import { 
  User, Post, Product, OrderStatus, UserType, GlobalSettings, TransactionType, PostType
} from '../types';
import { 
  getUsers, getPlatformRevenue, getPosts, getProducts, getAds,
  getTransactions, getSystemLogs, getReports, getGlobalSettings,
  adminUpdateUser, adminDeletePost, adminProcessReport, adminDeleteProduct,
  updateGlobalSettings, updateUserBalance, getStores, deleteUser
} from '../services/storageService';
import { 
  BanknotesIcon, UserGroupIcon, ShieldCheckIcon, TrashIcon, 
  CheckBadgeIcon, ChartPieIcon, MagnifyingGlassIcon, CurrencyDollarIcon, 
  NoSymbolIcon, 
  Cog6ToothIcon, GlobeAltIcon, 
  CommandLineIcon, ArrowPathIcon, 
  ClockIcon, Bars3Icon, XMarkIcon,
  ArrowLeftOnRectangleIcon,
  ShieldExclamationIcon,
  ShoppingBagIcon,
  ArrowTrendingUpIcon,
  NewspaperIcon,
  BuildingStorefrontIcon,
  DocumentIcon,
  EyeIcon,
  IdentificationIcon,
  PhoneIcon,
  EnvelopeIcon,
  CalendarDaysIcon,
  UserIcon,
  PencilIcon,
  DevicePhoneMobileIcon
} from '@heroicons/react/24/solid';
import Logo from './Logo';
import { DEFAULT_PROFILE_PIC } from '../constants';

type AdminTab = 'dashboard' | 'users' | 'posts' | 'stores' | 'moderation' | 'finance' | 'config';

interface AdminDashboardProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  onRefreshUser: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser, onNavigate, onRefreshUser }) => {
  const [activeTab, setActiveTab] = useState<AdminTab>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [settings, setSettings] = useState<GlobalSettings>(() => getGlobalSettings());

  const refresh = () => {
    setRefreshKey(prev => prev + 1);
    setSettings(getGlobalSettings());
    onRefreshUser();
  };

  const data = useMemo(() => ({
    users: getUsers(),
    posts: getPosts(),
    products: getProducts(),
    stores: getStores(),
    ads: getAds().sort((a, b) => (b.budget || 0) - (a.budget || 0)),
    transactions: getTransactions().sort((a, b) => b.timestamp - a.timestamp),
    reports: getReports().sort((a, b) => b.timestamp - a.timestamp),
    logs: getSystemLogs().sort((a, b) => b.timestamp - a.timestamp),
    revenue: getPlatformRevenue()
  }), [refreshKey]);

  const filteredData = useMemo(() => {
    const term = searchTerm.toLowerCase();
    switch (activeTab) {
      case 'users':
        return data.users.filter(u => `${u.firstName} ${u.lastName}`.toLowerCase().includes(term) || u.email.toLowerCase().includes(term));
      case 'posts':
        return data.posts.filter(p => p.authorName.toLowerCase().includes(term) || (p.content?.toLowerCase().includes(term)));
      case 'moderation':
        return data.reports.filter(r => r.reason.toLowerCase().includes(term) || r.targetId.includes(term));
      default:
        return [];
    }
  }, [data, searchTerm, activeTab]);

  const handleUpdateUserData = (updated: User) => {
    adminUpdateUser(updated);
    setSelectedUser(updated);
    refresh();
  };

  const handleToggleVerification = (user: User) => {
    handleUpdateUserData({ ...user, isVerified: !user.isVerified });
  };

  const handleToggleSuspension = (user: User) => {
    handleUpdateUserData({ ...user, isSuspended: !user.isSuspended });
  };

  const handleDeleteUser = (uId: string) => {
    if (confirm("⚠️ AÇÃO IRREVERSÍVEL: Deseja eliminar permanentemente este cadastro do ecossistema?")) {
      deleteUser(uId);
      setSelectedUser(null);
      refresh();
    }
  };

  const handleUpdateBalance = (uId: string) => {
    const val = prompt("Valor do ajuste (pode ser negativo):", "0");
    if (val !== null && !isNaN(parseFloat(val))) {
      updateUserBalance(uId, parseFloat(val));
      const updated = getUsers().find(u => u.id === uId);
      if (updated) setSelectedUser(updated);
      refresh();
    }
  };

  const handleViewDoc = (url?: string) => {
    if (url) window.open(url, '_blank');
    else alert("Documentação ausente.");
  };

  const SidebarItem = ({ id, icon: Icon, label }: { id: AdminTab, icon: any, label: string }) => (
    <button 
      onClick={() => { setActiveTab(id); setSearchTerm(''); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 rounded-2xl mb-1 ${activeTab === id ? 'bg-blue-600 text-white shadow-[0_10px_20px_rgba(37,99,235,0.3)] scale-[1.02]' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
    >
      <Icon className="h-5 w-5" />
      <span className="font-black text-[10px] uppercase tracking-widest">{label}</span>
    </button>
  );

  return (
    <div className="fixed inset-0 bg-[#080a0f] text-white flex flex-col md:flex-row font-sans z-[9999] overflow-hidden">

      {isSidebarOpen && (
