               <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-4 bg-white/5 rounded-2xl border border-white/10">
                  <Bars3Icon className="h-6 w-6" />
               </button>
               <div>
                  <h2 className="text-3xl md:text-5xl font-black uppercase tracking-tighter text-blue-500">{activeTab}</h2>
                  <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest mt-1">Console Administrativo</p>
               </div>
            </div>

            <div className="flex items-center gap-4 w-full lg:w-auto">
               <div className="relative flex-1 lg:w-80">
                  <MagnifyingGlassIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" />
                  <input type="text" placeholder="Filtrar registros..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="bg-white/5 border border-white/10 rounded-2xl pl-12 pr-6 py-4 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-600 w-full transition-all text-white"/>
               </div>
               <button onClick={refresh} className="p-4 bg-white/5 hover:bg-blue-600 text-blue-500 hover:text-white rounded-2xl transition-all border border-white/10 active:rotate-180 duration-500"><ArrowPathIcon className="h-6 w-6" /></button>
            </div>
         </header>

         {activeTab === 'users' && (
