               >
                  <button onClick={() => setSelectedUser(null)} className="absolute top-8 right-8 z-10 p-3 bg-white/5 hover:bg-red-600 text-gray-400 hover:text-white rounded-full transition-all"><XMarkIcon className="h-6 w-6" /></button>

