                                <div className="p-2.5 bg-blue-600/20 text-blue-400 rounded-xl font-black text-[8px] uppercase border border-blue-500/20">{log.action}</div>
                                <p className="text-xs font-bold text-gray-300 uppercase tracking-tight">{log.details}</p>
                            </div>
                            <div className="flex items-center gap-2 text-gray-600">
                               <ClockIcon className="h-4 w-4" />
                               <span className="text-[10px] font-black">{new Date(log.timestamp).toLocaleTimeString()}</span>
                            </div>
                        </div>
                    ))}
                 </div>
              </div>
           </div>
         )}
      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; height: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #1e293b; border-radius: 10px; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
