                           </div>
                           <div className="space-y-1">
                              <p className="text-[9px] font-black text-gray-600 uppercase ml-2">Documento Validado (ID)</p>
                              <div className="p-5 bg-white/5 rounded-2xl border border-white/5 text-sm font-bold text-gray-300 flex items-center gap-3 shadow-inner"><IdentificationIcon className="h-4 w-4 opacity-30" />{selectedUser.documentId}</div>
                           </div>
                        </div>
                     </div>

                     <div className="mb-14">
                        <h4 className="text-[11px] font-black text-gray-500 uppercase tracking-[0.4em] mb-8 flex items-center gap-3"><PencilIcon className="h-6 w-6 text-orange-500" /> Edição Direta Root</h4>
                        <div className="space-y-6">
                           <div className="grid grid-cols-2 gap-4">
                              <div className="space-y-1">
                                 <p className="text-[8px] font-black text-gray-600 uppercase ml-2">Primeiro Nome</p>
                                 <input type="text" defaultValue={selectedUser.firstName} onBlur={e => handleQuickUpdate({...selectedUser, firstName: e.target.value})} className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-blue-600 font-bold text-sm transition-all focus:bg-white/10" />
                              </div>
                              <div className="space-y-1">
                                 <p className="text-[8px] font-black text-gray-600 uppercase ml-2">Sobrenome</p>
                                 <input type="text" defaultValue={selectedUser.lastName} onBlur={e => handleQuickUpdate({...selectedUser, lastName: e.target.value})} className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-blue-600 font-bold text-sm transition-all focus:bg-white/10" />
                              </div>
                           </div>
                           <div className="space-y-1">
                              <p className="text-[8px] font-black text-gray-600 uppercase ml-2">Especialidade / Título Profissional</p>
                              <input type="text" defaultValue={selectedUser.credentials} onBlur={e => handleQuickUpdate({...selectedUser, credentials: e.target.value})} className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl outline-none focus:border-blue-600 font-bold text-sm transition-all" placeholder="Ex: Professor de Inglês" />
                           </div>
                           <div className="space-y-1">
                              <p className="text-[8px] font-black text-gray-600 uppercase ml-2">Biografia do Perfil</p>
                              <textarea defaultValue={selectedUser.bio} onBlur={e => handleQuickUpdate({...selectedUser, bio: e.target.value})} className="w-full p-5 bg-white/5 border border-white/10 rounded-[2rem] outline-none focus:border-blue-600 font-medium text-sm h-32 resize-none transition-all" placeholder="Biografia do usuário..." />
                           </div>
                        </div>
                     </div>

                     {/* RODAPÉ DE AÇÕES DE SEGURANÇA */}
                     <div className="flex flex-col md:flex-row items-center gap-4 pt-10 border-t border-white/5">
                        <button 
                          onClick={() => handleToggleSuspension(selectedUser)} 
                          className={`flex-1 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-widest transition-all flex items-center justify-center gap-3 border shadow-xl active:scale-95 ${selectedUser.isSuspended ? 'bg-orange-600 border-orange-400 text-white shadow-orange-500/20' : 'bg-white/5 text-orange-500 border-orange-500/20 hover:bg-orange-600 hover:text-white'}`}
                        >
                           <NoSymbolIcon className="h-5 w-5" /> {selectedUser.isSuspended ? 'Desbloquear Acesso' : 'Suspender Conta'}
                        </button>

                        <button 
                          onClick={() => handleRemoveUser(selectedUser.id)} 
                          className="flex-1 py-5 bg-red-600/10 text-red-500 border border-red-500/20 rounded-[2rem] font-black text-[11px] uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all shadow-xl active:scale-95 flex items-center justify-center gap-3"
                        >
                           <TrashIcon className="h-5 w-5" /> Excluir Permanentemente
                        </button>
                     </div>
                  </div>
               </div>
            </div>
         )}

         {activeTab === 'dashboard' && (
           <div className="space-y-10 animate-fade-in">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                 {[
                   { label: 'Total Usuários', val: localUsers.length, color: 'text-blue-500', icon: UserGroupIcon },
                   { label: 'Publicações', val: getPosts().length, color: 'text-purple-500', icon: NewspaperIcon },
                   { label: 'Circulação $', val: `$${localUsers.reduce((a,b) => a + (b.balance || 0), 0).toFixed(2)}`, color: 'text-emerald-500', icon: BanknotesIcon },
                   { label: 'Sessões Ativas', val: Math.floor(localUsers.length * 0.4), color: 'text-orange-500', icon: CommandLineIcon }
                 ].map(s => (
                   <div key={s.label} className="bg-[#12161f] p-8 rounded-[2.5rem] border border-white/5 shadow-2xl transition-transform hover:-translate-y-1 group">
                      <div className="flex items-center gap-3 mb-4">
                         <s.icon className={`h-5 w-5 ${s.color} opacity-60`} />
                         <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{s.label}</p>
                      </div>
                      <p className={`text-4xl font-black tracking-tighter ${s.color}`}>{s.val}</p>
                   </div>
                 ))}
              </div>

              <div className="bg-[#12161f] p-10 rounded-[3.5rem] border border-white/5 shadow-inner">
                 <div className="flex items-center justify-between mb-8">
                    <h3 className="text-[11px] font-black uppercase tracking-[0.4em] text-blue-500 flex items-center gap-3">
                       <CommandLineIcon className="h-5 w-5" /> Logs do Terminal Root
                    </h3>
                 </div>
                 <div className="space-y-3">
                    {getSystemLogs().slice(0, 10).map(log => (
                        <div key={log.id} className="flex items-center justify-between p-5 bg-white/[0.02] rounded-2xl border border-white/5 hover:bg-white/[0.04] transition-all group">
                            <div className="flex items-center gap-6">
                                <span className="p-2 bg-blue-600/20 text-blue-400 rounded-lg font-black text-[8px] uppercase border border-blue-500/20">{log.action}</span>
                                <p className="text-xs font-bold text-gray-300 truncate max-w-md">{log.details}</p>
                            </div>
                            <span className="text-[10px] font-black text-gray-600">{new Date(log.timestamp).toLocaleTimeString()}</span>
                        </div>
                    ))}
                 </div>
              </div>
           </div>
         )}
      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #1e293b; border-radius: 10px; }
        @keyframes scaleIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        .animate-scale-in { animation: scaleIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fadeIn 0.3s ease-out; }
      `}</style>
    </div>
  );
};

export default AdminDashboard;

import { 
  BanknotesIcon, UserGroupIcon, ShieldCheckIcon, TrashIcon, 
  CheckBadgeIcon, ChartPieIcon, MagnifyingGlassIcon, CurrencyDollarIcon, 
  NoSymbolIcon, 
  Cog6ToothIcon, 
  CommandLineIcon, ArrowPathIcon, 
  Bars3Icon, XMarkIcon,
  ArrowLeftOnRectangleIcon,
  ShieldExclamationIcon,
  NewspaperIcon,
  IdentificationIcon,
  EnvelopeIcon,
  PencilIcon,
  UserIcon,
  CheckIcon,
  // Added EyeIcon to imports
  EyeIcon
} from '@heroicons/react/24/solid';
import Logo from './Logo';
import { DEFAULT_PROFILE_PIC } from '../constants';

interface AdminDashboardProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  onRefreshUser: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser, onNavigate, onRefreshUser }) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'users' | 'posts' | 'moderation' | 'finance' | 'config'>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [localUsers, setLocalUsers] = useState<User[]>([]);

  // Carregamento de dados centralizado
  const loadData = () => {
    const users = getUsers();
    setLocalUsers(users);

    // Se houver um usuário selecionado no modal, atualiza ele também para refletir as mudanças
    if (selectedUser) {
      const updated = users.find(u => u.id === selectedUser.id);
      if (updated) setSelectedUser(updated);
      else setSelectedUser(null); // Caso tenha sido deletado
    }
    onRefreshUser();
  };

  useEffect(() => {
    loadData();
  }, [activeTab]);

  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return localUsers.filter(u => 
      `${u.firstName} ${u.lastName}`.toLowerCase().includes(term) || 
      u.email.toLowerCase().includes(term)
    );
  }, [localUsers, searchTerm]);

  // --- FUNÇÕES DE INTERAÇÃO ROOT ---

  const handleQuickUpdate = (updated: User) => {
    adminUpdateUser(updated);
    loadData();
  };

  const handleToggleVerification = (user: User) => {
    handleQuickUpdate({ ...user, isVerified: !user.isVerified });
  };

  const handleToggleSuspension = (user: User) => {
    handleQuickUpdate({ ...user, isSuspended: !user.isSuspended });
  };

  const handleRemoveUser = (userId: string) => {
    if (window.confirm("⚠️ ALERTA DE EXCLUSÃO: Esta ação é permanente e removerá todos os dados do usuário. Continuar?")) {
      deleteUser(userId);
      setSelectedUser(null);
      loadData();
    }
  };

  const handleAdjustBalance = (userId: string) => {
    const val = prompt("Ajustar saldo (ex: 50 para adicionar, -50 para remover):", "0");
    if (val !== null && !isNaN(parseFloat(val))) {
      updateUserBalance(userId, parseFloat(val));
      loadData();
    }
  };

  const SidebarItem = ({ id, icon: Icon, label }: { id: any, icon: any, label: string }) => (
    <button 
      onClick={() => { setActiveTab(id); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 rounded-2xl mb-1 ${activeTab === id ? 'bg-blue-600 text-white shadow-xl scale-[1.02]' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
    >
      <Icon className="h-5 w-5" />
      <span className="font-black text-[10px] uppercase tracking-widest">{label}</span>
    </button>
  );

  return (
    <div className="fixed inset-0 bg-[#080a0f] text-white flex flex-col md:flex-row font-sans z-[9999] overflow-hidden">

      {/* Overlay Mobile */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[505] md:hidden" onClick={() => setIsSidebarOpen(false)} />
      )}

      {/* SIDEBAR */}
      <aside className={`fixed inset-y-0 left-0 z-[510] w-72 bg-[#0d1117] border-r border-white/5 flex flex-col p-6 transition-transform duration-300 md:relative md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
         <div className="flex items-center justify-between mb-12">
            <Logo size="md" variant="white" />
            <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 text-gray-400 hover:text-white"><XMarkIcon className="h-7 w-7" /></button>
         </div>

         <nav className="flex-1 space-y-1">
            <p className="text-[9px] font-black text-gray-600 uppercase tracking-widest mb-4 ml-2">Sessão Administrador</p>
            <SidebarItem id="dashboard" icon={ChartPieIcon} label="Visão Geral" />
            <SidebarItem id="users" icon={UserGroupIcon} label="Gerenciar Membros" />
            <SidebarItem id="moderation" icon={ShieldExclamationIcon} label="Denúncias" />
            <SidebarItem id="finance" icon={BanknotesIcon} label="Economia" />
            <SidebarItem id="config" icon={Cog6ToothIcon} label="Ajustes Root" />
         </nav>

         <button onClick={() => onNavigate('feed')} className="mt-auto flex items-center gap-4 px-6 py-4 text-gray-500 hover:text-red-500 bg-white/5 rounded-2xl transition-all group">
            <ArrowLeftOnRectangleIcon className="h-5 w-5 group-hover:-translate-x-1 transition-transform" />
            <span className="font-black text-[10px] uppercase tracking-widest">Sair do Painel</span>
         </button>
      </aside>

      {/* CONTEÚDO PRINCIPAL */}
      <main className="flex-1 p-4 md:p-10 overflow-y-auto custom-scrollbar relative">
         <header className="flex items-center justify-between mb-12">
            <div className="flex items-center gap-4">
               <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-3 bg-white/5 rounded-xl border border-white/10">
                  <Bars3Icon className="h-6 w-6" />
               </button>
               <div>
                  <h2 className="text-4xl font-black uppercase tracking-tighter text-blue-500 leading-none">{activeTab}</h2>
                  <p className="text-[9px] text-gray-500 font-bold uppercase mt-1 tracking-widest">Controle de Sistema CyBerPhone</p>
               </div>
            </div>

            <div className="flex items-center gap-4">
               <div className="relative hidden lg:block">
                  <MagnifyingGlassIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" />
                  <input 
                    type="text" 
                    placeholder="Pesquisar registros..." 
                    value={searchTerm} 
                    onChange={e => setSearchTerm(e.target.value)} 
                    className="bg-white/5 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-600 w-72 transition-all"
                  />
               </div>
               <button onClick={loadData} className="p-3 bg-white/5 hover:bg-blue-600 rounded-xl transition-all active:rotate-180 duration-500"><ArrowPathIcon className="h-6 w-6" /></button>
            </div>
         </header>

         {/* TABELA DE USUÁRIOS */}
         {activeTab === 'users' && (
            <div className="bg-[#12161f] rounded-[2.5rem] border border-white/5 overflow-hidden shadow-2xl animate-fade-in">
               <table className="w-full text-left">
                  <thead className="bg-black/40 text-[10px] font-black uppercase text-gray-500 tracking-[0.2em]">
                     <tr>
                        <th className="px-8 py-6">Perfil</th>
                        <th className="px-8 py-6">Tipo</th>
                        <th className="px-8 py-6">Patrimônio</th>
                        <th className="px-8 py-6 text-right">Ações</th>
                     </tr>
                  </thead>
                  <tbody className="divide-y divide-white/[0.03]">
                     {filteredUsers.map(user => (
                        <tr 
                          key={user.id} 
                          onClick={() => setSelectedUser(user)}
                          className={`group cursor-pointer hover:bg-white/[0.03] transition-all ${user.isSuspended ? 'opacity-40 grayscale' : ''}`}
                        >
                           <td className="px-8 py-5">
                              <div className="flex items-center gap-4">
                                 <div className="relative">
                                    <img src={user.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-2xl object-cover border-2 border-white/5 group-hover:scale-110 transition-transform" />
                                    {user.isVerified && <CheckBadgeIcon className="h-4 w-4 text-blue-500 absolute -top-1 -right-1 shadow-lg" />}
                                 </div>
                                 <div>
                                    <p className="font-black text-sm uppercase tracking-tighter text-gray-100">{user.firstName} {user.lastName}</p>
                                    <p className="text-[10px] text-gray-500 font-medium">{user.email}</p>
                                 </div>
                              </div>
                           </td>
                           <td className="px-8 py-5">
                              <div className="flex flex-col gap-1">
                                <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase w-fit ${user.userType === UserType.CREATOR ? 'bg-purple-600/20 text-purple-400' : 'bg-blue-600/20 text-blue-400'}`}>
                                   {user.userType === UserType.CREATOR ? 'Professor' : 'Membro'}
                                </span>
                                {user.isSuspended && <span className="text-[7px] text-red-500 font-black uppercase">Bloqueado</span>}
                              </div>
                           </td>
                           <td className="px-8 py-5">
                              <p className="font-black text-emerald-500 tracking-tighter">${(user.balance || 0).toFixed(2)}</p>
                           </td>
                           <td className="px-8 py-5 text-right">
                              <button className="p-3 bg-blue-600/10 text-blue-500 rounded-xl group-hover:bg-blue-600 group-hover:text-white transition-all transform group-hover:scale-105">
                                 {/* Fixed: EyeIcon added to imports */}
                                 <EyeIcon className="h-5 w-5" />
                              </button>
                           </td>
                        </tr>
                     ))}
                  </tbody>
               </table>
            </div>
         )}

