import React, { useState, useEffect, useMemo } from 'react';
import { 
  User, UserType, SystemLog, ContentReport, Transaction
} from '../types';
import { 
  getUsers, getPosts, getSystemLogs,
  adminUpdateUser, deleteUser, updateUserBalance
} from '../services/storageService';
import { 
  BanknotesIcon, UserGroupIcon, ShieldCheckIcon, TrashIcon, 
  CheckBadgeIcon, ChartPieIcon, MagnifyingGlassIcon, CurrencyDollarIcon, 
  NoSymbolIcon, 
  Cog6ToothIcon, 
  CommandLineIcon, ArrowPathIcon, 
  Bars3Icon, XMarkIcon,
  ArrowLeftOnRectangleIcon,
  ShieldExclamationIcon,
  NewspaperIcon,
  IdentificationIcon,
  EnvelopeIcon,
  PencilIcon,
  EyeIcon
} from '@heroicons/react/24/solid';
import Logo from './Logo';
import { DEFAULT_PROFILE_PIC } from '../constants';

interface AdminDashboardProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  onRefreshUser: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentUser, onNavigate, onRefreshUser }) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'users' | 'posts' | 'moderation' | 'finance' | 'config'>('dashboard');
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [localUsers, setLocalUsers] = useState<User[]>([]);

  const loadData = () => {
    const users = getUsers();
    setLocalUsers(users);
    if (selectedUser) {
      const updated = users.find(u => u.id === selectedUser.id);
      if (updated) setSelectedUser(updated);
      else setSelectedUser(null);
    }
    onRefreshUser();
  };

  useEffect(() => {
    loadData();
  }, [activeTab]);

  const filteredUsers = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return localUsers.filter(u => 
      `${u.firstName} ${u.lastName}`.toLowerCase().includes(term) || 
      u.email.toLowerCase().includes(term)
    );
  }, [localUsers, searchTerm]);

  const handleQuickUpdate = (updated: User) => {
    adminUpdateUser(updated);
    loadData();
  };

  const handleToggleVerification = (user: User) => {
    handleQuickUpdate({ ...user, isVerified: !user.isVerified });
  };

  const handleToggleSuspension = (user: User) => {
    handleQuickUpdate({ ...user, isSuspended: !user.isSuspended });
  };

  const handleRemoveUser = (userId: string) => {
    if (window.confirm("⚠️ EXCLUSÃO PERMANENTE: Remover todos os dados do usuário?")) {
      deleteUser(userId);
      setSelectedUser(null);
      loadData();
    }
  };

  const handleAdjustBalance = (userId: string) => {
    const val = prompt("Ajustar saldo (ex: 50 ou -50):", "0");
    if (val !== null && !isNaN(parseFloat(val))) {
      updateUserBalance(userId, parseFloat(val));
      loadData();
    }
  };

  const SidebarItem = ({ id, icon: Icon, label }: { id: any, icon: any, label: string }) => (
    <button 
      onClick={() => { setActiveTab(id); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 rounded-2xl mb-1 ${activeTab === id ? 'bg-blue-600 text-white shadow-xl scale-[1.02]' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
    >
      <Icon className="h-5 w-5" />
      <span className="font-black text-[10px] uppercase tracking-widest">{label}</span>
    </button>
  );

  return (
    <div className="fixed inset-0 bg-[#080a0f] text-white flex flex-col md:flex-row font-sans z-[9999] overflow-hidden">
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[505] md:hidden" onClick={() => setIsSidebarOpen(false)} />
      )}

