                        </div>
                        <div className="flex flex-col md:flex-row gap-4 pt-10 border-t border-white/5">
                           <button onClick={() => handleToggleSuspension(selectedUser)} className={`flex-1 py-5 rounded-[2rem] font-black text-[11px] uppercase border ${selectedUser.isSuspended ? 'bg-orange-600 text-white' : 'bg-white/5 text-orange-500 border-orange-500/20'}`}>
