                           </button>
                           <button onClick={() => handleRemoveUser(selectedUser.id)} className="flex-1 py-5 bg-red-600/10 text-red-500 border border-red-500/20 rounded-[2rem] font-black text-[11px] uppercase hover:bg-red-600 hover:text-white transition-all">
                              Eliminar Permanente
                           </button>
                        </div>
                     </div>
                  </div>
               </div>
            </div>
         )}

         {activeTab === 'dashboard' && (
           <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 animate-fade-in">
              {[
                { label: 'Usuários', val: localUsers.length, color: 'text-blue-500', icon: UserGroupIcon },
                { label: 'Publicações', val: getPosts().length, color: 'text-purple-500', icon: NewspaperIcon },
                { label: 'Finanças Total', val: `$${localUsers.reduce((a,b) => a + (b.balance || 0), 0).toFixed(2)}`, color: 'text-emerald-500', icon: BanknotesIcon },
                { label: 'Registros Log', val: getSystemLogs().length, color: 'text-orange-500', icon: CommandLineIcon }
              ].map(s => (
                <div key={s.label} className="bg-[#12161f] p-8 rounded-[2.5rem] border border-white/5 shadow-2xl">
                   <div className="flex items-center gap-3 mb-4">
                      <s.icon className={`h-5 w-5 ${s.color}`} />
                      <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{s.label}</p>
                   </div>
                   <p className="text-4xl font-black tracking-tighter">{s.val}</p>
                </div>
              ))}
           </div>
         )}
      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; height: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #1e293b; border-radius: 10px; }
        @keyframes scaleIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        .animate-scale-in { animation: scaleIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fadeIn 0.3s ease-out; }
      `}</style>
    </div>
  );
};

export default AdminDashboard;

