// --- HELPER LOCALSTORAGE ---
const get = <T>(key: string, fallback: T): T => {
  try {
    const data = localStorage.getItem(key);
    if (!data || data === "undefined" || data === "null") return fallback;
    return JSON.parse(data);
  } catch (e) {
    return fallback;
  }
};

const set = (key: string, data: any) => {
  try {
    localStorage.setItem(key, JSON.stringify(data));
  } catch (e) {}
};

// --- SYNC ENGINE ---
// Sincroniza dados do Supabase para o LocalStorage ao iniciar
export const syncWithDatabase = async () => {
  try {
    // 1. Users/Profiles
    const { data: profiles } = await supabase.from('profiles').select('*');
    if (profiles) {
      // Map database columns to local TS types if needed
      const mappedUsers: User[] = profiles.map((p: any) => ({
        id: p.id,
        userType: p.user_type as UserType,
        firstName: p.first_name,
        lastName: p.last_name,
        email: p.email,
        phone: p.phone,
        documentId: p.document_id,
        birthDate: p.birth_date,
        profilePicture: p.profile_picture,
        balance: p.balance,
        credentials: p.credentials,
        bio: p.bio,
        isAdmin: p.is_admin,
        isVerified: p.is_verified,
        isSuspended: p.is_suspended,
        // Relations needs separate fetch, mocking for now or fetching from junction table
        followedUsers: [],
        followers: [] 
      }));
      set(KEYS.USERS, mappedUsers);
    }

    // 2. Posts
    const { data: posts } = await supabase.from('posts').select('*');
    if (posts) {
      const users = getUsers();
      const mappedPosts: Post[] = posts.map((p: any) => ({
        id: p.id,
        userId: p.user_id,
        authorName: users.find(u => u.id === p.user_id)?.firstName || 'Usuário',
        authorProfilePic: users.find(u => u.id === p.user_id)?.profilePicture,
        type: p.type as PostType,
        timestamp: p.timestamp,
        content: p.content,
        imageUrl: p.image_url,
        likes: p.likes || [],
        comments: [], // Comments would need a separate fetch/join
        shares: p.shares || [],
        saves: p.saves || [],
        isPinned: p.is_pinned,
        isBoosted: p.is_boosted,
        liveStream: p.live_data,
        reel: p.reel_data
      }));
      set(KEYS.POSTS, mappedPosts);
    }

    // 3. Stores & Products (Simplificado para o exemplo)
    const { data: dbStores } = await supabase.from('stores').select('*');
    if(dbStores) {
       const mappedStores = dbStores.map((s: any) => ({
         id: s.id, professorId: s.professor_id, name: s.name, description: s.description, brandColor: s.brand_color, productIds: []
       }));
       set(KEYS.STORES, mappedStores);
    }

    console.log('Sincronização com Supabase concluída.');
  } catch (error) {
    console.error('Erro na sincronização:', error);
  }
};

// Initialize only local defaults if empty, then sync
export const initializeData = () => {
  if (!localStorage.getItem(KEYS.USERS)) set(KEYS.USERS, DEFAULT_USERS);
  if (!localStorage.getItem(KEYS.POSTS)) set(KEYS.POSTS, DEFAULT_POSTS);
  // Trigger async sync
  syncWithDatabase();
};

initializeData();

// --- AUTH & USER ---

export const loginUser = async (email: string, pass: string): Promise<User> => {
  // Supabase Auth
  const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

  if (error) throw new Error(error.message);
  if (!data.user) throw new Error("Erro ao obter usuário");

  // Fetch Profile details
  const { data: profile } = await supabase.from('profiles').select('*').eq('id', data.user.id).single();

  if (profile) {
    const user: User = {
      id: profile.id,
      email: profile.email,
      firstName: profile.first_name,
      lastName: profile.last_name,
      userType: profile.user_type as UserType,
      phone: profile.phone,
      documentId: profile.document_id,
      birthDate: profile.birth_date,
      profilePicture: profile.profile_picture,
      balance: profile.balance,
      isAdmin: profile.is_admin,
      isVerified: profile.is_verified,
      isSuspended: profile.is_suspended,
      followedUsers: [],
      followers: []
    };
    // Update local cache
    const users = getUsers();
    const idx = users.findIndex(u => u.id === user.id);
    if(idx >= 0) users[idx] = user; else users.push(user);
    saveUsers(users);

    return user;
  }
  throw new Error("Perfil não encontrado");
};

export const registerUser = async (userData: any): Promise<User> => {
  // 1. Create Auth User
  const { data, error } = await supabase.auth.signUp({
    email: userData.email,
    password: userData.password,
    options: {
      data: {
        firstName: userData.firstName,
        lastName: userData.lastName,
        userType: userData.userType
      }
    }
  });

  if (error) throw new Error(error.message);
  if (!data.user) throw new Error("Erro na criação");

  // 2. Profile row is created by Database Trigger (defined in SQL), 
  // but we construct the local object immediately for responsiveness
  const newUser: User = {
    id: data.user.id,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.credentials,
    bio: userData.bio
  };

  // 3. Update extra fields in DB manually if Trigger didn't cover everything
  await supabase.from('profiles').update({
    phone: userData.phone,
    document_id: userData.documentId,
    birth_date: userData.birthDate,
    profile_picture: userData.profilePicture,
    bio: userData.bio,
    credentials: userData.credentials
  }).eq('id', newUser.id);

  if (newUser.userType === UserType.CREATOR) {
    const storeId = `store-${Date.now()}`; // UUID gen in real app
    newUser.storeId = storeId;
    await supabase.from('stores').insert({
      professor_id: newUser.id,
      name: `Loja de ${newUser.firstName}`,
      description: 'Bem-vindo!',
      brand_color: '#2563eb'
    });
  }

  saveUsers([...getUsers(), newUser]);
  return newUser;
};

