// --- DATA ACCESS (Read from Local, Write to DB + Local) ---

export const getUsers = (): User[] => get(KEYS.USERS, DEFAULT_USERS);
export const saveUsers = (users: User[]) => set(KEYS.USERS, users);
export const findUserById = (id: string) => getUsers().find(u => u.id === id);

export const getPosts = (): Post[] => get(KEYS.POSTS, DEFAULT_POSTS);
export const savePosts = (p: Post[]) => set(KEYS.POSTS, p);

export const addPost = async (p: Post) => {
  // Optimistic UI Update
  savePosts([p, ...getPosts()]);

  // Async DB Write
  await supabase.from('posts').insert({
    id: p.id.includes('-') ? undefined : p.id, // Let DB generate UUID if it's not one
    user_id: p.userId,
    type: p.type,
    content: p.content,
    image_url: p.imageUrl,
    timestamp: p.timestamp,
    font_family: p.fontFamily,
    text_color: p.textColor,
    background_color: p.backgroundColor,
    reel_data: p.reel,
    live_data: p.liveStream
  });
};

export const updatePost = async (p: Post) => {
  savePosts(getPosts().map(old => old.id === p.id ? p : old));
  await supabase.from('posts').update({
    content: p.content,
    likes: p.likes,
    saves: p.saves
  }).eq('id', p.id);
};

export const deletePost = async (postId: string) => {
  savePosts(getPosts().filter(p => p.id !== postId));
  await supabase.from('posts').delete().eq('id', postId);
};

