             </div>
             <button onClick={() => onNavigate('store')} className="w-full md:w-auto bg-white/10 hover:bg-white/20 text-white px-6 py-3 md:px-8 md:py-4 rounded-xl md:rounded-2xl font-black text-[10px] md:text-xs uppercase backdrop-blur-xl border border-white/10 transition-all relative z-10">Explorar Outros Professores</button>
