               </div>
               <div className="divide-y divide-gray-50 dark:divide-white/5">
                  {storeSales.length === 0 ? (
                    <div className="p-24 text-center text-gray-400 font-black uppercase text-xs tracking-widest">Aguardando sua primeira venda...</div>
                  ) : (
                    storeSales.map(sale => {
                       const buyer = findUserById(sale.buyerId);
                       const product = getProducts().find(p => p.id === sale.productId);
                       const isPhysical = product?.type === ProductType.PHYSICAL;

                       return (
                         <div key={sale.id} className="p-6 md:p-8 flex flex-col lg:flex-row gap-8 items-start lg:items-center hover:bg-gray-50/50 dark:hover:bg-white/5 transition-colors">
                            <div className="flex items-center gap-5 min-w-[240px]">
                               <img src={product?.imageUrls[0]} className="w-16 h-16 rounded-2xl object-cover shadow-lg" />
                               <div>
                                  <p className="font-black text-sm dark:text-white uppercase truncate max-w-[180px]">{product?.name}</p>
                                  <p className="text-[9px] font-bold text-gray-400 uppercase">#{sale.id.split('-')[1]}</p>
                               </div>
                            </div>

                            <div className="flex-1 space-y-3 w-full">
                               <div className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase">
                                  <ShoppingBagIcon className="h-4 w-4" />
