                                  <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${sale.status === OrderStatus.DELIVERED ? 'bg-green-100 text-green-600' : sale.status === OrderStatus.SHIPPING ? 'bg-blue-100 text-blue-600' : 'bg-orange-100 text-orange-600'}`}>
                                     {sale.status === OrderStatus.WAITLIST ? 'Em Preparo' : sale.status === OrderStatus.SHIPPING ? 'Em Trânsito' : 'Finalizado'}
