-- 7. Tabela de Posts (Feed, Reels e Lives)
CREATE TABLE posts (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    type TEXT DEFAULT 'TEXT', -- Mapeado para post_type
