-- Trigger para criar Profile automaticamente ao registrar no Supabase Auth
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, email, first_name, last_name, user_type, profile_picture, document_id, phone, bio, credentials, birth_date)
  VALUES (
    new.id,
    new.email,
    new.raw_user_meta_data->>'firstName',
    new.raw_user_meta_data->>'lastName',
    COALESCE(new.raw_user_meta_data->>'userType', 'STANDARD'),
    COALESCE(new.raw_user_meta_data->>'profilePicture', 'https://picsum.photos/200'),
    new.raw_user_meta_data->>'documentId',
    new.raw_user_meta_data->>'phone',
    new.raw_user_meta_data->>'bio',
    new.raw_user_meta_data->>'credentials',
    (new.raw_user_meta_data->>'birthDate')::BIGINT
  );

  -- Se for criador, cria a loja automaticamente
  IF (new.raw_user_meta_data->>'userType' = 'CREATOR') THEN
    INSERT INTO public.stores (professor_id, name, description, brand_color)
    VALUES (new.id, 'Loja de ' || (new.raw_user_meta_data->>'firstName'), 'Bem-vindo à minha loja!', '#2563eb');
  END IF;

  RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

