                                        <CheckBadgeIcon className="h-5 w-5 text-green-500" /> Venda Concluída
                                     </div>
                                  )}
                               </div>
                            </div>
                         </div>
                       );
                    })
                  )}
               </div>
            </div>
         </div>
       )}

       {activeTab === 'branding' && (
         <div className="max-w-4xl mx-auto space-y-10 animate-fade-in">
