// --- NOVO: Função de Upload para Supabase Storage ---
export const uploadFile = async (file: File | Blob, folder: string = 'general'): Promise<string> => {
  if (!isSupabaseConfigured) {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.readAsDataURL(file);
    });
  }

  try {
    const fileExt = file instanceof File ? file.name.split('.').pop() : 'webm';
    const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;

    const { data, error } = await supabase.storage
      .from('cyber-files')
      .upload(fileName, file);

    if (error) throw error;

    const { data: { publicUrl } } = supabase.storage
      .from('cyber-files')
      .getPublicUrl(fileName);

    return publicUrl;
  } catch (error) {
    console.error('Erro no upload:', error);
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.readAsDataURL(file);
    });
  }
};

export const compressImage = async (base64OrFile: string | File): Promise<string> => {
  if (base64OrFile instanceof File) {
    return uploadFile(base64OrFile, 'images');
  }
  return Promise.resolve(base64OrFile);
};

// --- AUTENTICAÇÃO HÍBRIDA (SUPABASE + LOCAL CACHE) ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  // 1. Tentar login no Supabase
  if (isSupabaseConfigured) {
    const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
      email,
      password
    });

    if (authError) {
      console.error("Erro Supabase Auth:", authError);
      throw new Error(authError.message === 'Invalid login credentials' ? 'Credenciais inválidas.' : authError.message);
    }

    if (authData.user) {
      // 2. Buscar dados do perfil na tabela 'profiles'
      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authData.user.id)
        .single();

      if (profileData) {
        // Mapear campos do Supabase (snake_case) para o app (camelCase)
        const user: User = {
          id: profileData.id,
          email: profileData.email || email,
          userType: profileData.user_type as UserType,
          firstName: profileData.first_name,
          lastName: profileData.last_name,
          phone: profileData.phone,
          documentId: profileData.document_id,
          birthDate: parseInt(profileData.birth_date),
          profilePicture: profileData.profile_picture,
          balance: profileData.balance,
          credentials: profileData.credentials,
          bio: profileData.bio,
          isAdmin: profileData.is_admin,
          isVerified: profileData.is_verified,
          followers: profileData.followers || [],
          followedUsers: profileData.followed_users || [],
          storeId: undefined // Lógica de store separada
        };

        // Se for criador, buscar ID da loja
        if (user.userType === UserType.CREATOR) {
           const { data: storeData } = await supabase.from('stores').select('id').eq('professor_id', user.id).single();
           if (storeData) user.storeId = storeData.id;
        }

        // Atualizar LocalStorage para manter a UI síncrona funcionando
        updateLocalUserCache(user);
        return user;
      }
    }
  }

  // Fallback LocalStorage (Offline ou Config Incompleta)
  const users = getUsers();
  const user = users.find(u => u.email === email);
  if (user) {
    return user;
  }
  throw new Error('Credenciais inválidas.');
};

export const registerUser = async (userData: any): Promise<User> => {
  // 1. Tentar registro no Supabase
  if (isSupabaseConfigured) {
    const { data, error } = await supabase.auth.signUp({
      email: userData.email,
      password: userData.password,
      options: {
        data: {
          firstName: userData.firstName,
          lastName: userData.lastName,
          userType: userData.userType,
          phone: userData.phone,
          documentId: userData.documentId,
          birthDate: userData.birthDate,
          profilePicture: userData.profilePicture,
          credentials: userData.credentials,
          bio: userData.bio
        }
      }
    });

    if (error) throw new Error(error.message);
    if (data.user) {
      // Objeto User para uso imediato na UI
      const newUser: User = {
        id: data.user.id,
        userType: userData.userType,
        firstName: userData.firstName,
        lastName: userData.lastName,
        email: userData.email,
        phone: userData.phone,
        documentId: userData.documentId,
        birthDate: userData.birthDate,
        profilePicture: userData.profilePicture,
        credentials: userData.credentials,
        bio: userData.bio,
        followedUsers: [],
        followers: [],
        balance: 0,
        storeId: userData.userType === UserType.CREATOR ? `temp-store-${data.user.id}` : undefined
      };

      updateLocalUserCache(newUser);
      return newUser;
    }
  }

  // Fallback LocalStorage
  const users = getUsers();
  if (users.some(u => u.email === userData.email)) {
    throw new Error('Email já cadastrado.');
  }

  const newUser: User = {
    id: `user-${Date.now()}`,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.userType === UserType.CREATOR ? userData.credentials : undefined,
    bio: userData.bio, 
    verificationFileUrl: userData.verificationFileUrl
  };

  if (newUser.userType === UserType.CREATOR) {
    const allStores = getStores();
    const storeId = `store-${Date.now()}`;
    newUser.storeId = storeId;
    saveStores([...allStores, {
      id: storeId,
      professorId: newUser.id,
      name: `Loja de ${newUser.firstName} ${newUser.lastName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: [],
    }]);
  }
  saveUsers([...users, newUser]);
  return newUser;
};

// Helper para sincronizar o usuário logado com o cache local (para não quebrar a UI existente)
const updateLocalUserCache = (user: User) => {
  const users = getUsers();
  const existingIndex = users.findIndex(u => u.id === user.id);
  if (existingIndex >= 0) {
    users[existingIndex] = user;
  } else {
    users.push(user);
  }
  saveUsers(users);
};

