export const getPosts = async (): Promise<Post[]> => {
  // Join com profiles para pegar nome/foto do autor
  const { data, error } = await supabase
    .from('posts')
    .select('*, profiles!user_id(first_name, last_name, profile_picture)')
    .order('timestamp', { ascending: false });

  if (error) {
    console.error(error);
    return [];
  }

  // Carregar comentários para cada post (pode ser otimizado depois)
  const posts = await Promise.all((data || []).map(async (p) => {
    const post = mapPostFromDB(p);
    const { data: comments } = await supabase
      .from('comments')
      .select('*, profiles!user_id(first_name, last_name, profile_picture)')
      .eq('post_id', post.id);

    post.comments = (comments || []).map((c: any) => ({
      id: c.id,
      userId: c.user_id,
      userName: `${c.profiles.first_name} ${c.profiles.last_name}`,
      profilePic: c.profiles.profile_picture,
      text: c.text,
      timestamp: Number(c.timestamp)
    }));
    return post;
  }));

  return posts;
};

