};

export const updatePostLikes = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('likes, user_id').eq('id', postId).single();
  if (!data) return;

  let likes: string[] = data.likes || [];
  if (likes.includes(userId)) {
    likes = likes.filter(id => id !== userId);
  } else {
    likes.push(userId);
    // Notificar dono do post
    if (data.user_id !== userId) {
      createNotification({
        type: NotificationType.LIKE,
        recipientId: data.user_id,
        actorId: userId,
        postId: postId,
        timestamp: Date.now()
      });
    }
  }
  await supabase.from('posts').update({ likes }).eq('id', postId);
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('saves').eq('id', postId).single();
  if (!data) return;

  let saves: string[] = data.saves || [];
  if (saves.includes(userId)) saves = saves.filter(id => id !== userId);
  else saves.push(userId);

  await supabase.from('posts').update({ saves }).eq('id', postId);
};

export const updatePostShares = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('shares').eq('id', postId).single();
  if (!data) return;
  let shares = data.shares || [];
  if (!shares.includes(userId)) {
    shares.push(userId);
    await supabase.from('posts').update({ shares }).eq('id', postId);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  await supabase.from('comments').insert({
    post_id: postId,
    user_id: comment.userId,
    text: comment.text,
    timestamp: comment.timestamp
  });

  // Notificar dono do post
  const { data: post } = await supabase.from('posts').select('user_id').eq('id', postId).single();
  if (post && post.user_id !== comment.userId) {
    createNotification({
      type: NotificationType.COMMENT,
      recipientId: post.user_id,
      actorId: comment.userId,
      postId: postId,
      timestamp: Date.now()
    });
  }
};

export const pinPost = async (postId: string, userId: string) => {
  // Desafixar todos primeiro
  await supabase.from('posts').update({ is_pinned: false }).eq('user_id', userId);
  // Fixar o novo
  await supabase.from('posts').update({ is_pinned: true }).eq('id', postId);
  return true;
};

export const unpinPost = async (postId: string, userId: string) => {
  await supabase.from('posts').update({ is_pinned: false }).eq('id', postId);
  return true;
};

export const boostPost = async (postId: string, userId: string, budget: number, days: number) => {
  const success = await updateUserBalance(userId, -budget);
  if (success) {
    const expires = Date.now() + (days * 86400000);
    await supabase.from('posts').update({ 
      is_boosted: true,
      boost_expires: expires
    }).eq('id', postId);
    return true;
  }
  return false;
};

export const indicatePostToUser = async (postId: string, fromId: string, toId: string) => {
  const { data } = await supabase.from('posts').select('indicated_user_ids').eq('id', postId).single();
  if (!data) return false;

  const indicated = data.indicated_user_ids || [];
  if (indicated.includes(toId)) return false;

  indicated.push(toId);
  await supabase.from('posts').update({ indicated_user_ids: indicated }).eq('id', postId);

  createNotification({
    type: NotificationType.INDICATION,
    recipientId: toId,
    actorId: fromId,
    postId: postId,
    timestamp: Date.now()
  });
  return true;
};

