export const saveProducts = async (products: Product[]) => {
  // Simplificação: Upsert para salvar/atualizar
  // Em uso real, normalmente salvamos um por um ou em batch na criação
  for (const p of products) {
    // Se ID começa com 'prod-', é novo gerado localmente, removemos ID para o banco gerar (ou mantemos se formos consistentes)
    // Para simplificar, assumimos que se o ID não for UUID válido do banco, é insert
    const isNew = p.id.startsWith('prod-'); 

    const payload = {
      store_id: p.storeId,
      name: p.name,
      description: p.description,
      price: p.price,
      image_urls: p.imageUrls,
      affiliate_commission_rate: p.affiliateCommissionRate,
      type: p.type,
      digital_content_url: p.digitalContentUrl,
      is_dropshipping: p.isDropshipping,
      external_provider_id: p.externalProviderId,
      original_price: p.originalPrice
    };

    if (isNew) {
      await supabase.from('products').insert(payload);
    } else {
      await supabase.from('products').update(payload).eq('id', p.id);
    }
  }
};

