export const getCart = (): CartItem[] => {
  const cartJson = localStorage.getItem('cyberphone_cart');
  return cartJson ? JSON.parse(cartJson) : [];
};

export const saveCart = (cart: CartItem[]) => {
  localStorage.setItem('cyberphone_cart', JSON.stringify(cart));
};

export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existingItem = cart.find(item => item.productId === productId && item.selectedColor === selectedColor);
  if (existingItem) {
    existingItem.quantity += quantity;
  } else {
    cart.push({ productId, quantity, selectedColor });
  }
  saveCart(cart);
};

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) {
    cart = cart.filter(item => item.productId !== productId);
  } else {
    const item = cart.find(item => item.productId === productId);
    if (item) {
      item.quantity = quantity;
    }
  }
  saveCart(cart);
};

export const removeFromCart = (productId: string) => {
  const cart = getCart().filter(item => item.productId !== productId);
  saveCart(cart);
};

export const clearCart = () => saveCart([]);

export const getNotifications = async (): Promise<Notification[]> => {
  const userId = getCurrentUserId();
  if (!userId) return [];
  const { data } = await supabase.from('notifications').select('*').eq('recipient_id', userId);
  return (data || []).map((n: any) => ({
    id: n.id,
    recipientId: n.recipient_id,
    actorId: n.actor_id,
    type: n.type as NotificationType,
    postId: n.post_id,
    saleId: n.sale_id,
    isRead: n.is_read,
    timestamp: Number(n.timestamp)
  }));
};

export const createNotification = async (notificationData: Omit<Notification, 'id' | 'isRead'>) => {
  if (notificationData.recipientId === notificationData.actorId) return;

  await supabase.from('notifications').insert({
    recipient_id: notificationData.recipientId,
    actor_id: notificationData.actorId,
    type: notificationData.type,
    post_id: notificationData.postId,
    sale_id: notificationData.saleId,
    timestamp: notificationData.timestamp,
    is_read: false
  });
};

export const getNotificationsForUser = async (userId: string): Promise<Notification[]> => {
  const { data } = await supabase.from('notifications').select('*').eq('recipient_id', userId).order('timestamp', { ascending: false });
