// Login usando Supabase Auth real
export const loginUser = async (email: string, password: string): Promise<User> => {
  const { data: authData, error: authError } = await supabase.auth.signInWithPassword({
    email,
    password
  });

  if (authError) throw new Error(authError.message === 'Invalid login credentials' ? 'Credenciais inválidas.' : authError.message);

  if (authData.user) {
    const user = await findUserById(authData.user.id);
    if (user) {
      saveCurrentUser(user.id);
      return user;
    }
  }
  throw new Error('Perfil não encontrado.');
};

// Registro usando Supabase Auth real
export const registerUser = async (userData: any): Promise<User> => {
  const { data, error } = await supabase.auth.signUp({
    email: userData.email,
    password: userData.password,
    options: {
      data: {
        firstName: userData.firstName,
        lastName: userData.lastName,
        userType: userData.userType,
        phone: userData.phone,
        documentId: userData.documentId,
        birthDate: userData.birthDate,
        profilePicture: userData.profilePicture,
        credentials: userData.credentials,
        bio: userData.bio
      }
    }
  });

  if (error) throw new Error(error.message);

  // A trigger SQL (handle_new_user) irá criar o perfil na tabela 'profiles' automaticamente.
  // Aguardamos um pouco ou retornamos o objeto construído manualmente para a UI instantânea.
  if (data.user) {
    const newUser: User = {
      id: data.user.id,
      userType: userData.userType,
      firstName: userData.firstName,
      lastName: userData.lastName,
      email: userData.email,
      phone: userData.phone,
      documentId: userData.documentId,
      birthDate: userData.birthDate,
      profilePicture: userData.profilePicture,
      credentials: userData.credentials,
      bio: userData.bio,
      followedUsers: [],
      followers: [],
      balance: 0
    };
    saveCurrentUser(newUser.id);
    return newUser;
  }
  throw new Error('Falha no registro.');
};

// Upload
export const uploadFile = async (file: File | Blob, folder: string = 'general'): Promise<string> => {
  try {
    const fileExt = file instanceof File ? file.name.split('.').pop() : 'webm';
    const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;

    const { error } = await supabase.storage
      .from('cyber-files')
      .upload(fileName, file);

    if (error) throw error;

    const { data: { publicUrl } } = supabase.storage
      .from('cyber-files')
      .getPublicUrl(fileName);

    return publicUrl;
  } catch (error) {
    console.error('Erro no upload:', error);
    // Fallback para base64 se falhar (ex: storage não configurado)
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.readAsDataURL(file);
    });
  }
};

export const compressImage = async (base64OrFile: string | File): Promise<string> => {
  if (base64OrFile instanceof File) {
    return uploadFile(base64OrFile, 'images');
  }
  return Promise.resolve(base64OrFile);
};

