// ==============================================================================
// AUTH & USER
// ==============================================================================

export const getCurrentUserId = (): string | null => {
  return localStorage.getItem('cyberphone_current_user_id');
};

export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem('cyberphone_current_user_id', userId);
  else localStorage.removeItem('cyberphone_current_user_id');
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (!isSupabaseConfigured) return undefined;
  const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();
  if (error || !data) return undefined;

  // Buscar Store ID se for Creator
  let user = mapProfileToUser(data);
  if (user.userType === UserType.CREATOR) {
    const { data: store } = await supabase.from('stores').select('id').eq('professor_id', user.id).single();
    if (store) user.storeId = store.id;
  }
  return user;
};

export const getUsers = async (): Promise<User[]> => {
  const { data } = await supabase.from('profiles').select('*');
  return (data || []).map(mapProfileToUser);
};

export const updateUser = async (updatedUser: User): Promise<void> => {
  await supabase.from('profiles').update({
    first_name: updatedUser.firstName,
    last_name: updatedUser.lastName,
    bio: updatedUser.bio,
    credentials: updatedUser.credentials,
    profile_picture: updatedUser.profilePicture,
    birth_date: updatedUser.birthDate,
    phone: updatedUser.phone
  }).eq('id', updatedUser.id);
};

export const updateUserBalance = async (userId: string, amount: number): Promise<boolean> => {
  const user = await findUserById(userId);
  if (!user) return false;
  const newBalance = (user.balance || 0) + amount;

  const { error } = await supabase.from('profiles').update({ balance: newBalance }).eq('id', userId);
  return !error;
};

export const toggleFollowUser = async (currentUserId: string, targetUserId: string) => {
  const currentUser = await findUserById(currentUserId);
  const targetUser = await findUserById(targetUserId);

  if (!currentUser || !targetUser) return;

  let newFollowing = [...currentUser.followedUsers];
  let newFollowers = [...targetUser.followers];

  if (newFollowing.includes(targetUserId)) {
    // Unfollow
    newFollowing = newFollowing.filter(id => id !== targetUserId);
    newFollowers = newFollowers.filter(id => id !== currentUserId);
  } else {
    // Follow
    newFollowing.push(targetUserId);
    newFollowers.push(currentUserId);
    createNotification({
      type: NotificationType.NEW_FOLLOWER,
      recipientId: targetUserId,
      actorId: currentUserId,
      timestamp: Date.now()
    });
  }

  await supabase.from('profiles').update({ followed_users: newFollowing }).eq('id', currentUserId);
  await supabase.from('profiles').update({ followers: newFollowers }).eq('id', targetUserId);
};

