// POSTS & FEED
// ==============================================================================

export const getPosts = async (): Promise<Post[]> => {
  const { data, error } = await supabase
    .from('posts')
    .select('*, profiles!user_id(first_name, last_name, profile_picture)')
    .order('timestamp', { ascending: false });

  if (error) {
    console.error(error);
    return [];
  }

  const posts = await Promise.all((data || []).map(async (p) => {
    const post = mapPostFromDB(p);
    const { data: comments } = await supabase
      .from('comments')
      .select('*, profiles!user_id(first_name, last_name, profile_picture)')
      .eq('post_id', post.id);

    post.comments = (comments || []).map((c: any) => ({
      id: c.id,
      userId: c.user_id,
      userName: `${c.profiles.first_name} ${c.profiles.last_name}`,
      profilePic: c.profiles.profile_picture,
      text: c.text,
      timestamp: Number(c.timestamp)
    }));
    return post;
  }));

  return posts;
};

export const addPost = async (post: Post): Promise<void> => {
  await supabase.from('posts').insert({
    user_id: post.userId,
    type: post.type,
    content: post.content,
    image_url: post.imageUrl,
    timestamp: post.timestamp,
    live_data: post.liveStream,
    reel_data: post.reel,
    font_family: post.fontFamily,
    text_color: post.textColor,
    background_color: post.backgroundColor,
    font_size: post.fontSize
  });
};

export const updatePost = async (post: Post): Promise<void> => {
  await supabase.from('posts').update({
    content: post.content,
    image_url: post.imageUrl,
    live_data: post.liveStream,
    reel_data: post.reel,
    font_family: post.fontFamily,
    text_color: post.textColor,
    background_color: post.backgroundColor,
    font_size: post.fontSize,
    is_pinned: post.isPinned,
    is_boosted: post.isBoosted,
    boost_expires: post.boostExpires
  }).eq('id', post.id);
};

export const deletePost = async (postId: string): Promise<void> => {
  await supabase.from('posts').delete().eq('id', postId);
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('likes, user_id').eq('id', postId).single();
  if (!data) return;

  let likes: string[] = data.likes || [];
  if (likes.includes(userId)) {
    likes = likes.filter(id => id !== userId);
  } else {
    likes.push(userId);
    if (data.user_id !== userId) {
      createNotification({
        type: NotificationType.LIKE,
        recipientId: data.user_id,
        actorId: userId,
        postId: postId,
        timestamp: Date.now()
      });
    }
  }
  await supabase.from('posts').update({ likes }).eq('id', postId);
};

