export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  for (const item of cartItems) {
    const product = await findProductById(item.productId);
    if (!product) continue;
    const store = await findStoreById(product.storeId);
    if (!store) continue;

    const itemTotal = product.price * item.quantity;
    const commission = affiliateUserId ? itemTotal * product.affiliateCommissionRate : 0;
    const netRevenue = itemTotal - commission;

    await updateUserBalance(store.professorId, netRevenue);

    if (affiliateUserId && commission > 0) {
      await updateUserBalance(affiliateUserId, commission);
      createNotification({
        type: NotificationType.AFFILIATE_SALE,
        recipientId: affiliateUserId,
        actorId: buyerId,
        timestamp: Date.now()
      });
    }

    await supabase.from('sales').insert({
      product_id: product.id,
      buyer_id: buyerId,
      affiliate_user_id: affiliateUserId,
      store_id: store.id,
      commission_earned: commission,
      sale_amount: itemTotal,
      status: OrderStatus.WAITLIST,
      shipping_address: shippingAddress,
      timestamp: Date.now()
    });
  }
  return true;
};

export const addProductRating = async (saleId: string, rating: number, comment: string) => {
  await supabase.from('sales').update({ is_rated: true }).eq('id', saleId);

  const { data: sale } = await supabase.from('sales').select('product_id').eq('id', saleId).single();
  if (sale) {
     const product = await findProductById(sale.product_id);
     if (product) {
       const newCount = product.ratingCount + 1;
       const newAvg = ((product.averageRating * product.ratingCount) + rating) / newCount;
       await supabase.from('products').update({ 
         average_rating: newAvg,
         rating_count: newCount 
       }).eq('id', sale.product_id);
     }
  }
  return true;
};

