export const getChats = async (): Promise<ChatConversation[]> => {
  const { data: convs } = await supabase.from('conversations').select('*');
  const chats: ChatConversation[] = [];

  for (const c of (convs || [])) {
    const { data: msgs } = await supabase.from('messages').select('*').eq('conversation_id', c.id).order('timestamp', { ascending: true });
    chats.push({
      id: c.id,
      participants: c.participants,
      messages: (msgs || []).map((m: any) => ({
        id: m.id,
        senderId: m.sender_id,
        receiverId: m.receiver_id,
        text: m.text,
        imageUrl: m.image_url,
        timestamp: Number(m.timestamp)
      }))
    });
  }
  return chats;
};

export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const { data } = await supabase.from('conversations').select('*').contains('participants', [u1, u2]);
  if (data && data.length > 0) {
    const chat = data[0];
    const { data: msgs } = await supabase.from('messages').select('*').eq('conversation_id', chat.id);
    return {
      id: chat.id,
      participants: chat.participants,
      messages: (msgs || []).map((m: any) => ({
        id: m.id,
        senderId: m.sender_id,
        receiverId: m.receiver_id,
        text: m.text,
        imageUrl: m.image_url,
        timestamp: Number(m.timestamp)
      }))
    };
  }

  const { data: newChat, error } = await supabase.from('conversations').insert({
    participants: [u1, u2]
  }).select().single();

  if (error || !newChat) throw new Error('Failed to create chat');

  return { id: newChat.id, participants: newChat.participants, messages: [] };
};

