import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Message } from '../types';
import { getPosts, findUserById, updateUserBalance, deletePost, getGlobalSettings } from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  XMarkIcon,
  HandRaisedIcon,
  SignalIcon,
  UsersIcon,
  ComputerDesktopIcon,
  PowerIcon,
  BanknotesIcon,
  PaperAirplaneIcon,
  SparklesIcon,
  PlayIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedIconOutline,
  ChatBubbleLeftRightIcon as ChatIconOutline,
  ComputerDesktopIcon as ScreenIconOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(false);
  const [isCamOn, setIsCamOn] = useState(false);
  const [isScreenSharing, setIsScreenSharing] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  const [activeSidebar, setActiveSidebar] = useState<'chat' | null>(null);
  const [handRaised, setHandRaised] = useState(false);

  const [chatMessages, setChatMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax;

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        streamRef.current?.removeTrack(track);
      });
      streamRef.current = null;
    }
  }, []);

  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
      setIsScreenSharing(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  const toggleMic = async () => {
    if (isMicOn) {
      if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsMicOn(false);
    } else {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const audioTrack = audioStream.getAudioTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.addTrack(audioTrack);
        setIsMicOn(true);
      } catch (err) { alert("Microfone indisponível."); }
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) { alert("Saldo insuficiente."); return; }
    setIsProcessingDonation(true);
    setTimeout(() => {
      updateUserBalance(currentUser.id, -pendingAmount);
      updateUserBalance(creator.id, pendingAmount * (1 - platformTax));
      refreshUser();
      setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });
      setTimeout(() => setDonationAlert(null), 5000);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
    }, 1000);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  return (
    <div className="fixed inset-0 bg-[#020408] z-[60] flex flex-col overflow-hidden text-white font-sans animate-fade-in">

      {/* HEADER BAR */}
      <nav className="w-full flex items-center justify-between px-4 py-2 md:px-6 md:py-4 z-50 flex-shrink-0 bg-gradient-to-b from-black/80 to-transparent">
        <button 
          onClick={handleExit} 
          className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/10 transition-all"
        >
          <XMarkIcon className="h-6 w-6" />
        </button>

        <div className="flex flex-col items-center">
           <div className="bg-red-600 px-3 py-1 rounded-full text-[8px] md:text-[10px] font-black flex items-center gap-1.5 shadow-[0_0_15px_rgba(220,38,38,0.4)] animate-pulse border border-red-500/50 uppercase">
             <SignalIcon className="h-3 w-3" /> AO VIVO
           </div>
           <p className="text-[10px] md:text-[11px] font-black uppercase mt-1 text-white/50">{post.liveStream.title}</p>
        </div>

        <div className="flex items-center gap-2">
           {isProfessional && (
             <button onClick={() => { if(window.confirm("Encerrar aula?")) { deletePost(post.id); handleExit(); refreshUser(); } }} className="bg-red-600 p-3 rounded-2xl shadow-lg border border-red-500 active:scale-90 transition-all"><PowerIcon className="h-5 w-5" /></button>
           )}
           <div className="flex items-center gap-2 bg-white/5 px-4 py-2.5 rounded-2xl border border-white/10">
              <UsersIcon className="h-4 w-4 text-blue-400" />
              <span className="text-xs font-black">1.2k</span>
           </div>
        </div>
      </nav>

      {/* ÁREA DO VÍDEO */}
      <main className="flex-1 flex relative items-center justify-center p-2 md:p-8">
        <div className="w-full h-full max-w-6xl rounded-[2rem] md:rounded-[4rem] overflow-hidden bg-black border-2 border-white/5 relative shadow-2xl group">
          {isCamOn ? (
            <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
          ) : (
            <div className="flex flex-col items-center justify-center h-full">
               <div className="w-32 h-32 md:w-48 md:h-48 rounded-[3rem] bg-white/5 flex items-center justify-center text-4xl md:text-8xl font-black border border-white/10 opacity-30">
                  {creator.firstName[0]}
               </div>
               <p className="mt-8 font-black uppercase tracking-[0.3em] text-xs text-white/10 animate-pulse">Aguardando Câmara</p>
            </div>
          )}

          {donationAlert && (
            <div className="absolute top-10 left-1/2 -translate-x-1/2 z-[100] animate-shoutout">
               <div className="bg-gradient-to-r from-yellow-400 to-amber-600 p-[1.5px] rounded-full shadow-[0_0_40px_rgba(245,158,11,0.5)]">
                  <div className="bg-black/90 backdrop-blur-3xl px-8 py-3 rounded-full flex items-center gap-4">
                     <SparklesIcon className="h-6 w-6 text-yellow-500" />
                     <p className="text-sm md:text-lg font-black text-white whitespace-nowrap">
                        {donationAlert.name} <span className="text-green-400">APOIOU COM ${donationAlert.amount}</span>
                     </p>
                  </div>
               </div>
            </div>
          )}

          {/* CONTROLES */}
          <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/40 backdrop-blur-3xl p-4 rounded-[2.5rem] border border-white/10 z-40 shadow-2xl opacity-0 group-hover:opacity-100 transition-opacity">
             <button onClick={toggleMic} className={`p-4 rounded-3xl transition-all ${isMicOn ? 'bg-blue-600 text-white' : 'bg-white/5 text-white/40'}`}>
                {isMicOn ? <MicrophoneIcon className="h-6 w-6" /> : <MicrophoneIconOutline className="h-6 w-6" />}
             </button>
             <button onClick={toggleCamera} className={`p-4 rounded-3xl transition-all ${isCamOn ? 'bg-blue-600 text-white' : 'bg-white/5 text-white/40'}`}>
                {isCamOn ? <VideoCameraIcon className="h-6 w-6" /> : <VideoCameraIconOutline className="h-6 w-6" />}
             </button>
             <button onClick={() => setShowDonationModal(true)} className="p-4 bg-yellow-500 text-black rounded-3xl font-black uppercase text-[10px] tracking-widest shadow-xl">Apoiar</button>
          </div>
        </div>
      </main>

      {/* MODAL APOIO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-[#12141c] w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/5" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter text-center mb-8">Apoiar Mestre</h3>
              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button key={val} onClick={() => setPendingAmount(val)} className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-500'}`}>${val}</button>
                 ))}
              </div>
              <button onClick={executeDonation} disabled={!pendingAmount || isProcessingDonation} className="w-full bg-blue-600 text-white py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl transition-all active:scale-95">
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      <style>{`
        @keyframes shoutout { 0% { transform: translate(-50%, -100%); opacity: 0; } 15% { transform: translate(-50%, 0); opacity: 1; } 85% { transform: translate(-50%, 0); opacity: 1; } 100% { transform: translate(-50%, -100%); opacity: 0; } }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

import React, { useState, useEffect, useCallback } from 'react';
import { User, CartItem, GlobalSettings } from './types';
import {
    getCurrentUserId,
    findUserById,
    saveCurrentUser,
    getNotificationsForUser,
    markNotificationsAsRead,
    getCart,
    addToCart,
    removeFromCart,
    updateCartItemQuantity,
    clearCart,
    deleteUser,
    getGlobalSettings
} from './services/storageService';
import Header from './components/Header';
import Footer from './components/Footer';
import AuthPage from './components/AuthPage';
import FeedPage from './components/FeedPage';
import ProfilePage from './components/ProfilePage';
import ChatPage from './components/ChatPage';
import AdCampaignPage from './components/AdCampaignPage';
import LiveStreamViewer from './components/LiveStreamViewer';
import { StorePage } from './components/StorePage';
import StoreManagerPage from './components/StoreManagerPage';
import CreatePost from './components/CreatePost';
import ReelsPage from './components/ReelsPage';
import SearchResultsPage from './components/SearchResultsPage';
import NotificationsPage from './components/NotificationsPage';
import CartModal from './components/CartModal';
import WalletModal from './components/WalletModal';
import ReportUserPage from './components/ReportUserPage';
import SettingsPage from './components/SettingsPage';
import AdminDashboard from './components/AdminDashboard';
import EventsPage from './components/EventsPage';
import PurchasesPage from './components/PurchasesPage';
import AffiliatesPage from './components/AffiliatesPage';
import Logo from './components/Logo';
import { WrenchScrewdriverIcon, BoltIcon } from '@heroicons/react/24/solid';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'manage-store' | 'edit-post' | 'create-post' | 'reels-page' | 'search-results' | 'notifications' | 'report-user' | 'settings' | 'admin' | 'events' | 'purchases' | 'affiliates';

const App: React.FC = () => {
    const [darkMode, setDarkMode] = useState(() => localStorage.getItem('cyberphone_theme') === 'dark');
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [currentPage, setCurrentPage] = useState<Page>('auth');
    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    const [cartItems, setCartItems] = useState<CartItem[]>(getCart());
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });
    const [settings, setSettings] = useState<GlobalSettings>(() => getGlobalSettings());
    const [isLoading, setIsLoading] = useState(true);

    const toggleTheme = useCallback(() => {
        setDarkMode(prev => {
            const newVal = !prev;
            localStorage.setItem('cyberphone_theme', newVal ? 'dark' : 'light');
            return newVal;
        });
    }, []);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    const refreshCurrentUser = useCallback(async () => {
        const userId = getCurrentUserId();
        const freshSettings = getGlobalSettings();
        setSettings(freshSettings);

        if (userId) {
            const user = await findUserById(userId);
            if (user) {
                setCurrentUser(user);
                const notifications = await getNotificationsForUser(user.id);
                setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
                if (currentPage === 'auth') setCurrentPage('feed');
            } else {
                saveCurrentUser(null);
                setCurrentUser(null);
                setCurrentPage('auth');
            }
        } else {
            setCurrentUser(null);
            setUnreadNotificationsCount(0);
            setCurrentPage('auth');
        }
        setIsLoading(false);
    }, [currentPage]);

    const refreshCart = useCallback(() => {
        setCartItems(getCart());
    }, []);

    useEffect(() => {
        refreshCurrentUser();
        refreshCart();
    }, []);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        setCurrentPage('feed');
    }, []);

    const handleLogout = useCallback(() => {
        setCurrentUser(null);
        saveCurrentUser(null);
        setCurrentPage('auth');
        clearCart();
        refreshCart();
    }, [refreshCart]);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
        }
        setCurrentPage(page);
        setPageParams(params);
        setIsMenuOpen(false); // Fecha o menu lateral ao navegar
        window.scrollTo(0, 0);
    }, [currentUser, refreshCurrentUser]);

    const handleAddToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
        addToCart(productId, quantity, selectedColor);
        refreshCart();
    };

    if (isLoading) {
        return <div className="h-screen w-full flex items-center justify-center bg-gray-50 dark:bg-[#0a0c10]"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-600"></div></div>;
    }

    if (settings?.maintenanceMode && !currentUser?.isAdmin) {
        return (
            <div className="min-h-screen bg-[#0a0c10] text-white flex flex-col items-center justify-center p-8 text-center animate-fade-in">
                <Logo size="xl" variant="white" className="mb-12 justify-center" />
                <WrenchScrewdriverIcon className="h-16 w-16 text-blue-500 mx-auto mb-6 animate-bounce" />
                <h2 className="text-3xl font-black uppercase tracking-tighter mb-4">Manutenção Root</h2>
                <p className="text-gray-400 font-medium text-sm">O sistema está sendo otimizado. Voltamos em breve.</p>
                <button onClick={() => window.location.reload()} className="mt-8 text-gray-500 hover:text-white transition-colors text-[10px] font-black uppercase tracking-[0.3em]">Recarregar</button>
            </div>
        );
    }

    if (currentPage === 'admin' && currentUser?.isAdmin) {
        return <AdminDashboard currentUser={currentUser} onNavigate={handleNavigate} onRefreshUser={refreshCurrentUser} />;
    }

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={toggleTheme} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={() => { deleteUser(currentUser.id); handleLogout(); }} />;
            case 'ads': return <AdCampaignPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'events': return <EventsPage currentUser={currentUser} />;
            case 'purchases': return <PurchasesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'live':
                return pageParams.postId 
                    ? <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />
                    : <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={handleAddToCart} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'manage-store': return <StoreManagerPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'create-post': return <CreatePost currentUser={currentUser} onPostCreated={() => handleNavigate('feed')} refreshUser={refreshCurrentUser} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query || ''} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'report-user': return <ReportUserPage currentUser={currentUser} targetUserId={pageParams.userId} onNavigate={handleNavigate} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300 w-full overflow-x-hidden">
            <Header 
              currentUser={currentUser} 
              onNavigate={handleNavigate} 
              unreadNotificationsCount={unreadNotificationsCount} 
              cartItemCount={cartItems.reduce((sum, item) => sum + item.quantity, 0)} 
              onOpenCart={() => setIsCartModalOpen(true)} 
              onToggleMenu={() => setIsMenuOpen(!isMenuOpen)}
            />
            <div className="flex flex-1 w-full overflow-x-hidden">
                {currentUser && (
                  <Footer 
                    currentUser={currentUser} 
                    onNavigate={handleNavigate} 
                    activePage={currentPage} 
                    onLogout={handleLogout} 
                    isMenuOpen={isMenuOpen}
                    onCloseMenu={() => setIsMenuOpen(false)}
                  />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[72px] md:pb-8 transition-all duration-300 w-full ${currentUser ? 'md:ml-64 px-0 md:px-8' : 'px-0'}`}>
                    <div className="max-w-7xl mx-auto w-full">{renderPage()}</div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={refreshCart} refreshUser={refreshCurrentUser} />
                <WalletModal isOpen={walletConfig.isOpen} mode={walletConfig.mode} onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })} currentUser={currentUser} refreshUser={refreshCurrentUser} />
              </>
            )}
        </div>
    );
};

export default App;

