  const [storeAffiliateSales, setStoreAffiliateSales] = useState<AffiliateSale[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [copiedLink, setCopiedLink] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
        setLoading(true);
        const mySales = await getSalesByAffiliateId(currentUser.id);
        setMyAffiliateSales(mySales);

        const products = await getProducts();
        setAllProducts(products);

        if (currentUser.userType === UserType.CREATOR && currentUser.storeId) {
            const storeSales = await getSalesByStoreId(currentUser.storeId);
            setStoreAffiliateSales(storeSales);
