export const getStores = async (): Promise<Store[]> => { const {data} = await supabase.from('stores').select('*'); return (data||[]).map(mapStoreFromDB); };
export const findStoreById = async (id: string): Promise<Store | undefined> => { const {data} = await supabase.from('stores').select('*').eq('id', id).single(); return data ? mapStoreFromDB(data) : undefined; };
export const updateStore = async (s: Store) => { await supabase.from('stores').update({name: s.name, description: s.description, brand_color: s.brandColor}).eq('id', s.id); };
export const getProducts = async (): Promise<Product[]> => { const {data} = await supabase.from('products').select('*'); return (data||[]).map(mapProductFromDB); };
export const findProductById = async (id: string): Promise<Product | undefined> => { const {data} = await supabase.from('products').select('*').eq('id', id).single(); return data ? mapProductFromDB(data) : undefined; };
export const saveProducts = async (products: Product[]) => { for(const p of products) { const isNew = p.id.startsWith('prod-'); const py = { store_id: p.storeId, name: p.name, description: p.description, price: p.price, image_urls: p.imageUrls, affiliate_commission_rate: p.affiliateCommissionRate, type: p.type, digital_content_url: p.digitalContentUrl, is_dropshipping: p.isDropshipping, external_provider_id: p.externalProviderId, original_price: p.originalPrice }; if(isNew) await supabase.from('products').insert(py); else await supabase.from('products').update(py).eq('id', p.id); } };
export const getAffiliateSales = async (): Promise<AffiliateSale[]> => { const {data} = await supabase.from('sales').select('*'); return (data||[]).map((s:any)=>({id: s.id, productId: s.product_id, buyerId: s.buyer_id, affiliateUserId: s.affiliate_user_id||'', storeId: s.store_id, commissionEarned: s.commission_earned, saleAmount: s.sale_amount, timestamp: Number(s.timestamp), status: s.status, isRated: s.is_rated, shippingAddress: s.shipping_address})); };
export const getPurchasesByBuyerId = async (uid: string) => { const s = await getAffiliateSales(); return s.filter(x => x.buyerId === uid); };
export const getSalesByAffiliateId = async (uid: string) => { const s = await getAffiliateSales(); return s.filter(x => x.affiliateUserId === uid); };
export const getSalesByStoreId = async (sid: string) => { const s = await getAffiliateSales(); return s.filter(x => x.storeId === sid); };
export const updateSaleStatus = async (sid: string, st: OrderStatus) => { await supabase.from('sales').update({status: st}).eq('id', sid); };
export const processProductPurchase = async (cart: CartItem[], buyer: string, affiliate: string|null, addr?: ShippingAddress) => { for(const i of cart) { const p = await findProductById(i.productId); if(!p) continue; const s = await findStoreById(p.storeId); if(!s) continue; const total = p.price * i.quantity; const comm = affiliate ? total * p.affiliateCommissionRate : 0; const net = total - comm; await updateUserBalance(s.professorId, net); if(affiliate && comm > 0) { await updateUserBalance(affiliate, comm); createNotification({type: NotificationType.AFFILIATE_SALE, recipientId: affiliate, actorId: buyer, timestamp: Date.now()}); } await supabase.from('sales').insert({product_id: p.id, buyer_id: buyer, affiliate_user_id: affiliate, store_id: s.id, commission_earned: comm, sale_amount: total, status: OrderStatus.WAITLIST, shipping_address: addr, timestamp: Date.now()}); } return true; };
export const addProductRating = async (sid: string, r: number, c: string) => { await supabase.from('sales').update({is_rated: true}).eq('id', sid); const {data:s} = await supabase.from('sales').select('product_id').eq('id', sid).single(); if(s) { const p = await findProductById(s.product_id); if(p) { await supabase.from('products').update({average_rating: ((p.averageRating*p.ratingCount)+r)/(p.ratingCount+1), rating_count: p.ratingCount+1}).eq('id', p.id); } } return true; };
export const saveAffiliateLink = (u: string, p: string, l: string) => { const links = JSON.parse(localStorage.getItem('cyber_affiliate_links') || '[]'); links.push({ u, p, l, t: Date.now() }); localStorage.setItem('cyber_affiliate_links', JSON.stringify(links)); };

