                               <div>
                                  <p className="font-black text-sm uppercase">Modo Manutenção</p>
                                  <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Trava acesso de membros</p>
                               </div>
                            </div>
                            <button type="button" onClick={() => setSettings({...settings, maintenanceMode: !settings.maintenanceMode})} className={`w-14 h-8 rounded-full relative transition-all ${settings.maintenanceMode ? 'bg-red-600' : 'bg-gray-700'}`}>
                               <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${settings.maintenanceMode ? 'right-1' : 'left-1'}`}></div>
                            </button>
                         </div>
                         <button type="submit" className="w-full py-6 bg-blue-600 hover:bg-blue-700 text-white rounded-[2rem] font-black uppercase text-sm tracking-[0.2em] shadow-xl transition-all active:scale-95">Salvar Root</button>
                      </form>
                   </div>
                </div>
             )}
