                   </div>
                 )}

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Biografia</label>
                    <textarea value={bio} onChange={e => setBio(e.target.value)} placeholder="Conte um pouco sobre você..." className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-[2rem] dark:text-white outline-none border-2 border-transparent focus:border-blue-500 font-medium h-32 resize-none" />
                 </div>
              </div>
           </div>

           <div className="bg-gray-100/50 dark:bg-white/[0.02] p-8 rounded-[3rem] border-2 border-dashed border-gray-200 dark:border-white/10">
              <div className="flex items-center justify-between mb-6">
                 <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Dados de Segurança (Imutáveis)</p>
                 <div className="bg-blue-600/10 text-blue-600 px-3 py-1 rounded-lg flex items-center gap-2">
                    <ShieldCheckIcon className="h-3 w-3" />
                    <span className="text-[8px] font-black uppercase">Verificado</span>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Endereço de E-mail</label>
                    <div className="relative">
                       <EnvelopeIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                       <input type="text" disabled value={currentUser.email} className="w-full p-4 pl-12 bg-white dark:bg-white/5 rounded-2xl text-gray-400 dark:text-gray-500 font-bold cursor-not-allowed border border-gray-100 dark:border-white/5" />
                       <LockClosedIcon className="h-4 w-4 absolute right-4 top-1/2 -translate-y-1/2 text-gray-300 opacity-50" />
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Telefone</label>
                    <div className="relative">
                       <PhoneIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-300" />
                       <input type="text" disabled value={currentUser.phone} className="w-full p-4 pl-12 bg-white dark:bg-white/5 rounded-2xl text-gray-400 dark:text-gray-500 font-bold cursor-not-allowed border border-gray-100 dark:border-white/5" />
                       <LockClosedIcon className="h-4 w-4 absolute right-4 top-1/2 -translate-y-1/2 text-gray-300 opacity-50" />
                    </div>
                 </div>
              </div>
           </div>

           <button 
             type="submit" 
             disabled={isSaving || isUploading} 
             className="w-full py-6 bg-blue-600 hover:bg-blue-700 text-white rounded-[2.2rem] font-black uppercase text-sm tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
           >
             {isSaving ? (
               <div className="w-5 h-5 border-3 border-white border-t-transparent animate-spin rounded-full"></div>
             ) : (
               <><CheckIcon className="h-6 w-6 stroke-[3]" /> Persistir Alterações</>
             )}
           </button>
        </form>
      </div>
    );
  }

  // Visualização de pagamentos
  if (view === 'payments') {
    return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
          <div className="flex items-center gap-6 mb-10">
            <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-blue-600 transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
            <h2 className="text-4xl font-black dark:text-white tracking-tighter">CyBer Card Pro</h2>
          </div>

          <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10 space-y-10 text-center">
             <div className="bg-gradient-to-br from-[#1e293b] to-[#020617] p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden aspect-[1.6/1] flex flex-col justify-between opacity-60">
                <p className="text-lg md:text-xl font-mono tracking-[0.3em] text-white/20 mt-12">COMING SOON</p>
                <div className="absolute inset-0 flex items-center justify-center">
                   <div className="bg-blue-600/90 text-white px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-[0.2em] shadow-2xl">Em Desenvolvimento</div>
                </div>
             </div>
             <button onClick={handleJoinWaitlist} className="w-full py-6 bg-blue-600 hover:bg-blue-700 text-white rounded-[2.2rem] font-black uppercase text-sm shadow-xl transition-all">Entrar na Lista VIP</button>
          </div>
        </div>
    );
  }

  const sections = [
    {
      title: 'Identidade Digital',
      items: [
        { label: 'Editar Perfil', desc: 'Nome, bio, foto e nascimento', icon: UserIcon, onClick: () => setView('edit-profile') },
        { label: 'Visual e Estilo', desc: 'Modo Escuro / Claro', icon: PaintBrushIcon, toggle: darkMode, onToggle: toggleTheme, onClick: () => {} }
      ]
    },
    {
      title: 'Finanças e Segurança',
      items: [
        { label: 'CyBer Card Pro', desc: 'Conta virtual (Beta)', icon: CreditCardIcon, onClick: () => setView('payments') },
        { label: 'Sair da Conta', desc: 'Desconectar dispositivo', icon: ArrowRightOnRectangleIcon, onClick: onLogout }
      ]
