const mapProfileToUser = (profile: any): User => ({
  id: profile.id,
  email: profile.email || '',
  userType: (profile.user_type as UserType) || UserType.STANDARD,
  firstName: profile.first_name || '',
  lastName: profile.last_name || '',
  phone: profile.phone || '',
  documentId: profile.document_id || '',
  birthDate: Number(profile.birth_date) || 0,
  profilePicture: profile.profile_picture || DEFAULT_PROFILE_PIC,
  balance: profile.balance || 0,
  credentials: profile.credentials,
  bio: profile.bio,
  isAdmin: profile.is_admin,
  isVerified: profile.is_verified,
  isSuspended: profile.is_suspended,
  isPremium: profile.is_premium,
  premiumExpiry: profile.premium_expiry,
  followers: profile.followers || [],
  followedUsers: profile.followed_users || [],
  storeId: undefined
});

const mapPostFromDB = (post: any): Post => ({
  id: post.id,
  userId: post.user_id,
  authorName: post.profiles ? `${post.profiles.first_name} ${post.profiles.last_name}` : 'Usuário Desconhecido',
  authorProfilePic: post.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
  type: post.type,
  timestamp: Number(post.timestamp) || new Date(post.created_at).getTime(),
  content: post.content,
  imageUrl: post.image_url,
  fontFamily: post.font_family,
  textColor: post.text_color,
  fontSize: post.font_size,
  backgroundColor: post.background_color,
  isBoosted: post.is_boosted,
  boostExpires: Number(post.boost_expires),
  likes: post.likes || [],
  shares: post.shares || [],
  saves: post.saves || [],
  isPinned: post.is_pinned,
  indicatedUserIds: post.indicated_user_ids || [],
  liveStream: post.live_data,
  reel: post.reel_data,
  comments: [] 
});

const mapProductFromDB = (prod: any): Product => ({
  id: prod.id,
  storeId: prod.store_id,
  name: prod.name,
  description: prod.description,
  price: prod.price,
  imageUrls: prod.image_urls || [],
  affiliateCommissionRate: prod.affiliate_commission_rate,
  type: prod.type,
  averageRating: prod.average_rating || 5,
  ratingCount: prod.rating_count || 0,
  digitalContentUrl: prod.digital_content_url,
  isDropshipping: prod.is_dropshipping,
  externalProviderId: prod.external_provider_id,
  originalPrice: prod.original_price,
  ratings: []
});

const mapStoreFromDB = (store: any): Store => ({
  id: store.id,
  professorId: store.professor_id,
  name: store.name,
  description: store.description,
  brandColor: store.brand_color,
  productIds: []
});

// ==============================================================================
// AUTH & USER (ATUALIZADO)
// ==============================================================================

export const getCurrentUserId = (): string | null => localStorage.getItem('cyberphone_current_user_id');
export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem('cyberphone_current_user_id', userId);
  else localStorage.removeItem('cyberphone_current_user_id');
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (!isSupabaseConfigured) return undefined;
  const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();
  if (error || !data) return undefined;
  let user = mapProfileToUser(data);
  if (user.userType === UserType.CREATOR) {
    const { data: store } = await supabase.from('stores').select('id').eq('professor_id', user.id).single();
    if (store) user.storeId = store.id;
  }
  return user;
};

export const getUsers = async (): Promise<User[]> => {
  const { data } = await supabase.from('profiles').select('*');
  return (data || []).map(mapProfileToUser);
};

export const updateUser = async (updatedUser: User): Promise<void> => {
  await supabase.from('profiles').update({
    first_name: updatedUser.firstName,
    last_name: updatedUser.lastName,
    bio: updatedUser.bio,
    credentials: updatedUser.credentials,
    profile_picture: updatedUser.profilePicture,
    birth_date: updatedUser.birthDate,
    phone: updatedUser.phone
  }).eq('id', updatedUser.id);
};

export const deleteUser = async (userId: string): Promise<void> => {
  // Nota: Apenas deleta o perfil público. A conta de Auth do Supabase requer Service Role para deletar via cliente.
  // Isso remove o usuário da "Rede Social".
  await supabase.from('profiles').delete().eq('id', userId);
};

// ==============================================================================
// POSTS (Resumo)
// ==============================================================================
export const getPosts = async (): Promise<Post[]> => {
  const { data } = await supabase.from('posts').select('*, profiles!user_id(first_name, last_name, profile_picture)').order('timestamp', { ascending: false });
  return await Promise.all((data || []).map(async (p) => {
    const post = mapPostFromDB(p);
    const { data: comments } = await supabase.from('comments').select('*, profiles!user_id(first_name, last_name, profile_picture)').eq('post_id', post.id);
    post.comments = (comments || []).map((c: any) => ({
      id: c.id, userId: c.user_id, userName: `${c.profiles.first_name} ${c.profiles.last_name}`, profilePic: c.profiles.profile_picture, text: c.text, timestamp: Number(c.timestamp)
    }));
    return post;
  }));
};
export const addPost = async (post: Post) => { await supabase.from('posts').insert({ user_id: post.userId, type: post.type, content: post.content, image_url: post.imageUrl, timestamp: post.timestamp, live_data: post.liveStream, reel_data: post.reel, font_family: post.fontFamily, text_color: post.textColor, background_color: post.backgroundColor, font_size: post.fontSize }); };
export const updatePost = async (post: Post) => { await supabase.from('posts').update({ content: post.content, image_url: post.imageUrl, live_data: post.liveStream, reel_data: post.reel, font_family: post.fontFamily, text_color: post.textColor, background_color: post.backgroundColor, font_size: post.fontSize, is_pinned: post.isPinned, is_boosted: post.isBoosted, boost_expires: post.boostExpires }).eq('id', post.id); };
export const deletePost = async (postId: string) => { await supabase.from('posts').delete().eq('id', postId); };
export const updatePostLikes = async (postId: string, userId: string) => { const { data } = await supabase.from('posts').select('likes, user_id').eq('id', postId).single(); if (!data) return; let likes = data.likes || []; if (likes.includes(userId)) likes = likes.filter((id: string) => id !== userId); else { likes.push(userId); if(data.user_id !== userId) createNotification({type: NotificationType.LIKE, recipientId: data.user_id, actorId: userId, postId, timestamp: Date.now()}); } await supabase.from('posts').update({ likes }).eq('id', postId); };
export const updatePostSaves = async (p: string, u: string) => { const {data} = await supabase.from('posts').select('saves').eq('id', p).single(); if(!data) return; let s = data.saves||[]; if(s.includes(u)) s=s.filter((i:string)=>i!==u); else s.push(u); await supabase.from('posts').update({saves:s}).eq('id', p); };
export const updatePostShares = async (p: string, u: string) => { const {data} = await supabase.from('posts').select('shares').eq('id', p).single(); if(!data) return; let s = data.shares||[]; if(!s.includes(u)) { s.push(u); await supabase.from('posts').update({shares:s}).eq('id', p); } };
export const addPostComment = async (pId: string, c: Comment) => { await supabase.from('comments').insert({ post_id: pId, user_id: c.userId, text: c.text, timestamp: c.timestamp }); const {data} = await supabase.from('posts').select('user_id').eq('id', pId).single(); if(data && data.user_id !== c.userId) createNotification({type: NotificationType.COMMENT, recipientId: data.user_id, actorId: c.userId, postId: pId, timestamp: Date.now()}); };
export const pinPost = async (p: string, u: string) => { await supabase.from('posts').update({is_pinned: false}).eq('user_id', u); await supabase.from('posts').update({is_pinned: true}).eq('id', p); return true; };
export const unpinPost = async (p: string, u: string) => { await supabase.from('posts').update({is_pinned: false}).eq('id', p); return true; };
export const boostPost = async (p: string, u: string, b: number, d: number) => { if(await updateUserBalance(u, -b)) { await supabase.from('posts').update({is_boosted: true, boost_expires: Date.now()+(d*86400000)}).eq('id', p); return true; } return false; };
export const indicatePostToUser = async (p: string, f: string, t: string) => { const {data} = await supabase.from('posts').select('indicated_user_ids').eq('id', p).single(); if(!data) return false; const i = data.indicated_user_ids||[]; if(i.includes(t)) return false; i.push(t); await supabase.from('posts').update({indicated_user_ids: i}).eq('id', p); createNotification({type: NotificationType.INDICATION, recipientId: t, actorId: f, postId: p, timestamp: Date.now()}); return true; };

