// ==============================================================================
export const getCart = (): CartItem[] => { return JSON.parse(localStorage.getItem('cyberphone_cart') || '[]'); };
export const saveCart = (c: CartItem[]) => localStorage.setItem('cyberphone_cart', JSON.stringify(c));
export const addToCart = (pid: string, q: number=1, c?: string) => { const cart=getCart(); const ex=cart.find(i=>i.productId===pid && i.selectedColor===c); if(ex) ex.quantity+=q; else cart.push({productId:pid, quantity:q, selectedColor:c}); saveCart(cart); };
export const updateCartItemQuantity = (pid: string, q: number) => { let cart=getCart(); if(q<=0) cart=cart.filter(i=>i.productId!==pid); else { const i=cart.find(x=>x.productId===pid); if(i) i.quantity=q; } saveCart(cart); };
export const removeFromCart = (pid: string) => saveCart(getCart().filter(i=>i.productId!==pid));
export const clearCart = () => saveCart([]);
export const getNotifications = async (): Promise<Notification[]> => { const uid=getCurrentUserId(); if(!uid) return []; const {data} = await supabase.from('notifications').select('*').eq('recipient_id', uid); return (data||[]).map((n:any)=>({id: n.id, recipientId: n.recipient_id, actorId: n.actor_id, type: n.type, postId: n.post_id, saleId: n.sale_id, isRead: n.is_read, timestamp: Number(n.timestamp)})); };
export const createNotification = async (n: any) => { if(n.recipientId===n.actorId) return; await supabase.from('notifications').insert({recipient_id: n.recipientId, actor_id: n.actorId, type: n.type, post_id: n.postId, sale_id: n.saleId, timestamp: n.timestamp, is_read: false}); };
export const getNotificationsForUser = async (uid: string) => { const {data} = await supabase.from('notifications').select('*').eq('recipient_id', uid).order('timestamp', {ascending: false}); return (data||[]).map((n:any)=>({id: n.id, recipientId: n.recipient_id, actorId: n.actor_id, type: n.type, postId: n.post_id, saleId: n.sale_id, isRead: n.is_read, timestamp: Number(n.timestamp)})); };
export const markNotificationsAsRead = async (uid: string) => { await supabase.from('notifications').update({is_read: true}).eq('recipient_id', uid); };
export const getChats = async (): Promise<ChatConversation[]> => { const {data:cs} = await supabase.from('conversations').select('*'); const chats: ChatConversation[] = []; for(const c of (cs||[])) { const {data:ms} = await supabase.from('messages').select('*').eq('conversation_id', c.id).order('timestamp', {ascending: true}); chats.push({id: c.id, participants: c.participants, messages: (ms||[]).map((m:any)=>({id: m.id, senderId: m.sender_id, receiverId: m.receiver_id, text: m.text, imageUrl: m.image_url, timestamp: Number(m.timestamp)}))}); } return chats; };
export const getOrCreateConversation = async (u1: string, u2: string) => { const {data} = await supabase.from('conversations').select('*').contains('participants', [u1, u2]); if(data && data.length>0) { const c=data[0]; const {data:ms} = await supabase.from('messages').select('*').eq('conversation_id', c.id); return {id: c.id, participants: c.participants, messages: (ms||[]).map((m:any)=>({id: m.id, senderId: m.sender_id, receiverId: m.receiver_id, text: m.text, imageUrl: m.image_url, timestamp: Number(m.timestamp)}))}; } const {data:nc} = await supabase.from('conversations').insert({participants: [u1, u2]}).select().single(); return {id: nc.id, participants: nc.participants, messages: []}; };
export const sendMessage = async (cid: string, m: Message) => { await supabase.from('messages').insert({conversation_id: cid, sender_id: m.senderId, receiver_id: m.receiverId, text: m.text, image_url: m.imageUrl, timestamp: m.timestamp}); };
export const loginUser = async (e: string, p: string): Promise<User> => { const {data, error} = await supabase.auth.signInWithPassword({email: e, password: p}); if(error) throw new Error('Credenciais inválidas.'); if(data.user) { const u = await findUserById(data.user.id); if(u) { saveCurrentUser(u.id); return u; } } throw new Error('Perfil não encontrado.'); };
export const registerUser = async (ud: any): Promise<User> => { const {data, error} = await supabase.auth.signUp({email: ud.email, password: ud.password, options: {data: {firstName: ud.firstName, lastName: ud.lastName, userType: ud.userType, phone: ud.phone, documentId: ud.documentId, birthDate: ud.birthDate, profilePicture: ud.profilePicture, credentials: ud.credentials, bio: ud.bio}}}); if(error) throw new Error(error.message); if(data.user) { const u: User = {id: data.user.id, userType: ud.userType, firstName: ud.firstName, lastName: ud.lastName, email: ud.email, phone: ud.phone, documentId: ud.documentId, birthDate: ud.birthDate, profilePicture: ud.profilePicture, credentials: ud.credentials, bio: ud.bio, followedUsers: [], followers: [], balance: 0}; saveCurrentUser(u.id); return u; } throw new Error('Falha.'); };
export const uploadFile = async (file: File | Blob, folder: string = 'general'): Promise<string> => { try { const ext = file instanceof File ? file.name.split('.').pop() : 'webm'; const name = `${folder}/${Date.now()}-${Math.random().toString(36).substring(7)}.${ext}`; const {error} = await supabase.storage.from('cyber-files').upload(name, file); if(error) throw error; const {data:{publicUrl}} = supabase.storage.from('cyber-files').getPublicUrl(name); return publicUrl; } catch { return new Promise(r=>{const rd=new FileReader(); rd.onloadend=()=>r(rd.result as string); rd.readAsDataURL(file);}); } };
export const compressImage = async (f: string|File) => f instanceof File ? uploadFile(f, 'images') : Promise.resolve(f);
export const getAds = async (): Promise<AdCampaign[]> => { const {data} = await supabase.from('ads').select('*'); return (data||[]).map((ad:any)=>({id: ad.id, professorId: ad.professor_id, title: ad.title, description: ad.description, targetAudience: ad.target_audience, budget: ad.budget, isActive: ad.is_active, imageUrl: ad.image_url, linkUrl: ad.link_url, ctaText: ad.cta_text, minAge: ad.min_age, maxAge: ad.max_age, timestamp: Number(ad.timestamp)})); };
export const saveAds = async (ads: AdCampaign[]) => { const l=ads[ads.length-1]; await supabase.from('ads').insert({professor_id: l.professorId, title: l.title, description: l.description, target_audience: l.targetAudience, budget: l.budget, is_active: l.isActive, image_url: l.imageUrl, link_url: l.linkUrl, cta_text: l.ctaText, min_age: l.minAge, max_age: l.maxAge, timestamp: l.timestamp}); };
export const getEvents = async (): Promise<CyberEvent[]> => { const {data} = await supabase.from('events').select('*'); return (data||[]).map((e:any)=>({id: e.id, creatorId: e.creator_id, creatorName: 'Organizador', title: e.title, description: e.description, dateTime: Number(e.date_time), endDateTime: Number(e.end_date_time), type: e.type, location: e.location, imageUrl: e.image_url, isPublic: e.is_public, attendees: e.attendees||[]})); };
export const createEvent = async (evt: CyberEvent) => { await supabase.from('events').insert({creator_id: evt.creatorId, title: evt.title, description: evt.description, date_time: evt.dateTime, end_date_time: evt.endDateTime, type: evt.type, location: evt.location, image_url: evt.imageUrl, is_public: evt.isPublic, attendees: evt.attendees}); };
export const toggleJoinEvent = async (eId: string, uId: string) => { const {data} = await supabase.from('events').select('attendees').eq('id', eId).single(); if(data) { let a = data.attendees||[]; if(a.includes(uId)) a=a.filter((i:string)=>i!==uId); else a.push(uId); await supabase.from('events').update({attendees: a}).eq('id', eId); } };
export const updateUserBalance = async (userId: string, amount: number): Promise<boolean> => { const user = await findUserById(userId); if (!user) return false; const newBalance = (user.balance || 0) + amount; const { error } = await supabase.from('profiles').update({ balance: newBalance }).eq('id', userId); return !error; };
export const toggleFollowUser = async (currentUserId: string, targetUserId: string) => { const currentUser = await findUserById(currentUserId); const targetUser = await findUserById(targetUserId); if (!currentUser || !targetUser) return; let newFollowing = [...currentUser.followedUsers]; let newFollowers = [...targetUser.followers]; if (newFollowing.includes(targetUserId)) { newFollowing = newFollowing.filter(id => id !== targetUserId); newFollowers = newFollowers.filter(id => id !== currentUserId); } else { newFollowing.push(targetUserId); newFollowers.push(currentUserId); createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: targetUserId, actorId: currentUserId, timestamp: Date.now() }); } await supabase.from('profiles').update({ followed_users: newFollowing }).eq('id', currentUserId); await supabase.from('profiles').update({ followers: newFollowers }).eq('id', targetUserId); };

