  ArrowDownTrayIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid,
  BookmarkIcon as BookmarkIconSolid,
  CheckBadgeIcon
} from '@heroicons/react/24/solid';

interface PostDetailModalProps {
  post: Post;
  currentUser: User;
  onClose: () => void;
  onUpdate: () => void;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const PostDetailModal: React.FC<PostDetailModalProps> = ({ post, currentUser, onClose, onUpdate, onNavigate, refreshUser }) => {
  const [commentText, setCommentText] = useState('');
  const [author, setAuthor] = useState<User | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    findUserById(post.userId).then(u => setAuthor(u || null));
  }, [post.userId]);

  const isOwner = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId);
  const hasLiked = post.likes?.includes(currentUser.id);
  const hasSaved = post.saves?.includes(currentUser.id);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'auto'; };
  }, []);

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onUpdate();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onUpdate();
  };

  const handleDownload = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!post.imageUrl) return;

    try {
      const response = await fetch(post.imageUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `cyberphone-midia-${post.id}.jpg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      // Fallback simples se o fetch falhar por CORS
      window.open(post.imageUrl, '_blank');
    }
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado!');
      }
      updatePostShares(post.id, currentUser.id);
      onUpdate();
    } catch (err) {}
  };

  const handleFollow = (e: React.MouseEvent) => {
    e.stopPropagation();
    toggleFollowUser(currentUser.id, post.userId);
    refreshUser();
    onUpdate();
  };

  const handleSendComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentText.trim()) return;

    addPostComment(post.id, {
      id: `comment-${Date.now()}`,
      userId: currentUser.id,
      userName: `${currentUser.firstName} ${currentUser.lastName}`,
      profilePic: currentUser.profilePicture,
      text: commentText,
      timestamp: Date.now()
    });

    setCommentText('');
    onUpdate();

    setTimeout(() => {
      if (scrollRef.current) {
        scrollRef.current.scrollTo({
          top: scrollRef.current.scrollHeight,
          behavior: 'smooth'
        });
      }
    }, 100);
  };

  if (!author) return null;

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return createPortal(
    <div className="fixed inset-0 z-[10000] bg-black/90 flex items-center justify-center animate-fade-in overflow-hidden backdrop-blur-md">

      <div className="w-full h-full md:h-[95vh] md:max-w-6xl md:rounded-[3rem] bg-white dark:bg-[#0a0c10] flex flex-col tablet:flex-row overflow-hidden relative shadow-2xl">

        {/* Mobile Header */}
        <div className="flex items-center justify-between px-4 md:hidden z-[101] bg-black/40 backdrop-blur-xl border-b border-white/10 h-16 shrink-0">
           <button onClick={onClose} className="p-2 text-white">
             <ArrowLeftIcon className="h-6 w-6" />
           </button>
           <span className="font-black text-[10px] uppercase text-white tracking-[0.3em]">Detalhes da Aula</span>
           <div className="w-10"></div>
        </div>

        {/* Desktop Close Button */}
        <button 
          onClick={onClose} 
          className="hidden md:flex absolute top-6 left-6 z-[101] p-4 bg-black/50 hover:bg-black/80 text-white rounded-full transition-all backdrop-blur-lg shadow-2xl border border-white/10 active:scale-90"
        >
          <XMarkIcon className="h-6 w-6" />
        </button>

        {/* Image Container - Reduzido para 50vh em mobile */}
        <div className={`w-full tablet:flex-1 bg-black flex items-center justify-center relative overflow-hidden shrink-0 ${!post.imageUrl ? 'hidden tablet:flex' : 'h-[50vh] tablet:h-full'}`}>
          {post.imageUrl && (
            <img 
              src={post.imageUrl} 
              className="w-full h-full object-contain" 
              alt="Mídia"
            />
          )}

          {/* Overlay flutuante de ações na imagem para mobile */}
          <div className="absolute bottom-6 right-6 flex flex-col gap-4 md:hidden">
             <button onClick={handleDownload} className="p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl bg-black/40 text-white active:scale-90 transition-all">
                <ArrowDownTrayIcon className="h-6 w-6" />
             </button>
             <button onClick={handleLike} className={`p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl transition-all ${hasLiked ? 'bg-blue-600 text-white' : 'bg-black/40 text-white'}`}>
                {hasLiked ? <HeartIconSolid className="h-6 w-6" /> : <HeartIconOutline className="h-6 w-6" />}
             </button>
             <button onClick={handleSave} className={`p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl transition-all ${hasSaved ? 'bg-yellow-500 text-white' : 'bg-black/40 text-white'}`}>
                {hasSaved ? <BookmarkIconSolid className="h-6 w-6" /> : <BookmarkIconOutline className="h-6 w-6" />}
             </button>
          </div>
        </div>

        {/* Content & Comments Sidebar */}
        <div className="flex-1 tablet:w-[480px] flex flex-col h-full bg-white dark:bg-[#0a0c10] border-l border-gray-100 dark:border-white/10 relative overflow-hidden">

          {/* Header Autor (Desktop) */}
          <div className="p-6 border-b border-gray-50 dark:border-white/10 flex items-center justify-between shrink-0 hidden tablet:flex bg-gray-50/50 dark:bg-white/[0.02]">
             <div className="flex items-center gap-4 cursor-pointer group" onClick={() => { onClose(); onNavigate('profile', { userId: post.userId }); }}>
                <div className="relative">
                   <img src={author.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-[1.2rem] object-cover border-2 border-white dark:border-white/10 shadow-lg" />
                   {author.userType === UserType.CREATOR && <div className="absolute -bottom-1 -right-1 bg-blue-600 p-0.5 rounded-lg border border-white dark:border-[#0a0c10]"><CheckBadgeIcon className="h-3 w-3 text-white" /></div>}
                </div>
                <div>
                   <h4 className="font-black text-sm dark:text-white group-hover:text-blue-600 transition-colors uppercase tracking-tight">{author.firstName} {author.lastName}</h4>
                   <p className="text-gray-400 text-[9px] font-black uppercase tracking-widest mt-0.5">Professor CyBer</p>
                </div>
             </div>
             {!isOwner && (
               <button 
                 onClick={handleFollow}
                 className={`px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95 ${isFollowing ? 'bg-gray-100 dark:bg-white/5 text-gray-500' : 'bg-blue-600 text-white shadow-xl shadow-blue-500/20'}`}
               >
                 {isFollowing ? 'Seguindo' : 'Seguir'}
               </button>
             )}
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-8">
             {!post.imageUrl && (
                <div className="tablet:hidden flex items-center justify-between mb-4 border-b border-gray-100 dark:border-white/5 pb-4">
                  <div className="flex items-center gap-4">
                     <img src={author.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover" />
                     <div className="flex flex-col">
                        <span className="font-black text-sm dark:text-white uppercase tracking-tight">{author.firstName} {author.lastName}</span>
                        <span className="text-gray-400 text-[9px] font-black uppercase tracking-widest">Professor CyBer</span>
                     </div>
                  </div>
                </div>
             )}

             {/* Content Block */}
             <div 
               className={`p-8 md:p-12 rounded-[2.5rem] shadow-inner flex flex-col items-center justify-center text-center animate-fade-in ${post.fontFamily || 'font-sans'}`}
               style={{ 
                 backgroundColor: hasBg ? post.backgroundColor : 'transparent',
                 color: post.textColor || 'inherit',
                 fontSize: post.fontSize ? `calc(${post.fontSize} * 1.2)` : '1.1rem',
                 minHeight: hasBg ? '300px' : 'auto',
                 border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
                 fontFamily: post.fontFamily?.replace('font-', '')
               }}
             >
                <p className={`font-black leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-xs' : 'text-left w-full'}`}>{post.content}</p>
                <div className={`text-[8px] font-black uppercase tracking-[0.2em] pt-8 mt-4 border-t w-full opacity-30 ${hasBg ? 'border-white/10' : 'border-gray-100'}`}>
                   Publicado em {new Date(post.timestamp).toLocaleDateString()}
                </div>
             </div>

             {/* Social Bar (Visible on Desktop always) */}
             <div className="hidden tablet:flex items-center justify-between py-6 border-b border-gray-50 dark:border-white/5 text-gray-400">
                <div className="flex items-center gap-4">
                   <button onClick={handleLike} className={`flex items-center gap-2 group transition-all active:scale-75 ${hasLiked ? 'text-blue-600' : 'hover:text-blue-600'}`}>
                      <div className={`p-3 rounded-2xl transition-colors ${hasLiked ? 'bg-blue-50 dark:bg-blue-600/10' : 'group-hover:bg-gray-50'}`}>
                       {hasLiked ? <HeartIconSolid className="h-6 w-6" /> : <HeartIconOutline className="h-6 w-6" />}
                      </div>
                      <span className="text-xs font-black">{post.likes?.length || 0}</span>
                   </button>
                   <div className="flex items-center gap-2 group text-gray-400">
                      <div className="p-3 rounded-2xl bg-gray-50 dark:bg-white/5">
                       <ChatBubbleOvalLeftIcon className="h-6 w-6" />
                      </div>
                      <span className="text-xs font-black">{post.comments?.length || 0}</span>
                   </div>
                </div>
                <div className="flex items-center gap-2">
                   <button onClick={handleDownload} className="p-3 rounded-2xl hover:bg-gray-50 text-gray-400 transition-all active:scale-90" title="Baixar Mídia">
                      <ArrowDownTrayIcon className="h-6 w-6" />
                   </button>
                   <button onClick={handleSave} className={`p-3 rounded-2xl transition-all active:scale-90 ${hasSaved ? 'text-yellow-500 bg-yellow-50 dark:bg-yellow-500/10' : 'hover:bg-gray-50 text-gray-300'}`}>
                      {hasSaved ? <BookmarkIconSolid className="h-6 w-6" /> : <BookmarkIconOutline className="h-6 w-6" />}
                   </button>
                   <button onClick={handleShare} className="p-3 rounded-2xl hover:bg-gray-50 text-gray-300 transition-all active:scale-90">
                      <ShareIcon className="h-6 w-6" />
                   </button>
                </div>
             </div>

             {/* Comments Section */}
             <div className="space-y-6 pt-4 pb-10">
                <div className="flex items-center justify-between mb-4">
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Comentários e Dúvidas</p>
                </div>

                {post.comments?.length === 0 ? (
                  <div className="py-12 text-center opacity-20">
                     <ChatBubbleOvalLeftIcon className="h-10 w-10 mx-auto mb-2" />
                     <p className="text-[10px] font-black uppercase tracking-widest">Seja o primeiro a comentar</p>
                  </div>
                ) : (
                  <div className="space-y-6">
                    {post.comments?.slice().map((c) => (
                      <div key={c.id} className="flex gap-4 animate-fade-in group">
                         <img src={c.profilePic || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover shrink-0 border-2 border-white dark:border-white/5 shadow-sm" />
                         <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                               <span className="font-black text-[11px] dark:text-white uppercase tracking-tighter truncate">{c.userName}</span>
                               <span className="text-gray-400 text-[8px] font-black uppercase">· {new Date(c.timestamp).getHours()}h</span>
                            </div>
                            <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-2xl rounded-tl-none border border-gray-100 dark:border-white/10 shadow-sm">
                               <p className="text-sm dark:text-gray-200 font-medium leading-relaxed">{c.text}</p>
                            </div>
                         </div>
                      </div>
                    ))}
                  </div>
                )}
             </div>
          </div>

          {/* Comment Input Footer */}
          <div className="p-6 bg-white dark:bg-[#0a0c10] border-t border-gray-100 dark:border-white/10 z-[105] shadow-[0_-10px_30px_rgba(0,0,0,0.05)] shrink-0">
             <form onSubmit={handleSendComment} className="max-w-4xl mx-auto flex items-end gap-3 bg-gray-50 dark:bg-white/5 p-3 rounded-[2rem] border border-gray-100 dark:border-white/10 shadow-inner group focus-within:border-blue-500/50 transition-all">
                <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-11 h-11 rounded-xl object-cover hidden sm:block border-2 border-white shadow-sm" />
                <div className="flex-1 flex items-center gap-3">
                   <textarea 
                    value={commentText}
                    onChange={e => setCommentText(e.target.value)}
                    placeholder="Adicionar um comentário..."
                    className="w-full bg-transparent dark:text-white outline-none resize-none text-sm placeholder-gray-400 py-3 font-bold custom-scrollbar max-h-24"
                    rows={1}
                    onInput={(e) => {
                      const target = e.target as HTMLTextAreaElement;
                      target.style.height = 'auto';
                      target.style.height = `${target.scrollHeight}px`;
                    }}
                   />
                   <button 
                     type="submit" 
                     disabled={!commentText.trim()}
                     className="bg-blue-600 hover:bg-blue-700 disabled:opacity-30 text-white p-3.5 rounded-2xl shadow-xl shadow-blue-500/20 active:scale-90 transition-all shrink-0"
                   >
                     <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                   </button>
                </div>
             </form>
             <div className="h-2 md:hidden"></div>
          </div>
        </div>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.05); border-radius: 10px; }
        .dark .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.05); }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        .animate-fade-in { animation: fadeIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>
    </div>,
    document.body
  );
};

export default PostDetailModal;

import React, { useState, useRef, useEffect } from 'react';
import { XMarkIcon, VideoCameraIcon, StopIcon, ArrowPathIcon, MusicalNoteIcon, SparklesIcon, CheckIcon, ChevronDownIcon } from '@heroicons/react/24/solid';
import { AudioTrack } from '../types';
import { uploadFile } from '../services/storageService';
import AudioSelectionModal from './AudioSelectionModal';

interface RecordReelModalProps {
  onClose: () => void;
  onSave: (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => void;
}

const VIDEO_FILTERS = [
  { id: 'none', label: 'Normal', css: '' },
  { id: 'grayscale(1) contrast(1.2)', label: 'Noir', css: 'grayscale(1) contrast(1.2)' },
  { id: 'sepia(0.6) saturate(1.5)', label: 'Vintage', css: 'sepia(0.6) saturate(1.5)' },
  { id: 'hue-rotate(90deg) brightness(1.2)', label: 'Neon', css: 'hue-rotate(90deg) brightness(1.2)' },
  { id: 'saturate(2.5) contrast(1.1)', label: 'Vibrante', css: 'saturate(2.5) contrast(1.1)' },
  { id: 'invert(0.9) hue-rotate(180deg)', label: 'Raio-X', css: 'invert(0.9) hue-rotate(180deg)' },
  { id: 'blur(1.5px) saturate(1.8)', label: 'Sonho', css: 'blur(1.5px) saturate(1.8)' },
  { id: 'contrast(1.5) brightness(0.8)', label: 'Drama', css: 'contrast(1.5) brightness(0.8)' },
  { id: 'sepia(0.2) brightness(1.3) contrast(0.9)', label: 'Brilho', css: 'sepia(0.2) brightness(1.3) contrast(0.9)' },
];

const MAX_RECORDING_TIME = 180; // 3 minutos

const RecordReelModal: React.FC<RecordReelModalProps> = ({ onClose, onSave }) => {
  const [isRecording, setIsRecording] = useState(false);
  const [recordedVideo, setRecordedVideo] = useState<Blob | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [timer, setTimer] = useState(0);
  const [showAudioModal, setShowAudioModal] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedAudioId, setSelectedAudioId] = useState<string | undefined>(undefined);
  const [selectedFilter, setSelectedFilter] = useState(VIDEO_FILTERS[0]);
  const [aiPrompt, setAiPrompt] = useState('');

  const videoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const timerIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    startCamera();
    return () => {
      stopCamera();
      if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
    };
  }, []);

  const startCamera = async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', aspectRatio: 9/16 }, 
        audio: true 
      });
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
    } catch (err) {
      alert("Permissão de câmera negada ou erro no hardware.");
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
    }
  };

  const startRecording = () => {
    if (!stream) return;
    chunksRef.current = [];
    const recorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
    recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunksRef.current.push(e.data);
    };
    recorder.onstop = () => {
      const blob = new Blob(chunksRef.current, { type: 'video/webm' });
      setRecordedVideo(blob);
    };

    recorder.start(1000);
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
    setTimer(0);

    timerIntervalRef.current = window.setInterval(() => {
      setTimer(prev => {
        if (prev >= MAX_RECORDING_TIME) {
          stopRecording();
          return MAX_RECORDING_TIME;
        }
        return prev + 1;
      });
    }, 1000);
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
    }
  };

  const handleSave = () => {
    if (recordedVideo) {
      // Passamos o blob para o pai (CreatePost) que fará o upload real
      onSave(recordedVideo, selectedAudioId, aiPrompt, selectedFilter.id);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  return (
    <div className="fixed inset-0 bg-black z-[200] flex flex-col animate-fade-in overflow-hidden">
      <div className="absolute top-0 left-0 w-full p-6 flex justify-between items-center z-50 bg-gradient-to-b from-black/80 to-transparent">
        <button onClick={onClose} className="p-3 bg-white/10 rounded-full text-white backdrop-blur-md hover:bg-white/20 transition-all">
          <XMarkIcon className="h-6 w-6" />
        </button>

        <div className="flex flex-col items-center">
           <div className={`px-4 py-1.5 rounded-full text-[10px] font-black text-white uppercase tracking-[0.2em] transition-colors ${isRecording ? 'bg-red-600 animate-pulse' : 'bg-white/20 backdrop-blur-md'}`}>
             {isRecording ? `Gravando • ${formatTime(timer)}` : 'Crie seu Reel'}
           </div>
        </div>
        <div className="w-12"></div>
      </div>

      <div className="flex-1 relative bg-[#050505] flex items-center justify-center">
        {!recordedVideo ? (
          <video 
            ref={videoRef} 
            autoPlay 
            muted 
            playsInline 
            className="w-full h-full object-cover scale-x-[-1]" 
            style={{ filter: selectedFilter.id === 'none' ? 'none' : selectedFilter.id }}
          />
        ) : (
          <video 
            src={URL.createObjectURL(recordedVideo)} 
            autoPlay 
            loop 
            playsInline 
            className="w-full h-full object-cover" 
            style={{ filter: selectedFilter.id === 'none' ? 'none' : selectedFilter.id }}
          />
        )}

        {!isRecording && !recordedVideo && !showFilters && (
          <div className="absolute right-5 top-1/2 -translate-y-1/2 flex flex-col gap-6 z-40">
             <button onClick={() => setShowAudioModal(true)} className="flex flex-col items-center gap-1.5 group">
                <div className={`p-4 rounded-2xl backdrop-blur-xl border border-white/20 transition-all shadow-2xl ${selectedAudioId ? 'bg-blue-600' : 'bg-black/40 group-hover:bg-black/60'}`}>
                  <MusicalNoteIcon className="h-6 w-6 text-white" />
                </div>
                <span className="text-[8px] font-black text-white uppercase tracking-widest shadow-lg">Áudio</span>
             </button>

             <button onClick={() => setShowFilters(true)} className="flex flex-col items-center gap-1.5 group">
                <div className="p-4 bg-black/40 rounded-2xl backdrop-blur-xl border border-white/20 transition-all shadow-2xl group-hover:bg-black/60">
                  <SparklesIcon className="h-6 w-6 text-white" />
                </div>
                <span className="text-[8px] font-black text-white uppercase tracking-widest shadow-lg">Filtros</span>
             </button>
          </div>
        )}

        {showFilters && !isRecording && (
          <div className="absolute inset-0 z-50 flex flex-col justify-end bg-black/20 animate-fade-in" onClick={() => setShowFilters(false)}>
             <div className="w-full bg-gradient-to-t from-black via-black/90 to-transparent pt-20 pb-10 px-0 animate-slide-up" onClick={e => e.stopPropagation()}>
                <div className="flex items-center justify-between px-8 mb-6">
                   <h4 className="text-[10px] font-black text-white uppercase tracking-[0.3em]">Estilos Criativos</h4>
                   <button onClick={() => setShowFilters(false)} className="bg-white/10 p-2 rounded-full text-white hover:bg-white/20 transition-all">
                      <CheckIcon className="h-4 w-4" />
                   </button>
                </div>
                <div className="flex gap-4 px-8 overflow-x-auto no-scrollbar scroll-smooth py-2">
                   {VIDEO_FILTERS.map(filter => (
                     <button key={filter.id} onClick={() => setSelectedFilter(filter)} className="flex flex-col items-center gap-3 shrink-0 group transition-transform active:scale-95">
                        <div className={`w-16 h-16 rounded-2xl border-2 transition-all duration-300 overflow-hidden relative ${selectedFilter.id === filter.id ? 'border-blue-500 scale-110 shadow-[0_0_20px_rgba(59,130,246,0.5)]' : 'border-white/20 opacity-60'}`}>
                           <div className="w-full h-full bg-gradient-to-tr from-gray-800 to-gray-700" style={{ filter: filter.id === 'none' ? 'none' : filter.id }}></div>
                           {selectedFilter.id === filter.id && (
                             <div className="absolute inset-0 flex items-center justify-center bg-blue-600/20">
                                <CheckIcon className="h-5 w-5 text-white" />
                             </div>
                           )}
                        </div>
                        <span className={`text-[9px] font-black uppercase tracking-widest ${selectedFilter.id === filter.id ? 'text-blue-400' : 'text-white/40'}`}>{filter.label}</span>
                     </button>
                   ))}
                </div>
             </div>
          </div>
        )}
      </div>

      <div className="p-10 bg-gradient-to-t from-black via-black/60 to-transparent z-50 flex flex-col items-center gap-8">
        {!recordedVideo ? (
          <div className="flex items-center gap-10">
             <div className="w-12"></div>
             <button onClick={isRecording ? stopRecording : startRecording} className={`relative group transition-all duration-500 ${isRecording ? 'scale-110' : 'hover:scale-105'}`}>
                <div className={`absolute inset-0 rounded-full blur-xl opacity-50 group-hover:opacity-100 transition-opacity ${isRecording ? 'bg-red-600' : 'bg-white'}`}></div>
                <div className={`w-20 h-20 rounded-full border-4 flex items-center justify-center relative z-10 ${isRecording ? 'border-red-600 bg-red-600/20' : 'border-white bg-white/10'}`}>
                  {isRecording ? <StopIcon className="h-10 w-10 text-red-600" /> : <div className="w-14 h-14 bg-red-600 rounded-full shadow-2xl" />}
                </div>
             </button>
             <button className="p-3 bg-white/10 rounded-full text-white/40 hover:text-white transition-all">
                <ArrowPathIcon className="h-6 w-6" />
             </button>
          </div>
        ) : (
          <div className="w-full max-w-lg animate-fade-in space-y-8">
            <div className="bg-white/10 backdrop-blur-2xl rounded-[2.5rem] p-8 border border-white/10 shadow-2xl">
               <div className="flex items-center gap-3 mb-5">
                  <div className="bg-purple-600 p-2 rounded-xl"><SparklesIcon className="h-5 w-5 text-white" /></div>
                  <span className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Refinar Estilo com IA</span>
               </div>
               <input 
                  type="text" 
                  value={aiPrompt}
                  onChange={e => setAiPrompt(e.target.value)}
                  placeholder="Ex: Estilo Ghibli, Realismo Fantástico..."
                  className="w-full bg-black/40 border-2 border-white/5 rounded-2xl p-5 text-sm text-white placeholder-white/20 focus:ring-0 focus:border-purple-500 transition-all font-bold"
               />
            </div>
            <div className="flex gap-4">
              <button onClick={() => { setRecordedVideo(null); setAiPrompt(''); }} className="flex-1 py-5 bg-white/10 rounded-3xl text-white font-black text-xs uppercase transition-all flex items-center justify-center gap-3 border border-white/5">
                <ArrowPathIcon className="h-4 w-4" /> Refazer
              </button>
              <button onClick={handleSave} className="flex-[2] py-5 bg-blue-600 rounded-3xl text-white font-black text-xs uppercase shadow-xl transition-all flex items-center justify-center gap-3">
                <CheckIcon className="h-5 w-5" /> Usar Vídeo
              </button>
            </div>
          </div>
        )}
      </div>
      {showAudioModal && <AudioSelectionModal onClose={() => setShowAudioModal(false)} onSelectTrack={(id) => { setSelectedAudioId(id); setShowAudioModal(false); }} />}
    </div>
  );
};

export default RecordReelModal;

import React, { useState, useEffect, useRef } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { addPost, updatePost, getPosts, uploadFile } from '../services/storageService';
import RecordReelModal from './RecordReelModal';
import { 
  VideoCameraIcon, 
  PhotoIcon, 
  XMarkIcon,
  DocumentTextIcon,
  LockClosedIcon,
  FilmIcon,
  ChevronRightIcon,
  BriefcaseIcon,
  BanknotesIcon,
  ArrowUpTrayIcon,
  TrashIcon
} from '@heroicons/react/24/solid';

interface CreatePostProps {
  currentUser: User;
  onPostCreated: () => void;
  refreshUser: () => void;
  postId?: string;
  onCancel?: () => void;
}

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId, onCancel }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');

  // Reel States
  const [reelUrl, setReelUrl] = useState('');
  const [reelFile, setReelFile] = useState<File | Blob | null>(null);

  const [liveTitle, setLiveTitle] = useState('');
  const [liveDescription, setLiveDescription] = useState('');
  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('5.00');
  const [showRecordReel, setShowRecordReel] = useState(false);

  const [fontFamily, setFontFamily] = useState('font-sans');
  const [textColor, setTextColor] = useState('#000000');
  const [fontSize, setFontSize] = useState('18px');
  const [backgroundColor, setBackgroundColor] = useState('transparent');

  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);

  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const isEditing = !!postId;
  const isProfessional = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    const loadPostData = async () => {
      if (postId) {
        const posts = await getPosts();
        const postToEdit = posts.find(p => p.id === postId);
        if (postToEdit) {
          setPostType(postToEdit.type);
          setContent(postToEdit.content || '');
          setImageUrl(postToEdit.imageUrl || '');
          setFontFamily(postToEdit.fontFamily || 'font-sans');
          setTextColor(postToEdit.textColor || '#000000');
          setFontSize(postToEdit.fontSize || '18px');
          setBackgroundColor(postToEdit.backgroundColor || 'transparent');

          if (postToEdit.type === PostType.REEL && postToEdit.reel) {
            setReelUrl(postToEdit.reel.videoUrl);
            setContent(postToEdit.reel.description);
          }
          if (postToEdit.type === PostType.LIVE && postToEdit.liveStream) {
            setLiveTitle(postToEdit.liveStream.title);
            setLiveDescription(postToEdit.liveStream.description);
            setIsLivePaid(postToEdit.liveStream.isPaid);
            setLivePrice(postToEdit.liveStream.price?.toString() || '0');
          }
          setIsExpanded(true);
        }
      }
    };
    loadPostData();
  }, [postId]);

  const resetState = () => {
    setContent(''); setImageUrl(''); setReelUrl(''); setReelFile(null); setLiveTitle(''); setLiveDescription('');
    setIsLivePaid(false); setLivePrice('5.00'); setBackgroundColor('transparent');
    setTextColor('#000000'); setFontFamily('font-sans'); setFontSize('18px');
  };

  const handleClose = () => {
    if (onCancel) onCancel();
    else if (isEditing) onPostCreated();
    else { setIsExpanded(false); resetState(); }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploading(true);
    try {
      const url = await uploadFile(file, 'posts');
      setImageUrl(url);
    } catch (error) {
      alert('Erro ao enviar imagem.');
    } finally {
      setUploading(false);
    }
  };

  const handleVideoFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validar tamanho (opcional, ex: 100MB)
    // Validar duração (máximo 3 minutos)
    const video = document.createElement('video');
    video.preload = 'metadata';
    video.onloadedmetadata = function() {
      window.URL.revokeObjectURL(video.src);
      if (video.duration > 180) { // 3 minutos
        alert("O vídeo deve ter no máximo 3 minutos.");
        return;
      }
      setReelFile(file);
      setReelUrl(URL.createObjectURL(file)); // Preview local
    };
    video.src = URL.createObjectURL(file);
  };

  const handleReelSaved = async (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setShowRecordReel(false);
    setPostType(PostType.REEL);
    setReelFile(videoBlob);
    setReelUrl(URL.createObjectURL(videoBlob)); // Preview local
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (uploading) return;

    setLoading(true);
    try {
      let finalReelUrl = reelUrl;

      // Se houver um arquivo de vídeo novo (upload ou gravação), fazer o upload agora
      if (postType === PostType.REEL && reelFile) {
        setUploading(true);
        try {
          finalReelUrl = await uploadFile(reelFile, 'reels');
        } catch(e) {
          alert("Erro no upload do vídeo.");
          setLoading(false);
          setUploading(false);
          return;
        }
        setUploading(false);
      }

      const existingPosts = await getPosts();
      const existingPost = isEditing ? existingPosts.find(p => p.id === postId) : undefined;

      const postData: Post = {
        id: isEditing ? postId! : `post-${Date.now()}`,
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: postType,
        timestamp: isEditing ? (existingPost?.timestamp || Date.now()) : Date.now(),
        content: (postType === PostType.TEXT || postType === PostType.IMAGE) ? content : undefined,
        imageUrl: postType === PostType.IMAGE ? imageUrl : undefined,
        fontFamily: postType === PostType.TEXT ? fontFamily : undefined,
        textColor: postType === PostType.TEXT ? textColor : undefined,
        fontSize: postType === PostType.TEXT ? fontSize : undefined,
        backgroundColor: postType === PostType.TEXT ? backgroundColor : undefined,
        reel: postType === PostType.REEL ? { videoUrl: finalReelUrl, description: content || 'Confira! 🚀' } : undefined,
        liveStream: postType === PostType.LIVE ? { title: liveTitle, description: liveDescription, isPaid: isLivePaid, price: isLivePaid ? parseFloat(livePrice) : 0 } : undefined,
        likes: isEditing ? (existingPost?.likes || []) : [],
        comments: isEditing ? (existingPost?.comments || []) : [],
        shares: isEditing ? (existingPost?.shares || []) : [],
        saves: isEditing ? (existingPost?.saves || []) : [],
        indicatedUserIds: isEditing ? (existingPost?.indicatedUserIds || []) : [],
      };
      if (isEditing) await updatePost(postData);
      else await addPost(postData);
      resetState();
      onPostCreated();
      if (!isEditing && !onCancel) setIsExpanded(false);
    } catch (err) { alert('Erro ao salvar.'); }
    finally { setLoading(false); }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-sm p-5 md:p-6 border border-gray-100 dark:border-white/10 flex flex-col gap-5">
         <div className="flex items-start gap-4">
            <img src={currentUser.profilePicture} className="w-12 h-12 rounded-2xl object-cover shrink-0 shadow-lg" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-6 py-3.5 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 font-bold text-xs md:text-sm transition-all hover:bg-gray-100 dark:hover:bg-white/10">
              {isProfessional ? `Olá Profissional, qual o insight de hoje?` : `O que você está pensando, ${currentUser.firstName}?`}
            </button>
         </div>
         <div className="flex items-center gap-6 md:gap-10 px-2 border-t border-gray-50 dark:border-white/5 pt-4 overflow-x-auto no-scrollbar">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-3 text-gray-500 hover:text-blue-600 transition-all shrink-0 active:scale-95 group">
               <div className="p-2 bg-blue-50 dark:bg-blue-600/10 rounded-xl group-hover:bg-blue-600 group-hover:text-white transition-all"><PhotoIcon className="h-5 w-5" /></div>
               <span className="text-[10px] font-black uppercase tracking-[0.2em]">Mídia</span>
            </button>
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.REEL); }} className="flex items-center gap-3 text-gray-500 hover:text-purple-600 transition-all shrink-0 active:scale-95 group">
               <div className="p-2 bg-purple-50 dark:bg-purple-600/10 rounded-xl group-hover:bg-purple-600 group-hover:text-white transition-all"><FilmIcon className="h-5 w-5" /></div>
               <span className="text-[10px] font-black uppercase tracking-[0.2em]">Reel</span>
            </button>
            {isProfessional && (
              <button onClick={() => { setIsExpanded(true); setPostType(PostType.LIVE); }} className="flex items-center gap-3 text-gray-500 hover:text-red-600 transition-all shrink-0 active:scale-95 group">
                 <div className="p-2 bg-red-50 dark:bg-red-600/10 rounded-xl group-hover:bg-red-600 group-hover:text-white transition-all"><VideoCameraIcon className="h-5 w-5" /></div>
                 <span className="text-[10px] font-black uppercase tracking-[0.2em]">Live Pro</span>
              </button>
            )}
         </div>
      </div>
    );
  }

  return (
    <>
      <div className="bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl p-8 md:p-12 border border-blue-50 dark:border-white/5 animate-fade-in relative overflow-hidden">
        <div className="absolute top-0 left-0 w-2 h-full bg-blue-600"></div>

        <div className="flex items-center justify-between mb-10">
          <div className="flex items-center gap-5">
             <div className={`p-4 text-white rounded-[1.5rem] shadow-2xl ${postType === PostType.LIVE ? 'bg-red-600' : postType === PostType.REEL ? 'bg-purple-600' : 'bg-blue-600'}`}>
               {postType === PostType.LIVE ? <VideoCameraIcon className="h-7 w-7" /> : postType === PostType.REEL ? <FilmIcon className="h-7 w-7" /> : <BriefcaseIcon className="h-7 w-7" />}
             </div>
             <div>
                <h3 className="font-black text-gray-900 dark:text-white uppercase text-[11px] tracking-[0.3em]">{isEditing ? 'Editar Post' : 'Novo Conteúdo'}</h3>
                <p className="text-[9px] text-blue-500 font-black uppercase mt-1 tracking-widest flex items-center gap-2">CyBer Studio Pro <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></span></p>
             </div>
          </div>
          <button onClick={handleClose} className="p-3 bg-gray-50 dark:bg-white/5 text-gray-300 hover:text-red-500 hover:bg-red-50 transition-all rounded-2xl active:scale-90">
            <XMarkIcon className="h-7 w-7" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="flex flex-wrap gap-3 p-2 bg-gray-50 dark:bg-white/5 rounded-[2rem] w-fit">
             {[
               { id: PostType.TEXT, icon: DocumentTextIcon, label: 'Texto', locked: false },
               { id: PostType.IMAGE, icon: PhotoIcon, label: 'Mídia', locked: false },
               { id: PostType.REEL, icon: FilmIcon, label: 'Reel', locked: false },
               { id: PostType.LIVE, icon: VideoCameraIcon, label: 'Live Pro', locked: !isProfessional }
             ].map(t => (
               <button key={t.id} type="button" disabled={t.locked} onClick={() => { setPostType(t.id); }} className={`flex items-center gap-3 px-6 py-3 rounded-[1.5rem] text-[10px] font-black uppercase tracking-[0.15em] transition-all active:scale-95 ${postType === t.id ? 'bg-white dark:bg-white/10 text-blue-600 dark:text-white shadow-xl' : 'text-gray-400'} ${t.locked ? 'opacity-20 grayscale' : ''}`}>
                  {t.locked ? <LockClosedIcon className="h-4 w-4" /> : <t.icon className="h-4 w-4" />} {t.label}
               </button>
             ))}
          </div>

          {postType === PostType.LIVE ? (
            <div className="space-y-8 animate-fade-in">
              <input type="text" value={liveTitle} onChange={(e) => setLiveTitle(e.target.value)} className="w-full p-8 bg-gray-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-[2rem] outline-none font-black text-2xl dark:text-white transition-all shadow-inner" placeholder="Título da Aula..." required />
              <textarea value={liveDescription} onChange={(e) => setLiveDescription(e.target.value)} className="w-full p-8 bg-gray-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-[2rem] outline-none font-medium text-lg dark:text-white h-40 resize-none transition-all shadow-inner" placeholder="Sobre o que será essa live profissional?" />

              <div className="p-6 bg-red-50 dark:bg-red-900/10 rounded-[2rem] border border-red-100 dark:border-red-500/20">
                 <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                       <BanknotesIcon className="h-6 w-6 text-red-600" />
                       <div>
                          <h4 className="font-black text-red-900 dark:text-white text-xs uppercase tracking-widest">Monetização</h4>
                          <p className="text-[9px] text-red-400 font-bold uppercase">Defina o valor de acesso</p>
                       </div>
                    </div>
                    <label className="relative inline-flex items-center cursor-pointer">
                      <input type="checkbox" checked={isLivePaid} onChange={() => setIsLivePaid(!isLivePaid)} className="sr-only peer" />
                      <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer dark:bg-gray-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-red-600"></div>
                    </label>
                 </div>

                 {isLivePaid && (
                    <div className="flex items-center gap-4 animate-fade-in">
                       <span className="text-red-600 font-black text-2xl">$</span>
                       <input 
                         type="number" 
                         value={livePrice} 
                         onChange={e => setLivePrice(e.target.value)} 
                         className="flex-1 bg-white dark:bg-white/5 p-4 rounded-xl font-black text-xl outline-none border-2 border-transparent focus:border-red-500 transition-all"
                         step="0.01"
                         min="1"
                       />
                    </div>
                 )}
              </div>
            </div>
          ) : postType === PostType.IMAGE ? (
             <div className="space-y-6">
                <textarea value={content} onChange={(e) => setContent(e.target.value)} className="w-full p-6 bg-gray-50 dark:bg-white/5 rounded-[2rem] outline-none font-medium resize-none h-32" placeholder="Legenda da imagem..." />

                <div 
                  onClick={() => imageInputRef.current?.click()}
                  className={`w-full h-64 border-4 border-dashed rounded-[3rem] flex flex-col items-center justify-center gap-4 cursor-pointer transition-all ${imageUrl ? 'border-blue-500' : 'border-gray-200 dark:border-white/10 hover:border-blue-400'}`}
                >
                   {uploading ? (
                      <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent animate-spin rounded-full"></div>
                   ) : imageUrl ? (
                      <img src={imageUrl} className="w-full h-full object-cover rounded-[2.5rem]" />
                   ) : (
                      <>
                         <PhotoIcon className="h-12 w-12 text-gray-300" />
                         <span className="font-black text-xs text-gray-400 uppercase tracking-widest">Carregar Imagem</span>
                      </>
                   )}
                   <input type="file" ref={imageInputRef} onChange={handleImageUpload} accept="image/*" className="hidden" />
                </div>
             </div>
          ) : postType === PostType.REEL ? (
             <div className="space-y-6 animate-fade-in">
                {reelUrl ? (
                   <div className="relative w-full h-64 bg-black rounded-[2rem] overflow-hidden group">
                      <video src={reelUrl} className="w-full h-full object-cover" controls />
                      <button type="button" onClick={() => { setReelUrl(''); setReelFile(null); }} className="absolute top-4 right-4 bg-white text-black p-2 rounded-full shadow-lg text-xs font-bold hover:bg-red-50 hover:text-red-500 transition-colors">
                        <TrashIcon className="h-4 w-4" />
                      </button>
                   </div>
                ) : (
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div onClick={() => setShowRecordReel(true)} className="h-48 bg-purple-50 dark:bg-purple-900/10 rounded-[2rem] flex flex-col items-center justify-center cursor-pointer border-2 border-dashed border-purple-200 dark:border-purple-500/20 hover:border-purple-500 transition-all group">
                         <div className="bg-purple-600 p-4 rounded-full mb-3 group-hover:scale-110 transition-transform shadow-lg">
                            <VideoCameraIcon className="h-8 w-8 text-white" />
                         </div>
                         <span className="font-black text-xs text-purple-600 uppercase tracking-widest">Gravar Câmera</span>
                         <span className="text-[9px] text-purple-400 mt-1 font-bold">Máx 3 minutos</span>
                      </div>

                      <div onClick={() => videoInputRef.current?.click()} className="h-48 bg-blue-50 dark:bg-blue-900/10 rounded-[2rem] flex flex-col items-center justify-center cursor-pointer border-2 border-dashed border-blue-200 dark:border-blue-500/20 hover:border-blue-500 transition-all group">
                         <div className="bg-blue-600 p-4 rounded-full mb-3 group-hover:scale-110 transition-transform shadow-lg">
                            <ArrowUpTrayIcon className="h-8 w-8 text-white" />
                         </div>
                         <span className="font-black text-xs text-blue-600 uppercase tracking-widest">Upload Vídeo</span>
                         <span className="text-[9px] text-blue-400 mt-1 font-bold">Máx 3 minutos</span>
                         <input type="file" ref={videoInputRef} onChange={handleVideoFileSelect} accept="video/*" className="hidden" />
                      </div>
                   </div>
                )}
                <textarea value={content} onChange={(e) => setContent(e.target.value)} className="w-full p-6 bg-gray-50 dark:bg-white/5 rounded-[2rem] outline-none font-medium resize-none h-24" placeholder="Descrição do Reel..." />
             </div>
          ) : (
            <textarea value={content} onChange={(e) => setContent(e.target.value)} className={`w-full p-12 border-4 border-transparent focus:border-blue-500/10 rounded-[3.5rem] outline-none transition-all duration-500 shadow-inner resize-none flex items-center justify-center text-center ${fontFamily}`} style={{ color: textColor, fontSize: fontSize, backgroundColor: backgroundColor === 'transparent' ? 'transparent' : backgroundColor, minHeight: '400px', display: backgroundColor !== 'transparent' ? 'flex' : 'block', fontFamily: fontFamily.replace('font-', '') }} placeholder="O que deseja partilhar?" required={postType === PostType.TEXT} />
          )}

          <div className="flex justify-end pt-10 border-t border-gray-50 dark:border-white/5">
             <button type="submit" disabled={loading || uploading} className="bg-gradient-to-r from-blue-600 to-indigo-700 text-white px-16 py-6 rounded-[2.5rem] font-black text-sm uppercase shadow-xl transition-all flex items-center gap-4 disabled:opacity-30 active:scale-95">
                {loading ? 'Processando...' : uploading ? 'Enviando...' : isEditing ? 'Atualizar' : 'Publicar'} 
                <ChevronRightIcon className="h-6 w-6" />
             </button>
          </div>
        </form>
      </div>

      {showRecordReel && (
        <RecordReelModal 
          onClose={() => { setShowRecordReel(false); if(!reelUrl) setPostType(PostType.TEXT); }} 
          onSave={handleReelSaved} 
        />
      )}
    </>
  );
};

export default CreatePost;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Message, ChatConversation } from '../types';
import {
  getChats,
  findUserById,
  getOrCreateConversation,
  sendMessage
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  PhoneIcon, 
  VideoCameraIcon, 
  XMarkIcon, 
  ChatBubbleLeftRightIcon, 
  PhotoIcon, 
  ArrowLeftIcon, 
  PaperAirplaneIcon, 
  CheckBadgeIcon, 
  MagnifyingGlassIcon, 
  UserPlusIcon 
} from '@heroicons/react/24/solid';

interface ChatPageProps {
  currentUser: User;
}

const ConversationItem: React.FC<{ chat: ChatConversation; isActive: boolean; onClick: () => void; currentUser: User }> = ({ chat, isActive, onClick, currentUser }) => {
  const [partner, setPartner] = useState<User | null>(null);

  useEffect(() => {
    const fetchPartner = async () => {
      const partnerId = chat.participants.find(id => id !== currentUser.id);
      if (partnerId) {
        const user = await findUserById(partnerId);
        setPartner(user || null);
      }
    };
    fetchPartner();
  }, [chat, currentUser.id]);

  if (!partner) return null;

  const lastMsg = chat.messages && chat.messages.length > 0 ? chat.messages[chat.messages.length - 1] : null;

  return (
    <button
      onClick={onClick}
      className={`w-full flex items-center p-4 rounded-2xl transition-all ${isActive ? 'bg-blue-600 text-white shadow-xl scale-[1.02]' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
    >
      <div className="relative shrink-0">
        <img src={partner.profilePicture || DEFAULT_PROFILE_PIC} className={`w-14 h-14 rounded-2xl object-cover border-2 ${isActive ? 'border-white/30' : 'border-blue-500'}`} />
        <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white dark:border-darkcard rounded-full shadow-lg"></div>
      </div>
      <div className="ml-4 text-left overflow-hidden flex-1">
        <p className={`font-black text-sm truncate ${isActive ? 'text-white' : 'text-gray-900 dark:text-white'}`}>{partner.firstName} {partner.lastName}</p>
        <p className={`text-[11px] truncate mt-0.5 ${isActive ? 'text-blue-100 font-medium' : 'text-gray-400 font-bold'}`}>
           {lastMsg ? (lastMsg.senderId === currentUser.id ? 'Você: ' : '') + (lastMsg.text || '📷 Imagem') : 'Inicie uma conversa'}
        </p>
      </div>
    </button>
  );
};

