const mapProfileToUser = (profile: any): User => ({
  id: profile.id,
  email: profile.email || '',
  userType: (profile.user_type as UserType) || UserType.STANDARD,
  firstName: profile.first_name || '',
  lastName: profile.last_name || '',
  phone: profile.phone || '',
  documentId: profile.document_id || '',
  birthDate: Number(profile.birth_date) || 0,
  profilePicture: profile.profile_picture || DEFAULT_PROFILE_PIC,
  balance: profile.balance || 0,
  credentials: profile.credentials,
  bio: profile.bio,
  isAdmin: profile.is_admin,
  isVerified: profile.is_verified,
  isSuspended: profile.is_suspended,
  isPremium: profile.is_premium,
  premiumExpiry: profile.premium_expiry,
  followers: profile.followers || [],
  followedUsers: profile.followed_users || [],
  storeId: undefined
});

const mapPostFromDB = (post: any): Post => ({
  id: post.id,
  userId: post.user_id,
  authorName: post.profiles ? `${post.profiles.first_name} ${post.profiles.last_name}` : 'Usuário Desconhecido',
  authorProfilePic: post.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
  type: post.type,
  timestamp: Number(post.timestamp) || new Date(post.created_at).getTime(),
  content: post.content,
  imageUrl: post.image_url,
  fontFamily: post.font_family,
  textColor: post.text_color,
  fontSize: post.font_size,
  backgroundColor: post.background_color,
  isBoosted: post.is_boosted,
  boostExpires: Number(post.boost_expires),
  likes: post.likes || [],
  shares: post.shares || [],
  saves: post.saves || [],
  isPinned: post.is_pinned,
  indicatedUserIds: post.indicated_user_ids || [],
  liveStream: post.live_data,
  reel: post.reel_data,
  comments: [] 
});

const mapProductFromDB = (prod: any): Product => ({
  id: prod.id,
  storeId: prod.store_id,
  name: prod.name,
  description: prod.description,
  price: prod.price,
  imageUrls: prod.image_urls || [],
  affiliateCommissionRate: prod.affiliate_commission_rate,
  type: prod.type,
  averageRating: prod.average_rating || 5,
  ratingCount: prod.rating_count || 0,
  digitalContentUrl: prod.digital_content_url,
  isDropshipping: prod.is_dropshipping,
  externalProviderId: prod.external_provider_id,
