export const getStories = async (): Promise<Story[]> => {
  // Busca da tabela 'stories' e junta com 'profiles'
  const { data, error } = await supabase.from('stories').select('*, profiles!user_id(first_name, last_name, profile_picture)').gte('expires_at', new Date().toISOString());
  if (error || !data) return [];

  // Agrupa stories por usuário
  const storiesMap: Record<string, Story> = {};
  data.forEach((item: any) => {
    if (!storiesMap[item.user_id]) {
      storiesMap[item.user_id] = {
        userId: item.user_id,
        userName: `${item.profiles.first_name} ${item.profiles.last_name}`,
        userProfilePic: item.profiles.profile_picture || DEFAULT_PROFILE_PIC,
        items: []
      };
    }
    storiesMap[item.user_id].items.push({
      id: item.id,
      imageUrl: item.image_url,
      text: item.text,
      background_color: item.backgroundColor,
      text_color: item.textColor,
      font_family: item.fontFamily,
      timestamp: new Date(item.created_at).getTime()
    });
  });

  return Object.values(storiesMap);
};

export const addStory = async (userId: string, item: any) => {
  // Insere na tabela stories
  await supabase.from('stories').insert({
    user_id: userId,
    image_url: item.imageUrl,
    text: item.text,
    background_color: item.backgroundColor,
    text_color: item.textColor,
    font_family: item.fontFamily,
