export const processProductPurchase = async (cart: CartItem[], buyer: string, affiliate: string|null, addr?: ShippingAddress) => {
  for(const i of cart) {
    const p = await findProductById(i.productId);
    if(!p) continue;
    const s = await findStoreById(p.storeId);
    if(!s) continue;
    const total = p.price * i.quantity;
    const comm = affiliate ? total * p.affiliateCommissionRate : 0;
    const net = total - comm;
    await updateUserBalance(s.professorId, net);
    if(affiliate && comm > 0) {
      await updateUserBalance(affiliate, comm);
      createNotification({type: NotificationType.AFFILIATE_SALE, recipientId: affiliate, actorId: buyer, timestamp: Date.now()});
    }
    await supabase.from('sales').insert({product_id: p.id, buyer_id: buyer, affiliate_user_id: affiliate, store_id: s.id, commission_earned: comm, sale_amount: total, status: OrderStatus.WAITLIST, shipping_address: addr, timestamp: Date.now()});
  }
  return true;
};

export const addProductRating = async (sid: string, r: number, c: string) => {
  await supabase.from('sales').update({is_rated: true}).eq('id', sid);
  const {data:s} = await supabase.from('sales').select('product_id').eq('id', sid).single();
  if(s) {
    const p = await findProductById(s.product_id);
    if(p) {
      const newCount = (p.ratingCount || 0) + 1;
      const newAvg = (((p.averageRating || 5) * (p.ratingCount || 0)) + r) / newCount;
      await supabase.from('products').update({average_rating: newAvg, rating_count: newCount}).eq('id', p.id);
    }
  }
  return true;
};

