export const saveCart = (c: CartItem[]) => localStorage.setItem('cyberphone_cart', JSON.stringify(c));
export const addToCart = (pid: string, q: number=1, c?: string) => { const cart=getCart(); const ex=cart.find(i=>i.productId===pid && i.selectedColor===c); if(ex) ex.quantity+=q; else cart.push({productId:pid, quantity:q, selectedColor:c}); saveCart(cart); };
export const updateCartItemQuantity = (pid: string, q: number) => { let cart=getCart(); if(q<=0) cart=cart.filter(i=>i.productId!==pid); else { const i=cart.find(x=>x.productId===pid); if(i) i.quantity=q; } saveCart(cart); };
export const removeFromCart = (pid: string) => saveCart(getCart().filter(i=>i.productId!==pid));
export const clearCart = () => saveCart([]);

export const getNotifications = async (): Promise<Notification[]> => {
  const uid=getCurrentUserId(); if(!uid) return [];
  const {data} = await supabase.from('notifications').select('*').eq('recipient_id', uid);
  return (data||[]).map((n:any)=>({id: n.id, recipientId: n.recipient_id, actorId: n.actor_id, type: n.type, postId: n.post_id, saleId: n.sale_id, isRead: n.is_read, timestamp: Number(n.timestamp)}));
};

export const createNotification = async (n: any) => {
  if(n.recipientId===n.actorId) return;
  await supabase.from('notifications').insert({recipient_id: n.recipientId, actor_id: n.actorId, type: n.type, post_id: n.postId, sale_id: n.saleId, timestamp: n.timestamp, is_read: false});
};

export const getNotificationsForUser = async (uid: string) => {
  const {data} = await supabase.from('notifications').select('*').eq('recipient_id', uid).order('timestamp', {ascending: false});
  return (data||[]).map((n:any)=>({id: n.id, recipientId: n.recipient_id, actorId: n.actor_id, type: n.type, postId: n.post_id, saleId: n.sale_id, isRead: n.is_read, timestamp: Number(n.timestamp)}));
};

export const markNotificationsAsRead = async (uid: string) => {
  await supabase.from('notifications').update({is_read: true}).eq('recipient_id', uid);
};

// ==============================================================================
// CHAT
// ==============================================================================

export const getChats = async (): Promise<ChatConversation[]> => {
  const {data:cs} = await supabase.from('conversations').select('*');
  const chats: ChatConversation[] = [];
  for(const c of (cs||[])) {
    const {data:ms} = await supabase.from('messages').select('*').eq('conversation_id', c.id).order('timestamp', {ascending: true});
    chats.push({id: c.id, participants: c.participants, messages: (ms||[]).map((m:any)=>({id: m.id, senderId: m.sender_id, receiverId: m.receiver_id, text: m.text, imageUrl: m.image_url, timestamp: Number(m.timestamp)}))});
  }
  return chats;
};

export const getOrCreateConversation = async (u1: string, u2: string) => {
  const {data} = await supabase.from('conversations').select('*').contains('participants', [u1, u2]);
  if(data && data.length>0) {
    const c=data[0];
    const {data:ms} = await supabase.from('messages').select('*').eq('conversation_id', c.id);
    return {id: c.id, participants: c.participants, messages: (ms||[]).map((m:any)=>({id: m.id, senderId: m.sender_id, receiverId: m.receiver_id, text: m.text, imageUrl: m.image_url, timestamp: Number(m.timestamp)}))};
  }
  const {data:nc} = await supabase.from('conversations').insert({participants: [u1, u2]}).select().single();
  return {id: nc.id, participants: nc.participants, messages: []};
};

export const sendMessage = async (cid: string, m: Message) => {
  await supabase.from('messages').insert({conversation_id: cid, sender_id: m.senderId, receiver_id: m.receiverId, text: m.text, image_url: m.imageUrl, timestamp: m.timestamp});
};

// ==============================================================================
// FILES & ASSETS
// ==============================================================================

export const uploadFile = async (file: File | Blob, folder: string = 'general'): Promise<string> => {
  try {
    const ext = file instanceof File ? file.name.split('.').pop() : 'webm';
    const name = `${folder}/${Date.now()}-${Math.random().toString(36).substring(7)}.${ext}`;
    const {error} = await supabase.storage.from('cyber-files').upload(name, file);
    if(error) throw error;
    const {data:{publicUrl}} = supabase.storage.from('cyber-files').getPublicUrl(name);
    return publicUrl;
  } catch(e) {
    console.error('Erro upload:', e);
    // Fallback apenas para não quebrar a UI em dev se storage falhar, mas idealmente deve lançar erro
    throw new Error('Upload falhou');
  }
};

export const compressImage = async (f: string|File) => f instanceof File ? uploadFile(f, 'images') : Promise.resolve(f);

export const getAudioTracks = async (): Promise<AudioTrack[]> => {
  // Supondo uma tabela audio_tracks, ou retornando vazio se não existir para não simular
  const {data} = await supabase.from('audio_tracks').select('*');
  if(!data) return [];
  return data.map((t:any) => ({ id: t.id, title: t.title, artist: t.artist, url: t.url }));
};

export const findAudioTrackById = async (id: string): Promise<AudioTrack | undefined> => {
  const {data} = await supabase.from('audio_tracks').select('*').eq('id', id).single();
  return data ? { id: data.id, title: data.title, artist: data.artist, url: data.url } : undefined;
};

// ==============================================================================
// ADMIN & SETTINGS
// ==============================================================================

export const getGlobalSettings = () => {
  const stored = localStorage.getItem('cyber_global_settings');
  return stored ? JSON.parse(stored) : { platformTax: 0.1, upgradeCost: 29.9, minWithdrawal: 50, maintenanceMode: false };
};

export const updateGlobalSettings = (s: any) => localStorage.setItem('cyber_global_settings', JSON.stringify(s));

export const getSystemLogs = async (): Promise<SystemLog[]> => {
  const { data, error } = await supabase.from('logs').select('*').order('timestamp', { ascending: false }).limit(100);
  if (error) return [];
  return (data || []).map((l: any) => ({
    id: l.id, adminId: l.admin_id, action: l.action, targetId: l.target_id, details: l.details, timestamp: Number(l.timestamp)
  }));
};

export const getTransactions = async (): Promise<Transaction[]> => {
  const { data } = await supabase.from('sales').select('*').order('timestamp', { ascending: false });
  return (data || []).map((s: any) => ({
    id: s.id, userId: s.buyer_id, type: TransactionType.PURCHASE, amount: s.sale_amount, description: `Compra de produto ${s.product_id}`, timestamp: Number(s.timestamp), status: 'COMPLETED'
  }));
};

export const getPlatformRevenue = async (): Promise<number> => {
  const { data } = await supabase.from('sales').select('sale_amount');
  if (!data) return 0;
  const settings = getGlobalSettings();
  const totalSales = data.reduce((acc, curr) => acc + curr.sale_amount, 0);
  return totalSales * settings.platformTax;
};

export const getReports = async (): Promise<ContentReport[]> => {
  const { data, error } = await supabase.from('reports').select('*');
  if (error) return [];
  return (data || []).map((r: any) => ({
    id: r.id, reporterId: r.reporter_id, targetId: r.target_id, targetType: r.target_type, reason: r.reason, details: r.details, status: r.status, timestamp: Number(r.timestamp)
  }));
};

export const createReport = async (reportData: any) => {
  await supabase.from('reports').insert({
    reporter_id: reportData.reporterId, target_id: reportData.targetId, target_type: reportData.targetType, reason: reportData.reason, details: reportData.details, status: 'OPEN', timestamp: Date.now()
  });
};

export const adminDeletePost = async (id: string) => { await deletePost(id); };
export const adminDeleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); };
export const adminProcessReport = async (reportId: string, status: string, adminId: string) => { await supabase.from('reports').update({ status }).eq('id', reportId); };
export const adminUpdateUser = async (user: User) => { await updateUser(user); };

