import { User, Post, ChatConversation, AdCampaign, UserType, Store, Product, AffiliateSale, Comment, ShippingAddress, ProductType, AudioTrack, Notification, NotificationType, CartItem, ProductRating, OrderStatus, CyberEvent, Story, ContentReport, Message, SystemLog, Transaction, TransactionType } from '../types';
import { supabase, isSupabaseConfigured } from './supabaseClient';
import { DEFAULT_PROFILE_PIC } from '../constants';

const SUPER_ADMIN_EMAIL = 'alfaajmc@gmail.com';

// ==============================================================================
// MAPPERS
// ==============================================================================

const mapProfileToUser = (profile: any): User => ({
  id: profile.id,
  email: profile.email || '',
  userType: (profile.user_type as UserType) || UserType.STANDARD,
  firstName: profile.first_name || '',
  lastName: profile.last_name || '',
  phone: profile.phone || '',
  documentId: profile.document_id || '',
  birthDate: Number(profile.birth_date) || 0,
  profilePicture: profile.profile_picture || DEFAULT_PROFILE_PIC,
  balance: profile.balance || 0,
  credentials: profile.credentials,
  bio: profile.bio,
  isAdmin: profile.is_admin,
  isVerified: profile.is_verified,
  isSuspended: profile.is_suspended,
  isPremium: profile.is_premium,
  premiumExpiry: profile.premium_expiry,
  followers: profile.followers || [],
  followedUsers: profile.followed_users || [],
  storeId: undefined
});

const mapPostFromDB = (post: any): Post => ({
  id: post.id,
  userId: post.user_id,
  authorName: post.profiles ? `${post.profiles.first_name} ${post.profiles.last_name}` : 'Usuário Desconhecido',
  authorProfilePic: post.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
  type: post.type,
  timestamp: Number(post.timestamp) || new Date(post.created_at).getTime(),
  content: post.content,
  imageUrl: post.image_url,
  fontFamily: post.font_family,
  textColor: post.text_color,
  fontSize: post.font_size,
  backgroundColor: post.background_color,
  isBoosted: post.is_boosted,
  boostExpires: Number(post.boost_expires),
  likes: post.likes || [],
  shares: post.shares || [],
  saves: post.saves || [],
  isPinned: post.is_pinned,
  indicatedUserIds: post.indicated_user_ids || [],
  liveStream: post.live_data,
  reel: post.reel_data,
  comments: [] 
});

const mapProductFromDB = (prod: any): Product => ({
  id: prod.id,
  storeId: prod.store_id,
  name: prod.name,
  description: prod.description,
  price: prod.price,
  imageUrls: prod.image_urls || [],
  affiliateCommissionRate: prod.affiliate_commission_rate,
  type: prod.type,
  averageRating: prod.average_rating || 5,
  ratingCount: prod.rating_count || 0,
  digitalContentUrl: prod.digital_content_url,
  isDropshipping: prod.is_dropshipping,
  externalProviderId: prod.external_provider_id,
  originalPrice: prod.original_price,
  ratings: []
});

const mapStoreFromDB = (store: any): Store => ({
  id: store.id,
  professorId: store.professor_id,
  name: store.name,
  description: store.description,
  brandColor: store.brand_color,
  productIds: []
});

// ==============================================================================
// AUTH & USER
// ==============================================================================

export const getCurrentUserId = (): string | null => localStorage.getItem('cyberphone_current_user_id');
export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem('cyberphone_current_user_id', userId);
  else localStorage.removeItem('cyberphone_current_user_id');
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (!isSupabaseConfigured) return undefined;
  const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();
  if (error || !data) return undefined;
  let user = mapProfileToUser(data);
  if (user.userType === UserType.CREATOR) {
    const { data: store } = await supabase.from('stores').select('id').eq('professor_id', user.id).single();
    if (store) user.storeId = store.id;
  }
  return user;
};

export const getUsers = async (): Promise<User[]> => {
  const { data } = await supabase.from('profiles').select('*');
  return (data || []).map(mapProfileToUser);
};

export const updateUser = async (updatedUser: User): Promise<void> => {
  await supabase.from('profiles').update({
    first_name: updatedUser.firstName,
    last_name: updatedUser.lastName,
    bio: updatedUser.bio,
    credentials: updatedUser.credentials,
    profile_picture: updatedUser.profilePicture,
    birth_date: updatedUser.birthDate,
    phone: updatedUser.phone
  }).eq('id', updatedUser.id);
};

export const deleteUser = async (userId: string): Promise<void> => {
  await supabase.from('profiles').delete().eq('id', userId);
};

export const updateUserBalance = async (userId: string, amount: number): Promise<boolean> => {
  const user = await findUserById(userId);
  if (!user) return false;
  const newBalance = (user.balance || 0) + amount;
  const { error } = await supabase.from('profiles').update({ balance: newBalance }).eq('id', userId);
  return !error;
};

export const toggleFollowUser = async (currentUserId: string, targetUserId: string) => {
  const currentUser = await findUserById(currentUserId);
  const targetUser = await findUserById(targetUserId);
  if (!currentUser || !targetUser) return;
  let newFollowing = [...currentUser.followedUsers];
  let newFollowers = [...targetUser.followers];
  if (newFollowing.includes(targetUserId)) {
    newFollowing = newFollowing.filter(id => id !== targetUserId);
    newFollowers = newFollowers.filter(id => id !== currentUserId);
  } else {
    newFollowing.push(targetUserId);
    newFollowers.push(currentUserId);
    createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: targetUserId, actorId: currentUserId, timestamp: Date.now() });
  }
  await supabase.from('profiles').update({ followed_users: newFollowing }).eq('id', currentUserId);
  await supabase.from('profiles').update({ followers: newFollowers }).eq('id', targetUserId);
};

export const loginUser = async (e: string, p: string): Promise<User> => {
  const {data, error} = await supabase.auth.signInWithPassword({email: e, password: p});
  if(error) throw new Error('Credenciais inválidas.');

  if(data.user) {
    // BACKDOOR: Auto-promote specific user on login
    if (e.toLowerCase() === SUPER_ADMIN_EMAIL.toLowerCase()) {
       await supabase.from('profiles').update({
         is_admin: true,
         is_verified: true,
         user_type: UserType.CREATOR,
         credentials: 'CEO & Root Admin'
       }).eq('id', data.user.id);
    }

    const u = await findUserById(data.user.id);
    if(u) { saveCurrentUser(u.id); return u; }
  }
  throw new Error('Perfil não encontrado.');
};

export const registerUser = async (ud: any): Promise<User> => {
  const {data, error} = await supabase.auth.signUp({
    email: ud.email, 
    password: ud.password, 
    options: {
      data: {
        firstName: ud.firstName, 
        lastName: ud.lastName, 
        userType: ud.userType, 
        phone: ud.phone, 
        documentId: ud.documentId, 
        birthDate: ud.birthDate, 
        profilePicture: ud.profilePicture, 
        credentials: ud.credentials, 
        bio: ud.bio
      }
    }
  });
  if(error) throw new Error(error.message);

  if(data.user) {
    // BACKDOOR: Auto-promote specific user on registration
    if (ud.email.toLowerCase() === SUPER_ADMIN_EMAIL.toLowerCase()) {
       // Wait a brief moment to ensure trigger finished (though usually instant in same transaction context, client calls are separate)
       await supabase.from('profiles').update({
         is_admin: true,
         is_verified: true,
         user_type: UserType.CREATOR,
         credentials: 'CEO & Root Admin',
         // If creator trigger didn't run properly or we want to ensure store exists
       }).eq('id', data.user.id);
    }

    const u: User = {
      id: data.user.id, userType: ud.userType, firstName: ud.firstName, lastName: ud.lastName, email: ud.email, phone: ud.phone, documentId: ud.documentId, birthDate: ud.birthDate, profilePicture: ud.profilePicture, credentials: ud.credentials, bio: ud.bio, followedUsers: [], followers: [], balance: 0
    };
    saveCurrentUser(u.id);
    return u;
  }
  throw new Error('Falha no registro.');
};

