export const getPosts = async (): Promise<Post[]> => {
  const { data } = await supabase.from('posts').select('*, profiles!user_id(first_name, last_name, profile_picture)').order('timestamp', { ascending: false });
  return await Promise.all((data || []).map(async (p) => {
    const post = mapPostFromDB(p);
    const { data: comments } = await supabase.from('comments').select('*, profiles!user_id(first_name, last_name, profile_picture)').eq('post_id', post.id);
    post.comments = (comments || []).map((c: any) => ({
      id: c.id, userId: c.user_id, userName: `${c.profiles.first_name} ${c.profiles.last_name}`, profilePic: c.profiles.profile_picture, text: c.text, timestamp: Number(c.timestamp)
    }));
    return post;
  }));
};

export const addPost = async (post: Post) => {
  await supabase.from('posts').insert({
    user_id: post.userId, type: post.type, content: post.content, image_url: post.imageUrl, timestamp: post.timestamp, live_data: post.liveStream, reel_data: post.reel, font_family: post.fontFamily, text_color: post.textColor, background_color: post.backgroundColor, font_size: post.fontSize
  });
};

export const updatePost = async (post: Post) => {
  await supabase.from('posts').update({
    content: post.content, image_url: post.imageUrl, live_data: post.liveStream, reel_data: post.reel, font_family: post.fontFamily, text_color: post.textColor, background_color: post.backgroundColor, font_size: post.fontSize, is_pinned: post.isPinned, is_boosted: post.isBoosted, boost_expires: post.boostExpires, indicated_user_ids: post.indicatedUserIds
  }).eq('id', post.id);
};

export const deletePost = async (postId: string) => { await supabase.from('posts').delete().eq('id', postId); };

export const updatePostLikes = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('likes, user_id').eq('id', postId).single();
  if (!data) return;
  let likes = data.likes || [];
  if (likes.includes(userId)) likes = likes.filter((id: string) => id !== userId);
  else {
    likes.push(userId);
    if(data.user_id !== userId) createNotification({type: NotificationType.LIKE, recipientId: data.user_id, actorId: userId, postId, timestamp: Date.now()});
  }
  await supabase.from('posts').update({ likes }).eq('id', postId);
};

export const updatePostSaves = async (p: string, u: string) => {
  const {data} = await supabase.from('posts').select('saves').eq('id', p).single();
  if(!data) return;
  let s = data.saves||[];
  if(s.includes(u)) s=s.filter((i:string)=>i!==u); else s.push(u);
  await supabase.from('posts').update({saves:s}).eq('id', p);
};

export const updatePostShares = async (p: string, u: string) => {
  const {data} = await supabase.from('posts').select('shares').eq('id', p).single();
  if(!data) return;
  let s = data.shares||[];
  if(!s.includes(u)) { s.push(u); await supabase.from('posts').update({shares:s}).eq('id', p); }
};

export const addPostComment = async (pId: string, c: Comment) => {
  await supabase.from('comments').insert({ post_id: pId, user_id: c.userId, text: c.text, timestamp: c.timestamp });
  const {data} = await supabase.from('posts').select('user_id').eq('id', pId).single();
  if(data && data.user_id !== c.userId) createNotification({type: NotificationType.COMMENT, recipientId: data.user_id, actorId: c.userId, postId: pId, timestamp: Date.now()});
};

export const pinPost = async (p: string, u: string) => {
  await supabase.from('posts').update({is_pinned: false}).eq('user_id', u);
  await supabase.from('posts').update({is_pinned: true}).eq('id', p);
  return true;
};

export const unpinPost = async (p: string, u: string) => {
  await supabase.from('posts').update({is_pinned: false}).eq('id', p);
  return true;
};

export const boostPost = async (p: string, u: string, b: number, d: number) => {
  if(await updateUserBalance(u, -b)) {
    await supabase.from('posts').update({is_boosted: true, boost_expires: Date.now()+(d*86400000)}).eq('id', p);
    return true;
  }
  return false;
};

export const indicatePostToUser = async (p: string, f: string, t: string) => {
  const {data} = await supabase.from('posts').select('indicated_user_ids').eq('id', p).single();
  if(!data) return false;
  const i = data.indicated_user_ids||[];
  if(i.includes(t)) return false;
  i.push(t);
  await supabase.from('posts').update({indicated_user_ids: i}).eq('id', p);
  createNotification({type: NotificationType.INDICATION, recipientId: t, actorId: f, postId: p, timestamp: Date.now()});
  return true;
};

