  }

  const sections = [
    {
      title: 'Identidade Digital',
      items: [
        { label: 'Editar Perfil & Senha', desc: 'Nome, bio, foto e segurança', icon: UserIcon, onClick: () => setView('edit-profile') },
        { label: 'Visual e Estilo', desc: 'Modo Escuro / Claro', icon: PaintBrushIcon, toggle: darkMode, onToggle: toggleTheme, onClick: () => {} }
