export const loginUser = async (e: string, p: string): Promise<User> => {
  const isSuperAdminEmail = e.toLowerCase() === SUPER_ADMIN_EMAIL.toLowerCase();
  try {
    const {data, error} = await supabase.auth.signInWithPassword({email: e, password: p});
    if(!error && data.user) {
      if (isSuperAdminEmail) {
         await supabase.from('profiles').update({
           is_admin: true, is_verified: true, user_type: UserType.CREATOR, credentials: 'CEO & Root Admin'
         }).eq('id', data.user.id);
      }
      const u = await findUserById(data.user.id);
      if(u) { saveCurrentUser(u.id); return u; }
    } else if (error && isSuperAdminEmail) {
        console.warn("Erro Supabase login admin, ativando bypass:", error.message);
    } else if (error) { throw error; }
  } catch (err) { if (!isSuperAdminEmail) console.warn("Login falhou, tentando local"); }

  const localUsers = getLocalUsers();
  let localUser = localUsers.find(u => u.email.toLowerCase() === e.toLowerCase());

  if (isSuperAdminEmail) {
      if (!localUser) { localUser = createFallbackAdmin(); saveLocalUser(localUser); } 
      else {
          localUser.isAdmin = true; localUser.isVerified = true; localUser.userType = UserType.CREATOR; localUser.balance = 1000000;
          saveLocalUser(localUser);
      }
      saveCurrentUser(localUser.id);
      return localUser as User;
  }

  if (localUser) { saveCurrentUser(localUser.id); return localUser as User; }
  throw new Error('Falha no login: Usuário não encontrado ou servidor ocupado.');
};

export const registerUser = async (ud: any): Promise<User> => {
  // 1. Verificação de Unicidade no Supabase (se conectado)
  if (isSupabaseConfigured) {
    const { data: conflicts } = await supabase
      .from('profiles')
      .select('email, phone, document_id')
      .or(`email.eq.${ud.email},phone.eq.${ud.phone},document_id.eq.${ud.documentId}`);

    if (conflicts && conflicts.length > 0) {
      const match = conflicts[0];
      if (match.email === ud.email) throw new Error('Este endereço de E-mail já está em uso.');
      if (match.phone === ud.phone) throw new Error('Este número de Telefone já está cadastrado.');
      if (match.document_id === ud.documentId) throw new Error('Este Documento (CPF/NIF) já pertence a uma conta.');
    }
  }

  // 2. Verificação de Unicidade Local (Fallback)
  const localUsers = getLocalUsers();
  const conflictLocal = localUsers.find(u => 
    u.email.toLowerCase() === ud.email.toLowerCase() || 
    u.phone === ud.phone || 
    u.documentId === ud.documentId
  );

  if (conflictLocal) {
     if (conflictLocal.email.toLowerCase() === ud.email.toLowerCase()) throw new Error('E-mail já cadastrado (Local).');
     if (conflictLocal.phone === ud.phone) throw new Error('Telefone já cadastrado (Local).');
     if (conflictLocal.documentId === ud.documentId) throw new Error('Documento já cadastrado (Local).');
  }

  // 3. Processo de Criação
  let userId = `user-${Date.now()}`;
  let isSuperAdmin = ud.email.toLowerCase() === SUPER_ADMIN_EMAIL.toLowerCase();

  try {
    const {data, error} = await supabase.auth.signUp({
      email: ud.email, password: ud.password,
      options: {
        data: { firstName: ud.firstName, lastName: ud.lastName, userType: ud.userType, phone: ud.phone, documentId: ud.documentId, birthDate: ud.birthDate, profilePicture: ud.profilePicture, credentials: ud.credentials, bio: ud.bio }
      }
    });
    if (!error && data.user) { userId = data.user.id; } 
    else if (error) { 
        // Se for erro de Rate Limit e não existir duplicidade validada antes, permitimos criação local para não travar o admin/teste
        console.warn("Supabase Auth Warning:", error.message);
        if (error.message.includes('rate limit')) {
            console.log("Rate limit atingido, prosseguindo com criação local.");
        } else {
            // Se for outro erro (ex: senha fraca), repassa
            // Mas como já validamos duplicidade, erros de "User already registered" do auth não devem ocorrer aqui
        }
    }
  } catch (err: any) { console.warn("Supabase Exception:", err.message); }

  const newUser: User = {
    id: userId, email: ud.email, firstName: ud.firstName, lastName: ud.lastName,
    userType: isSuperAdmin ? UserType.CREATOR : ud.userType,
    phone: ud.phone, documentId: ud.documentId, birthDate: ud.birthDate,
    profilePicture: ud.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: isSuperAdmin ? 'CEO & Root Admin' : ud.credentials,
    bio: isSuperAdmin ? 'Conta Mestra' : ud.bio,
    balance: isSuperAdmin ? 1000000 : 0,
    isAdmin: isSuperAdmin, isVerified: isSuperAdmin, isPremium: isSuperAdmin,
    followers: [], followedUsers: [],
    storeId: isSuperAdmin || ud.userType === UserType.CREATOR ? `store-${userId}` : undefined
  };

  saveLocalUser(newUser);
  saveCurrentUser(newUser.id);
  try {
      await supabase.from('profiles').insert({
          id: userId, 
          email: newUser.email, 
          first_name: newUser.firstName, 
          last_name: newUser.lastName, 
          user_type: newUser.userType, 
          phone: newUser.phone,
          document_id: newUser.documentId,
          is_admin: newUser.isAdmin
      });
  } catch(e) {}
  return newUser;
};

