const getLocalUsers = (): any[] => {
  try { return JSON.parse(localStorage.getItem(LOCAL_STORAGE_USERS_KEY) || '[]'); } catch { return []; }
};
const saveLocalUser = (user: any) => {
  const users = getLocalUsers();
  const index = users.findIndex(u => u.id === user.id);
  if (index >= 0) users[index] = user; else users.push(user);
  localStorage.setItem(LOCAL_STORAGE_USERS_KEY, JSON.stringify(users));
};

const getLocalPosts = (): any[] => {
  try { return JSON.parse(localStorage.getItem(LOCAL_STORAGE_POSTS_KEY) || '[]'); } catch { return []; }
};
const saveLocalPost = (post: any) => {
  const posts = getLocalPosts();
  const index = posts.findIndex(p => p.id === post.id);
  if (index >= 0) posts[index] = post; else posts.unshift(post); // Add to beginning
  localStorage.setItem(LOCAL_STORAGE_POSTS_KEY, JSON.stringify(posts));
};

const getLocalStories = (): any[] => {
  try { return JSON.parse(localStorage.getItem(LOCAL_STORAGE_STORIES_KEY) || '[]'); } catch { return []; }
};
const saveLocalStory = (story: any) => {
  const stories = getLocalStories();
  // Stories logic is complex (grouped by user), handling simplistically for backup
  const index = stories.findIndex(s => s.userId === story.userId);
  if (index >= 0) stories[index] = story; else stories.push(story);
  localStorage.setItem(LOCAL_STORAGE_STORIES_KEY, JSON.stringify(stories));
};

