export const getPosts = async (): Promise<Post[]> => {
  let posts: Post[] = [];
  try {
    const { data } = await supabase.from('posts').select('*, profiles!user_id(first_name, last_name, profile_picture)').order('timestamp', { ascending: false });
    if (data && data.length > 0) {
        posts = data.map(mapPostFromDB);
    }
  } catch(e) {}

  if (posts.length === 0) {
      // Fallback para local se o banco estiver vazio ou offline
      const local = getLocalPosts();
      // Ordena por timestamp
      posts = local.sort((a: Post, b: Post) => b.timestamp - a.timestamp);
  }
  return posts;
};

