                <div className="relative">
                  <CalendarDaysIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className={inputClasses + " pl-10"} />
                </div>
              </div>
            </>
          )}

          <input type="email" placeholder="E-mail de acesso" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="space-y-4">
               <div className="relative">
                  <div className="flex bg-gray-50 dark:bg-white/5 rounded-2xl border-2 border-transparent focus-within:border-blue-500 transition-all shadow-inner overflow-visible">
                     <button 
                       type="button" 
                       onClick={() => setShowCountryPicker(!showCountryPicker)}
                       className="flex items-center gap-2 px-4 border-r border-gray-200 dark:border-white/10 hover:bg-gray-100 dark:hover:bg-white/5 transition-colors shrink-0"
                     >
