  return {
    id: post.id,
    userId: post.user_id,
    authorName: profile ? `${profile.first_name} ${profile.last_name}` : 'Usuário Desconhecido',
    authorProfilePic: profile?.profile_picture || DEFAULT_PROFILE_PIC,
