    // Se vierem apenas IDs dos comentários (para contagem), mapeamos para um array stub
    comments: post.comments ? (Array.isArray(post.comments) ? post.comments.map((c: any) => ({ id: c.id, text: '...', userId: '', userName: '', timestamp: 0 })) : []) : []
