export const getPosts = async (limit: number = 50): Promise<Post[]> => {
  let posts: Post[] = [];
  if (isSupabaseConfigured) {
    try {
      const { data, error } = await supabase
        .from('posts')
        .select(`
          *,
          profiles:user_id (first_name, last_name, profile_picture),
          comments (id)
        `)
        .order('is_pinned', { ascending: false })
        .order('timestamp', { ascending: false })
        .limit(limit);

      if (error) throw error;

      if (data) {
        posts = data.map(mapPostFromDB);
      }
    } catch (e) {
      console.error("Erro ao buscar posts:", e);
    }
  }

  if (posts.length === 0) {
      const local = getLocalPosts();
      posts = local.sort((a: Post, b: Post) => b.timestamp - a.timestamp).slice(0, limit);
  }
  return posts;
};

