export const updatePostLikes = async (postId: string, userId: string) => {
  // Update Local
  const localPosts = getLocalPosts();
  const postIndex = localPosts.findIndex(p => p.id === postId);
  if (postIndex >= 0) {
      let likes = localPosts[postIndex].likes || [];
      if (likes.includes(userId)) likes = likes.filter((id: string) => id !== userId);
      else likes.push(userId);
      localPosts[postIndex].likes = likes;
      localStorage.setItem(LOCAL_STORAGE_POSTS_KEY, JSON.stringify(localPosts));
  }

  // Update DB
  try {
      const { data } = await supabase.from('posts').select('likes').eq('id', postId).single();
      if (data) {
          let likes = data.likes || [];
          if (likes.includes(userId)) likes = likes.filter((id: string) => id !== userId);
          else likes.push(userId);
          await supabase.from('posts').update({ likes }).eq('id', postId);
      }
  } catch(e) {}
};

