export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (isSupabaseConfigured) {
    try {
      const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();
      if (data && !error) {
        let user = mapProfileToUser(data);
        if (user.userType === UserType.CREATOR) {
          const { data: store } = await supabase.from('stores').select('id').eq('professor_id', user.id).single();
          if (store) user.storeId = store.id;
        }
        return user;
      }
    } catch (e) {}
  }
  const localUsers = getLocalUsers();
  const localUser = localUsers.find(u => u.id === userId);
  return localUser ? localUser as User : undefined;
};

export const getUsers = async (): Promise<User[]> => {
