export const deletePost = async (postId: string) => { 
    const posts = getLocalPosts().filter(p => p.id !== postId);
    localStorage.setItem(LOCAL_STORAGE_POSTS_KEY, JSON.stringify(posts));
    try { await supabase.from('posts').delete().eq('id', postId); } catch(e){} 
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const localPosts = getLocalPosts();
  const postIndex = localPosts.findIndex(p => p.id === postId);
  if (postIndex >= 0) {
      let likes = localPosts[postIndex].likes || [];
      if (likes.includes(userId)) likes = likes.filter((id: string) => id !== userId);
      else likes.push(userId);
      localPosts[postIndex].likes = likes;
      localStorage.setItem(LOCAL_STORAGE_POSTS_KEY, JSON.stringify(localPosts));
  }

  try {
      const { data } = await supabase.from('posts').select('likes').eq('id', postId).single();
      if (data) {
          let likes = data.likes || [];
          if (likes.includes(userId)) likes = likes.filter((id: string) => id !== userId);
          else likes.push(userId);
          await supabase.from('posts').update({ likes }).eq('id', postId);
      }
  } catch(e) {}
};

export const updatePostSaves = async (p: string, u: string) => {
    const localPosts = getLocalPosts();
    const post = localPosts.find(post => post.id === p);
    if(post) {
       let saves = post.saves || [];
       if(saves.includes(u)) saves = saves.filter((i:string) => i!==u); else saves.push(u);
       post.saves = saves;
       localStorage.setItem(LOCAL_STORAGE_POSTS_KEY, JSON.stringify(localPosts));
    }
    try {
        const {data} = await supabase.from('posts').select('saves').eq('id', p).single();
        if(data) {
            let s = data.saves||[];
            if(s.includes(u)) s=s.filter((i:string)=>i!==u); else s.push(u);
            await supabase.from('posts').update({saves:s}).eq('id', p);
        }
    } catch(e) {}
};

export const updatePostShares = async (p: string, u: string) => {
    try {
        const {data} = await supabase.from('posts').select('shares').eq('id', p).single();
        if(data) {
            let s = data.shares||[];
            if(!s.includes(u)) { s.push(u); await supabase.from('posts').update({shares:s}).eq('id', p); }
        }
    } catch(e) {}
};

export const addPostComment = async (pId: string, c: Comment) => {
    const localPosts = getLocalPosts();
    const post = localPosts.find(p => p.id === pId);
    if (post) {
        if (!post.comments) post.comments = [];
        post.comments.push(c);
        localStorage.setItem(LOCAL_STORAGE_POSTS_KEY, JSON.stringify(localPosts));
    }

    try {
        await supabase.from('comments').insert({ post_id: pId, user_id: c.userId, text: c.text, timestamp: c.timestamp });
    } catch(e) {}
};

