export const saveProducts = async (products: Product[]) => {
    try {
        for(const p of products) {
            // Se o ID não for UUID válido, o banco vai rejeitar.
            // O componente deve gerar o UUID.
            const py = { 
                id: p.id,
                store_id: p.storeId, 
                name: p.name, 
                description: p.description, 
                price: p.price, 
                image_urls: p.imageUrls, 
                affiliate_commission_rate: p.affiliateCommissionRate, 
                type: p.type, 
                digital_content_url: p.digitalContentUrl, 
                is_dropshipping: p.isDropshipping, 
                external_provider_id: p.externalProviderId, 
                original_price: p.originalPrice 
            };

            // Upsert é mais seguro se ID já existe
            const { error } = await supabase.from('products').upsert(py);
            if (error) console.error("Erro salvar produto:", error);
        }
    } catch(e) {}
};

