              </button>
              <button 
                onClick={() => setFilter('MY_EVENTS')}
                className={`px-6 py-2.5 rounded-xl font-black text-[10px] uppercase transition-all ${filter === 'MY_EVENTS' ? 'bg-white dark:bg-darkcard text-blue-600 shadow-md' : 'text-gray-500'}`}
              >
                Meus Eventos
              </button>
