// Helper to simulate delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Helper for UUID
export const generateUUID = (): string => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2);
};

// Helper for File Upload (Mock)
export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  await delay(500);
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.readAsDataURL(file);
  });
};

// Users
export const getUsers = (): User[] => JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
export const saveUsers = (users: User[]) => localStorage.setItem(USERS_KEY, JSON.stringify(users));

export const findUserById = (userId: string): User | undefined => getUsers().find(u => u.id === userId);

export const loginUser = async (email: string, password: string): Promise<User> => {
  await delay(500);
  const users = getUsers();
  const user = users.find(u => u.email === email);
  if (user) return user; 
  throw new Error('Credenciais inválidas.');
};

export const registerUser = async (userData: any): Promise<User> => {
  await delay(500);
  const users = getUsers();
  if (users.some(u => u.email === userData.email)) throw new Error('Email já cadastrado.');

  const newUser: User = {
    id: `user-${Date.now()}`,
    ...userData,
    followers: [],
    followedUsers: [],
    balance: 0
  };

  if (newUser.userType === UserType.CREATOR) {
    const stores = getStores();
    const storeId = `store-${Date.now()}`;
    newUser.storeId = storeId;
    stores.push({
      id: storeId,
      professorId: newUser.id,
      name: `Loja de ${newUser.firstName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: []
    });
    saveStores(stores);
  }

  saveUsers([...users, newUser]);
  return newUser;
};

export const updateUser = async (updatedUser: User): Promise<void> => {
  const users = getUsers().map(u => u.id === updatedUser.id ? updatedUser : u);
  saveUsers(users);
};

export const deleteUser = async (userId: string): Promise<void> => {
  const users = getUsers().filter(u => u.id !== userId);
  saveUsers(users);
};

export const getCurrentUserId = (): string | null => localStorage.getItem(CURRENT_USER_KEY);
export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem(CURRENT_USER_KEY, userId);
  else localStorage.removeItem(CURRENT_USER_KEY);
};

export const recoverPassword = async (email: string): Promise<void> => {
  await delay(500);
  const users = getUsers();
  if (!users.find(u => u.email === email)) throw new Error('Email não encontrado.');
};

export const updateUserPassword = async (password: string): Promise<void> => {
  await delay(500);
};

export const adminUpdateUser = async (user: User) => updateUser(user);

export const toggleFollowUser = (currentUserId: string, targetUserId: string) => {
  const users = getUsers();
  const current = users.find(u => u.id === currentUserId);
  const target = users.find(u => u.id === targetUserId);

  if (current && target) {
    if (current.followedUsers.includes(targetUserId)) {
      current.followedUsers = current.followedUsers.filter(id => id !== targetUserId);
      target.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      current.followedUsers.push(targetUserId);
      target.followers.push(currentUserId);
      createNotification({
        type: NotificationType.NEW_FOLLOWER,
        recipientId: targetUserId,
        actorId: currentUserId,
        timestamp: Date.now()
      });
    }
    saveUsers(users);
  }
};

export const updateUserBalance = (userId: string, amount: number) => {
  const users = getUsers();
  const user = users.find(u => u.id === userId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    saveUsers(users);

    const transactions = getTransactions();
    transactions.push({
      id: generateUUID(),
      userId,
      type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
      amount,
      description: amount > 0 ? 'Depósito/Recebimento' : 'Saque/Pagamento',
      timestamp: Date.now(),
      status: 'COMPLETED'
    });
    saveTransactions(transactions);
    return true;
  }
  return false;
};

