export const addPost = async (post: Post) => {
  const posts = getPosts();
  savePosts([post, ...posts]);

  const user = findUserById(post.userId);
  if (user) {
    user.followers.forEach(followerId => {
      createNotification({
        type: NotificationType.NEW_POST,
        recipientId: followerId,
        actorId: post.userId,
        postId: post.id,
        timestamp: Date.now()
      });
    });
  }
};

export const updatePost = async (post: Post) => {
  const posts = getPosts().map(p => p.id === post.id ? post : p);
  savePosts(posts);
};

export const deletePost = (postId: string) => {
  const posts = getPosts().filter(p => p.id !== postId);
  savePosts(posts);
};

export const adminDeletePost = async (postId: string) => deletePost(postId);

export const updatePostLikes = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) {
      post.likes = post.likes.filter(id => id !== userId);
    } else {
      post.likes.push(userId);
      createNotification({
        type: NotificationType.LIKE,
        recipientId: post.userId,
        actorId: userId,
        postId,
        timestamp: Date.now()
      });
    }
    savePosts(posts);
  }
};

export const updatePostShares = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    savePosts(posts);
  }
};

export const updatePostSaves = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) {
      post.saves = post.saves.filter(id => id !== userId);
    } else {
      post.saves.push(userId);
    }
    savePosts(posts);
  }
};

export const addPostComment = (postId: string, comment: Comment) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    post.comments.push(comment);
    savePosts(posts);
    createNotification({
      type: NotificationType.COMMENT,
      recipientId: post.userId,
      actorId: comment.userId,
      postId,
      timestamp: Date.now()
    });
  }
};

export const pinPost = (postId: string, userId: string) => {
  const posts = getPosts();
  posts.forEach(p => {
    if (p.userId === userId) p.isPinned = p.id === postId;
  });
  savePosts(posts);
};

export const unpinPost = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId && p.userId === userId);
  if (post) {
    post.isPinned = false;
    savePosts(posts);
  }
};

export const boostPost = (postId: string, userId: string, budget: number, days: number): boolean => {
  if (updateUserBalance(userId, -budget)) {
    const posts = getPosts();
    const post = posts.find(p => p.id === postId);
    if (post) {
      post.isBoosted = true;
      post.boostExpires = Date.now() + (days * 24 * 60 * 60 * 1000);
      savePosts(posts);
      return true;
    }
  }
  return false;
};

export const indicatePostToUser = (postId: string, fromUserId: string, toUserId: string): boolean => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (!post.indicatedUserIds) post.indicatedUserIds = [];
    if (post.indicatedUserIds.includes(toUserId)) return false;
    post.indicatedUserIds.push(toUserId);
    savePosts(posts);
    createNotification({
      type: NotificationType.INDICATION,
      recipientId: toUserId,
      actorId: fromUserId,
      postId,
      timestamp: Date.now()
    });
    return true;
  }
  return false;
};

