export const getOrCreateConversation = async (user1Id: string, user2Id: string): Promise<ChatConversation> => {
  const chats = getChats();
  let chat = chats.find(c => c.participants.includes(user1Id) && c.participants.includes(user2Id));
  if (!chat) {
    chat = { id: `chat-${generateUUID()}`, participants: [user1Id, user2Id], messages: [] };
    saveChats([...chats, chat]);
  }
  return chat;
};

export const sendMessage = async (chatId: string, message: any) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === chatId);
  if (chat) {
    chat.messages.push(message);
    saveChats(chats);

    const receiverId = chat.participants.find(p => p !== message.senderId);
    if (receiverId) {
      createNotification({
        type: NotificationType.MESSAGE,
        recipientId: receiverId,
        actorId: message.senderId,
        timestamp: Date.now()
      });
    }
  }
};

