export const processProductPurchase = (items: CartItem[], buyerId: string, affiliateId: string | null, address?: ShippingAddress): boolean => {
  const sales = getAffiliateSales();
  const products = getProducts();
  const users = getUsers();
  const stores = getStores();

  items.forEach(item => {
    const product = products.find(p => p.id === item.productId);
    if (!product) return;

    const store = stores.find(s => s.id === product.storeId);
    if (!store) return;

    const owner = users.find(u => u.id === store.professorId);
    if (!owner) return;

    const total = product.price * item.quantity;
    const commission = affiliateId ? total * product.affiliateCommissionRate : 0;
    const net = total - commission; 

    owner.balance = (owner.balance || 0) + net;

    if (affiliateId) {
      const affiliate = users.find(u => u.id === affiliateId);
      if (affiliate) {
        affiliate.balance = (affiliate.balance || 0) + commission;
        createNotification({
          type: NotificationType.AFFILIATE_SALE,
          recipientId: affiliateId,
          actorId: buyerId,
          timestamp: Date.now()
        });
      }
    }

    sales.push({
      id: `sale-${generateUUID()}`,
      productId: item.productId,
      buyerId,
      affiliateUserId: affiliateId || '',
      storeId: product.storeId,
      commissionEarned: commission,
      saleAmount: total,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      shippingAddress: address,
      digitalContentUrl: product.digitalContentUrl
    });
  });

  saveUsers(users);
  saveAffiliateSales(sales);
  clearCart();
  return true;
};

export const addProductRating = (saleId: string, rating: number, comment: string) => {
  const sales = getAffiliateSales();
  const sale = sales.find(s => s.id === saleId);
  if (sale && !sale.isRated) {
    sale.isRated = true;
    saveAffiliateSales(sales);

    const products = getProducts();
    const product = products.find(p => p.id === sale.productId);
    if (product) {
      product.ratings.push({
        id: generateUUID(),
        saleId,
        userId: sale.buyerId,
        rating,
        comment,
        timestamp: Date.now()
      });
      product.ratingCount++;
      product.averageRating = product.ratings.reduce((acc, r) => acc + r.rating, 0) / product.ratingCount;
      saveProducts(products);
    }
  }
};

