async function getGeminiClient(): Promise<GoogleGenAI> {
  const apiKey = typeof process !== 'undefined' ? process.env.API_KEY : '';
  if (!apiKey) {
    throw new Error('API_KEY is not defined.');
  }
  return new GoogleGenAI({ apiKey });
}

