        return;
      }

      setVerificationFileName(file.name);
      const reader = new FileReader();
      reader.onloadend = () => {
        setVerificationFile(reader.result as string);
        setError(''); // Limpa erros anteriores
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !phone || !documentId || !birthDate || !password) {
      setError('Preencha todos os campos obrigatórios.');
      return;
    }

    if (userType === UserType.CREATOR && !verificationFile) {
      setError('Para conta profissional, o envio do documento é obrigatório.');
      return;
    }

    setLoading(true);
    setLoadingMessage('Criando conta...');

    try {
      if (userType === UserType.CREATOR && verificationFile) {
        setLoadingMessage('A IA está auditando seu documento...');
        const analysis = await verifyProfessionalDocument(verificationFile);

        if (!analysis.isValid) {
          // Erro específico da validação
          throw new Error(`Documento Recusado: ${analysis.reason}`);
        }

        // Se a IA detectou a profissão e o campo estava vazio, preenche auto
        if (analysis.professionDetected && !credentials) {
           setCredentials(analysis.professionDetected);
        }
      }

      const fullPhone = `${selectedCountry.ddi} ${phone}`;
      const newUser = await registerUser({
        userType, firstName, lastName, email, phone: fullPhone, documentId,
        birthDate: new Date(birthDate).getTime(), password, profilePicture: profilePicBase64,
        credentials: userType === UserType.CREATOR ? credentials : undefined,
        bio: bio || undefined, verificationFileUrl: verificationFile || undefined
      });
      saveCurrentUser(newUser.id);
      onLoginSuccess(newUser);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Erro desconhecido no cadastro.');
    } finally {
      setLoading(false);
      setLoadingMessage('');
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!email || !password) {
      setError('Email e senha obrigatórios.');
      return;
    }
    setLoading(true);
    setLoadingMessage('Entrando...');
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError('Credenciais inválidas.');
    } finally {
      setLoading(false);
      setLoadingMessage('');
    }
  };

  const handleRecovery = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccessMessage('');
    if (!email) {
      setError('Digite seu e-mail para recuperar.');
      return;
    }
    setLoading(true);
    setLoadingMessage('Enviando link...');
    try {
      await recoverPassword(email);
      setSuccessMessage(`Um link de recuperação foi enviado para ${email}. Verifique sua caixa de entrada.`);
    } catch (err: any) {
      setError(err.message || 'Erro ao enviar recuperação.');
    } finally {
      setLoading(false);
      setLoadingMessage('');
    }
  };

  if (isRecovery) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4 font-sans">
        <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10">
           <button onClick={() => { setIsRecovery(false); setError(''); setSuccessMessage(''); }} className="mb-6 flex items-center text-gray-400 hover:text-blue-600 font-bold text-xs uppercase tracking-widest gap-2 transition-colors">
              <ArrowLeftIcon className="h-4 w-4" /> Voltar
           </button>

           <div className="mb-8 flex flex-col items-center">
              <div className="bg-blue-50 dark:bg-blue-900/10 p-4 rounded-full mb-4">
                 <ShieldCheckIcon className="h-10 w-10 text-blue-600" />
              </div>
              <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter">Recuperar Acesso</h2>
              <p className="text-center text-gray-400 text-xs font-medium mt-2">Informe seu e-mail para receber um link seguro de redefinição.</p>
           </div>

           {error && <div className="bg-red-50 dark:bg-red-900/20 text-red-600 p-4 rounded-2xl text-[10px] font-black mb-6 text-center uppercase tracking-widest">{error}</div>}
           {successMessage && <div className="bg-green-50 dark:bg-green-900/20 text-green-600 p-4 rounded-2xl text-[10px] font-black mb-6 text-center uppercase tracking-widest">{successMessage}</div>}

           <form onSubmit={handleRecovery} className="space-y-6">
              <div className="relative">
                 <EnvelopeIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                 <input type="email" placeholder="Seu e-mail cadastrado" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses + " pl-12"} />
              </div>
              <button 
                type="submit" 
                disabled={loading} 
                className="w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 bg-blue-600 text-white disabled:opacity-50"
              >
                {loading ? 'Enviando...' : 'Enviar Link de Resgate'}
              </button>
           </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4 font-sans">
      <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10 relative overflow-visible">

        <div className="mb-6 flex flex-col items-center">
          <Logo size="lg" className="mb-1" />
          <p className="text-center text-gray-400 font-bold uppercase text-[8px] tracking-[0.25em] opacity-80">
            {isRegister ? 'Ecossistema Digital' : 'Bem-vindo ao CyBerPhone'}
          </p>
        </div>

        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 text-red-600 p-4 rounded-2xl text-[10px] font-black mb-6 text-center uppercase tracking-widest leading-tight flex items-center justify-center gap-2">
            <ExclamationTriangleIcon className="h-5 w-5 shrink-0" />
            <span>{error}</span>
          </div>
        )}

        {isRegister && (
          <div className="flex bg-gray-50 dark:bg-white/5 p-1 rounded-2xl mb-6">
            <button type="button" onClick={() => setUserType(UserType.STANDARD)} className={`flex-1 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${userType === UserType.STANDARD ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400'}`}>Normal</button>
            <button type="button" onClick={() => setUserType(UserType.CREATOR)} className={`flex-1 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${userType === UserType.CREATOR ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400'}`}>Profissional</button>
          </div>
        )}

        <form onSubmit={isRegister ? handleRegister : handleLogin} className="space-y-4">
          {isRegister && (
            <div className="flex flex-col items-center mb-4">
              <div onClick={() => profilePicInputRef.current?.click()} className="relative group cursor-pointer">
                <div className="w-20 h-20 rounded-[1.8rem] overflow-hidden border-4 border-gray-50 dark:border-white/10 shadow-xl transition-all group-hover:scale-105 group-hover:border-blue-500">
                  <img src={profilePicBase64} className="w-full h-full object-cover" alt="Preview" />
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <CameraIcon className="h-6 w-6 text-white" />
                  </div>
                </div>
                <div className="absolute -bottom-1 -right-1 bg-blue-600 text-white p-1.5 rounded-lg shadow-lg border-2 border-white dark:border-darkcard">
                  <PlusIcon className="h-2.5 w-2.5 stroke-[4]" />
                </div>
                <input type="file" ref={profilePicInputRef} onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => setProfilePicBase64(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }} accept="image/*" className="hidden" />
              </div>
              <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mt-2">Identidade Visual</p>
            </div>
          )}

          {isRegister && (
            <>
              <div className="grid grid-cols-2 gap-2.5">
                <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClasses} />
                <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClasses} />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Data de Nascimento</label>
                <div className="relative">
                  <CalendarDaysIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className={inputClasses + " pl-10"} />
                </div>
              </div>
            </>
          )}

          <input type="email" placeholder="E-mail de acesso" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="space-y-4">
               <div className="relative">
                  <div className="flex bg-gray-50 dark:bg-white/5 rounded-2xl border-2 border-transparent focus-within:border-blue-500 transition-all shadow-inner overflow-visible">
                     <button 
                       type="button" 
                       onClick={() => setShowCountryPicker(!showCountryPicker)}
                       className="flex items-center gap-2 px-4 border-r border-gray-200 dark:border-white/10 hover:bg-gray-100 dark:hover:bg-white/5 transition-colors shrink-0"
                     >
                        <span className="text-xl">{selectedCountry.flag}</span>
                        <span className="text-xs font-black dark:text-white">{selectedCountry.ddi}</span>
                        <ChevronDownIcon className={`h-3 w-3 text-gray-400 transition-transform ${showCountryPicker ? 'rotate-180' : ''}`} />
                     </button>
                     <input type="tel" placeholder="Telefone" value={phone} onChange={handlePhoneChange} className="w-full p-3.5 bg-transparent dark:text-white outline-none font-bold text-sm" />
                  </div>
                  {showCountryPicker && (
                    <div className="absolute top-full left-0 mt-2 w-72 bg-white dark:bg-[#1a1e26] rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.3)] border border-gray-100 dark:border-white/10 z-[100] flex flex-col overflow-hidden animate-fade-in">
                       <div className="p-3 border-b dark:border-white/10 bg-gray-50 dark:bg-white/5">
                          <div className="relative">
                             <MagnifyingGlassIcon className="h-4 w-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
