export const createNotification = (notificationData: Omit<Notification, 'id' | 'isRead'>) => {
  if (notificationData.recipientId === notificationData.actorId) return;
  const notifications = getNotifications();
  const newNotification: Notification = {
    ...notificationData,
    id: generateUUID(),
    isRead: false,
  };
  saveNotifications([newNotification, ...notifications]);
};

export const getNotificationsForUser = (userId: string): Notification[] => {
  return getNotifications().filter(n => n.recipientId === userId);
};

export const markNotificationsAsRead = (userId: string) => {
  let notifications = getNotifications();
  notifications.forEach(n => {
    if (n.recipientId === userId && !n.isRead) n.isRead = true;
  });
  saveNotifications(notifications);
};

// --- Ads ---

export const getAds = (): AdCampaign[] => {
  const adsJson = localStorage.getItem(ADS_KEY);
  return adsJson ? JSON.parse(adsJson) : [];
};

export const saveAds = (ads: AdCampaign[]) => {
  localStorage.setItem(ADS_KEY, JSON.stringify(ads));
};

// --- Stories ---

export const getStories = (): Story[] => {
  const storiesJson = localStorage.getItem(STORIES_KEY);
  return storiesJson ? JSON.parse(storiesJson) : [];
};

export const addStory = (uId: string, item: any) => {
  const stories = getStories();
  const user = findUserById(uId);
  if (!user) return;
  let userStory = stories.find(s => s.userId === uId);
  if (!userStory) {
    userStory = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
    stories.push(userStory);
  }
  userStory.items.push({ ...item, id: generateUUID(), timestamp: Date.now() });
  localStorage.setItem(STORIES_KEY, JSON.stringify(stories));
};

// --- Events ---

export const getEvents = (): CyberEvent[] => {
  const eventsJson = localStorage.getItem(EVENTS_KEY);
  return eventsJson ? JSON.parse(eventsJson) : [];
};

export const createEvent = (evt: CyberEvent) => {
  const evts = getEvents();
  localStorage.setItem(EVENTS_KEY, JSON.stringify([evt, ...evts]));
};

export const toggleJoinEvent = (eId: string, uId: string) => {
  const evts = getEvents();
  const evt = evts.find(e => e.id === eId);
  if (evt) {
    if (evt.attendees.includes(uId)) evt.attendees = evt.attendees.filter(id => id !== uId);
    else evt.attendees.push(uId);
    localStorage.setItem(EVENTS_KEY, JSON.stringify(evts));
  }
};

// --- Audio ---

export const getAudioTracks = (): AudioTrack[] => {
  const tracksJson = localStorage.getItem(AUDIO_TRACKS_KEY);
  return tracksJson ? JSON.parse(tracksJson) : [];
};

export const findAudioTrackById = (id: string): AudioTrack | undefined => {
  return getAudioTracks().find(t => t.id === id);
};

// --- Reports & Admin ---

export const createReport = (reportData: Omit<ContentReport, 'id' | 'status' | 'timestamp'>) => {
    const reports = getReports();
    reports.push({
        ...reportData,
        id: generateUUID(),
        status: 'OPEN',
        timestamp: Date.now()
    });
    localStorage.setItem(REPORTS_KEY, JSON.stringify(reports));
};

export const getReports = (): ContentReport[] => {
    const json = localStorage.getItem(REPORTS_KEY);
    return json ? JSON.parse(json) : [];
};

export const adminProcessReport = (reportId: string, status: 'RESOLVED' | 'DISMISSED', adminId: string) => {
    let reports = getReports();
    reports = reports.map(r => r.id === reportId ? { ...r, status } : r);
    localStorage.setItem(REPORTS_KEY, JSON.stringify(reports));

    // Log action
    const logs = getSystemLogs();
    logs.push({
        id: generateUUID(),
        adminId,
        action: `REPORT_${status}`,
        targetId: reportId,
        details: `Report ${reportId} processed as ${status}`,
        timestamp: Date.now()
    });
    localStorage.setItem(LOGS_KEY, JSON.stringify(logs));
};

export const getSystemLogs = (): SystemLog[] => {
    const json = localStorage.getItem(LOGS_KEY);
    return json ? JSON.parse(json) : [];
};

export const getTransactions = (): Transaction[] => {
    const json = localStorage.getItem(TRANSACTIONS_KEY);
    return json ? JSON.parse(json) : [];
};

export const getPlatformRevenue = async (): Promise<number> => {
    const transactions = getTransactions();
    // Simplified logic: revenue could be withdrawals tax
    return transactions.reduce((sum, t) => t.type === TransactionType.WITHDRAWAL ? sum + (t.amount * 0.1) : sum, 0);
};

export const getGlobalSettings = (): GlobalSettings => {
    const json = localStorage.getItem(SETTINGS_KEY);
    return json ? JSON.parse(json) : { platformTax: 0.1, upgradeCost: 29.9, minWithdrawal: 50, maintenanceMode: false };
};

export const updateGlobalSettings = (settings: GlobalSettings) => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
};

// --- Files ---

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.readAsDataURL(file);
  });
};

