              </div>
              <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mt-2">Identidade Visual</p>
            </div>
          )}

          {isRegister && (
            <>
              <div className="grid grid-cols-2 gap-2.5">
                <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClasses} />
                <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClasses} />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Data de Nascimento</label>
                <div className="relative">
                  <CalendarDaysIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className={inputClasses + " pl-10"} />
                </div>
              </div>
            </>
          )}

          <input type="email" placeholder="E-mail de acesso" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="space-y-4">
               <div className="relative">
                  <div className="flex bg-gray-50 dark:bg-white/5 rounded-2xl border-2 border-transparent focus-within:border-blue-500 transition-all shadow-inner overflow-visible">
                     <button 
                       type="button" 
                       onClick={() => setShowCountryPicker(!showCountryPicker)}
                       className="flex items-center gap-2 px-4 border-r border-gray-200 dark:border-white/10 hover:bg-gray-100 dark:hover:bg-white/5 transition-colors shrink-0"
                     >
                        <span className="text-xl">{selectedCountry.flag}</span>
                        <span className="text-xs font-black dark:text-white">{selectedCountry.ddi}</span>
                        <ChevronDownIcon className={`h-3 w-3 text-gray-400 transition-transform ${showCountryPicker ? 'rotate-180' : ''}`} />
                     </button>
                     <input type="tel" placeholder="Telefone" value={phone} onChange={handlePhoneChange} className="w-full p-3.5 bg-transparent dark:text-white outline-none font-bold text-sm" />
                  </div>
                  {showCountryPicker && (
                    <div className="absolute top-full left-0 mt-2 w-72 bg-white dark:bg-[#1a1e26] rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.3)] border border-gray-100 dark:border-white/10 z-[100] flex flex-col overflow-hidden animate-fade-in">
                       <div className="p-3 border-b dark:border-white/10 bg-gray-50 dark:bg-white/5">
                          <div className="relative">
                             <MagnifyingGlassIcon className="h-4 w-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                             <input 
                               type="text" 
                               autoFocus
                               placeholder="Buscar país ou DDI..." 
                               value={countrySearch}
                               onChange={e => setCountrySearch(e.target.value)}
                               className="w-full pl-9 pr-4 py-2 bg-white dark:bg-[#0d1117] rounded-xl outline-none font-bold text-[10px] dark:text-white"
                             />
                          </div>
                       </div>
                       <div className="max-h-64 overflow-y-auto custom-scrollbar">
                          {filteredCountries.map((c) => (
                            <button 
                              key={c.code} 
                              type="button" 
                              onClick={() => { setSelectedCountry(c); setShowCountryPicker(false); setPhone(''); setCountrySearch(''); }} 
                              className={`w-full flex items-center justify-between p-4 hover:bg-blue-50 dark:hover:bg-white/5 transition-colors text-left ${selectedCountry.code === c.code ? 'bg-blue-50/50 dark:bg-blue-600/10' : ''}`}
                            >
                               <div className="flex items-center gap-3">
                                  <span className="text-xl">{c.flag}</span>
                                  <span className="text-[10px] font-black uppercase dark:text-white truncate max-w-[120px]">{c.name}</span>
                               </div>
                               <span className="text-[10px] font-bold text-blue-600">{c.ddi}</span>
                            </button>
                          ))}
                          {filteredCountries.length === 0 && (
                            <div className="p-8 text-center text-[10px] font-black text-gray-400 uppercase">Nenhum país encontrado</div>
                          )}
                       </div>
                    </div>
                  )}
               </div>
               <input type="text" placeholder="Documento ID (CPF/BI)" value={documentId} onChange={e => setDocumentId(e.target.value)} className={inputClasses} />
            </div>
          )}

          <input type="password" placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="space-y-4 animate-fade-in pt-1">
              {userType === UserType.CREATOR && (
                <>
                  <input type="text" placeholder="Área de Atuação / Cargo" value={credentials} onChange={e => setCredentials(e.target.value)} className={inputClasses} />

                  <div className="space-y-2">
                    <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3 flex items-center gap-1">
                       Comprovação de Habilitação <ShieldCheckIcon className="h-3 w-3 text-blue-500" />
                    </label>
                    <div 
                      onClick={() => docInputRef.current?.click()}
                      className={`w-full p-4 bg-gray-50 dark:bg-white/5 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center gap-2 cursor-pointer transition-all ${verificationFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10' : 'border-gray-200 dark:border-white/10 hover:border-blue-500'}`}
                    >
                      {verificationFile ? (
                        <div className="flex items-center gap-3 w-full">
                           <DocumentCheckIcon className="h-6 w-6 text-green-600" />
                           <div className="flex-1 min-w-0">
                              <p className="text-[10px] font-black text-green-700 truncate">{verificationFileName}</p>
                              <p className="text-[8px] font-bold text-green-600/60 uppercase">Arquivo pronto para Auditoria IA</p>
                           </div>
                           <button 
                             type="button" 
                             onClick={(e) => { e.stopPropagation(); setVerificationFile(null); setVerificationFileName(null); }}
                             className="p-1.5 bg-white dark:bg-darkcard rounded-lg shadow-sm text-red-500 hover:bg-red-50"
                           >
                             <XMarkIcon className="h-4 w-4" />
                           </button>
                        </div>
                      ) : (
                        <>
                          <DocumentArrowUpIcon className="h-6 w-6 text-gray-400" />
                          <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest text-center">
                             Upload PDF ou Imagem<br/>do Documento Oficial
                          </span>
                        </>
                      )}
                      <input 
                        type="file" 
                        ref={docInputRef} 
                        onChange={handleFileChange} 
                        accept=".pdf,image/*" 
                        className="hidden" 
                      />
                    </div>
                  </div>
                </>
              )}
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Sobre você</label>
                <textarea placeholder="Resumo do perfil..." value={bio} onChange={e => setBio(e.target.value)} className={inputClasses + " h-20 resize-none font-medium text-xs"} />
              </div>
            </div>
          )}

          <button 
            type="submit" 
            disabled={loading} 
            className="w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 bg-blue-600 text-white mt-4 disabled:opacity-50 disabled:bg-gray-400"
          >
            {loading ? (
              <>
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                <span>{loadingMessage || 'Processando...'}</span>
              </>
            ) : isRegister ? 'Confirmar Registro' : 'Acessar Rede'}
          </button>
        </form>

        {!isRegister && (
          <div className="mt-4 text-center">
             <button onClick={openRecovery} className="text-[9px] font-black text-gray-400 hover:text-blue-600 uppercase tracking-widest transition-colors">
               Esqueceu a senha?
             </button>
          </div>
        )}

        <button onClick={() => { setIsRegister(!isRegister); setError(''); }} className="w-full mt-6 text-[8px] font-black uppercase tracking-[0.3em] text-gray-400 hover:text-blue-600 transition-colors">
          {isRegister ? 'Já possui acesso? Entrar' : 'Novo integrante? Obter acesso'}
        </button>
      </div>
    </div>
  );
};

export default AuthPage;

import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  updatePostSaves, 
  deletePost, 
  pinPost,
  unpinPost,
  updateUserBalance,
  createReport
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  TrashIcon, 
  CheckBadgeIcon,
  FlagIcon,
  MapPinIcon as PinIconOutline,
  VideoCameraIcon,
  SignalIcon,
  ShareIcon,
  RocketLaunchIcon,
  PencilSquareIcon,
  UserPlusIcon,
  LockClosedIcon,
  LockOpenIcon,
  CurrencyDollarIcon,
  FilmIcon,
  PlayIcon,
  SpeakerXMarkIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  BoltIcon,
  ShareIcon as ShareIconSolid,
  BanknotesIcon
} from '@heroicons/react/24/solid';
import IndicateModal from './IndicateModal';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  const [postAuthor, setPostAuthor] = useState<User | null>(null);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);

  // Refs para Auto-play de Reels no Feed
  const videoRef = useRef<HTMLVideoElement>(null);
  const observerRef = useRef<IntersectionObserver | null>(null);

  useEffect(() => {
    const fetchAuthor = async () => {
      const author = await findUserById(post.userId);
      setPostAuthor(author || null);
    };
    fetchAuthor();
  }, [post.userId]);

  // Lógica de Autoplay para Reels
  useEffect(() => {
    if (post.type === PostType.REEL && videoRef.current) {
      observerRef.current = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              videoRef.current?.play().catch(() => {}); // Ignora erro de autoplay se navegador bloquear
            } else {
              videoRef.current?.pause();
            }
          });
        },
        { threshold: 0.6 } // Toca quando 60% visível
      );
      observerRef.current.observe(videoRef.current);
    }
    return () => {
      if (observerRef.current) observerRef.current.disconnect();
    };
  }, [post.type]);

  if (!post || !currentUser || !post.id) return null;
  if (!postAuthor) return null;

  const hasLiked = post.likes?.includes(currentUser.id) || false;
  const hasSaved = post.saves?.includes(currentUser.id) || false;
  const isAuthor = currentUser.id === post.userId;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const handleEnterLive = () => {
    if (!post.liveStream) return;
    if (isAuthor || !post.liveStream.isPaid) {
      onNavigate('live', { postId: post.id });
      return;
    }
    const price = post.liveStream.price || 0;
    if ((currentUser.balance || 0) < price) {
       alert(`Saldo insuficiente. Preço: $${price.toFixed(2)}.`);
       return;
    }
    if (window.confirm(`Deseja pagar $${price.toFixed(2)} para entrar?`)) {
       updateUserBalance(currentUser.id, -price);
       updateUserBalance(post.userId, price);
       refreshUser();
       onNavigate('live', { postId: post.id });
    }
  };

  const handleGoToReel = () => {
    onNavigate('reels-page', { startPostId: post.id });
  };

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={() => {
          if (post.type === PostType.LIVE) handleEnterLive();
          else if (post.type === PostType.REEL) handleGoToReel();
          else setShowDetailModal(true);
        }}
        className="bg-white dark:bg-darkcard rounded-[2rem] md:rounded-[3rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-6 transition-all hover:shadow-2xl hover:-translate-y-1 animate-fade-in cursor-pointer group"
      >
        <div className="p-5 md:p-8 flex items-center justify-between">
          <div className="flex items-center gap-4 md:gap-5">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 md:w-16 md:h-16 rounded-[1.2rem] md:rounded-[1.8rem] object-cover shadow-lg border-2 border-white dark:border-white/10" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1.5 -right-1.5 bg-blue-600 rounded-xl p-1 border-2 border-white dark:border-darkcard shadow-md">
                  <CheckBadgeIcon className="h-4 w-4 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-2">
                <h4 className="font-black text-gray-900 dark:text-white text-base md:text-xl truncate tracking-tighter hover:text-blue-600 transition-colors">
                    {postAuthor.firstName}
                </h4>
                {post.isPinned && <PinIconSolid className="h-4 w-4 text-blue-500 shrink-0" />}
                {isPostBoosted && <BoltIcon className="h-4 w-4 text-orange-500 animate-pulse shrink-0" />}
              </div>
              <p className="text-[9px] md:text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mt-0.5">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-3 text-blue-600">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <button 
            onClick={(e) => { e.stopPropagation(); setShowActionsModal(true); }} 
            className="p-3 rounded-2xl bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-blue-600 transition-all"
          >
            <EllipsisHorizontalIcon className="h-7 w-7" />
          </button>
        </div>

        <div className="px-5 md:px-8 pb-5 md:pb-8">
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[2.5rem] md:rounded-[3.5rem] overflow-hidden bg-gray-900 text-white p-8 md:p-16 relative shadow-2xl border-4 border-white/5">
                <div className="absolute top-6 left-6 z-10 flex gap-3">
                   <div className="bg-red-600 px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-1.5 shadow-2xl animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3.5 w-3.5" /> Ao Vivo
                   </div>
                   {post.liveStream.isPaid ? (
                      <div className="bg-blue-600/90 backdrop-blur-md px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-2 shadow-2xl uppercase tracking-widest">
                         <LockClosedIcon className="h-3.5 w-3.5" /> Pro: ${post.liveStream.price?.toFixed(2)}
                      </div>
                   ) : (
                      <div className="bg-green-600/90 backdrop-blur-md px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-2 shadow-2xl uppercase tracking-widest">
                         <LockOpenIcon className="h-3.5 w-3.5" /> Livre
                      </div>
                   )}
                </div>

                <div className="relative z-10 py-8 flex flex-col items-center text-center">
                   <div className="w-20 h-20 md:w-28 md:h-28 bg-white/5 backdrop-blur-xl rounded-[2.5rem] md:rounded-[3rem] flex items-center justify-center mb-8 border border-white/10 shadow-inner group-hover:scale-110 transition-transform duration-500">
                      <VideoCameraIcon className="h-10 w-10 md:h-14 md:w-14 text-blue-400" />
                   </div>
                   <h3 className="text-2xl md:text-4xl font-black mb-8 tracking-tighter leading-tight uppercase line-clamp-2 max-w-2xl">{post.liveStream.title}</h3>
                   <button className={`relative overflow-hidden group/btn px-10 py-5 md:px-16 md:py-6 rounded-[2.2rem] font-black text-[11px] md:text-sm uppercase tracking-[0.2em] shadow-xl transition-all active:scale-90 flex items-center justify-center gap-4 ${post.liveStream.isPaid && !isAuthor ? 'bg-gradient-to-r from-yellow-400 to-yellow-600 text-black' : 'bg-blue-600 text-white'}`}>
                      {post.liveStream.isPaid && !isAuthor ? <><BanknotesIcon className="h-6 w-6" /> Contratar Acesso</> : <><PlayIcon className="h-6 w-6" /> Entrar Agora</>}
                   </button>
                </div>
             </div>
          ) : post.type === PostType.REEL && post.reel ? (
            /* REEL REPRESENTATION IN FEED */
            <div className="flex justify-center bg-black rounded-[2.5rem] overflow-hidden relative group/reel border-4 border-gray-900 shadow-2xl">
               <div className="relative w-full max-w-sm aspect-[9/16]">
                  <video 
                    ref={videoRef}
                    src={post.reel.videoUrl} 
                    muted 
                    loop 
                    playsInline 
                    className="w-full h-full object-cover opacity-90 group-hover/reel:opacity-100 transition-opacity"
                  />
                  <div className="absolute inset-0 bg-gradient-to-b from-black/30 via-transparent to-black/60 pointer-events-none"></div>

                  <div className="absolute top-4 right-4 bg-purple-600 text-white px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5 shadow-lg backdrop-blur-md z-10">
                     <FilmIcon className="h-3 w-3" /> Reel
                  </div>

                  <div className="absolute bottom-6 left-6 right-6 text-white z-10 pointer-events-none">
                     <p className="line-clamp-2 text-sm font-bold leading-snug drop-shadow-md">{post.reel.description}</p>
                  </div>

                  <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover/reel:opacity-100 transition-opacity z-20">
                     <div className="bg-white/20 backdrop-blur-md p-4 rounded-full border border-white/30 shadow-2xl transform scale-90 group-hover/reel:scale-100 transition-transform">
                        <PlayIcon className="h-8 w-8 text-white" />
                     </div>
                  </div>

                  <div className="absolute bottom-6 right-6 z-10">
                     <SpeakerXMarkIcon className="h-5 w-5 text-white/50" />
                  </div>
               </div>
            </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`p-10 md:p-20 rounded-[2.5rem] md:rounded-[4rem] mb-6 transition-all duration-700 group-hover:scale-[1.01] flex items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
                  style={{ backgroundColor: hasBg ? post.backgroundColor : 'transparent', color: post.textColor || 'inherit', fontSize: post.fontSize ? `calc(${post.fontSize} * 1.1)` : '1.2rem', minHeight: hasBg ? '320px' : 'auto', border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)', fontFamily: post.fontFamily?.replace('font-', '') }}
                >
                  <p className={`font-black leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-xl' : 'text-left w-full'}`}>{post.content}</p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-xl">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[700px] transition-transform duration-1000 group-hover:scale-105" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        <div className="px-6 md:px-12 py-5 md:py-8 flex items-center justify-between border-t border-gray-50 dark:border-white/5">
          <div className="flex items-center gap-2 md:gap-5">
            <button onClick={handleLike} className={`flex items-center gap-3 px-5 md:px-7 py-3 md:py-4 rounded-[1.5rem] transition-all active:scale-75 ${hasLiked ? 'text-blue-600 bg-blue-50 dark:bg-blue-600/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {hasLiked ? <HeartIconSolid className="h-6 w-6 md:h-8 md:w-8" /> : <HeartIconOutline className="h-6 w-6 md:h-8 md:w-8" />}
              <span className="text-xs md:text-base font-black">{post.likes?.length || 0}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-3 px-5 md:px-7 py-3 md:py-4 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ChatIconOutline className="h-6 w-6 md:h-8 md:w-8" />
              <span className="font-black text-xs md:text-base">{post.comments?.length || 0}</span>
            </button>
            <button className="p-4 md:p-5 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ShareIcon className="h-6 w-6 md:h-8 md:w-8" />
            </button>
          </div>
          <button onClick={(e) => { e.stopPropagation(); updatePostSaves(post.id, currentUser.id); onPostUpdatedOrDeleted(); }} className={`p-4 md:p-5 rounded-[1.5rem] transition-all active:scale-90 ${hasSaved ? 'text-blue-600 bg-blue-50 dark:bg-blue-600/10' : 'text-gray-300 hover:bg-gray-50'}`}>
            {hasSaved ? <BookmarkIconSolid className="h-6 w-6 md:h-8 md:w-8" /> : <BookmarkIconOutline className="h-6 w-6 md:h-8 md:w-8" />}
          </button>
        </div>
      </div>

      {showActionsModal && (
        <PostActionsModal isAuthor={isAuthor} isPinned={!!post.isPinned} onClose={() => setShowActionsModal(false)} onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }} onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }} onPin={() => { if(post.isPinned) unpinPost(post.id, currentUser.id); else pinPost(post.id, currentUser.id); onPostUpdatedOrDeleted(); setShowActionsModal(false); }} onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }} onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }} onIndicate={() => { setShowActionsModal(false); setShowIndicateModal(true); }} onReport={() => { if(confirm("Denunciar?")) createReport({ reporterId: currentUser.id, targetId: post.id, targetType: 'POST', reason: 'DENÚNCIA', details: 'Via PostCard' }); setShowActionsModal(false); }} />
      )}

      {showDetailModal && <PostDetailModal post={post} currentUser={currentUser} onClose={() => setShowDetailModal(false)} onUpdate={onPostUpdatedOrDeleted} onNavigate={onNavigate} refreshUser={refreshUser} />}
      {showBoostModal && <BoostPostModal post={post} currentUser={currentUser} onClose={() => setShowBoostModal(false)} onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }} />}
      {showDeleteModal && <DeleteConfirmModal onClose={() => setShowDeleteModal(false)} onConfirm={() => { deletePost(post.id); setShowDeleteModal(false); onPostUpdatedOrDeleted(); }} />}
      {showEditModal && <EditPostModal postId={post.id} currentUser={currentUser} onClose={() => setShowEditModal(false)} onSuccess={onPostUpdatedOrDeleted} />}
      {showIndicateModal && <IndicateModal post={post} currentUser={currentUser} onClose={() => setShowIndicateModal(false)} onPostUpdated={onPostUpdatedOrDeleted} />}
    </>
  );
};

export default PostCard;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, PostType, AudioTrack } from '../types';
import { 
  getPosts, 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  toggleFollowUser, 
  findAudioTrackById, 
  updatePostSaves 
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../constants';
import {
  ChatBubbleOvalLeftIcon as ChatIconOutline,
  ShareIcon as ShareIconOutline,
  SpeakerWaveIcon,
  SpeakerXMarkIcon,
  PlayIcon,
  BookmarkIcon as BookmarkIconOutline,
  MusicalNoteIcon,
  UserPlusIcon
} from '@heroicons/react/24/outline';
import {
  HeartIcon as HeartIconSolid,
  BookmarkIcon as BookmarkIconSolid
} from '@heroicons/react/24/solid';
import CommentsModal from './CommentsModal';
import IndicateModal from './IndicateModal';

interface ReelsPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
  startPostId?: string;
}

interface ReelVideoProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  isIntersecting: boolean;
  onPostUpdate: () => void;
}

const ReelVideo: React.FC<ReelVideoProps> = ({ post, currentUser, onNavigate, onFollowToggle, refreshUser, isIntersecting, onPostUpdate }) => {
  if (!post || !currentUser) return null;

  const videoRef = useRef<HTMLVideoElement>(null);
  const [isMuted, setIsMuted] = useState(true);
  const [showPlayIcon, setShowPlayIcon] = useState(false);
  const [isCommentsModalOpen, setIsCommentsModalOpen] = useState(false);
  const [isIndicateModalOpen, setIsIndicateModalOpen] = useState(false);
  const [likeHearts, setLikeHearts] = useState<{ id: number; x: number; y: number }[]>([]);
  const [videoProgress, setVideoProgress] = useState(0);
  const [postAuthor, setPostAuthor] = useState<User | null>(null);

  const clickTimeout = useRef<number | null>(null);

  useEffect(() => {
    const u = findUserById(post.userId);
    setPostAuthor(u || null);
  }, [post.userId]);

  const isFollowing = currentUser.followedUsers?.includes(post.userId);
  const hasLiked = post.likes?.includes(currentUser.id);
  const hasSaved = post.saves?.includes(currentUser.id);
  const [audioTrack, setAudioTrack] = useState<AudioTrack | null>(null);

  useEffect(() => {
    if (post.reel?.audioTrackId) {
      setAudioTrack(findAudioTrackById(post.reel.audioTrackId) || null);
    }
  }, [post.reel?.audioTrackId]);

  const syncPlay = useCallback(async () => {
    const video = videoRef.current;
    if (!video) return;
    try {
      video.muted = isMuted;
      if (video.paused) await video.play();
    } catch (e) {}
  }, [isMuted]);

  const syncPause = useCallback(() => {
    const video = videoRef.current;
    if (video && !video.paused) video.pause();
  }, []);

  useEffect(() => {
    if (isIntersecting) syncPlay();
    else syncPause();
  }, [isIntersecting, syncPlay, syncPause]);

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      const progress = (videoRef.current.currentTime / videoRef.current.duration) * 100;
      setVideoProgress(progress);
    }
  };

  const togglePlayPause = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) {
      syncPlay();
      setShowPlayIcon(false);
    } else {
      syncPause();
      setShowPlayIcon(true);
    }
  };

  const handleLike = (e?: any) => {
    if (e) e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onPostUpdate();
    refreshUser();
  };

  const handleDoubleClick = (e: any) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = (e.clientX || (e.touches && e.touches[0].clientX)) - rect.left;
    const y = (e.clientY || (e.touches && e.touches[0].clientY)) - rect.top;

    const newHeart = { id: Date.now(), x, y };
    setLikeHearts(prev => [...prev, newHeart]);
    if (!hasLiked) handleLike();
    setTimeout(() => setLikeHearts(prev => prev.filter(h => h.id !== newHeart.id)), 800);
  };

  const handleMainContainerClick = (e: React.MouseEvent) => {
    if (clickTimeout.current) {
      window.clearTimeout(clickTimeout.current);
      clickTimeout.current = null;
      handleDoubleClick(e);
    } else {
      clickTimeout.current = window.setTimeout(() => {
        togglePlayPause();
        clickTimeout.current = null;
      }, 250);
    }
  };

  if (!postAuthor || !post.reel) return null;

  return (
    <div 
      className="relative w-full h-full snap-start snap-always overflow-hidden bg-black flex items-center justify-center"
      onClick={handleMainContainerClick}
    >
      {/* 1. LAYER: VIDEO */}
      <video
        ref={videoRef}
        src={post.reel.videoUrl}
        loop
        playsInline
        webkit-playsinline="true"
        onTimeUpdate={handleTimeUpdate}
        className="w-full h-full object-cover md:max-w-lg md:mx-auto"
        style={{ filter: post.reel.filter || 'none' }}
      />

      {/* 2. LAYER: OVERLAYS */}
      <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-transparent to-black/80 pointer-events-none z-10"></div>

      {/* 3. LAYER: INTERACTIVE ELEMENTS */}

      {/* Play Icon Feedback */}
      {showPlayIcon && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-30">
          <div className="bg-black/20 p-8 rounded-full backdrop-blur-md animate-scale-in">
            <PlayIcon className="h-16 w-16 text-white/80" />
          </div>
        </div>
      )}

      {/* Double Tap Hearts */}
      {likeHearts.map(heart => (
        <div key={heart.id} className="absolute z-50 pointer-events-none animate-like-heart" style={{ left: heart.x - 40, top: heart.y - 40 }}>
          <HeartIconSolid className="w-24 h-24 text-red-500 drop-shadow-[0_0_20px_rgba(239,68,68,0.8)]" />
        </div>
      ))}

      {/* ACTIONS SIDEBAR (Right) - Otimizado para caber em telas menores */}
      <div 
        className="absolute bottom-20 right-1 flex flex-col items-center gap-1.5 z-40 px-2"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Seguir */}
        {!isFollowing && currentUser.id !== post.userId && (
          <button 
            onClick={(e) => { e.stopPropagation(); onFollowToggle(post.userId); }} 
            className="flex flex-col items-center group p-1"
          >
            <div className="bg-blue-600 p-2 rounded-full shadow-2xl border border-white/20 group-active:scale-125 transition-transform">
              <UserPlusIcon className="h-6 w-6 text-white" />
            </div>
            <span className="text-[8px] font-black text-white uppercase mt-0.5 drop-shadow-md">Seguir</span>
          </button>
        )}

        {/* Volume */}
        <button 
          onClick={(e) => { e.stopPropagation(); setIsMuted(!isMuted); }} 
          className="flex flex-col items-center group p-1"
        >
          <div className="bg-black/40 backdrop-blur-md p-2 rounded-full shadow-2xl border border-white/10 group-active:scale-125 transition-transform">
            {isMuted ? (
              <SpeakerXMarkIcon className="h-6 w-6 text-white" />
            ) : (
              <SpeakerWaveIcon className="h-6 w-6 text-white" />
            )}
          </div>
          <span className="text-[8px] font-black text-white uppercase mt-0.5 drop-shadow-md">Som</span>
        </button>

        {/* Like */}
        <button onClick={handleLike} className="flex flex-col items-center group p-1">
          <div className="transition-transform duration-200 group-active:scale-150">
            <HeartIconSolid className={`h-8 w-8 drop-shadow-xl ${hasLiked ? 'text-red-500' : 'text-white'}`} />
          </div>
          <span className="text-[10px] font-black text-white mt-0.5 drop-shadow-md">{post.likes?.length || 0}</span>
        </button>

        {/* Comments */}
        <button onClick={(e) => { e.stopPropagation(); setIsCommentsModalOpen(true); }} className="flex flex-col items-center group p-1">
          <ChatIconOutline className="h-8 w-8 text-white drop-shadow-xl group-active:scale-125 transition-transform" />
          <span className="text-[10px] font-black text-white mt-0.5 drop-shadow-md">{post.comments?.length || 0}</span>
        </button>

        {/* Save */}
        <button onClick={(e) => { e.stopPropagation(); updatePostSaves(post.id, currentUser.id); onPostUpdate(); }} className="flex flex-col items-center group p-1">
          <BookmarkIconSolid className={`h-8 w-8 drop-shadow-xl transition-all duration-300 group-active:scale-125 ${hasSaved ? 'text-yellow-400' : 'text-white'}`} />
          <span className="text-[10px] font-black text-white mt-0.5 drop-shadow-md">{post.saves?.length || 0}</span>
        </button>

        {/* Indicate */}
        <button onClick={(e) => { e.stopPropagation(); setIsIndicateModalOpen(true); }} className="flex flex-col items-center group p-1">
          <ShareIconOutline className="h-8 w-8 text-white drop-shadow-xl group-active:scale-125 transition-transform" />
          <span className="text-[8px] font-black text-white uppercase mt-0.5 drop-shadow-md">Indicar</span>
        </button>

        {/* Spinning Audio Icon */}
        <div className="mt-1">
          <div className="w-9 h-9 rounded-full bg-gradient-to-r from-gray-800 to-black border border-white/20 flex items-center justify-center overflow-hidden shadow-2xl animate-spin-slow">
            <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-full h-full object-cover opacity-60" />
          </div>
        </div>
      </div>

      {/* INFO AREA (Bottom Left) */}
      <div 
        className="absolute bottom-4 left-0 right-20 z-30 px-5 pb-4 pointer-events-none flex flex-col gap-1.5"
      >
        <div 
          className="flex items-center gap-2 pointer-events-auto cursor-pointer w-fit"
          onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}
        >
          <span className="font-black text-base text-white hover:underline drop-shadow-lg">@{post.authorName}</span>
          <span className="bg-blue-600/90 backdrop-blur-md px-2 py-0.5 rounded-lg text-[8px] font-black text-white uppercase border border-white/10">Mestre</span>
        </div>

        <div className="pointer-events-auto max-w-full">
           <p className="text-xs text-white/95 font-medium leading-snug drop-shadow-md line-clamp-2">
            {post.reel.description}
           </p>
        </div>

        <div className="flex items-center gap-2 mt-1 pointer-events-auto w-fit bg-black/30 backdrop-blur-md px-3 py-1 rounded-full border border-white/5">
          <MusicalNoteIcon className="h-3 w-3 text-white animate-pulse" />
          <div className="overflow-hidden max-w-[120px]">
            <div className="whitespace-nowrap text-[9px] font-black text-white uppercase tracking-wider animate-marquee">
              {audioTrack ? `${audioTrack.title} - ${audioTrack.artist}` : `Áudio Original • ${post.authorName}`}
            </div>
          </div>
        </div>
      </div>

      {/* Progress Bar (Bottom) */}
      <div className="absolute bottom-0 left-0 w-full h-1 bg-white/10 z-50 pointer-events-none">
        <div 
          className="h-full bg-blue-600 transition-all duration-100 ease-linear shadow-[0_0_10px_#2563eb]" 
          style={{ width: `${videoProgress}%` }}
        />
      </div>

      {/* MODALS */}
      {isCommentsModalOpen && (
        <CommentsModal postId={post.id} currentUser={currentUser} onClose={() => setIsCommentsModalOpen(false)} onCommentsUpdated={onPostUpdate} />
      )}

      {isIndicateModalOpen && (
        <IndicateModal post={post} currentUser={currentUser} onClose={() => setIsIndicateModalOpen(false)} onPostUpdated={onPostUpdate} />
      )}

      <style>{`
        .animate-spin-slow { animation: spin 5s linear infinite; }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

        @keyframes marquee {
          0% { transform: translateX(100%); }
          100% { transform: translateX(-100%); }
        }
        .animate-marquee {
          display: inline-block;
          animation: marquee 8s linear infinite;
        }

        @keyframes like-heart {
          0% { transform: scale(0); opacity: 0; }
          20% { transform: scale(1.2) rotate(15deg); opacity: 1; }
          80% { transform: scale(1) rotate(-10deg); opacity: 1; }
          100% { transform: scale(2.5); opacity: 0; }
        }
        .animate-like-heart { animation: like-heart 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </div>
  );
};

const ReelsPage: React.FC<ReelsPageProps> = ({ currentUser, onNavigate, refreshUser, startPostId }) => {
  const [reels, setReels] = useState<Post[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);
  const [visibleIdx, setVisibleIdx] = useState(0);
  const [loading, setLoading] = useState(true);

  const fetchReels = useCallback(async () => {
    const allPosts = await getPosts();
    const posts = allPosts.filter(p => p.type === PostType.REEL).sort((a, b) => b.timestamp - a.timestamp);
    setReels(posts);

    // Se houver um post inicial, encontrar o índice
    if (startPostId) {
      const idx = posts.findIndex(p => p.id === startPostId);
      if (idx !== -1) {
        setVisibleIdx(idx);
        // Pequeno delay para garantir que o DOM renderizou
        setTimeout(() => {
          if (containerRef.current?.children[idx]) {
            containerRef.current.children[idx].scrollIntoView();
          }
        }, 100);
      }
    }
    setLoading(false);
  }, [startPostId]);

  useEffect(() => {
    fetchReels();
  }, [fetchReels]);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          const idx = Number((e.target as HTMLElement).dataset.idx);
          setVisibleIdx(idx);
        }
      });
    }, { threshold: 0.65 });

    const items = containerRef.current?.children;
    if (items) {
      Array.from(items).forEach(item => {
        if ((item as HTMLElement).dataset.idx !== undefined) {
          observer.observe(item as Element);
        }
      });
    }
    return () => observer.disconnect();
  }, [reels]);

  const handleFollowToggle = useCallback(
    (userIdToFollow: string) => {
      toggleFollowUser(currentUser.id, userIdToFollow);
      refreshUser();
      fetchReels();
    },
    [currentUser.id, refreshUser, fetchReels],
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center w-full h-screen bg-black text-white text-xl">
        <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mr-3"></div>
        Carregando...
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 md:top-[72px] md:ml-64 bottom-[64px] md:bottom-0 bg-black z-10"
    >
      <div 
        ref={containerRef} 
        className="w-full h-full overflow-y-scroll snap-y snap-mandatory no-scrollbar scroll-smooth"
        style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
      >
        {reels.length > 0 ? (
          reels.map((r, i) => (
            <div 
              key={r.id} 
              data-idx={i} 
              className="h-full w-full snap-start snap-always"
            >
              <ReelVideo 
                post={r} 
                currentUser={currentUser} 
                onNavigate={onNavigate} 
                onFollowToggle={handleFollowToggle} 
                refreshUser={refreshUser} 
                isIntersecting={i === visibleIdx}
                onPostUpdate={fetchReels}
              />
            </div>
          ))
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-white p-10 text-center">
            <MusicalNoteIcon className="h-20 w-20 text-gray-800 mb-6" />
            <h3 className="text-2xl font-black uppercase tracking-tighter">Nenhum Reel ainda</h3>
            <p className="text-gray-500 mt-2 font-medium">Seja o primeiro mestre a publicar conteúdo vertical!</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ReelsPage;

import React, { useState, useEffect, useCallback } from 'react';
import { User, CartItem } from '../types';
import {
    getCurrentUserId,
    findUserById,
    saveCurrentUser,
    getNotificationsForUser,
    markNotificationsAsRead,
    getCart,
    addToCart,
    removeFromCart,
    updateCartItemQuantity,
    clearCart
} from '../services/storageService';
import Header from './Header';
import Footer from './Footer';
import AuthPage from './AuthPage';
import FeedPage from './FeedPage';
import ProfilePage from './ProfilePage';
import ChatPage from './ChatPage';
import AdCampaignPage from './AdCampaignPage';
import LiveStreamViewer from './LiveStreamViewer';
import { StorePage } from './StorePage';
import CreatePost from './CreatePost';
import ReelsPage from './ReelsPage';
import SearchResultsPage from './SearchResultsPage';
import NotificationsPage from './NotificationsPage';
import AffiliatesPage from './AffiliatesPage';
import CartModal from './CartModal';
import { requestNotificationPermission } from '../services/notificationService';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'edit-post' | 'create-post' | 'reels-page' | 'search-results' | 'notifications' | 'affiliates';

const App: React.FC = () => {
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [isLoadingUser, setIsLoadingUser] = useState(true);
    const [currentPage, setCurrentPage] = useState<Page>('auth');
    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    const [cartItems, setCartItems] = useState<CartItem[]>(getCart());
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [isMenuOpen, setIsMenuOpen] = useState(false);

    // Carrega o usuário atual do banco de dados ao iniciar
    const refreshCurrentUser = useCallback(async () => {
        const userId = getCurrentUserId();
        if (userId) {
            try {
                const user = await findUserById(userId);
                if (user) {
                    setCurrentUser(user);
                    const notifications = await getNotificationsForUser(user.id);
                    setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
                    if (currentPage === 'auth') setCurrentPage('feed');
                } else {
                    setCurrentUser(null);
                    setCurrentPage('auth');
                }
            } catch (e) {
                console.error(e);
                setCurrentUser(null);
            }
        } else {
            setCurrentUser(null);
            setCurrentPage('auth');
        }
        setIsLoadingUser(false);
    }, [currentPage]);

    const refreshCart = useCallback(() => {
        setCartItems(getCart());
    }, []);

    useEffect(() => {
        refreshCurrentUser();
        refreshCart();
        if ('Notification' in window) {
            requestNotificationPermission();
        }
    }, []);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        refreshCurrentUser();
        refreshCart();
        setCurrentPage('feed');
    }, [refreshCurrentUser, refreshCart]);

    const handleLogout = useCallback(() => {
        setCurrentUser(null);
        saveCurrentUser(null);
        setCurrentPage('auth');
        setUnreadNotificationsCount(0);
        clearCart();
        refreshCart();
    }, [refreshCart]);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            setUnreadNotificationsCount(0);
        }
        setCurrentPage(page);
        setPageParams(params);
        setIsMenuOpen(false);
        window.scrollTo(0, 0);
    }, [currentUser]);

    const handleAddToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
        addToCart(productId, quantity, selectedColor);
        refreshCart();
        setIsCartModalOpen(true);
    };

    if (isLoadingUser) {
        return <div className="h-screen w-full flex items-center justify-center bg-gray-50 dark:bg-[#0a0c10]"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-600"></div></div>;
    }

    const renderPage = () => {
        if (!currentUser) {
            return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        }

        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} startPostId={pageParams.startPostId || pageParams.postId} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={() => {}} />;
            case 'chat': return <ChatPage currentUser={currentUser} />;
            case 'ads': return <AdCampaignPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={handleAddToCart} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'live': return <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'create-post': return <CreatePost currentUser={currentUser} onPostCreated={() => handleNavigate('feed')} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300 w-full overflow-x-hidden">
            <Header 
              currentUser={currentUser} 
              onNavigate={handleNavigate} 
              unreadNotificationsCount={unreadNotificationsCount} 
              cartItemCount={cartItems.reduce((sum, item) => sum + item.quantity, 0)} 
              onOpenCart={() => setIsCartModalOpen(true)} 
              onToggleMenu={() => setIsMenuOpen(!isMenuOpen)}
            />
            <div className="flex flex-1 w-full overflow-x-hidden">
                {currentUser && (
                  <Footer 
                    currentUser={currentUser} 
                    onNavigate={handleNavigate} 
                    activePage={currentPage} 
                    onLogout={handleLogout} 
                    isMenuOpen={isMenuOpen}
                    onCloseMenu={() => setIsMenuOpen(false)}
                  />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[72px] md:pb-8 transition-all duration-300 w-full ${currentUser ? 'md:ml-64 px-0 md:px-8' : 'px-0'}`}>
                    <div className="max-w-7xl mx-auto w-full">{renderPage()}</div>
                </main>
            </div>
            {currentUser && (
              <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={refreshCart} refreshUser={refreshCurrentUser} />
            )}
        </div>
    );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { addPost, updatePost, getPosts, uploadFile, generateUUID } from '../services/storageService';
import RecordReelModal from './RecordReelModal';
import { 
  VideoCameraIcon, 
  PhotoIcon, 
  XMarkIcon, 
  DocumentTextIcon, 
  LockClosedIcon, 
  FilmIcon, 
  ChevronRightIcon, 
  BriefcaseIcon, 
  BanknotesIcon, 
  ArrowUpTrayIcon, 
  TrashIcon,
  SwatchIcon,
  LanguageIcon
} from '@heroicons/react/24/solid';

interface CreatePostProps {
  currentUser: User;
  onPostCreated: () => void;
  refreshUser: () => void;
  postId?: string;
  onCancel?: () => void;
}

const BACKGROUND_OPTIONS = [
  { id: 'transparent', value: 'transparent', label: 'Padrão' },
  { id: 'gradient-1', value: 'linear-gradient(135deg, #FF9A9E 0%, #FECFEF 99%, #FECFEF 100%)', label: 'Suave' },
  { id: 'gradient-2', value: 'linear-gradient(120deg, #84fab0 0%, #8fd3f4 100%)', label: 'Menta' },
  { id: 'gradient-3', value: 'linear-gradient(120deg, #e0c3fc 0%, #8ec5fc 100%)', label: 'Sonho' },
  { id: 'gradient-4', value: 'linear-gradient(to right, #4facfe 0%, #00f2fe 100%)', label: 'Oceano' },
  { id: 'gradient-5', value: 'linear-gradient(to right, #43e97b 0%, #38f9d7 100%)', label: 'Natureza' },
  { id: 'gradient-6', value: 'linear-gradient(to right, #fa709a 0%, #fee140 100%)', label: 'Pôr do Sol' },
  { id: 'solid-dark', value: '#1a1a1a', label: 'Dark' },
  { id: 'solid-blue', value: '#2563eb', label: 'Blue' },
  { id: 'solid-red', value: '#dc2626', label: 'Red' },
];

const FONT_OPTIONS = [
  { id: 'font-sans', name: 'Moderna', class: 'font-sans' },
  { id: 'font-serif', name: 'Elegante', class: 'font-serif' },
  { id: 'font-mono', name: 'Código', class: 'font-mono' },
  { id: 'font-bebas', name: 'Impacto', class: 'font-bebas' },
  { id: 'font-caveat', name: 'Manuscrito', class: 'font-caveat' },
  { id: 'font-marker', name: 'Poster', class: 'font-marker' },
  { id: 'font-typewriter', name: 'Retro', class: 'font-typewriter' },
];

const TEXT_COLORS = ['#000000', '#FFFFFF', '#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#00FFFF'];

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId, onCancel }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');

  // Reel States
  const [reelUrl, setReelUrl] = useState('');
  const [reelFile, setReelFile] = useState<File | Blob | null>(null);

  const [liveTitle, setLiveTitle] = useState('');
  const [liveDescription, setLiveDescription] = useState('');
  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('5.00');
  const [showRecordReel, setShowRecordReel] = useState(false);

  // Custom Text Post States
  const [fontFamily, setFontFamily] = useState('font-sans');
  const [textColor, setTextColor] = useState('#000000');
  const [fontSize, setFontSize] = useState('24px');
  const [backgroundColor, setBackgroundColor] = useState('transparent');

  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);

  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const isEditing = !!postId;
  const isProfessional = currentUser.userType === UserType.CREATOR;

  useEffect(() => {
    const loadPostData = async () => {
      if (postId) {
        const posts = await getPosts();
        const postToEdit = posts.find(p => p.id === postId);
        if (postToEdit) {
          setPostType(postToEdit.type);
          setContent(postToEdit.content || '');
          setImageUrl(postToEdit.imageUrl || '');
          setFontFamily(postToEdit.fontFamily || 'font-sans');
          setTextColor(postToEdit.textColor || '#000000');
          setFontSize(postToEdit.fontSize || '24px');
          setBackgroundColor(postToEdit.backgroundColor || 'transparent');

          if (postToEdit.type === PostType.REEL && postToEdit.reel) {
            setReelUrl(postToEdit.reel.videoUrl);
            setContent(postToEdit.reel.description);
          }
          if (postToEdit.type === PostType.LIVE && postToEdit.liveStream) {
            setLiveTitle(postToEdit.liveStream.title);
            setLiveDescription(postToEdit.liveStream.description);
            setIsLivePaid(postToEdit.liveStream.isPaid);
            setLivePrice(postToEdit.liveStream.price?.toString() || '0');
          }
          setIsExpanded(true);
        }
      }
    };
    loadPostData();
  }, [postId]);

  const resetState = () => {
    setContent(''); setImageUrl(''); setReelUrl(''); setReelFile(null); setLiveTitle(''); setLiveDescription('');
    setIsLivePaid(false); setLivePrice('5.00'); setBackgroundColor('transparent');
    setTextColor('#000000'); setFontFamily('font-sans'); setFontSize('24px');
  };

  const handleClose = () => {
    if (onCancel) onCancel();
    else if (isEditing) onPostCreated();
    else { setIsExpanded(false); resetState(); }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploading(true);
    try {
      const url = await uploadFile(file, 'posts');
      setImageUrl(url);
    } catch (error) {
      alert('Erro ao enviar imagem.');
    } finally {
      setUploading(false);
    }
  };

  const handleVideoFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const video = document.createElement('video');
    video.preload = 'metadata';
    video.onloadedmetadata = function() {
      window.URL.revokeObjectURL(video.src);
      if (video.duration > 180) { // 3 minutos
        alert("O vídeo deve ter no máximo 3 minutos.");
        return;
      }
      setReelFile(file);
      setReelUrl(URL.createObjectURL(file)); 
    };
    video.src = URL.createObjectURL(file);
  };

  const handleReelSaved = async (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setShowRecordReel(false);
    setPostType(PostType.REEL);
    setReelFile(videoBlob);
    setReelUrl(URL.createObjectURL(videoBlob));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (uploading) return;

    setLoading(true);
    try {
      let finalReelUrl = reelUrl;

      if (postType === PostType.REEL && reelFile) {
        setUploading(true);
        try {
          finalReelUrl = await uploadFile(reelFile, 'reels');
        } catch(e) {
          alert("Erro no upload do vídeo.");
          setLoading(false);
          setUploading(false);
          return;
        }
        setUploading(false);
      }

      const existingPosts = await getPosts();
      const existingPost = isEditing ? existingPosts.find(p => p.id === postId) : undefined;

      const postData: Post = {
        id: isEditing ? postId! : generateUUID(),
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        authorProfilePic: currentUser.profilePicture,
        type: postType,
        timestamp: isEditing ? (existingPost?.timestamp || Date.now()) : Date.now(),
        content: (postType === PostType.TEXT || postType === PostType.IMAGE) ? content : undefined,
        imageUrl: postType === PostType.IMAGE ? imageUrl : undefined,
        fontFamily: postType === PostType.TEXT ? fontFamily : undefined,
        textColor: postType === PostType.TEXT ? textColor : undefined,
        fontSize: postType === PostType.TEXT ? fontSize : undefined,
        backgroundColor: postType === PostType.TEXT ? backgroundColor : undefined,
        reel: postType === PostType.REEL ? { videoUrl: finalReelUrl, description: content || 'Confira! 🚀' } : undefined,
        liveStream: postType === PostType.LIVE ? { title: liveTitle, description: liveDescription, isPaid: isLivePaid, price: isLivePaid ? parseFloat(livePrice) : 0 } : undefined,
        likes: isEditing ? (existingPost?.likes || []) : [],
        comments: isEditing ? (existingPost?.comments || []) : [],
        shares: isEditing ? (existingPost?.shares || []) : [],
        saves: isEditing ? (existingPost?.saves || []) : [],
        indicatedUserIds: isEditing ? (existingPost?.indicatedUserIds || []) : [],
      };
      if (isEditing) await updatePost(postData);
      else await addPost(postData);
      resetState();
      onPostCreated();
      if (!isEditing && !onCancel) setIsExpanded(false);
    } catch (err) { alert('Erro ao salvar.'); }
    finally { setLoading(false); }
  };

  const handleBgSelect = (bgValue: string) => {
    setBackgroundColor(bgValue);
    // Se o fundo for escuro/colorido, muda texto para branco por padrão, senão preto
    if (bgValue !== 'transparent') {
      setTextColor('#FFFFFF');
    } else {
      setTextColor('#000000');
    }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-sm p-5 md:p-6 border border-gray-100 dark:border-white/10 flex flex-col gap-5">
         <div className="flex items-start gap-4">
            <img src={currentUser.profilePicture} className="w-12 h-12 rounded-2xl object-cover shrink-0 shadow-lg" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-6 py-3.5 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 font-bold text-xs md:text-sm transition-all hover:bg-gray-100 dark:hover:bg-white/10">
              {isProfessional ? `Olá Profissional, qual o insight de hoje?` : `O que você está pensando, ${currentUser.firstName}?`}
            </button>
         </div>
         <div className="flex items-center gap-6 md:gap-10 px-2 border-t border-gray-50 dark:border-white/5 pt-4 overflow-x-auto no-scrollbar">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-3 text-gray-500 hover:text-blue-600 transition-all shrink-0 active:scale-95 group">
               <div className="p-2 bg-blue-50 dark:bg-blue-600/10 rounded-xl group-hover:bg-blue-600 group-hover:text-white transition-all"><PhotoIcon className="h-5 w-5" /></div>
               <span className="text-[10px] font-black uppercase tracking-[0.2em]">Mídia</span>
            </button>
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.REEL); }} className="flex items-center gap-3 text-gray-500 hover:text-purple-600 transition-all shrink-0 active:scale-95 group">
               <div className="p-2 bg-purple-50 dark:bg-purple-600/10 rounded-xl group-hover:bg-purple-600 group-hover:text-white transition-all"><FilmIcon className="h-5 w-5" /></div>
               <span className="text-[10px] font-black uppercase tracking-[0.2em]">Reel</span>
            </button>
            {isProfessional && (
              <button onClick={() => { setIsExpanded(true); setPostType(PostType.LIVE); }} className="flex items-center gap-3 text-gray-500 hover:text-red-600 transition-all shrink-0 active:scale-95 group">
                 <div className="p-2 bg-red-50 dark:bg-red-600/10 rounded-xl group-hover:bg-red-600 group-hover:text-white transition-all"><VideoCameraIcon className="h-5 w-5" /></div>
                 <span className="text-[10px] font-black uppercase tracking-[0.2em]">Live Pro</span>
              </button>
            )}
         </div>
      </div>
    );
  }

  return (
    <>
      <div className="bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl p-8 md:p-12 border border-blue-50 dark:border-white/5 animate-fade-in relative overflow-hidden">
        <div className="absolute top-0 left-0 w-2 h-full bg-blue-600"></div>

        <div className="flex items-center justify-between mb-10">
          <div className="flex items-center gap-5">
             <div className={`p-4 text-white rounded-[1.5rem] shadow-2xl ${postType === PostType.LIVE ? 'bg-red-600' : postType === PostType.REEL ? 'bg-purple-600' : 'bg-blue-600'}`}>
               {postType === PostType.LIVE ? <VideoCameraIcon className="h-7 w-7" /> : postType === PostType.REEL ? <FilmIcon className="h-7 w-7" /> : <BriefcaseIcon className="h-7 w-7" />}
             </div>
             <div>
                <h3 className="font-black text-gray-900 dark:text-white uppercase text-[11px] tracking-[0.3em]">{isEditing ? 'Editar Post' : 'Novo Conteúdo'}</h3>
                <p className="text-[9px] text-blue-500 font-black uppercase mt-1 tracking-widest flex items-center gap-2">CyBer Studio Pro <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></span></p>
             </div>
          </div>
          <button onClick={handleClose} className="p-3 bg-gray-50 dark:bg-white/5 text-gray-300 hover:text-red-500 hover:bg-red-50 transition-all rounded-2xl active:scale-90">
            <XMarkIcon className="h-7 w-7" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="flex flex-wrap gap-3 p-2 bg-gray-50 dark:bg-white/5 rounded-[2rem] w-fit">
             {[
               { id: PostType.TEXT, icon: DocumentTextIcon, label: 'Texto', locked: false },
               { id: PostType.IMAGE, icon: PhotoIcon, label: 'Mídia', locked: false },
               { id: PostType.REEL, icon: FilmIcon, label: 'Reel', locked: false },
               { id: PostType.LIVE, icon: VideoCameraIcon, label: 'Live Pro', locked: !isProfessional }
             ].map(t => (
               <button key={t.id} type="button" disabled={t.locked} onClick={() => { setPostType(t.id); }} className={`flex items-center gap-3 px-6 py-3 rounded-[1.5rem] text-[10px] font-black uppercase tracking-[0.15em] transition-all active:scale-95 ${postType === t.id ? 'bg-white dark:bg-white/10 text-blue-600 dark:text-white shadow-xl' : 'text-gray-400'} ${t.locked ? 'opacity-20 grayscale' : ''}`}>
                  {t.locked ? <LockClosedIcon className="h-4 w-4" /> : <t.icon className="h-4 w-4" />} {t.label}
               </button>
             ))}
          </div>

          {postType === PostType.TEXT && (
            <div className="space-y-6">
               <div className="flex flex-col gap-4">
                  {/* Visual Editor Area */}
                  <textarea 
                    value={content} 
                    onChange={(e) => setContent(e.target.value)} 
                    className={`w-full p-12 border-4 border-transparent focus:border-white/20 rounded-[3.5rem] outline-none transition-all duration-500 shadow-2xl resize-none flex items-center justify-center text-center ${fontFamily}`} 
                    style={{ 
                      color: textColor, 
                      fontSize: fontSize, 
                      background: backgroundColor, 
                      minHeight: '400px', 
                      display: backgroundColor !== 'transparent' ? 'flex' : 'block',
                      fontFamily: fontFamily.replace('font-', '')
                    }} 
                    placeholder="O que deseja partilhar?" 
                    required 
                  />

                  {/* Controls */}
                  <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-[2rem] space-y-4">
                     <div className="flex items-center gap-4 overflow-x-auto no-scrollbar pb-2">
                        <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest shrink-0 flex items-center gap-1"><SwatchIcon className="h-3 w-3"/> Fundo:</span>
                        {BACKGROUND_OPTIONS.map(bg => (
                           <button 
                             key={bg.id}
                             type="button"
                             onClick={() => handleBgSelect(bg.value)}
                             className={`w-8 h-8 rounded-full border-2 transition-all ${backgroundColor === bg.value ? 'scale-125 border-blue-600 shadow-lg' : 'border-transparent hover:scale-110'}`}
                             style={{ background: bg.value, border: bg.value === 'transparent' ? '2px solid #ddd' : undefined }}
                             title={bg.label}
                           >
                             {bg.value === 'transparent' && <span className="text-[8px] text-gray-400 block -rotate-45">/</span>}
                           </button>
                        ))}
                     </div>

                     <div className="flex flex-col md:flex-row gap-4">
                        <div className="flex-1 flex items-center gap-4 overflow-x-auto no-scrollbar pb-2">
                           <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest shrink-0 flex items-center gap-1"><LanguageIcon className="h-3 w-3"/> Fonte:</span>
                           {FONT_OPTIONS.map(font => (
                              <button
                                key={font.id}
                                type="button"
                                onClick={() => setFontFamily(font.class)}
                                className={`px-3 py-1.5 rounded-lg text-xs border transition-all whitespace-nowrap ${fontFamily === font.class ? 'bg-black text-white border-black dark:bg-white dark:text-black' : 'bg-white dark:bg-white/5 text-gray-500 border-gray-200 dark:border-white/10'}`}
                              >
                                 {font.name}
                              </button>
                           ))}
                        </div>

                        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar pb-2">
                           {TEXT_COLORS.map(color => (
                              <button
                                key={color}
                                type="button"
                                onClick={() => setTextColor(color)}
                                className={`w-6 h-6 rounded-full border border-gray-200 shadow-sm transition-transform ${textColor === color ? 'scale-125 ring-2 ring-offset-2 ring-blue-500' : ''}`}
                                style={{ backgroundColor: color }}
                              />
                           ))}
                        </div>
                     </div>
                  </div>
               </div>
            </div>
          )}

          {postType === PostType.LIVE && (
            <div className="space-y-8 animate-fade-in">
              <input type="text" value={liveTitle} onChange={(e) => setLiveTitle(e.target.value)} className="w-full p-8 bg-gray-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-[2rem] outline-none font-black text-2xl dark:text-white transition-all shadow-inner" placeholder="Título da Aula..." required />
              <textarea value={liveDescription} onChange={(e) => setLiveDescription(e.target.value)} className="w-full p-8 bg-gray-50 dark:bg-white/5 border-2 border-transparent focus:border-red-500 rounded-[2rem] outline-none font-medium text-lg dark:text-white h-40 resize-none transition-all shadow-inner" placeholder="Sobre o que será essa live profissional?" />

              <div className="p-6 bg-red-50 dark:bg-red-900/10 rounded-[2rem] border border-red-100 dark:border-red-500/20">
                 <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                       <BanknotesIcon className="h-6 w-6 text-red-600" />
                       <div>
                          <h4 className="font-black text-red-900 dark:text-white text-xs uppercase tracking-widest">Monetização</h4>
                          <p className="text-[9px] text-red-400 font-bold uppercase">Defina o valor de acesso</p>
                       </div>
                    </div>
                    <label className="relative inline-flex items-center cursor-pointer">
                      <input type="checkbox" checked={isLivePaid} onChange={() => setIsLivePaid(!isLivePaid)} className="sr-only peer" />
                      <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer dark:bg-gray-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-red-600"></div>
                    </label>
                 </div>

                 {isLivePaid && (
                    <div className="flex items-center gap-4 animate-fade-in">
                       <span className="text-red-600 font-black text-2xl">$</span>
                       <input 
                         type="number" 
                         value={livePrice} 
                         onChange={e => setLivePrice(e.target.value)} 
                         className="flex-1 bg-white dark:bg-white/5 p-4 rounded-xl font-black text-xl outline-none border-2 border-transparent focus:border-red-500 transition-all"
                         step="0.01"
                         min="1"
                       />
                    </div>
                 )}
              </div>
            </div>
          )} 

          {postType === PostType.IMAGE && (
             <div className="space-y-6">
                <textarea value={content} onChange={(e) => setContent(e.target.value)} className="w-full p-6 bg-gray-50 dark:bg-white/5 rounded-[2rem] outline-none font-medium resize-none h-32" placeholder="Legenda da imagem..." />

                <div 
                  onClick={() => imageInputRef.current?.click()}
                  className={`w-full h-64 border-4 border-dashed rounded-[3rem] flex flex-col items-center justify-center gap-4 cursor-pointer transition-all ${imageUrl ? 'border-blue-500' : 'border-gray-200 dark:border-white/10 hover:border-blue-400'}`}
                >
                   {uploading ? (
                      <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent animate-spin rounded-full"></div>
                   ) : imageUrl ? (
                      <img src={imageUrl} className="w-full h-full object-cover rounded-[2.5rem]" />
                   ) : (
                      <>
                         <PhotoIcon className="h-12 w-12 text-gray-300" />
                         <span className="font-black text-xs text-gray-400 uppercase tracking-widest">Carregar Imagem</span>
                      </>
                   )}
                   <input type="file" ref={imageInputRef} onChange={handleImageUpload} accept="image/*" className="hidden" />
                </div>
             </div>
          )}

          {postType === PostType.REEL && (
             <div className="space-y-6 animate-fade-in">
                {reelUrl ? (
                   <div className="relative w-full h-64 bg-black rounded-[2rem] overflow-hidden group">
                      <video src={reelUrl} className="w-full h-full object-cover" controls />
                      <button type="button" onClick={() => { setReelUrl(''); setReelFile(null); }} className="absolute top-4 right-4 bg-white text-black p-2 rounded-full shadow-lg text-xs font-bold hover:bg-red-50 hover:text-red-500 transition-colors">
                        <TrashIcon className="h-4 w-4" />
                      </button>
                   </div>
                ) : (
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div onClick={() => setShowRecordReel(true)} className="h-48 bg-purple-50 dark:bg-purple-900/10 rounded-[2rem] flex flex-col items-center justify-center cursor-pointer border-2 border-dashed border-purple-200 dark:border-purple-500/20 hover:border-purple-500 transition-all group">
                         <div className="bg-purple-600 p-4 rounded-full mb-3 group-hover:scale-110 transition-transform shadow-lg">
                            <VideoCameraIcon className="h-8 w-8 text-white" />
                         </div>
                         <span className="font-black text-xs text-purple-600 uppercase tracking-widest">Gravar Câmera</span>
                         <span className="text-[9px] text-purple-400 mt-1 font-bold">Máx 3 minutos</span>
                      </div>

                      <div onClick={() => videoInputRef.current?.click()} className="h-48 bg-blue-50 dark:bg-blue-900/10 rounded-[2rem] flex flex-col items-center justify-center cursor-pointer border-2 border-dashed border-blue-200 dark:border-blue-500/20 hover:border-blue-500 transition-all group">
                         <div className="bg-blue-600 p-4 rounded-full mb-3 group-hover:scale-110 transition-transform shadow-lg">
                            <ArrowUpTrayIcon className="h-8 w-8 text-white" />
                         </div>
                         <span className="font-black text-xs text-blue-600 uppercase tracking-widest">Upload Vídeo</span>
                         <span className="text-[9px] text-blue-400 mt-1 font-bold">Máx 3 minutos</span>
                         <input type="file" ref={videoInputRef} onChange={handleVideoFileSelect} accept="video/*" className="hidden" />
                      </div>
                   </div>
                )}
                <textarea value={content} onChange={(e) => setContent(e.target.value)} className="w-full p-6 bg-gray-50 dark:bg-white/5 rounded-[2rem] outline-none font-medium resize-none h-24" placeholder="Descrição do Reel..." />
             </div>
          )}

          <div className="flex justify-end pt-10 border-t border-gray-50 dark:border-white/5">
             <button type="submit" disabled={loading || uploading} className="bg-gradient-to-r from-blue-600 to-indigo-700 text-white px-16 py-6 rounded-[2.5rem] font-black text-sm uppercase shadow-xl transition-all flex items-center gap-4 disabled:opacity-30 active:scale-95">
                {loading ? 'Processando...' : uploading ? 'Enviando...' : isEditing ? 'Atualizar' : 'Publicar'} 
                <ChevronRightIcon className="h-6 w-6" />
             </button>
          </div>
        </form>
      </div>

      {showRecordReel && (
        <RecordReelModal 
          onClose={() => { setShowRecordReel(false); if(!reelUrl) setPostType(PostType.TEXT); }} 
          onSave={handleReelSaved} 
        />
      )}
    </>
  );
};

