import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostShares, 
  updatePostSaves, 
  deletePost, 
  pinPost,
  unpinPost,
  updateUserBalance,
  createReport
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  TrashIcon, 
  CheckBadgeIcon,
  FlagIcon,
  MapPinIcon as PinIconOutline,
  VideoCameraIcon,
  SignalIcon,
  ShareIcon,
  RocketLaunchIcon,
  PencilSquareIcon,
  UserPlusIcon,
  LockClosedIcon,
  LockOpenIcon,
  CurrencyDollarIcon,
  FilmIcon,
  PlayIcon,
  SpeakerXMarkIcon
} from '@heroicons/react/24/outline';
