export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
  const { data: currentUser } = await supabase.from('profiles').select('followed_users').eq('id', currentUserId).single();
  const { data: targetUser } = await supabase.from('profiles').select('followers').eq('id', userIdToFollow).single();

  if (!currentUser || !targetUser) return;

  let newFollowed = currentUser.followed_users || [];
  let newFollowers = targetUser.followers || [];

  if (newFollowed.includes(userIdToFollow)) {
    newFollowed = newFollowed.filter((id: string) => id !== userIdToFollow);
    newFollowers = newFollowers.filter((id: string) => id !== currentUserId);
  } else {
    newFollowed.push(userIdToFollow);
    newFollowers.push(currentUserId);
    createNotification({
        type: NotificationType.NEW_FOLLOWER,
        recipientId: userIdToFollow,
        actorId: currentUserId,
        timestamp: Date.now()
    });
  }

  await supabase.from('profiles').update({ followed_users: newFollowed }).eq('id', currentUserId);
  await supabase.from('profiles').update({ followers: newFollowers }).eq('id', userIdToFollow);
};

