                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Data de Nascimento</label>
                    <div className="relative">
                       <CalendarDaysIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                       <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className="w-full p-4 pl-12 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-blue-500 font-bold" />
                    </div>
                 </div>

                 {currentUser.userType === UserType.CREATOR && (
