              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Endereço de E-mail</label>
                    <div className="relative">
                       <EnvelopeIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-blue-500' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={email} 
                        onChange={e => setEmail(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-blue-500' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Telefone</label>
                    <div className="relative">
                       <PhoneIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-blue-500' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={phone} 
                        onChange={e => setPhone(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-blue-500' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>

                 {currentUser.userType === UserType.CREATOR && (
                    <div className="space-y-2 md:col-span-2">
                       <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Documento de Habilitação (PDF)</label>
                       <div className={`w-full p-4 rounded-2xl font-bold border flex items-center gap-3 ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`}>
                          <ShieldCheckIcon className="h-5 w-5" />
                          <span className="text-xs">
                             {currentUser.isAdmin ? 'Como Admin, você pode revalidar documentos.' : 'Arquivo Verificado pelo Admin'}
                          </span>
                       </div>
                    </div>
                 )}
              </div>
           </div>

           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border border-red-50 dark:border-red-900/10">
              <p className="text-[10px] font-black text-red-500 uppercase tracking-widest mb-6 ml-1 flex items-center gap-2"><KeyIcon className="h-4 w-4"/> Segurança e Acesso</p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Nova Senha</label>
                    <input type="password" value={newPassword} onChange={e => setNewPassword(e.target.value)} placeholder="Mínimo 6 caracteres" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-red-500 font-bold" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Confirmar Senha</label>
                    <input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} placeholder="Repita a senha" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-red-500 font-bold" />
